def sm_ord(k):
    if 11 <= k % 100 <= 13:
        return f"{k}th"
    return f"{k}" + {1: "st", 2: "nd", 3: "rd"}.get(k % 10, "th")


def sm_cap(t):
    return t[0].upper() + t[1:]


def sm_camp(line, c):
    """N and the group sizes from "A camp has 240 settlers: 160 farmers and 80 guards."."""
    mt = re.fullmatch(rf"A {c[1]} has (\d+) {c[0]}: (.+)\.", line)
    need(mt is not None, f"can't read {line!r}")
    G = []
    for i, part in enumerate(re.split(r", | and (?=\d)", mt.group(2))):
        m2 = re.fullmatch(rf"(\d+) {c[2][i]}", part)
        need(m2 is not None, f"can't read the group {part!r}")
        G.append(int(m2.group(1)))
    need(sum(G) == int(mt.group(1)), "the groups don't add to the population")
    need(len(set(G)) == len(G), "two groups are the same size")
    return int(mt.group(1)), G


def sm_table(q, c, cols):
    """Columns of the groups table as ints, with the Total row checked."""
    rows = q["table"]["rows"]
    need(rows[0][0] == "group" and len(rows[0][1]) == cols, "table heads")
    need([r[0] for r in rows[1:-1]] == list(c[2][:len(rows) - 2]) and rows[-1][0] == "Total", "table groups")
    out = [[int(r[1][j]) for r in rows[1:-1]] for j in range(cols)]
    for j in range(cols):
        need(sum(out[j]) == int(rows[-1][1][j]), "a column doesn't add to its total")
    return out


def sm_scale(q, N, G, n=None):
    """The interval for a sample of n, with each group whole at that scale."""
    need(n is not None and n > 0 and N % n == 0, f"{N} is not a whole number of samples of {n}")
    k = N // n
    p1 = q["paper"] == 1
    need(k != n, "the interval is the sample size")
    need((4 if p1 else 6) <= k <= (20 if p1 else 40) and (10 if p1 else 40) <= n <= (40 if p1 else 150), f"n = {n}, k = {k} is outside the limits")
    for g in G:
        need(g % k == 0, f"the group of {g} isn't a whole multiple of {k}")
    return k


def sm_technique(line, c, G):
    """The checklist on a surveyor's method: (technique, sample size, interval)."""
    every = re.search(r"every (\d+)(?:st|nd|rd|th) name", line)
    random = "at random" in line or "random start" in line
    filled = re.search(rf"(\d+) {c[2][0]} and (\d+) {c[2][1]}", line)
    if every:
        k = int(every.group(1))
        need(random and f"among the first {k} names" in line and every.group(0) == f"every {sm_ord(k)} name", f"can't read the interval in {line!r}")
        return "systematic", sum(G) // k
    if filled:
        a, b = int(filled.group(1)), int(filled.group(2))
        need(a * G[1] == b * G[0], f"the groups in {line!r} are not in proportion")
        return ("stratified" if random else "quota"), a + b
    n = int(re.search(r"\b(\d+)\b", line).group(1))
    return ("simple" if random else "convenience"), n


def sm_size(line, N):
    mt = re.fullmatch(r"The surveyor wants a sample of (\d+)(%?) of them\.", line)
    need(mt is not None, f"can't read {line!r}")
    v = int(mt.group(1))
    if mt.group(2):
        need(N * v % 100 == 0, "the percentage isn't a whole number of people")
        return N * v // 100
    return v


def sm_arith(q):
    """The working's sums, wherever a step writes one."""
    for sol in q["solutions"]:
        for st in sol["steps"]:
            for a, b, r in re.findall(r"(\d+) ÷ (\d+) = (\d+)", st):
                need(int(a) == int(b) * int(r), f"{st!r}")
            for a, b, r in re.findall(r"(\d+) − (\d+) = (\d+)", st):
                need(int(a) - int(b) == int(r), f"{st!r}")


def check_sampling(q):
    g, u, L, rep, asked = q["given"], q["view"]["unknown"], q["lines"], q["view"]["rep"], q["asked"]
    c = SM_CTX[int(g["ctx"])]
    who, place, names, spot, lst, topic = c
    a, b = names[0], names[1]
    wrongs, want = {}, None
    if u in ("name-technique", "technique-disadvantage", "is-it-random"):
        N, G = sm_camp(L[0], c)
        tech, n = sm_technique(L[1], c, G)
        k = sm_scale(q, N, G, n)
        if u == "name-technique":
            need(asked == "Which sampling technique is this?", f"asked {asked!r}")
            want = SM_NAMES[tech]
            wrongs = {"quota": {SM_T + "0": {SM_NAMES["stratified"]}}, "stratified": {SM_T + "0": {SM_NAMES["quota"]}},
                      "systematic": {SM_T + "1": {SM_NAMES["simple"]}}, "convenience": {SM_T + "2": {SM_NAMES["simple"]}}, "simple": {SM_T + "1": {SM_NAMES["systematic"]}}}[tech]
            need(all(o["text"] in SM_NAMES.values() for o in q["choices"]), "an option is not a technique")
        elif u == "technique-disadvantage":
            want = SM_MAIN[tech].format(place)
            for o in q["choices"]:
                key = next((f for f in SM_FLAWS if f.format(place) == o["text"]), None)
                need(key is not None, f"{o['text']!r} is not a known flaw")
                need(o["correct"] or tech not in SM_FLAWS[key], f"{o['text']!r} is true of {tech}, so it is no wrong option")
        else:
            need(asked == "Is this a simple random sample?", f"asked {asked!r}")
            if tech == "systematic":
                want = "No: only the start is random, and the interval fixes every pick after it."
                wrongs = {SM_T + "1": {"Yes: the start is random, so the whole sample is random.", f"Yes: every {sm_ord(k)} name is as good as any other."}}
            elif tech == "convenience":
                want = "No: anyone who doesn't come by has no chance of being chosen."
                wrongs = {SM_T + "2": {"Yes: whoever comes by is a random person.", "Yes: the surveyor didn't choose who came by."}}
            else:
                need(tech == "simple", f"{tech} isn't asked here")
                want = f"Yes: every set of {n} people has the same chance."
                wrongs = {SM_T + "1": {"No: only the start is random."}}
    elif u == "best-technique":
        text = " ".join(L)
        if "There is no list. " in text:
            mt = re.fullmatch(rf"The (\d+) {who} come by {spot} one at a time during a shift\.", L[0])
            need(mt is not None, f"can't read {L[0]!r}")
            need("spread evenly along the line, from a random start" in L[1], f"{L[1]!r}")
            want, wrongs = SM_NAMES["systematic"], {SM_T + "1": {SM_NAMES["simple"]}}
        elif "There is no list," in text:
            sm_camp(L[0], c)
            need(f"can only reach people {spot}" in L[1], f"{L[1]!r}")
            want, wrongs = SM_NAMES["quota"], {SM_T + "0": {SM_NAMES["stratified"]}}
        elif "must have an equal chance" in text:
            sm_camp(L[0], c)
            want, wrongs = SM_NAMES["stratified"], {SM_T + "0": {SM_NAMES["quota"]}}
        else:
            need("The groups don't matter here" in text, f"{text!r}")
            want = SM_NAMES["simple"]
            wrongs = {SM_T + "1": {SM_NAMES["systematic"]}, SM_T + "2": {SM_NAMES["convenience"]}}
    elif u == "describe-systematic":
        N, G = sm_camp(L[0], c)
        n = sm_size(L[1], N)
        k = sm_scale(q, N, G, n)
        want = f"Go down {lst}, pick a random start among the first {k} names, then take every {sm_ord(k)} name."
        wrongs = {SM_T + "1": {f"Draw {n} names at random from {lst}."},
                  SM_S + "5": {f"Go down {lst}, pick a random start among the first {n} names, then take every {sm_ord(n)} name."}}
    elif u == "systematic-interval":
        mt = re.fullmatch(rf"{re.escape(sm_cap(lst))} lists (\d+) {who}\.", L[0])
        need(mt is not None, f"can't read {L[0]!r}")
        N = int(mt.group(1))
        n = sm_size(L[1], N)
        k = sm_scale(q, N, [], n)
        want = f"interval = {k}"
        wrongs = {SM_S + "5": {f"interval = {n}"}}
    elif u == "systematic-member":
        mt = re.fullmatch(rf"{re.escape(sm_cap(lst))} numbers (\d+) {who} from 1 to (\d+)\.", L[0])
        m2 = re.fullmatch(r"A systematic sample starts at number (\d+) and takes every (\d+)(?:st|nd|rd|th) name\.", L[1])
        m3 = re.fullmatch(r"Find the number of the (\d+)(?:st|nd|rd|th) person chosen\.", asked)
        need(mt and m2 and m3 and mt.group(1) == mt.group(2), "can't read the sample")
        N, start, k, j = int(mt.group(1)), int(m2.group(1)), int(m2.group(2)), int(m3.group(1))
        v = start + (j - 1) * k
        need(1 <= start <= k and v <= N, "the pick is off the list")
        want = f"number {v}"
        wrongs = {SM_S + "6": {f"number {start + j * k}"}, SM_S + "7": {f"number {j * k}"}}
    elif u == "quota-number":
        mt = re.search(r"A (quota|stratified) sample of (\d+) must match", L[1])
        need(mt is not None, f"can't read {L[1]!r}")
        n = int(mt.group(2))
        if rep == "table":
            m2 = re.fullmatch(rf"The table shows the (\d+) {who} in a {place}\.", L[0])
            need(m2 is not None, f"can't read {L[0]!r}")
            G = sm_table(q, c, 1)[0]
            N = int(m2.group(1))
            need(N == sum(G), "the table's total isn't the population")
        else:
            N, G = sm_camp(L[0], c)
        sm_scale(q, N, G, n)
        m3 = re.fullmatch(r"Find how many (.+) go in the sample\.", asked)
        i = names.index(m3.group(1))
        v = sp.Rational(G[i] * n, N)
        need(v.q == 1, "the number isn't whole")
        want = f"number = {v}"
        if n % 3 == 0 and len(G) == 3:
            wrongs = {SM_S + "8": {f"number = {n // 3}"}}
    elif u in ("fair-share", "under-represented"):
        if rep == "table":
            mt = re.fullmatch(rf"The table shows a {place} of (\d+) {who} and a sample of (\d+) of them\.", L[0])
            need(mt is not None, f"can't read {L[0]!r}")
            N, n = int(mt.group(1)), int(mt.group(2))
            G, got = sm_table(q, c, 2)
            need(sum(G) == N and sum(got) == n, "totals")
        else:
            N, G = sm_camp(L[0], c)
            mt = re.fullmatch(rf"A sample of (\d+) holds (\d+) {names[0]}, (\d+) {names[1]} and (\d+) {names[2]}\.", L[1])
            need(mt is not None, f"can't read {L[1]!r}")
            n, got = int(mt.group(1)), [int(mt.group(i)) for i in (2, 3, 4)]
            need(sum(got) == n, "the sample doesn't add up")
        sm_scale(q, N, G, n)
        fair = [sp.Rational(x * n, N) for x in G]
        need(all(f.q == 1 for f in fair), "a fair share isn't whole")
        if u == "fair-share":
            m3 = re.fullmatch(rf"By how many does the number of (.+) fall short of the mix of the {place}\?", asked)
            i = names.index(m3.group(1))
            need(got[i] < fair[i] and got[i] > 0, "the group doesn't fall short")
            want = f"number = {fair[i] - got[i]}"
            wrongs = {SM_S + "9": {f"number = {fair[i]}"}, SM_S + "10": {f"number = {G[i] - got[i]}"}}
        else:
            ratio = [sp.Rational(x, f) for x, f in zip(got, fair)]
            short = [f - x for x, f in zip(got, fair)]
            i = ratio.index(min(ratio))
            need(short[i] == max(short) and short.count(short[i]) == 1 and sorted(ratio)[1] > ratio[i], "no one group is clearly the most under-represented")
            need(got[i] != min(got), "the smallest count gives the answer away")
            want = sm_cap(names[i])
            wrongs = {SM_B + "1": {f"None: the sample matches the {place}."},
                      SM_S + "11": {sm_cap(names[j]) for j in range(len(got)) if got[j] == min(got)}}
    elif u in ("why-biased", "better-method"):
        N, G = sm_camp(L[0], c)
        mt = re.fullmatch(rf"To learn {topic} across the whole {place}, a surveyor draws (\d+) {a} at random and asks only them\.", L[1])
        need(mt is not None, f"can't read {L[1]!r}")
        n = int(mt.group(1))
        if u == "why-biased":
            want = f"Only {a} were asked, so the {b} had no chance of being chosen."
            wrongs = {SM_B + "0": {f"The sample is too small: with more {a} it would have no bias."},
                      SM_B + "1": {f"Nothing: a random draw always represents the whole {place}."}}
        else:
            want = f"Stratified sampling: draw at random from both the {a} and the {b}, in proportion to their numbers."
            wrongs = {SM_B + "0": {f"Keep to the {a}, and ask {2 * n} of them instead."},
                      SM_B + "1": {f"Change nothing: a random draw from the {a} is enough."},
                      SM_T + "2": {f"Ask the first {n} {who} who come by {spot}."}}
    elif u == "bias-direction":
        mt = re.fullmatch(r"She asks (\d+) of them, all (.+)\.", L[1])
        need(mt is not None and mt.group(2) in SM_LEAN, f"can't read {L[1]!r}")
        n, want = int(mt.group(1)), SM_LEAN[mt.group(2)]
        wrongs = {SM_B + "0": {f"Neither: asking {n} people cancels out any bias."}, SM_B + "1": {"Neither: a sample is always a fair picture of everyone."}}
    elif u == "bigger-sample":
        N, G = sm_camp(L[0], c)
        mt = re.fullmatch(rf"A surveyor asks (\d+) {a} about {topic}, and none of the {b}\.", L[1])
        need(mt is not None and L[2] == f"She plans to ask {3 * int(mt.group(1))} {a} instead.", f"can't read {L[1:]!r}")
        want = f"No: the result gets steadier, but the {b} are still left out."
        wrongs = {SM_B + "0": {"Yes: a larger sample removes bias.", f"Yes: with {3 * int(mt.group(1))} people everyone has had a chance."}}
    elif u == "random-not-perfect":
        if rep == "table":
            mt = re.fullmatch(rf"The table shows a {place} of (\d+) {who} and a simple random sample of (\d+) of them\.", L[0])
            need(mt is not None, f"can't read {L[0]!r}")
            N, n = int(mt.group(1)), int(mt.group(2))
            G, got = sm_table(q, c, 2)
        else:
            N, G = sm_camp(L[0], c)
            mt = re.fullmatch(rf"A simple random sample of (\d+) holds (\d+) {a} and (\d+) {b}\.", L[1])
            need(mt is not None, f"can't read {L[1]!r}")
            n, got = int(mt.group(1)), [int(mt.group(2)), int(mt.group(3))]
        need(sum(got) == n, "the sample doesn't add up")
        sm_scale(q, N, G, n)
        need(all(abs(sp.Rational(x * n, N) - y) >= 2 for x, y in zip(G, got)), "the sample doesn't miss the mix")
        want = "The draw can be fair and still miss the mix: chance alone moves a sample."
        wrongs = {SM_B + "1": {f"The draw can't have been random: a random sample always matches the {place}.", f"The {place}'s numbers must be wrong: a sample shows the true mix."},
                  SM_S + "12": {f"The method is biased against the {x}." for x in names[:len(G)]}}
    elif u == "improve-reliability":
        mt = re.fullmatch(rf"A surveyor wants to learn {topic}, so she draws (\d+) of all the {who} at random\.", L[0])
        need(mt is not None and 5 <= int(mt.group(1)) <= 12, f"can't read {L[0]!r}")
        want = "Take a larger random sample, so that one person counts for less."
        wrongs = {SM_B + "1": {f"Keep the {mt.group(1)}: a random sample is always exact."}}
    elif u == "source-reliability":
        mt = re.fullmatch(r"The figure comes from (.+)\.", L[1])
        key = next((k for k in SM_WHY if k in mt.group(1)), None)
        need(key is not None, f"can't read {L[1]!r}")
        want = SM_WHY[key]
        wrongs = {SM_B + "0": {f"It is reliable: {re.search(r'[0-9]+', L[1]).group()} is enough to remove any bias."}}
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs)
    sm_arith(q)
    for sol in q["solutions"]:
        need(want in sol["steps"][-1], f"{sol['name']}: the last step {sol['steps'][-1]!r} doesn't state {want!r}")
    return None, None


# ── cumulative-frequency (t4-cumulative-frequency, FAL-726) ──
# The `cumulative-frequency` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/cumulative_frequency.gd. A curve's readings come from the drawn curve in
# the question's figure, a table's from its written rows, never from the situation. Every reading
# must be a corner of the grid, so Paper 1 has one right value.

CF_Q = "SL4.2.cumfreq-quartiles#"
CF_C = "SL4.2.cumfreq-count#"
CF_B = "SL4.2.cumfreq-build#"
CF_T = "t4-cumulative-frequency#"  # its own slips (FAL-820)
CF_SQUARES = 20
# (who, what the curve shows, the axis, the noun, letter, unit, more than, at most, square across, limit)
CF_CTX = [("scavengers", "the hours worked last week by {} scavengers", "hours worked", "hours worked", "h", "hours", "worked more than {} hours", "worked at most {} hours", 2, None),
          ("wells", "the depth of {} wells", "depth (m)", "depth", "d", "m", "are deeper than {} m", "are at most {} m deep", 1, None),
          ("crates", "the mass of {} salvage crates", "mass (kg)", "mass", "m", "kg", "are heavier than {} kg", "are at most {} kg", 5, None),
          ("drones", "the flight time of {} drones", "flight time (minutes)", "flight time", "t", "minutes", "flew for more than {} minutes", "flew for at most {} minutes", 10, None),
          ("patrols", "the distance walked by {} patrols", "distance (km)", "distance", "d", "km", "walked more than {} km", "walked at most {} km", 2, None),
          ("traders", "the takings of {} traders last week", "takings (caps)", "takings", "c", "caps", "took more than {} caps", "took at most {} caps", 20, None),
          ("bean plants", "the height of {} bean plants", "height (cm)", "height", "h", "cm", "are taller than {} cm", "are at most {} cm tall", 5, None),
          ("tanks", "the water held in {} tanks", "water (litres)", "water held", "w", "litres", "hold more than {} litres", "hold at most {} litres", 10, "Each tank holds at most {} litres."),
          ("trucks", "the load carried by {} trucks", "load (kg)", "load", "l", "kg", "carry more than {} kg", "carry at most {} kg", 20, "Each truck can carry at most {} kg.")]


def cf_curve(q, c):
    """(n, dx, dy, points): the figure, held to the grid its scale line describes."""
    who, of, axis, noun, sym, unit, more, most, dx0, _ = c
    gr = q["graph"]
    need(gr is not None and gr["kind"] == "cumfreq", "no cumulative frequency curve")
    mt = re.fullmatch(re.escape("The curve shows " + of).replace(r"\{\}", r"(\d+)") + r"\.", q["lines"][0])
    need(mt is not None, f"can't read {q['lines'][0]!r}")
    n = int(mt.group(1))
    m2 = re.fullmatch(rf"Each small square is (\d+) {unit} across and (\d+) {who} up\.", q["lines"][1])
    need(m2 is not None, f"can't read {q['lines'][1]!r}")
    dx, dy = int(m2.group(1)), int(m2.group(2))
    need(dx == dx0 and n % CF_SQUARES == 0 and dy * CF_SQUARES == n and 40 <= n <= 240, f"n = {n}, dy = {dy}")
    need(gr["dx"] == dx and gr["dy"] == dy and gr["y1"] == n and gr["x1"] == CF_SQUARES * dx, "the grid isn't the one the line describes")
    need(gr["x_name"] == axis and gr["y_name"] == "cumulative frequency", "the axes aren't labelled")
    pts = [(sp.Rational(str(a)), sp.Rational(str(b))) for a, b in gr["curve"]]
    need(pts[0][1] == 0 and pts[-1][1] == n, "the curve doesn't run from 0 to n")
    for (a, b), (e, f) in zip(pts, pts[1:]):
        need(e > a and f > b, "the curve isn't strictly rising")
    return n, dx, dy, pts


def cf_read_x(pts, y, dx, dy):
    """The value at height y: a point of the curve on a corner of the grid."""
    hit = [a for a, b in pts if b == y]
    need(len(hit) == 1, f"the curve has no point at height {y}")
    need(hit[0] % dx == 0 and sp.Rational(y) % dy == 0, f"({hit[0]}, {y}) is not on a corner of the grid")
    return hit[0]


def cf_read_y(pts, x, dx, dy):
    """The height at value x: a point of the curve on a corner of the grid."""
    hit = [b for a, b in pts if a == x]
    need(len(hit) == 1, f"the curve has no point at {x}")
    need(sp.Rational(x) % dx == 0 and hit[0] % dy == 0, f"({x}, {hit[0]}) is not on a corner of the grid")
    return hit[0]


def cf_val(v, c):
    return f"{dec_text(sp.Rational(v))} {c[5]}"


def cf_classes(rows, c, cum_col=None, freq_col=0):
    """Boundaries and the frequencies from a table's written rows; None for a hidden frequency."""
    bs, fs = [], []
    for row in rows[1:]:
        mt = re.fullmatch(rf"(\d+) < {c[4]} ≤ (\d+)", row[0])
        need(mt is not None, f"can't read the class {row[0]!r}")
        a, b = int(mt.group(1)), int(mt.group(2))
        need(not bs or bs[-1] == a, "the classes don't join up")
        bs += [a] if not bs else []
        bs.append(b)
        fs.append(row[1][freq_col])
    w = {bs[i + 1] - bs[i] for i in range(len(bs) - 1)}
    return bs, fs, w


def cf_running(fs):
    out, total = [], 0
    for f in fs:
        total += f
        out.append(total)
    return out


def cf_table(q, c):
    """(n, boundaries, frequencies, running totals) from a table with both columns shown."""
    rows = q["table"]["rows"]
    need(rows[0][1] == ["frequency", "cumulative"], "table heads")
    bs, fs, w = cf_classes(rows, c)
    need(len(w) == 1, "the classes aren't equal")
    fs = [int(f) for f in fs]
    run = cf_running(fs)
    need([r[1][1] for r in rows[1:]] == [str(x) for x in run], "the cumulative column isn't the running total")
    mt = re.fullmatch(re.escape("The table shows " + c[1]).replace(r"\{\}", r"(\d+)") + r"\.", q["lines"][0])
    need(mt is not None and int(mt.group(1)) == run[-1], "the table's total isn't n")
    return run[-1], bs, fs, run


def cf_interp(bs, fs, run, t):
    for j, r in enumerate(run):
        if t <= r:
            before = r - fs[j]
            return bs[j] + sp.Rational((t - before) * (bs[j + 1] - bs[j]), fs[j])
    raise Fail(f"{t} is above the table")


def cf_count(bs, fs, run, v):
    for j in range(len(fs)):
        if v <= bs[j + 1]:
            return run[j] - fs[j] + sp.Rational(fs[j] * (v - bs[j]), bs[j + 1] - bs[j])
    raise Fail(f"{v} is above the table")


def cf_clean(v):
    need((v * 10).q == 1, f"the estimate {v} has more than one decimal")
    return v


def cf_arith(q):
    """Every sum the working writes, worked again."""
    num = r"\d+(?:\.\d+)?"
    for sol in q["solutions"]:
        for st in sol["steps"]:
            for a, b, c, d, e, r in re.findall(rf"({num}) \+ \(({num}) − ({num})\) ÷ ({num}) × ({num}) = ({num})", st):
                need(R(a) + (R(b) - R(c)) / R(d) * R(e) == R(r), f"{st!r}")
            for a, b, r in re.findall(rf"(?<![÷×(] )\b({num}) − ({num}) = ({num})", st):
                need(R(a) - R(b) == R(r), f"{st!r}")
            for a, b, r in re.findall(rf"\b({num}) \+ ({num}) = ({num})", st):
                need(R(a) + R(b) == R(r), f"{st!r}")
            for a, b, r in re.findall(rf"\b({num}) ÷ ({num}) = ({num})", st):
                need(R(a) / R(b) == R(r), f"{st!r}")
            for a, b, r in re.findall(rf"\b({num}) ÷ ({num}) × 100 = ({num})", st):
                need(R(a) / R(b) * 100 == R(r), f"{st!r}")
            for a, b, r in re.findall(rf"\b({num}) × ({num}) = ({num})", st):
                if "÷" not in st:
                    need(R(a) * R(b) == R(r), f"{st!r}")


def cf_near_curve(curve, want):
    return any(abs(a - want[0]) < 1e-9 and abs(b - want[1]) < 1e-9 for a, b in curve)


def cf_pick(q, c):
    """Pick the curve: each card holds the points its mistake says, and only the right one is right."""
    rows = q["table"]["rows"]
    need(rows[0][1] == ["frequency"], "table heads")
    bs, fs, w = cf_classes(rows, c)
    fs = [int(f) for f in fs]
    run = cf_running(fs)
    sets = {"": [(bs[0], 0)] + [(bs[i + 1], run[i]) for i in range(len(fs))],
            "midpoints": [(bs[0], 0)] + [(sp.Rational(bs[i] + bs[i + 1], 2), run[i]) for i in range(len(fs))],
            "frequencies": [(bs[0], 0)] + [(bs[i + 1], fs[i]) for i in range(len(fs))],
            "lower": [(bs[i], run[i]) for i in range(len(fs))]}
    refs = {"": "", "midpoints": CF_B + "0", "frequencies": CF_B + "1", "lower": ""}
    need(sorted(o["mistake"] for o in q["choices"]) == sorted(sets), "the four cards aren't the four curves")
    want = None
    for o, gr in zip(q["choices"], q["graphs"]):
        need(o["ref"] == refs[o["mistake"]], f"the {o['mistake']} graph is mistagged")
        for p in sets[o["mistake"]]:
            need(cf_near_curve(gr["curves"][0], (float(p[0]), float(p[1]))), f"the {o['mistake']!r} card misses {p}")
        need(gr["x_name"] == c[4] and gr["y_name"] == "cf", "the card's axes aren't named")
        if o["correct"]:
            want = o["text"]
    need(q["answer_text"] == want and want is not None, "the right graph isn't the answer")
    return want


def check_cumulative_frequency(q):
    g, u, L, rep, asked = q["given"], q["view"]["unknown"], q["lines"], q["view"]["rep"], q["asked"]
    need(q["paper"] == 1, "cumulative frequency is Paper 1")
    c = CF_CTX[int(g["ctx"])]
    who, of, axis, noun, sym, unit, more, most, dx0, limit = c
    wrongs, want = {}, None
    spread = ", taking each class as evenly spread."
    if u == "pick-curve":
        want = cf_pick(q, c)
        gc_check_common(q, want, {CF_B + "0": {o["text"] for o in q["choices"]}, CF_B + "1": {o["text"] for o in q["choices"]}})
        return None, None
    if rep == "graph":
        n, dx, dy, pts = cf_curve(q, c)
        rx = lambda y: cf_read_x(pts, y, dx, dy)
        ry = lambda x: cf_read_y(pts, x, dx, dy)
        v_more = re.escape(more).replace(r"\{\}", r"(\d+)")
        if u == "median-from-graph":
            need(asked == f"Use the curve to estimate the median {noun}.", f"asked {asked!r}")
            med = rx(sp.Rational(n, 2))
            need(med != 10 * dx, "the median is at the middle of the axis")
            want = "median = " + cf_val(med, c)
            wrongs = {CF_Q + "0": {"median = " + cf_val(10 * dx, c)},
                      CF_T + "7": {"median = " + cf_val(rx(sp.Rational(k * n, 4)), c) for k in (1, 3)}}  # a quartile's height
        elif u == "quartile-from-graph":
            low = "lower quartile" in asked
            lab = "Q1 = " if low else "Q3 = "
            want = lab + cf_val(rx(sp.Rational(n, 4) * (1 if low else 3)), c)
            wrongs = {CF_T + "7": {lab + cf_val(rx(sp.Rational(n, 4) * (3 if low else 1)), c), lab + cf_val(rx(sp.Rational(n, 2)), c)}}  # the other quartile's or the median's height
        elif u == "iqr-from-graph":
            a, b = rx(sp.Rational(n, 4)), rx(sp.Rational(3 * n, 4))
            want = "IQR = " + cf_val(b - a, c)
            wrongs = {CF_Q + "1": {"IQR = " + cf_val(sp.Rational(n, 2), c)},
                      CF_T + "8": {"IQR = " + cf_val(a, c), "IQR = " + cf_val(b, c)},  # one quartile alone
                      CF_T + "9": {"IQR = " + cf_val(a + b, c)}}  # added
        elif u == "percentile-from-graph":
            k = int(re.match(r"Use the curve to estimate the (\d+)", asked).group(1))
            need(n != 100, "k and k% of n are the same when n is 100")
            want = "percentile = " + cf_val(rx(sp.Rational(k * n, 100)), c)
            wrongs = {CF_Q + "2": {"percentile = " + cf_val(rx(k), c)}}
        elif u == "range-from-graph":
            want = "range = " + cf_val(pts[-1][0] - pts[0][0], c)
            wrongs = {CF_T + "10": {"range = " + cf_val(pts[-1][0], c)},  # the end only
                      CF_T + "9": {"range = " + cf_val(pts[-1][0] + pts[0][0], c)},  # added
                      CF_T + "11": {"range = " + cf_val(rx(sp.Rational(3 * n, 4)) - rx(sp.Rational(n, 4)), c)}}  # the IQR
        elif u in ("count-below", "count-above", "percent-above", "scale-to-population"):
            if u == "count-below":
                mt = re.fullmatch(rf"Estimate how many {who} " + re.escape(most).replace(r"\{\}", r"(\d+)") + r"\.", asked)
            elif u == "count-above":
                mt = re.fullmatch(rf"Estimate how many {who} {v_more}\.", asked)
            elif u == "percent-above":
                mt = re.fullmatch(rf"Estimate the percentage of the {who} that {v_more}\.", asked)
            else:
                mt = re.fullmatch(rf"Estimate how many of all \d+ {who} {v_more}\.", asked)
            need(mt is not None, f"can't read {asked!r}")
            f = ry(int(mt.group(1)))
            if u == "count-below":
                want = f"number = {f}"
                wrongs = {CF_T + "12": {f"number = {n - f}"}}  # those above
            elif u == "count-above":
                want = f"number = {n - f}"
                wrongs = {CF_C + "0": {f"number = {f}"}}
            elif u == "percent-above":
                p = sp.Rational((n - f) * 100, n)
                need(p.q == 1, "the percentage isn't whole")
                want = f"percentage = {p}%"
                wrongs = {CF_C + "0": {f"percentage = {100 - p}%"}, CF_T + "15": {f"percentage = {n - f}%"}}  # the count, not a percentage
            else:
                m2 = re.fullmatch(rf"They were chosen at random from (\d+) {who}\.", L[2])
                need(m2 is not None, f"can't read {L[2]!r}")
                whole = int(m2.group(1))
                need(whole % n == 0 and f"all {whole} " in asked, "the whole group isn't a multiple of the sample")
                want = f"number = {(n - f) * whole // n}"
                wrongs = {CF_C + "0": {f"number = {f * whole // n}"}, CF_T + "17": {f"number = {n - f}"}}  # not scaled up
        elif u == "count-between":
            mt = re.fullmatch(rf"Estimate how many {who} are between (\d+) {unit} and (\d+) {unit}\.", asked)
            need(mt is not None, f"can't read {asked!r}")
            a, b = ry(int(mt.group(1))), ry(int(mt.group(2)))
            want = f"number = {b - a}"
            wrongs = {CF_T + "13": {f"number = {b}"}, CF_T + "9": {f"number = {a + b}"}, CF_T + "14": {f"number = {n - (b - a)}"}}  # upper only, added, outside
        elif u == "percentile-of-value":
            mt = re.fullmatch(rf"Which percentile of the {noun} is (\d+) {unit}\?", asked)
            need(mt is not None, f"can't read {asked!r}")
            f = ry(int(mt.group(1)))
            p = sp.Rational(f * 100, n)
            need(p.q == 1, "the percentile isn't whole")
            want = f"percentile = {p}"
            wrongs = {CF_T + "15": {f"percentile = {f}"}, CF_T + "16": {f"percentile = {100 - p}"}}  # the count; the share above
        elif u == "cutoff-top":
            mt = re.fullmatch(rf"The (\d+) {who} with the highest {noun} are set aside\.", L[2])
            need(mt is not None, f"can't read {L[2]!r}")
            t = int(mt.group(1))
            want = f"{noun} = " + cf_val(rx(n - t), c)
            wrongs = {CF_C + "1": {f"{noun} = " + cf_val(rx(t), c)}}
        elif u == "cutoff-percent":
            mt = re.fullmatch(r"(\d+)% of the " + who + " " + re.escape(more).replace(r"\{\}", "k") + r"\. Find k\.", asked)
            need(mt is not None, f"can't read {asked!r}")
            t = sp.Rational(int(mt.group(1)) * n, 100)
            want = "k = " + cf_val(rx(n - t), c)
            wrongs = {CF_C + "1": {"k = " + cf_val(rx(t), c)}}
        elif u == "share-of-limit":
            need(limit is not None and L[2] == limit.format(gr_x1 := q["graph"]["x1"]), f"can't read {L[2]!r}")
            mt = re.fullmatch(rf"Estimate how many {who} are above (\d+)% of that limit\.", asked)
            need(mt is not None, f"can't read {asked!r}")
            f = ry(sp.Rational(int(mt.group(1)) * gr_x1, 100))
            need(0 < f < n, "nobody or everybody is above it")
            want = f"number = {n - f}"
            wrongs = {CF_C + "0": {f"number = {f}"}}
        elif u == "frequency-from-graph":
            mt = re.fullmatch(rf"Find the number of {who} in the class (\d+) < {sym} ≤ (\d+)\.", asked)
            need(mt is not None, f"can't read {asked!r}")
            a, b = ry(int(mt.group(1))), ry(int(mt.group(2)))
            want = f"number = {b - a}"
            wrongs = {CF_B + "1": {f"number = {b}"}, CF_T + "20": {f"number = {a}"}, CF_T + "9": {f"number = {a + b}"}}  # the lower total; added
        elif u == "p-q-from-graph":
            need(q["asked"] == "Use the curve to find p and q.", f"asked {asked!r}")
            rows = q["table"]["rows"]
            bs, fs, w = cf_classes(rows, c)
            need(sorted(x for x in fs if x in "pq") == ["p", "q"], "the table doesn't hide p and q")
            vals, tops = {}, {}
            for j, f in enumerate(fs):
                got = ry(bs[j + 1]) - (ry(bs[j]) if j else 0)
                if j == 0:
                    need(bs[0] == pts[0][0], "the first class doesn't start where the curve does")
                if f in "pq":
                    vals[f], tops[f] = got, ry(bs[j + 1])
                else:
                    need(int(f) == got, f"the table's {f} isn't what the curve gives ({got})")
            want = f"p = {vals['p']}, q = {vals['q']}"
            wrongs = {CF_B + "1": {f"p = {tops['p']}, q = {tops['q']}"}, CF_T + "21": {f"p = {vals['q']}, q = {vals['p']}"}}  # swapped
        else:
            raise Fail(f"no check for {u}")
    elif u == "frequency-from-cf":
        rows = q["table"]["rows"]
        vals = {}
        for row in rows[1:]:
            mt = re.fullmatch(rf"{sym} ≤ (\d+)", row[0])
            need(mt is not None, f"can't read {row[0]!r}")
            vals[int(mt.group(1))] = int(row[1][0])
        keys = list(vals)
        need(all(vals[a] < vals[b] for a, b in zip(keys, keys[1:])) and vals[keys[0]] == 0, "the totals don't rise from 0")
        mt = re.fullmatch(rf"Find the number of {who} in the class (\d+) < {sym} ≤ (\d+)\.", asked)
        a, b = vals[int(mt.group(1))], vals[int(mt.group(2))]
        need(a > 0, "the class is the first one")
        want = f"number = {b - a}"
        wrongs = {CF_B + "1": {f"number = {b}"}, CF_T + "20": {f"number = {a}"}, CF_T + "9": {f"number = {a + b}"}}  # the lower total; added
    elif u == "cf-entry":
        rows = q["table"]["rows"]
        need(asked == "Find the cumulative frequency marked ?.", f"asked {asked!r}")
        fs = [int(r[1][0]) for r in rows[1:]]
        cum = [r[1][1] for r in rows[1:]]
        j = cum.index("?")
        run = cf_running(fs)
        need(j >= 1 and all(cum[i] == str(run[i]) for i in range(j)) and all(x == "–" for x in cum[j + 1:]), "the shown totals are wrong")
        want = f"? = {run[j]}"
        wrongs = {CF_B + "1": {f"? = {fs[j]}"}, CF_T + "18": {f"? = {run[j - 1]}"}}  # the total so far
    elif u == "last-frequency":
        rows = q["table"]["rows"]
        fs = [r[1][0] for r in rows[1:]]
        n = int(rows[-1][1][1])
        need(fs.count("p") == 1, "no p")
        others = sum(int(f) for f in fs if f != 'p')
        want = f"p = {n - others}"
        wrongs = {CF_T + "19": {f"p = {others}"}, CF_B + "1": {f"p = {n}"}}  # the others' sum; the total
    else:
        n, bs, fs, run = cf_table(q, c)
        val_more = re.escape(more).replace(r"\{\}", r"(\d+)")
        if u == "median-from-table":
            need(asked == f"Estimate the median {noun}{spread}", f"asked {asked!r}")
            want = "median = " + cf_val(cf_clean(cf_interp(bs, fs, run, sp.Rational(n, 2))), c)
            wrongs = {CF_Q + "0": {"median = " + cf_val(sp.Rational(bs[0] + bs[-1], 2), c)}}
        elif u == "quartile-from-table":
            low = "lower quartile" in asked
            want = ("Q1 = " if low else "Q3 = ") + cf_val(cf_clean(cf_interp(bs, fs, run, sp.Rational(n, 4) * (1 if low else 3))), c)
        elif u == "iqr-from-table":
            a, b = cf_interp(bs, fs, run, sp.Rational(n, 4)), cf_interp(bs, fs, run, sp.Rational(3 * n, 4))
            want = "IQR = " + cf_val(cf_clean(b - a), c)
            wrongs = {CF_Q + "1": {"IQR = " + cf_val(sp.Rational(n, 2), c)},
                      CF_T + "8": {"IQR = " + cf_val(a, c), "IQR = " + cf_val(b, c)},  # one quartile alone
                      CF_T + "9": {"IQR = " + cf_val(a + b, c)}}  # added
        elif u == "percentile-from-table":
            k = int(re.match(r"Estimate the (\d+)", asked).group(1))
            need(n != 100, "k and k% of n are the same when n is 100")
            want = "percentile = " + cf_val(cf_clean(cf_interp(bs, fs, run, sp.Rational(k * n, 100))), c)
            wrongs = {CF_Q + "2": {"percentile = " + cf_val(cf_interp(bs, fs, run, k), c)}}
        elif u == "count-below-table":
            mt = re.fullmatch(rf"Estimate how many {who} " + re.escape(most).replace(r"\{\}", r"(\d+)") + re.escape(spread), asked)
            need(mt is not None, f"can't read {asked!r}")
            f = cf_count(bs, fs, run, int(mt.group(1)))
            need(f.q == 1, "the count isn't whole")
            want = f"number = {f}"
            wrongs = {CF_T + "12": {f"number = {n - f}"}}  # those above
        elif u == "count-above-table":
            mt = re.fullmatch(rf"Estimate how many {who} {val_more}" + re.escape(spread), asked)
            need(mt is not None, f"can't read {asked!r}")
            f = cf_count(bs, fs, run, int(mt.group(1)))
            need(f.q == 1, "the count isn't whole")
            want = f"number = {n - f}"
            wrongs = {CF_C + "0": {f"number = {f}"}}
        elif u == "count-between-table":
            mt = re.fullmatch(rf"Estimate how many {who} are between (\d+) {unit} and (\d+) {unit}" + re.escape(spread), asked)
            need(mt is not None, f"can't read {asked!r}")
            a, b = cf_count(bs, fs, run, int(mt.group(1))), cf_count(bs, fs, run, int(mt.group(2)))
            need(a.q == 1 and b.q == 1 and b > a, "the counts aren't whole")
            want = f"number = {b - a}"
            wrongs = {CF_T + "13": {f"number = {b}"}, CF_T + "9": {f"number = {a + b}"}, CF_T + "14": {f"number = {n - (b - a)}"}}  # upper only, added, outside
        elif u == "cutoff-table":
            mt = re.match(rf"The (\d+) {who} with the highest {noun} are set aside\.", asked)
            need(mt is not None, f"can't read {asked!r}")
            t = int(mt.group(1))
            want = f"{noun} = " + cf_val(cf_clean(cf_interp(bs, fs, run, n - t)), c)
            wrongs = {CF_C + "1": {f"{noun} = " + cf_val(cf_interp(bs, fs, run, t), c)}}
        elif u == "plot-point":
            mt = re.fullmatch(rf"Which point is plotted on the curve for the class (\d+) < {sym} ≤ (\d+)\?", asked)
            need(mt is not None, f"can't read {asked!r}")
            a, b = int(mt.group(1)), int(mt.group(2))
            j = bs.index(b) - 1
            want = f"({b}, {run[j]})"
            wrongs = {CF_B + "0": {f"({dec_text(sp.Rational(a + b, 2))}, {run[j]})"}, CF_B + "1": {f"({b}, {fs[j]})"},
                      CF_T + "22": {f"({a}, {run[j]})"}}  # at the lower boundary
        elif u == "curve-start":
            need(bs[0] > 0, "the curve starts at the origin, so (0, 0) is no wrong option")
            want = f"({bs[0]}, 0)"
            wrongs = {CF_T + "23": {"(0, 0)"}, CF_T + "24": {f"({bs[1]}, {fs[0]})"},  # from the origin; from the first point
                      CF_B + "0": {f"({dec_text(sp.Rational(bs[0] + bs[1], 2))}, 0)"}}  # the class's middle

        else:
            raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs)
    cf_arith(q)
    return None, None


# ── arc-sector (t3-arc-sector, FAL-726) ──────────────────────
# The `arc-sector` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/arc_sector.gd. r, θ, the arc, the area and the perimeter are read back
# from the lines or the figure, and each answer is worked out from those alone, exactly, or to
# 40 digits where it holds a root. A figure is held to its real angle.

AS_SKILL = "SL3.4."
AS_EDGE = sp.Rational(29, 1000)         # the engine's is 0.03
AS_DEN = 24
AS_R1 = (2, 12)
AS_DEG_P1 = {30, 45, 60, 90, 120, 135, 150, 210, 225, 240, 270, 300}


def as_val(text):
    """An exact value as the game writes it: "12 + 3π", "9π − 4.5", "5π/6", "7.5", "1/6"."""
    t = text.strip().replace("−", "-")
    t = re.sub(r"(\d)π", r"\1*pi", t).replace("π", "pi")
    return sp.nsimplify(sp.sympify(t, rational=True), rational=True) if "pi" not in t else sp.sympify(t, rational=True)


def as_pair(v):
    """a and b of a + bπ."""
    e = sp.expand(v)
    b = e.coeff(sp.pi)
    a = e - b * sp.pi
    need(a.is_Rational and b.is_Rational, f"{v} is not a + bπ")
    return a, b


def as_pi(b):
    n, d = abs(b.p), b.q
    return ("−" if b < 0 else "") + ("π" if n == 1 else f"{n}π") + ("" if d == 1 else f"/{d}")


def as_exact(v):
    a, b = as_pair(v)
    if b == 0:
        return dec_text(a)
    if a == 0:
        return as_pi(b)
    if a < 0:
        return f"{as_pi(b)} − {dec_text(-a)}"
    return f"{dec_text(a)} + {as_pi(b)}"


def as_text(label, v, tail, paper):
    return label + (as_exact(v) if paper == 1 else rg_s(sp.N(v, 40))) + tail


def as_clear(x):
    v = abs(num(x))
    e = sp.floor(sp.log(v, 10))
    scaled = v / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= AS_EDGE


def as_read(q):
    """r, θ in radians and as written, the arc, the area and the perimeter, and the unit."""
    L, rep = q["lines"], q["view"]["rep"]
    k = {"r": None, "th": None, "tt": None, "form": None, "l": None, "a": None, "p": None, "unit": " cm"}

    def angle(text, deg):
        k["tt"] = text
        k["form"] = "deg" if deg else ("pi" if "π" in text else "rad")
        v = as_val(text)
        k["th"] = v * sp.pi / 180 if deg else v
        if deg:
            k["deg"] = v

    def plain(text):
        return as_val(text)

    if rep == "equation":
        for ln in L:
            if ln == "Sector OAB has centre O.":
                continue
            m = re.fullmatch(r"r = (\S+) cm", ln)
            if m:
                k["r"] = plain(m.group(1))
                continue
            m = re.fullmatch(r"θ = (\S+?)(°| radians?)", ln)
            if m:
                angle(m.group(1), m.group(2) == "°")
                continue
            m = re.fullmatch(r"(arc AB|area|perimeter) = (.+?) cm(²?)", ln)
            need(m is not None, f"can't read {ln!r}")
            k[{"arc AB": "l", "area": "a", "perimeter": "p"}[m.group(1)]] = plain(m.group(2))
        return k
    if rep == "words":
        text = " ".join(L)
        m = re.search(r"has a reach of ([\d.]+) (cm|km|m)\b", text)
        if m:
            k["r"] = plain(m.group(1))
            k["unit"] = " " + m.group(2)
        m = re.search(r"(?:with an angle of|a gap with an angle of) (\S+?)(°| radians?) at the centre", text)
        if m:
            angle(m.group(1), m.group(2) == "°")
        for key, pat in (("l", r"The curved edge of the sector is (.+?) (cm|km|m) long\."), ("a", r"The area of the sector is (.+?) (cm|km|m)²\."),
                         ("p", r"The perimeter of the sector is (.+?) (cm|km|m)\.")):
            m = re.search(pat, text)
            if m:
                k[key] = plain(m.group(1))
                k["unit"] = " " + m.group(2)
        return k
    g = q["graph"]
    if q["view"]["unknown"] == "segments-theta":
        return k
    need(g is not None and g["kind"] == "sector", "no sector drawn")
    k["fig"] = g
    if g["r_label"] not in ("", "r"):
        k["r"] = plain(g["r_label"].removesuffix(" cm"))
    if g["angle_label"] not in ("", "θ"):
        t = g["angle_label"]
        angle(t.rstrip("°"), t.endswith("°"))
    if g["arc_label"]:
        k["l"] = plain(g["arc_label"].removesuffix(" cm"))
    for ln in L:
        m = re.fullmatch(r"The area of the sector is (.+) cm²\.", ln)
        if m:
            k["a"] = plain(m.group(1))
        m = re.fullmatch(r"The perimeter of the sector is (.+) cm\.", ln)
        if m:
            k["p"] = plain(m.group(1))
    return k


def as_figure(k, th):
    """The sector is drawn to the angle of the question."""
    g = k.get("fig")
    if g is not None:
        need(abs(sp.Float(g["theta"], 30) - sp.N(th, 30)) < sp.Rational(1, 10**6), f"the figure's angle {g['theta']} is not {th}")


def as_limits(q, k):
    """Paper 1 numbers are simple; Paper 2 numbers are to 1 or 2 places."""
    r, paper = k["r"], q["paper"]
    if r is not None:
        if paper == 1:
            need(r.q == 1 and AS_R1[0] <= r <= AS_R1[1], f"r = {r} on Paper 1")
        else:
            need((r * 10).q == 1, f"r = {r} is not to 1 d.p.")
    th = k["th"]
    if th is not None:
        need(0 < sp.N(th) < 2 * sp.pi, f"θ = {th}")
        if paper == 1 and k["form"] == "deg":
            need(k["deg"] in AS_DEG_P1, f"{k['deg']}° is no landmark")
        if paper == 2 and k["form"] == "deg":
            need(k["deg"] % 15 != 0, f"{k['deg']}° needs no calculator")


def as_eval(text):
    t = text.strip()
    if not t or not re.search(r"\d", t):
        return None
    t = t.replace("½", "(1/2)").replace("²", "**2").replace("×", "*").replace("÷", "/").replace("−", "-")
    t = re.sub(r"√(\d+(?:\.\d+)?)", r"sqrt(\1)", t)
    t = re.sub(r"(\d+(?:\.\d+)?)?π(?:/(\d+))?", lambda m: f"(({m.group(1) or 1})*pi/{m.group(2) or 1})", t)
    t = re.sub(r"(\d|\))\s*\(", r"\1*(", t)
    try:
        return sp.sympify(t, rational=True)
    except (sp.SympifyError, SyntaxError, TypeError):
        return None


def as_working(q):
    """Each "expr = value" whose two sides are plain numbers holds for the figures shown."""
    n = 0
    for sol in q["solutions"]:
        for st in sol["steps"]:
            parts = st.split(" = ")
            for left, right in zip(parts, parts[1:]):
                lm = re.search(r"[\d.π×÷+−/²()½√ °]+$", left)
                rm = re.match(r"[\d.π/ +−×÷²()½]+", right.strip())
                if lm is None or rm is None:
                    continue
                lt = lm.group().replace("°", "")
                if not re.search(r"[×÷+−/²½√π]", lt):
                    continue
                lv, rv = as_eval(lt), as_eval(rm.group().rstrip(" +−"))
                if lv is None or rv is None:
                    continue
                shown = rm.group().strip()
                if q["paper"] == 1 or re.search(r"[π/×÷²]", shown):
                    ok = abs(sp.N(lv - rv, 30)) < sp.Rational(1, 10**20)
                else:
                    d = len(shown.split(".")[1]) if "." in shown else 0
                    ok = abs(sp.N(lv - rv, 30)) <= sp.Rational(6, 10) * sp.Rational(1, 10**d)
                need(ok, f"{sol['name']}: in {st!r}, {lt.strip()} is {sp.N(lv, 10)}, not {shown}")
                n += 1
    return n


def as_plate_root(goal, deg=False):
    """θ with θ − sin θ = goal on (0, 2π), by halving (it only rises)."""
    lo, hi = mpmath.mpf(0), 2 * mpmath.pi
    for _ in range(140):
        mid = (lo + hi) / 2
        if mid - mpmath.sin(mpmath.radians(mid) if deg else mid) < goal:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2


def check_arc_sector(q):
    with mpmath.workdps(40):
        return as_check(q)


def as_check(q):
    u, L, rep, asked, paper = q["view"]["unknown"], q["lines"], q["view"]["rep"], q["asked"], q["paper"]
    k = as_read(q)
    r, th, l, a, p, un = k["r"], k["th"], k["l"], k["a"], k["p"], k["unit"]
    un2 = un + "²"
    wr = {}
    pi = sp.pi

    def W(ref, label, tail, v):
        if sp.N(v) > 0:
            wr.setdefault(AS_SKILL + ref, set()).add(as_text(label, v, tail, paper))

    def M(i, label, tail, v):
        """The type's own misconception #i (FAL-815): its value from the question's numbers."""
        if sp.N(v) > 0:
            wr.setdefault(f"t3-arc-sector#{i}", set()).add(as_text(label, v, tail, paper))

    label, tail, v = None, "", None
    if u == "deg-to-rad":
        d = k["deg"]
        label, v = "θ = ", d * pi / 180
        need(paper == 2 or (d % 30 == 0 or d % 45 == 0), f"{d}° is no landmark")
        if paper == 1:
            wr[AS_SKILL + "convert#0"] = {"θ = " + sig3(d * 180 / pi)}
            wr[AS_SKILL + "convert#2"] = {"θ = " + sig3(v)}
        else:
            W("convert#0", label, "", d * 180 / pi)
            M(11, label, "", d / 180)
        M(10, label, "", d * pi / 360)
    elif u == "rad-to-deg":
        label, tail, v = "θ = ", "°", th * 180 / pi
        if paper == 1:
            need(k["form"] == "pi", "Paper 1 converts a multiple of π")
            wr[AS_SKILL + "convert#1"] = {f"θ = {sig3(th)}°"}
        else:
            wr[AS_SKILL + "convert#1"] = {f"θ = {sig3(th)}°"}
        M(10, label, tail, th * 360 / pi)
    elif u == "arc-length":
        label, tail, v = "l = ", un, r * th
        if k["form"] == "deg":
            W("arc-length#0", label, tail, r * k["deg"])
        M(12, label, tail, r**2 * th / 2)
        M(13, label, tail, r * th + 2 * r)
    elif u == "perimeter":
        label, tail, v = "P = ", un, 2 * r + r * th
        W("arc-length#1", label, tail, r * th)
        if k["form"] == "deg":
            W("arc-length#0", label, tail, 2 * r + r * k["deg"])
        M(14, label, tail, r * th + r)
    elif u == "theta-from-arc":
        label, v = "θ = ", l / r
        M(15, label, "", l * r)
    elif u == "r-from-arc":
        label, tail, v = "r = ", un, l / th
        if paper == 2:
            M(15, label, tail, l * th)
    elif u == "r-from-perimeter":
        label, tail, v = "r = ", un, p / (2 + th)
        W("arc-length#1", label, tail, p / th)
        M(14, label, tail, p / (1 + th))
    elif u == "theta-from-perimeter":
        label, v = "θ = ", (p - 2 * r) / r
        W("arc-length#1", label, "", p / r)
        M(14, label, "", (p - r) / r)
    elif u == "major-arc":
        label, tail, v = "l = ", un, r * (2 * pi - th)
        need(sp.N(th) < sp.N(pi), "the given angle is not the minor angle")
        W("arc-length#2", label, tail, r * th)
        M(16, label, tail, 2 * pi * r)
        M(13, label, tail, r * (2 * pi - th) + 2 * r)
    elif u == "r-in-terms-of-theta":
        if rep == "words":
            mt = re.search(r"is ([\d.]+) (cm|km|m) long", L[0])
        else:
            mt = re.fullmatch(r"([\d.]+) (cm)", k["fig"]["arc_label"])
        need(mt is not None, "can't read the arc")
        ls = mt.group(1)
        want = f"r = {dec_text(R(ls))}/θ"
        gc_check_common(q, want, {"t3-arc-sector#15": {f"r = {dec_text(R(ls))}θ"}})
        return None, None
    elif u == "theta-from-bent-strip":
        mt = re.fullmatch(r"A water trough is bent from a strip of tin ([\d.]+) cm wide\. Across the strip it has a straight side ([\d.]+) cm long, a curved part, then another straight side ([\d.]+) cm long\.", L[0])
        need(mt is not None and mt.group(2) == mt.group(3), f"can't read {L[0]!r}")
        mr = re.fullmatch(r"The curved part is an arc of a circle of radius ([\d.]+) cm\.", L[1])
        need(mr is not None, f"can't read {L[1]!r}")
        wd, sd, rr = R(mt.group(1)), R(mt.group(2)), R(mr.group(1))
        label, v = "θ = ", (wd - 2 * sd) / rr
        M(17, label, "", wd / rr)
        M(18, label, "", (wd - sd) / rr)
        M(15, label, "", (wd - 2 * sd) * rr)
    elif u == "sector-area":
        label, tail, v = "A = ", un2, r**2 * th / 2
        if k["form"] == "deg":
            W("sector-area#0", label, tail, r**2 * k["deg"] / 2)
        slip = r * th**2 / 2
        if paper == 2 or k["form"] == "rad":
            W("sector-area#1", label, tail, slip)
        else:
            b = sp.expand(slip / pi**2)
            wr[AS_SKILL + "sector-area#1"] = {f"A = {as_pi(sp.Rational(b)).replace('π', 'π²')}{un2}"}
        M(19, label, tail, r**2 * th)
        M(20, label, tail, r * th / 2)
        M(21, label, tail, r * th)
    elif u == "theta-from-area":
        label, v = "θ = ", 2 * a / r**2
        M(19, label, "", a / r**2)
        M(20, label, "", 2 * a / r)
    elif u == "r-from-area":
        label, tail, v = "r = ", un, sp.sqrt(2 * a / th)
        M(22, label, tail, 2 * a / th)
        if paper == 2:
            M(19, label, tail, sp.sqrt(a / th))
    elif u == "major-sector":
        label, tail, v = "A = ", un2, r**2 * (2 * pi - th) / 2
        need(sp.N(th) < sp.N(pi), "the given angle is not the minor angle")
        W("sector-area#2", label, tail, r**2 * th / 2)
        M(23, label, tail, pi * r**2)
        M(21, label, tail, r * (2 * pi - th))
        M(19, label, tail, r**2 * (2 * pi - th))
    elif u == "area-from-arc":
        label, tail, v = "A = ", un2, r * l / 2
        M(19, label, tail, r * l)
    elif u == "perimeter-from-area":
        rr = sp.sqrt(2 * a / th)
        label, tail, v = "P = ", un, rr * (2 + th)
        W("arc-length#1", label, tail, rr * th)
        M(14, label, tail, rr * (1 + th))
    elif u == "major-from-perimeter":
        mt = re.fullmatch(r"The diagram shows a circle with centre O\. Angle AOB is ([\d.]+) radians, and the perimeter of the small shaded sector is ([\d.]+) cm\.", L[0])
        need(mt is not None, f"can't read {L[0]!r}")
        t0, per = R(mt.group(1)), R(mt.group(2))
        th = t0
        k["th"] = None
        rr = per / (2 + t0)
        label, tail, v = "A = ", un2, rr**2 * (2 * pi - t0) / 2
        W("sector-area#2", label, tail, rr**2 * t0 / 2)
        M(23, label, tail, pi * rr**2)
        M(19, label, tail, rr**2 * (2 * pi - t0))
    elif u == "cone-radius":
        if rep == "words":
            mt = re.fullmatch(r"A sheet of tin is cut into a sector of radius ([\d.]+) cm and angle (\S+?)(°| radians?)\. Its two straight edges are joined to make a funnel, with the arc as the rim\.", L[0].replace(" m ", " cm ").replace(" km ", " cm "))
            need(mt is not None, f"can't read {L[0]!r}")
            r = R(mt.group(1))
            d = as_val(mt.group(2))
            th = d * pi / 180 if mt.group(3) == "°" else d
            un = re.search(r"radius [\d.]+( \w+) and", L[0]).group(1)
        else:
            need(k["fig"].get("cone") is True, "the cone isn't drawn")
        label, tail, v = "radius = ", un, r * th / (2 * pi)
        if paper == 1:
            need(v.is_Rational, f"radius {v}")
        M(24, label, tail, r * th)
        M(25, label, tail, r * th / 2)
        M(26, label, tail, r)
    elif u in ("ring-inner-radius", "ring-perimeter"):
        need(paper == 2, "a curved strip is Paper 2")
        g = q["graph"]
        need(g is not None and g["kind"] == "sector" and g["inner"] > 0, "no curved strip drawn")
        mt = re.search(r"The reflex angle at O is ([\d.]+) radians, the outer radius is ([\d.]+) cm and the inner radius is (r cm|[\d.]+ cm)\.", L[0])
        need(mt is not None, f"can't read {L[0]!r}")
        t0, big = R(mt.group(1)), R(mt.group(2))
        need(t0 > 3 and t0 < 2 * pi, "the angle is not reflex")
        need(g["angle_label"] == mt.group(1) and g["r_label"] == mt.group(2) + " cm", "the figure's labels")
        as_figure({"fig": g}, t0)
        if u == "ring-inner-radius":
            ma = re.fullmatch(r"The area of the strip is ([\d.]+) cm²\.", L[1])
            need(ma is not None, f"can't read {L[1]!r}")
            ar = R(ma.group(1))
            label, tail, v = "r = ", " cm", sp.sqrt(big**2 - 2 * ar / t0)
            M(22, label, tail, big**2 - 2 * ar / t0)
            M(19, label, tail, sp.sqrt(big**2 - ar / t0))
            M(27, label, tail, big - sp.sqrt(2 * ar / t0))
            need(0 < sp.N(v) < big, f"r = {sp.N(v)}")
        else:
            small = R(mt.group(3).removesuffix(" cm"))
            label, tail, v = "P = ", " cm", t0 * (big + small) + 2 * (big - small)
            M(28, label, tail, t0 * (big + small))
            M(29, label, tail, t0 * big + 2 * (big - small))
        th = None
    elif u == "segments-theta":
        need(paper == 2, "a plate is Paper 2")
        g = q["graph"]
        need(g is not None and g["kind"] == "plate", "no plate drawn")
        mt = re.fullmatch(r"A steel plate is a rectangle (\d+) cm by (\d+) cm\. An equal segment is cut from each of two opposite edges, as in the diagram\.", L[0])
        mr = re.fullmatch(r"Each segment is part of a circle of radius (\d+) cm, with angle θ at its centre O, where θ is in radians and 0 < θ < π\.", L[1])
        ma = re.fullmatch(r"The area of the plate that is left is ([\d.]+) cm²\.", L[2])
        need(mt and mr and ma, "can't read the plate")
        w, h, rho, ar = int(mt.group(1)), int(mt.group(2)), int(mr.group(1)), R(ma.group(1))
        need(g["w"] == w and g["h"] == h and g["rho"] == rho, "the plate drawn is another plate")
        goal = mpmath.mpf((w * h - ar).p) / (w * h - ar).q / rho**2
        root = as_plate_root(goal)
        need(0 < root < mpmath.pi, f"θ = {root}")
        chord = 2 * rho * mpmath.sin(root / 2)
        need(chord < h, "the cut is longer than the edge")
        need(abs(g["theta"] - float(root)) < 1e-6, "the figure's angle")
        v = nu_f(root)
        label = "θ = "
        wr[AS_SKILL + "segment-shaded#0"] = {"θ = " + rg_s(nu_f(as_plate_root(goal, True)))}
        wr["t3-arc-sector#30"] = {"θ = " + rg_s(nu_f(as_plate_root(2 * goal)))}
        th = None
    else:
        raise Fail(f"no check for {u}")
    # What the question drew or said matches the angle, once the angle is known.
    if u in ("theta-from-arc", "theta-from-perimeter", "theta-from-area"):
        as_figure(k, v)
    elif u == "area-from-arc":
        as_figure(k, l / r)
    elif u in ("r-from-arc", "r-from-perimeter", "r-from-area", "perimeter-from-area", "arc-length", "perimeter", "sector-area", "deg-to-rad", "rad-to-deg", "major-arc", "major-sector", "cone-radius"):
        if th is not None:
            as_figure(k, th)
    as_limits(q, k)
    trap = None
    if paper == 1:
        a0, b0 = as_pair(v)
        need(a0.q <= AS_DEN and b0.q <= AS_DEN, f"{v} has a big denominator")
        if b0 != 0:
            need(asked.endswith(" Give your answer in terms of π."), f"asked {asked!r}")
        if u in ("r-from-arc", "r-from-perimeter", "r-from-area"):
            need(v.is_integer, f"r = {v} is not whole on Paper 1")
    else:
        need(asked.endswith(" Give your answer to 3 significant figures."), f"asked {asked!r}")
        x = sp.N(v, 40)
        need(as_clear(x), f"{x} is on a rounding edge")
        t2 = bn_trap(label, x)
        trap = t2 + tail if t2 else None
    want = as_text(label, v, tail, paper)
    gc_check_common(q, want, wr, trap)
    as_working(q)
    return None, None


# ── circular-region (t3-composite-circular-region, FAL-739) ──
# The `circular-region` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/circular_region.gd. The numbers are read back from the lines and the
# figure, and each answer is worked out from those alone with mpmath at 40 digits, or exactly on
# Paper 1. A root of θ = k sin θ comes from its own halving, and the two roots of a sector's
# quadratic from the conditions. A figure is held to the shape it says it draws.

CR_SKILL = "SL3.4."
CR_T = "t3-composite-circular-region#"
CR_DEG_SECTOR, CR_ANY_SINE = CR_T + "13", CR_T + "14"
CR_LETTERS = "r is the radius of the sector and θ is its angle at the centre, in radians."
CR_DEN = 24
CR_BOTH = ("theta-in-r", "two-conditions-quadratic", "two-conditions-r", "two-conditions-theta", "two-conditions-both", "arc-area-radius")
CR_RATIOS_OUT = ((1, 1), (3, 5))        # the bank's own ratios


def cr_mp(x):
    x = sp.Rational(x)
    return mpmath.mpf(x.p) / x.q


def cr_root(k):
    """θ on (0, π) with θ = k sin θ, k > 1, by halving: θ/sin θ only rises."""
    lo, hi = mpmath.mpf(10) ** -30, mpmath.pi - mpmath.mpf(10) ** -30
    for _ in range(160):
        mid = (lo + hi) / 2
        if mid / mpmath.sin(mid) < k:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2


def cr_num(text):
    return R(text.replace(",", ""))


def cr_fig(q, shape, **labels):
    g = q["graph"]
    need(g is not None and g["kind"] == "region" and g["shape"] == shape, f"no {shape} drawn")
    for key, want in labels.items():
        need(g.get(key) == want, f"the figure's {key} is {g.get(key)!r}, not {want!r}")
    return g


def cr_drawn(g, th):
    need(abs(mpmath.mpf(g["theta"]) - th) < mpmath.mpf(10) ** -6, f"the figure's angle {g['theta']} is not {th}")


def cr_angle(text):
    """An angle as a label or a story writes it: (radians, degrees or None)."""
    if text.endswith("°"):
        d = cr_num(text[:-1])
        need(d.q == 1 and d % 15 != 0 and 0 < d < 180, f"{text} on Paper 2")
        return cr_mp(d) * mpmath.pi / 180, d
    t = cr_num(text)
    need(0 < t < sp.pi and (t * 100).q == 1, f"θ = {t}")
    return cr_mp(t), None


def cr_segment(q):
    """r, θ in radians, the degrees or None, and the unit, of a segment."""
    if q["view"]["rep"] == "words":
        m = re.fullmatch(r"(?:The floor of a round silo|A round pond at the bean farm|A round camp on the flats) has radius ([\d.]+) m\. A straight (wall|dam|fence) joins points A and B on its edge, and angle AOB at the centre O is (\S+?)(°| radians?)\. The smaller part, behind the \2, is the (grain bay|fish pen|goat yard)\.", q["lines"][0])
        need(m is not None, f"can't read {q['lines'][0]!r}")
        th, d = cr_angle(m.group(3) + ("°" if m.group(4) == "°" else ""))
        return cr_num(m.group(1)), th, d, " m"
    g = cr_fig(q, "segment")
    need(g["r_label"].endswith(" cm"), "the radius isn't labelled")
    th, d = cr_angle(g["angle_label"])
    cr_drawn(g, th)
    return cr_num(g["r_label"].removesuffix(" cm")), th, d, " cm"


def cr_eval(text):
    """A step's expression, with its sines worked out, or None."""
    def fn(m):
        arg = m.group(2).strip()
        deg = arg.endswith("°")
        v = as_eval(arg.rstrip("°"))
        if v is None:
            return "x"
        v = mpmath.mpf(str(sp.N(v, 45)))
        v = mpmath.radians(v) if deg else v
        return "(" + mpmath.nstr({"sin": mpmath.sin, "cos": mpmath.cos, "tan": mpmath.tan}[m.group(1)](v), 38) + ")"
    t = re.sub(r"(sin|cos|tan) ((?:\d+π?|π)(?:\.\d+)?(?:/\d+)?°?)", fn, text)
    if "x" in t:
        return None
    t = re.sub(r"(\d)√", r"\1*√", t)
    t = re.sub(r"(\d|\))\s*(\()", r"\1*\2", t)
    return as_eval(t.replace("e-", "E-"))


def cr_working(q):
    """Each "expr = value" of plain numbers holds, within the last figure shown."""
    n = 0
    for sol in q["solutions"]:
        for st in sol["steps"]:
            parts = st.split(" = ")
            for left, right in zip(parts, parts[1:]):
                lm = re.search(r"(?:sin |cos |tan |[\d.π×÷+−/²()½√ °])+$", left)
                rm = re.match(r"(?:sin |cos |tan |[\d.π/ +−×÷²()½√°])+", right.strip())
                if lm is None or rm is None:
                    continue
                lt, rt = lm.group().strip(), rm.group().strip().rstrip(" +−.")
                if not re.search(r"[×÷+−/²½√π]|sin|cos|tan", lt) or not rt or lt.startswith(("²", "+", "−", "×", "÷", "/")) or rt.endswith(("×", "÷", "/", "(")):
                    continue
                lv, rv = cr_eval(lt), cr_eval(rt)
                if lv is None or rv is None:
                    continue
                gap = abs(sp.N(lv - rv, 30))
                if re.fullmatch(r"[\d.]+", rt):
                    d = len(rt.split(".")[1]) if "." in rt else 0
                    ok = gap <= sp.Rational(6, 10) * sp.Rational(1, 10**d) if q["paper"] == 2 else gap < sp.Rational(1, 10**20)
                else:
                    ok = gap < (sp.Rational(1, 10**20) if q["paper"] == 1 else sp.Rational(1, 500))
                need(ok, f"{sol['name']}: in {st!r}, {lt} is {sp.N(lv, 10)}, not {rt}")
                n += 1
    return n


def cr_exact_pi(b):
    return as_pi(sp.Rational(b))


def cr_pi_x2(b):
    return ("πx²" if b.p == 1 else f"{b.p}πx²") + ("" if b.q == 1 else f"/{b.q}")


def check_circular_region(q):
    with mpmath.workdps(40):
        return cr_check(q)


def cr_check(q):
    u, L, rep, asked, paper = q["view"]["unknown"], q["lines"], q["view"]["rep"], q["asked"], q["paper"]
    pi = mpmath.pi
    sin, cos, tan, sqrt = mpmath.sin, mpmath.cos, mpmath.tan, mpmath.sqrt
    need(paper == 2 or u in CR_BOTH + ("segment-exact",), f"{u} on Paper {paper}")
    wr = {}

    def W(ref, x):
        if x > 0:
            wr.setdefault(ref if ref.startswith(CR_T) else CR_SKILL + ref, set()).add(label + rg_s(nu_f(x)) + tail)

    label, tail, x = None, "", None
    if u == "segment-area":
        r, th, d, un = cr_segment(q)
        rr = cr_mp(r)
        label, tail, x = "A = ", un + "²", rr**2 * (th - sin(th)) / 2
        W("segment-shaded#3", rr**2 * th / 2)
        W(CR_T + "15", rr**2 * (th + sin(th)) / 2)
        W(CR_T + "16", rr**2 * (th - sin(th)))
        W(CR_T + "17", rr * (th - sin(th)) / 2)
        if d is None:
            W("segment-shaded#0", rr**2 * (th - sin(mpmath.radians(th))) / 2)
        else:
            W(CR_DEG_SECTOR, rr**2 * (cr_mp(d) - sin(th)) / 2)
    elif u == "segment-perimeter":
        r, th, d, un = cr_segment(q)
        rr = cr_mp(r)
        label, tail, x = "P = ", un, rr * th + 2 * rr * sin(th / 2)
        W("segment-shaded#1", rr * th + 2 * rr)
        W(CR_T + "19", rr * th)
        if d is None:
            W(CR_ANY_SINE, rr * th + 2 * rr * sin(mpmath.radians(th / 2)))
        else:
            W("arc-length#0", rr * cr_mp(d) + 2 * rr * sin(th / 2))
    elif u == "segment-exact":
        need(paper == 1, "an exact landmark segment is Paper 1")
        g = cr_fig(q, "segment")
        r = cr_num(g["r_label"].removesuffix(" cm"))
        need(r.q == 1 and r % 2 == 0 and 4 <= r <= 12, f"r = {r}")
        t = as_val(g["angle_label"])
        need(t / sp.pi in [sp.Rational(a, b) for a, b in ((1, 6), (1, 3), (1, 2), (2, 3), (5, 6))], f"θ = {t}")
        cr_drawn(g, mpmath.mpf(str(sp.N(t, 45))))
        area = r**2 * t / 2 - r**2 * sp.sin(t) / 2
        b = r**2 * (t / sp.pi) / 2
        c = sp.nsimplify(b * sp.pi - area)
        surd = c.has(sp.sqrt(3))
        c0 = c / sp.sqrt(3) if surd else c
        root = "√3" if surd else ""
        want = f"A = {cr_exact_pi(b)} − {dec_text(c0)}{root} cm²"
        need(asked == "Find the exact area of the shaded segment.", f"asked {asked!r}")
        gc_check_common(q, want, {CR_SKILL + "segment-shaded#3": {f"A = {cr_exact_pi(b)} cm²"},
                                  CR_T + "15": {f"A = {cr_exact_pi(b)} + {dec_text(c0)}{root} cm²"},
                                  CR_T + "16": {f"A = {cr_exact_pi(2 * b)} − {dec_text(2 * c0)}{root} cm²"}})
        cr_working(q)
        return None, None
    elif u == "segment-in-terms-of-theta":
        g = cr_fig(q, "segment", angle_label="θ")
        r = cr_num(g["r_label"].removesuffix(" cm"))
        m = re.fullmatch(r"A and B lie on a circle with centre O and radius ([\d.]+) cm\. Chord AB cuts off the shaded segment, and angle AOB is θ radians, where 0 < θ < π\.", L[0])
        need(m and cr_num(m.group(1)) == r and r.q == 1, f"can't read {L[0]!r}")
        a = dec_text(r**2 / 2)
        a2, ah = dec_text(r**2), dec_text(r / 2)
        gc_check_common(q, f"A = {a}θ − {a} sin θ cm²", {CR_SKILL + "segment-shaded#3": {f"A = {a}θ cm²"},
                                                         CR_T + "15": {f"A = {a}θ + {a} sin θ cm²"},
                                                         CR_T + "16": {f"A = {a2}θ − {a2} sin θ cm²"},
                                                         CR_T + "17": {f"A = {ah}θ − {ah} sin θ cm²"}})
        cr_working(q)
        return None, None
    elif u == "segment-radius":
        g = cr_fig(q, "segment", r_label="r")
        th, _ = cr_angle(g["angle_label"])
        cr_drawn(g, th)
        m = re.fullmatch(r"The area of the segment is ([\d.]+) cm²\.", L[1])
        need(m is not None, f"can't read {L[1]!r}")
        a = cr_mp(cr_num(m.group(1)))
        label, tail, x = "r = ", " cm", sqrt(2 * a / (th - sin(th)))
        W("segment-shaded#3", sqrt(2 * a / th))
        W("segment-shaded#0", sqrt(2 * a / (th - sin(mpmath.radians(th)))))
        W(CR_T + "18", 2 * a / (th - sin(th)))
        W(CR_T + "16", sqrt(a / (th - sin(th))))
        W(CR_T + "15", sqrt(2 * a / (th + sin(th))))
    elif u in ("tether-area", "tether-expression", "tether-angle"):
        if rep == "words":
            m = re.fullmatch(r"Two straight walls meet at a corner A\. A rover is tied to a stake O on one wall by a cable ([\d.]+) m long, and the stake is ([\d.]+) m from A\. Stretched out, the cable reaches D further along that wall and E on the other wall, and angle DOE is ([\d.]+) radians?\.", L[0])
            need(m and m.group(1) == m.group(2), f"can't read {L[0]!r}")
            rr, th = cr_mp(cr_num(m.group(1))), cr_mp(cr_num(m.group(3)))
        else:
            head = "Two straight walls meet at A. A rover is tied by a cable to a stake O on one wall, with OA = OD = OE, where D is further along that wall and E is on the other wall. "
            need(L[0].startswith(head), f"can't read {L[0]!r}")
            rest = L[0][len(head):]
            g = cr_fig(q, "tether")
            if u == "tether-area":
                m = re.fullmatch(r"OA = ([\d.]+) m and angle DOE is ([\d.]+) radians?\.", rest)
                need(m is not None, f"can't read {rest!r}")
                rr, th = cr_mp(cr_num(m.group(1))), cr_mp(cr_num(m.group(2)))
                need(g["r_label"] == m.group(1) + " m" and g["angle_label"] == m.group(2), "the figure's labels")
                cr_drawn(g, th)
            elif u == "tether-angle":
                m = re.fullmatch(r"OA = ([\d.]+) m, arc DE is ([\d.]+) m long, and angle DOE is θ radians\.", rest)
                need(m is not None and g.get("mark_a") is True, f"can't read {rest!r}")
                rr, l = cr_mp(cr_num(m.group(1))), cr_mp(cr_num(m.group(2)))
                need(g["r_label"] == m.group(1) + " m" and g["arc_label"] == m.group(2) + " m", "the figure's labels")
                th = l / rr
                cr_drawn(g, th)
            else:
                need(rest == "OA = r m and angle DOE is θ radians.", f"can't read {rest!r}")
                m = re.fullmatch(r"Arc DE is (\d+) m long\. The rover can reach the shaded ground: sector ODE and triangle OEA\.", L[1])
                need(m is not None and g["arc_label"] == m.group(1) + " m", f"can't read {L[1]!r}")
                k = R(m.group(1)) ** 2 / 2
                gc_check_common(q, f"A = ({dec_text(k)}/θ²)(θ + sin θ) m²", {CR_SKILL + "segment-shaded#8": {f"A = {dec_text(k)}/θ m²"},
                                CR_T + "16": {f"A = ({dec_text(2 * k)}/θ²)(θ + sin θ) m²"}, CR_T + "15": {f"A = ({dec_text(k)}/θ²)(θ − sin θ) m²"}})
                cr_working(q)
                return None, None
        if u == "tether-angle":
            # The triangle OEA is isosceles with π − θ at O.
            label, tail, x = "angle DAE = ", " radians", (pi - (pi - th)) / 2
            W(CR_T + "20", th)
            W(CR_T + "21", pi - th)
        else:
            # Sector ODE and triangle OEA, whose angle at O is π − θ.
            label, tail, x = "A = ", " m²", rr**2 * th / 2 + rr**2 * sin(pi - th) / 2
            W("segment-shaded#8", rr**2 * th / 2)
            W("segment-shaded#0", rr**2 * (th + sin(mpmath.radians(th))) / 2)
            W(CR_T + "15", rr**2 * (th - sin(th)) / 2)
            W(CR_T + "16", rr**2 * (th + sin(th)))
    elif u in ("ratio-equation", "ratio-theta"):
        m = re.fullmatch(r"The shaded segment on chord RQ and the shaded triangle POR have areas in the ratio (\d+) : (\d+)\.", L[1])
        need(m is not None, f"can't read {L[1]!r}")
        a, b = int(m.group(1)), int(m.group(2))
        need((a, b) not in CR_RATIOS_OUT, "the bank's own ratio")
        g = cr_fig(q, "semi", angle_label="θ", r_label="r")
        k = sp.Rational(a + b, b)
        flip = sp.Rational(a + b, a)
        th = cr_root(cr_mp(k))
        need(abs((th - sin(th)) / sin(pi - th) - mpmath.mpf(a) / b) < mpmath.mpf(10) ** -25, "the root doesn't fit the ratio")
        cr_drawn(g, th)
        if u == "ratio-equation":
            kt = lambda v: dec_text(v) if v.q == 1 else f"({frac_text(v)})"
            gc_check_common(q, f"θ = {kt(k)} sin θ", {CR_SKILL + "segment-shaded#6": {f"θ = {kt(flip)} sin θ"},
                                                     CR_T + "22": {f"θ = {kt(sp.Rational(a, b))} sin θ"}})
            cr_working(q)
            return None, None
        label, x = "θ = ", th
        W("segment-shaded#6", cr_root(cr_mp(flip)))
    elif u == "ratio-radius":
        m = re.fullmatch(r"P has an area of ([\d.]+) cm², and area P : area Q = (\d+) : (\d+)\.", L[1])
        need(m is not None, f"can't read {L[1]!r}")
        area, a, b = cr_mp(cr_num(m.group(1))), int(m.group(2)), int(m.group(3))
        need((a, b) not in CR_RATIOS_OUT, "the bank's own ratio")
        g = cr_fig(q, "segment", r_label="r", angle_label="θ", circle=True, parts=True)
        th = cr_root(1 + mpmath.mpf(a) / b)
        cr_drawn(g, th)
        tri = area * b / a
        label, tail, x = "r = ", " cm", sqrt(2 * tri / sin(th))
        W("segment-shaded#3", sqrt(2 * area / th))
        W("segment-shaded#0", sqrt(2 * tri / sin(mpmath.radians(th))))
        th2 = cr_root(1 + mpmath.mpf(b) / a)
        W("segment-shaded#6", sqrt(2 * area * a / b / sin(th2)))
        W(CR_T + "18", 2 * tri / sin(th))
        W(CR_T + "16", sqrt(tri / sin(th)))
    elif u == "arch-area":
        m = re.fullmatch(r"The shaded end of a shelter is a rectangle with arc AB on top\. Each vertical side is ([\d.]+) cm high\.", L[0])
        m2 = re.fullmatch(r"Arc AB is part of a circle with centre O and radius ([\d.]+) cm, and angle AOB is ([\d.]+) radians\.", L[1])
        need(m and m2, "can't read the arch")
        h, rr, th = cr_mp(cr_num(m.group(1))), cr_mp(cr_num(m2.group(1))), cr_mp(cr_num(m2.group(2)))
        g = cr_fig(q, "arch", r_label=m2.group(1) + " cm", h_label=m.group(1) + " cm", angle_label=m2.group(2))
        cr_drawn(g, th)
        need(abs(mpmath.mpf(g["r"]) - rr) < 1e-6 and abs(mpmath.mpf(g["h"]) - h) < 1e-6, "the arch drawn is another arch")
        need(h > rr * cos(th / 2), "O is below the rectangle")
        wide = sqrt(2 * rr**2 * (1 - cos(th)))
        seg = rr**2 * (th - sin(th)) / 2
        label, tail, x = "A = ", " cm²", wide * h + seg
        W("segment-shaded#3", wide * h + rr**2 * th / 2)
        dg = mpmath.radians
        W(CR_ANY_SINE, 2 * rr * sin(dg(th / 2)) * h + rr**2 * (th - sin(dg(th))) / 2)
    elif u in ("ring-area", "ring-expression"):
        g = q["graph"]
        need(g is not None and g["kind"] == "sector" and g["inner"] > 0, "no curved strip drawn")
        m = re.fullmatch(r"A curved shield lies between two circles with centre O, as shaded\. The reflex angle at O is ([\d.]+) radians, the outer radius is ([\d.]+) cm and the inner radius is (r cm, where r < [\d.]+|[\d.]+ cm)\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        t0, big = cr_num(m.group(1)), cr_num(m.group(2))
        need(sp.pi < t0 < 2 * sp.pi, "the angle is not reflex")
        need(g["angle_label"] == m.group(1) and g["r_label"] == m.group(2) + " cm", "the figure's labels")
        cr_drawn(g, cr_mp(t0))
        if u == "ring-expression":
            need(m.group(3) == f"r cm, where r < {m.group(2)}", "r has no limit")
            need(g["inner_label"] == "r", "the figure's r")
            a, b = t0 * big**2 / 2, t0 / 2
            gc_check_common(q, f"A = {dec_text(a)} − {dec_text(b)}r² cm²", {CR_T + "17": {f"A = {dec_text(a)} − {dec_text(b)}r cm²"},
                                                                           CR_T + "16": {f"A = {dec_text(2 * a)} − {dec_text(2 * b)}r² cm²"}})
            cr_working(q)
            return None, None
        small = cr_num(m.group(3).removesuffix(" cm"))
        need(0 < small < big and abs(g["inner"] - float(small / big)) < 1e-6, "the inner circle drawn")
        tt, bb, ss = cr_mp(t0), cr_mp(big), cr_mp(small)
        label, tail, x = "A = ", " cm²", tt * (bb**2 - ss**2) / 2
        W("sector-area#2", (2 * pi - tt) * (bb**2 - ss**2) / 2)
        W(CR_T + "23", tt * bb**2 / 2)
        W(CR_T + "24", tt * (bb - ss)**2 / 2)
        W(CR_T + "16", tt * (bb**2 - ss**2))
    elif u in ("hatch-area", "hatch-height"):
        m = re.fullmatch(r"A bunker hatch is a rectangle (\d+)x m wide and h m high with a semicircle on top\. The semicircle's diameter is the top of the rectangle\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        k = int(m.group(1))
        need(k in (2, 4, 6), f"k = {k}")
        g = cr_fig(q, "hatch", w_label=f"{k}x m", h_label="h m")
        if u == "hatch-area":
            b = sp.Rational(k**2, 8)
            gc_check_common(q, f"A = {k}xh + {cr_pi_x2(b)} m²", {CR_SKILL + "segment-shaded#7": {f"A = {k}xh + {cr_pi_x2(4 * b)} m²"},
                                                                 CR_T + "25": {f"A = {k}xh + {cr_pi_x2(2 * b)} m²"}})
        else:
            m = re.fullmatch(r"The perimeter of the whole hatch is (\d+) m\.", L[1])
            need(m is not None, f"can't read {L[1]!r}")
            per = R(m.group(1))
            need(abs(2 * mpmath.mpf(g["rho"]) + 2 * mpmath.mpf(g["h"]) + pi * mpmath.mpf(g["rho"]) - cr_mp(per)) < 1e-6, "the hatch drawn doesn't have that perimeter")
            arc = "πx" if k == 2 else f"{k // 2}πx"
            gc_check_common(q, f"h = ½({per} − {k}x − {arc})", {CR_SKILL + "segment-shaded#4": {f"h = ½({per} − {2 * k}x − {arc})"},
                                                                CR_T + "25": {f"h = ½({per} − {k}x − {k}πx)"}, CR_T + "26": {f"h = {per} − {k}x − {arc}"}})
        cr_working(q)
        return None, None
    elif u in ("tangent-region", "tangent-expression"):
        m = re.fullmatch(r"AD and AE are tangents to a circle with centre O and radius ([\d.]+) cm, touching it at D and E\. Angle DAE is (\S+) radians?\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        need(L[1] == "The shaded region lies between the tangents and minor arc DE.", f"can't read {L[1]!r}")
        r = cr_num(m.group(1))
        g = cr_fig(q, "tangent", r_label=m.group(1) + " cm", angle_label=m.group(2))
        if u == "tangent-expression":
            need(m.group(2) == "2α" and r.q == 1, "the angle is 2α")
            a = dec_text(r**2)
            c = dec_text(r**2 / 2)
            gc_check_common(q, f"A = {a}/tan α − {c}(π − 2α) cm²", {CR_SKILL + "segment-shaded#5": {f"A = {a}/tan α − {a}α cm²"},
                                                                   CR_T + "27": {f"A = {a}/tan α cm²"}, CR_T + "16": {f"A = {a}/tan α − {a}(π − 2α) cm²"}})
            cr_working(q)
            return None, None
        th = cr_mp(cr_num(m.group(2)))
        cr_drawn(g, th)
        rr = cr_mp(r)
        # Two right triangles with legs r and r/tan(θ/2), less the sector with the angle left at O.
        kite = 2 * rr * (rr / tan(th / 2)) / 2
        label, tail, x = "A = ", " cm²", kite - rr**2 * (pi - th) / 2
        W("segment-shaded#5", kite - rr**2 * th / 2)
        W(CR_T + "27", kite)
    elif u == "cone-from-area":
        m = re.fullmatch(r"The sector in the diagram, with centre O and radius ([\d.]+) cm, has an area of ([\d.]+) cm²\. It is rolled up so that OA meets OB, to make a cone, and the arc becomes the rim\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        g = q["graph"]
        need(g is not None and g["kind"] == "sector" and g.get("cone") is True and g["r_label"] == m.group(1) + " cm", "the cone isn't drawn")
        rr, a = cr_mp(cr_num(m.group(1))), cr_mp(cr_num(m.group(2)))
        th = 2 * a / rr**2
        need(0 < th < 2 * pi, f"θ = {th}")
        cr_drawn(g, th)
        label, tail, x = "radius = ", " cm", rr * th / (2 * pi)
        W(CR_T + "30", 2 * a / rr)
        W(CR_T + "31", sqrt(a / pi))
    else:
        if rep != "diagram":
            need(L[1] == CR_LETTERS, "r and θ aren't said")
            L = L[:1] + L[2:]
        k = as_read({**q, "lines": L})
        un = k["unit"]
        if u == "arc-area-radius":
            l, a = k["l"], k["a"]
            need(l is not None and a is not None, "no arc or no area")
            r = 2 * a / l
            th = l / r
            need(0 < sp.N(th) < 2 * sp.pi, f"θ = {th}")
            as_figure(k, th)
            label, tail = "r = ", un
            if paper == 1:
                need(r.q == 1, f"r = {r}")
                gc_check_common(q, as_text(label, r, tail, 1), {CR_T + "16": {as_text(label, a / l, tail, 1)}})
                cr_working(q)
                return None, None
            x = cr_mp(r)
            W(CR_T + "16", cr_mp(a / l))
        else:
            p, a = k["p"], k["a"]
            need(p is not None, "no perimeter")
            if u == "theta-in-r":
                gc_check_common(q, f"θ = ({dec_text(p)} − 2r)/r", {CR_SKILL + "sector-two-conditions#0": {f"θ = {dec_text(p)}/r"},
                                                                  CR_T + "28": {f"θ = ({dec_text(p)} − r)/r"}, CR_T + "29": {f"θ = ({dec_text(p)} + 2r)/r"}}, steps=(2, 5))
                cr_working(q)
                return None, None
            need(a is not None, "no area")
            b = p / 2
            if u == "two-conditions-quadratic":
                gc_check_common(q, f"r² − {dec_text(b)}r + {dec_text(a)} = 0", {CR_SKILL + "sector-two-conditions#0": {f"r − {frac_text(2 * a / p)} = 0"}})
                cr_working(q)
                return None, None
            disc = b**2 - 4 * a
            need(disc > 0, "no two roots")
            roots = [(b - sp.sqrt(disc)) / 2, (b + sp.sqrt(disc)) / 2]
            if paper == 1:
                need(all(v.is_integer for v in roots), f"roots {roots}")
            else:
                need((p * 10).q == 1 and (a * 10).q == 1, "Paper 2 gives 1 d.p.")
            thetas = [(p - 2 * v) / v for v in roots]
            good = [sp.N(t) > 0 and sp.N(t) < sp.N(2 * sp.pi) for t in thetas]
            no_ref, big_ref, one_ref = (CR_SKILL + f"sector-two-conditions#{i}" for i in range(3))

            def T(lb, v, tl):
                return as_text(lb, sp.nsimplify(v) if paper == 1 else v, tl, paper)

            if u == "two-conditions-both":
                need(all(good), "a root is no sector")
                as_figure(k, thetas[1])
                if paper == 1:
                    want = f"r = {dec_text(roots[0])}{un} or {dec_text(roots[1])}{un}"
                else:
                    want = f"r = {rg_s(sp.N(roots[0], 40))}{un} or {rg_s(sp.N(roots[1], 40))}{un}"
                    need(asked.endswith(" Give your answers to 3 significant figures."), f"asked {asked!r}")
                gc_check_common(q, want, {one_ref: {T("r = ", roots[0], un), T("r = ", roots[1], un)}})
                cr_working(q)
                return None, None
            need(good == [False, True], "not exactly the larger root is a sector")
            as_figure(k, thetas[1])
            if u == "two-conditions-r":
                label, tail, v, slips = "r = ", un, roots[1], {big_ref: roots[0], no_ref: 2 * a / p}
            else:
                label, tail, v, slips = "θ = ", "", thetas[1], {big_ref: thetas[0], no_ref: p**2 / (2 * a)}
            wr = {ref: {T(label, s, tail)} for ref, s in slips.items()}
            if paper == 1:
                gc_check_common(q, T(label, v, tail), wr)
                cr_working(q)
                return None, None
            x = mpmath.mpf(str(sp.N(v, 45)))
    n = nu_f(x)
    need(asked.endswith(" Give your answer to 3 significant figures."), f"asked {asked!r}")
    need(as_clear(n), f"{n} is on a rounding edge")
    t2 = bn_trap(label, n)
    gc_check_common(q, label + rg_s(n) + tail, wr, t2 + tail if t2 else None)
    cr_working(q)
    return None, None


# ── bearings-elevation (t3-bearings-elevation, FAL-726) ──────
# Reads the distances, bearings and angles back from the lines and works each answer out again
# with mpmath at 40 digits. A sketch is held to the story: each length to one scale, each bearing
# and angle to the points drawn.

BE_SKILL = "SL3.3."
BE_EDGE = sp.Rational(29, 1000)         # the engine's is 0.03


def be_c(d):
    return mpmath.cos(mpmath.radians(d))


def be_s(d):
    return mpmath.sin(mpmath.radians(d))


def be_t(d):
    return mpmath.tan(mpmath.radians(d))


def be_mp(x):
    x = sp.Rational(x)
    return mpmath.mpf(x.p) / x.q


def be_text(label, x, tail=""):
    return label + rg_s(nu_f(x)) + tail


def be_bearing(b):
    return f"{int(b) % 360:03d}°"


def be_angle(p, a, b):
    """The angle at p between the directions to a and b, in degrees."""
    u = (a[0] - p[0], a[1] - p[1])
    v = (b[0] - p[0], b[1] - p[1])
    dot = u[0] * v[0] + u[1] * v[1]
    return mpmath.degrees(mpmath.acos(dot / (mpmath.hypot(*u) * mpmath.hypot(*v))))


def be_clear(x):
    v = abs(num(nu_f(x)))
    if v == 0:
        return True
    e = sp.floor(sp.log(v, 10))
    scaled = v / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= BE_EDGE


def be_figure(q, to_scale=True):
    """Every label on the sketch says what the points drawn say."""
    g = q["graph"]
    need(g is not None and g["kind"] == "sketch", "no sketch")
    pts = {n: tuple(mpmath.mpf(c) for c in p) for n, p in g["pts"].items()}
    scale = None
    for ln in g["lines"]:
        m = re.fullmatch(r"([\d.]+) (km|m)", ln["label"])
        if m and to_scale:
            d = mpmath.hypot(pts[ln["a"]][0] - pts[ln["b"]][0], pts[ln["a"]][1] - pts[ln["b"]][1])
            ratio = d / be_mp(R(m.group(1)))
            scale = scale if scale is not None else ratio
            need(abs(ratio / scale - 1) < mpmath.mpf(10) ** -6, f"{ln['a']}{ln['b']} is not to scale")
    for a in g["arcs"]:
        if a["label"] == "?" or not to_scale:
            continue
        p, to = pts[a["at"]], pts[a["to"]]
        if a["from"] == "N":
            b = mpmath.degrees(mpmath.atan2(to[0] - p[0], to[1] - p[1])) % 360
            need(a["at"] in g["north"], f"no north line at {a['at']}")
            need(abs(b - int(a["label"].rstrip("°"))) < mpmath.mpf("1e-5"), f"the bearing {a['label']} isn't drawn ({b})")
        elif a["label"].endswith("°"):
            ang = be_angle(p, pts[a["from"]], to)
            need(abs(ang - be_mp(R(a["label"].rstrip("°")))) < mpmath.mpf("1e-5"), f"the angle {a['label']} isn't drawn ({ang})")
    return pts


def be_journey(L):
    m1 = re.fullmatch(r".+ leaves camp A and travels ([\d.]+) km on a bearing of (\d{3})° to a well at B\.", L[0])
    m2 = re.fullmatch(r"It then travels ([\d.]+) km on a bearing of (\d{3})° to a depot at C\.", L[1])
    need(m1 and m2, f"can't read {L[:2]!r}")
    return R(m1.group(1)), int(m1.group(2)), R(m2.group(1)), int(m2.group(2))


def be_angle_read(text):
    """An angle of elevation or depression in radians, and its size."""
    m = re.search(r"(?:elevation|depression)[^.]*? is ([\d.]+)(°| radians)", text)
    need(m is not None, f"can't read an angle in {text!r}")
    v = be_mp(R(m.group(1)))
    return (mpmath.radians(v), True) if m.group(2) == "°" else (v, False)


def check_bearings(q):
    with mpmath.workdps(40):
        return be_check(q)


def be_check(q):
    u, L, rep, asked = q["view"]["unknown"], q["lines"], q["view"]["rep"], q["asked"]
    need(q["paper"] == 2, "these are Paper 2")
    text = " ".join(L)
    wr = {}
    pi = mpmath.pi
    tan, sin, cos = mpmath.tan, mpmath.sin, mpmath.cos
    label, tail, x, want = None, "", None, None

    def W(ref, val):
        wr.setdefault(BE_SKILL + ref, set()).add(be_text(label, val, tail))

    def T(i, val):
        """One of the type's own misconceptions, t3-bearings-elevation#i (FAL-815)."""
        if val > 0:
            wr.setdefault(f"t3-bearings-elevation#{i}", set()).add(be_text(label, val, tail))

    if rep == "words":
        need(q["graph"] is None, "words have no sketch")
    scaled = True
    if u == "back-bearing":
        m = re.fullmatch(r"From a camp at A, a tower at B is on a bearing of (\d{3})°\.", L[0])
        need(m is not None and asked == "Find the bearing of A from B.", f"{L[0]!r}")
        b = int(m.group(1))
        want = "bearing = " + be_bearing(b + 180)
        wr[BE_SKILL + "bearings#1"] = {"bearing = " + be_bearing(b)}
        wr[BE_SKILL + "bearings#0"] = {"bearing = " + be_bearing(360 - b)}
    elif u == "angle-from-bearing":
        m = re.search(r"due east.*on a bearing of (\d{3})°\. Angle ABC is (\d+)°\.", text)
        need(m is not None, f"{text!r}")
        b, phi = int(m.group(1)), int(m.group(2))
        want = f"angle ACB = {180 - (90 - b) - phi}°"
        wr[BE_SKILL + "bearings#2"] = {f"angle ACB = {180 - b - phi}°"}
    elif u in ("two-leg-distance", "two-leg-bearing", "return-bearing"):
        d1, b1, d2, b2 = be_journey(L)
        need((d1 * 10).q == 1 and (d2 * 10).q == 1, "distances to 1 d.p.")
        d1m, d2m = be_mp(d1), be_mp(d2)
        e = d1m * be_s(b1) + d2m * be_s(b2)
        n = d1m * be_c(b1) + d2m * be_c(b2)
        if u == "two-leg-distance":
            label, tail, x = "distance = ", " km", mpmath.hypot(e, n)
            t = abs(b2 - b1)
            t = 360 - t if t > 180 else t
            need(30 <= t <= 150, f"the turn is {t}°")
            # The same distance from the cosine rule, with the angle inside.
            again = mpmath.sqrt(d1m**2 + d2m**2 - 2 * d1m * d2m * be_c(180 - t))
            need(abs(again - x) < mpmath.mpf(10) ** -25, "the cosine rule disagrees with the components")
            W("bearings#2", mpmath.sqrt(d1m**2 + d2m**2 - 2 * d1m * d2m * be_c(t)))
            T(9, d1m + d2m)  # the legs added
            W("multi-triangle#1", mpmath.hypot(d1m, d2m))  # Pythagoras with no right angle
        else:
            there = mpmath.degrees(mpmath.atan2(e, n)) % 360
            label, tail = "bearing = ", "°"
            if u == "two-leg-bearing":
                x = there
                W("bearings#1", (there + 180) % 360)
                W("bearings#0", 360 - there)
            else:
                x = (there + 180) % 360
                W("bearings#1", there)
                W("bearings#0", 360 - x)  # measured anticlockwise
            need(100 <= x < 360, f"a bearing of {x} isn't three figures at 3 s.f.")
    elif u == "due-east-distance":
        m = re.search(r"An outpost B is ([\d.]+) km due east of a camp at A\. A signal fire at C is ([\d.]+) km from A, on a bearing of (\d{3})°\.", text)
        need(m is not None, f"{text!r}")
        ab, ac, b = be_mp(R(m.group(1))), be_mp(R(m.group(2))), int(m.group(3))
        label, tail = "BC = ", " km"
        x = mpmath.sqrt(ab**2 + ac**2 - 2 * ab * ac * be_c(90 - b))
        W("bearings#2", mpmath.sqrt(ab**2 + ac**2 - 2 * ab * ac * be_c(b)))
        W("multi-triangle#1", mpmath.hypot(ab, ac))  # Pythagoras with no right angle
    elif u == "sine-rule-distance":
        m = re.search(r"An outpost B is ([\d.]+) km due east of a camp at A\. From A, a signal fire at C is on a bearing of (\d{3})°\. Angle ABC is (\d+)°\.", text)
        wh = re.fullmatch(r"Find the distance (AC|BC)\. Give your answer to 3 significant figures\.", asked)
        need(m and wh, f"{text!r} {asked!r}")
        ab, b, phi = be_mp(R(m.group(1))), int(m.group(2)), int(m.group(3))
        at_a = 90 - b
        c = 180 - at_a - phi
        opp = phi if wh.group(1) == "AC" else at_a
        label, tail = wh.group(1) + " = ", " km"
        x = ab * be_s(opp) / be_s(c)
        W("bearings#2", ab * be_s(phi if wh.group(1) == "AC" else b) / be_s(180 - b - phi))
        T(10, ab * be_s(at_a if wh.group(1) == "AC" else phi) / be_s(c))  # the other side's angle on top
    elif u == "due-west-side":
        m = re.search(r"AC = ([\d.]+) m, the bearing of B from A is (\d{3})° and angle BAC is (\d+)°\.", text)
        need(m is not None, f"{text!r}")
        ac, b, phi = be_mp(R(m.group(1))), int(m.group(2)), int(m.group(3))
        # From coordinates, not from the angle chase: A at the origin, BC on a line due west.
        c = (ac * be_s(b + phi), ac * be_c(b + phi))
        ab = c[1] / be_c(b)
        bpt = (ab * be_s(b), ab * be_c(b))
        need(abs(bpt[1] - c[1]) < mpmath.mpf(10) ** -25 and c[0] < bpt[0] and c[1] < 0, "C is not due west of B")
        label, tail, x = "BC = ", " m", bpt[0] - c[0]
        abc = b - 90
        W("bearings#2", ac * be_s(phi) / be_s(b))  # the bearing for angle ABC
        T(10, ac * be_s(phi) / be_s(180 - phi - abc))  # AC paired with angle ACB
    elif u == "height-from-elevation":
        m = re.search(r"([\d.]+) m from the foot", text)
        t, deg = be_angle_read(text)
        d = be_mp(R(m.group(1)))
        label, tail, x = "height = ", " m", d * tan(t)
        T(11, d * sin(t))
        T(11, d * cos(t))
        T(12, d / tan(t))
        e_ = be_mp(R(re.search(r"(?:elevation|depression)[^.]*? is ([\d.]+)", text).group(1)))
        T(13, d * (be_t(e_) if not deg else tan(e_)))  # radians read as degrees, or degrees as radians
    elif u == "distance-from-depression":
        m = re.search(r"From the top T of a .+? ([\d.]+) m high", text)
        t, deg = be_angle_read(text)
        h = be_mp(R(m.group(1)))
        label, tail, x = "distance = ", " m", h / tan(t)
        W("elevation-depression#1", h * tan(t))
        T(11, h * sin(t))
        T(11, h / cos(t))
        T(14, h / sin(t))  # the line of sight
    elif u == "angle-of-depression":
        m = re.search(r"From the top T of a .+? ([\d.]+) m high", text)
        m2 = re.search(r"P is ([\d.]+) m from the foot", text)
        h, d = be_mp(R(m.group(1))), be_mp(R(m2.group(1)))
        label, tail, x = "angle = ", "°", mpmath.degrees(mpmath.atan(h / d))
        W("elevation-depression#0", mpmath.degrees(mpmath.atan(d / h)))
    elif u == "height-with-eye-level":
        m = re.search(r"eyes are ([\d.]+) m above the level ground stands ([\d.]+) m from", text)
        t, deg = be_angle_read(text)
        eye, d = be_mp(R(m.group(1))), be_mp(R(m.group(2)))
        label, tail, x = "height = ", " m", eye + d * tan(t)
        W("elevation-depression#2", d * tan(t))
        T(11, d * sin(t) + eye)
        T(15, d * tan(t) - eye)
        T(12, d / tan(t) + eye)
    elif u == "chain-below-hook":
        m = re.search(r"([\d.]+) m from the foot of a crane", text)
        m2 = re.search(r"A guard ([\d.]+) m tall stands under it, and the hook on the chain is ([\d.]+) m above", text)
        t, deg = be_angle_read(text)
        d, eye, gp = be_mp(R(m.group(1))), be_mp(R(m2.group(1))), be_mp(R(m2.group(2)))
        label, tail, x = "length = ", " m", d * tan(t) - eye - gp
        need(x > 0, "the chain has no length")
        W("elevation-depression#2", d * tan(t) - gp)
        T(16, d * tan(t) - eye)
        T(17, d * tan(t))
        T(11, d * sin(t) - eye - gp)
    elif u == "time-from-depression":
        m = re.search(r"From the top of a .+? ([\d.]+) m high", text)
        m2 = re.search(r"at (\d+) km/h", text)
        t, deg = be_angle_read(text)
        h, v = be_mp(R(m.group(1))), int(m2.group(1))
        label, tail, x = "time = ", " minutes", h / tan(t) / 1000 / v * 60
        W("elevation-depression#1", h * tan(t) / 1000 / v * 60)
        T(18, h / tan(t) / 1000 / v)  # still in hours
        scaled = False
    elif u == "route-time":
        m = re.search(r"PB = ([\d.]+) km\. A camp at A is ([\d.]+) km from P", text)
        m2 = re.search(r"at (\d+) km/h, and a truck drives along the road at (\d+) km/h", text)
        b, a = be_mp(R(m.group(1))), be_mp(R(m.group(2)))
        v1, v2 = int(m2.group(1)), int(m2.group(2))
        label, tail = "time = ", " hours"
        x = mpmath.hypot(a, b) / v1 if "straight across" in asked else a / v1 + b / v2
        if "straight across" in asked:
            T(19, (a + b) / v1)  # both legs
            T(21, mpmath.hypot(a, b) / v2)  # the truck's speed
        else:
            T(20, (a + b) / v1)
            T(20, (a + b) / v2)
            T(21, a / v2 + b / v1)  # the speeds swapped
    elif u == "shared-side":
        m = re.search(r"AB = ([\d.]+) km, AD = ([\d.]+) km and angle BAD = 90°\. BC = ([\d.]+) km and angle DBC = (\d+)°", text)
        ab, ad, bc, phi = [be_mp(R(m.group(i))) for i in (1, 2, 3, 4)]
        bd = mpmath.hypot(ab, ad)
        label, tail, x = "CD = ", " km", mpmath.sqrt(bd**2 + bc**2 - 2 * bd * bc * mpmath.cos(mpmath.radians(phi)))
        rough = be_mp(R(sig3(nu_f(bd), 2)))
        W("multi-triangle#0", mpmath.sqrt(rough**2 + bc**2 - 2 * rough * bc * mpmath.cos(mpmath.radians(phi))))
        W("multi-triangle#1", mpmath.hypot(bd, bc))
    elif u == "quadrilateral-area":
        m = re.search(r"AB = ([\d.]+) km, AD = ([\d.]+) km and angle BAD = (\d+)°\. BC = ([\d.]+) km and angle DBC = (\d+)°", text)
        ab, ad, a0, bc, phi = [be_mp(R(m.group(i))) for i in range(1, 6)]
        bd = mpmath.sqrt(ab**2 + ad**2 - 2 * ab * ad * mpmath.cos(mpmath.radians(a0)))
        label, tail = "area = ", " km²"
        x = ab * ad * mpmath.sin(mpmath.radians(a0)) / 2 + bd * bc * mpmath.sin(mpmath.radians(phi)) / 2
        T(22, ab * ad * mpmath.sin(mpmath.radians(a0)) / 2)
        T(22, bd * bc * mpmath.sin(mpmath.radians(phi)) / 2)
        T(23, 2 * x)  # not halved
    elif u == "perpendicular-split":
        m = re.search(r"to a depot B, ([\d.]+) km away\. A well at C is ([\d.]+) km from A, and angle BAC is (\d+)°\.", text)
        ab, ac, phi = be_mp(R(m.group(1))), be_mp(R(m.group(2))), int(m.group(3))
        label, tail = "BC = ", " km"
        x = mpmath.sqrt(ab**2 + ac**2 - 2 * ab * ac * be_c(phi))
        W("multi-triangle#1", mpmath.hypot(ab, ac))
        need(phi != 90, "the angle is a right angle")
    elif u == "rule-to-use":
        sas = re.fullmatch(r"In triangle PQR, PQ = \d+ km, PR = \d+ km and angle QPR = \d+°\.", L[0])
        sss = re.fullmatch(r"In triangle PQR, PQ = \d+ km, PR = \d+ km and QR = \d+ km\.", L[0])
        aas = re.fullmatch(r"In triangle PQR, PQ = \d+ km, angle QPR = \d+° and angle PQR = \d+°\.", L[0])
        rt = re.fullmatch(r"In triangle PQR, angle PQR = 90°, PQ = \d+ km and angle QPR = \d+°\.", L[0])
        need(sum(1 for z in (sas, sss, aas, rt) if z) == 1, f"can't read {L[0]!r}")
        want = "The sine rule" if aas else ("A right-angle ratio such as tan" if rt else "The cosine rule")
        if sas or sss:
            wr[BE_SKILL + "multi-triangle#2"] = {"The sine rule"}
        if not rt:
            wr[BE_SKILL + "multi-triangle#1"] = {"A right-angle ratio such as tan"}  # no right angle to use it in
    else:
        raise Fail(f"no check for {u}")
    trap = None
    if x is not None:
        need(x > 0 and be_clear(x), f"{x} is on a rounding edge")
        need(asked.endswith(" Give your answer to 3 significant figures."), f"asked {asked!r}")
        want = be_text(label, x, tail)
        t2 = bn_trap(label, nu_f(x))
        trap = t2 + tail if t2 else None
    gc_check_common(q, want, wr, trap)
    if rep == "diagram":
        be_figure(q, scaled)
    for sol in q["solutions"]:
        tri_working(q, sol)
    return None, None


# ── right-triangle (t3-right-angle-trig, FAL-739) ────────────
# Reads the sides, angles and gradients back from the lines and works each answer out again, with
# exact surds where the question is exact and mpmath at 40 digits where it isn't. A figure is held
# to the story, and an angle of elevation or depression to the horizontal at the eye.

RT_EITHER = ("ratio-from-sides", "ratio-needs-pythagoras", "ratio-in-letters", "side-in-letters", "side-special", "angle-special")
RT_FIGURE = ("side-in-letters", "side-special", "angle-special", "edge-from-span", "upper-edge", "height-from-angle",
             "elevation-after-walk", "equal-elevations", "cone-from-eye-level", "depression-sight-line",
             "depression-from-sight-line", "depression-two-points", "name-the-angle")
RT_A = "SL3.2.right-angle#"
RT_R = "SL3.2.right-ratio#"
RT_S = "SL3.2.right-side#"
RT_E = "SL3.3.elevation-depression#"
RT_T = "t3-right-angle-trig#"
# The slips FAL-815 named: the right sides with the wrong one of sin, cos and tan; the two given
# legs over each other with no hypotenuse; and dividing by the ratio when the side wanted is on top.
RT_WRONG_FN, RT_NO_HYP, RT_DIVIDE = RT_T + "29", RT_T + "30", RT_T + "31"
RT_NUM = r"(\d+(?:\.\d+)?)"
RT_AWAY = 5                             # the engine's: an acute angle this far from 45°


def rt_exact(v):
    """A fraction or a surd as the game writes it: 5/13, 3√13/13, 5√3, √2/2."""
    v = sp.nsimplify(v)
    if v.is_Rational:
        return str(v.p) if v.q == 1 else f"{v.p}/{v.q}"
    c, rd = v.as_coeff_Mul()
    root = rd**2
    need(c.is_Rational and root.is_Integer, f"{v} is not one surd")
    c = sp.Rational(c)
    return ("" if c.p == 1 else str(c.p)) + f"√{root}" + ("" if c.q == 1 else f"/{c.q}")


def rt_value(t):
    """5, 3/4, √2, 3√5 as the game writes a side."""
    m = re.fullmatch(r"(\d*)√(\d+)", t)
    if m:
        return (int(m.group(1)) if m.group(1) else 1) * sp.sqrt(int(m.group(2)))
    return sp.Rational(t)


def rt_triangle(L):
    """The right angle R, the vertex T with θ and the third vertex O, and the sides by name."""
    m = re.fullmatch(r"Triangle ([A-Z]{3}) has a right angle at ([A-Z])\.", L[0])
    m2 = re.fullmatch(r"θ is angle ([A-Z])([A-Z])([A-Z])\.", L[2])
    need(m and m2, f"can't read {L!r}")
    need(m2.group(1) == m.group(2) and sorted(m2.groups()) == sorted(m.group(1)), "θ is not an angle of the triangle at a vertex with no right angle")
    R, T, O = m2.groups()
    sides = {}
    for a, val in re.findall(r"([A-Z]{2}) = ([^ ,.]+)", L[1]):
        sides[frozenset(a)] = val
    return T, R, O, sides


def rt_pick(fn, o, a, h):
    return {"sin": (o, h), "cos": (a, h), "tan": (o, a)}[fn]


def rt_mpf(v):
    return mpmath.mpf(str(sp.N(v, 45)))


def rt_e(deg):
    need(deg == int(deg) and 8 <= deg <= 75 and abs(deg - 45) >= RT_AWAY, f"the angle {deg} is out of limits")
    return mpmath.radians(deg)


def rt_mode(fn, deg):
    """fn of an angle in degrees, on a calculator in radians."""
    return {"sin": mpmath.sin, "cos": mpmath.cos, "tan": mpmath.tan}[fn](deg)


def rt_ratio_wrongs(fn, o, a, h, longer):
    """Tag -> (top, bottom), for the three slips of a written ratio."""
    top, bot = rt_pick(fn, o, a, h)
    out = {RT_R + "1": (bot, top)}
    if fn != "tan":
        other = a if fn == "sin" else o
        out[RT_R + "0"] = (other, h)
        if longer:
            out[RT_R + "2"] = (top, other)
    return out


def rt_gradient(text):
    m = re.search(r"gradient of (\d+)/(\d+)", text)
    need(m, f"can't read a gradient in {text!r}")
    p, q_ = int(m.group(1)), int(m.group(2))
    need(sp.gcd(p, q_) == 1, "the gradient is not in lowest terms")
    deg = mpmath.degrees(mpmath.atan(mpmath.mpf(p) / q_))
    need(10 < deg < 60 and abs(deg - 45) >= RT_AWAY, "the gradient is out of limits")
    return p, q_


def rt_arcs_at_eye(q, u):
    """An angle of elevation or depression runs from the horizontal through its vertex."""
    pts = {n: tuple(mpmath.mpf(c) for c in p) for n, p in q["graph"]["pts"].items()}
    for a in q["graph"]["arcs"] if u in RT_FIGURE[3:] else ():
        if a["label"] == "θ" or u == "equal-elevations" and a["label"].endswith("°"):
            continue
        need(abs(pts[a["from"]][1] - pts[a["at"]][1]) < mpmath.mpf("1e-9"), f"the angle at {a['at']} is not measured from the horizontal")
        if a["label"] != "?" and not a["label"].endswith("°"):
            need(abs(be_angle(pts[a["at"]], pts[a["from"]], pts[a["to"]]) - mpmath.degrees(be_mp(R(a["label"])))) < mpmath.mpf("1e-5"), f"the angle {a['label']} isn't drawn")
    for n in q["graph"].get("right", []):
        near = [ln["a"] if ln["b"] == n else ln["b"] for ln in q["graph"]["lines"] if n in (ln["a"], ln["b"])]
        need(abs(be_angle(pts[n], pts[near[0]], pts[near[1]]) - 90) < mpmath.mpf("1e-5"), f"no right angle at {n}")


def check_right_triangle(q):
    with mpmath.workdps(40):
        return rt_check(q)


def rt_check(q):
    u, L, rep, asked, paper = q["view"]["unknown"], q["lines"], q["view"]["rep"], q["asked"], q["paper"]
    need(paper == 2 or u in RT_EITHER, "this needs a calculator: Paper 2")
    need(rep == "diagram" or u not in RT_FIGURE, "this unknown needs its figure")
    if rep == "words":
        need(q["graph"] is None, "words have no sketch")
    text = " ".join(L)
    wr = {}
    pi = mpmath.pi
    tan, sin, cos, atan, asin, acos = mpmath.tan, mpmath.sin, mpmath.cos, mpmath.atan, mpmath.asin, mpmath.acos
    sqrt, deg = mpmath.sqrt, mpmath.degrees
    label, tail, x, want = None, "", None, None

    def W(ref, val):
        if val > 0:
            need(be_clear(val), f"the slip {ref} is on a rounding edge")
            wr.setdefault(ref, set()).add(be_text(label, val, tail))

    def n(pattern, group=1):
        m = re.search(pattern, text)
        need(m, f"can't read {pattern!r} in {text!r}")
        return be_mp(R(m.group(group)))

    if u == "ratio-from-sides":
        T, Rt, O, _ = rt_triangle(L)
        o = R(re.search(rf"{sorted(Rt + O)[0]}{sorted(Rt + O)[1]} = (\d+) m", text).group(1))
        a = R(re.search(rf"{sorted(T + Rt)[0]}{sorted(T + Rt)[1]} = (\d+) m", text).group(1))
        h = R(re.search(rf"{sorted(T + O)[0]}{sorted(T + O)[1]} = (\d+) m", text).group(1))
        need(o**2 + a**2 == h**2 and h <= 60, "the sides are not a right-angled triangle within the limits")
        fn = re.search(r"value of (sin|cos|tan) θ as a fraction", asked).group(1)
        top, bot = rt_pick(fn, o, a, h)
        want = f"{fn} θ = {rt_exact(top / bot)}"
        mine, other = (o, a) if fn == "sin" else (a, o)
        for ref, (p_, q_) in rt_ratio_wrongs(fn, o, a, h, fn != "tan" and mine < other).items():
            wr[ref] = {f"{fn} θ = {rt_exact(p_ / q_)}"}
        wr[RT_WRONG_FN] = {f"{fn} θ = {rt_exact(p_ / q_)}" for p_, q_ in ((o, h), (a, h), (o, a)) if (p_, q_) != (top, bot)}
    elif u == "ratio-needs-pythagoras":
        T, Rt, O, _ = rt_triangle(L)
        o = R(re.search(rf"{sorted(Rt + O)[0]}{sorted(Rt + O)[1]} = (\d+) m", text).group(1))
        a = R(re.search(rf"{sorted(T + Rt)[0]}{sorted(T + Rt)[1]} = (\d+) m", text).group(1))
        h = sp.sqrt(o**2 + a**2)
        need(not h.is_Rational, "the hypotenuse is whole")
        fn = re.search(r"exact value of (sin|cos) θ\.", asked).group(1)
        top, bot = rt_pick(fn, o, a, h)
        want = f"{fn} θ = {rt_exact(top / bot)}"
        mine, other = (o, a) if fn == "sin" else (a, o)
        for ref, (p_, q_) in rt_ratio_wrongs(fn, o, a, h, mine < other).items():
            wr[ref] = {f"{fn} θ = {rt_exact(p_ / q_)}"}
        # The ratio's own leg over the other given leg, with no hypotenuse found.
        wr[RT_NO_HYP] = {f"{fn} θ = {rt_exact(mine / other)}"}
    elif u == "ratio-in-letters":
        T, Rt, O, sd = rt_triangle(L)
        o, a, h = sd[frozenset(Rt + O)], sd[frozenset(T + Rt)], sd[frozenset(T + O)]
        need(sorted((o, a, h)) == ["p", "q", "r"], "the sides are not p, q and r")
        fn = re.search(r"Write down (sin|cos|tan) θ in terms", asked).group(1)
        top, bot = rt_pick(fn, o, a, h)
        want = f"{fn} θ = {top}/{bot}"
        longer = False
        if rep == "diagram" and fn != "tan":
            pts = {k: tuple(mpmath.mpf(c) for c in p) for k, p in q["graph"]["pts"].items()}
            dist_o = mpmath.hypot(pts[Rt][0] - pts[O][0], pts[Rt][1] - pts[O][1])
            dist_a = mpmath.hypot(pts[Rt][0] - pts[T][0], pts[Rt][1] - pts[T][1])
            longer = dist_a > dist_o if fn == "sin" else dist_o > dist_a
        for ref, (p_, q_) in rt_ratio_wrongs(fn, o, a, h, longer).items():
            wr[ref] = {f"{fn} θ = {p_}/{q_}"}
        wr[RT_WRONG_FN] = {f"{fn} θ = {p_}/{q_}" for p_, q_ in ((o, h), (a, h), (o, a)) if (p_, q_) != (top, bot)}
    elif u == "side-in-letters":
        m = re.fullmatch(r"Write down an expression for (PS|RS) in terms of r and θ\.", asked)
        need(m and "Angle PRS = θ." in text and "radius r" in text, f"can't read {asked!r}")
        fn = "sin" if m.group(1) == "PS" else "cos"
        other = "cos" if fn == "sin" else "sin"
        head = m.group(1) + " = "
        want = f"{head}2r {fn} θ"
        wr[RT_T + "25"] = {f"{head}r {fn} θ"}
        wr[RT_R + "0"] = {f"{head}2r {other} θ"}
        wr[RT_S + "1"] = {f"{head}2r tan θ"}
        if q["graph"] is not None:
            pts = {k: tuple(mpmath.mpf(c) for c in p) for k, p in q["graph"]["pts"].items()}
            th = mpmath.radians(be_angle(pts["R"], pts["S"], pts["P"]))
            r_ = mpmath.hypot(*pts["R"])
            for k in "PQRS":
                need(abs(mpmath.hypot(*pts[k]) - r_) < mpmath.mpf("1e-9"), "a corner is off the circle")
            need(abs(mpmath.hypot(pts["P"][0] - pts["S"][0], pts["P"][1] - pts["S"][1]) - 2 * r_ * sin(th)) < mpmath.mpf("1e-9"), "PS is not 2r sin θ on the figure")
            need(abs(mpmath.hypot(pts["R"][0] - pts["S"][0], pts["R"][1] - pts["S"][1]) - 2 * r_ * cos(th)) < mpmath.mpf("1e-9"), "RS is not 2r cos θ on the figure")
    elif u == "side-from-angle":
        e = rt_e(int(n(r"angle of (\d+)° with the ground")))
        dg = int(n(r"angle of (\d+)° with the ground"))
        m = re.fullmatch(r"Find ([A-Z]{2}), the (height|distance) .+ Give your answer to 3 significant figures\.", asked)
        need(m, f"can't read {asked!r}")
        tail = " m"
        label = m.group(1) + " = "
        if "cable" in text:
            fn, d = "tan", n(r", " + RT_NUM + r" m from [A-Z]\.")
        else:
            fn, d = ("sin" if m.group(2) == "height" else "cos"), n(r"is " + RT_NUM + r" m long")
        x = d * {"sin": sin, "cos": cos, "tan": tan}[fn](e)
        W(RT_T + "7", d * rt_mode(fn, dg))
        if fn == "sin":
            W(RT_S + "1", d * tan(e))
        # Dividing by the ratio; sin and cos swapped; the right sides in the wrong function.
        W(RT_DIVIDE, d / {"sin": sin, "cos": cos, "tan": tan}[fn](e))
        if fn == "sin":
            W(RT_R + "0", d * cos(e))
        elif fn == "cos":
            W(RT_R + "0", d * sin(e))
            W(RT_WRONG_FN, d * tan(e))
        else:
            W(RT_WRONG_FN, d * cos(e))
            W(RT_WRONG_FN, d * sin(e))
    elif u == "side-under-ratio":
        dg = int(n(r"at an angle of (\d+)°\."))
        e = rt_e(dg)
        m = re.fullmatch(r"Find ([A-Z]{2}), the length of the .+ Give your answer to 3 significant figures\.", asked)
        need(m, f"can't read {asked!r}")
        tail, label = " m", m.group(1) + " = "
        sn_ = re.search(r"Its top [A-Z] is " + RT_NUM + r" m above", text)
        fn = "sin" if sn_ else "cos"
        d = be_mp(R(sn_.group(1))) if sn_ else n(r"[A-Z]{2} = " + RT_NUM + r" m\.")
        f = {"sin": sin, "cos": cos}[fn]
        x = d / f(e)
        W(RT_S + "0", d * f(e))
        W(RT_T + "7", d / rt_mode(fn, dg))
        if fn == "sin":
            W(RT_S + "1", d / tan(e))
        # sin and cos swapped.
        W(RT_R + "0", d / (cos(e) if fn == "sin" else sin(e)))
    elif u == "side-either-angle":
        dg = int(n(r"angle of (\d+)° with the ground"))
        e = rt_e(dg)
        d = n(r"its top [A-Z] " + RT_NUM + r" m high")
        m = re.match(r"Find ([A-Z]{2}), ", asked)
        tail, label = " m", m.group(1) + " = "
        x = d / tan(e)
        W(RT_S + "0", d * tan(e))
        W(RT_T + "7", d / rt_mode("tan", dg))
        # The opposite and the adjacent put into sin or cos instead of tan.
        W(RT_WRONG_FN, d / sin(e))
        W(RT_WRONG_FN, d / cos(e))
    elif u == "chord-length":
        r_, d = n(r"within (\d+) km"), n(r"passes (\d+) km from S")
        need(3 * r_ <= 10 * d <= 8 * r_, "the road is too near or too far")
        tail, label = " km", "AB = "
        x = 2 * sqrt(r_**2 - d**2)
        W(RT_S + "3", x / 2)
        W(RT_S + "1", 2 * sqrt(r_**2 + d**2))
        if rep == "diagram":
            pts = {k: tuple(mpmath.mpf(c) for c in p) for k, p in q["graph"]["pts"].items()}
            for k in "AB":
                need(abs(mpmath.hypot(*pts[k]) - r_) < mpmath.mpf("1e-9"), "the road's ends are off the circle")
            need(q["graph"]["circles"] == [{"at": "S", "through": "A"}], "the range isn't drawn")
    elif u == "side-special":
        m = re.fullmatch(r"Triangle [A-Z]{3} has a right angle at ([A-Z]), and angle ([A-Z])([A-Z])([A-Z]) = (\d+)°\.", L[0])
        m2 = re.fullmatch(r"([A-Z]{2}) = (\d+) m\.", L[1])
        m3 = re.fullmatch(r"Find the exact length of ([A-Z]{2})\.", asked)
        need(m and m2 and m3 and m.group(1) == m.group(2), f"can't read {L!r}")
        T, O, dg = m.group(3), m.group(4), int(m.group(5))
        need(dg in (30, 45, 60), "not a special angle")
        Rt = m.group(1)
        th = sp.rad(dg)
        size = {frozenset(Rt + O): sp.sin(th), frozenset(T + Rt): sp.cos(th), frozenset(T + O): sp.Integer(1)}
        known, have, name = int(m2.group(2)), size[frozenset(m2.group(1))], m3.group(1)
        wanted = size[frozenset(name)]
        want = f"{name} = {rt_exact(known * wanted / have)} m"
        legs = (frozenset(Rt + O), frozenset(T + Rt))
        if frozenset(name) == frozenset(T + O):
            wr[RT_S + "0"] = {f"{name} = {rt_exact(known * have)} m"}
            # The other leg's ratio: sin and cos swapped.
            other_leg = legs[1] if frozenset(m2.group(1)) == legs[0] else legs[0]
            wr[RT_R + "0"] = {f"{name} = {rt_exact(known / size[other_leg])} m"}
        else:
            other_leg = legs[1] if frozenset(name) == legs[0] else legs[0]
            wr[RT_DIVIDE] = {f"{name} = {rt_exact(known / wanted)} m"}
            wr[RT_R + "0"] = {f"{name} = {rt_exact(known * size[other_leg])} m"}
    elif u == "angle-from-sides":
        tail, label = "°", "angle = "
        if re.search(r"It is .+ long, and [A-Z] is", text):
            fn, hh, s_ = "sin", n(r"It is " + RT_NUM + " m long"), n(r"and [A-Z] is " + RT_NUM + " m above")
            r_ = s_ / hh
            t = asin(r_)
        elif "long" in " ".join(L[1:]):
            fn, hh, s_ = "cos", n(r"It is " + RT_NUM + " m long"), n(r"[A-Z]{2} = " + RT_NUM + r" m\.")
            r_ = s_ / hh
            t = acos(r_)
        else:
            fn, s_, hh = "tan", n(r"[A-Z] is " + RT_NUM + " m above"), n(r"[A-Z]{2} = " + RT_NUM + r" m\.")
            r_ = s_ / hh
            t = atan(r_)
        x = deg(t)
        need(12 < x < 75 and abs(x - 45) >= RT_AWAY, "the angle is out of limits")
        f = {"sin": sin, "cos": cos, "tan": tan}[fn]
        W(RT_A + "0", f(mpmath.radians(r_)))
        W(RT_A + "1", 1 / f(mpmath.radians(r_)))
        if fn == "tan":
            W(RT_A + "2", 90 - x)
        else:
            # sin⁻¹ for cos⁻¹ or the other way: the other acute angle.
            W(RT_R + "0", 90 - x)
    elif u == "angle-special":
        T, Rt, O, _ = rt_triangle(L)
        got = {frozenset(a): rt_value(v) for a, v in re.findall(r"([A-Z]{2}) = (\d*√?\d+) m", L[1])}
        need(len(got) == 2, "not two sides")
        ko, ka, kh = frozenset(Rt + O), frozenset(T + Rt), frozenset(T + O)
        if ko in got and kh in got:
            fn, val, f = "sin", got[ko] / got[kh], sp.asin
        elif ka in got and kh in got:
            fn, val, f = "cos", got[ka] / got[kh], sp.acos
        else:
            fn, val, f = "tan", got[ko] / got[ka], sp.atan
        dg = sp.simplify(f(val) * 180 / sp.pi)
        need(dg in (30, 45, 60), f"the sides give {dg}°")
        want = f"θ = {dg}°"
        if fn == "tan" and dg != 45:
            wr[RT_A + "2"] = {f"θ = {90 - dg}°"}
        elif dg != 45:
            wr[RT_R + "0"] = {f"θ = {90 - dg}°"}
    elif u == "gradient-from-angle":
        dg = int(n(r"at an angle of (\d+)° above"))
        e = rt_e(dg)
        label = "gradient = "
        x = tan(e)
        W(RT_R + "3", sin(e))
        W(RT_R + "4", 1 / tan(e))
    elif u == "angle-from-gradient":
        p_, q_ = rt_gradient(text)
        r_ = mpmath.mpf(p_) / q_
        tail, label = "°", "angle = "
        x = deg(atan(r_))
        if r_ < 1:
            W(RT_A + "3", deg(asin(r_)))
        W(RT_A + "2", deg(atan(1 / r_)))
        W(RT_A + "0", tan(mpmath.radians(r_)))
        if rep == "diagram":
            pts = {k: tuple(mpmath.mpf(c) for c in p) for k, p in q["graph"]["pts"].items()}
            ln = next(ln for ln in q["graph"]["lines"] if ln["label"].startswith("gradient"))
            need(ln["label"] == f"gradient {p_}/{q_}", "the figure shows another gradient")
            a_, b_ = sorted((pts[ln["a"]], pts[ln["b"]]))
            need(abs((b_[1] - a_[1]) / (b_[0] - a_[0]) - r_) < mpmath.mpf("1e-9"), "the slope isn't drawn to its gradient")
    elif u == "angle-with-vertical":
        p_, q_ = rt_gradient(text)
        tail, label = "°", "angle BAM = "
        x = deg(atan(mpmath.mpf(q_) / p_))
        W(RT_A + "4", 90 - x)
        W(RT_T + "26", 2 * x)
    elif u in ("edge-from-span", "upper-edge"):
        p_, q_ = rt_gradient(text)
        m = re.search(r"PQ = " + RT_NUM + r" m\. M and N are level points on the lower edges, with MN = " + RT_NUM + r" m and QM = " + RT_NUM + r" m\.", text)
        need(m, f"can't read {text!r}")
        t_, span, over = [be_mp(R(m.group(i))) for i in (1, 2, 3)]
        r_ = mpmath.mpf(p_) / q_
        sec = sqrt(1 + r_**2)
        lower = span / 2 * sec + over
        tail = " m"
        if u == "edge-from-span":
            label = "QV = "
            x = lower
            W(RT_T + "17", span * sec + over)
            W(RT_T + "18", span / 2 * sec)
            W(RT_R + "0", span / 2 * sec / r_ + over)
        else:
            label = "PU = "
            x = lower + t_ * r_
            W(RT_T + "19", lower)
            W(RT_T + "20", lower + t_)
            W(RT_R + "0", lower + t_ / r_)
        pts = {k: tuple(mpmath.mpf(c) for c in p) for k, p in q["graph"]["pts"].items()}
        for a_, b_ in (("Q", "V"), ("P", "U")):
            need(abs((pts[b_][1] - pts[a_][1]) / (pts[b_][0] - pts[a_][0]) - r_) < mpmath.mpf("1e-9"), "the edge isn't drawn to its gradient")
    elif u == "height-from-angle":
        t, is_deg = be_angle_read(text)
        d = n(RT_NUM + r" m from the foot F")
        tail, label = " m", "height = "
        x = d * tan(t)
        size = R(re.search(r"is ([\d.]+)(°| radians)", text).group(1))
        W(RT_T + "7", d * (tan(be_mp(size)) if is_deg else tan(mpmath.radians(be_mp(size)))))
        W(RT_WRONG_FN, d * sin(t))
        W(RT_WRONG_FN, d * cos(t))
        W(RT_DIVIDE, d / tan(t))
    elif u == "elevation-after-walk":
        t, is_deg = be_angle_read(L[0])
        d, w = n(RT_NUM + r" m from the foot F"), n(r"walks " + RT_NUM + " m straight")
        need(0 < w < d, "the walk passes the foot")
        hh = d * tan(t)
        tail, label = ("°", "angle = ") if is_deg else (" radians", "angle = ")
        c = deg if is_deg else (lambda z: z)
        x = c(atan(hh / (d - w)))
        W(RT_T + "21", c(atan(hh / w)))
        # Adjacent ÷ opposite: the angle at the top.
        W(RT_A + "2", c(atan((d - w) / hh)))
    elif u == "equal-elevations":
        m = re.search(r"PA = " + RT_NUM + r" m, PB = " + RT_NUM + r" m and angle APB = (\d+)°\.", text)
        need(m, f"can't read {text!r}")
        la, lb, phi = be_mp(R(m.group(1))), be_mp(R(m.group(2))), int(m.group(3))
        need(la > lb and phi % 2 == 0 and phi != 90, "the towers or the angle are out of limits")
        th = mpmath.radians(mpmath.mpf(180 - phi) / 2)
        tail, label = " m", "height = "
        x = la * sin(th)
        W(RT_T + "22", la * sin(mpmath.radians(mpmath.mpf(phi) / 2)))
        W(RT_T + "27", lb * sin(th))
        W(RT_WRONG_FN, la * tan(th))
    elif u == "cone-from-eye-level":
        t, _ = be_angle_read(text)
        hh, d, eye = n(r", " + RT_NUM + r" m high"), n(r"at Q, " + RT_NUM + " m from the edge"), n(r"eyes E " + RT_NUM + " m above")
        tail, label = " m", "radius = "
        x = (hh - eye) / tan(t) - d
        need(x > 3, "the cone is too small")
        W(RT_E + "2", hh / tan(t) - d)
        W(RT_T + "23", (hh - eye) / tan(t))
        W(RT_S + "0", (hh - eye) * tan(t) - d)
        W(RT_WRONG_FN, (hh - eye) / sin(t) - d)
    elif u == "depression-sight-line":
        t, _ = be_angle_read(L[1])
        hh = n(r"is " + RT_NUM + " m above level ground")
        tail, label = " m", "TP = "
        x = hh / sin(t)
        W(RT_E + "1", hh / cos(t))
        W(RT_S + "0", hh * sin(t))
        W(RT_WRONG_FN, hh / tan(t))
    elif u == "depression-from-sight-line":
        hh, l_ = n(r"is " + RT_NUM + " m above level ground"), n(r"TP = " + RT_NUM + r" m\.")
        tail, label = "°", "angle = "
        x = deg(asin(hh / l_))
        need(14 < x < 70 and abs(x - 45) >= RT_AWAY, "the angle is out of limits")
        W(RT_E + "0", 90 - x)
        W(RT_WRONG_FN, deg(atan(hh / l_)))
    elif u == "depression-two-points":
        m = re.search(r"angle of depression of P is (\d+)° and of Q is (\d+)°\.", text)
        need(m, f"can't read {text!r}")
        hh = n(r"is " + RT_NUM + " m above level ground")
        a1, a2 = mpmath.radians(int(m.group(1))), mpmath.radians(int(m.group(2)))
        need(int(m.group(1)) - int(m.group(2)) >= 8, "the two angles are too close")
        tail, label = " m", "PQ = "
        x = hh / tan(a2) - hh / tan(a1)
        W(RT_E + "1", hh * tan(a1) - hh * tan(a2))
        W(RT_T + "28", hh / tan(a2) + hh / tan(a1))
    elif u == "name-the-angle":
        need(q["graph"] is not None, "no figure")
        pts = {k: tuple(mpmath.mpf(c) for c in p) for k, p in q["graph"]["pts"].items()}
        dep = "depression" in asked
        eye, seen = ("T", "P") if dep else ("P", "T")
        names = [o["text"] for o in q["choices"]]
        good = []
        for nm in names:
            a_, v_, b_ = nm[-3:]
            if v_ == eye and b_ == seen and abs(pts[a_][1] - pts[eye][1]) < mpmath.mpf("1e-9"):
                good.append(nm)
            elif v_ == eye and a_ == seen and abs(pts[b_][1] - pts[eye][1]) < mpmath.mpf("1e-9"):
                good.append(nm)
        need(len(good) == 1, f"{len(good)} options are the angle at the eye from the horizontal")
        want = good[0]
        wr[RT_T + "24"] = {"angle FPT" if dep else "angle HTP"}
        if dep:
            wr[RT_E + "0"] = {"angle FTP"}
    else:
        raise Fail(f"no check for {u}")
    trap = None
    if x is not None:
        need(x > 0 and be_clear(x), f"{x} is on a rounding edge")
        need(asked.endswith(" Give your answer to 3 significant figures."), f"asked {asked!r}")
        want = be_text(label, x, tail)
        t2 = bn_trap(label, nu_f(x))
        trap = t2 + tail if t2 else None
    gc_check_common(q, want, wr, trap)
    if rep == "diagram":
        be_figure(q, "note" not in q["graph"])
        need(u in ("edge-from-span", "upper-edge", "cone-from-eye-level") or "note" not in q["graph"], "only a crowded figure is not to scale")
        rt_arcs_at_eye(q, u)
    for sol in q["solutions"]:
        tri_working(q, sol)
    return None, None


# ── solid (t3-solid-volume-area, FAL-726) ────────────────────
# The `solid` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/solid.gd. Each question's measures are read back from its sketch or its
# sentences, the shape from its opening line, and every value is worked out again with exact
# rationals and π. The working's arithmetic is evaluated wherever a step is plain numbers.

SD_EDGE = sp.Rational(29, 1000)         # the engine's is 0.03
SD_V = "SL3.1.volume-solids#"
SD_S = "SL3.1.surface-area#"
SD_T = "t3-solid-volume-area#"           # FAL-820: the slips that were blank options
SD_SHAPES = {"a right cone": "cone", "a right pyramid": "pyramid", "a solid sphere": "sphere", "a solid hemisphere": "hemisphere",
             "a solid made of a cone on a hemisphere with the same radius": "cone-hemisphere",
             "a solid made of a cone on a cylinder with the same radius": "cone-cylinder",
             "a solid made of a hemisphere on a cylinder with the same radius": "hemisphere-cylinder",
             "a solid cylinder with a hemisphere hollowed out of its top": "cylinder-minus-hemisphere",
             "a solid made of a cylinder with a hemisphere on each end": "capsule",
             "a solid cylinder with a smaller cylinder removed from its centre": "hollow",
             "a solid cylinder that fits exactly inside a hollow sphere": "inscribed"}
SD_NAMES = {"radius": "r", "diameter": "d", "height": "h", "slant height": "l", "slant height of each face": "t", "slant edge": "e",
            "base edge": "a", "other base edge": "b", "cone's height": "h", "cone's slant height": "l", "cylinder's height": "c",
            "cylinder's radius": "big", "hemisphere's radius": "r", "sphere's radius": "r", "sector's radius": "l", "sector's angle": "theta"}


def sd_shape(q):
    """The solid named in the opening line, the longest name that fits."""
    found = [v for k, v in SD_SHAPES.items() if f" is {k}" in q["lines"][0]]
    if not found:
        need("sector" in q["lines"][0] or "cone with no base" in q["lines"][0], f"can't read the solid in {q['lines'][0]!r}")
        return "sector"
    need(len(found) == 1, f"two solids in {q['lines'][0]!r}")
    if q["graph"] is not None:
        need(q["graph"]["shape"] == found[0], "the sketch is not the solid in the words")
    return found[0]


def sd_len(text):
    """"5.2 cm", "127°" as a Rational, or None for a letter."""
    mt = re.fullmatch(r"(\d+(?:\.\d+)?)(?: cm| m|°)", text)
    return sp.Rational(mt.group(1)) if mt else None


def sd_read(q):
    """The measures the student is shown, as Rationals, by key: r, h, l and so on."""
    out = {}
    if q["graph"] is not None:
        need(q["graph"]["kind"] == "solid", "not a solid sketch")
        for k, v in q["graph"].items():
            if k not in ("kind", "shape"):
                out[k] = sd_len(v)
    else:
        text = " ".join(q["lines"])
        for mt in re.finditer(r"[Tt]he ((?:(?! is )[a-z' ])+) is (\d+(?:\.\d+)?(?: cm| m|°))(?=[ ,.])", text):
            if mt.group(1) not in ("volume", "total surface area"):
                out[SD_NAMES[mt.group(1)]] = sd_len(mt.group(2))
    if "d" in out and out["d"] is not None:
        out["r"] = out["d"] / 2
    return out


def sd_given(q, name):
    """A total shown in a line: Rational, and whether it has π."""
    mt = re.search(rf"The {name} is (?:\((\d+/\d+)\)|(\d+))?(π)? ?(?:cm|m)", " ".join(q["lines"]))
    need(mt is not None, f"can't read the {name}")
    return sp.Rational(mt.group(1) or mt.group(2) or 1), mt.group(3) is not None


def sd_lead(c):
    """A coefficient as Fmt.lead writes it: (2/3), 5, and nothing for 1."""
    c = sp.Rational(c)
    return "" if c == 1 else (str(c.p) if c.q == 1 else f"({c.p}/{c.q})")


def sd_text(head, x, unit, paper, pi):
    """An answer x (times π where `pi`) as the game writes it."""
    if paper == 2:
        return head + rg_s(sp.N(x * (sp.pi if pi else 1), 40)) + unit
    x = sp.Rational(x)
    return head + (sd_lead(x) + "π" if pi else frac_text(x)) + unit


def sd_trap(head, x, unit, pi):
    v = sp.N(x * (sp.pi if pi else 1), 40)
    return head + dec_text(sp.Rational(sig3(v, 2))) + unit


def sd_set(q, head, x, unit, pi, table):
    """want, trap and wrongs for x; `table` is ref -> the values that mistake gives."""
    paper = q["paper"]
    wrongs = {ref: {sd_text(head, v, unit, paper, pi) for v in vals} for ref, vals in table.items()}
    return sd_text(head, x, unit, paper, pi), (sd_trap(head, x, unit, pi) if paper == 2 else None), wrongs


def sd_terms(head, terms, minus=False):
    return head + (" − " if minus else " + ").join(sd_lead(c) + body for c, body in terms)


def sd_edge(q, x):
    """On Paper 2 the answer is clear of a rounding edge and needs rounding."""
    if q["paper"] != 2:
        return
    v = abs(sp.N(x, 40))
    e = int(sp.floor(sp.log(v, 10)))
    scaled = v / sp.Integer(10) ** (e - 2)
    need(abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= SD_EDGE, f"{v} is too close to a rounding edge")
    need(sp.Rational(sig3(v)) != v, f"{v} needs no rounding")


def sd_measures(q, m):
    """Paper 1 measures are whole, Paper 2 measures have one decimal place."""
    for k, v in m.items():
        if v is None or (k == "r" and "d" in m):
            continue
        if q["paper"] == 1:
            need(v.q == 1 or k == "theta", f"{k} = {v} is not whole on Paper 1")
        else:
            need((v * 10).q == 1, f"{k} = {v} has more than one decimal place on Paper 2")


SD_UNIT = re.compile(r"(?:cm|m)(?:²|³)?(?![a-zA-Z])")


def sd_value(text):
    """A step's piece as a number, or None if it has letters or words in it."""
    t = SD_UNIT.sub("", text).strip().rstrip(".")
    if not t or not re.fullmatch(r"[0-9.()+−×÷/π²³√ ]+", t):
        return None
    t = t.replace("−", "-").replace("×", "*").replace("÷", "/").replace("²", "**2").replace("³", "**3")
    t = re.sub(r"(\d|\))π", r"\1*pi", t).replace("π", "pi")
    t = re.sub(r"√\(", "sqrt(", t)
    if "√" in t:
        return None
    return sp.N(sp.sympify(t, rational=True), 30)


def sd_steps(q):
    """Each pair of neighbouring plain-number sides of a step agree, to the figures shown. Returns
    how many pairs were read."""
    pairs = 0
    for sol in q["solutions"]:
        for st in sol["steps"]:
            sides = [sd_value(p) for p in re.split(r" = ", re.sub(r"^.*: ", "", st))]
            for a, b in zip(sides, sides[1:]):
                if a is None or b is None:
                    continue
                pairs += 1
                need(abs(a - b) <= max(abs(b) * sp.Rational(3, 10000), sp.Rational(6, 1000)), f"{sol['name']}: {st!r} doesn't add up ({a} and {b})")
    return pairs


def check_solid(q):
    u, paper, L = q["view"]["unknown"], q["paper"], q["lines"]
    shape = sd_shape(q)
    m = sd_read(q)
    sd_measures(q, m)
    unit = " " + ("m" if u == "paint-cost" else "cm")
    u2, u3 = unit + "²", unit + "³"
    V, S, T = SD_V, SD_S, SD_T
    pi = True
    r, h, l, c = m.get("r"), m.get("h"), m.get("l"), m.get("c")
    if shape == "inscribed":
        h = h if h is not None else c
    if q["graph"] is None and u not in ("hollow-surface", "hollow-volume-from-surface", "surface-from-volume"):
        need(not any(x is None for x in m.values()), f"a letter in the words: {m}")
    table, want, trap, wrongs, x = {}, None, None, {}, None
    pyth = lambda a, b: sp.sqrt(a * a + b * b)
    leg = lambda hyp, a: sp.sqrt(hyp * hyp - a * a)
    if paper == 1 and u in ("cone-volume", "cone-curved", "cone-total", "cone-volume-from-slant", "height-from-slant"):
        have = [v for v in (r, h, l) if v is not None]
        need(len(have) == 2, "a cone shows two lengths")
    if u in ("cone-volume", "cone-volume-from-slant", "cone-volume-from-total", "sector-cone-volume", "height-from-slant", "slant-from-total"):
        if u in ("cone-volume-from-total", "slant-from-total"):
            A, has_pi = sd_given(q, "total surface area")
            need(has_pi == (paper == 1), "the area's form is not this paper's")
            l = A / r - r if paper == 1 else A / (sp.pi * r) - r
        if u == "sector-cone-volume":
            l, th = m["l"], m["theta"]
            r = l * th / 360
        if u != "cone-volume":
            need(l > r, "the slant height is not the longest side")
            h = leg(l, r)
        if paper == 1:
            need(sp.Rational(h).q == 1 if h.is_rational else False, f"h = {h} is not whole")
        x = r * r * h / 3
        if u == "cone-volume":
            table = {V + "1": [3 * x], T + "6": [r * r * h / 2]}  # a half for the third
            if "d" in m:
                table[V + "2"] = [4 * x]
            want, trap, wrongs = sd_set(q, "V = ", x, u3, True, table)
        elif u == "height-from-slant":
            x, pi = h, False
            table = {T + "8": [l - r]}  # the lengths taken away, not their squares
            if paper == 2:
                table[T + "9"] = [pyth(l, r)]  # the squares added
            else:
                table[V + "0"] = [l]  # the slant height given as the height
            want, trap, wrongs = sd_set(q, "h = ", h, unit, False, table)
        elif u == "slant-from-total":
            x, pi = l, False
            want, trap, wrongs = sd_set(q, "l = ", l, unit, False, {T + "13": [l + r]})  # A ÷ πr with r not taken away
        else:
            want, trap, wrongs = sd_set(q, "V = ", x, u3, True, {V + "0": [r * r * l / 3], V + "1": [3 * x]})
    elif u in ("cone-curved", "cone-total"):
        if l is None:
            l = pyth(r, h)
        else:
            h = None
        need(paper == 2 or l.q == 1, "l is not whole")
        x = r * l + (r * r if u == "cone-total" else 0)
        table = {S + "0": [r * h + (r * r if u == "cone-total" else 0)]} if h is not None else {}
        if u == "cone-curved":
            table[T + "10"] = [r * l + r * r]  # the base added
            table[T + "11"] = [2 * r * l]  # 2πrl
        else:
            table[S + "1"] = [r * l]  # the base left out
            table[T + "12"] = [r * l + 2 * r * r]  # two ends
        want, trap, wrongs = sd_set(q, "area = ", x, u2, True, table)
    elif u == "pyramid-volume":
        a, b = m["a"], m.get("b", m["a"])
        x, pi = a * b * h / 3, False
        need(paper == 2 or x.q == 1, "a Paper 1 pyramid's volume is whole")
        want, trap, wrongs = sd_set(q, "V = ", x, u3, False, {V + "1": [3 * x], T + "6": [a * b * h / 2]})  # a half for the third
    elif u in ("pyramid-volume-from-slant", "pyramid-volume-from-edge"):
        a = m["a"]
        sl = m["t"] if "slant" in u else m["e"]
        h = leg(sl, a / 2) if "slant" in u else sp.sqrt(sl * sl - a * a / 2)
        need(paper == 2 or h.is_integer, f"h = {h} is not whole")
        x, pi = a * a * h / 3, False
        want, trap, wrongs = sd_set(q, "V = ", x, u3, False, {V + "0": [a * a * sl / 3], V + "1": [3 * x]})
    elif u == "pyramid-surface":
        a = m["a"]
        t = pyth(a / 2, h)
        need(paper == 2 or t.is_integer, f"t = {t} is not whole")
        x, pi = a * a + 2 * a * t, False
        want, trap, wrongs = sd_set(q, "area = ", x, u2, False, {S + "0": [a * a + 2 * a * h], S + "1": [2 * a * t],  # no base
                                                                T + "14": [a * a + 4 * a * t]})  # faces not halved
    elif u in ("sphere-volume", "sphere-surface", "hemisphere-volume", "hemisphere-surface"):
        if u == "sphere-volume":
            x = 4 * r ** 3 / 3
        elif u == "sphere-surface":
            x = 4 * r * r
        elif u == "hemisphere-volume":
            x = 2 * r ** 3 / 3
        else:
            x = 3 * r * r
        table = {V + "2": [x * (8 if "volume" in u else 4)]} if "d" in m else {}
        if u == "hemisphere-volume":
            table[V + "1"] = [2 * x]
        if u == "hemisphere-surface":
            table[S + "1"] = [2 * r * r]
            table[S + "2"] = [4 * r * r]
        # The other formula: a surface for a volume, a volume for a surface.
        table[T + "15"] = {"sphere-volume": [4 * r * r], "sphere-surface": [4 * r ** 3 / 3], "hemisphere-volume": [2 * r * r, 3 * r * r],
                           "hemisphere-surface": [2 * r ** 3 / 3]}[u]
        if u == "sphere-surface":
            table[T + "16"] = [r * r]  # a flat circle
        want, trap, wrongs = sd_set(q, "V = " if "volume" in u else "area = ", x, u3 if "volume" in u else u2, True, table)
    elif u == "radius-from-volume":
        Vv, has_pi = sd_given(q, "volume")
        need(has_pi == (paper == 1), "the volume's form is not this paper's")
        W = Vv * sp.pi if has_pi else Vv
        if shape == "sphere":
            x = sp.real_root(3 * W / (4 * sp.pi), 3)
        elif shape == "hemisphere":
            x = sp.real_root(3 * W / (2 * sp.pi), 3)
        else:
            x = sp.sqrt(3 * W / (sp.pi * h))
        x = sp.nsimplify(x) if paper == 1 else x
        pi = False
        need(paper == 2 or x.is_integer, f"r = {x} is not whole")
        table = {V + "2": [2 * x]}
        if paper == 2 and shape == "hemisphere":
            table[V + "1"] = [sp.real_root(3 * W / (4 * sp.pi), 3)]
        if paper == 2 and shape == "cone":
            table[V + "1"] = [sp.sqrt(W / (sp.pi * h))]
        if shape == "cone":
            table[T + "17"] = [x * x]  # r² with no root
        want, trap, wrongs = sd_set(q, "r = ", x, unit, False, table)
    elif u == "height-from-volume":
        Vv, has_pi = sd_given(q, "volume")
        cone = shape == "cone"
        W = Vv * sp.pi if has_pi else Vv
        x = 3 * W / (sp.pi * r * r) if cone else 3 * W / (m["a"] ** 2)
        pi = False
        table = {V + "1": [x / 3]}
        if "d" in m:
            table[V + "2"] = [x / 4]
        want, trap, wrongs = sd_set(q, "h = ", x, unit, False, table)
    elif u in ("composite-volume", "composite-surface", "paint-cost"):
        big = m.get("big")
        if shape.startswith("cone"):
            if l is None:
                l = pyth(r, h)
            elif h is None:
                h = leg(l, r)
        shown_h = "h" in m
        cone_v = r * r * h / 3 if shape.startswith("cone") else 0
        dome_v = 2 * r ** 3 / 3
        cone_s = r * l if shape.startswith("cone") else 0
        if shape == "cone-hemisphere":
            vol, surf, base = cone_v + dome_v, cone_s + 2 * r * r, 0
        elif shape == "cone-cylinder":
            vol, surf, base = cone_v + r * r * c, cone_s + 2 * r * c + r * r, r * r
        elif shape == "hemisphere-cylinder":
            vol, surf, base = dome_v + r * r * c, 2 * r * r + 2 * r * c + r * r, r * r
        else:
            need(shape == "cylinder-minus-hemisphere", f"{shape} is not a composite")
            need(r <= big - sp.Rational(2, 5) and c >= r + sp.Rational(9, 10), "the hemisphere doesn't fit")
            vol, surf, base = big * big * c - dome_v, 2 * r * r + 2 * big * c + big * big + big * big - r * r, big * big
        if u == "composite-volume":
            x = vol
            table = {}
            if shape.startswith("cone"):
                table[V + "1"] = [x + 2 * cone_v]
                if "l" in m:
                    table.setdefault(V + "0", []).append(x + (l - h) * r * r / 3)
            if shape in ("cone-hemisphere", "hemisphere-cylinder"):
                table.setdefault(V + "1", []).append(x + dome_v)
            if shape == "cylinder-minus-hemisphere":
                table[T + "19"] = [big * big * c + dome_v]  # the hole added
            else:
                first = cone_v if shape.startswith("cone") else dome_v
                table[T + "18"] = [first, x - first]  # one piece
            want, trap, wrongs = sd_set(q, "V = ", x, u3, True, table)
        elif u == "composite-surface":
            x = surf
            table = {S + "1": [x + (r * r if shape == "cylinder-minus-hemisphere" else 2 * r * r)]}
            if shape.startswith("cone") and shown_h:
                table[S + "0"] = [x + r * (h - l)]
            if shape != "cone-cylinder":
                table[S + "2"] = [x + 2 * r * r]
            if shape in ("cone-cylinder", "hemisphere-cylinder"):
                table[S + "1"].append(x - r * r)  # the base left out
            want, trap, wrongs = sd_set(q, "area = ", x, u2, True, table)
        else:
            mt = re.fullmatch(r"Paint costs \$(\d+(?:\.\d\d)?) per m²\.", L[-1])
            need(mt is not None, f"can't read {L[-1]!r}")
            price = sp.Rational(mt.group(1))
            need(q["asked"] == "Find the cost of painting the outside of the tank. The base is not painted.", q["asked"])
            need(shape in ("cone-cylinder", "hemisphere-cylinder"), "a tank is a cone or hemisphere on a cylinder")
            op = surf - base
            x = op * price
            table = {S + "1": [surf * price]}
            if shape == "cone-cylinder" and shown_h:
                table[S + "0"] = [x + r * (h - l) * price]
            if shape == "hemisphere-cylinder":
                table[S + "2"] = [x + 2 * r * r * price]
            table[T + "20"] = [op]  # the area, not the cost
            want, trap, wrongs = sd_set(q, "cost = $", x, "", True, table)
    elif u == "composite-volume-solve":
        need(paper == 2, "the GDC solver is Paper 2")
        need(q["asked"] == "Find r.", q["asked"])
        Vv, has_pi = sd_given(q, "volume")
        need(not has_pi, "a Paper 2 volume is a number")
        cone = shape == "cone-hemisphere"
        p23, p43 = sp.Rational(2, 3), sp.Rational(4, 3)
        b = sp.Rational(h) / 3 if cone else sp.Rational(c)
        roots = [sd_root(p23, b, Vv)]
        x = roots[0]
        pi = False
        slip = sd_root(p23, sp.Rational(h), Vv) if cone else sd_root(p43, sp.Rational(c), Vv)
        want, trap, wrongs = sd_set(q, "r = ", x, unit, False, {V + "1": [slip]})
    elif u == "volume-in-terms":
        need("in terms of x" in q["asked"], q["asked"])
        rx, hx, cc = sd_x_measures(q)
        v = {"cone": [(sp.Rational(rx * rx * (hx or 0), 3), "πx³")], "sphere": [(sp.Rational(4 * rx ** 3, 3), "πx³")],
             "hemisphere": [(sp.Rational(2 * rx ** 3, 3), "πx³")],
             "hemisphere-cylinder": [(sp.Rational(2 * rx ** 3, 3), "πx³"), (rx * rx * (cc or 0), "πx²")],
             "cone-cylinder": [(sp.Rational(rx * rx * (hx or 0), 3), "πx³"), (rx * rx * (cc or 0), "πx²")]}[shape]
        want = sd_terms("V = ", v)
        wrongs = {}
        if shape != "sphere":
            first = 2 if shape.startswith("hemi") else 3
            wrongs[V + "1"] = {sd_terms("V = ", [(v[0][0] * first, "πx³")] + v[1:])}
        q["_expr"] = True
    elif u == "surface-in-terms":
        rx, hx, cc = sd_x_measures(q)
        if shape == "cone":
            lx = sp.sqrt(rx * rx + hx * hx)
            need(lx.is_integer, "l is not a whole multiple of x")
            whole = "total" in q["asked"]
            base = rx * rx if whole else 0
            want = sd_terms("S = ", [(rx * lx + base, "πx²")])
            wrongs = {S + "0": {sd_terms("S = ", [(rx * hx + base, "πx²")])}}
            if not whole:
                wrongs[T + "10"] = {sd_terms("S = ", [(rx * lx + rx * rx, "πx²")])}  # the base added
        elif shape == "hemisphere":
            want = sd_terms("S = ", [(3 * rx * rx, "πx²")])
            wrongs = {S + "1": {sd_terms("S = ", [(2 * rx * rx, "πx²")])}, S + "2": {sd_terms("S = ", [(4 * rx * rx, "πx²")])}}
        else:
            need(shape == "hemisphere-cylinder", shape)
            wall = 2 * rx * cc
            want = sd_terms("S = ", [(3 * rx * rx, "πx²"), (wall, "πx")])
            wrongs = {S + "1": {sd_terms("S = ", [(2 * rx * rx, "πx²"), (wall, "πx")])}, S + "2": {sd_terms("S = ", [(5 * rx * rx, "πx²"), (wall, "πx")])}}
        q["_expr"] = True
    elif u in ("hollow-surface", "hollow-volume-from-surface"):
        need(shape == "hollow", shape)
        txt = q["graph"]["big"] if q["graph"] else re.search(r"outer radius is (\d+)r", " ".join(L)).group(1) + "r"
        k = int(txt[:-1])
        if u == "hollow-surface":
            r_s, h_s = sp.symbols("r h", positive=True)
            S_e = sp.expand(2 * sp.pi * k * r_s * h_s + 2 * sp.pi * r_s * h_s + 2 * sp.pi * ((k * r_s) ** 2 - r_s ** 2))
            a2, a1 = S_e.coeff(r_s, 2) / sp.pi, S_e.coeff(r_s, 1).coeff(h_s, 1) / sp.pi
            want = sd_terms("S = ", [(a2, "πr²"), (a1, "πrh")])
            outer = 2 * k
            wrongs = {S + "1": {sd_terms("S = ", [(2 * a2, "πr²"), (a1, "πrh")])},
                      T + "21": {sd_terms("S = ", [(2 * k * k, "πr²"), (a1, "πrh")])},  # the hole left in the rings
                      T + "22": {sd_terms("S = ", [(a2, "πr²"), (outer, "πrh")])},  # no inner wall
                      T + "23": {sd_terms("S = ", [(a2, "πr²"), (outer - 2, "πrh")])}}  # inner wall taken away
        else:
            mt = re.search(r"total surface area is (\d+)π cm²", " ".join(L))
            need(mt is not None, "can't read S")
            M_ = int(mt.group(1))
            r_s, h_s = sp.symbols("r h", positive=True)
            hh = sp.solve(2 * (k * k - 1) * r_s ** 2 + 2 * (k + 1) * r_s * h_s - M_, h_s)[0]
            Vx = sp.expand((k * k - 1) * r_s ** 2 * hh)
            want = "V = " + f"{sd_lead(Vx.coeff(r_s, 1))}πr − {sd_lead(-Vx.coeff(r_s, 3))}πr³"
            need(Vx.coeff(r_s, 1) > 0 and Vx.coeff(r_s, 3) < 0, "the expression's signs")
        q["_expr"] = True
    elif u == "surface-from-volume":
        mt = re.search(r"its volume is (\d+) cm³", " ".join(L))
        need(mt is not None, "can't read the volume")
        W = int(mt.group(1))
        need(shape in ("capsule", "hemisphere-cylinder"), shape)
        two = shape == "capsule"
        want = sd_terms("S = ", [(2 * W, "/x"), (4 if two else 3, "πx²")])
        wrongs = {S + "1": {sd_terms("S = ", [(2 * W, "/x"), (6 if two else 2, "πx²")])},
                  T + "24": {sd_terms("S = ", [(W, "/x"), (4 if two else 3, "πx²")])}}  # the wall's two dropped
        if not two:
            wrongs[S + "2"] = {sd_terms("S = ", [(2 * W, "/x"), (5, "πx²")])}
        q["_expr"] = True
    elif u in ("inscribed-volume", "inscribed-surface"):
        need(h < 2 * r, "the cylinder doesn't fit")
        R_ = leg(r, h / 2)
        need(paper == 2 or R_.is_integer, f"R = {R_} is not whole")
        if u == "inscribed-volume":
            x = R_ * R_ * h
            want, trap, wrongs = sd_set(q, "V = ", x, u3, True, {V + "0": [r * r * h], V + "1": [x / 3], T + "7": [R_ * h],  # R not squared
                                                                 T + "25": [4 * r ** 3 / 3 - x]})  # the space left over
        else:
            x = 2 * R_ * R_ + 2 * R_ * h
            want, trap, wrongs = sd_set(q, "area = ", x, u2, True, {S + "0": [2 * r * r + 2 * r * h], S + "1": [R_ * R_ + 2 * R_ * h, 2 * R_ * h]})
    elif u in ("sector-cone-radius", "sector-curved"):
        l, th = m["l"], m["theta"]
        need(60 <= th <= 300, f"θ = {th}")
        rr = l * th / 360
        if u == "sector-cone-radius":
            x, pi = rr, False
            need(paper == 2 or rr.q == 1, "r is not whole")
            want, trap, wrongs = sd_set(q, "r = ", rr, unit, False, {V + "2": [2 * rr]})  # the diameter
        else:
            x = th / 360 * l * l
            want, trap, wrongs = sd_set(q, "area = ", x, u2, True, {T + "26": [l * l], T + "27": [rr * rr], T + "10": [x + rr * rr]})  # whole circle, base, base added
    elif u == "sector-angle":
        if q["graph"] is not None:
            need(q["graph"]["theta"] == "θ", "the angle is the unknown")
            l = sd_len(q["graph"]["l"])
            mt = re.search(r"base radius is (\S+ cm)\.", L[-1])
            rr = sd_len(mt.group(1))
        else:
            mt = re.search(r"has radius (\S+ cm) and slant height (\S+ cm)\.", L[0])
            rr, l = sd_len(mt.group(1)), sd_len(mt.group(2))
        x, pi = 360 * rr / l, False
        need(60 <= x <= 300, f"θ = {x}")
        need(paper == 2 or x.q == 1, "θ is not whole")
        want, trap, wrongs = sd_set(q, "θ = ", x, "°", False, {T + "28": [360 - x]})  # the part cut away
    else:
        raise Fail(f"no check for {u}")
    if x is not None:
        sd_edge(q, x * (sp.pi if pi else 1))
        if paper == 2:
            need(not trap or not q["answer"].get("exact", False), "a Paper 2 answer is not exact-only")
    expr_answer = q.pop("_expr", False)
    gc_check_common(q, want, wrongs, trap, steps=(2, 5))
    pairs = sd_steps(q)
    need(pairs > 0 or expr_answer or u in ("slant-from-total", "composite-volume-solve", "radius-from-volume", "height-from-volume"), "no working was read")
    return None, None


def sd_root(a, b, W):
    """The positive root of π(a r³ + b r²) = W, to 40 figures."""
    y = sp.Symbol("y")
    poly = sp.Poly(a * y ** 3 + b * y ** 2 - sp.Rational(W) / sp.pi, y)
    roots = [t for t in poly.nroots(n=40, maxsteps=200) if abs(sp.im(t)) < 1e-30 and sp.re(t) > 0]
    need(len(roots) == 1, f"{len(roots)} positive roots")
    return sp.re(roots[0])


def sd_x_measures(q):
    """rx, hx and the whole cylinder height of a solid given in terms of x."""
    if q["graph"] is not None:
        g = q["graph"]
        r_t, h_t, c_t = g["r"], g.get("h"), g.get("c")
    else:
        text = " ".join(q["lines"])
        find = lambda n: (lambda mt: mt.group(1) if mt else None)(re.search(rf"[Tt]he {n} is (\d*x? cm)", text))
        r_t = find("radius")
        h_t = find("height") or find("cone's height")
        c_t = find("cylinder's height")
    coef = lambda t: None if t is None else (lambda b: 1 if b == "" else int(b))(t.replace(" cm", "").replace("x", ""))
    need(r_t is not None and "x" in r_t, f"can't read r = {r_t!r}")
    return coef(r_t), coef(h_t), coef(c_t)


# ── standard-form (t1-standard-form, FAL-726) ────────────────
# The `standard-form` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/standard_form.gd. Numbers are read back from the question's text as exact
# Rationals, so a power of ten never has to fit a float, and each answer is normalised again here.

SF_EDGE = sp.Rational(59, 1000)         # the engine's is 0.06
SF_C = "SL1.1.convert#"
SF_M = "SL1.1.multiply-divide#"
SF_X = "SL1.1.context#"
SF_T = "t1-standard-form#"              # FAL-815: the slips that were blank options
SF_SUP = str.maketrans("⁰¹²³⁴⁵⁶⁷⁸⁹⁻", "0123456789-")
SF_NUM = re.compile(r"(?:(\d+(?:\.\d+)?) × )?10([⁰¹²³⁴⁵⁶⁷⁸⁹⁻]+)")
SF_PLAIN = re.compile(r"\d+(?: \d{3})*(?:\.\d+)?")


def sf_read(text):
    """Every a × 10^k in a piece of text, as [(a, k)]."""
    return [(sp.Rational(mt.group(1) or 1), int(mt.group(2).translate(SF_SUP))) for mt in SF_NUM.finditer(text)]


def sf_v(pair):
    return pair[0] * sp.Rational(10) ** pair[1]


def sf_norm(v):
    """v as (a, k) with 1 ≤ a < 10, without leaving exact numbers."""
    k = 0
    while v >= 10:
        v, k = v / 10, k + 1
    while v < 1:
        v, k = v * 10, k - 1
    return v, k


def sf_ten(k):
    return "10" + str(k).translate(str.maketrans("0123456789-", "⁰¹²³⁴⁵⁶⁷⁸⁹⁻"))


def sf_a(a, rounded, figs=3):
    a = sp.Rational(a)
    q = a.q
    for f in (2, 5):
        while q % f == 0:
            q //= f
    return sig3(a, figs) if rounded or q != 1 else dec_text(a)


def sf_text(a, k, rounded, head="", tail=""):
    return f"{head}{sf_a(a, rounded)} × {sf_ten(k)}{tail}"


def sf_answer(q, v, head="", tail=""):
    """want and trap for the value v: rounded on Paper 2, where it needs it."""
    a, k = sf_norm(v)
    rounded = q["paper"] == 2
    if q["paper"] == 1:
        need(sp.Rational(a * 1000).q == 1, f"a = {a} has too many figures for Paper 1")
    if abs(k) < 2:
        raise Fail(f"k = {k} is too small an answer power")
    if rounded:
        scaled = a * 100
        need(a < sp.Rational(99, 10), f"a = {a} is too near 10")
        need(abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= SF_EDGE, f"a = {a} is too close to a rounding edge")
    trap = None
    if rounded and sp.Rational(sig3(a)) != a:
        trap = f"{head}{sig3(a, 2)} × {sf_ten(k)}{tail}"
    return sf_text(a, k, rounded, head, tail), trap, a, k


def sf_raw(a, k):
    return f"{sig3(a)}E{str(k).replace('-', '−')}"


def sf_value(text):
    """A step's side as a number, or None if it has words or letters in it."""
    t = re.sub(r",.*$", "", text).strip().rstrip(".")
    t = re.sub(r"(?<=\d) (?=\d{3})", "", t)
    if not t or not re.fullmatch(r"[0-9.()+−×÷^ ⁰¹²³⁴⁵⁶⁷⁸⁹⁻²³]+", t):
        return None
    t = re.sub(r"([⁰¹²³⁴⁵⁶⁷⁸⁹⁻]+)", lambda mt: f"**({mt.group(1).translate(SF_SUP)})", t)
    t = t.replace("−", "-").replace("×", "*").replace("÷", "/").replace("^", "**")
    return sp.sympify(t, rational=True)


def sf_steps(q):
    pairs = 0
    for sol in q["solutions"]:
        for st in sol["steps"]:
            sides = [sf_value(p) for p in re.sub(r"^.*: ", "", st).split(" = ")]
            for a, b in zip(sides, sides[1:]):
                if a is None or b is None:
                    continue
                pairs += 1
                need(abs(a - b) <= abs(b) * sp.Rational(3, 10000), f"{sol['name']}: {st!r} doesn't add up ({a} and {b})")
    return pairs


def check_standard_form(q):
    u, paper, L, asked = q["view"]["unknown"], q["paper"], q["lines"], q["asked"]
    C, M, X = SF_C, SF_M, SF_X
    rounded = paper == 2
    text = " ".join(L)
    want, trap, wrongs = None, None, {}
    T = lambda a, k: sf_text(a, k, rounded)
    pq = sf_read(L[0]) + sf_read(L[1]) if u in ("multiply", "multiply-renormalise", "divide", "divide-renormalise", "power-product") else None
    if pq is not None:
        need(L[0].startswith("p = ") and L[1].startswith("q = "), "p and q")
        (a, m), (b, n) = pq
        need(m != 0 and n != 0, "a power of 0")
    if u in ("to-form-large", "to-form-small"):
        src = L[0] if L else asked
        mt = re.search(r"\d[\d ]*\d(?:\.\d+)?|0\.\d+|\d+", src.replace("10^k", "").replace("1 ≤ a < 10", ""))
        need(mt is not None, "can't read the number")
        v = sp.Rational(mt.group(0).replace(" ", ""))
        want, trap, a, k = sf_answer(q, v)
        need((v > 1) == (u == "to-form-large"), "the number is on the wrong side of 1")
        digit = k + 1 if k > 0 else k - 1
        wrongs = {C + "0": {T(a, -k)}, C + "1": {T(a, digit)}, C + "2": {T(a * 10, k - 1), T(a / 10, k + 1)}}
        if paper == 2:
            wrongs[X + "0"] = {sf_raw(a, k)}
    elif u in ("to-ordinary-large", "to-ordinary-small"):
        (a, k), = sf_read(text if L else asked)
        need((k > 0) == (u == "to-ordinary-large"), "the power is on the wrong side of 0")
        lab = "number = "
        want = lab + dec_text(a * sp.Rational(10) ** k)
        d = k + 1 if k > 0 else k - 1
        wrongs = {C + "0": {lab + dec_text(a * sp.Rational(10) ** -k)}, C + "1": {lab + dec_text(a * sp.Rational(10) ** d)}}
    elif u == "renormalise":
        rd = sf_read(asked)
        need(len(rd) == 1, "one number")
        a0, k0 = rd[0]
        need(not (1 <= a0 < 10), "the number is already in standard form")
        a, k = sf_norm(sf_v(rd[0]))
        want = sf_text(a, k, False)
        wrongs = {C + "2": {sf_text(a * 10 if a0 < 1 else a / 10, k - 1 if a0 < 1 else k + 1, False)}}
        # a brought between 1 and 10 by moving the point; the power left as shown, or moved the
        # other way: by as many places as the point moved, which k − k0 counts.
        wrongs[SF_T + "9"] = {sf_text(a, k0, False)}
        wrongs[SF_T + "10"] = {sf_text(a, k0 - (k - k0), False)}
    elif u == "order-mixed":
        mt = re.fullmatch(r"The four numbers are (.+)\.", L[0])
        need(mt is not None, "can't read the list")
        items = mt.group(1).split(",  ")
        need(len(items) == 4, "four numbers")
        vals = {}
        for it in items:
            rd = sf_read(it)
            vals[it] = sf_v(rd[0]) if rd else sp.Rational(it.replace(" ", ""))
        need(len(set(vals.values())) == 4, "two numbers are equal")
        big = "largest" in asked
        best = (max if big else min)(vals, key=lambda i: vals[i])
        lab = "largest: " if big else "smallest: "
        want = lab + best
        tricks = {lab + it for it in items if it != best and sf_read(it) and ((sf_read(it)[0][0] < 1) if big else (sf_read(it)[0][0] >= 10))}
        wrongs = {C + "2": tricks}
    elif u == "display-to-form":
        need(paper == 2, "a display is Paper 2")
        mt = re.fullmatch(r"A GDC shows (\d\.\d+)E(−?\d+)\.", L[0])
        need(mt is not None, f"can't read {L[0]!r}")
        a, k = sp.Rational(mt.group(1)), int(mt.group(2).replace("−", "-"))
        want = sf_text(a, k, False)
        wrongs = {X + "0": {mt.group(1) + "E" + mt.group(2)}, C + "0": {sf_text(a, -k, False)}}
    elif u in ("multiply", "multiply-renormalise"):
        need(m * n != m + n and m != n, "the powers are a degenerate pair")
        want, trap, r, k = sf_answer(q, a * b * sp.Rational(10) ** (m + n))
        need((a * b >= 10) == (u == "multiply-renormalise"), "the product is on the wrong side of 10")
        wrongs = {M + "0": {T(r, k - m - n + m * n)}, M + "2": {T(r, k - m - n + m - n)}}
        if a * b >= 10:
            wrongs[M + "1"] = {T(a * b, m + n)}
            wrongs[SF_T + "9"] = {T(a * b / 10, m + n)}
    elif u in ("divide", "divide-renormalise"):
        need(m != n, "the powers are equal")
        want, trap, r, k = sf_answer(q, a / b * sp.Rational(10) ** (m - n))
        need((a < b) == (u == "divide-renormalise"), "the quotient is on the wrong side of 1")
        wrongs = {M + "2": {T(r, k - m + n + m + n)}}
        if a < b:
            wrongs[M + "1"] = {T(a / b, m - n)}
            # 10a/b with the power raised, not lowered, to balance it.
            wrongs[SF_T + "10"] = {T(10 * a / b, m - n + 1)}
    elif u == "power-product":
        e = 2 * m + n
        want, trap, r, k = sf_answer(q, a * a * b * sp.Rational(10) ** e)
        wrongs = {M + "0": {T(r, k - e + m * m + n)}}
        # a² q with p's power of ten taken once: a² b × 10^(m + n).
        wrongs[SF_T + "12"] = {T(*sf_norm(a * a * b * sp.Rational(10) ** (m + n)))}
        if a * a * b >= 10:
            wrongs[M + "1"] = {T(a * a * b, e)}
    elif u in ("times-larger", "time-from-rate", "total-from-unit", "rate-unit-shift"):
        rd = sf_read(L[0])
        need(len(rd) == 2, "two numbers in the story")
        (a, m), (b, n) = rd
        if u == "times-larger":
            need(sf_v(rd[0]) > sf_v(rd[1]), "the first is not the larger")
            v = sf_v(rd[0]) / sf_v(rd[1])
            slip = sig_v2(a) / sig_v2(b) * sp.Rational(10) ** (m - n)
            fr, fk = sf_norm(1 / v)
            wrongs[X + "2"] = {T(fr, fk)}
        elif u == "total-from-unit":
            v = sf_v(rd[0]) * sf_v(rd[1])
            slip = sig_v2(a) * sig_v2(b) * sp.Rational(10) ** (m + n)
            # The story gives the amount for each first, then how many: how many ÷ each.
            wrongs[SF_T + "17"] = {T(*sf_norm(sf_v(rd[1]) / sf_v(rd[0])))}
        else:
            need("m s⁻¹" in L[0] and ("kilometres away" if u == "rate-unit-shift" else "metres away") in L[0], "the units")
            shift = 3 if u == "rate-unit-shift" else 0
            v = sf_v((b, n + shift)) / sf_v((a, m))
            slip = sig_v2(b) / sig_v2(a) * sp.Rational(10) ** (n + shift - m)
            if u == "rate-unit-shift":
                wrongs[SF_T + "13"] = {T(*sf_norm(sf_v((b, n)) / sf_v((a, m))))}
            else:
                wrongs[SF_T + "15"] = {T(*sf_norm(sf_v((a, m)) / sf_v((b, n))))}
                wrongs[SF_T + "16"] = {T(*sf_norm(sf_v((a, m)) * sf_v((b, n))))}
        want, trap, r, k = sf_answer(q, v)
        if paper == 2:
            sr, sk = sf_norm(slip)
            wrongs[X + "1"] = {T(sr, sk)}
            wrongs[X + "0"] = {sf_raw(r, k)}
    elif u == "unit-shift":
        (a, m), = sf_read(L[0])
        pairs = [("grams", "kilograms", -3), ("kilometres", "metres", 3), ("millimetres", "metres", -3), ("kilowatts", "watts", 3), ("kilograms", "grams", 3), ("metres", "kilometres", -3)]
        found = [s for f, to, s in pairs if re.search(rf"\b{f}\b", L[0]) and f"in {to}." in asked]
        need(len(found) == 1, "can't read the units")
        want = sf_text(a, m + found[0], False)
        wrongs[SF_T + "11"] = {sf_text(a, m - found[0], False)}
        need(1 <= a < 10 and abs(m + found[0]) >= 2, "the amount's a or power")
    elif u == "scale-value":
        (a, m), = sf_read(L[0])
        mt = re.search(r" (\d) times ", L[0])
        need(mt is not None, "can't read the multiplier")
        f = int(mt.group(1))
        want, trap, r, k = sf_answer(q, a * f * sp.Rational(10) ** m)
        if a * f >= 10:
            wrongs[M + "1"] = {T(a * f, m)}
    elif u == "sphere-volume-pi":
        (d, m), = sf_read(L[0])
        need("diameter" in L[0], "a diameter")
        c = (d / 2) ** 3 * sp.Rational(4, 3)
        want, trap, r, k = sf_answer(q, c * sp.Rational(10) ** (3 * m), "V = π(", ") m³")
        if not (1 <= c < 10):
            wrongs[M + "1"] = {sf_text(c, 3 * m, rounded, "V = π(", ") m³")}
        # (4/3)d³, the diameter cubed in place of the radius.
        dr, dk = sf_norm(d ** 3 * sp.Rational(4, 3) * sp.Rational(10) ** (3 * m))
        wrongs[SF_T + "14"] = {sf_text(dr, dk, rounded, "V = π(", ") m³")}
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, trap, steps=(2, 5))
    sf_steps(q)
    return None, None


def sig_v2(x):
    """x rounded early, to 2 s.f."""
    return sp.Rational(sig3(x, 2))


# ── Exact trig (t3-exact-values, t3-identity-values, t3-trig-equation, FAL-727) ──
# Exact values as the game writes them, read back and worked out again with SymPy from what the
# question shows. An angle in the export is the multiple of π.

TR_FN = {"sin": sp.sin, "cos": sp.cos, "tan": sp.tan}


def tr_read(text):
    """A value as the game writes it: "−√3/2", "(1 + √3)/2", "5√2/2", "7/2"."""
    t = text.strip().replace("−", "-")
    t = re.sub(r"(\d)√(\d+)", r"\1*sqrt(\2)", t)
    t = re.sub(r"√(\d+)", r"sqrt(\1)", t)
    return sp.sympify(t, rational=True)


def tr_text(v):
    """The checker's own writing of a + b√r, with the root on top."""
    v = sp.radsimp(sp.expand(sp.simplify(v)))
    if v.has(sp.Float):  # only a float needs it: on 24 − 3√3/2, nsimplify gives a power tower
        v = sp.nsimplify(v)
    a, b, r = sp.Integer(0), sp.Integer(0), None
    for term in sp.Add.make_args(sp.expand(v)):
        if term.is_Rational:
            a += term
            continue
        c, rest = term.as_coeff_Mul()
        need(rest.is_Pow and rest.exp == sp.Rational(1, 2) and rest.base.is_Integer, f"{v} is not a + b√r")
        need(r is None or r == rest.base, f"{v} has two surds")
        b, r = c, rest.base
    if b == 0:
        return frac_text(a)
    d = sp.ilcm(a.q, b.q)
    ai, bi = int(a * d), int(b * d)
    unit = lambda n: ("" if n == 1 else str(n)) + f"√{r}"
    if ai == 0:
        return ("−" if bi < 0 else "") + unit(abs(bi)) + ("" if d == 1 else f"/{d}")
    two = f"{frac_text(sp.Integer(ai))} {'+' if bi > 0 else '−'} {unit(abs(bi))}"
    return two if d == 1 else f"({two})/{d}"


def tr_angle(t, form="pi"):
    t = R(t)
    if form == "deg":
        return dec_text(t * 180) + "°"
    return as_pi(t) if t != 0 else "0"


def tr_call(fn, t, form="pi"):
    return f"{fn} {tr_angle(t, form)}" if form == "deg" else f"{fn}({tr_angle(t, form)})"


def tr_of(fn, t):
    return TR_FN[fn](R(t) * sp.pi)


def tr_hyphens(q):
    for tx in [q["asked"]] + q["lines"] + [str(st) for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z])-\d", tx), f"a hyphen for a minus in {tx!r}")


def tr_common(q, label, v, wrongs, tail="", steps=(2, 10), read=None):
    """The answer is label + the value + tail. Every option is checked by value too, so a wrong
    option can't be the right value written another way."""
    want = label + tr_text(v) + tail
    tr_hyphens(q)
    gc_check_common(q, want, {k: {label + tr_text(w) + tail for w in vs} for k, vs in wrongs.items()}, steps=steps)
    for o in q["choices"]:
        body = o["text"]
        need(body.startswith(label) and body.endswith(tail), f"option {body!r} has another shape")
        x = tr_read(body[len(label):len(body) - len(tail) if tail else None])
        need(sp.simplify(x - v) == 0 if o["correct"] else sp.simplify(x - v) != 0, f"option {body!r} has the wrong value")


def tr_claim(q, right, wrongs, steps=(2, 6)):
    tr_hyphens(q)
    gc_check_common(q, right, wrongs, steps=steps)


TR_ROUND = {sp.Rational(*p) for p in [(2, 3), (3, 4), (5, 6), (7, 6), (5, 4), (4, 3), (5, 3), (7, 4), (11, 6)]}
TR_FAR = {sp.Rational(*p) for p in [(-1, 6), (-1, 4), (-1, 3), (-2, 3), (-3, 4), (-5, 6), (13, 6), (9, 4), (7, 3)]}
TR_ACUTE = {sp.Rational(1, 6), sp.Rational(1, 4), sp.Rational(1, 3)}
TR_SPECIAL = TR_ACUTE | {sp.Integer(0), sp.Rational(1, 2)}


def tr_quadrant(t):
    return int(sp.floor((R(t) % 2) * 2)) + 1


def tr_ref(t):
    """The angle to the nearest x-axis, worked from the unit circle's own folds."""
    u = R(t) % 2
    u = u if u <= 1 else u - 1
    return min(u, 1 - u)


def check_exact_trig(q):
    g, u, rep, L, asked = q["given"], q["view"]["unknown"], q["view"]["rep"], q["lines"], q["asked"]
    need(q["paper"] == 1, "every exact value is Paper 1")
    SW, TS, SF = "SL3.5.exact-special#0", "SL3.5.exact-special#1", "SL3.5.exact-special#2"
    SG, YA, NG = "SL3.5.related-angles#0", "SL3.5.related-angles#1", "SL3.5.related-angles#2"
    CO, CK, TZ = "SL3.5.unit-circle#0", "SL3.5.unit-circle#1", "SL3.5.unit-circle#2"
    US = "t3-exact-values#9"

    def one_surd(x):
        return len({p.base for p in sp.expand(sp.nsimplify(x)).atoms(sp.Pow) if p.exp in (sp.Rational(1, 2), sp.Rational(-1, 2))}) <= 1

    def first_wrongs(fn, t, k=1):
        w = {}
        t = R(t)
        if fn != "tan" and t in (sp.Rational(1, 6), sp.Rational(1, 3)):
            w[SW] = [k * tr_of("cos" if fn == "sin" else "sin", t)]
        if fn == "tan" and t == sp.Rational(1, 6):
            w[TS] = [k * sp.sqrt(3)]
        if fn != "tan" and t == sp.Rational(1, 4):
            w[SF] = [k * sp.Rational(1, 2)]
        return w

    if u == "special-value":
        fn, t = g["fn"], R(g["t"])
        need(t in (TR_ACUTE if rep == "diagram" else TR_SPECIAL), f"{t} is no landmark")
        need(not (fn == "tan" and t == sp.Rational(1, 2)), "tan(π/2) has no value")
        name = tr_call(fn, t, g["form"])
        v = tr_of(fn, t)
        need(g["form"] == "pi" or rep == "equation", "degrees are in the written form")
        if rep == "diagram":
            d = q["diagram"]
            need(abs(math.atan2(d["vertices"]["C"][1], d["vertices"]["B"][0]) - float(t) * math.pi) < 1e-6, "the triangle has another angle")
            need(d["vertices"]["B"][1] == 0 and abs(d["vertices"]["C"][0] - d["vertices"]["B"][0]) < 1e-9, "the triangle isn't right-angled at B")
            labels = {sd["side"]: sd["label"] for sd in d["sides"]}
            a, b, c = tr_read(labels["a"]), tr_read(labels["b"]), tr_read(labels["c"])
            need(sp.simplify(a / c - sp.tan(t * sp.pi)) == 0 and sp.simplify(a**2 + c**2 - b**2) == 0, "the sides don't fit the angle")
            tr_common(q, f"{fn} θ = ", v, first_wrongs(fn, t))
            return None, None
        if rep == "table":
            rows = dict((r[0], r[1]) for r in q["table"]["rows"])
            need(rows["θ"] == ["0", "π/6", "π/4", "π/3", "π/2"], "the table's heads are wrong")
            need(rows[f"{fn} θ"][rows["θ"].index(tr_angle(t))] == "?", "the asked cell is not marked")
            for f, cells in rows.items():
                if f != "θ" and f != f"{fn} θ":
                    for h, c in zip(["0", "1/6", "1/4", "1/3", "1/2"], cells):
                        need(c == tr_text(tr_of(f[:3], h)), f"the table's {f} at {h}π is wrong")
        need(name in asked or rep == "table", f"the question doesn't ask {name}")
        tr_common(q, name + " = ", v, first_wrongs(fn, t))
    elif u == "scaled-value":
        fn, t, k = g["fn"], R(g["t"]), R(g["k"])
        need(t in TR_ACUTE and 2 <= k <= 12, "out of range")
        v = k * tr_of(fn, t)
        ang = tr_angle(t)
        if rep == "equation":
            need(L == [f"f(x) = {k} {fn} x"] and asked == f"Find the exact value of f({ang}).", f"can't read {L}")
            tr_common(q, f"f({ang}) = ", v, first_wrongs(fn, t, k))
        else:
            need(f"h = {k} {fn} θ metres" in L[0] and asked.endswith(f"θ = {ang}."), f"can't read {L}")
            tr_common(q, "h = ", v, first_wrongs(fn, t, k), " m")
    elif u == "special-sum":
        fn, t, fn2, t2, plus, first = g["fn"], R(g["t"]), g["fn2"], R(g["t2"]), g["plus"], R(g["first"])
        sg = 1 if plus else -1
        v = first * tr_of(fn, t)**2 + sg * tr_of(fn2, t2)
        need(L == [f"{'' if first == 1 else first}{fn}²({tr_angle(t)}) {'+' if plus else '−'} {tr_call(fn2, t2)}"], f"can't read {L}")
        w = {}
        if fn != "tan" and t == sp.Rational(1, 4):
            w[SF] = [first * sp.Rational(1, 4) + sg * tr_of(fn2, t2)]
        unsquared = first * tr_of(fn, t) + sg * tr_of(fn2, t2)
        if one_surd(unsquared):
            w[US] = [unsquared]
        tr_common(q, "", v, w)
    elif u == "related-value":
        fn, t = g["fn"], R(g["t"])
        need(t in (TR_ROUND if rep == "graph" else TR_ROUND | TR_FAR), f"{t} is out of range")
        name = tr_call(fn, t)
        need(name in asked, f"the question doesn't ask {name}")
        v = tr_of(fn, t)
        w = {SG: [-v]}
        if t < 0:
            w[NG] = [tr_of(fn, -t)]
        r = tr_ref(t)
        need(sp.simplify(abs(v) - tr_of(fn, r)) == 0, "the reference angle doesn't give the size")
        if r != sp.Rational(1, 4):
            w[YA] = [sp.sign(v) * tr_of(fn, sp.Rational(1, 2) - r)]
        elif fn != "tan":
            w[SF] = [sp.sign(v) * sp.Rational(1, 2)]
        if rep == "diagram":
            p = q["graph"]["points"][0]
            need(abs(p["x"] - math.cos(float(t) * math.pi)) < 1e-9 and abs(p["y"] - math.sin(float(t) * math.pi)) < 1e-9, "P is drawn at another angle")
        elif rep == "graph":
            p = q["graph"]["points"][0]
            need(abs(p["x"] - float(t) * math.pi) < 1e-9 and abs(p["y"] - float(v)) < 1e-9, "P is drawn in another place")
            pts = q["graph"]["curves"][0]
            f = math.sin if fn == "sin" else math.cos
            need(all(abs(y - f(x)) < 1e-9 for x, y in pts), "the curve is another function")
        tr_common(q, name + " = ", v, w)
    elif u == "related-sum":
        fn, t, fn2, t2 = g["fn"], R(g["t"]), g["fn2"], R(g["t2"])
        need(t in TR_ROUND and t2 in TR_ROUND and t != t2, "out of range")
        need(L == [f"{tr_call(fn, t)} + {tr_call(fn2, t2)}"], f"can't read {L}")
        a, b = tr_of(fn, t), tr_of(fn2, t2)
        tr_common(q, "", a + b, {SG: [b - a, a - b, -a - b]}, steps=(2, 10))
    elif u == "given-related":
        gv = sp.Rational(R(g["g"]), R(g["n"]))
        need(0 < gv < 1, "the given ratio is out of range")
        # A numeric acute angle stands in for θ: the sign must hold at any acute θ.
        fn, rule = g["fn"], g["rule"]
        if rep == "diagram":
            need(L[1] == f"sin CAD = {frac_text(gv)}", f"can't read {L}")
            th = q["graph"]["theta"]
            need(abs(math.sin(th) - float(gv)) < 1e-9 and th < math.pi / 2, "the figure has another angle")
            tr_common(q, "sin CAB = ", gv, {SG: [-gv]})
        else:
            need(L == [f"{fn} θ = {frac_text(gv)}, where θ is acute."], f"can't read {L}")
            ang = {"pi-minus": lambda x: sp.pi - x, "pi-plus": lambda x: sp.pi + x, "minus": lambda x: -x}[rule]
            name = {"pi-minus": "π − θ", "pi-plus": "π + θ", "minus": "−θ"}[rule]
            x = sp.Symbol("x", positive=True)
            sign = sp.simplify(TR_FN[fn](ang(x)) / TR_FN[fn](x))
            need(sign in (1, -1), f"{fn} at {name} is no multiple of {fn} θ")
            tr_common(q, f"{fn}({name}) = ", sign * gv, {SG: [-sign * gv]})
    elif u == "point-at-angle":
        t = R(g["t"])
        x, y = tr_of("cos", t), tr_of("sin", t)
        need(tr_angle(t) in L[0], f"can't read {L}")
        want = f"P = ({tr_text(x)}, {tr_text(y)})"
        pw = {CO: {f"P = ({tr_text(y)}, {tr_text(x)})"}, CK: {f"P = ({tr_text(x)}, {tr_text(-y)})"}}
        tr_hyphens(q)
        gc_check_common(q, want, pw)
    elif u in ("ratio-from-point", "tan-from-point"):
        x, y = R(g["x"]), R(g["y"])
        need(x**2 + y**2 == 1, "the point is not on the unit circle")
        need(f"({frac_text(x)}, {frac_text(y)})" in L[0], f"can't read {L}")
        if u == "ratio-from-point":
            fn = g["fn"]
            tr_common(q, f"{fn} θ = ", y if fn == "sin" else x, {CO: [x if fn == "sin" else y]})
        else:
            tr_common(q, "tan θ = ", y / x, {CO: [x / y]})
    elif u == "sign-in-quadrant":
        qd, fn, fn2 = g["q"], g["fn"], g["fn2"]
        th = sp.pi * sp.Rational(2 * qd - 1, 4)
        need(["0 < θ < π/2", "π/2 < θ < π", "π < θ < 3π/2", "3π/2 < θ < 2π"][qd - 1] in L[0], f"can't read {L}")
        text = lambda s1, s2: f"{fn} θ {'>' if s1 > 0 else '<'} 0 and {fn2} θ {'>' if s2 > 0 else '<'} 0"
        a, b = TR_FN[fn](th), TR_FN[fn2](th)
        ma, mb = TR_FN[fn](-th), TR_FN[fn2](-th)
        tr_claim(q, text(a, b), {CK: {text(ma, mb)}})
    elif u == "tan-undefined":
        t = R(g["t"])
        need(sp.cos(t * sp.pi) == 0, "tan has a value there")
        at = tr_angle(t)
        need(asked == f"Why does tan({at}) have no value?", asked)
        tr_claim(q, f"cos({at}) = 0, so sin ÷ cos divides by zero",
                 {TZ: {f"tan({at}) = 0, because the angle is on an axis", f"tan({at}) = 1, because sin and cos are equal there"},
                  CO: {f"sin({at}) = 0, so tan has no value"}})
    else:
        need(False, f"no check for {u}")
    return None, None


def tr_mid(qd):
    """An angle in quadrant qd, to read signs from."""
    return sp.pi * sp.Rational(2 * qd - 1, 4)


def check_trig_identity(q):
    g, u, rep, L, asked = q["given"], q["view"]["unknown"], q["view"]["rep"], q["lines"], q["asked"]
    need(q["paper"] == 1, "every identity question is Paper 1")
    SG, DS, RT = "SL3.6.ratio-from-ratio#0", "SL3.6.ratio-from-ratio#1", "SL3.6.ratio-from-ratio#2"
    S2, C2, LS = "SL3.6.double-angle-values#0", "SL3.6.double-angle-values#1", "SL3.6.double-angle-values#2"
    EX, PR = "SL3.6.simplify#0", "SL3.6.simplify#1"
    O = "t3-identity-values#"  # the type's own lines (FAL-1149)

    def wave(fn, k, n):
        return ("" if k == 1 else f"{k} ") + f"{fn} {'' if n == 1 else n}x"

    def expand(k, b):
        return f"{k} {'+' if b > 0 else '−'} {'' if abs(b) == 1 else str(abs(b)) + ' '}sin 2x"

    def theta():
        """sin θ and cos θ from the shown ratio and quadrant alone."""
        qd = g["q"]
        size = sp.sqrt(R(g["top"])) / R(g["n"])
        need(size < 1, "the given ratio is out of range")
        mid = tr_mid(qd)
        rest = sp.sqrt(1 - size**2)
        if g["fn"] == "sin":
            sv, cv = sp.sign(sp.sin(mid)) * size, sp.sign(sp.cos(mid)) * rest
            shown = sv
        else:
            cv, sv = sp.sign(sp.cos(mid)) * size, sp.sign(sp.sin(mid)) * rest
            shown = cv
        tr_given(f"{g['fn']} θ = {tr_text(shown)}", qd, sv, cv)
        return sv, cv

    def tr_given(head, qd, sv, cv):
        if rep == "diagram":
            need(L[0].startswith(head + ". The point P"), f"can't read {L}")
            p = q["graph"]["points"][0]
            need(abs(p["x"] - float(cv)) < 1e-9 and abs(p["y"] - float(sv)) < 1e-9, "P is drawn in another place")
            need(q["graph"]["quadrant"] == qd, "another quadrant is shaded")
        else:
            need(L == [f"{head} and {['0 < θ < π/2', 'π/2 < θ < π', 'π < θ < 3π/2', '3π/2 < θ < 2π'][qd - 1]}."], f"can't read {L}")

    if u == "cos-from-sin":
        sv, cv = theta()
        tr_common(q, "cos θ = ", cv, {SG: [-cv], DS: [1 - sv], O + "8": [cv**2]})
    elif u == "sin-from-cos":
        sv, cv = theta()
        tr_common(q, "sin θ = ", sv, {SG: [-sv], RT: [sp.sign(sv) * (1 - abs(cv))], O + "8": [sv**2]})
    elif u == "tan-from-ratio":
        sv, cv = theta()
        tr_common(q, "tan θ = ", sv / cv, {SG: [-sv / cv], O + "9": [cv / sv]})
    elif u == "cos-from-tan":
        qd = g["q"]
        t = sp.sign(sp.tan(tr_mid(qd))) * sp.Rational(g["rise"], g["run"])
        cv = sp.sign(sp.cos(tr_mid(qd))) / sp.sqrt(1 + t**2)
        tr_given(f"tan θ = {frac_text(t)}", qd, t * cv, cv)
        # sin θ for cos θ, and rise² + run² taken as the hypotenuse itself
        tr_common(q, "cos θ = ", cv, {SG: [-cv], O + "10": [t * cv],
                                      O + "11": [sp.sign(cv) * sp.Integer(g["run"]) / (g["rise"]**2 + g["run"]**2)]})
    elif u == "sin2-from-ratio":
        sv, cv = theta()
        w = {S2: [2 * sv], O + "12": [sv * cv], O + "13": [cv**2 - sv**2]}
        if cv < 0:
            w[LS] = [2 * sv * abs(cv)]
        tr_common(q, "sin 2θ = ", 2 * sv * cv, w)
    elif u == "cos2-from-sin":
        sv, cv = theta()
        tr_common(q, "cos 2θ = ", cv**2 - sv**2, {C2: [1 - sv**2, 2 * cv, 2 * sv**2 - 1]})
    elif u == "cos2-from-cos":
        sv, cv = theta()
        tr_common(q, "cos 2θ = ", cv**2 - sv**2, {C2: [2 * cv, 1 - 2 * cv**2, cv**2 - 1]})
    elif u == "cos-from-cos2":
        if rep == "diagram":
            a, b, c = R(g["a"]), R(g["b"]), R(g["c"])
            need(L == [f"In triangle ABC, AB = {c} cm, AC = {b} cm, BC = {a} cm and angle BAC = 2θ."], f"can't read {L}")
            need(a < b + c and b < a + c and c < a + b, "no such triangle")
            k = (b**2 + c**2 - a**2) / (2 * b * c)
            v = q["diagram"]["vertices"]
            need(abs(math.hypot(v["C"][0] - v["B"][0], v["C"][1] - v["B"][1]) - float(a)) < 1e-6, "the figure has another side")
        else:
            k = R(g["cos2"])
            need(L == [f"cos 2θ = {frac_text(k)} and 0 < θ < π/2."], f"can't read {L}")
        need(-1 < k < 1 and k != 0, "out of range")
        tr_common(q, "cos θ = ", sp.sqrt((1 + k) / 2), {C2: [k / 2], O + "8": [(1 + k) / 2], SG: [-sp.sqrt((1 + k) / 2)],
                                                     O + "14": [sp.sqrt((1 - k) / 2)]})
    elif u == "rewrite-in-sin":
        base, dbl, p, m, k = g["base"], g["src"] == "double", R(g["p"]), R(g["m"]), R(g["k"])
        x, y = sp.Symbol("x"), sp.Symbol("y")
        other = "cos" if base == "sin" else "sin"
        lead = f"{p} cos 2x" if dbl else f"{p} {other}²x"
        need(L[0].startswith(lead), f"can't read {L}")
        expr = p * (sp.cos(2 * x) if dbl else TR_FN[other](x)**2) + m * TR_FN[base](x) + k
        # The coefficients of the quadratic in u = sin x or cos x, from three values of x.
        a_, b_, c_ = sp.symbols("a_ b_ c_")
        eqs = [sp.Eq(a_ * TR_FN[base](t)**2 + b_ * TR_FN[base](t) + c_, expr.subs(x, t)) for t in (sp.pi / 6, sp.pi / 2, -sp.pi / 2, 0, sp.pi / 3)]
        sol = sp.solve(eqs[:3] if base == "sin" else [eqs[3], sp.Eq(a_ - b_ + c_, expr.subs(x, sp.pi)), eqs[4]], [a_, b_, c_])
        for e in eqs:
            need(sp.simplify(e.lhs.subs(sol) - e.rhs) == 0, "no quadratic fits")
        co = [int(sol[a_]), int(sol[b_]), int(sol[c_])]
        text = lambda c: tr_quad(c, base)
        w = {}
        if dbl:
            w[C2] = {text([int(-p), int(m), int(p + k)] if base == "sin" else [int(p), int(m), int(k)])}
        tr_hyphens(q)
        gc_check_common(q, text(co), w, steps=(2, 10))
    elif u == "single-cos":
        k, w_ = int(g["k"]), int(g["w"])
        inner = "" if w_ == 1 else str(w_)
        x = sp.Symbol("x")
        if g["from"] == "sin":
            need(L == [f"{k} − {2 * k} sin²{inner}x"], f"can't read {L}")
            e = k - 2 * k * sp.sin(w_ * x)**2
        else:
            need(L == [f"{2 * k} cos²{inner}x − {k}"], f"can't read {L}")
            e = 2 * k * sp.cos(w_ * x)**2 - k
        need(sp.simplify(e - k * sp.cos(2 * w_ * x)) == 0, "the identity fails")
        tr_hyphens(q)
        gc_check_common(q, f"{k} cos {2 * w_}x".replace("1 cos", "cos") if k > 1 else f"cos {2 * w_}x",
                        {O + "15": {wave("cos", 2 * k, 2 * w_)}, O + "16": {wave("cos", k, w_)}}, steps=(2, 10))
    elif u == "product-sine":
        k, w_ = int(g["k"]), int(g["w"])
        inner = "" if w_ == 1 else str(w_)
        need(L == [f"{2 * k} sin {inner}x cos {inner}x"], f"can't read {L}")
        x = sp.Symbol("x")
        need(sp.simplify(2 * k * sp.sin(w_ * x) * sp.cos(w_ * x) - k * sp.sin(2 * w_ * x)) == 0, "the identity fails")
        tr_hyphens(q)
        gc_check_common(q, f"{k} sin {2 * w_}x" if k > 1 else f"sin {2 * w_}x", {PR: {f"{2 * k} sin {2 * w_}x"}, O + "16": {wave("sin", k, w_)}}, steps=(2, 10))
    elif u == "expand-square":
        k, minus = int(g["k"]), g["minus"]
        need(L == [f"{'' if k == 1 else k}(sin x {'−' if minus else '+'} cos x)²"], f"can't read {L}")
        x = sp.Symbol("x")
        b = -k if minus else k
        need(sp.simplify(k * (sp.sin(x) + (-1 if minus else 1) * sp.cos(x))**2 - (k + b * sp.sin(2 * x))) == 0, "the identity fails")
        tr_hyphens(q)
        gc_check_common(q, f"{k} {'−' if minus else '+'} {'' if k == 1 else str(k) + ' '}sin 2x", {EX: {str(k)}, O + "17": {expand(k, -b)}, O + "18": {expand(2 * k, b)}, O + "19": {expand(k, 2 * b)}}, steps=(2, 10))
    elif u == "max-after-rewrite":
        k, w_, d = int(g["k"]), int(g["w"]), int(g["d"])
        x = sp.Symbol("x")
        top = sp.maximum(k * sp.sin(2 * w_ * x) + d, x, sp.Interval(0, sp.pi))
        tr_hyphens(q)
        low = sp.minimum(k * sp.sin(2 * w_ * x) + d, x, sp.Interval(0, sp.pi))
        w = {PR: {f"maximum = {frac_text(2 * k + d)}"}, O + "21": {f"maximum = {frac_text(low)}"}}
        if d:
            w[O + "20"] = {f"maximum = {frac_text(top - d)}"}  # the sine part's maximum alone
        gc_check_common(q, f"maximum = {frac_text(top)}", w, steps=(2, 10))
    else:
        need(False, f"no check for {u}")
    return None, None


def tr_quad(c, fn):
    def term(v, body, first):
        size = "" if abs(v) == 1 else f"{abs(v)} "
        if first:
            return ("−" if v < 0 else "") + size + body
        return f" {'+' if v > 0 else '−'} {size}{body}"
    out = term(c[0], f"{fn}²x", True)
    if c[1]:
        out += term(c[1], f"{fn} x", False)
    if c[2]:
        out += f" {'+' if c[2] > 0 else '−'} {abs(c[2])}"
    return out


TQ_NS = {"pi": math.pi, "sqrt": math.sqrt}


def tq_python(text):
    """A side of an equation as the game writes it, as Python: the checker reads what is shown."""
    t = text.replace("−", "-").replace("π", "pi").replace("θ", "x").replace("°", "")
    t = re.sub(r"√(\d+)", r"sqrt(\1)", t)
    t = re.sub(r"(sin|cos|tan)²x", r"\1(x)**2", t)
    t = re.sub(r"(sin|cos|tan) (\d*)x", lambda m: f"{m.group(1)}({m.group(2) + '*' if m.group(2) else ''}x)", t)
    t = re.sub(r"(\d)(x|pi)", r"\1*\2", t)
    t = re.sub(r"(\d|\))\s*(sin|cos|tan|sqrt)", r"\1*\2", t)
    t = t.replace(")(", ")*(")
    return t


def tq_function(line, deg):
    """f(x) = left − right, from the shown equation, in radians or degrees."""
    left, right = [tq_python(p.strip()) for p in line.split(" = ")]
    ns = dict(TQ_NS)
    k = math.pi / 180 if deg else 1.0
    ns["sin"], ns["cos"], ns["tan"] = (lambda u: math.sin(u * k)), (lambda u: math.cos(u * k)), (lambda u: math.tan(u * k))
    code = compile(f"({left}) - ({right})", "shown", "eval")
    return lambda x: eval(code, ns, {"x": x})


def tq_roots(f, lo, hi, open_hi, deg, step):
    """Every root of f on the interval: on a grid of the angles that can come out exactly, and
    any sign change between those that isn't one of them is a failure."""
    n = round((hi - lo) / step)
    roots = []
    grid = [lo + i * step for i in range(n + 1)]
    for x in grid:
        if abs(f(x)) < 1e-9 and not (open_hi and x == grid[-1]):
            roots.append(x)
    fine = 900
    last = None
    limit = 1e6
    for i in range(fine + 1):
        x = lo + (hi - lo) * (i + 0.37) / (fine + 1)
        y = f(x)
        if last is not None and last * y < 0 and abs(y) < limit and abs(last) < limit and abs(y - last) < 3:
            need(any(abs(r - x) < 2 * (hi - lo) / fine for r in roots), f"the equation has a root near {x}")
        last = y
    return roots


def tq_names(roots, deg):
    if deg:
        return [dec_text(sp.Rational(round(x * 2), 2)) + "°" for x in roots]
    names = []
    for x in roots:
        m = sp.Rational(round(x / math.pi * 144), 144)
        need(abs(float(m) * math.pi - x) < 1e-9, f"{x} is no multiple of π")
        names.append(tr_angle(m))
    return names


def tq_list(names):
    if not names:
        return None
    return "x = " + (names[0] if len(names) == 1 else ", ".join(names[:-1]) + " or " + names[-1])


def tq_solve(fn, k, b, phi, lo, hi, open_hi=False, deg=False):
    """fn(bx + φ) = k on an interval given in the unit of x, the checker's own sweep."""
    u = 180.0 if deg else math.pi
    step = 2.5 if deg else math.pi / 144
    g = {"sin": math.sin, "cos": math.cos, "tan": math.tan}[fn]
    pi_ = math.pi
    f = (lambda x: g(b * x * (pi_ / 180) + phi * pi_) - k) if deg else (lambda x: g(b * x + phi * pi_) - k)
    n = round((hi - lo) / step)
    out = []
    for i in range(n + 1):
        x = lo + i * step
        if abs(f(x)) < 1e-9 and not (open_hi and i == n):
            out.append(x)
    return tq_names(out, deg)


def check_trig_equation(q):
    g, u, rep, L, asked = q["given"], q["view"]["unknown"], q["view"]["rep"], q["lines"], q["asked"]
    need(q["paper"] == (2 if u in ("basic-decimal", "compound-decimal") else 1), f"paper {q['paper']} for {u}")
    tr_hyphens(q)
    B0, B1, B2 = "SL3.8.solve-basic#0", "SL3.8.solve-basic#1", "SL3.8.solve-basic#2"
    K0, K1, K2 = "SL3.8.compound-angle#0", "SL3.8.compound-angle#1", "SL3.8.compound-angle#2"
    F0, F1, F2 = "SL3.8.factorise-not-divide#0", "SL3.8.factorise-not-divide#1", "SL3.8.factorise-not-divide#2"
    Q1 = "SL3.8.quadratic-in-trig#1"
    SF = "t3-trig-equation#10"
    deg = g["form"] == "deg"
    if u == "factor-reject":
        m = R(g["m"])
        side = {1: "sin θ cos θ", -1: "−sin θ cos θ"}.get(m, f"{frac_text(m)} sin θ cos θ")
        need(L == [f"sin²θ = {side}, for 0 < θ < π"], f"can't read {L}")
        f = tq_function(L[0].split(",")[0], False)
        t = math.atan2(float(m), 1.0)
        t = t if t > 0 else t + math.pi
        need(abs(f(t)) < 1e-9, "tan θ doesn't solve the equation")
        tr_common(q, "tan θ = ", m, {F1: [1 / m], SF: [-m]})
        return None, None
    if u == "least-positive":
        f = tq_function(L[0], False)
        step = math.pi / 144
        roots = tq_roots(f, step, 8 * math.pi, False, False, step)
        need(len(roots) > 0, "no positive solution")
        want = tq_list(tq_names(roots[:1], False))
        phi, b = float(R(g["phi"])), float(R(g["b"]))
        w = tq_solve(g["fn"], tr_val_float(g["k"]), b, -phi, step, 8 * math.pi)
        gc_check_common(q, want, {K2: {tq_list(w[:1])}} if w else {}, steps=(2, 6))
        return None, None
    line = L[0]
    mt = re.fullmatch(r"(.+), for (.+) ≤ x (≤|<) (.+)", line)
    need(mt is not None, f"can't read {line!r}")
    open_hi = mt.group(3) == "<"
    read_end = lambda e: float(sp.sympify(tq_python(e), {"pi": sp.pi}))
    lo, hi = read_end(mt.group(2)), read_end(mt.group(4))
    need(lo == float(R(g["lo"]) * (180 if deg else sp.pi)) and hi == float(R(g["hi"]) * (180 if deg else sp.pi)), "the interval is another one")
    f = tq_function(mt.group(1), deg)
    if u in ("basic-decimal", "compound-decimal"):
        fn, k, b = g["fn"], R(g["k"]), int(R(g["b"]))
        ks = float(k)
        mpmath.mp.dps = 30
        need(abs(k) < 1 or fn == "tan", "k is out of range")
        base = {"sin": [mpmath.asin(ks), mpmath.pi - mpmath.asin(ks)], "cos": [mpmath.acos(ks), -mpmath.acos(ks)], "tan": [mpmath.atan(ks)]}[fn]
        period = mpmath.pi if fn == "tan" else 2 * mpmath.pi
        xs = sorted({round(float((u0 + n * period) / b), 9) for u0 in base for n in range(-6, 12) if -1e-9 <= (u0 + n * period) / b <= hi + 1e-9})
        need(all(abs(f(x)) < 1e-6 for x in xs), "the solutions don't solve the equation")
        vals = [sp.Float(str(x), 12) for x in xs]
        names = [gc_s(v) for v in vals]
        want = "x = " + (names[0] if len(names) == 1 else ", ".join(names[:-1]) + " or " + names[-1])
        w = {}
        if u == "basic-decimal" and len(xs) > 1:
            w[B0] = {f"x = {names[0]}"}
        if u == "compound-decimal":
            kept = [gc_s(v) for v, x in zip(vals, xs) if x * b <= hi + 1e-9]
            if 0 < len(kept) < len(names):
                w[K0] = {"x = " + (kept[0] if len(kept) == 1 else ", ".join(kept[:-1]) + " or " + kept[-1])}
            if len(xs) > 1:
                w[B0] = {f"x = {names[0]}"}
        gc_check_common(q, want, w, gc_trap(vals, gc_xs2(vals)), steps=(2, 6))
        return None, None
    step = 2.5 if deg else math.pi / 144
    roots = tq_roots(f, lo, hi, open_hi, deg, step)
    need(1 <= len(roots) <= 8, f"{len(roots)} solutions")
    names = tq_names(roots, deg)
    want = tq_list(names)
    w = {}
    fn = g["fn"]
    b, phi = float(R(g["b"])), float(R(g["phi"]))
    ks = tr_val_float(g["k"]) if "k" in g else None
    sv = lambda fn_, k_, bb=1.0, ph=0.0: tq_solve(fn_, k_, bb, ph, lo, hi, open_hi, deg)
    d = math.degrees if deg else (lambda v: v)

    def flip(fn_, k_, bb=1.0, ph=0.0):
        """The shown equation solved for the opposite value, as a set of option texts."""
        alt = sv(fn_, -k_, bb, ph)
        if alt:
            w[SF] = {tq_list(alt)}
    if u in ("basic-exact", "wide-interval", "basic-degrees"):
        need(ks is not None and abs(ks) <= 2, "k is out of range")
        al = {"sin": math.asin, "cos": math.acos, "tan": math.atan}[fn](ks)
        if len(roots) > 1:
            w[B0] = {tq_list(tq_names([d(al)], deg))}
        if fn == "cos":
            pair = sorted({round(v, 9) for v in (d(al), d(math.pi - al)) if lo - 1e-9 <= v <= hi + 1e-9})
            if pair:
                w[B1] = {tq_list(tq_names(pair, deg))}
        if u == "wide-interval" and lo < 0:
            pos = [r for r in roots if r >= -1e-9]
            if pos:
                w[B2] = {tq_list(tq_names(pos, deg))}
        flip(fn, ks, b, phi)
    elif u in ("multiple-angle", "shifted-angle", "degree-compound"):
        al = {"sin": math.asin, "cos": math.acos, "tan": math.atan}[fn](ks)
        ph_x = phi * (180 if deg else math.pi)
        if b > 1:
            kept = [r for r in roots if b * r <= hi + 1e-9]
            if kept and len(kept) < len(roots):
                w[K0] = {tq_list(tq_names(kept, deg))}
            w[K1] = {tq_list(tq_names([(d(al) - ph_x) / b], deg))}
        if phi != 0:
            alt = sv(fn, ks, b, -phi)
            if alt:
                w[K2] = {tq_list(alt)}
        flip(fn, ks, b, phi)
    elif u == "tan-compound":
        w[K1] = {tq_list(tq_names([math.atan(ks) / b], deg))}
        w[F1] = {tq_list(sv("tan", 1 / ks, b, phi))}
        flip("tan", ks, b, phi)
    elif u == "k-cos-to-tan":
        w[F1] = {tq_list(sv("tan", 1 / ks))}
        w[B0] = {tq_list(names[:1])}
        flip("tan", ks)
    elif u == "double-equals-cos":
        w[F0] = {tq_list(sv("sin", ks))}
        # cos x = 0 kept, and sin x solved for the opposite value: the whole list from the
        # factorised equation with the sign of its second bracket changed.
        flipped = tq_roots(lambda x: math.cos(x) * (2 * math.sin(x) + 2 * ks), lo, hi, open_hi, deg, step)
        if flipped:
            w[SF] = {tq_list(tq_names(flipped, deg))}
    elif u == "double-equals-sin":
        w[F0] = {tq_list(sv("cos", ks))}
        if abs(ks - 0.5) < 1e-9:
            w[F2] = {"x = 0"}
    elif u == "product-zero":
        w[F0] = {tq_list(sv(g["f2"], ks))}
    elif u == "squares-to-tan":
        w[Q1] = {tq_list(sv("tan", ks))}
    else:
        need(False, f"no check for {u}")
    gc_check_common(q, want, w, steps=(2, 7))
    if rep == "graph" and u in ("basic-exact", "wide-interval", "multiple-angle", "shifted-angle"):
        need(abs(q["graph"]["hlines"][0]["at"] - ks) < 1e-9, "the dashed line is at another height")
    return None, None


def tr_val_float(v):
    """A value [a, b, r] of the export: a + b√r."""
    return float(R(v[0])) + float(R(v[1])) * math.sqrt(float(v[2]))


TM_CONTEXTS = [("D", "m", "hours"), ("T", "°C", "hours"), ("h", "m", "minutes"), ("L", "m", "days"), ("P", "kW", "minutes"), ("R", "m", "hours")]
TM_P2_ONLY = ("sum-as-cos", "tan-two-points", "wheel-model", "c-from-crossing", "level-from-duration")


def tm_f(v):
    """An exact value as gc_s takes it."""
    return v if isinstance(v, sp.Rational) else sp.Float(sp.N(v, 30), 30)


def tm_named(pairs, sf=True):
    return ", ".join(f"{n} = {gc_s(tm_f(v)) if sf else dec_text(v)}" for n, v in pairs)


def tm_x(paper, v):
    return as_pi(v) if paper == 1 else dec_text(v)


def tm_wave(q):
    """The wave's numbers from its turning points alone, and the figure held to them."""
    g, rep, L, paper = q["given"], q["view"]["rep"], q["lines"], q["paper"]
    top, low, xm, xn = R(g["top"]), R(g["low"]), R(g["xmax"]), R(g["xmin"])
    need(top > low and xn > xm, "the turning points are in the wrong order")
    a, d = (top - low) / 2, (top + low) / 2
    per = 2 * (xn - xm)
    if paper == 1:
        need(a.q == 1 and d.q == 1, "a and d are not whole on Paper 1")
        b = 1 / (per / 2)
        need(b.q == 1, "b is not whole on Paper 1")
        need(R(g["w"]) == b, "the given b is not the turning points' b")
    else:
        need(R(g["period"]) == per, "the given period is not the turning points' period")
        b = 2 * sp.pi / per
    tp = f"({tm_x(paper, xm)}, {dec_text(top)})"
    bp = f"({tm_x(paper, xn)}, {dec_text(low)})"
    if rep == "graph":
        gr = q["graph"]
        need([p["label"] for p in gr["points"]] == [f"max {tp}", f"min {bp}"], "the turning points are labelled wrongly")
        s = math.pi if paper == 1 else 1.0
        bf = float(b)
        pts = gr["curves"][0]
        for x, y in pts[::17]:
            need(abs(y - (float(a) * math.cos(bf * (x - float(xm) * s)) + float(d))) < 1e-6, "the curve is another wave")
    elif rep == "words":
        c = TM_CONTEXTS[g["ctx"]]
        need(L[1] == f"Its largest value is {dec_text(top)} {c[1]}, at t = {dec_text(xm)}, and its next smallest value is {dec_text(low)} {c[1]}, at t = {dec_text(xn)}.", f"can't read {L}")
    else:
        need(L[1] == f"A maximum is at {tp} and the next minimum at {bp}.", f"can't read {L}")
    return a, b, d, xm, xn, per


def tm_num(q, label, v, wrongs, steps=(2, 7)):
    v = tm_f(v)
    want = label + gc_s(v)
    gc_check_common(q, want, {k: {label + gc_s(tm_f(w)) for w in vs} for k, vs in wrongs.items()}, gc_trap([v], label + gc_s2(v)), steps=steps)


def tm_c_text(paper, v):
    return "c = " + (as_pi(v) if paper == 1 else dec_text(v))


def check_trig_model(q):
    g, u, rep, L, asked, paper = q["given"], q["view"]["unknown"], q["view"]["rep"], q["lines"], q["asked"], q["paper"]
    need(paper == (1 if u == "q-from-minimum" else 2) if u == "q-from-minimum" or u in TM_P2_ONLY else paper in (1, 2), f"paper {paper} for {u}")
    need(rep != "words" or paper == 2, "a story is Paper 2")
    PG, NH, CS = "SL3.7.equation-from-graph#0", "SL3.7.equation-from-graph#1", "SL3.7.equation-from-graph#2"
    SB, ST, RG = "SL3.7.transformations#0", "SL3.7.transformations#1", "SL3.7.transformations#2"
    DG, PB = "SL3.7.model-context#0", "SL3.7.model-context#2"
    O = lambda i: f"t3-trig-model-parameters#{i}"  # the type's own slips (FAL-1149)
    tr_hyphens(q)
    if u == "amp-axis":
        a, b, d, *_ = tm_wave(q)
        gc_check_common(q, tm_named([("a", a), ("d", d)], False), {NH: {tm_named([("a", 2 * a), ("d", d)], False)}, O(8): {tm_named([("a", d), ("d", a)], False)}})
    elif u == "b-from-period":
        a, b, d, xm, xn, per = tm_wave(q)
        if paper == 1:
            gc_check_common(q, f"b = {dec_text(b)}", {PG: {f"b = {dec_text(2 * b)}"}})
        else:
            tm_num(q, "b = ", b, {PG: [2 * b], PB: [per], O(9): [per / (2 * sp.pi)]})
    elif u == "c-cos-from-max":
        a, b, d, xm, xn, per = tm_wave(q)
        need(0 < xm < per, "c is not the smallest positive")
        gc_check_common(q, tm_c_text(paper, xm), {CS: {tm_c_text(paper, -xm)}, O(10): {tm_c_text(paper, xn)}})
    elif u == "c-sine-shift":
        a, b, d, xm, xn, per = tm_wave(q)
        c = xm - per / 4
        need(0 < c < per, "c is not the smallest positive")
        gc_check_common(q, tm_c_text(paper, c), {CS: {tm_c_text(paper, -c)}, O(11): {tm_c_text(paper, xm)}, O(12): {tm_c_text(paper, xm + per / 4)}})
    elif u == "all-four":
        a, b, d, xm, xn, per = tm_wave(q)
        if paper == 1:
            t = lambda a_, b_, c_, d_: f"a = {dec_text(a_)}, b = {dec_text(b_)}, c = {as_pi(c_)}, d = {dec_text(d_)}"
        else:
            t = lambda a_, b_, c_, d_: tm_named([("a", a_), ("b", b_), ("c", c_), ("d", d_)])
        gc_check_common(q, t(a, b, xm, d), {NH: {t(2 * a, b, xm, d)}, PG: {t(a, 2 * b, xm, d)}, CS: {t(a, b, -xm, d)},
                                            O(10): {t(a, b, xn, d)}, O(8): {t(d, b, xm, a)}}, steps=(2, 6))
    elif u == "q-from-minimum":
        p, m, phi, fn = R(g["p"]), R(g["m"]), R(g["phi"]), g["fn"]
        need(L[0] == f"f(x) = {p} {fn}(x + {as_pi(phi)}) + q", f"can't read {L}")
        qv = m + p
        # q taken as the minimum; the exact value's sign flipped; it not multiplied by p; q alone.
        tr_common(q, "f(0) = ", p * tr_of(fn, phi) + qv, {O(13): [p * tr_of(fn, phi) + m], O(14): [-p * tr_of(fn, phi) + qv],
                                                          O(15): [tr_of(fn, phi) + qv], O(16): [qv]})
    elif u == "sum-as-cos":
        p, q0, k = R(g["p"]), R(g["q0"]), R(g["k"])
        ks = "" if k == 1 else str(k)
        need(L[0] == f"g(x) = {p} sin {ks}x + {q0} cos {ks}x", f"can't read {L}")
        x = sp.Symbol("x")
        amp = sp.sqrt(p**2 + q0**2)
        c = sp.atan2(p, q0) / k
        need(sp.simplify(p * sp.sin(k * x) + q0 * sp.cos(k * x) - amp * sp.cos(k * (x - c))).equals(0) in (True, None), "the two forms differ")
        for t_ in (0.3, 1.1):
            need(abs(float(p) * math.sin(float(k) * t_) + float(q0) * math.cos(float(k) * t_) - float(amp) * math.cos(float(k) * (t_ - float(c)))) < 1e-9, "the two forms differ")
        t = lambda a_, c_: tm_named([("a", a_), ("b", k), ("c", c_)])
        gc_check_common(q, t(amp, c), {NH: {t(2 * amp, c)}, CS: {t(amp, -c)}, O(17): {t(p + q0, c)}}, steps=(2, 6))
    elif u == "tan-two-points":
        z, h, v = R(g["z"]), R(g["h"]), R(g["v"])
        need(h < z / 2, "the point is past the asymptote")
        b = sp.pi / z
        a = v / sp.tan(b * h)
        b2 = 2 * sp.pi / z
        t = lambda a_, b_: tm_named([("a", a_), ("b", b_)])
        # tan's period taken as 2π; a = y ÷ x as for a line; tan(bh) worked in degrees.
        gc_check_common(q, t(a, b), {O(18): {t(v / sp.tan(b2 * h), b2)}, O(19): {t(v / h, b)}, DG: {t(v / sp.tan(b * h * sp.pi / 180), b)}}, steps=(2, 6))
    elif u == "shift-from-bracket":
        bw, phi, right = R(g["bw"]), R(g["phi"]), g["right"]
        c = phi / bw if right else -phi / bw
        phi_s = phi if right else -phi
        need(f"{bw}x {'−' if right else '+'} {tm_x(paper, phi)}" in L[0], f"can't read {L}")
        ct = lambda v: "c = " + tm_x(paper, v)
        gc_check_common(q, ct(c), {SB: {ct(phi_s)}, RG: {ct(-c)}, O(20): {ct(phi_s * bw)}})
    elif u == "image-equation":
        amp, bw, lift, fn = int(g["amp"]), int(g["bw"]), int(g["lift"]), g["fn"]
        need(L[0] == f"f(x) = {amp} {fn}({bw}x) {'+' if lift > 0 else '−'} {abs(lift)}", f"can't read {L}")
        tail = lambda v: "" if v == 0 else f" {'+' if v > 0 else '−'} {abs(v)}"
        if g["kind"] == "translate":
            c, up = R(g["mv"]), int(g["up"])
            need(f"({tm_x(paper, c)}, {frac_text(up)})" in L[1] or rep == "words", f"can't read {L}")
            img = lambda v: f"g(x) = {amp} {fn}({bw}(x {'−' if v > 0 else '+'} {tm_x(paper, abs(v))})){tail(lift + up)}"
            down = f"g(x) = {amp} {fn}({bw}(x {'−' if c > 0 else '+'} {tm_x(paper, abs(c))})){tail(lift - up)}"
            gc_check_common(q, img(c), {RG: {img(-c)}, O(21): {down}})
        else:
            sf = int(g["sf"])
            d = sp.Rational(bw, sf)
            dt = dec_text(d) if d.q == 1 else f"({frac_text(d)})"
            gc_check_common(q, f"g(x) = {amp} {fn}({bw * sf}x){tail(lift)}", {ST: {f"g(x) = {amp} {fn}({dt}x){tail(lift)}"}})
    elif u == "describe-transformations":
        amp, bw, lift, fn, phi, right = int(g["amp"]), int(g["bw"]), int(g["lift"]), g["fn"], R(g["phi"]), g["right"]
        need(L[0] == f"y = {amp} {fn}({bw}x {'−' if right else '+'} {tm_x(paper, phi)}) {'+' if lift > 0 else '−'} {abs(lift)}", f"can't read {L}")
        c = phi / bw if right else -phi / bw
        t = lambda sf, v: f"A vertical stretch with scale factor {amp}, a horizontal stretch with scale factor {sf}, then a translation by ({tm_x(paper, v)}, {frac_text(lift)})"
        # The image of a test point under the right chain must be on the graph.
        x0 = 0.4
        f0 = {"sin": math.sin, "cos": math.cos}[fn]
        s_ = math.pi if paper == 1 else 1.0
        need(abs(amp * f0(x0) + lift - (amp * f0(bw * (x0 / bw + float(c) * s_) - (float(phi) * s_ if right else -float(phi) * s_)) + lift)) < 1e-9, "the chain is not the graph")
        gc_check_common(q, t(f"1/{bw}", c), {SB: {t(f"1/{bw}", phi if right else -phi)}, ST: {t(str(bw), c)}, RG: {t(f"1/{bw}", -c)}})
    elif u == "pq-from-translation":
        amp, bw, up, fn, phi, right = int(g["amp"]), int(g["bw"]), int(g["up"]), g["fn"], R(g["phi"]), g["right"]
        p = phi / bw if right else -phi / bw
        t = lambda p_, q_: f"p = {tm_x(paper, p_)}, q = {frac_text(q_)}"
        need(L[0] == f"f(x) = {amp} {fn}({bw}x)", f"can't read {L}")
        gc_check_common(q, t(p, up), {SB: {t(phi if right else -phi, up)}, RG: {t(-p, up)}, O(21): {t(p, -up)}})
    elif u == "wheel-model":
        dia, base, per = R(g["dia"]), R(g["base"]), R(g["period"])
        if rep == "words":
            need(L[0] == f"A wheel of diameter {dia} m turns once every {dec_text(per)} minutes. Its lowest seat passes {base} m above the ground, and a seat starts at the lowest point at t = 0.", f"can't read {L}")
        else:
            pts = q["graph"]["points"]
            need(abs(pts[0]["y"] - float(base)) < 1e-9 and abs(pts[1]["y"] - float(base + dia)) < 1e-9 and abs(pts[1]["x"] - float(per) / 2) < 1e-9, "the figure has other numbers")
        a, b, d = -dia / 2, 2 * sp.pi / per, base + dia / 2
        t = lambda b_: tm_named([("a", a), ("b", b_), ("d", d)])
        r_ = dia / 2
        gc_check_common(q, t(b), {PB: {t(per)}, PG: {t(2 * b)}, NH: {tm_named([("a", -dia), ("b", b), ("d", d)])},
                                  O(22): {tm_named([("a", r_), ("b", b), ("d", d)])}, O(23): {tm_named([("a", a), ("b", b), ("d", r_)])}})
    elif u == "c-from-crossing":
        top, low, t1, level, per = R(g["top"]), R(g["low"]), R(g["t1"]), R(g["level"]), R(g["period"])
        a, d = (top - low) / 2, (top + low) / 2
        with mpmath.workdps(40):
            r = sp.Rational(level - d) / a
            need(abs(r) < 1, "the level is out of range")
            b = 2 * sp.pi / per
            c = t1 - sp.asin(r) / b
            cd = t1 - (sp.asin(r) * 180 / sp.pi) / b
            need(abs(sp.N(a * sp.sin(b * (t1 - c)) + d - level)) < 1e-20, "the crossing is wrong")
            need(sp.N(sp.cos(b * (t1 - c))) > 0, "the model is not rising there")
            # The angle added, t − c given as c, and sin⁻¹ left out.
            tm_num(q, "c = ", c, {DG: [cd], O(24): [t1 + sp.asin(r) / b], O(25): [sp.asin(r) / b], O(26): [t1 - r / b]})
    elif u == "level-from-duration":
        top, low, width, per, xm = R(g["top"]), R(g["low"]), R(g["width"]), R(g["period"]), R(g["xmax"])
        a, d = (top - low) / 2, (top + low) / 2
        b = 2 * sp.pi / per
        need(0 < width < per, "the time above k is out of range")
        k = a * sp.cos(b * width / 2) + d
        kd = a * sp.cos(b * width / 2 * sp.pi / 180) + d
        # The whole time from the peak, half of it from the minimum, and sin for cos.
        tm_num(q, "k = ", k, {DG: [kd], O(27): [a * sp.cos(b * width) + d], O(28): [d - a * sp.cos(b * width / 2)], O(29): [a * sp.sin(b * width / 2) + d]})
    else:
        need(False, f"no check for {u}")
    return None, None


# ── geometric-sequence (t1-geometric-sequence, t1-sum-to-infinity, FAL-728) ──
# The `geometric-sequence` situation's clean limits, the checker's own copy: the engine's is
# in game/engine/situations/geometric_sequence.gd. Each answer is found again from the numbers
# with exact rationals or SymPy's solvers, with no code shared with the engine, and each
# misconception's wrong value is worked out from what the slip does.

GS13, GS18 = "SL1.3.", "SL1.8."
GS_O, SI_O = "t1-geometric-sequence#", "t1-sum-to-infinity#"  # the types' own slips (FAL-820)
GS_LIMIT = {1: 200000, 2: 5000000}
GS_DEN_MAX = 6561
GS_EDGE = sp.Rational(19, 1000)         # the engine's is 0.02; a hair under it, for float ties
GS_BALLS = ["rubber ball", "steel spring", "salvaged drone shell", "scrap tyre"]
GS_P2 = ("gdc-seq", "gdc-solver", "gdc-sum-seq", "gdc-sigma", "partial-sums")


def gs_work(v, n=6):
    t = sig3(v, n).replace("-", "−")
    return t.rstrip("0").rstrip(".") if "." in t else t


def gs_x(p, v):
    """A number as the question writes it."""
    v = sp.Rational(v)
    if p == 1:
        return frac_text(v)
    t = dec_text(v)
    return t if len(t) <= 9 and "/" not in t else gs_work(v)


def gs_ends(v):
    """v is whole, or 3 s.f. write it exactly."""
    return v.is_rational and (v.q == 1 or sp.Rational(sig3(v)) == v)


def gs_show(p, vals):
    if p == 1:
        return "frac"
    return "dec" if all(gs_ends(v) for v in vals) else "sf"


def gs_text(show, v):
    if v == 0:
        return "0"
    if show == "frac":
        return frac_text(v)
    if show == "dec":
        t = dec_text(v) if v.is_rational else "/"
        # A Paper 2 option never reads as a fraction or a long decimal.
        return t if v.is_rational and (v.q == 1 or ("/" not in t and len(t) <= 8)) else dec_text(sp.Rational(sig3(v)))
    return sig3(v).replace("-", "−")


def gs_clear(x):
    v = abs(num(x))
    if v == 0:
        return True
    e = sp.floor(sp.log(v, 10))
    scaled = v / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= GS_EDGE


def gs_num(paper, vals):
    """The clean limits on an answer."""
    for v in vals:
        need(abs(num(v)) <= GS_LIMIT[paper], f"{float(v)} is too large for Paper {paper}")
        if paper == 1:
            need(v.is_rational and v.q <= GS_DEN_MAX, f"{v} is not a clean Paper 1 value")
        elif not gs_ends(v):
            need(gs_clear(v), f"{float(v):.6f} is on a rounding edge")


def gs_trap(show, label, v, unit=""):
    if show != "sf":
        return None
    return label + dec_text(sp.Rational(sig3(v, 2))) + unit


def gs_u(k):
    return "u" + str(k).translate(str.maketrans("0123456789", "₀₁₂₃₄₅₆₇₈₉"))


def gs_s(k):
    return "S" + str(k).translate(str.maketrans("0123456789", "₀₁₂₃₄₅₆₇₈₉"))


def gs_sum(u1, r, n):
    """Added term by term, not from the formula."""
    return sum((u1 * r ** i for i in range(n)), sp.Integer(0))


def gs_inf(u1, r):
    """The limit of the partial sums, as SymPy finds it."""
    m = sp.Symbol("m", positive=True, integer=True)
    return sp.limit(u1 * (1 - abs(r) ** m) / (1 - r), m, sp.oo)


def gs_xs_text(p, name, vals):
    vals = sorted(vals, key=lambda v: num(v))
    show = gs_show(p, vals)
    return f"{name} = " + " or ".join(gs_text(show, v) for v in vals), show


def gs_named(show, names, vals):
    return ", ".join(f"{n} = {gs_text(show, v)}" for n, v in zip(names, vals))


def gs_terms(p, u1, r, k=4):
    return ", ".join(gs_x(p, u1 * r ** i) for i in range(k)) + ", …"


def gs_expr(a, b):
    """a·k + b as the game writes it, read back with SymPy for the checker's own use."""
    return a * sp.Symbol("k") + b


def gs_seq_shown(q, u1, r, k=4):
    """What is shown is the sequence: notation, terms, table or dots."""
    rep, L, p = q["view"]["rep"], q["lines"], q["paper"]
    if rep == "notation":
        need(L[0] == f"u₁ = {gs_x(p, u1)},  r = {gs_x(p, r)}", f"the notation shows {L[0]!r}")
    elif rep == "terms":
        need(L[0] == gs_terms(p, u1, r, k), f"the terms show {L[0]!r}")
    elif rep == "table":
        rows = q["table"]["rows"]
        need(rows == [["n", [str(i + 1) for i in range(k)]], ["uₙ", [gs_x(p, u1 * r ** i) for i in range(k)]]], "the table is not the sequence")
    elif rep == "graph":
        pts = q["graph"]["points"]
        need(len(pts) == k and all(sp.nsimplify(pt["y"]) == u1 * r ** i and pt["x"] == i + 1 for i, pt in enumerate(pts)), "the dots are not the sequence")
        need(q["graph"]["y1"] >= max(pt["y"] for pt in pts), "a dot is off the graph")


def gs_series_shown(q, u1, r, last):
    p = q["paper"]
    second, third = u1 * r, u1 * r ** 2
    bits = gs_x(p, u1) + "".join((" − " if v < 0 else " + ") + gs_x(p, abs(v)) for v in (second, third))
    want = bits + " + … " + ("− " if last < 0 else "+ ") + gs_x(p, abs(last))
    need(q["lines"][0] == want, f"the series shows {q['lines'][0]!r}, not {want!r}")


def gs_sigma_text(p, c, b, lower, shift, upper):
    tail = "k" if shift == 0 else (f"(k − {-shift})" if shift < 0 else f"(k + {shift})")
    top = "∞" if upper < 0 else str(upper)
    return f"Σ (k = {lower} to {top}) {gs_x(p, c)}({gs_x(p, b)})^{tail}"


def check_geometric(q):
    g, v, L, asked, paper = q["given"], q["view"], q["lines"], q["asked"], q["paper"]
    u, rep, angle = v["unknown"], v["rep"], v["angle"]
    need(angle not in GS_P2 or paper == 2, f"{angle} is Paper 2 only")
    if u in ("term-exact", "sum-exact", "sum-closed-form", "sum-of-sums", "sum-alternating", "x-from-log-series"):
        need(paper == 1, f"{u} is Paper 1")
    if u in ("coefficients-geometric", "exists-table", "deposit-for-target"):
        need(paper == 2, f"{u} is Paper 2")
    has = lambda k: k in g
    u1 = R(g["u1"]) if has("u1") else None
    r = R(g["r"]) if has("r") else None
    n = int(g["n"]) if has("n") else None
    wrongs, trap, want = {}, None, None

    def one(label, x, unit=""):
        """The answer as one number: its text, trap and how a wrong value reads."""
        nonlocal want, trap
        gs_num(paper, [x])
        show = gs_show(paper, [x])
        want = label + gs_text(show, x) + unit
        trap = gs_trap(show, label, x, unit)
        return lambda w: label + gs_text(show, w) + unit

    if u == "r-from-terms":
        gs_seq_shown(q, u1, r)
        need(asked == "Find the common ratio r.", f"asked {asked!r}")
        t = one("r = ", (u1 * r) / u1)
        wrongs[GS13 + "nth-term#2"] = {t(u1 / (u1 * r)), t(u1 * r - u1)}
        wrongs[GS13 + "find-r-u1#0"] = {t(u1 * r ** 2 - u1 * r)}  # u₃ − u₂, a difference
    elif u in ("term-from-u1-r", "term-exact"):
        gs_seq_shown(q, u1, r)
        need(asked == (f"Find {gs_u(n)}." if u == "term-from-u1-r" else f"Find the exact value of {gs_u(n)}."), f"asked {asked!r}")
        need(5 <= n <= 9, "n is outside 5 to 9")
        val = u1
        for _ in range(n - 1):
            val *= r
        t = one(gs_u(n) + " = ", val)
        wrongs[GS13 + "nth-term#0"] = {t(val * r)}
        wrongs[GS13 + "nth-term#1"] = {t((u1 * r) ** (n - 1))}
        wrongs[GS_O + "13"] = {t(val / r)}  # one power too few
        wrongs[GS_O + "14"] = {t(u1 * r * (n - 1))}  # times the power, not to it
    elif u == "general-term":
        gs_seq_shown(q, u1, r)
        exp_form = angle == "exponential-form"
        need(asked == ("Find an expression for uₙ in the form a × b^n." if exp_form else "Find an expression for uₙ in terms of n."), f"asked {asked!r}")
        a = u1 / r if exp_form else u1
        tail = "n" if exp_form else "(n − 1)"
        br = lambda x: f"({gs_x(paper, x)})" if x < 0 or "/" in gs_x(paper, x) else gs_x(paper, x)
        rl = lambda c, b, e: f"{gs_x(paper, c)} × {br(b)}^{e}"
        want = "uₙ = " + rl(a, r, tail)
        # The rule is right: it gives the first three terms.
        for k in (1, 2, 3):
            need(a * r ** (k if exp_form else k - 1) == u1 * r ** (k - 1), "the rule misses a term")
        wrongs[GS13 + "nth-term#0"] = {"uₙ = " + rl(u1, r, "n")}
        wrongs[GS13 + "nth-term#1"] = {f"uₙ = {br(u1 * r)}^(n − 1)"}
        if not exp_form:
            wrongs[GS_O + "15"] = {"uₙ = " + rl(r, u1, tail)}  # u₁ and r swapped
    elif u in ("r-odd-gap", "r-even-gap", "u1-from-two-terms", "term-choose-sign"):
        pp, qq = int(g["p"]), int(g["q"])
        up, uq = R(g["up"]), R(g["uq"])
        gap = qq - pp
        need(gap % 2 == (0 if u in ("r-even-gap", "term-choose-sign") else 1), f"the gap {gap} is the wrong parity")
        need(up == u1 * r ** (pp - 1) and uq == u1 * r ** (qq - 1), "the given terms are not the sequence's")
        x = sp.Symbol("x", real=True)
        roots = sorted(sp.real_roots(sp.Poly(x ** gap * up - uq, x)), key=num)
        need(all(ro.is_rational for ro in roots), "r is not rational")
        if u == "term-choose-sign":
            m = int(g["m"])
            need((m - pp) % 2 == 1 and up > 0, "the far term doesn't settle the sign")
            neg = r < 0
            want_line = f"{gs_u(pp)} = {gs_x(paper, up)},  {gs_u(qq)} = {gs_x(paper, uq)},  {gs_u(m)} {'<' if neg else '>'} 0"
            if rep == "notation":
                need(L[0] == want_line, f"line {L[0]!r}")
            else:
                need(L[0].endswith(f"term is {'negative' if neg else 'positive'}."), f"line {L[0]!r}")
            # The far term's sign picks one root.
            keep = [ro for ro in roots if (ro < 0) == neg]
            need(len(keep) == 1, "the sign doesn't pick one root")
            need(n == qq + 1 and asked == f"Find {gs_u(n)}.", f"asked {asked!r}")
            val = uq * keep[0]
            t = one(gs_u(n) + " = ", val)
            if neg:
                wrongs[GS13 + "find-r-u1#1"] = {t(-val)}
            else:
                wrongs[GS_O + "21"] = {t(-val)}  # the root of the sign ruled out
            wrongs[GS13 + "find-r-u1#0"] = {t(uq + (uq - up) / gap)}  # a common difference
            wrongs[GS_O + "16"] = {t(uq * uq / up)}  # r^gap, no root
            wrongs[GS13 + "nth-term#0"] = {t(val * keep[0])}  # one step too far
        else:
            if rep == "notation":
                need(L[0] == f"{gs_u(pp)} = {gs_x(paper, up)},  {gs_u(qq)} = {gs_x(paper, uq)}", f"line {L[0]!r}")
            else:
                need(L[0] == f"The {bn_ordinal(pp)} term of a geometric sequence is {gs_x(paper, up)} and the {bn_ordinal(qq)} term is {gs_x(paper, uq)}.", f"line {L[0]!r}")
            if u == "r-odd-gap":
                need(len(roots) == 1 and asked == "Find r.", "an odd gap has one r")
                t = one("r = ", roots[0])
                wrongs[GS13 + "find-r-u1#0"] = {t((uq - up) / gap)}
                wrongs[GS_O + "16"] = {t(uq / up)}  # no root
                wrongs[GS_O + "17"] = {t(uq / up / gap)}  # divided by the gap
                if paper == 2 and uq / up > 0:
                    wrongs[GS13 + "find-r-u1#2"] = {t(sp.Rational(str(round(float(num((uq / up) ** sp.Rational(1, gap + 1))), 9))))}
            elif u == "r-even-gap":
                need(len(roots) == 2 and roots[0] == -roots[1] and asked == "Find the possible values of r.", "an even gap has ±r")
                gs_num(paper, roots)
                want, show = gs_xs_text(paper, "r", roots)
                wrongs[GS13 + "find-r-u1#1"] = {f"r = {gs_text(show, roots[1])}"}
                wrongs[GS13 + "find-r-u1#0"] = {f"r = {gs_text(show, (uq - up) / gap)}"}
                wrongs[GS_O + "16"] = {f"r = {gs_text(show, uq / up)}", gs_xs_text_as(show, "r", [uq / up, -uq / up])}  # no root
            else:
                need(len(roots) == 1 and asked == "Find u₁.", "an odd gap has one r")
                val = up / roots[0] ** (pp - 1)
                t = one("u₁ = ", val)
                wrongs[GS13 + "find-r-u1#2"] = {t(up / roots[0] ** pp)}
                wrongs[GS_O + "18"] = {t(up * roots[0] ** (pp - 1))}  # multiplied going back
                if pp != 2:
                    wrongs[GS_O + "19"] = {t(up / roots[0])}  # divided once
                wrongs[GS_O + "20"] = {t(roots[0])}  # r for u₁
                wrongs[GS13 + "find-r-u1#0"] = {t(up - (pp - 1) * roots[0])}  # r as a difference
    elif u == "interior-terms":
        a, b = R(g["first"]), R(g["fourth"])
        need(a > 0 and b > 0, "the outer terms are not positive")
        root = sp.real_root(b / a, 3)
        p1, p2 = a * root, a * root ** 2
        ax, bx = gs_x(paper, a), gs_x(paper, b)
        need(L[0] == (f"{ax}, p, q, {bx}" if rep == "terms" else f"The numbers {ax}, p, q and {bx} are four consecutive terms of a geometric sequence."), f"line {L[0]!r}")
        if paper == 1:
            need(root.is_rational and p1.q == 1 and p2.q == 1, "Paper 1's four terms are not whole")
        else:
            need(not root.is_rational, "Paper 2's ratio is not a surd")
        gs_num(paper, [p1, p2])
        show = gs_show(paper, [sp.nsimplify(p1), sp.nsimplify(p2)])
        names = ["p", "q"]
        want = gs_named(show, names, [p1, p2])
        third = (b - a) / 3
        wrongs[GS13 + "find-r-u1#0"] = {gs_named(show, names, [a + third, a + 2 * third])}
        wrongs[GS_O + "22"] = {gs_named(show, names, [p2, p1])}  # p and q swapped
        if paper == 2:
            r4 = (b / a) ** sp.Rational(1, 4)
            wrongs[GS13 + "find-r-u1#2"] = {gs_named(show, names, [a * r4, a * r4 ** 2])}
    elif u == "k-consecutive":
        e = [int(t) for t in g["e"]]
        k = sp.Symbol("k")
        t1, t2, t3 = e[0] * k + e[1], e[2] * k + e[3], e[4] * k + e[5]
        roots = sp.solve(sp.Eq(t2 ** 2, t1 * t3), k)
        need(len(roots) == 2, "not two values of k")
        for ro in roots:
            need(all(sp.simplify(t.subs(k, ro)) != 0 for t in (t1, t2, t3)), "a term is 0")
            need(sp.simplify(t2.subs(k, ro) ** 2 - t1.subs(k, ro) * t3.subs(k, ro)) == 0, "k doesn't make it geometric")
        if paper == 1:
            need(all(ro.is_rational and ro.q <= 6 for ro in roots), "Paper 1's k are not simple")
        else:
            need(not any(ro.is_rational for ro in roots), "Paper 2's k are not surds")
        gs_num(paper, roots)
        want, show = gs_xs_text(paper, "k", roots)
        if e[0] + e[4] != 2 * e[2]:
            wrongs[GS13 + "find-r-u1#0"] = {f"k = {gs_text(show, sp.solve(2 * t2 - t1 - t3, k)[0])}"}
        wrongs[GS_O + "23"] = {f"k = {gs_text(show, ro)}" for ro in roots}  # one root only
        wrongs[GS_O + "24"] = {gs_xs_text_as(show, "k", [-ro for ro in roots])}  # b's sign slipped
    elif u == "coefficients-geometric":
        nn = int(g["n"])
        a, b, d = [int(t) for t in g["pow"]]
        need(L[0] == "(1 + hx)" + "".join("⁰¹²³⁴⁵⁶⁷⁸⁹"[int(c)] for c in str(nn)) + ", where h > 0", f"line {L[0]!r}")
        need(a < b < d <= nn, "the powers are out of order")
        h = sp.Symbol("h", positive=True)
        co = [sp.binomial(nn, j) * h ** j for j in (a, b, d)]
        sols = sp.solve(sp.Eq(co[1] ** 2, co[0] * co[2]), h)
        need(len(sols) == 1, "not one positive h")
        t = one("h = ", sols[0])
        wrongs[GS_O + "25"] = {t(1 / sols[0])}  # the ratio upside down
        if abs(2 * b - a - d) == 2:
            wrongs[GS_O + "26"] = {t(sols[0] ** 2)}  # h², no root
    elif u in ("sum-from-u1-r", "sum-exact"):
        gs_seq_shown(q, u1, r)
        ex = "the exact value of " if u == "sum-exact" else ""
        need(asked == f"Find {ex}{gs_s(n)}, the sum of the first {n} terms.", f"asked {asked!r}")
        val = gs_sum(u1, r, n)
        t = one(gs_s(n) + " = ", val)
        wrongs[GS13 + "sum#0"] = {t(u1 * (1 - r ** (n - 1)) / (1 - r))}
        if r < 0 and n % 2 == 1:
            wrongs[GS13 + "sum#1"] = {t(u1 * (1 - abs(r) ** n) / (1 - r))}
        wrongs[GS_O + "27"] = {t(u1 * r ** (n - 1))}  # the last term, not the sum
    elif u == "sum-last-term":
        last = R(g["last"])
        need(last == u1 * r ** (n - 1), "the last term is not the nth")
        gs_series_shown(q, u1, r, last)
        val = gs_sum(u1, r, n)
        t = one("Sum = ", val)
        wrongs[GS13 + "sum#2"] = {t(gs_sum(u1, r, n - 1)), t(gs_sum(u1, r, n + 1))}
        wrongs[GS_O + "27"] = {t(last)}  # the last term, not the sum
        if r < 0 and n % 2 == 1:
            wrongs[GS13 + "sum#1"] = {t(u1 * (1 - abs(r) ** n) / (1 - r))}
    elif u == "sum-closed-form":
        need(L[0] == f"u₁ = {frac_text(u1)},  r = {frac_text(r)}", f"line {L[0]!r}")
        need(r > 1 and r.q == 1, "r is not a whole number above 1")
        if u1 == 1:
            a, b = r, r - 1
            need(all((a ** m - 1) / b == gs_sum(u1, r, m) for m in range(1, 7)), "the closed form is wrong")
            want = f"a = {a}, b = {b}"
            wrongs[GS_O + "29"] = {f"a = {b}, b = {a}"}  # swapped
        else:
            a, b = r, u1 / (r - 1)
            need(all(b * (a ** m - 1) == gs_sum(u1, r, m) for m in range(1, 7)), "the closed form is wrong")
            want = f"a = {a}, k = {frac_text(b)}"
            wrongs[GS_O + "29"] = {f"a = {frac_text(b)}, k = {a}"}  # swapped
            wrongs[GS_O + "28"] = {f"a = {a}, k = {frac_text(u1)}"}  # not divided by r − 1
    elif u == "sum-of-sums":
        need(u1 == 1 and r >= 3, "the sequence is out of range")
        a, b, c = r, r - 1, (r - 1) ** 2
        for m in range(1, 8):
            total = sum(gs_sum(u1, r, j) for j in range(1, m + 1))
            need((a * (a ** m - 1) - b * m) / c == total, "the closed form is wrong")
        want = f"a = {a}, b = {b}, c = {c}"
        wrongs[GS_O + "30"] = {f"a = {a}, b = {b}, c = {b}"}  # divided by r − 1 once
        wrongs[GS_O + "31"] = {f"a = {a}, b = 1, c = {c}"}  # n not over the denominator
    elif u == "sum-alternating":
        need(r == -1 and L[0] == gs_terms(paper, u1, r), f"line {L[0]!r}")
        odd = g["odd"]
        count = "2m + 1" if odd else "2m"
        need(asked == f"Find the sum of the first {count} terms, where m is a positive whole number.", f"asked {asked!r}")
        vals = {gs_sum(u1, r, 2 * m + (1 if odd else 0)) for m in (1, 2, 3, 4, 5)}
        need(len(vals) == 1, "the sum depends on m")
        t = one("Sum = ", vals.pop())
        if odd:
            wrongs[GS13 + "sum#1"] = {t(sp.Integer(0))}
        else:
            wrongs[GS_O + "32"] = {t(u1)}  # a term left over
    elif u in ("bounce-before", "bounce-total", "bounce-multiple"):
        ctx = GS_BALLS[int(g["ctx"])]
        need(ctx in L[0], f"the story {L[0]!r}")
        rate = gs_x(paper, r) if paper == 1 else dec_text(r * 100) + "%"
        need(f"rebounds to {rate} of" in L[0], f"the story {L[0]!r} doesn't give r")
        if rep == "diagram":
            gr = q["graph"]
            need(gr["kind"] == "bounce" and abs(gr["peaks"][2] - float(r ** 2)) < 1e-9, "the figure is not this ball")
        if u == "bounce-multiple":
            total = 1 + 2 * sum((r ** i for i in range(1, 400)), sp.Integer(0))  # a check on the closed form below
            exact = (1 + r) / (1 - r)
            need(abs(num(exact - total)) < 1e-6 * exact, "the distance is wrong")
            need(asked == "The total distance it travels before it comes to rest is kx metres. Find k.", f"asked {asked!r}")
            t = one("k = ", exact)
            wrongs[GS18 + "applications#0"] = {t(2 / (1 - r))}
            wrongs[SI_O + "28"] = {t(1 / (1 - r))}  # the falls alone
            wrongs[SI_O + "29"] = {t(2 * r / (1 - r))}  # no first drop
        else:
            h = R(g["h"])
            need(f"height of {gs_x(paper, h)} m" in L[0], f"the story {L[0]!r} doesn't give the height")
            if u == "bounce-before":
                need(asked == f"Find the total distance it has travelled at the moment it lands for the {bn_ordinal(n)} time.", f"asked {asked!r}")
                # The path, leg by leg: down, then up and down n − 1 times.
                height, dist = h, h
                for _ in range(n - 1):
                    height *= r
                    dist += 2 * height
                t = one("Distance = ", dist, " m")
                wrongs[GS18 + "applications#0"] = {t(dist + h)}
                wrongs[GS_O + "33"] = {t(h + sum(h * r ** i for i in range(1, n)))}  # each rebound once
                wrongs[GS_O + "34"] = {t(dist + 2 * h * r ** n)}  # a rebound too many
                wrongs[GS_O + "35"] = {t(dist - h)}  # no first drop
            else:
                need(asked == "Find the total distance it travels before it comes to rest.", f"asked {asked!r}")
                t = one("Total distance = ", h + 2 * gs_inf(h * r, r), " m")
                wrongs[GS18 + "applications#0"] = {t(2 * gs_inf(h, r))}
                wrongs[SI_O + "28"] = {t(gs_inf(h, r))}  # the falls alone
                wrongs[SI_O + "29"] = {t(2 * gs_inf(h * r, r))}  # no first drop
    elif u in ("sigma-first-r", "sigma-evaluate"):
        c, b, lo, sh, up = R(g["c"]), R(g["b"]), int(g["lower"]), int(g["shift"]), int(g["upper"])
        need(L[0] == gs_sigma_text(paper, c, b, lo, sh, up), f"the Σ shows {L[0]!r}")
        k = sp.Symbol("k")
        f = c * b ** (k + sh)
        first, second = f.subs(k, lo), f.subs(k, lo + 1)
        if u == "sigma-first-r":
            need(asked == "Write down u₁ and r for this series.", f"asked {asked!r}")
            show = gs_show(paper, [first, second / first])
            names = ["u₁", "r"]
            gs_num(paper, [first])
            want = gs_named(show, names, [first, second / first])
            if first != c:
                wrongs[GS13 + "sigma#0"] = {gs_named(show, names, [c, second / first])}
            wrongs[GS13 + "sigma#1"] = {gs_named(show, names, [first, c])}
            if first == c:
                wrongs[GS_O + "15"] = {gs_named(show, names, [second / first, first])}  # u₁ and r swapped
        else:
            count = up - lo + 1
            need(asked == "Find the value of this sum.", f"asked {asked!r}")
            val = sum(f.subs(k, j) for j in range(lo, up + 1))
            t = one("Sum = ", val)
            if first != c:
                wrongs[GS13 + "sigma#0"] = {t(gs_sum(c, b, count))}
            wrongs[GS13 + "sigma#2"] = {t(gs_sum(first, b, up - lo))}
            wrongs[GS_O + "27"] = {t(f.subs(k, up))}  # the last term, not the sum
    elif u == "sigma-write":
        last = R(g["last"])
        need(last == u1 * r ** (n - 1), "the last term is not the nth")
        gs_series_shown(q, u1, r, last)
        need(sum(u1 * r ** (j - 1) for j in range(1, n + 1)) == gs_sum(u1, r, n), "the Σ is not the series")
        want = f"a = {frac_text(u1)}, b = {frac_text(r)}, n = {n}"
        wrongs[GS13 + "sum#2"] = {f"a = {frac_text(u1)}, b = {frac_text(r)}, n = {n - 1}"}  # the last power as n
        wrongs[GS_O + "15"] = {f"a = {frac_text(r)}, b = {frac_text(u1)}, n = {n}"}  # u₁ and r swapped
    elif u == "exists-claim":
        gs_seq_shown(q, u1, r)
        ar = abs(r)
        kind = g["kind"]
        need(kind == ("conv" if ar < 1 else "one" if r == 1 else "neg-one" if r == -1 else "big" if r > 0 else "neg-big"), f"kind {kind} for r = {r}")
        mag = gs_x(paper, ar)
        if ar < 1:
            want = f"Yes: |r| = {mag}, which is less than 1"
            wrongs[SI_O + "12"] = {f"No: |r| = {mag}, and |r| has to be more than 1"}  # the test reversed
            wrongs[SI_O + "13"] = {"No: the terms never reach 0"}
            wrongs[SI_O + "14"] = {"No: an infinite sum can't be finite"}
        elif ar > 1:
            want = f"No: |r| = {mag}, which is more than 1"
            wrongs[SI_O + "15"] = {"Yes: r is not 1", "Yes: S∞ exists for any r except 1"}  # only r = 1 fails
            wrongs[GS18 + "sum-to-infinity#2"] = {f"Yes: S∞ = u₁/(1 − r) = {gs_x(paper, u1 / (1 - r))}"}
            if r < 0:
                wrongs[GS18 + "convergence#0"] = {f"Yes: r = {gs_x(paper, r)}, which is less than 1"}
        else:
            want = "No: |r| = 1, and |r| has to be less than 1"
            wrongs[GS18 + "convergence#2"] = {"Yes: |r| ≤ 1 is enough"}
            if r == -1:
                wrongs[GS18 + "sum-to-infinity#2"] = {f"Yes: S∞ = u₁/(1 − r) = {gs_x(paper, u1 / 2)}"}
    elif u == "exists-table":
        rows = q["table"]["rows"]
        ns = [int(t) for t in rows[0][1]]
        need(rows[1][1] == [gs_work(gs_sum(u1, r, m)) for m in ns], "the table is not the partial sums")
        lim = u1 / (1 - r)
        settles = abs(r) < 1
        need(g["kind"] == ("conv" if settles else "big" if r > 0 else "neg-big"), "the kind is wrong")
        if settles:
            want = f"S∞ exists: the sums settle near {gs_text('sf', lim)}"
            wrongs[SI_O + "16"] = {"S∞ does not exist: the sums keep changing"}
            wrongs[SI_O + "13"] = {"S∞ does not exist: no term is 0"}
        else:
            want = "S∞ does not exist: the sums never settle"
            wrongs[SI_O + "17"] = {"S∞ exists: it is the last sum shown"}
            wrongs[GS18 + "sum-to-infinity#2"] = {f"S∞ exists: u₁/(1 − r) = {gs_text('sf', lim)}"}
    elif u == "x-interval":
        a, b, c = int(g["ax"]), int(g["bx"]), int(g["cx"])
        x = sp.Symbol("x", real=True)
        ex = sp.Rational(a, c) * x + sp.Rational(b, c)
        sol = sp.solve_univariate_inequality(sp.Abs(ex) < 1, x, relational=False)
        need(isinstance(sol, sp.Interval) and sol.left_open and sol.right_open, f"|r| < 1 gives {sol}")
        lo, hi = sol.start, sol.end
        need(lo == R(g["lo"]) and hi == R(g["hi"]), "the ends are not where |r| = 1")
        want = f"{frac_text(lo)} < x < {frac_text(hi)}"
        one_end = sp.solve(sp.Eq(ex, 1), x)[0]
        wrongs[GS18 + "convergence#1"] = {f"x {'<' if a > 0 else '>'} {frac_text(one_end)}"}
        wrongs[GS18 + "convergence#2"] = {f"{frac_text(lo)} ≤ x ≤ {frac_text(hi)}"}
        wrongs[SI_O + "12"] = {f"x < {frac_text(lo)} or x > {frac_text(hi)}"}  # |r| > 1
        if rep == "graph":
            gr = q["graph"]
            need(lo.q == 1 and hi.q == 1, "a graph's ends are whole")
            need(any(h_["at"] == 1 for h_ in gr["hlines"]) and any(h_["at"] == -1 for h_ in gr["hlines"]), "the band is missing")
            for px, py in gr["curves"][0][::40]:
                need(abs(float(ex.subs(x, sp.Float(px))) - py) < 1e-6, "the line is not r(x)")
            need(gr["x0"] < lo and hi < gr["x1"], "an end is off the graph")
        else:
            shown = re.fullmatch(r"A geometric series has common ratio r = (.+), where x is a real number\.", L[0])
            need(shown is not None and sp.simplify(parse(shown.group(1)).subs(X, x) - ex) == 0, f"line {L[0]!r} is not r = {ex}")
    elif u == "sinf-value":
        gs_seq_shown(q, u1, r)
        need(abs(r) < 1, "no sum to infinity")
        if paper == 1:
            need((u1 / (1 - r)).q <= 30, "a Paper 1 S∞ has a large denominator")
        t = one("S∞ = ", gs_inf(u1, r))
        wrongs[GS18 + "sum-to-infinity#0"] = {t(u1 / (1 + r))}
        wrongs[GS18 + "find-unknown#2"] = {t(u1 * r / (1 - r))}  # from u₂
        wrongs[SI_O + "18"] = {t(1 / (1 - r))}  # no u₁ on top
    elif u == "sinf-sigma":
        c, b, lo, sh = R(g["c"]), R(g["b"]), int(g["lower"]), int(g["shift"])
        need(L[0] == gs_sigma_text(paper, c, b, lo, sh, -1), f"the Σ shows {L[0]!r}")
        k = sp.Symbol("k", integer=True)
        first = c * b ** (lo + sh)
        val = sp.summation(c * b ** (k + sh), (k, lo, sp.oo))
        need(val == first / (1 - b), "the sum is not the closed form")
        t = one("S∞ = ", val)
        wrongs[GS18 + "sum-to-infinity#0"] = {t(first / (1 + b))}
        if first != c:
            wrongs[GS18 + "sum-to-infinity#1"] = {t(c / (1 - b))}
        wrongs[GS18 + "find-unknown#2"] = {t(first * b / (1 - b))}  # from the second term
    elif u == "sinf-shaded":
        cut, shaded, area = int(g["cut"]), int(g["shaded"]), R(g["area"])
        need(f"{cut} by {cut} grid" in L[0] and f"area {gs_x(paper, area)} " in L[0] and f"{shaded} of the" in L[0], f"line {L[0]!r}")
        gr = q["graph"]
        need(gr["kind"] == "squares" and gr["style"] == "shaded" and gr["cut"] == cut and gr["shaded"] == shaded, "the figure is another")
        # What stays unshaded: one cell of each grid, down to nothing. The rest is shaded in the ratio s : 1 cell's remainder.
        cells = cut * cut
        need(0 < shaded < cells, "the shaded count is out of range")
        m = sp.Symbol("m", positive=True, integer=True)
        val = sp.limit(area * sp.Rational(shaded, cells) * (1 - sp.Rational(1, cells) ** m) / (1 - sp.Rational(1, cells)), m, sp.oo)
        t = one("Total shaded area = ", val)
        wrongs[GS18 + "sum-to-infinity#0"] = {t(area * sp.Rational(shaded, cells) / (1 + sp.Rational(1, cells)))}
        wrongs[SI_O + "19"] = {t(area * sp.Rational(shaded, cells))}  # the first shading only
        wrongs[SI_O + "20"] = {t(area)}  # the whole square
    elif u == "x-from-log-series":
        m, base, ln, tt = int(g["m2"]), int(g["base"]), int(g["ln"]), int(g["t"])
        log_name = f"log{str(base).translate(str.maketrans('0123456789', '₀₁₂₃₄₅₆₇₈₉'))}"
        need(L[0] == f"{log_name} x + p {log_name} x + (1/{m}) {log_name} x + …, where x > 1 and p > 0", f"line {L[0]!r}")
        p = sp.Symbol("p", positive=True)
        ps = sp.solve(sp.Eq(p / 1, sp.Rational(1, m) / p), p)
        need(len(ps) == 1, "not one ratio")
        S = ln / (1 - ps[0])
        sq = sp.sqrt(m)
        if tt:
            need(sp.simplify(S - tt * (m + sq)) == 0, "S∞ is not t(m + √m)")
            head = f"{tt * m} + {'' if tt == 1 else tt}√{m}"
        else:
            need(S == R(g["sinf"]), "the S∞ given is wrong")
            head = frac_text(S)
        need(asked == f"The series is geometric, with S∞ = {head}. Find x.", f"asked {asked!r}")
        val = sp.Integer(base) ** sp.simplify(S * (1 - ps[0]))
        t = one("x = ", val)
        wrongs[SI_O + "21"] = {t(sp.simplify(S * (1 - ps[0])))}  # the log left in
        wrongs[SI_O + "22"] = {t(base * sp.simplify(S * (1 - ps[0])))}  # times the base
    elif u in ("u1-from-sinf", "r-from-sinf"):
        S = R(g["sinf"])
        need(abs(r) < 1, "no sum to infinity")
        need(S == u1 / (1 - r), "S∞ is not the sequence's")
        x = sp.Symbol("x")
        if u == "u1-from-sinf":
            shown = f"r = {gs_x(paper, r)},  S∞ = {gs_x(paper, S)}" if rep == "notation" else f"A geometric series has common ratio {gs_x(paper, r)} and sum to infinity {gs_x(paper, S)}."
            need(L[0] == shown, f"line {L[0]!r}")
            sol = sp.solve(sp.Eq(x / (1 - r), S), x)
            t = one("u₁ = ", sol[0])
            wrongs[GS18 + "find-unknown#0"] = {t(S / (1 - r))}
            wrongs[SI_O + "23"] = {t(S * r)}  # times r
            wrongs[GS18 + "sum-to-infinity#0"] = {t(S * (1 + r))}  # 1 + r below
        else:
            shown = f"u₁ = {gs_x(paper, u1)},  S∞ = {gs_x(paper, S)}" if rep == "notation" else f"A geometric series has first term {gs_x(paper, u1)} and sum to infinity {gs_x(paper, S)}."
            need(L[0] == shown, f"line {L[0]!r}")
            sol = sp.solve(sp.Eq(u1 / (1 - x), S), x)
            t = one("r = ", sol[0])
            wrongs[GS18 + "find-unknown#0"] = {t(1 - S / u1)}
            wrongs[SI_O + "24"] = {t(u1 / S)}  # stopped at 1 − r
            wrongs[SI_O + "25"] = {t(1 + u1 / S)}  # added, not taken away
    elif u == "r-from-multiple":
        mult = R(g["mult"])
        tm = gs_x(paper, mult)
        br = f"({tm})" if mult < 0 or "/" in tm else tm
        need(L[0] == (f"S∞ = {br} × u₁,  u₁ ≠ 0" if rep == "notation" else f"The sum to infinity of a geometric series is {tm} times its first term."), f"line {L[0]!r}")
        x = sp.Symbol("x")
        sol = sp.solve(sp.Eq(1 / (1 - x), mult), x)
        need(abs(sol[0]) < 1, "|r| is not below 1")
        t = one("r = ", sol[0])
        wrongs[GS18 + "find-unknown#0"] = {t(1 - mult)}
        wrongs[SI_O + "24"] = {t(1 / mult)}  # stopped at 1 − r
        wrongs[SI_O + "25"] = {t(1 + 1 / mult)}  # added, not taken away
    elif u in ("r-from-u2-reject", "r-from-u2-both"):
        S, u2 = R(g["sinf"]), R(g["u2"])
        shown = f"u₂ = {gs_x(paper, u2)},  S∞ = {gs_x(paper, S)}" if rep == "notation" else f"The second term of a geometric series is {gs_x(paper, u2)} and its sum to infinity is {gs_x(paper, S)}."
        need(L[0] == shown, f"line {L[0]!r}")
        x = sp.Symbol("x", real=True)
        roots = sorted(sp.solve(sp.Eq(u2 / x / (1 - x), S), x), key=num)
        need(len(roots) == 2, "not two roots")
        need(all(ro.is_rational for ro in roots) if paper == 1 else not any(ro.is_rational for ro in roots), "the roots don't suit the paper")
        good = [ro for ro in roots if abs(num(ro)) < 1]
        gs_num(paper, good)
        if u == "r-from-u2-reject":
            need(len(good) == 1 and asked == "Find r.", "one root should be rejected")
            want, show = gs_xs_text(paper, "r", good)
            bad = [ro for ro in roots if ro not in good]
            wrongs[GS18 + "find-unknown#1"] = {gs_xs_text_as(show, "r", roots), gs_xs_text_as(show, "r", bad)}
            wrongs[SI_O + "27"] = {gs_xs_text_as(show, "r", [-ro for ro in roots])}  # both signs slipped
        else:
            need(len(good) == 2 and asked == "Find the possible values of r.", "both roots should stay")
            want, show = gs_xs_text(paper, "r", good)
            wrongs[SI_O + "26"] = {f"r = {gs_text(show, ro)}" for ro in good}  # one root only
            wrongs[SI_O + "27"] = {gs_xs_text_as(show, "r", [-ro for ro in good])}  # both signs slipped
        wrongs[GS18 + "find-unknown#2"] = {f"r = {gs_text(show, 1 - u2 / S)}"}
    elif u == "recurring-decimal":
        digits, ln = int(g["digits"]), int(g["len"])
        block = str(digits).rjust(ln, "0")
        need(L[0] == "0." + block * 3 + "…", f"line {L[0]!r}")
        need(block != block[0] * ln or ln == 1, "the block is a shorter block repeated")
        top = 10 ** ln
        d = sp.Symbol("d")
        val = sp.solve(sp.Eq(top * d - d, digits), d)[0]     # 10ᵏd − d cancels the tail
        need(val == gs_inf(sp.Rational(digits, top), sp.Rational(1, top)), "the series and the algebra disagree")
        want = frac_text(val)
        wrongs[SI_O + "19"] = {frac_text(sp.Rational(digits, top))}  # the first block only
        if ln > 1:
            wrongs[GS18 + "applications#1"] = {frac_text(sp.Rational(digits, top) / sp.Rational(9, 10))}
    elif u == "nested-squares":
        tt, side = R(g["t"]), R(g["h"])
        need(f"side {gs_x(paper, side)} cm" in L[0] and f"corner {frac_text(tt)} of the way" in L[0], f"line {L[0]!r}")
        gr = q["graph"]
        need(gr["kind"] == "squares" and gr["style"] == "nested" and abs(gr["t"] - float(tt)) < 1e-9, "the figure is another")
        # The next side by Pythagoras, on coordinates of one corner triangle.
        rr = sp.Matrix([tt * side, (1 - tt) * side]).dot(sp.Matrix([tt * side, (1 - tt) * side])) / side ** 2
        t = one("Total area = ", gs_inf(side ** 2, rr), " cm²")
        wrongs[SI_O + "19"] = {t(side ** 2)}  # the first square only
        wrongs[SI_O + "30"] = {t(side ** 2 / (1 - tt))}  # r = t
        wrongs[GS18 + "sum-to-infinity#0"] = {t(side ** 2 / (1 + rr))}
    elif u == "story-total":
        need(gs_x(paper, u1) in L[0], f"story {L[0]!r}")
        rate = gs_x(paper, r) if paper == 1 else dec_text(r * 100) + "%"
        need(f" {rate} of" in L[0], f"story {L[0]!r} doesn't give the share")
        unit = re.search(r"\d ([A-Za-z]+) ", L[0]).group(1)
        t = one("Total = ", gs_inf(u1, r), " " + unit)
        wrongs[GS18 + "sum-to-infinity#0"] = {t(u1 / (1 + r))}
        wrongs[GS18 + "find-unknown#2"] = {t(u1 * r / (1 - r))}  # from the second amount
    elif u == "story-target":
        target, kind = R(g["target"]), g["kind"]
        need(gs_x(paper, u1) in L[0], f"story {L[0]!r}")
        rate = gs_x(paper, r) if paper == 1 else dec_text(r * 100) + "%"
        need(f" {rate} of" in L[0], f"story {L[0]!r} doesn't give the share")
        need(asked.startswith(f"Does the total ever reach {gs_x(paper, target)} "), f"asked {asked!r}")
        goal = asked[len("Does the total ever reach "):-1]
        lim = gs_x(paper, u1 / (1 - r))
        if abs(r) < 1:
            s_inf = gs_inf(u1, r)
            if s_inf < target:
                need(kind == "under", "the total stops short")
                want = f"No: the total stays below S∞ = {lim}, and that is less than {goal}"
                wrongs[SI_O + "31"] = {f"Yes: the total keeps rising, so it passes {goal} in the end", "Yes: an endless run of additions has no limit"}
            else:
                need(kind == "over" and s_inf > target, "the total passes the target")
                need(next(m for m in range(1, 900) if gs_sum(u1, r, m) > target) > 1, "the first amount passes it")
                want = f"Yes: S∞ = {lim}, which is more than {goal}"
            wrongs[SI_O + "32"] = {"No: the total stops once the amounts are small"}
        else:
            need(kind == "grow" and r > 1, "r is not above 1")
            need(next(m for m in range(1, 900) if gs_sum(u1, r, m) > target) > 1, "the target is too low")
            want = "Yes: r > 1, so the total grows without limit"
            wrongs[GS18 + "applications#2"] = {f"No: S∞ = {lim}, so it stops there"}
    elif u == "deposit-for-target":
        target = R(g["target"])
        rate = dec_text(r * 100) + "%"
        need(f" {rate} of" in L[0], f"story {L[0]!r} doesn't give the share")
        need(f"after {n} " in asked and f" is {gs_x(paper, target)} " in asked, f"asked {asked!r}")
        x = sp.Symbol("x")
        sol = sp.solve(sp.Eq(gs_sum(x, r, n), target), x)
        unit = asked[asked.index(f" is {gs_x(paper, target)}") + len(f" is {gs_x(paper, target)}"):].split(".")[0]
        t = one("First amount = ", sol[0], unit)
        wrongs[SI_O + "33"] = {t(target * (1 - r))}  # S∞ for Sₙ
        wrongs[SI_O + "34"] = {t(target / n)}  # an equal split
        wrongs[SI_O + "35"] = {t(target / gs_sum(sp.Integer(1), r, m)) for m in (n - 1, n + 1)}  # a term too many or few
    else:
        need(False, f"no check for {u}")
    gc_check_common(q, want, wrongs, trap)
    return None, None


def gs_xs_text_as(show, name, vals):
    vals = sorted(vals, key=lambda v: num(v))
    return f"{name} = " + " or ".join(gs_text(show, v) for v in vals)


# ── geometric-context (t1-geometric-in-context, FAL-752) ─────
# The `geometric-context` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/geometric_context.gd. The story, table, dots or Σ are read back from what
# the student sees. Every value is worked out again with exact rationals, every least n by testing
# the terms or totals one at a time, and each tagged option from what its slip does.

E10GE_NUM = r"−?\d+(?:\.\d+)?"
E10GE_M, E10GE_F = "SL1.3.model#", "SL1.3.find-n#"
E10GE_NTH0, E10GE_NTH1, E10GE_SUM0 = "SL1.3.nth-term#0", "SL1.3.nth-term#1", "SL1.3.sum#0"
E10GE_ARITH, E10GE_ROOT = "SL1.3.find-r-u1#0", "SL1.3.find-r-u1#2"
# The slips FAL-815 named (misconceptions with no ref of their own).
E10GE_RISE_AS_FALL, E10GE_NO_R_MINUS_1 = "t1-geometric-in-context#21", "t1-geometric-in-context#22"
E10GE_LIMIT = 5000000
E10GE_P1_LIMIT = 200000
E10GE_EDGE = sp.Rational(19, 1000)      # the engine's is 0.02; a hair under it, for float ties
E10GE_CLEAR = sp.Rational(99, 1000)     # the engine's is 0.1; the same, for a crossing
E10GE_P1 = ("factor-from-percent", "term-number-after", "scaled-area-term", "mean-of-areas")
E10GE_BALLS = ["rubber ball", "steel spring", "scrap tyre", "drone shell"]
# now, thing, subject, unit, round, heading, sign
E10GE_STOCKS = [
    ("Glow-moss covers {} m² of a bunker wall today.", "area of moss", "The area", " m²", "month", "Area (m²)", 1),
    ("The Guild's vault holds {} kg of silver today.", "mass of silver", "The mass", " kg", "year", "Mass (kg)", 1),
    ("A vat holds {} litres of algae oil today.", "volume of algae oil", "The volume", " litres", "week", "Volume (litres)", 1),
    ("A scrap heap weighs {} kg today.", "mass of the heap", "The mass", " kg", "year", "Mass (kg)", 1),
    ("A leaking tank holds {} litres of fuel today.", "volume of fuel", "The volume", " litres", "day", "Volume (litres)", -1),
    ("The reading at a crater is {} mSv today.", "reading", "The reading", " mSv", "year", "Reading (mSv)", -1),
    ("A battery bank holds {} kWh today.", "charge", "The charge", " kWh", "day", "Charge (kWh)", -1),
    ("A silo holds {} kg of grain today.", "mass of grain", "The mass", " kg", "week", "Mass (kg)", -1),
]
# first, thing, subject, unit, round, heading, total, preposition, sign
E10GE_FLOWS = [
    ("A rooftop farm yields {} kg of beans in its first season.", "yield", "The yield", " kg", "season", "Yield (kg)", "total yield", "in", 1),
    ("A salvage crew hauls {} kg of scrap in its first month.", "haul", "The haul", " kg", "month", "Haul (kg)", "total haul", "in", 1),
    ("A guard is paid {} tokens in her first year.", "pay", "Her pay", " tokens", "year", "Pay (tokens)", "total pay", "in", 1),
    ("A copper mine sends out {} kg in its first year.", "output", "The output", " kg", "year", "Output (kg)", "total output", "in", 1),
    ("A spring gives {} litres of water in its first week.", "flow", "The flow", " litres", "week", "Flow (litres)", "total flow", "in", -1),
    ("A dig site gives up {} kg of scrap in its first month.", "find", "The find", " kg", "month", "Find (kg)", "total find", "in", -1),
    ("A solar rig stores {} kWh on its first day.", "charge stored", "The charge stored", " kWh", "day", "Charge stored (kWh)", "total charge stored", "on", -1),
    ("A trade route brings in {} tokens in its first year.", "income", "The income", " tokens", "year", "Income (tokens)", "total income", "in", -1),
]
# opening, round, unit, heading, what a payment is called
E10GE_DEALS = [
    ("A scavenger signs on for {} months, paid once a month, and may pick one of two deals.", "month", " tokens", "tokens", "payment"),
    ("A settler takes a water ration for {} weeks, once a week, and may pick one of two deals.", "week", " litres", "litres", "ration"),
    ("A caravan buys fuel on contract for {} months, with a delivery each month, and may pick one of two deals.", "month", " litres", "litres", "delivery"),
    ("A bazaar trader rents a stall out for {} weeks, for one payment a week, and may pick one of two deals.", "week", " scrap", "scrap", "payment"),
]
E10GE_RIVALS = [("Yard A", "Yard B", "turns out", " kg", "year"), ("Well A", "Well B", "gives", " litres", "month"),
                ("Stall A", "Stall B", "takes", " tokens", "week"), ("Farm A", "Farm B", "grows", " kg", "season")]
E10GE_SHEETS = [("A workshop cuts {} rectangular armour plates, numbered {} to {}.", "P", "plate", "plates"),
                ("A rigger stitches {} rectangular tarpaulins, numbered {} to {}.", "T", "tarpaulin", "tarpaulins"),
                ("A signal crew paints {} rectangular flags, numbered {} to {}.", "F", "flag", "flags"),
                ("A glazier cuts {} rectangular solar panels, numbered {} to {}.", "S", "panel", "panels")]
E10GE_SPREADS = [
    ("In round 1, {} scouts hear a warning.", "In each round after that, {} times as many scouts hear it as in the round before.", "In the last round, {} scouts hear it.", "How many rounds are there?"),
    ("A spore patch has {} spores on day 1.", "Each day after that it has {} times as many as the day before.", "On the last day of the count it has {} spores.", "How many days does the count last?"),
    ("On the first level of a shaft, a crew finds {} scrap coils.", "On each deeper level it finds {} times as many as on the level before.", "On the lowest level it finds {} coils.", "How many levels does the shaft have?"),
    ("A trader's first shipment is {} cans.", "Each shipment after that is {} times the one before.", "The last shipment is {} cans.", "How many shipments are there?"),
]


def e10ge_q(t):
    return sp.Rational(t.replace("−", "-"))


def e10ge_sub(k):
    return "".join("₀₁₂₃₄₅₆₇₈₉"[int(c)] for c in str(k))


def e10ge_fill(pattern, text):
    """The numbers put into a pattern's {} to make text, or None."""
    parts = pattern.split("{}")
    rx = f"({E10GE_NUM})".join(re.escape(p) for p in parts)
    m = re.fullmatch(rx, text)
    return [e10ge_q(g) for g in m.groups()] if m else None


def e10ge_near(text, x, tol=sp.Rational(1, 50000)):
    """A number from the working agrees with x to the figures shown."""
    return abs(num(e10ge_q(text)) - num(x)) <= num(tol) * max(abs(num(x)), sp.Rational(1, 1000))


def e10ge_clear(x):
    v = abs(num(x))
    e = sp.floor(sp.log(v, 10))
    scaled = v / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= E10GE_EDGE


def e10ge_b(v):
    t = frac_text(v)
    return f"({t})" if "/" in t else t


def e10ge_val(x, unit, want_clear=True):
    """x as Paper 2 writes it, with its trap, once x is known to be off a rounding edge."""
    if want_clear:
        need(e10ge_clear(x) and abs(num(x)) <= E10GE_LIMIT, f"the value {num(x)} is on an edge or too large")
    return gc_s(x) + unit


def e10ge_table(q, u1_row=-1):
    t = q["table"]
    need(t is not None, "no table")
    rows = t["rows"]
    return rows, [e10ge_q(v) for v in rows[u1_row][1]]


def e10ge_ratio(vals):
    r = vals[1] / vals[0]
    need(all(vals[i + 1] == vals[i] * r for i in range(len(vals) - 1)), "the table is not geometric")
    return r


def e10ge_stock(q):
    """The value today, r, p and the story, from the sentences or the table."""
    L, rep = q["lines"], q["view"]["rep"]
    if rep == "table":
        for st in E10GE_STOCKS:
            if L[0] == f"The table shows the {st[1]}. It changes by the same percentage each {st[4]}.":
                rows, vals = e10ge_table(q)
                need(rows[-1][0] == st[5] and rows[-2] == [f"{st[4].capitalize()}s from now", ["0", "1", "2"]], "the table's headings")
                r = e10ge_ratio(vals)
                need((r > 1) == (st[6] > 0), "the table runs the wrong way for its story")
                return st, vals[0], r, abs(r - 1) * 100
        raise Fail(f"can't read {L[0]!r}")
    for st in E10GE_STOCKS:
        got = e10ge_fill(st[0], L[0])
        if got:
            m = re.fullmatch(rf"{re.escape(st[2])} (rises|falls) by (\d+)% each {st[4]}\.", L[1])
            need(m is not None, f"can't read {L[1]!r}")
            sign = 1 if m.group(1) == "rises" else -1
            need(sign == st[6], "the change runs the wrong way for its story")
            p = sp.Integer(m.group(2))
            return st, got[0], 1 + sign * p / 100, p
    raise Fail(f"can't read {L[0]!r}")


def e10ge_flow(q, lines=None):
    """u₁, r, p and the story of an amount for each round, from the sentences or the table."""
    L, rep = lines if lines is not None else q["lines"], q["view"]["rep"]
    if rep == "table":
        for st in E10GE_FLOWS:
            if L[0] in (f"The table shows the {st[1]} in the first three {st[4]}s. It changes by the same percentage each {st[4]}.",
                        f"The table shows the {st[1]} in the first three {st[4]}s. Each value is the same multiple of the one before."):
                rows, vals = e10ge_table(q)
                need(rows[0] == [st[4].capitalize(), ["1", "2", "3"]] and rows[1][0] == st[5], "the table's headings")
                r = e10ge_ratio(vals)
                need((r > 1) == (st[8] > 0), "the table runs the wrong way for its story")
                return st, vals[0], r, abs(r - 1) * 100
        raise Fail(f"can't read {L[0]!r}")
    for st in E10GE_FLOWS:
        got = e10ge_fill(st[0], L[0])
        if got:
            subj, each = re.escape(st[2]), f" each {st[4]}."
            m = re.fullmatch(rf"{subj} (rises|falls) by (\d+)%{re.escape(each)}", L[1])
            if m:
                sign = 1 if m.group(1) == "rises" else -1
                need(sign == st[8], "the change runs the wrong way for its story")
                p = sp.Integer(m.group(2))
                return st, got[0], 1 + sign * p / 100, p
            word = {"doubles": 2, "triples": 3, "halves": sp.Rational(1, 2)}
            m = re.fullmatch(rf"{subj} (doubles|triples|halves){re.escape(each)}", L[1])
            need(m is not None, f"can't read {L[1]!r}")
            r = sp.Rational(word[m.group(1)])
            need((r > 1) == (st[8] > 0), "the change runs the wrong way for its story")
            return st, got[0], r, abs(r - 1) * 100
    raise Fail(f"can't read {L[0]!r}")


def e10ge_dots(q, totals):
    """u₁, r and the target from a figure: the first three dots are labelled, and all must fit."""
    g = q["graph"]
    pts = g["points"]
    need(g["x_name"] == "n" and g["y_name"] == ("Sₙ" if totals else "uₙ"), "the axes' names")
    shown = [e10ge_q(p["label"]) for p in pts[:3]]
    need(all(p["label"] == "" for p in pts[3:]), "a dot past the third is labelled")
    u1 = shown[0]
    terms = [shown[0], shown[1] - shown[0], shown[2] - shown[1]] if totals else shown
    r = terms[1] / terms[0]
    need(terms[2] == terms[1] * r, "the dots are not geometric")
    for i, p in enumerate(pts):
        k = i + 1
        y = u1 * (r ** k - 1) / (r - 1) if totals else u1 * r ** (k - 1)
        need(p["x"] == k and abs(p["y"] - float(y)) <= 1e-6 * float(y), f"the dot at n = {k} is off the model")
    need(len(g["hlines"]) == 1, "no target line")
    target = e10ge_q(g["hlines"][0]["label"].replace("y = ", ""))
    need(abs(g["hlines"][0]["at"] - float(target)) < 1e-6 * float(target), "the target line is drawn at the wrong height")
    return u1, r, target


def e10ge_seq(q, totals):
    """u₁, r, the story or None, from any representation of a sequence."""
    L, rep = q["lines"], q["view"]["rep"]
    if rep == "notation":
        m = re.fullmatch(rf"A geometric sequence has u₁ = ({E10GE_NUM}) and r = ({E10GE_NUM})\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        if totals:
            need(L[1] == "Sₙ is the sum of its first n terms.", f"can't read {L[1]!r}")
        return e10ge_q(m.group(1)), e10ge_q(m.group(2)), None, None
    if rep == "graph":
        u1, r, target = e10ge_dots(q, totals)
        st = next((s_ for s_ in E10GE_FLOWS if f"changes by the same percentage each {s_[4]}, and the line is the target" in L[0] and f"The {s_[1]} changes" in L[0]), None)
        need(st is not None, f"can't read {L[0]!r}")
        need((r > 1) == (st[8] > 0), "the dots run the wrong way for their story")
        return u1, r, st, target
    st, u1, r, _ = e10ge_flow(q, L[:-1] if rep == "words" else L[:1])
    want = f"Let Sₙ be the {st[6]} of the first n {st[4]}s." if totals else f"Let uₙ be the {st[1]} {st[7]} {st[4]} n."
    need(L[-1] == want, f"the last line {L[-1]!r}")
    return u1, r, st, None


def e10ge_first(cond, top=4000):
    k = 1
    while k <= top:
        if cond(k):
            return k
        k += 1
    return 0


def e10ge_crossing(x, n):
    """The real crossing x is well clear of a whole number, and n is the next one up."""
    f = abs(mpmath.mpf(x) - mpmath.nint(x))
    need(f >= mpmath.mpf(int(E10GE_CLEAR.p)) / int(E10GE_CLEAR.q), f"the crossing {x} is too near a whole number")
    need(int(mpmath.ceil(x)) == n, f"the crossing {x} doesn't round up to {n}")


def e10ge_steps(q):
    return {sol["angle"]: sol["steps"] for sol in q["solutions"]}


def e10ge_find_work(q, value, n, x, u, qv, letter="n"):
    """The working of a find-n question, from what the game writes: the power isolated (qv), the
    bound after logs, value(k) at the table's rows, and the crossing on the graph."""
    w = e10ge_steps(q)
    if "logs" in w:
        solve = next(st for st in w["logs"] if "Solve" in st)
        m = re.search(rf"[<>] ({E10GE_NUM})$", solve)
        need(m is not None and e10ge_near(m.group(1), qv), f"the power isn't isolated in {solve!r}")
        logs = next(st for st in w["logs"] if "ln" in st)
        if u in ("term", "first"):
            m = re.search(rf"n − 1 > ({E10GE_NUM})$", logs)
            need(m is not None and e10ge_near(m.group(1), x - 1), f"the bound in {logs!r}")
            m = re.search(rf"So n > ({E10GE_NUM}),", " ".join(w["logs"]))
            need(m is not None and e10ge_near(m.group(1), x), "the bound on n")
        else:
            m = re.search(rf"{letter} > ({E10GE_NUM})$", logs)
            need(m is not None and e10ge_near(m.group(1), x), f"the bound in {logs!r}")
        if qv < 1:
            need("flips the sign" in logs, "the inequality isn't flipped")
        need("next whole number" in " ".join(w["logs"]), "the bound isn't rounded up")
    if "gdc-table" in w:
        st = next((t for t in w["gdc-table"] if t.startswith("X = ")), "")
        m = re.fullmatch(rf"X = (\d+) gives ({E10GE_NUM}), and X = (\d+) gives ({E10GE_NUM})\.", st)
        need(m is not None, f"the table row {st!r}")
        need(int(m.group(1)) == n - 1 and int(m.group(3)) == n, "the table rows are not either side of n")
        need(e10ge_near(m.group(2), value(n - 1)) and e10ge_near(m.group(4), value(n)), "the table's values")
    if "graph-intersect" in w:
        m = re.search(rf"find where they meet: x = ({E10GE_NUM})\.", " ".join(w["graph-intersect"]))
        need(m is not None and e10ge_near(m.group(1), x), "the crossing in the graph working")


def e10ge_short(angle, rising):
    return {"logs": E10GE_F + ("1" if rising else "0"), "gdc-table": E10GE_F + "3"}.get(angle, E10GE_F + "1")


def e10ge_list(st, r, first, label):
    """Each entry of a listed working is the one before × r."""
    vals = [e10ge_q(v) for v in re.findall(rf"{label} ?\d* ?\w*: ({E10GE_NUM})", st, re.I)]
    need(len(vals) >= 2, f"nothing listed in {st!r}")
    prev = first
    for v in vals:
        need(abs(num(v - prev * r)) <= 2e-5 * num(abs(prev * r)) + 1e-9, f"{num(v)} doesn't follow {num(prev)}")
        prev = v
    return vals


def e10ge_check(q):
    u, rep, L, asked, angle, paper = q["view"]["unknown"], q["view"]["rep"], q["lines"], q["asked"], q["view"]["angle"], q["paper"]
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z])-\d", tx), f"a hyphen for a minus in {tx!r}")
    both = ("rebound-height", "nth-expression", "value-after-years", "value-in-round")
    if u in E10GE_P1 or angle == "exact-power" or (angle == "tabulate" and u in both[:2]):
        need(paper == 1, f"{u} by {angle} is Paper 1")
    elif u not in both or (angle == "tabulate" and u in both[2:]):
        need(paper == 2, f"{u} by {angle} is Paper 2")
    if paper == 1:
        for sol in q["solutions"]:
            need(sol["angle"] in ("multiplier", "tabulate", "exact-power"), f"{sol['angle']} is shown on Paper 1")
    wrongs, trap, want = {}, None, None
    w = e10ge_steps(q)
    M, F = E10GE_M, E10GE_F

    def value(x, unit):
        nonlocal want, trap
        if paper == 1:
            want = dec_text(x) + unit
            return lambda v: dec_text(v) + unit
        want = e10ge_val(x, unit)
        trap = gc_trap([x], gc_s2(x) + unit)
        return lambda v: gc_s(v) + unit

    if u == "factor-from-percent":
        st, _, r, p = e10ge_stock(q)
        need(asked == f"The {st[1]} after each {st[4]} is r times what it was. Write down the value of r.", f"asked {asked!r}")
        want = "r = " + dec_text(r)
        t = lambda v: "r = " + dec_text(v)
        # The rate as a decimal or as the percentage itself; one plus it for a fall, one minus it for a rise.
        wrongs = {M + "0": {t(p / 100), t(p)}, M + "1": {t(1 + p / 100)}}
        if r > 1:
            wrongs[E10GE_RISE_AS_FALL] = {t(1 - p / 100)}
    elif u == "value-after-years":
        st, start, r, p = e10ge_stock(q)
        m = re.fullmatch(rf"Find the {re.escape(st[1])} after (\d+) {st[4]}s?\.(?: Give your answer to 3 s\.f\.)?", asked)
        need(m is not None and asked.endswith("3 s.f.") == (paper == 2), f"asked {asked!r}")
        k = int(m.group(1))
        need(4 <= k <= 8 or (paper == 1 and 2 <= k <= 3 and p in (10, 20, 50)), "t or p is out of range")
        x = start * r ** k
        rate = p / 100
        t = value(x, st[3])
        wrongs = {M + "2": {t(start * r ** (k - 1))}, E10GE_NTH0: {t(start * r ** (k + 1))}, M + "0": {t(start * rate ** k)},
                  M + "3": {t(start * (1 + k * rate))}, M + "1": {t(start * (1 + rate) ** k)}}
        if r < 1 and 1 - k * rate > 0:
            wrongs[M + "1"].add(t(start * (1 - k * rate)))
        need(any(e10ge_near(z, x) for z in re.findall(rf"= ({E10GE_NUM})$", w["multiplier"][2])), "the multiplier's result")
        need(f"^{k} =" in w["multiplier"][2] and start == e10ge_q(w["multiplier"][2].split(" ")[0]), "the multiplier's power")
        vals = e10ge_list(w["tabulate"][1].split("Today: ")[1], r, start, "after")
        need(len(vals) == k and e10ge_near(dec_text(vals[-1]), x), "the listed rows")
    elif u == "value-in-round":
        st, u1, r, p = e10ge_flow(q)
        m = re.fullmatch(rf"Find the {re.escape(st[1])} {st[7]} {st[4]} (\d+)\.(?: Give your answer to 3 s\.f\.)?", asked)
        need(m is not None and asked.endswith("3 s.f.") == (paper == 2), f"asked {asked!r}")
        k = int(m.group(1))
        need(5 <= k <= 9 or (paper == 1 and 3 <= k <= 4 and p in (10, 20, 50)), "n or p is out of range")
        x = u1 * r ** (k - 1)
        rate = p / 100
        t = value(x, st[3])
        wrongs = {E10GE_NTH0: {t(u1 * r ** k)}, M + "0": {t(u1 * rate ** (k - 1))}, M + "3": {t(u1 * (1 + (k - 1) * rate))}, M + "1": {t(u1 * (1 + rate) ** (k - 1))}}
        if r < 1 and 1 - (k - 1) * rate > 0:
            wrongs[M + "1"].add(t(u1 * (1 - (k - 1) * rate)))
        need(f"^{k - 1} = " in w["multiplier"][2] and e10ge_near(w["multiplier"][2].rsplit("= ", 1)[1], x), "the multiplier's result")
        vals = e10ge_list(w["tabulate"][1].split(f"{st[4].capitalize()} 1: ")[1].split(";", 1)[1], r, u1, st[4])
        need(len(vals) == k - 1 and e10ge_near(dec_text(vals[-1]), x), "the listed rows")
    elif u == "term-number-after":
        st, _, _, _ = e10ge_stock(q)
        m = re.search(rf"uₙ is the {re.escape(st[1])} after (\d+) {st[4]}s?\.$", asked)
        need(m is not None and asked.startswith(f"Let u₁ be the {st[1]} today, u₂ the {st[1]} after 1 {st[4]}"), f"asked {asked!r}")
        k = int(m.group(1))
        # u₁ is after 0 steps, so count the terms: after k steps there have been k + 1.
        names = list(range(0, k + 1))
        want = f"n = {len(names)}"
        wrongs = {E10GE_F + "7": {f"n = {k}"}}
    elif u == "rebound-height":
        m = re.fullmatch(rf"A (.+) is dropped from a height of ({E10GE_NUM}) (cm|m)\. Each time it lands it rebounds to (\S+) of the height it fell from\.", L[0])
        need(m is not None and m.group(1) in E10GE_BALLS, f"the story {L[0]!r}")
        h, unit = e10ge_q(m.group(2)), " " + m.group(3)
        r = e10ge_q(m.group(4)) if paper == 1 else e10ge_q(m.group(4).rstrip("%")) / 100
        need((paper == 1) == (unit == " cm"), "the unit doesn't fit the paper")
        if rep == "diagram":
            g = q["graph"]
            need(g["kind"] == "bounce" and abs(g["peaks"][2] - float(r ** 2)) < 1e-9 and g["h_label"] == dec_text(h) + unit, "the figure is not this ball")
        m = re.fullmatch(r"Find the height it reaches after the (\d+)(?:st|nd|rd|th) bounce\.(?: Give your answer to 3 s\.f\.)?", asked)
        need(m is not None and bool(asked.endswith("3 s.f.")) == (paper == 2), f"asked {asked!r}")
        k = int(m.group(1))
        x = h * r ** k
        slip = h - k * (h - h * r)
        if paper == 1:
            need(x.q == 1 and 40 <= h <= 1000, "a Paper 1 height is not whole")
            t = value(x, unit)
            vals = e10ge_list(w["tabulate"][1], r, h, "after bounce") if "tabulate" in w else [x]
            need(vals[-1] == x, "the listed rows")
