            a_row, b_row = q["table"]["rows"][1:3]
            need(a_row[0] == f"Deal A ({st[3]})" and b_row[0] == f"Deal B ({st[3]})", "the table's headings")
            need(len(set(a_row[1])) == 1, "Deal A isn't flat")
