            if u == "least-n-term":
                wrongs[F + "5"] = {f"n = {e10ge_first(lambda i: tot(i) > t_)}"}
            elif totals:
                wrongs[F + "5"] = {f"n = {e10ge_first(lambda i: term(i) > t_)}"}
