# ── solid-angle (t3-3d-angle, FAL-754) ───────────────────────────────────
# The `solid-angle` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/solid_angle.gd. The solid or the points are read back from the
# sentences or the figure's labels (never the question's `given`), put on the checker's own
# axes, and every angle is found again from vectors with SymPy: a line and a plane from the
# rise over the length, two lines from their dot product. Each tagged slip is worked out
# again from its description, and every sum, length and ratio in the working is evaluated.
E12SA_LP = "SL3.1.angle-line-plane#"
E12SA_TL = "SL3.1.angle-two-lines#"
E12SA_T = "t3-3d-angle#"
E12SA_LINE_PLANE = ("cuboid-diagonal-base", "pyramid-edge-base", "pyramid-face-base", "cone-slant-base", "coords-line-plane", "landmark-angle")
E12SA_LOW, E12SA_HIGH = 12, 78
E12SA_WIDE_LOW, E12SA_WIDE_HIGH = 20, 160
E12SA_RIGHT_GAP = 4
E12SA_LANDMARK_GAP = sp.Rational(1, 2)
E12SA_EDGE = sp.Rational(3, 100)
E12SA_LONGEST = 18
E12SA_REACH = 12
E12SA_BANK = {(8, 6, 10), (6, 8, 10), (6, 8, 9), (8, 6, 9)}
E12SA_BANK_POINTS = {((8, 6, 0), (4, 3, 10)), ((6, 8, 0), (3, 4, 9)), ((1, -2, 3), (4, 2, 15))}
E12SA_N = r"−?\d+"


def e12sa_int(t):
    return int(t.replace("−", "-"))


def e12sa_sub(a, b):
    return tuple(x - y for x, y in zip(a, b))


def e12sa_dot(a, b):
    return sum(x * y for x, y in zip(a, b))


def e12sa_len(a):
    return sp.sqrt(e12sa_dot(a, a))


def e12sa_between(u, v):
    """The angle between two directions, in degrees, exactly."""
    return sp.acos(sp.nsimplify(e12sa_dot(u, v)) / (e12sa_len(u) * e12sa_len(v))) * 180 / sp.pi


def e12sa_to_plane(d):
    """The angle between a direction and the horizontal plane, in degrees."""
    return sp.asin(sp.Abs(d[2]) / e12sa_len(d)) * 180 / sp.pi


def e12sa_deg_atan(y, x):
    return sp.atan(sp.nsimplify(y) / sp.nsimplify(x)) * 180 / sp.pi


def e12sa_n(x):
    return sp.N(x, 40)


def e12sa_text(label, x):
    return f"{label}{gc_s(e12sa_n(x))}°"


def e12sa_clear(x):
    """x is clear of a rounding edge at 3 s.f. by E12SA_EDGE of a unit in the third figure."""
    v = abs(e12sa_n(x))
    e = sp.floor(sp.log(v, 10))
    scaled = v / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= E12SA_EDGE


def e12sa_real(x):
    """A wrong value that is a real angle reading clearly at 3 s.f., as the engine keeps them."""
    v = e12sa_n(x)
    if not v.is_real or v <= sp.Rational(1, 2) or v >= sp.Rational(359, 2):
        return False
    e = sp.floor(sp.log(abs(v), 10))
    scaled = abs(v) / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= sp.Rational(1, 500)


def e12sa_acos(c):
    c = sp.nsimplify(c)
    return sp.acos(c) * 180 / sp.pi if abs(e12sa_n(c)) <= 1 else None


def e12sa_asin(c):
    c = sp.nsimplify(c)
    return sp.asin(c) * 180 / sp.pi if abs(e12sa_n(c)) <= 1 else None


# Reading the question back.

def e12sa_unit_lengths(text, names):
    out = {}
    for n in names:
        m = re.search(rf"\b{n} = (?:[A-Z]{{2}} = )?(\d+) (cm|m)\b", text)
        if m:
            out[n] = int(m.group(1))
    return out


def e12sa_label_len(g, a, b):
    for ln in g["lines"]:
        if {ln["a"], ln["b"]} == {a, b} and ln.get("label"):
            m = re.fullmatch(r"(\d+) (cm|m)", ln["label"])
            need(m is not None, f"can't read the measure {ln['label']!r}")
            return int(m.group(1))
    return None


def e12sa_pt(g, n):
    return tuple(sp.nsimplify(v) for v in g["pts"][n])


def e12sa_dist(g, a, b):
    return e12sa_len(e12sa_sub(e12sa_pt(g, a), e12sa_pt(g, b)))


def e12sa_asked_lines(g):
    return sorted("".join(sorted([ln["a"], ln["b"]])) for ln in g["lines"] if ln["asked"])


def e12sa_box(q, rep):
    """A cuboid's AB, BC and AE from the words or the figure's measures."""
    text = " ".join(q["lines"])
    if rep == "words":
        need(q["graph"] is None, "a story has a figure")
        d = e12sa_unit_lengths(text, ["AB", "BC", "AE"])
        need(len(d) == 3, f"can't read the cuboid in {text!r}")
        return d["AB"], d["BC"], d["AE"]
    g = q["graph"]
    need(g is not None and g["kind"] == "space" and not g["axes"], "no figure of the cuboid")
    l, w, h = (e12sa_label_len(g, *e) for e in ("AB", "BC", "AE"))
    need(None not in (l, w, h), "the figure doesn't give AB, BC and AE")
    # The figure is a box with those edges.
    P = {n: e12sa_pt(g, n) for n in "ABCDEFGH"}
    a = P["A"]
    u, v, z = e12sa_sub(P["B"], a), e12sa_sub(P["D"], a), e12sa_sub(P["E"], a)
    need(e12sa_dot(u, v) == 0 and e12sa_dot(u, z) == 0 and e12sa_dot(v, z) == 0, "the figure's edges at A are not at right angles")
    need(z[0] == 0 and z[1] == 0 and z[2] > 0, "E is not directly above A")
    need((e12sa_len(u), e12sa_len(v), e12sa_len(z)) == (l, w, h), "the figure is not drawn to its measures")
    for n, parts in {"C": "BD", "F": "BE", "G": "BDE", "H": "DE"}.items():
        want = tuple(a[i] + sum(e12sa_sub(P[p], a)[i] for p in parts) for i in range(3))
        need(P[n] == want, f"{n} is not a corner of the box")
    return l, w, h


def e12sa_cuboid_pts(l, w, h):
    P = {"A": (0, 0, 0), "B": (l, 0, 0), "C": (l, w, 0), "D": (0, w, 0)}
    for low, high in zip("ABCD", "EFGH"):
        P[high] = P[low][:2] + (h,)
    P["M"] = (sp.Rational(l, 2), sp.Rational(w, 2), sp.Rational(h, 2))
    return P


def e12sa_pyramid(q, rep, landmark=False):
    """A pyramid's AB, BC and height VX (exactly, from equal edges on Paper 1)."""
    text = " ".join(q["lines"])
    if rep == "words":
        need(q["graph"] is None, "a story has a figure")
        m = re.search(r"base ABCD is a (square|rectangle) with (?:AB = BC = (\d+) (cm|m)|AB = (\d+) (cm|m) and BC = (\d+) (cm|m)).*VX = (\d+) (cm|m)\.", text)
        need(m is not None, f"can't read the pyramid in {text!r}")
        if m.group(1) == "square":
            l = w = int(m.group(2))
        else:
            l, w = int(m.group(4)), int(m.group(6))
            need(l != w, "a rectangle with equal sides")
        return l, w, sp.Integer(m.group(8)), None
    g = q["graph"]
    need(g is not None and g["kind"] == "space" and not g["axes"], "no figure of the pyramid")
    l, w = e12sa_label_len(g, "A", "B"), e12sa_label_len(g, "B", "C")
    need(l is not None and w is not None, "the figure doesn't give AB and BC")
    shape = re.search(r"with a (square|rectangular) base", text)
    need(shape is not None and (shape.group(1) == "square") == (l == w), "the base's shape is not its measures")
    P = {n: e12sa_pt(g, n) for n in "ABCDV"}
    u, v = e12sa_sub(P["B"], P["A"]), e12sa_sub(P["D"], P["A"])
    need(e12sa_dot(u, v) == 0 and u[2] == 0 and v[2] == 0 and (e12sa_len(u), e12sa_len(v)) == (l, w), "the base is not drawn to its measures")
    need(P["C"] == tuple(P["B"][i] + v[i] for i in range(3)), "C is not a corner of the base")
    centre = tuple((P["A"][i] + P["C"][i]) / 2 for i in range(3))
    need(P["V"][:2] == centre[:2] and P["V"][2] > 0, "V is not above the centre of the base")
    slant = None
    if landmark:
        need("every edge of the pyramid has the same length" in text, "the equal edges aren't stated")
        lens = [e12sa_label_len(g, "V", k) for k in "ABCD"]
        lens = [x for x in lens if x is not None]
        need(len(lens) == 1 and l == w == lens[0], "the slant edge is not given equal to the base edge")
        slant = lens[0]
        h = sp.sqrt(sp.Integer(slant) ** 2 - sp.Rational(l * l + w * w, 4))
    else:
        h = e12sa_label_len(g, "V", "X")
        need(h is not None, "the figure doesn't give VX")
        h = sp.Integer(h)
    need(sp.simplify(P["V"][2] - h) == 0 or abs(float(P["V"][2]) - float(h)) < 1e-9, "V is not drawn at its height")
    return l, w, h, slant


def e12sa_pyramid_pts(l, w, h):
    # SymPy integers throughout, so a midpoint is an exact half, never a float.
    l, w, z = sp.Integer(l), sp.Integer(w), sp.Integer(0)
    P = {"A": (z, z, z), "B": (l, z, z), "C": (l, w, z), "D": (z, w, z)}
    P["X"] = (sp.Rational(l, 2), sp.Rational(w, 2), 0)
    P["V"] = (sp.Rational(l, 2), sp.Rational(w, 2), h)
    return P


def e12sa_cone(q, rep):
    """A cone's r, h and slant height, each exact; the two given ones whole."""
    text = " ".join(q["lines"])
    if rep == "words":
        need(q["graph"] is None, "a story has a figure")
        got = {}
        for key, words in (("r", "base radius"), ("h", "vertical height"), ("l", "slant height")):
            m = re.search(rf"its {words} is (\d+) (cm|m)", text)
            if m:
                got[key] = sp.Integer(m.group(1))
    else:
        g = q["graph"]
        need(g is not None and g["kind"] == "space", "no figure of the cone")
        got = {}
        for key, (a, b) in (("r", "OA"), ("h", "VO"), ("l", "VA")):
            v = e12sa_label_len(g, a, b)
            if v is not None:
                got[key] = sp.Integer(v)
    need(len(got) == 2, f"the cone gives {sorted(got)}, not two measures")
    r, h, l = got.get("r"), got.get("h"), got.get("l")
    if r is None:
        r = sp.sqrt(l ** 2 - h ** 2)
    if h is None:
        h = sp.sqrt(l ** 2 - r ** 2)
    if l is None:
        l = sp.sqrt(r ** 2 + h ** 2)
    need(e12sa_n(r) > 0 and e12sa_n(h) > 0 and e12sa_n(l) > e12sa_n(r) and e12sa_n(l) > e12sa_n(h), "not a cone")
    if rep == "diagram":
        g = q["graph"]
        O, V, A = (e12sa_pt(g, n) for n in "OVA")
        need(abs(float(e12sa_len(e12sa_sub(V, O))) - float(h)) < 1e-6 and abs(float(e12sa_len(e12sa_sub(A, O))) - float(r)) < 1e-6, "the cone is not drawn to its measures")
        need(e12sa_dot(e12sa_sub(V, O), e12sa_sub(A, O)) == 0 and A[2] == O[2], "VO is not at right angles to the base")
        need(len(g.get("rims", [])) == 1 and abs(float(g["rims"][0]["r"]) - float(r)) < 1e-6, "the rim is not the base")
    return r, h, l, sorted(got)


def e12sa_points(q, rep, names, drops=False):
    """The points from the words or the figure's labels. A line-plane figure drops each point
    to the xy-plane; a triangle's figure has no drops."""
    text = " ".join(q["lines"])
    out = {}
    if rep == "diagram":
        g = q["graph"]
        need(g is not None and g["kind"] == "space" and g["axes"], "no axes")
        for n in names:
            m = re.fullmatch(rf"{n}\(({E12SA_N}), ({E12SA_N}), ({E12SA_N})\)", g["labels"][n])
            need(m is not None, f"can't read {g['labels'][n]!r}")
            out[n] = tuple(e12sa_int(t) for t in m.groups())
            need(e12sa_pt(g, n) == out[n], f"{n} is drawn at the wrong place")
            if drops and out[n][2] != 0:
                need(g["pts"].get("_" + n) is not None and e12sa_pt(g, "_" + n) == out[n][:2] + (0,), f"{n}'s drop to the xy-plane is wrong")
        return out
    need(q["graph"] is None, "only a diagram has a figure")
    for n in names:
        pat = rf"\b{n.lower()} = \(({E12SA_N}), ({E12SA_N}), ({E12SA_N})\)" if rep == "notation" else rf"\b{n}\(({E12SA_N}), ({E12SA_N}), ({E12SA_N})\)"
        m = re.search(pat, text)
        need(m is not None, f"can't read {n} in {text!r}")
        out[n] = tuple(e12sa_int(t) for t in m.groups())
    if rep == "notation":
        need("position vectors" in text, "the vectors are not called position vectors")
    return out


# The working.

def e12sa_value(t):
    """A sum of numbers and roots as it is written, or None if it isn't only numbers."""
    t = t.strip().rstrip(".")
    if not t or not re.fullmatch(r"[\d.+−×÷()√² ]+", t) or not re.search(r"\d", t):
        return None
    if t.count("(") != t.count(")"):
        return None
    t = t.replace("−", "-").replace("×", "*").replace("÷", "/").replace("²", "**2")
    t = re.sub(r"(\d)√", r"\1*√", t)
    t = t.replace("√(", "sqrt(")
    t = re.sub(r"√(\d+(?:\.\d+)?)", r"sqrt(\1)", t)
    if "√" in t:
        return None
    t = re.sub(r"(?<![\w.])(\d+(?:\.\d+)?)", lambda m: f"sp.Rational('{m.group(1)}')", t)
    try:
        return eval(t, {"sp": sp, "sqrt": sp.sqrt})
    except (SyntaxError, TypeError, ZeroDivisionError):
        return None


def e12sa_same(a, b):
    return abs(e12sa_n(a - b)) < sp.Float("1e-25")


def e12sa_clauses(st):
    return [c.strip() for c in re.split(r", (?![^()]*\))| and (?=[A-Z]{2}²? = )|: |\. (?=[A-Z(√])|\.$", st) if c.strip()]


def e12sa_steps(q, P, name, t, paper):
    """Every sum and named length in the working is true, each ratio is the angle's, and each
    inverse gives the answer."""
    tf = e12sa_n(t)
    ans = q["answer_text"]
    ratio_of = {"tan": sp.tan, "sin": sp.sin, "cos": sp.cos}
    for sol in q["solutions"]:
        found_ratio = found_inverse = False
        for st in sol["steps"]:
            for c in e12sa_clauses(st):
                c2 = re.sub(r"^(so|and|then|Then|So) ", "", c)
                pieces = c2.split(" = ")
                vals = [e12sa_value(p) for p in pieces]
                nums = [v for v in vals if v is not None]
                for x, y in zip(nums, nums[1:]):
                    need(e12sa_same(x, y), f"{c!r} doesn't add up in {st!r}")
                if not nums:
                    continue
                # A named length or its square is the length of that segment on the checker's axes.
                for p in pieces:
                    m = re.fullmatch(r"(?:[A-Za-z ]+ )?([A-Z]{2})(²?)", p.strip())
                    if m and m.group(1)[0] in P and m.group(1)[1] in P and m.group(1)[0] != m.group(1)[1] and not re.search(r"[A-Z]{3}$", p.strip()):
                        L = e12sa_len(e12sa_sub(P[m.group(1)[0]], P[m.group(1)[1]]))
                        need(e12sa_same(L ** (2 if m.group(2) else 1), nums[0]), f"{m.group(1)} is not {nums[0]} in {st!r}")
                # A ratio is the ratio of the angle itself.
                m = re.fullmatch(rf"(tan|sin|cos) (?:θ|{re.escape(name)})", pieces[0])
                half = re.fullmatch(rf"sin\({re.escape(name)} ÷ 2\)", pieces[0])
                if m or half:
                    fn = sp.sin if half else ratio_of[m.group(1)]
                    want = fn((tf / 2 if half else tf) * sp.pi / 180)
                    need(abs(e12sa_n(nums[-1]) - e12sa_n(want)) < sp.Float("1e-12"), f"{c!r} is not the ratio of the angle")
                    found_ratio = True
            for m in re.finditer(r"(2 × )?(tan|sin|cos)⁻¹\((.+)\) = ([\d.]+)° to 3 s\.f\.", st):
                v = e12sa_value(m.group(3))
                need(v is not None, f"can't evaluate {m.group(3)!r}")
                x = {"tan": sp.atan, "sin": sp.asin, "cos": sp.acos}[m.group(2)](v) * 180 / sp.pi * (2 if m.group(1) else 1)
                need(e12sa_same(x, t), f"{m.group(0)!r} is not the angle")
                need(gc_s(e12sa_n(x)) == m.group(4), f"{m.group(0)!r} is not rounded right")
                found_inverse = True
            for m in re.finditer(rf"Δx = ({E12SA_N}), Δy = ({E12SA_N}) and Δz = ({E12SA_N})", st):
                d = tuple(e12sa_int(x) for x in m.groups())
                need(d == e12sa_sub(P["B"], P["A"]), f"the moves in {st!r} are not B − A")
        need(found_ratio if paper == 1 else found_inverse, f"{sol['name']}: no {'ratio' if paper == 1 else 'inverse'} of the angle in the working")
        need(ans in sol["steps"][-1], f"{sol['name']}: the last step doesn't give {ans!r}")
        if paper == 1:
            need("⁻¹" not in " ".join(sol["steps"]), f"{sol['name']}: an inverse on Paper 1")


def e12sa_read_ok(q):
    for t in [q["asked"]] + q["lines"] + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z])-\d", t), f"a hyphen for a minus in {t!r}")


def e12sa_limits(u, t, paper):
    tv = e12sa_n(t)
    if paper == 1:
        need(u == "landmark-angle", f"{u} is Paper 2")
        need(sp.nsimplify(sp.simplify(t)) in (30, 45, 60), f"the landmark angle is {tv}")
        return
    need(u != "landmark-angle", "landmark-angle is Paper 1")
    need(e12sa_clear(t), f"the angle {tv} is on a rounding edge")
    for mark in (30, 45, 60):
        need(abs(tv - mark) >= E12SA_LANDMARK_GAP, f"the angle {tv} is too close to {mark}°")
    if u in E12SA_LINE_PLANE:
        need(E12SA_LOW <= tv <= E12SA_HIGH, f"the line-plane angle {tv} is out of range")
    else:
        need(E12SA_WIDE_LOW <= tv <= E12SA_WIDE_HIGH and abs(tv - 90) >= E12SA_RIGHT_GAP, f"the angle between lines {tv} is out of range")


def e12sa_sign_change(*pts):
    return any(a[i] * b[i] < 0 for a, b in combinations(pts, 2) for i in range(3))


def e12sa_name_of(asked):
    m = re.search(r"size of angle ([A-Z]{3})", asked)
    return m.group(1) if m else "θ"


def E12SA_check(q):
    u, rep, paper, asked = q["view"]["unknown"], q["view"]["rep"], q["paper"], q["asked"]
    text = " ".join(q["lines"])
    e12sa_read_ok(q)
    name = e12sa_name_of(asked)
    label = "θ = " if name == "θ" else f"angle {name} = "
    LP, TL, T = E12SA_LP, E12SA_TL, E12SA_T
    w = defaultdict(list)
    g = q["graph"]
    need(paper == (1 if u == "landmark-angle" else 2), f"{u} on Paper {paper}")
    if paper == 2:
        need(asked.endswith("Give your answer to 3 significant figures."), "Paper 2 doesn't ask for 3 s.f.")

    def solid_figure(asked_lines, base_shaded):
        if rep != "diagram":
            return
        need(e12sa_asked_lines(g) == sorted("".join(sorted(x)) for x in asked_lines), f"the figure marks {e12sa_asked_lines(g)}, not {asked_lines}")
        need((g.get("faces") == [["A", "B", "C", "D"]]) == base_shaded, "the base is shaded wrongly")

    if u in ("cuboid-diagonal-base", "cuboid-two-diagonals", "cuboid-diagonal-edge") or (u == "landmark-angle" and "cuboid" in text):
        l, w_, h = e12sa_box(q, "diagram" if u == "landmark-angle" else rep)
        if u == "landmark-angle":
            need(q["graph"] is not None, "a landmark angle has no figure")
        need(len({l, w_, h}) == 3 or u == "landmark-angle", "two edges of the cuboid are equal")
        need(all(2 <= x <= E12SA_LONGEST for x in (l, w_, h)), "an edge is out of range")
        P = e12sa_cuboid_pts(l, w_, h)
        AG = e12sa_sub(P["G"], P["A"])
        d = e12sa_len(AG)
        if u in ("cuboid-diagonal-base", "landmark-angle"):
            need("between the diagonal AG and the base ABCD" in asked, "not the diagonal and the base")
            t = e12sa_to_plane(AG)
            solid_figure(["AG"], True)
            if u == "cuboid-diagonal-base":
                w[LP + "0"] += [e12sa_between(AG, e12sa_sub(P[k], P["A"])) for k in "BD"]
                w[LP + "1"].append(e12sa_deg_atan(sp.sqrt(l * l + w_ * w_), h))
                w[T + "7"].append(e12sa_deg_atan(h, d))
            else:
                w[T + "6"].append(90 - t)
        elif u == "cuboid-two-diagonals":
            m = re.search(r"The diagonals AG and ([A-H]{2}) meet at M\.", text)
            need(m is not None, "can't read the diagonals")
            other = m.group(1)
            need(e12sa_same(P[other[0]][0] + P[other[1]][0], l) and e12sa_same(P[other[0]][1] + P[other[1]][1], w_) and P[other[0]][2] + P[other[1]][2] == h,
                 f"{other} is not a space diagonal")
            corner = next(c for c in other if name == "AM" + c)
            e = e12sa_len(e12sa_sub(P[corner], P["A"]))
            MA, MB = e12sa_sub(P["A"], P["M"]), e12sa_sub(P[corner], P["M"])
            t = e12sa_between(MA, MB)
            solid_figure(["AG", other], False)
            if rep == "diagram":
                w[TL + "0"].append(sp.Integer(90))
                need(any(a["at"] == "M" and {a["from"], a["to"]} == {"A", corner} for a in g.get("angles", [])), "the angle at M isn't marked")
            for f in (l * l + w_ * w_, l * l + h * h, w_ * w_ + h * h):
                c = e12sa_acos(1 - sp.Rational(2) * e * e / f)
                if c is not None:
                    w[TL + "1"].append(c)
            w[TL + "2"].append(e12sa_between(e12sa_sub(P["M"], P["A"]), e12sa_sub(P[corner], P["A"])))
            w[T + "13"].append(t / 2)
            n = d ** 2
            w[T + "14"].append(e12sa_acos((2 * n - e * e) / (2 * n)))
            w[T + "15"].append(e12sa_acos((2 * n / 4 - e * e) / (n / 4)))
            w[T + "17"].append(180 - t)
        else:
            m = re.search(r"between the diagonal AG and the edge (A[BDE])\.", asked)
            need(m is not None and name == "G" + m.group(1), "can't read the edge")
            edge = m.group(1)
            E = e12sa_sub(P[edge[1]], P["A"])
            t = e12sa_between(AG, E)
            solid_figure(["AG", edge], False)
            ek = e12sa_len(E)
            leg = e12sa_len(e12sa_sub(P["G"], P[edge[1]]))
            for other in "BDE":
                if other != edge[1]:
                    f = e12sa_sub(P[edge[1]], P["A"])
                    fd = tuple(a + b for a, b in zip(f, e12sa_sub(P[other], P["A"])))
                    w[TL + "1"].append(e12sa_between(fd, E))
            w[TL + "2"].append(e12sa_between(e12sa_sub(P["A"], P["G"]), e12sa_sub(P[edge[1]], P["G"])))
            w[T + "19"] += [e12sa_deg_atan(leg, d), e12sa_deg_atan(ek, d)]
            if edge != "AE":
                w[T + "18"].append(e12sa_to_plane(AG))
    elif u in ("pyramid-edge-base", "pyramid-face-base", "pyramid-apex-angle") or (u == "landmark-angle" and "pyramid" in text):
        lm = u == "landmark-angle"
        l, w_, h, slant = e12sa_pyramid(q, "diagram" if lm else rep, lm)
        need(all(3 <= x <= 14 for x in (l, w_)) and (lm or 3 <= h <= E12SA_LONGEST), "a measure is out of range")
        if not lm:
            need((l, w_, int(h)) not in E12SA_BANK, "the bank's pyramid")
        P = e12sa_pyramid_pts(l, w_, h)
        if u in ("pyramid-edge-base", "landmark-angle"):
            m = re.search(r"between the edge V([A-D]) and the base ABCD", asked)
            need(m is not None, "can't read the edge")
            k = m.group(1)
            VK = e12sa_sub(P["V"], P[k])
            t = e12sa_to_plane(VK)
            solid_figure(["V" + k], True)
            if lm:
                w[T + "6"].append(90 - t)
            else:
                xk = e12sa_len(e12sa_sub(P["X"], P[k]))
                nb = [n for n in "ABCD" if n != k and ("ABCD".index(n) - "ABCD".index(k)) % 2 == 1]
                w[LP + "0"] += [e12sa_between(e12sa_sub(P["V"], P[k]), e12sa_sub(P[n], P[k])) for n in nb]
                mids = [tuple((a + b) / 2 for a, b in zip(P[k], P[n])) for n in nb]
                w[LP + "2"] += [e12sa_deg_atan(h, e12sa_len(e12sa_sub(P["X"], mm))) for mm in mids]
                w[T + "6"].append(90 - t)
                w[T + "7"].append(e12sa_deg_atan(h, e12sa_len(VK)))
                w[T + "8"].append(e12sa_deg_atan(h, 2 * xk))
        elif u == "pyramid-face-base":
            m = re.search(r"M is the midpoint of ([A-D]{2})\.", text)
            need(m is not None and m.group(1) in ("AB", "BC", "CD", "DA"), "can't read M")
            e = m.group(1)
            need("between the line VM and the base ABCD" in asked, "not VM and the base")
            P["M"] = tuple((a + b) / 2 for a, b in zip(P[e[0]], P[e[1]]))
            if rep == "diagram":
                mg = e12sa_pt(g, "M")
                ga, gb = e12sa_pt(g, e[0]), e12sa_pt(g, e[1])
                need(mg == tuple((a + b) / 2 for a, b in zip(ga, gb)), "M is not drawn at the midpoint")
            VM = e12sa_sub(P["V"], P["M"])
            t = e12sa_to_plane(VM)
            solid_figure(["VM"], True)
            edge_len = e12sa_len(e12sa_sub(P[e[0]], P[e[1]]))
            w[LP + "2"].append(e12sa_deg_atan(h, e12sa_len(e12sa_sub(P["X"], P["A"]))))
            w[T + "6"].append(90 - t)
            w[T + "7"].append(e12sa_deg_atan(h, e12sa_len(VM)))
            if l != w_:
                w[T + "9"].append(e12sa_deg_atan(h, edge_len / 2))
        else:
            m = re.fullmatch(r"([A-D])V([A-D])", name)
            need(m is not None and name in ("AVB", "BVC", "AVC"), f"can't read the angle {name}")
            a, b = m.groups()
            VA, VB = e12sa_sub(P[a], P["V"]), e12sa_sub(P[b], P["V"])
            t = e12sa_between(VA, VB)
            solid_figure(["V" + a, "V" + b], False)
            side = e12sa_len(e12sa_sub(P[a], P[b]))
            s = e12sa_len(VA)
            if rep == "diagram":
                w[TL + "0"].append(e12sa_deg_atan(side, s))
                need(any(x["at"] == "V" and {x["from"], x["to"]} == {a, b} for x in g.get("angles", [])), "the angle at V isn't marked")
            w[TL + "2"].append(e12sa_between(e12sa_sub(P["V"], P[a]), e12sa_sub(P[b], P[a])))
            w[T + "13"].append(t / 2)
            w[T + "15"].append(e12sa_acos((2 * s ** 2 - side ** 2) / s ** 2))
            c = e12sa_asin(side / 2 / h)
            if c is not None:
                w[T + "16"].append(2 * c)
    elif u in ("cone-slant-base",) or (u == "landmark-angle" and "cone" in text):
        r, h, sl, given = e12sa_cone(q, "diagram" if u == "landmark-angle" else rep)
        need("between the slant height VA and the base of the cone" in asked, "not the slant height and the base")
        t = e12sa_to_plane((r, 0, h))
        P = {"O": (0, 0, 0), "A": (r, 0, 0), "V": (0, 0, h)}
        if rep == "diagram" or u == "landmark-angle":
            need(e12sa_asked_lines(g) == ["AV"], "the slant height isn't marked")
        w[T + "6"].append(90 - t)
        if u == "cone-slant-base":
            need(all(e12sa_n(x) <= E12SA_LONGEST for k, x in (("h", h), ("l", sl), ("r", r)) if k in given), "a given measure is out of range")
            w[T + "10"].append(e12sa_deg_atan(h, 2 * r))
            w[T + "11"].append(e12sa_deg_atan(sl, r))
            w[T + "7"].append(e12sa_deg_atan(h, sl))
    elif u == "coords-line-plane":
        P = e12sa_points(q, rep, ["A", "B"], drops=True)
        need("between the line AB and the xy-plane" in asked, "not AB and the xy-plane")
        need(all(abs(v) <= E12SA_REACH for p in P.values() for v in p), "a point is out of reach")
        need(e12sa_sign_change(P["A"], P["B"]), "no coordinate changes sign")
        need((P["A"], P["B"]) not in E12SA_BANK_POINTS and (P["B"], P["A"]) not in E12SA_BANK_POINTS, "the bank's points")
        dv = e12sa_sub(P["B"], P["A"])
        need(dv[2] != 0 and (dv[0], dv[1]) != (0, 0), "AB is vertical or level")
        t = e12sa_to_plane(dv)
        if rep == "diagram":
            need(e12sa_asked_lines(g) == ["AB"], "AB isn't marked")
        rise = abs(dv[2])
        w[T + "6"].append(90 - t)
        w[T + "7"].append(e12sa_deg_atan(rise, e12sa_len(dv)))
        w[T + "12"] += [e12sa_deg_atan(rise, abs(x)) for x in dv[:2] if x != 0]
    elif u in ("coords-angle-abc", "coords-right-angle"):
        P = e12sa_points(q, rep, ["A", "B", "C"])
        need(name == "ABC", "not angle ABC")
        need(all(abs(v) <= E12SA_REACH for p in P.values() for v in p), "a point is out of reach")
        need(e12sa_sign_change(P["A"], P["B"], P["C"]), "no coordinate changes sign")
        BA, BC = e12sa_sub(P["A"], P["B"]), e12sa_sub(P["C"], P["B"])
        t = e12sa_between(BA, BC)
        at_a = e12sa_between(e12sa_sub(P["B"], P["A"]), e12sa_sub(P["C"], P["A"]))
        at_c = e12sa_between(e12sa_sub(P["A"], P["C"]), e12sa_sub(P["B"], P["C"]))
        rights = [n for n, x in (("A", at_a), ("B", t), ("C", at_c)) if sp.simplify(x - 90) == 0]
        if u == "coords-right-angle":
            need(len(rights) == 1 and rights[0] in "AC", f"the right angle is at {rights}, not A or C")
        else:
            need(not rights and all(abs(e12sa_n(x) - 90) >= E12SA_RIGHT_GAP and e12sa_n(x) >= 12 for x in (at_a, t, at_c)), "a triangle near a right angle, or thin")
        if rep == "diagram":
            need(e12sa_asked_lines(g) == ["AB", "BC"], "AB and BC aren't marked")
            need(any(x["at"] == "B" for x in g.get("angles", [])), "the angle at B isn't marked")
        p2, q2, r2 = e12sa_dot(BA, BA), e12sa_dot(BC, BC), e12sa_dot(e12sa_sub(P["C"], P["A"]), e12sa_sub(P["C"], P["A"]))
        w[TL + "2"] += [x for x in (at_a, at_c) if sp.simplify(x - 90) != 0]
        w[T + "15"].append(e12sa_acos(sp.Rational(p2 + q2 - r2) / sp.sqrt(p2 * q2)))
        if u == "coords-angle-abc":
            w[T + "17"].append(180 - t)
        else:
            hyp = sp.sqrt(max(p2, q2))
            w[T + "19"] += [e12sa_deg_atan(sp.sqrt(r2), hyp), e12sa_deg_atan(sp.sqrt(min(p2, q2)), hyp)]
    else:
        raise Fail(f"no check for {u}")

    e12sa_limits(u, t, paper)
    if paper == 1:
        tv = int(sp.nsimplify(sp.simplify(t)))
        want = f"{label}{tv}°"
        wrongs = {ref: {f"{label}{int(sp.nsimplify(sp.simplify(x)))}°" for x in xs} for ref, xs in w.items()}
        trap = None
        need("exact" in asked, "a Paper 1 angle isn't asked exactly")
    else:
        want = e12sa_text(label, t)
        wrongs = {ref: {e12sa_text(label, x) for x in xs if x is not None and e12sa_real(x)} for ref, xs in w.items()}
        trap = f"{label}{gc_s2(e12sa_n(t))}°"
    gc_check_common(q, want, wrongs, trap)
    e12sa_steps(q, P, name, t, paper)
    return None, None


SITUATION_CHECKS["solid-angle"] = E12SA_check

# ── end solid-angle ──


# ── polynomial-conditions (t5-ext-unknown-coefficients, t5-ext-stationary-conditions, FAL-776) ──
# The checker's own reading of the curve and its conditions, from the lines the student sees.
# The letters are SymPy symbols, so the derivative is SymPy's, and the conditions are solved
# with sp.solve. Each tagged slip is worked out from its own wrong equations. Every line of the
# working that states an equation is checked to be that condition, and error-spot lines are
# judged one by one against the true curve. The clean limits are the checker's own copy:
# the engine's are in game/engine/situations/polynomial_conditions.gd.

E13PC_X = sp.Symbol("x")
E13PC_L = {n: sp.Symbol(n) for n in "abckp"}
E13PC_UC, E13PC_SC = "SL5.3.unknown-coefficients#", "SL5.8.stationary-point-conditions#"
E13PC_NUM = r"−?\d+(?:/\d+)?"
E13PC_LIMIT, E13PC_LETTER, E13PC_GIVEN = 30, 9, 99


def E13PC_expr(text):
    """'kx³ − 4x − 3', '3ax² + b', '12a − 4b' as SymPy, the letters as symbols."""
    t = text.strip().replace("−", "-").replace("²", "**2").replace("³", "**3")
    t = re.sub(r"(\d)([a-z(])", r"\1*\2", t)
    t = re.sub(r"([abckp])x", r"\1*x", t)
    t = re.sub(r"([abckp])\(", r"\1*(", t)
    t = re.sub(r"\)\(", r")*(", t)
    need(re.fullmatch(r"[0-9abckpx*+\-/() ]+", t) is not None, f"can't read {text!r}")
    return sp.expand(parse_expr(t, local_dict={"x": E13PC_X, **E13PC_L}))


def E13PC_n(t):
    return sp.Rational(t.replace("−", "-"))


def E13PC_read(q):
    """(f, the letters, the conditions as a dict) from the question's lines."""
    u, rep, L = q["view"]["unknown"], q["view"]["rep"], q["lines"]
    if "A student's working:" in L:
        L = L[:L.index("A student's working:")]
    N = E13PC_NUM
    c = {}
    if rep == "words":
        pats = {
            "k-from-gradient": rf"The curve y = (.+) has gradient ({N}) at the point where x = ({N})\.",
            "two-from-gradient-and-point": rf"The curve y = (.+) passes through the point \(({N}), ({N})\), where its gradient is ({N})\.",
            "two-gradients": rf"The gradient of the curve y = (.+) is ({N}) where x = ({N}), and ({N}) where x = ({N})\.",
            "from-tangent": rf"The line y = (.+) is the tangent to the curve y = (.+) at the point where x = ({N})\.",
            "k-from-stationary-x": rf"The curve y = (.+) has a stationary point where x = ({N})\.",
            "two-from-stationary-point": rf"The curve y = (.+) has a stationary point at \(({N}), ({N})\)\.",
            "k-from-inflexion": rf"The curve y = (.+) has a point of inflexion where x = ({N})\.",
            "two-from-two-stationary": rf"The curve y = (.+) has stationary points where x = ({N}) and where x = ({N})\.",
        }
        need(len(L) == 1, "a words question is one line")
        m = re.fullmatch(pats[u], L[0])
        need(m is not None, f"can't read {L[0]!r}")
        g = m.groups()
        if u == "from-tangent":
            f, rest = g[1], [g[0], g[2]]
        else:
            f, rest = g[0], list(g[1:])
        if u == "k-from-gradient":
            c = {"m": E13PC_n(rest[0]), "x0": E13PC_n(rest[1])}
        elif u == "two-from-gradient-and-point":
            c = {"x0": E13PC_n(rest[0]), "y0": E13PC_n(rest[1]), "m": E13PC_n(rest[2])}
        elif u == "two-gradients":
            c = {"m": E13PC_n(rest[0]), "x0": E13PC_n(rest[1]), "m1": E13PC_n(rest[2]), "x1": E13PC_n(rest[3])}
        elif u == "from-tangent":
            c = {"line": E13PC_expr(rest[0]), "x0": E13PC_n(rest[1])}
        elif u in ("k-from-stationary-x", "k-from-inflexion"):
            c = {"x0": E13PC_n(rest[0])}
        elif u == "two-from-stationary-point":
            c = {"x0": E13PC_n(rest[0]), "y0": E13PC_n(rest[1])}
        else:
            c = {"x0": E13PC_n(rest[0]), "x1": E13PC_n(rest[1])}
    else:
        need(len(L) == 2, "an equation question is two lines")
        m = re.fullmatch(r"f\(x\) = (.+)", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        f = m.group(1)
        pats = {
            "k-from-gradient": (rf"f′\(({N})\) = ({N})\.", ("x0", "m")),
            "two-from-gradient-and-point": (rf"f′\(({N})\) = ({N}) and f\(({N})\) = ({N})\.", ("x0", "m", "x0b", "y0")),
            "two-gradients": (rf"f′\(({N})\) = ({N}) and f′\(({N})\) = ({N})\.", ("x0", "m", "x1", "m1")),
            "from-tangent": (rf"The tangent to y = f\(x\) at x = ({N}) is y = (.+)\.", ("x0", "line")),
            "k-from-stationary-x": (rf"The graph of f has a stationary point at x = ({N})\.", ("x0",)),
            "two-from-stationary-point": (rf"The graph of f has a stationary point at \(({N}), ({N})\)\.", ("x0", "y0")),
            "k-from-inflexion": (rf"The graph of f has a point of inflexion at x = ({N})\.", ("x0",)),
            "two-from-two-stationary": (rf"The graph of f has stationary points at x = ({N}) and x = ({N})\.", ("x0", "x1")),
        }
        rx, names = pats[u]
        m = re.fullmatch(rx, L[1])
        need(m is not None, f"can't read {L[1]!r}")
        for n, v in zip(names, m.groups()):
            c[n] = E13PC_expr(v) if n == "line" else E13PC_n(v)
        if "x0b" in c:
            need(c.pop("x0b") == c["x0"], "the gradient and the point are at different x")
    F = E13PC_expr(f)
    letters = sorted((s for s in F.free_symbols if s != E13PC_X), key=lambda s: s.name)
    return F, letters, c


def E13PC_solve(eqs, letters):
    sol = sp.solve(eqs, letters, dict=True)
    need(len(sol) == 1 and all(l in sol[0] for l in letters), f"{eqs} do not fix {letters} once")
    return [sp.Rational(sol[0][l]) for l in letters]


def E13PC_text(letters, vals):
    return ", ".join(f"{l.name} = {frac_text(v)}" for l, v in zip(letters, vals))


def E13PC_at(e, x):
    return sp.expand(e.subs(E13PC_X, x))


def E13PC_conditions(u, F, c):
    """The true equations, each (expression, value)."""
    X = E13PC_X
    d1, d2 = sp.diff(F, X), sp.diff(F, X, 2)
    x0 = c["x0"]
    if u == "k-from-gradient":
        return [(E13PC_at(d1, x0), c["m"])]
    if u == "two-from-gradient-and-point":
        return [(E13PC_at(d1, x0), c["m"]), (E13PC_at(F, x0), c["y0"])]
    if u == "two-gradients":
        return [(E13PC_at(d1, x0), c["m"]), (E13PC_at(d1, c["x1"]), c["m1"])]
    if u == "from-tangent":
        line = sp.Poly(c["line"], X)
        need(line.degree() == 1, "the tangent is not a line")
        return [(E13PC_at(d1, x0), line.coeff_monomial(X)), (E13PC_at(F, x0), E13PC_at(c["line"], x0))]
    if u == "k-from-stationary-x":
        return [(E13PC_at(d1, x0), 0)]
    if u == "two-from-stationary-point":
        return [(E13PC_at(d1, x0), 0), (E13PC_at(F, x0), c["y0"])]
    if u == "k-from-inflexion":
        return [(E13PC_at(d2, x0), 0)]
    return [(E13PC_at(d1, x0), 0), (E13PC_at(d1, c["x1"]), 0)]


def E13PC_slips(u, F, c, letters):
    """ref -> the texts its slip gives."""
    X = E13PC_X
    d1 = sp.diff(F, X)
    x0 = c["x0"]
    out = {}

    def add(ref, eqs):
        try:
            vals = E13PC_solve(eqs, letters)
        except Fail:
            return
        out[ref] = {E13PC_text(letters, vals)}

    if u == "k-from-gradient":
        add(E13PC_UC + "0", [sp.Eq(E13PC_at(F, x0), c["m"])])
    elif u == "two-from-gradient-and-point":
        add(E13PC_UC + "0", [sp.Eq(E13PC_at(F, x0), c["m"]), sp.Eq(E13PC_at(d1, x0), c["y0"])])
    elif u == "two-gradients":
        add(E13PC_UC + "0", [sp.Eq(E13PC_at(F, x0), c["m"]), sp.Eq(E13PC_at(F, c["x1"]), c["m1"])])
    elif u == "from-tangent":
        line = sp.Poly(c["line"], X)
        add("t5-ext-unknown-coefficients#2", [sp.Eq(E13PC_at(d1, x0), line.coeff_monomial(X)), sp.Eq(E13PC_at(F, x0), line.coeff_monomial(1))])
    elif u == "k-from-stationary-x":
        add(E13PC_SC + "0", [sp.Eq(E13PC_at(F, x0), 0)])
    elif u == "two-from-stationary-point":
        add(E13PC_SC + "2", [sp.Eq(E13PC_at(d1, c["y0"]), 0), sp.Eq(E13PC_at(F, x0), c["y0"])])
    elif u == "k-from-inflexion":
        add("t5-ext-stationary-conditions#3", [sp.Eq(E13PC_at(d1, x0), 0)])
    else:
        lead = sp.Poly(F, X).LC()
        bc = sp.Poly(sp.expand(lead * (X - x0) * (X - c["x1"])), X).all_coeffs()
        b, cc = letters
        add("t5-ext-stationary-conditions#4", [sp.Eq(sp.Poly(d1, X).coeff_monomial(X), bc[1]), sp.Eq(sp.Poly(d1, X).coeff_monomial(1), bc[2])])
        # Stationary points taken at −x0 and −x1: each factor of f′ with the wrong sign.
        add("t5-ext-stationary-conditions#8", [sp.Eq(E13PC_at(d1, -x0), 0), sp.Eq(E13PC_at(d1, -c["x1"]), 0)])
    # FAL-815: the slips that were blank options.
    true_vals = E13PC_solve([sp.Eq(e, v) for e, v in E13PC_conditions(u, F, c)], letters)
    if len(letters) == 2:
        # The right pair written against the wrong letters.
        swap = "t5-ext-unknown-coefficients#3" if u in ("two-from-gradient-and-point", "two-gradients", "from-tangent") else "t5-ext-stationary-conditions#5"
        out[swap] = {E13PC_text(letters, true_vals[::-1])}
    else:
        k = letters[0]
        if u in ("k-from-gradient", "k-from-stationary-x"):
            # The k term kxⁿ differentiated to kxⁿ⁻¹, the power not brought down.
            fk = sp.expand(F).coeff(k)
            bad = sp.diff(sp.expand(F - k * fk), X) + k * sp.cancel(fk / X)
            rhs = c["m"] if u == "k-from-gradient" else 0
            add("t5-ext-unknown-coefficients#4" if u == "k-from-gradient" else "t5-ext-stationary-conditions#6", [sp.Eq(E13PC_at(bad, x0), rhs)])
        if u in ("k-from-stationary-x", "k-from-inflexion"):
            # c·k + n = 0 solved as c·k = n: the number moved across keeps its sign.
            e = E13PC_at(sp.diff(F, X, 1 if u == "k-from-stationary-x" else 2), x0)
            n = e.subs(k, 0)
            add("t5-ext-stationary-conditions#7", [sp.Eq(e - n, n)])
    return out


def E13PC_clean(F, letters, vals, c):
    X = E13PC_X
    full = sp.Poly(sp.expand(F.subs(dict(zip(letters, vals)))), X)
    for l, v in zip(letters, vals):
        need(v.q == 1 and v != 0 and abs(v) <= E13PC_LETTER, f"{l} = {v} is not a small nonzero whole number")
    for coef in sp.Poly(F, X, *letters).coeffs():
        need(coef.is_integer and abs(coef) <= E13PC_LIMIT, f"the coefficient {coef} is not a small whole number")
    for k in ("m", "y0", "m1"):
        if k in c:
            need(abs(c[k]) <= E13PC_GIVEN, f"{k} = {c[k]} is too big to work by hand")
    need(c["x0"] != 0 and c["x0"].q == 1, "x0 is not a nonzero whole number")
    return full


def E13PC_eq_line(t, letters):
    """'27a + b = 79' as an expression that is 0."""
    m = re.fullmatch(r"(.+) = (.+)", t)
    need(m is not None, f"no equation in {t!r}")
    return sp.expand(E13PC_expr(m.group(1)) - E13PC_expr(m.group(2)))


E13PC_LIN = r"−?\d*[abckp](?: [+−] \d*[abckp])*(?: [+−] \d+)? = −?\d+(?:/\d+)?"


def E13PC_working(q, F, letters, vals, c, u):
    """Every derivative the working states is SymPy's, every equation holds for the answer, and an
    equation a condition "gives" is that condition with its number moved across."""
    X = E13PC_X
    d1, d2 = sp.expand(sp.diff(F, X)), sp.expand(sp.diff(F, X, 2))
    true_eqs = [sp.expand(e - v) for e, v in E13PC_conditions(u, F, c)]
    at = dict(zip(letters, vals))
    for sol in q["solutions"]:
        for st in sol["steps"]:
            m = re.search(r"f′\(x\) = (.+?)(?:\.$|, a quadratic)", st)
            if m:
                parts = m.group(1).split(" = ")
                need(E13PC_expr(parts[0]) == d1 or (st.startswith("So ") and E13PC_expr(parts[0]) == sp.expand(d1.subs(at))),
                     f"{sol['name']}: f′ is not {parts[0]!r}")
                for p in parts[1:]:
                    need(E13PC_expr(p) == sp.expand(d1.subs(at)), f"{sol['name']}: f′ is not {p!r}")
            m = re.search(r"f″\(x\) = (.+)\.$", st)
            if m:
                need(E13PC_expr(m.group(1)) == d2, f"{sol['name']}: f″ is not {m.group(1)!r}")
            for m in re.finditer(E13PC_LIN, st):
                need(E13PC_eq_line(m.group(0), letters).subs(at) == 0, f"{sol['name']}: {m.group(0)!r} is false for the answer")
            for m in re.finditer(rf"(?:gives |give |\d: |\d and )({E13PC_LIN})", st):
                if re.fullmatch(r"[a-z] = .+", m.group(1)):
                    continue
                e = E13PC_eq_line(m.group(1), letters)
                need(any(sp.expand(e - t) == 0 for t in true_eqs), f"{sol['name']}: {m.group(1)!r} is not one of the conditions")
            m = re.fullmatch(r"f[′″]\((−?\d+)\) = ([^:]+) = (−?\d+)\.", st)
            if m and " gives " not in st:
                e = sp.expand(E13PC_expr(m.group(2)) - E13PC_n(m.group(3)))
                need(any(sp.expand(e - t) == 0 for t in true_eqs), f"{sol['name']}: {st!r} is not the condition")
            m = re.search(r"f[′″]\((−?\d+)\) = 0: (.+) = 0\.$", st)
            if m:
                need(any(sp.expand(E13PC_expr(m.group(2)) - t) == 0 for t in true_eqs), f"{sol['name']}: {st!r} is not the condition")


def E13PC_check(q):
    u, angle = q["view"]["unknown"], q["view"]["angle"]
    F, letters, c = E13PC_read(q)
    want_letters = {"k-from-gradient": "k", "k-from-stationary-x": "k", "k-from-inflexion": "p", "two-from-two-stationary": "bc"}.get(u, "ab")
    need("".join(l.name for l in letters) == want_letters, f"the letters are {letters}")
    need(q["paper"] == (2 if angle.startswith("gdc-") else 1), f"Paper {q['paper']} for {angle}")
    conds = E13PC_conditions(u, F, c)
    vals = E13PC_solve([sp.Eq(e, v) for e, v in conds], letters)
    full = E13PC_clean(F, letters, vals, c)
    X = E13PC_X
    if u in ("k-from-stationary-x", "two-from-stationary-point", "two-from-two-stationary"):
        d = sp.diff(full.as_expr(), X)
        for x in [c["x0"]] + ([c["x1"]] if "x1" in c else []):
            need(d.subs(X, x) == 0, "not a stationary point")
    if u == "k-from-inflexion":
        d2 = sp.diff(full.as_expr(), X, 2)
        need(d2.subs(X, c["x0"]) == 0 and d2.subs(X, c["x0"] - 1) * d2.subs(X, c["x0"] + 1) < 0, "f″ doesn't change sign there")
    if u == "two-from-stationary-point":
        need(full.as_expr().subs(X, c["x0"]) == c["y0"], "the point is not on the curve")
    if u == "from-tangent":
        line = c["line"]
        need(sp.expand(full.as_expr() - line).subs(X, c["x0"]) == 0 and sp.diff(full.as_expr() - line, X).subs(X, c["x0"]) == 0, "the line is not the tangent")
    if len(letters) == 1:
        want = f"{letters[0].name} = {frac_text(vals[0])}"
    else:
        want = E13PC_text(letters, vals)
    gc_check_common(q, want, E13PC_slips(u, F, c, letters))
    E13PC_working(q, F, letters, vals, c, u)
    return None, None


def E13PC_spot(q, lines):
    """The first line of a student's working that is false for the true curve."""
    u = q["view"]["unknown"]
    F, letters, c = E13PC_read(q)
    X = E13PC_X
    conds = E13PC_conditions(u, F, c)
    vals = E13PC_solve([sp.Eq(e, v) for e, v in conds], letters)
    true_eqs = [sp.expand(e - v) for e, v in conds]
    d1 = sp.diff(F, X)
    N = E13PC_NUM
    for i, t in enumerate(lines):
        if re.fullmatch(rf"f′\(({N})\) = 0 has many solutions; take a = ({N}), so b = ({N})", t):
            ok = False  # one equation can't fix two unknowns, whatever is picked
        elif (m := re.fullmatch(r"f′\(x\) = (.+)", t)):
            ok = E13PC_expr(m.group(1)) == d1
        elif (m := re.fullmatch(rf"f′\(({N})\) = ([^g]+) = ({N})", t)):
            ok = E13PC_expr(m.group(2)) == E13PC_at(d1, E13PC_n(m.group(1))) and any(
                sp.expand(E13PC_expr(m.group(2)) - E13PC_n(m.group(3)) - e) == 0 for e in true_eqs)
        elif (m := re.fullmatch(rf"(f′?)\(({N})\) = ({N}) gives (.+)", t)):
            g = d1 if m.group(1) == "f′" else F
            want = sp.expand(E13PC_at(g, E13PC_n(m.group(2))) - E13PC_n(m.group(3)))
            ok = any(sp.expand(want - e) == 0 for e in true_eqs) and sp.expand(E13PC_eq_line(m.group(4), letters) - want) == 0
        elif (m := re.fullmatch(rf"The gradient at x = ({N}) is f′\(({N})\), so f′\(({N})\) = ({N})", t)):
            ok = len({m.group(1), m.group(2), m.group(3)}) == 1 and E13PC_n(m.group(1)) == c["x0"] and E13PC_n(m.group(4)) == c["m"]
        elif (m := re.fullmatch(rf"The point \(({N}), ({N})\) is on the curve, and f′\(({N})\) = 0", t)):
            ok = (E13PC_n(m.group(1)), E13PC_n(m.group(2))) == (c["x0"], c["y0"]) and E13PC_n(m.group(3)) == c["x0"]
        elif (m := re.fullmatch(r"So f\(x\) = (.+)", t)):
            ok = E13PC_expr(m.group(1)) == sp.expand(F.subs(dict(zip(letters, vals))))
        elif (m := re.fullmatch(rf"([a-z]) = ({N})(?:, ([a-z]) = ({N}))?", t)):
            got = {m.group(1): E13PC_n(m.group(2))}
            if m.group(3):
                got[m.group(3)] = E13PC_n(m.group(4))
            ok = got == {l.name: v for l, v in zip(letters, vals)}
        else:
            e = E13PC_eq_line(t, letters)
            ok = e.subs(dict(zip(letters, vals))) == 0
        if not ok:
            return i
    return None


SITUATION_CHECKS["polynomial-conditions"] = E13PC_check
SPOT_CHECKS["polynomial-conditions"] = E13PC_spot

# ── end polynomial-conditions ──


# ── E13 writers (FAL-776) ─────────────────────────────────────
# The checker's own copy of how the game writes a sum of terms (DifferentiationViews.SUM and
# Fmt.lead, Fmt.poly, Fmt.factor), for the E13 types' statements.

E13_SUPS = str.maketrans("0123456789-", "⁰¹²³⁴⁵⁶⁷⁸⁹⁻")


def E13_lead(v):
    v = sp.Rational(v)
    if v == 1:
        return ""
    if v == -1:
        return "−"
    if v == sp.Rational(1, 2):
        return "½"
    if v == sp.Rational(-1, 2):
        return "−½"
    if v.q == 1:
        return frac_text(v)
    return ("−" if v < 0 else "") + f"({frac_text(abs(v))})"


def E13_T(c, body):
    c = sp.Rational(c)
    if body == "" or body.startswith("/"):
        return frac_text(c) + body
    head = E13_lead(c)
    if any(body.startswith(w) for w in ("ln", "sin", "cos")) and head not in ("", "−"):
        return head + " " + body
    return head + body


def E13_sum(terms):
    out = ""
    for c, body in terms:
        c = sp.Rational(c)
        if c == 0:
            continue
        t = E13_T(abs(c), body)
        out += (("−" if c < 0 else "") if out == "" else (" − " if c < 0 else " + ")) + t
    return out or "0"


def E13_sup(p):
    p = int(p)
    return "" if p == 1 else str(p).translate(E13_SUPS)


def E13_poly(coeffs, letter="x"):
    n = len(coeffs) - 1
    return E13_sum([(c, "" if n - i == 0 else letter + E13_sup(n - i)) for i, c in enumerate(coeffs)])


def E13_factor(r):
    r = sp.Rational(r)
    return "x" if r == 0 else f"(x {'+' if r < 0 else '−'} {frac_text(abs(r))})"


def E13_expr(text, extra=()):
    """The game's way of writing an expression in x, as SymPy (e^x, e^(2x), ln x, 3/x², (x + 1)²)."""
    t = text.strip()
    t = t.replace("ln x", "log(x)")
    return sp.expand(calc_expr(t))


# ── always-increasing (t5-ext-always-increasing, FAL-776) ─────
# f is read back from its line and differentiated by SymPy. Each statement the answer could be
# is written here from the checker's own f′: the right one for the asked method, the tagged slips
# and the plain ones, and every option must be one of them. A quadratic f′ is completed and its
# discriminant found here; on Paper 2 the least value of f′ is where f″ = 0, at 40 digits.

E13AI_SK = "SL5.2.show-always-increasing#"
E13AI_X = sp.Symbol("x")
E13AI_T = "t5-ext-always-increasing#"


def E13AI_vertex(A, h, K):
    return E13_sum([(A, E13_factor(h) + "²"), (K, "")])


def E13AI_quad(q, angle, g, f):
    X = CX
    d = sp.Poly(sp.diff(f, X), X)
    need(d.degree() == 2, "f′ is not a quadratic")
    A, B, C = d.all_coeffs()
    up = g == "f"
    need((A > 0) == up and A % 3 == 0 and abs(A) in (3, 6), f"the x² coefficient of {g}′ is {A}")
    h = -B / (2 * A)
    need(h.q == 1 and h != 0 and abs(h) <= 3, f"the vertex of {g}′ is at {h}")
    K = C - B**2 / (4 * A)
    need(K.q == 1 and (K > 0) == up and 1 <= abs(K) <= 9, f"the least or greatest value of {g}′ is {K}")
    delta = B**2 - 4 * A * C
    need(delta < 0, "the discriminant is not negative")
    sign, word, end = (">", "positive", f"f′(x) > 0 for all x") if up else ("<", "negative", f"g′(x) < 0 for all x")
    ends = (lambda k: f"≥ {frac_text(k)} > 0 for all x, so f is increasing") if up else (lambda k: f"≤ {frac_text(k)} < 0 for all x, so g is decreasing")
    cs = f"{g}′(x) = {E13AI_vertex(A, h, K)} {ends(K)}"
    disc = f"{g}′(x) = {E13_poly([A, B, C])} has discriminant {frac_text(delta)} < 0 and a {word} x² coefficient, so {end}"
    strict = f"{g}′(x) = {E13AI_vertex(A, h, K)} {sign} {frac_text(K)} for all x, so {g} is {'increasing' if up else 'decreasing'}"
    k_slip = K + (1 if up else -1) * (abs(A) - 1) * h**2
    cs_slip = f"{g}′(x) = {E13AI_vertex(A, h, k_slip)} {ends(k_slip)}"
    disc_slip = f"{g}′(x) = {E13_poly([A, B, C])} has discriminant {frac_text((B / 2)**2 - 4 * A * C)} < 0 and a {word} x² coefficient, so {end}"
    pts = set()
    for o in q["choices"]:
        m = re.fullmatch(rf"{g}′\((−?\d+)\) = (−?\d+) and {g}′\((−?\d+)\) = (−?\d+) are both {word}, so {re.escape(end)}", o["text"])
        if m:
            x1, v1, x2, v2 = (E13PC_n(t) for t in m.groups())
            if x2 == x1 + 2 and v1 == d.eval(x1) and v2 == d.eval(x2):
                pts.add(o["text"])
    right = cs if angle == "complete-square" else disc
    return right, {E13AI_SK + "0": pts, E13AI_SK + "2": {strict}, E13AI_T + "5": {cs_slip}, E13AI_T + "6": {disc_slip}}, set(), (A, B, C, h, K, delta)


def E13AI_claims(terms, strict):
    (c0, b0), (c1, _), (c2, b2) = terms
    return f"{E13_T(c0, b0)} {'>' if strict else '≥'} 0, {frac_text(c1)} > 0 and {E13_T(c2, b2)} > 0"


def E13AI_E(s):
    return "e^x" if s == 1 else f"e^({s}x)"


def E13AI_check(q):
    u, angle, L = q["view"]["unknown"], q["view"]["angle"], q["lines"]
    if "A student's working:" in L:
        L = L[:L.index("A student's working:")]
    X = CX
    need(q["paper"] == (2 if u == "gdc-minimum" else 1), f"Paper {q['paper']}")
    tagged, plain = {}, set()
    if u in ("quadratic-derivative", "decreasing-quadratic"):
        g = "f" if u == "quadratic-derivative" else "g"
        m = re.fullmatch(rf"{g}\(x\) = (.+)", L[0])
        need(m is not None and len(L) == 1, f"can't read {L}")
        f = E13PC_expr(m.group(1))
        right, tagged, plain, (A, B, C, h, K, delta) = E13AI_quad(q, angle, g, f)
        for sol in q["solutions"]:
            for st in sol["steps"]:
                for part in re.findall(rf"{g}′\(x\) = ([^,.]+?)(?=\.$|, a quadratic| ≥| ≤| has)", st):
                    for side in part.split(" = "):
                        need(E13PC_expr(side) == sp.expand(A * X**2 + B * X + C), f"{sol['name']}: {side!r} is not {g}′(x)")
                mm = re.search(r"Δ = b² − 4ac = (.+) = (−?\d+)\.$", st)
                if mm:
                    need(E13PC_n(mm.group(2)) == delta and sp.sympify(mm.group(1).replace("−", "-").replace("²", "**2").replace("×", "*")) == delta, f"{sol['name']}: {st!r}")
    elif u == "sum-of-terms":
        m = re.fullmatch(r"f\(x\) = (\d*)x³ \+ (\d*)x \+ (\d*)e\^(?:x|\((\d)x\))", L[0])
        need(m is not None and len(L) == 1, f"can't read {L}")
        p, qq, r = (int(t) if t else 1 for t in m.groups()[:3])
        s = int(m.group(4) or 1)
        need(s in (2, 3) if m.group(4) else True, "e^(1x)")
        need(1 <= p <= 3 and 1 <= qq <= 9 and 1 <= r <= 4, f"f(x) = {m.group(1)}")
        f = p * X**3 + qq * X + r * sp.exp(s * X)
        d = sp.diff(f, X)
        need(sp.simplify(d - (3 * p * X**2 + qq + r * s * sp.exp(s * X))) == 0, "f′")
        t = [(3 * p, "x²"), (qq, ""), (r * s, E13AI_E(s))]
        fp = E13_sum(t)
        right = f"{E13AI_claims(t, False)}, so f′(x) = {fp} > 0 for all x"
        f1 = E13_sum([(3 * p + qq, ""), (r * s, "e" + E13_sup(s))])
        need(sp.simplify(d.subs(X, 1) - (3 * p + qq + r * s * sp.E**s)) == 0, "f′(1)")
        tagged = {E13AI_SK + "0": {f"f′(0) = {qq + r * s} and f′(1) = {f1} are both positive, so f′(x) > 0 for all x"},
                  E13AI_SK + "1": {f"{L[0][7:]} > 0 for all x, so f is increasing"},
                  E13AI_SK + "2": {f"{E13AI_claims(t, True)}, so f′(x) = {fp} > 0 for all x"}}
        st = [(3 * p, "x²"), (qq, ""), (r, E13AI_E(s))] if s > 1 else [(p, "x²"), (qq, ""), (r, E13AI_E(s))]
        tagged[E13AI_T + "9"] = {f"{E13AI_claims(st, False)}, so f′(x) = {E13_sum(st)} > 0 for all x"}
    elif u == "inverse-exists":
        m = re.fullmatch(r"f\(x\) = (\d*)x² \+ (\d*) ?ln x, for x > 0", L[0])
        need(m is not None and len(L) == 1, f"can't read {L}")
        a, b = (int(t) if t else 1 for t in m.groups())
        need(1 <= a <= 4 and 1 <= b <= 9, "a or b")
        d = sp.diff(a * X**2 + b * sp.log(X), X)
        need(sp.simplify(d - (2 * a * X + b / X)) == 0, "f′")
        fp = E13_sum([(2 * a, "x"), (b, "/x")])
        right = f"For x > 0, {E13_T(2 * a, 'x')} > 0 and {E13_T(b, '/x')} > 0, so f′(x) = {fp} > 0: f is increasing, so it is one-to-one and has an inverse"
        tagged = {E13AI_SK + "0": {f"f′(1) = {frac_text(d.subs(X, 1))} and f′(2) = {frac_text(d.subs(X, 2))} are both positive, so f is increasing and has an inverse"},
                  E13AI_SK + "1": {f"{E13_T(a, 'x²')} > 0 and {E13_T(b, 'ln x')} > 0 for x > 0, so f(x) > 0 and f has an inverse"}}
        tagged[E13AI_T + "9"] = {f"For x > 0, {E13_T(2 * a, 'x')} > 0 and {E13_T(b, '/x²')} > 0, so f′(x) = {E13_sum([(2 * a, 'x'), (b, '/x²')])} > 0: f is increasing, so it is one-to-one and has an inverse"}
    else:
        m = re.fullmatch(r"f\(x\) = (\d*)e\^x − (\d*)x²(?: ([+−]) (\d*)x)?", L[0])
        need(m is not None and len(L) == (2 if q["view"]["rep"] == "graph" else 1), f"can't read {L}")
        A = int(m.group(1) or 1)
        B = int(m.group(2) or 1)
        n = (int(m.group(4) or 1) * (-1 if m.group(3) == "−" else 1)) if m.group(3) else 0
        f = A * sp.exp(X) - B * X**2 + n * X
        d = sp.diff(f, X)
        xs = sp.solve(sp.diff(d, X), X)
        need(len(xs) == 1, "f′ has no single least value")
        xm = xs[0]
        need(sp.diff(d, X, 2).subs(X, xm) > 0, "not a minimum")
        v = sp.N(d.subs(X, xm), 40)
        need(v > sp.Rational(1, 10) and not on_edge(v) and not on_edge(abs(sp.N(xm, 40))), f"least value {v}")
        right = f"The GDC shows the least value of f′(x) is {gc_s(v)}, at x = {gc_s(sp.N(xm, 40))}, so f′(x) > 0 for all x"
        f1 = sp.N(d.subs(X, 1), 40)
        need(f1 > 0 and d.subs(X, 0) > 0, "a tested value is not positive")
        tagged = {E13AI_SK + "0": {f"f′(0) = {d.subs(X, 0)} and f′(1) = {gc_s(f1)} are both positive, so f′(x) > 0 for all x"}}
        tagged[E13AI_T + "7"] = {f"The GDC shows the least value of f′(x) is {d.subs(X, 0)}, at x = 0, so f′(x) > 0 for all x"}
        tagged[E13AI_T + "8"] = {f"The GDC shows f′(x) = 0 at x = {gc_s(sp.N(xm, 40))}, so f has a stationary point there"}
        if q["view"]["rep"] == "graph":
            dl = sp.lambdify(X, d, "math")
            for x, y in q["graph"]["curves"][0][::11]:
                need(abs(dl(x) - y) < 1e-6, "the graph is not y = f′(x)")
    gc_check_common(q, right, tagged)
    for o in q["choices"]:
        if not o["correct"] and not o["ref"]:
            need(o["text"] in plain, f"the checker can't say why {o['text']!r} is wrong")
    return None, None


def E13AI_claim_true(t, domain_pos):
    """Whether 'T ≥ 0' or 'T > 0' holds for every x (every x > 0 with domain_pos)."""
    X = CX
    m = re.fullmatch(r"(.+) (≥|>) 0", t)
    need(m is not None, f"no claim in {t!r}")
    e = E13_expr(m.group(1))
    dom = sp.Interval.open(0, sp.oo) if domain_pos else sp.S.Reals
    bad = sp.solve_univariate_inequality(e < 0 if m.group(2) == "≥" else e <= 0, X, relational=False, domain=dom)
    return bad == sp.S.EmptySet


def E13AI_spot(q, lines):
    u, L = q["view"]["unknown"], q["lines"]
    L = L[:L.index("A student's working:")]
    X = CX
    if u in ("quadratic-derivative", "decreasing-quadratic"):
        g = "f" if u == "quadratic-derivative" else "g"
        d = sp.diff(E13PC_expr(re.fullmatch(rf"{g}\(x\) = (.+)", L[0]).group(1)), X)
        A, B, C = sp.Poly(d, X).all_coeffs()
        top = C - B**2 / (4 * A)
        for i, t in enumerate(lines):
            t = re.sub(rf"^{g}′\(x\) ", "", t)
            m = re.fullmatch(r"(?:= (.+?) )?(≥|≤) (−?\d+) (>|<) 0, so .+", t)
            if m:
                ok = (m.group(1) is None or E13PC_expr(m.group(1)) == sp.expand(d)) and E13PC_n(m.group(3)) == top
            else:
                ok = E13PC_expr(t.removeprefix("= ")) == sp.expand(d)
            if not ok:
                return i
        return None
    if u == "sum-of-terms":
        f = E13_expr(L[0][len("f(x) = "):])
        dom = False
    else:
        f = E13_expr(re.fullmatch(r"f\(x\) = (.+), for x > 0", L[0]).group(1))
        dom = True
    d = sp.diff(f, X)
    for i, t in enumerate(lines):
        if (m := re.fullmatch(r"f′\(x\) = (.+)", t)):
            ok = sp.simplify(E13_expr(m.group(1)) - d) == 0
        elif (m := re.fullmatch(r"f\(x\) = (.+?)(?: is defined for x > 0)?", t)):
            ok = sp.simplify(E13_expr(m.group(1)) - f) == 0
        elif t in ("So f′(x) > 0 for all x", "So f is increasing for all x"):
            ok = not dom  # the conclusions of a sum of terms that really are positive
        elif t in ("So f′(x) > 0 for x > 0", "So f is one-to-one and has an inverse"):
            ok = dom
        else:
            body = t.removeprefix("For x > 0, ")
            parts = re.split(r", | and ", body)
            ok = all(E13AI_claim_true(p, dom) for p in parts)
        if not ok:
            return i
    return None


SITUATION_CHECKS["always-increasing"] = E13AI_check
SPOT_CHECKS["always-increasing"] = E13AI_spot

# ── end always-increasing ──


# ── hence-integral (t5-ext-hence-integral, FAL-776) ───────────
# Every option is read back as an expression and judged by SymPy, not compared with the
# engine's wording: the given derivative result is differentiated again, the right option must
# differentiate to the integrand (with + C) or equal the exact integral, every other option must
# not, and each tagged option must be its slip worked out here: a multiple of the derivative
# result itself, a multiple of F with the extra term left in, the antiderivative without + C, or
# F times the factor that should have been divided out.

E13HI_SK = "SL5.10.hence-from-derivative#"
E13HI_X = sp.Symbol("x")


def E13HI_e(t):
    return sp.expand(calc_expr(t.removesuffix(" + C")).subs(sp.Symbol("e"), sp.E))


def E13HI_same(a, b):
    return sp.simplify(sp.expand_log(sp.expand(a - b), force=True)) == 0


def E13HI_const(a, b):
    """a/b when it is a nonzero rational number, else None."""
    if b == 0:
        return None
    r = sp.simplify(a / b)
    return r if r.is_Rational and r != 0 else None


def E13HI_coeff(t):
    """The number written in front of an expression: 9 in '9x(x² + 2)³', 1 in 'ln x + 1'."""
    m = re.match(r"(\d+) ?(?=[a-z(])", t)
    return sp.Integer(m.group(1)) if m and not re.match(r"\d+ ?[+−]", t) else sp.Integer(1)


def E13HI_result(line):
    m = re.fullmatch(r"d/dx \((.+)\) = (.+)", line)
    need(m is not None, f"can't read the result {line!r}")
    F, G = E13HI_e(m.group(1)), E13HI_e(m.group(2))
    need(E13HI_same(sp.diff(F, E13HI_X), G), f"the result {line!r} is false")
    return F, G


def E13HI_standard(term):
    X = E13HI_X
    fs = sp.Mul.make_args(term)
    trans = any(f.has(sp.exp, sp.sin, sp.cos, sp.log) for f in fs)
    xpow = any(f == X or (f.is_Pow and f.base == X and f.exp > 0) for f in fs)
    return not (trans and xpow)


def E13HI_helps(G, g):
    for t in sp.Add.make_args(sp.expand(G)):
        if E13HI_const(t, g) is not None:
            return all(E13HI_standard(r) for r in sp.Add.make_args(sp.expand(G - t)) if r != 0)
    return False


def E13HI_check(q):
    u, L, asked, ch = q["view"]["unknown"], q["lines"], q["asked"], q["choices"]
    if "A student's working:" in L:
        L = L[:L.index("A student's working:")]
    X = E13HI_X
    need(q["paper"] == 1, "a hence question has no calculator")
    wr = defaultdict(set)
    if u == "find-derivative":
        m = re.fullmatch(r"Find d/dx \((.+)\)\.", asked)
        need(m is not None, f"asked {asked!r}")
        F = E13HI_e(m.group(1))
        v = sp.simplify(F / X)
        d = sp.diff(F, X)
        right = lambda e, o: E13HI_same(e, d)
        slips = {"SL5.6.product-rule#0": [sp.diff(v, X)], "SL5.6.product-rule#1": [v, X * sp.diff(v, X)]}
        for o in ch:
            if o["ref"]:
                need(any(E13HI_same(E13HI_e(o["text"]), s) for s in slips.get(o["ref"], [])), f"{o['text']!r} is not what {o['ref']} gives")
                wr[o["ref"]].add(o["text"])
    elif u == "pick-the-derivative":
        m = re.fullmatch(r"Which derivative result helps to find ∫ (.+) dx\?", asked)
        need(m is not None, f"asked {asked!r}")
        g = E13HI_e(m.group(1))
        helps = []
        for o in ch:
            F, G = E13HI_result(o["text"])
            if E13HI_helps(G, g):
                helps.append(o["text"])
            if o["ref"]:
                need(o["ref"] == "t5-ext-hence-integral#10" and E13HI_same(F, g), f"{o['text']!r} is not what {o['ref']} gives")
                wr[o["ref"]].add(o["text"])
        need(len(helps) == 1, f"{len(helps)} results help: {helps}")
        right = lambda e, o: o == helps[0]
    else:
        F, G = E13HI_result(L[0])
        if u == "hence-definite":
            m = re.fullmatch(r"Hence find the exact value of ∫ from (\d+) to (\d+) of (.+) dx\.", asked)
            need(m is not None, f"asked {asked!r}")
            a, b, g = int(m.group(1)), int(m.group(2)), E13HI_e(m.group(3))
            V = sp.integrate(g, (X, a, b))
            r = E13HI_coeff(m.group(3)) / E13HI_coeff(L[0].split(" = ", 1)[1])
            right = lambda e, o: E13HI_same(e, V)
            slips = {E13HI_SK + "0": r * (G.subs(X, b) - G.subs(X, a)), E13HI_SK + "1": r * (F.subs(X, b) - F.subs(X, a)),
                     "t5-ext-hence-integral#5": E13HI_coeff(m.group(3)) * (F.subs(X, b) - F.subs(X, a))}
            # #8: the integrand's antiderivative (no constant) at the upper limit only.
            Ag = sp.integrate(g, X)
            slips["t5-ext-hence-integral#8"] = Ag.subs(X, b)
            # #9: the moved term keeps its sign: r(2F − A) for A = ∫ g/r dx.
            K = 2 * F - sp.integrate(g / r, X)
            slips["t5-ext-hence-integral#9"] = r * (K.subs(X, b) - K.subs(X, a))
            for o in ch:
                if o["ref"]:
                    need(E13HI_same(E13HI_e(o["text"]), slips[o["ref"]]), f"{o['text']!r} is not what {o['ref']} gives")
                    wr[o["ref"]].add(o["text"])
        else:
            m = re.fullmatch(r"Hence find ∫ (.+) dx\.", asked)
            need(m is not None, f"asked {asked!r}")
            g = E13HI_e(m.group(1))
            right = lambda e, o: o.endswith(" + C") and E13HI_same(sp.diff(e, X), g)
            for o in ch:
                ref, e, c = o["ref"], E13HI_e(o["text"]), o["text"].endswith(" + C")
                if not ref:
                    continue
                if ref == E13HI_SK + "0":
                    ok = c and E13HI_const(e, G) is not None
                elif ref == E13HI_SK + "1":
                    ok = c and E13HI_const(e, F) is not None and not E13HI_same(sp.diff(e, X), g)
                elif ref == E13HI_SK + "2":
                    ok = not c and E13HI_same(sp.diff(e, X), g)
                elif ref == "t5-ext-hence-integral#5":
                    ok = c and E13HI_same(e, E13HI_coeff(m.group(1)) * F)
                else:
                    ok = False
                need(ok, f"{o['text']!r} is not what {ref} gives")
                wr[ref].add(o["text"])
            if u == "adjust-factor":
                need(E13HI_const(g, G) is not None, "the integrand is not a multiple of the result")
            else:
                need(E13HI_const(g, G) is None and E13HI_helps(G, g), "the integrand is not a term of the result")
    rights = [o["text"] for o in ch if right(E13HI_e(o["text"]) if u != "pick-the-derivative" else None, o["text"])]
    need(len(rights) == 1, f"{len(rights)} options are right: {rights}")
    gc_check_common(q, rights[0], wr)
    return None, None


def E13HI_spot(q, lines):
    X = E13HI_X
    for i, t in enumerate(lines):
        if (m := re.fullmatch(r"(?:Check: )?d/dx \((.+)\) = (.+)", t)):
            ok = E13HI_same(sp.diff(E13HI_e(m.group(1)), X), E13HI_e(m.group(2)))
        elif (m := re.fullmatch(r"(?:So )?∫ (.+) dx = (.+) \+ C", t)):
            ok = E13HI_same(sp.diff(E13HI_e(m.group(2)), X), E13HI_e(m.group(1)))
        elif (m := re.fullmatch(r"(.+) is (\d+(?:/\d+)?) times (.+)", t)):
            ok = E13HI_same(E13HI_e(m.group(1)), sp.Rational(m.group(2)) * E13HI_e(m.group(3)))
        else:
            raise Fail(f"can't judge the line {t!r}")
        if not ok:
            return i
    return None


SITUATION_CHECKS["hence-integral"] = E13HI_check
SPOT_CHECKS["hence-integral"] = E13HI_spot

# ── end hence-integral ──


# ── integral-gdc (t5-ext-integral-gdc, FAL-776) ───────────────
# The integrand and limits are read back from the lines, integrated by mpmath at 30 digits, and
# each slip is made here from the integrand's own shape: limits swapped (the negative), degree
# mode (every sin argument times π/180) and a bracket closed before the constant (h(inner) becomes
# h(inner − c) + c). A GDC entry is read with the checker's calc_expr and compared with SymPy.

E13IG_SK = "SL5.5.definite-integral-gdc#"
E13IG_X = sp.Symbol("x")


def E13IG_read(q):
    L, asked = q["lines"], q["asked"]
    if "A student's working:" in L:
        L = L[:L.index("A student's working:")]
    m = re.fullmatch(r"The graph of y = (.+) is shown, with the region from x = (−?\d+) to x = (−?\d+) shaded\.", L[0])
    if m:
        t, a, b = m.groups()
        need(asked == f"Find ∫ from {a} to {b} of {IntegrationViews_wrapped(t)} dx, to 3 s.f.", f"asked {asked!r}")
    else:
        m = re.fullmatch(r"∫ from (−?\d+) to (−?\d+) of (.+) dx", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        a, b, t = m.groups()
    t = t[1:-1] if t.startswith("(") and t.endswith(")") and E13IG_balanced(t[1:-1]) else t
    return E13IG_e(t), E13PC_n(a), E13PC_n(b), t


def E13IG_e(t):
    """An expression as written, not expanded (e^(x + 4) stays one exponential)."""
    return calc_expr(t).subs(sp.Symbol("e"), sp.E)


def E13IG_same(e1, e2, a, b):
    """Whether two integrands agree on [a, b], at nine points (they are simple functions of x)."""
    f1, f2 = sp.lambdify(E13IG_X, e1, "mpmath"), sp.lambdify(E13IG_X, e2, "mpmath")
    for k in range(9):
        x = mpmath.mpf(a) + (mpmath.mpf(b) - mpmath.mpf(a)) * (k + 0.5) / 9
        if abs(f1(x) - f2(x)) > mpmath.mpf(10) ** -15 * max(1, abs(f1(x))):
            return False
    return True


def E13IG_balanced(t):
    d = 0
    for ch in t:
        d += 1 if ch == "(" else -1 if ch == ")" else 0
        if d < 0:
            return False
    return d == 0


def IntegrationViews_wrapped(t):
    """The game's brackets round a sum (IntegrationViews.wrapped), the checker's own copy."""
    d = 0
    for i, ch in enumerate(t):
        d += 1 if ch == "(" else -1 if ch == ")" else 0
        if d == 0 and i > 0 and ch in "+−":
            return f"({t})"
    return t


def E13IG_val(f, a, b):
    g = sp.lambdify(E13IG_X, f, "mpmath")
    with mpmath.workdps(30):
        return sp.Float(mpmath.quad(g, [a, b]), 30)


def E13IG_slip(f):
    """The integrand with its bracket closed before the constant, or None."""
    X = E13IG_X
    if f.func in (sp.exp, sp.log) and f.args[0].is_Add:
        inner = f.args[0]
    elif f.is_Pow and f.base.is_Add:
        inner = f.base
    else:
        return None
    c = inner.as_coeff_Add()[0]
    if c == 0:
        return None
    rest = inner - c
    if f.is_Pow:
        return sp.powdenest(rest**f.exp, force=True) + c
    return f.func(rest) + c


def E13IG_deg(f):
    return f.replace(sp.sin, lambda a: sp.sin(a * sp.pi / 180)).replace(sp.cos, lambda a: sp.cos(a * sp.pi / 180))


def E13IG_entry(t):
    return E13IG_e(t)


def E13IG_trig(f):
    return f.has(sp.sin, sp.cos)


def E13IG_check(q):
    u, ch = q["view"]["unknown"], q["choices"]
    need(q["paper"] == 2, "a GDC integral is Paper 2")
    f, a, b, ftext = E13IG_read(q)
    need(a < b and abs(b - a) <= 3, f"limits {a}, {b}")
    v = E13IG_val(f, a, b)
    need(not on_edge(abs(v)) and abs(v - sp.floor(v + sp.Rational(1, 2))) > sp.Rational(2, 100), f"{v} is not fair to 3 s.f.")
    wr = {E13IG_SK + "1": {gc_s(-v)}}
    if u == "polynomial-check":
        f = sp.expand(f)
        need(f.is_polynomial(E13IG_X), "not a polynomial")
        V = sp.integrate(f, (E13IG_X, a, b))
        need(sp.N(V - v, 20) == 0 or abs(sp.N(V - v, 20)) < 1e-20, "the GDC value is not the exact one")
        X = E13IG_X
        Fb, Fa = sp.integrate(f, (X, 0, b)), sp.integrate(f, (X, 0, a))
        wr["t5-ext-integral-gdc#5"] = {gc_s(Fb)}  # F(b) alone
        wr["t5-ext-integral-gdc#6"] = {gc_s(Fb + Fa)}  # F(b) + F(a)
        wr["t5-ext-integral-gdc#7"] = {gc_s(f.subs(X, b) - f.subs(X, a))}  # f(b) − f(a)
        for sol in q["solutions"]:
            for st in sol["steps"]:
                mm = re.fullmatch(r"F\(−?\d+\) − F\(−?\d+\) = .+ = (.+)\.", st)
                if mm:
                    need(E13PC_n(mm.group(1)) == V, f"{sol['name']}: {st!r}")
                mm = re.fullmatch(r"F\(x\) = (.+)\.", st)
                if mm:
                    need(sp.expand(sp.diff(E13HI_e(mm.group(1)), E13IG_X) - f) == 0, f"{sol['name']}: F is not an antiderivative")
    elif u == "gdc-value":
        if E13IG_trig(f):
            wr[E13IG_SK + "0"] = {gc_s(E13IG_val(E13IG_deg(f), a, b))}
        else:
            s = E13IG_slip(f)
            need(s is not None, f"{ftext} has no bracket to slip")
            wr[E13IG_SK + "2"] = {gc_s(E13IG_val(s, a, b))}
        if q["view"]["rep"] == "graph":
            fl = sp.lambdify(E13IG_X, f, "math")
            for x, y in q["graph"]["curves"][0][::9]:
                need(abs(fl(x) - y) < 1e-6, "the graph is not y = f(x)")
            sh = q["graph"]["shade"][0]
            need(abs(sh[0][0] - float(a)) < 1e-9 and abs(sh[-1][0] - float(b)) < 1e-9, "the shaded region is not from a to b")
    if u in ("gdc-value", "polynomial-check"):
        for sol in q["solutions"]:
            for st in sol["steps"]:
                mm = re.search(r"gives (−?[\d.]+)\.$", st)
                if mm:
                    need(abs(float(mm.group(1).replace("−", "-")) - float(v)) < 1e-5 * max(1, abs(float(v))), f"{sol['name']}: the GDC does not give {mm.group(1)}")
                mm = re.match(r"(?:Enter|Graph y = )(?:f\(x\) = )?(\S+)", st)
                if mm and "template" in st or st.startswith("Graph y = "):
                    e = re.match(r"(?:Enter (?:f\(x\) = )?|Graph y = )(.+?)(?: in the GDC| on the GDC)", st).group(1)
                    need(E13IG_same(E13IG_entry(e), f, a, b), f"{sol['name']}: the entry {e!r} is not the integrand")
        gc_check_common(q, gc_s(v), wr, gc_s2(v))
        return None, None
    # which-entry
    rx = r"Function (.+), lower limit (−?\d+), upper limit (−?\d+)(, radian mode|, degree mode)?"
    trig = E13IG_trig(f)
    rights, wr = [], defaultdict(set)
    for o in ch:
        m = re.fullmatch(rx, o["text"])
        need(m is not None, f"can't read the entry {o['text']!r}")
        e, lo, hi, mode = E13IG_entry(m.group(1)), E13PC_n(m.group(2)), E13PC_n(m.group(3)), m.group(4)
        same = E13IG_same(e, f, a, b)
        good_mode = (mode == ", radian mode") if trig else mode is None
        if same and (lo, hi) == (a, b) and good_mode:
            rights.append(o["text"])
        if o["ref"] == E13IG_SK + "1":
            need(same and (lo, hi) == (b, a) and good_mode, f"{o['text']!r} does not swap the limits")
        elif o["ref"] == E13IG_SK + "0":
            need(trig and same and (lo, hi) == (a, b) and mode == ", degree mode", f"{o['text']!r} is not degree mode")
        elif o["ref"] == E13IG_SK + "2":
            s = E13IG_slip(f)
            need(s is not None and E13IG_same(e, s, a, b) and (lo, hi) == (a, b), f"{o['text']!r} is not the bracket slip")
        if o["ref"]:
            wr[o["ref"]].add(o["text"])
    need(len(rights) == 1, f"{len(rights)} right entries")
    gc_check_common(q, rights[0], wr)
    return None, None


def E13IG_spot(q, lines):
    f, a, b, ftext = E13IG_read(q)
    v = E13IG_val(f, a, b)
    for i, t in enumerate(lines):
        if (m := re.fullmatch(r"The integral is ∫ from (−?\d+) to (−?\d+) of (.+) dx", t)):
            ok = (E13PC_n(m.group(1)), E13PC_n(m.group(2))) == (a, b) and E13IG_same(E13IG_e(m.group(3).strip("()") if E13IG_balanced(m.group(3)[1:-1]) else m.group(3)), f, a, b)
        elif t in ("Mode: degrees", "Mode: radians"):
            ok = t == "Mode: radians" or not E13IG_trig(f)
        elif (m := re.fullmatch(r"Entered: (.+)", t)):
            ok = E13IG_same(E13IG_entry(m.group(1)), f, a, b)
        elif (m := re.fullmatch(r"Limits: lower (−?\d+), upper (−?\d+)", t)):
            ok = (E13PC_n(m.group(1)), E13PC_n(m.group(2))) == (a, b)
        elif (m := re.fullmatch(r"The GDC gives (\S+), so the integral is (\S+)", t)):
            ok = m.group(1) == m.group(2) == gc_s(v)
        else:
            raise Fail(f"can't judge the line {t!r}")
        if not ok:
            return i
    return None


SITUATION_CHECKS["integral-gdc"] = E13IG_check
SPOT_CHECKS["integral-gdc"] = E13IG_spot

# ── end integral-gdc ──


# ── area-under-curve (t5-ext-area-under-curve, FAL-776) ───────
# f and R's edges are read back from what the student sees: the shaded strips of the figure, or
# the lines, axes and roots the words name (solved here with SymPy). The area is integrated again
# exactly, or by mpmath for the Paper 2 curve, and f is checked to be positive inside R. Each
# integral option is read back (limits and integrand) and judged; each tagged slip is worked out:
# y-values as limits, the limits swapped, f′ as the integrand, F(lower) − F(upper), a lower limit
# of 0 and roots rounded to 1 d.p.

E13AU_SE, E13AU_SP = "SL5.5.area-expression#", "SL5.5.area-positive#"
E13AU_X = sp.Symbol("x")


def E13AU_f(t):
    return E13IG_e(t)


def E13AU_round1(x):
    """x to 1 d.p., halves away from zero, as the engine's snappedf rounds."""
    x = sp.Float(x, 30)
    s = 1 if x >= 0 else -1
    return s * sp.floor(abs(x) * 10 + sp.Rational(1, 2)) / 10


def E13AU_positive(f, lo, hi):
    X = E13AU_X
    g = sp.lambdify(X, f, "mpmath")
    for k in range(1, 40):
        a, b = mpmath.mpf(str(sp.N(lo, 40))), mpmath.mpf(str(sp.N(hi, 40)))
        x = a + (b - a) * k / 40
        need(g(x) > 0, f"f is not above the x-axis at x = {x}")


def E13AU_roots(f):
    rs = sorted(sp.real_roots(sp.Poly(sp.expand(f), E13AU_X)), key=float)
    need(len(rs) == 2 and rs[0] != rs[1], f"f has roots {rs}")
    return rs


def E13AU_edges_from_graph(q, f):
    g = q["graph"]
    sh = g["shade"]
    need(len(sh) == 1, "R is not one shaded region")
    lo, hi = sh[0][0][0], sh[0][-1][0]
    fl = sp.lambdify(E13AU_X, f, "math")
    for x, y0, y1 in sh[0][::7]:
        need(abs(y0) < 1e-9 and abs(y1 - fl(x)) < 1e-6, "the shading is not between the curve and the x-axis")
    for x, y in g["curves"][0][::13]:
        need(abs(fl(x) - y) < 1e-6, "the curve drawn is not y = f(x)")
    return sp.Rational(round(lo * 1000), 1000), sp.Rational(round(hi * 1000), 1000)


def E13AU_read(q):
    """f, the edges of R, and how R was described."""
    u, rep, L = q["view"]["unknown"], q["view"]["rep"], q["lines"]
    X = E13AU_X
    if rep == "graph":
        m = re.fullmatch(r"The graph of (?:the line )?y = (.+) is shown\. R(?:, between the curve and the x-axis,)? is shaded\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        f = E13AU_f(m.group(1))
        lo, hi = E13AU_edges_from_graph(q, f)
        if "between the curve and the x-axis" in L[0]:
            rs = E13AU_roots(f)
            need((lo, hi) == (rs[0], rs[1]), "the shading is not between the roots")
        return f, lo, hi, "graph"
    if rep == "equation":
        m = re.fullmatch(r"∫ from (−?\d+) to (−?\d+) of (.+) dx", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        t = m.group(3)
        t = t[1:-1] if t.startswith("(") and E13IG_balanced(t[1:-1]) else t
        return E13AU_f(t), E13PC_n(m.group(1)), E13PC_n(m.group(2)), "integral"
    m = re.fullmatch(r"f\(x\) = (.+)", L[0])
    need(m is not None and len(L) == 2, f"can't read {L}")
    f = E13AU_f(m.group(1))
    b = L[1]
    if (m := re.fullmatch(r"R is the region enclosed by the (?:curve|line) y = f\(x\), the x-axis and the lines x = (−?\d+) and x = (−?\d+)\.", b)):
        return f, E13PC_n(m.group(1)), E13PC_n(m.group(2)), "lines"
    if b == "R is the region enclosed by the curve y = f(x) and the x-axis.":
        rs = E13AU_roots(f)
        return f, rs[0], rs[1], "roots"
    if b == "R is the region bounded by the curve y = f(x), the x-axis and the y-axis, where x ≥ 0.":
        rs = E13AU_roots(f)
        need(rs[0] < 0 < rs[1], "the roots are not either side of the y-axis")
        return f, sp.Integer(0), rs[1], "y-axis"
    raise Fail(f"can't read {b!r}")


def E13AU_val(f, lo, hi):
    X = E13AU_X
    if sp.expand(f).is_polynomial(X):
        return sp.integrate(sp.expand(f), (X, lo, hi))
    return E13IG_val(f, lo, hi)


def E13AU_integral(t):
    m = re.fullmatch(r"∫ from (\S+) to (\S+) of (.+) dx", t)
    need(m is not None, f"can't read the integral {t!r}")
    g = m.group(3)
    g = g[1:-1] if g.startswith("(") and E13IG_balanced(g[1:-1]) else g
    return m.group(1), m.group(2), E13AU_f(g)


def E13AU_check(q):
    u, angle, ch = q["view"]["unknown"], q["view"]["angle"], q["choices"]
    X = E13AU_X
    gdc = angle.startswith("gdc-") or u == "area-gdc-limits"
    need(q["paper"] == (2 if gdc else 1), f"Paper {q['paper']}")
    wr = defaultdict(set)
    if u == "region-for-integral":
        f, p, qq, _ = E13AU_read(q)
        rs = E13AU_roots(f)
        need(rs[0] < 0 < p < qq < rs[1], "the limits are not inside the hump, right of the y-axis")
        mk = {"from-zero": (0, qq), "to-root": (p, rs[1]), "left-part": (rs[0], p)}
        fl = sp.lambdify(X, f, "math")
        for o, gr in zip(ch, q["graphs"]):
            sh = gr["shade"][0]
            got = (sp.Rational(round(sh[0][0] * 1000), 1000), sp.Rational(round(sh[-1][0] * 1000), 1000))
            for x, y in gr["curves"][0][::13]:
                need(abs(fl(x) - y) < 1e-6, "a card's curve is not y = f(x)")
            want = (p, qq) if o["correct"] else mk.get(o["mistake"])
            need(want is not None and got == tuple(sp.Rational(w) for w in want), f"the {o.get('mistake') or 'right'} card shades {got}")
        gc_check_common(q, next(o["text"] for o in ch if o["correct"]), {})
        return None, None
    f, lo, hi, how = E13AU_read(q)
    E13AU_positive(f, lo, hi)
    if u in ("integral-from-graph", "integral-from-roots"):
        d = sp.diff(f, X)
        if gdc:
            rs = E13AU_roots(f)
            need(not all(r.is_Rational for r in rs), "the roots need no GDC")
            show = lambda v: gc_s(sp.N(v, 30))
        else:
            need(lo.q == 1 and hi.q == 1, "the edges are not whole numbers")
            show = lambda v: frac_text(v)
        rights = []
        for o in ch:
            a, b, g = E13AU_integral(o["text"])
            same = sp.simplify(g - f) == 0
            if same and (a, b) == (show(lo), show(hi)):
                rights.append(o["text"])
            if o["ref"] == E13AU_SE + "0":
                need(same and (a, b) == (show(f.subs(X, lo)), show(f.subs(X, hi))), f"{o['text']!r} does not use the y-values")
            elif o["ref"] == E13AU_SE + "1":
                need(same and (a, b) == (show(hi), show(lo)), f"{o['text']!r} does not swap the limits")
            elif o["ref"] == E13AU_SE + "2":
                need(sp.simplify(g - d) == 0 and (a, b) == (show(lo), show(hi)), f"{o['text']!r} does not integrate f′")
            elif o["ref"] == E13AU_SP + "1":
                need(u == "integral-from-roots" and same and hi > 0 and (a, b) == (show(0), show(hi)), f"{o['text']!r} does not start at zero")
            elif o["ref"]:
                raise Fail(f"the checker can't confirm {o['ref']} on {u}")
            if o["ref"]:
                wr[o["ref"]].add(o["text"])
        need(len(rights) == 1, f"{len(rights)} right integrals")
        gc_check_common(q, rights[0], wr)
        return None, None
    A = E13AU_val(f, lo, hi)
    show = (lambda v: gc_s(sp.N(v, 30))) if gdc else (lambda v: frac_text(v))
    if not gdc:
        need(A.is_Rational, "a Paper 1 area is not exact")
    else:
        need(not on_edge(sp.N(A, 30)) and abs(sp.N(A, 30) - round(float(A))) > 0.02, "the area is not fair to 3 s.f.")
    wr[E13AU_SP + "0"] = {show(-A)}
    if u == "area-between-roots":
        wr[E13AU_SP + "1"] = {show(E13AU_val(f, 0, hi))}
    if u == "area-gdc-limits":
        rs = E13AU_roots(f)
        wr[E13AU_SP + "2"] = {show(E13AU_val(f, E13AU_round1(sp.N(rs[0], 30)), E13AU_round1(sp.N(rs[1], 30))))}
        need(rs[0] < 0 < rs[1], "the roots are not either side of the y-axis")
        wr[E13AU_SP + "1"] = {show(E13AU_val(f, 0, hi))}
    T = "t5-ext-area-under-curve#"
    if u in ("area-between-lines", "area-straight-edge") and lo > 0:
        wr[T + "6"] = {show(E13AU_val(f, 0, hi))}
    if u == "area-between-lines" and f.is_polynomial(X):
        wr[T + "7"] = {show(f.subs(X, hi) - f.subs(X, lo))}
    if u == "area-with-y-axis":
        wr[T + "8"] = {show(E13AU_val(f, E13AU_roots(f)[0], hi))}
    if u == "area-straight-edge":
        need(sp.degree(f, X) == 1, "R's top is not a line")
        wr[T + "9"] = {show(f.subs(X, hi) * (hi - lo))}
        wr[T + "10"] = {show((f.subs(X, lo) + f.subs(X, hi)) * (hi - lo))}
    for sol in q["solutions"]:
        for st in sol["steps"]:
            if (m := re.fullmatch(r"F\(x\) = (.+)\.", st)):
                need(sp.expand(sp.diff(E13AU_f(m.group(1)), X) - sp.expand(f)) == 0, f"{sol['name']}: F is not an antiderivative")
            if (m := re.fullmatch(r"F\((−?\d+)\) − F\((−?\d+)\) = .+ = (.+)\.", st)):
                need((E13PC_n(m.group(1)), E13PC_n(m.group(2))) == (hi, lo) and E13PC_n(m.group(3)) == A, f"{sol['name']}: {st!r}")
            if (m := re.fullmatch(r"Area = ½ × \((−?\d+) \+ (−?\d+)\) × (\d+) = (.+)\.", st)):
                need(E13PC_n(m.group(1)) == f.subs(X, lo) and E13PC_n(m.group(2)) == f.subs(X, hi) and E13PC_n(m.group(3)) == hi - lo and E13PC_n(m.group(4)) == A, f"{sol['name']}: {st!r}")
            if (m := re.search(r"gives (−?[\d.]+)\.$", st)):
                need(abs(float(m.group(1).replace("−", "-")) - float(A)) < 1e-5 * max(1, abs(float(A))), f"{sol['name']}: the GDC does not give {m.group(1)}")
    gc_check_common(q, show(A), wr, gc_s2(sp.N(A, 30)) if gdc else None)
    return None, None


SITUATION_CHECKS["area-under-curve"] = E13AU_check

# ── end area-under-curve ──


# ── mutually-exclusive (FAL-777) ─────────────────────────────
# t4-ext-mutually-exclusive. Each pair of events is decided again from what the question shows:
# the probabilities, the Venn counts, or the outcomes of the die, spinner or cards read back from
# the words. The checker's own copy of the clean limits: probabilities are multiples of 0.05.

E14ME_SK = "SL4.6.mutually-exclusive#"
E14ME_T = "t4-ext-mutually-exclusive#"
E14ME_DEVICES = {"A fair six-sided die is rolled once.": (6, "roll"), "A fair spinner numbered 1 to 8 is spun once.": (8, "spin"),
                 "One card is drawn at random from ten cards numbered 1 to 10.": (10, "card"),
                 "One card is drawn at random from twelve cards numbered 1 to 12.": (12, "card")}


def E14ME_dec(text):
    need(re.fullmatch(r"0\.\d+", text) is not None, f"{text!r} is not a probability in decimals")
    v = sp.Rational(text)
    need((v * 20).q == 1 and 0 < v < 1, f"{text} is not a multiple of 0.05 between 0 and 1")
    return v


def E14ME_frac(text):
    return sp.Rational(text)


def E14ME_event(text, n):
    """The outcomes 1..n in an event, from its words."""
    xs = range(1, n + 1)
    if (m := re.fullmatch(r"an? (\d+)", text)):
        k = int(m.group(1))
        need((text.startswith("an ")) == (k in (8, 11, 18)), f"article in {text!r}")
        return {k}
    if (m := re.fullmatch(r"a number greater than (\d+)", text)):
        return {x for x in xs if x > int(m.group(1))}
    if (m := re.fullmatch(r"a number less than (\d+)", text)):
        return {x for x in xs if x < int(m.group(1))}
    tests = {"an odd number": lambda x: x % 2 == 1, "an even number": lambda x: x % 2 == 0, "a multiple of 3": lambda x: x % 3 == 0,
             "a multiple of 4": lambda x: x % 4 == 0, "a prime number": sp.isprime, "a square number": lambda x: sp.sqrt(x).is_integer,
             "a factor of 12": lambda x: 12 % x == 0}
    need(text in tests, f"can't read the event {text!r}")
    return {x for x in xs if tests[text](x)}


def E14ME_num_word(x):
    return ("an " if x in (8, 11, 18) else "a ") + str(x)


def E14ME_slips(me, pa, pb, pi, w):
    out = {}
    out[E14ME_SK + "0"] = {"Yes: P(A ∩ B) = P(A) × P(B)"} if (not me and pi == pa * pb) else {"No: P(A ∩ B) ≠ P(A) × P(B)"}
    if not me and pa + pb < 1:
        out[E14ME_SK + "1"] = {f"Yes: P(A) + P(B) = {w(pa + pb)} < 1"}
    if pa + pb != 1:
        out[E14ME_T + "4"] = {f"No: P(A) + P(B) = {w(pa + pb)}, not 1"}
    out[E14ME_T + "5"] = {f"No: P(A ∪ B) = {w(pa + pb - pi)}, not 0"}
    return out


def E14ME_values(q, want, wrongs):
    """A value question: the answer, its tagged slips, and every other option a probability
    that isn't the answer."""
    gc_check_common(q, q["answer"]["label"] + dec_text(want), {k: {q["answer"]["label"] + dec_text(v)} for k, v in wrongs.items()})
    for o in q["choices"]:
        v = sp.Rational(o["text"][len(q["answer"]["label"]):])
        need(0 < v < 1, f"option {o['text']!r} is no probability")
        need(o["correct"] == (v == want), f"option {o['text']!r}")


def E14ME_check(q):
    u, L = q["view"]["unknown"], q["lines"]
    need(q["paper"] == 1, f"Paper {q['paper']}")
    if u == "decide-from-probabilities":
        need(len(L) == 3, f"can't read {L}")
        pa = E14ME_dec(L[0].removeprefix("P(A) = "))
        pb = E14ME_dec(L[1].removeprefix("P(B) = "))
        need(L[0].startswith("P(A) = ") and L[1].startswith("P(B) = "), f"can't read {L}")
        if L[2].startswith("P(A ∪ B) = "):
            pu = E14ME_dec(L[2][11:])
            pi = pa + pb - pu
            via = "P(A ∩ B) = P(A) + P(B) − P(A ∪ B) = "
        else:
            need(L[2].startswith("P(A ∩ B) = "), f"can't read {L[2]!r}")
            pi = sp.Rational(L[2][11:])
            via = "P(A ∩ B) = "
        need(0 <= pi < min(pa, pb), f"P(A ∩ B) = {pi} doesn't fit P(A) and P(B)")
        need(pa != pb and pa + pb - pi <= 1, "the clean limits")
        me = pi == 0
        right = f"Yes: {via}0" if me else f"No: {via}{dec_text(pi)}, not 0"
        tagged = E14ME_slips(me, pa, pb, pi, dec_text)
        for st in q["solutions"][0]["steps"]:
            if (m := re.fullmatch(r"P\(A ∪ B\) = P\(A\) \+ P\(B\) − P\(A ∩ B\), so P\(A ∩ B\) = ([\d.]+) \+ ([\d.]+) − ([\d.]+) = ([\d.]+)\.", st)):
                a, b, c, d = (sp.Rational(x) for x in m.groups())
                need((a, b, c) == (pa, pb, pa + pb - pi) and a + b - c == d, f"working {st!r}")
    elif u == "decide-from-venn":
        m = re.fullmatch(r"The Venn diagram shows how many of (\d+) equally likely outcomes are in each region for events A and B\.", L[0])
        need(m is not None and len(L) == 1, f"can't read {L}")
        n = int(m.group(1))
        g = q["graph"]
        need(g["kind"] == "venn" and g["names"] == ["A", "B"], "no Venn diagram")
        a, i, b, o = (int(g[k]) for k in "aibo")
        need(a + i + b + o == n and min(a, b, o) >= 1 and i >= 0, f"the regions don't make {n}")
        need(n in (20, 24, 30, 40) and a + i != b + i and a + b + 2 * i < n, "the clean limits")
        pa, pb, pi = sp.Rational(a + i, n), sp.Rational(b + i, n), sp.Rational(i, n)
        me = i == 0
        right = "Yes: no outcome is in both A and B, so P(A ∩ B) = 0" if me else f"No: {i} outcomes are in both A and B, so P(A ∩ B) = {frac_text(pi)}, not 0"
        tagged = E14ME_slips(me, pa, pb, pi, frac_text)
    elif u == "decide-in-context":
        need(len(L) == 2 and L[0] in E14ME_DEVICES, f"can't read {L}")
        n, one = E14ME_DEVICES[L[0]]
        m = re.fullmatch(r'A is the event "(.+)" and B is the event "(.+)"\.', L[1])
        need(m is not None, f"can't read {L[1]!r}")
        A, B = E14ME_event(m.group(1), n), E14ME_event(m.group(2), n)
        need(A and B and len(A) < n and len(B) < n and A != B, "an event is empty, certain, or the other one")
        both = sorted(A & B)
        me = not both
        need(len(A) + len(B) != n, "P(A) + P(B) = 1")
        right = f"Yes: no single {one} is both {m.group(1)} and {m.group(2)}" if me else f"No: {E14ME_num_word(both[0])} is both {m.group(1)} and {m.group(2)}"
        tagged = E14ME_slips(me, sp.Rational(len(A), n), sp.Rational(len(B), n), sp.Rational(len(both), n), frac_text)
        lists = f"A: {', '.join(map(str, sorted(A)))}. B: {', '.join(map(str, sorted(B)))}."
        for sol in q["solutions"]:
            need(any(lists in st for st in sol["steps"]), f"{sol['name']}: the outcomes listed are not the events'")
    elif u == "union-exclusive":
        if q["view"]["rep"] == "equation":
            need(len(L) == 3 and L[0] == "A and B are mutually exclusive." and L[1].startswith("P(A) = ") and L[2].startswith("P(B) = "), f"can't read {L}")
            pa, pb = E14ME_dec(L[1][7:]), E14ME_dec(L[2][7:])
        else:
            need(len(L) == 1 and "exactly one" in L[0], f"can't read {L}")
            ps = re.findall(r"\b0\.\d+", L[0])
            need(len(ps) == 2, f"can't read {L}")
            pa, pb = (E14ME_dec(p) for p in ps)
        need(pa != pb and pa + pb < 1, "the clean limits")
        E14ME_values(q, pa + pb, {E14ME_T + "2": pa * pb, E14ME_T + "3": pa + pb - pa * pb})
        return None, None
    else:
        need(len(L) == 3 and L[0] == "A and B are mutually exclusive." and L[1].startswith("P(A) = ") and L[2].startswith("P(A ∪ B) = "), f"can't read {L}")
        pa, pu = E14ME_dec(L[1][7:]), E14ME_dec(L[2][11:])
        need(pu > pa and pu - pa != pa and pa * 20 in (4, 10, 12, 15, 16), "the clean limits")
        E14ME_values(q, pu - pa, {E14ME_T + "3": (pu - pa) / (1 - pa)})
        return None, None
    gc_check_common(q, right, tagged)
    for o in q["choices"]:
        need(o["correct"] or o["ref"], f"the checker can't say why {o['text']!r} is wrong")
    return None, None


SITUATION_CHECKS["mutually-exclusive"] = E14ME_check

# ── end mutually-exclusive ──


# ── conditional-diagram (FAL-777) ────────────────────────────
# t4-ext-conditional-diagram. The table, the Venn diagram, the tree or the bag is read back from
# what the question shows, and the conditional worked out again by restricting to the given group.

E14CD_SK = "SL4.6.conditional-diagram#"
E14CD_T = "t4-ext-conditional-diagram#"
E14CD_COLOURS = [("red", "blue"), ("green", "white"), ("black", "yellow"), ("red", "green")]


def E14CD_counts(q):
    """a, i, b, o and u from the two-way table or the Venn diagram, with the totals checked."""
    if q["view"]["rep"] == "table":
        rows = q["table"]["rows"]
        need(rows[0] == ["", ["B", "B′", "Total"]] and [r[0] for r in rows[1:]] == ["A", "A′", "Total"], "the table's headings")
        (i, a, na), (b, o, nn), (nb, nb2, u) = ([int(x) for x in r[1]] for r in rows[1:])
        need(na == a + i and nn == b + o and nb == i + b and nb2 == a + o and u == a + i + b + o, "the table's totals don't add up")
        m = re.fullmatch(r"The table shows (\d+) .+\. A means they .+ and B means they .+\.", q["lines"][0])
        need(m is not None and int(m.group(1)) == u, f"can't read {q['lines'][0]!r}")
    else:
        g = q["graph"]
        need(g["kind"] == "venn", "no Venn diagram")
        a, i, b, o = (int(g[k]) for k in "aibo")
        u = a + i + b + o
        need(q["lines"][0] == f"The Venn diagram shows how many of {u} outcomes are in each region for events A and B. One is chosen at random.", "the total")
    need(min(a, b, o) >= 2 and i >= 2 and max(a, b, o) <= 30 and i <= 20, "the clean limits")
    return a, i, b, o, u


def E14CD_spot(q, lines):
    a, i, b, o, u = E14CD_counts(q)
    gb = E14CD_given_b(q) if q["view"]["rep"] == "table" else q["asked"] == "Find P(A | B)."
    given = "B" if gb else "A"
    ng = i + (b if given == "B" else a)
    name = "P(A | B)" if given == "B" else "P(B | A)"
    value = None
    for k, t in enumerate(lines):
        if (m := re.fullmatch(r"The given group is ([AB]): n\(([AB])\) = (\d+) \+ (\d+) = (\d+)\.", t)):
            ok = m.group(1) == m.group(2) == given and int(m.group(3)) + int(m.group(4)) == int(m.group(5)) == ng
        elif (m := re.fullmatch(r"Both A and B: n\(A ∩ B\) = (\d+)\.", t)):
            ok = int(m.group(1)) == i
        elif (m := re.fullmatch(r"(P\([AB] \| [AB]\)) = (\d+) ÷ (\d+)", t)):
            ok = m.group(1) == name and int(m.group(2)) == i and int(m.group(3)) == ng
            value = sp.Rational(int(m.group(2)), int(m.group(3)))
        elif (m := re.fullmatch(r"= (\d+/\d+|\d+)", t)):
            ok = value is not None and sp.Rational(m.group(1)) == value and value == sp.Rational(i, ng)
        elif (m := re.fullmatch(r"So (P\([AB] \| [AB]\)) = (\d+/\d+|\d+)", t)):
            ok = m.group(1) == name and sp.Rational(m.group(2)) == sp.Rational(i, ng)
        else:
            need(False, f"can't read the line {t!r}")
        if not ok:
            return k
    return None


def E14CD_given_b(q):
    """On a table, whether the question restricts to group B: the asked sentence names B's
    words after 'those who' (the table line says which words are A and which B)."""
    m = re.fullmatch(r"The table shows \d+ .+\. A means they (.+) and B means they (.+)\.", q["lines"][0])
    need(m is not None, "can't read the table's line")
    mm = re.fullmatch(r"An? .+ is chosen at random from those who (.+)\. Find the probability that they also (.+)\.", q["asked"])
    need(mm is not None, f"can't read {q['asked']!r}")
    need({mm.group(1), mm.group(2)} == {m.group(1), m.group(2)}, "the asked groups are not the table's")
    return mm.group(1) == m.group(2)


def E14CD_check(q):
    u_, L = q["view"]["unknown"], q["lines"]
    if "A student's working:" in L:
        L = L[:L.index("A student's working:")]
        q = dict(q, lines=L)
    need(q["paper"] == 1, f"Paper {q['paper']}")
    R1 = sp.Rational
    if u_ in ("from-table", "from-venn"):
        a, i, b, o, u = E14CD_counts(q)
        if u_ == "from-table":
            gb = E14CD_given_b(q)
            label = "probability = "
        else:
            need(q["asked"] in ("Find P(A | B).", "Find P(B | A)."), f"asked {q['asked']!r}")
            gb = q["asked"] == "Find P(A | B)."
            label = "P(A | B) = " if gb else "P(B | A) = "
        ng, nother = (i + b, i + a) if gb else (i + a, i + b)
        need(5 * ng >= u and ng != nother, "the clean limits")
        want = R1(i, ng)
        wrongs = {E14CD_SK + "0": R1(i, u), E14CD_SK + "1": R1(i, nother), E14CD_T + "7": R1(ng, u)}
        need(len({want, *wrongs.values()}) == 4, "two slips give the same number")
        text = lambda v: label + frac_text(v)
    elif u_ == "tree-branch":
        g = q["graph"]
        need(g["kind"] == "tree" and g["first"] == ["A", "A′"] and g["second"] == ["B", "B′"], "no tree")
        pa, pa2 = (R1(x) for x in g["p"])
        (pba, pba2), (pbn, pbn2) = ([R1(x) for x in r] for r in g["q"])
        need(pa + pa2 == 1 and pba + pba2 == 1 and pbn + pbn2 == 1, "a pair of branches doesn't add to 1")
        need((pa * 10).q == 1 and sp.Rational(1, 5) <= pa <= sp.Rational(4, 5) and (pba * 20).q == 1 and (pbn * 20).q == 1 and 0 < pba < 1 and 0 < pbn < 1, "the clean limits")
        if q["asked"] == "Find P(B | A).":
            want, label = pba, "P(B | A) = "
            wrongs = {E14CD_T + "2": pa * pba, E14CD_T + "4": pbn, E14CD_T + "6": pa * pba + (1 - pa) * pbn}
        else:
            need(q["asked"] == "Find P(B′ | A′).", f"asked {q['asked']!r}")
            want, label = 1 - pbn, "P(B′ | A′) = "
            wrongs = {E14CD_T + "2": (1 - pa) * (1 - pbn), E14CD_T + "4": 1 - pba, E14CD_T + "6": (1 - pa) * (1 - pbn) + pa * (1 - pba)}
        need(len({want, *wrongs.values()}) == 4, "two slips give the same number")
        text = lambda v: label + dec_text(v)
    else:
        m = re.fullmatch(r"A bag holds (\d+) (\w+) and (\d+) (\w+) (\w+)\.", L[0])
        need(m is not None and len(L) == 2 and L[1] == "Two are taken at random, one after the other, without replacement.", f"can't read {L}")
        r, c0, g_, c1 = int(m.group(1)), m.group(2), int(m.group(3)), m.group(4)
        need((c0, c1) in E14CD_COLOURS and r != g_ and 3 <= r <= 9 and 3 <= g_ <= 9, "the clean limits")
        mm = re.fullmatch(rf"Given that the first is {c0}, find the probability that the second is (\w+)\.", q["asked"])
        need(mm is not None and mm.group(1) in (c0, c1), f"asked {q['asked']!r}")
        same = mm.group(1) == c0
        n = r + g_
        # The second draw, counted from the bag that is left.
        top = sum(1 for k in range(n) if k != 0 and (k < r if same else k >= r))
        want = R1(top, n - 1)
        wrongs = {E14CD_T + "2": R1(r * top, n * (n - 1)), E14CD_T + "3": R1(r if same else g_, n)}
        if same:
            wrongs[E14CD_SK + "0"] = R1(top, n)
        need(len({want, *wrongs.values()}) == len(wrongs) + 1, "two slips give the same number")
        text = lambda v: "probability = " + frac_text(v)
    gc_check_common(q, text(want), {k: {text(v)} for k, v in wrongs.items()})
    for o in q["choices"]:
        lab = q["answer"]["label"]
        need(o["text"].startswith(lab), f"option {o['text']!r}")
        v = R1(o["text"][len(lab):])
        need(0 < v < 1 and o["correct"] == (v == want), f"option {o['text']!r}")
    return None, None


SITUATION_CHECKS["conditional-diagram"] = E14CD_check
SPOT_CHECKS["conditional-diagram"] = E14CD_spot

# ── end conditional-diagram ──


# ── z-score (FAL-777) ────────────────────────────────────────
# t4-ext-z-scores. μ, σ and the value are read back from the model line, the story or the figure,
# and z = (x − μ)/σ or x = μ + zσ worked out again; a comparison standardises both values (and
# for the proportion below uses mpmath's normal cdf), and the better is the larger z, or for a
# time the smaller. The checker's own copy of the clean limits.

E14ZS_ZS = "SL4.12.z-score#"
E14ZS_CZ = "SL4.12.compare-z#"
E14ZS_T = "t4-ext-z-scores#"
E14ZS_SIGMAS = {2, 4, 5, 8, 10, 16, 20}
# what -> (unit, one value, its subject, its noun)
E14ZS_CTX = {"The marks in a test": (" marks", "a mark", "The mark", "mark"),
             "The masses of melons from a farm": (" g", "a melon's mass", "The melon's mass", "mass"),
             "The heights of adult cactus plants": (" cm", "a cactus's height", "The cactus's height", "height"),
             "The lengths of steel rods from a forge": (" mm", "a rod's length", "The rod's length", "length")}


def E14ZS_n(t):
    return sp.Rational(t.replace("−", "-"))


def E14ZS_model(q):
    """μ, σ and the context (None for X ~ N) from the first line."""
    L = q["lines"]
    if (m := re.fullmatch(r"X ~ N\((\d+), (\d+)²\)", L[0])):
        return int(m.group(1)), int(m.group(2)), None
    m = re.fullmatch(r"(.+) are normally distributed with mean (\d+)(.*) and standard deviation (\d+)(.*)\.", L[0])
    need(m is not None and m.group(1) in E14ZS_CTX, f"can't read {L[0]!r}")
    c = E14ZS_CTX[m.group(1)]
    need(m.group(3) == c[0] == m.group(5), "the units")
    return int(m.group(2)), int(m.group(4)), c


def E14ZS_cap(t):
    return t[:1].upper() + t[1:]


def E14ZS_values(q, want, wrongs, label, unit=""):
    text = lambda v: label + dec_text(v) + unit
    gc_check_common(q, text(want), {k: {text(v)} for k, v in wrongs.items()})
    for o in q["choices"]:
        need(o["text"].startswith(label) and o["text"].endswith(unit), f"option {o['text']!r}")
        v = E14ZS_n(o["text"][len(label):len(o["text"]) - len(unit)])
        need(o["correct"] == (v == want), f"option {o['text']!r}")


def E14ZS_pct(z):
    return gc_s(100 * mpmath.ncdf(mpmath.mpf(sp.Rational(z).p) / sp.Rational(z).q)) + "%"


def E14ZS_compare(q, times):
    L = q["lines"]
    need(len(L) == 2, f"can't read {L}")
    vals = {}
    for t in L:
        if times:
            m = re.fullmatch(r"(\w+) ran the 400 m in (\d+) s\. In (.+), 400 m times have mean (\d+) s and standard deviation (\d+) s\.", t)
        else:
            m = re.fullmatch(r"(\w+)'s mark in (\w+) was (\d+)\. The (\w+) marks had mean (\d+) and standard deviation (\d+)\.", t)
        need(m is not None, f"can't read {t!r}")
        if times:
            name, x, grp, mu, sg = m.group(1), int(m.group(2)), m.group(3), int(m.group(4)), int(m.group(5))
            key = name
        else:
            name, key, x, mu, sg = m.group(1), m.group(2), int(m.group(3)), int(m.group(5)), int(m.group(6))
            need(m.group(4) == key, "the subject")
            grp = None
        z = sp.Rational(x - mu, sg)
        need(2 <= sg <= 10 and (z * 4).q == 1 and sp.Rational(1, 2) <= abs(z) <= sp.Rational(5, 2), f"the clean limits: z = {z}")
        need((z < 0) == times, "a score below the mean or a time above it")
        vals[key] = dict(name=name, x=x, mu=mu, sg=sg, z=z, grp=grp, gap=abs(x - mu))
    k1, k2 = sorted(vals, key=lambda k: vals[k]["z"], reverse=not times)
    a, b = vals[k1], vals[k2]
    need(abs(a["z"] - b["z"]) >= sp.Rational(1, 4) and abs(a["z"]) > abs(b["z"]), "the z-values are too close")
    need((a["x"] < b["x"]) if not times else (a["x"] > b["x"]), "the raw values don't point the other way")
    need(a["gap"] < b["gap"] and a["mu"] != b["mu"], "the gaps don't point the other way")
    need(q["paper"] == 2, "a comparison is Paper 2")
    perc = q["view"]["angle"] == "compare-percentiles"
    if times:
        need(q["asked"] == "Whose time was more exceptional? Give a reason.", "asked")
        if perc:
            right = f"{a['name']}'s: only {E14ZS_pct(a['z'])} of {a['grp']} were faster than {a['name']}, fewer than {E14ZS_pct(b['z'])} of {b['grp']} for {b['name']}"
        else:
            right = f"{a['name']}'s: {a['name']}'s z-value, {dec_text(a['z'])}, is lower than {b['name']}'s, {dec_text(b['z'])}, and a lower time is better"
        tagged = {E14ZS_CZ + "2": {f"{b['name']}'s: {b['name']}'s z-value, {dec_text(b['z'])}, is higher than {a['name']}'s, {dec_text(a['z'])}"},
                  E14ZS_CZ + "0": {f"{b['name']}'s: {b['name']}'s time, {b['x']} s, is lower than {a['x']} s"},
                  E14ZS_CZ + "1": {f"{b['name']}'s: {b['name']} was {b['gap']} s below the mean, more than {a['name']}'s {a['gap']} s"}}
        plain = set()
    else:
        who = a["name"]
        need(b["name"] == who and q["asked"] == f"In which subject did {who} do better relative to the class? Give a reason.", "asked")
        if perc:
            right = f"{E14ZS_cap(k1)}: {E14ZS_pct(a['z'])} of the class scored below {who} there, more than {E14ZS_pct(b['z'])} in {k2}"
        else:
            right = f"{E14ZS_cap(k1)}: {who}'s z-value there, {dec_text(a['z'])}, is higher than {dec_text(b['z'])} in {k2}"
        tagged = {E14ZS_CZ + "0": {f"{E14ZS_cap(k2)}: {who}'s mark there, {b['x']}, is higher than {a['x']}"},
                  E14ZS_CZ + "1": {f"{E14ZS_cap(k2)}: {who} is {b['gap']} marks above the mean there, more than {a['gap']}"}}
        if perc:
            plain = {f"Neither: {who} scored above {E14ZS_pct(a['z'])} of the class in {k1} and above {E14ZS_pct(b['z'])} in {k2}, so both marks are equally good"}
        else:
            plain = {f"Neither: {who}'s z-values, {dec_text(a['z'])} in {k1} and {dec_text(b['z'])} in {k2}, are both positive, so both marks are equally good"}
    gc_check_common(q, right, tagged)
    for o in q["choices"]:
        need(o["correct"] or o["ref"] or o.get("trap") or o["text"] in plain, f"the checker can't say why {o['text']!r} is wrong")
    # The working: each value standardised, or its proportion below.
    for sol in q["solutions"]:
        for v in (a, b):
            lead = (v["name"] if times else E14ZS_cap(k1 if v is a else k2)) + ": "
            if sol["angle"] == "compare-z-values":
                want = f"{lead}z = ({v['x']} − {v['mu']})/{v['sg']} = {dec_text(v['z'])}."
            else:
                p = gc_s(mpmath.ncdf(mpmath.mpf(v["z"].p) / v["z"].q))
                want = f"{lead}P(X < {v['x']}) = normalcdf(−10^99, {v['x']}, {v['mu']}, {v['sg']}) = {p}."
            need(want in sol["steps"], f"{sol['name']}: no line {want!r}")


def E14ZS_check(q):
    u, L = q["view"]["unknown"], q["lines"]
    if "A student's working:" in L:
        L = L[:L.index("A student's working:")]
        q = dict(q, lines=L)
    if u in ("compare-scores", "compare-times"):
        E14ZS_compare(q, u == "compare-times")
        return None, None
    need(q["paper"] == 1, f"Paper {q['paper']}")
    mu, sg, c = E14ZS_model(q)
    rep = q["view"]["rep"]
    need(sg in E14ZS_SIGMAS, f"σ = {sg}")
    if u == "z-from-x":
        if rep == "words":
            m = re.fullmatch(rf"Find the z-value of {re.escape(c[1])} of (\d+){re.escape(c[0])}\.", q["asked"])
            need(m is not None and len(L) == 1, f"asked {q['asked']!r}")
        else:
            m = re.fullmatch(r"Find the z-value of x = (\d+)\.", q["asked"])
            need(m is not None and len(L) == 2, f"asked {q['asked']!r}")
            x_line = f"x = {m.group(1)}" + (" is marked on the axis, with μ and steps of σ." if rep == "graph" else "")
            need(L[1] == x_line, f"can't read {L[1]!r}")
        x = int(m.group(1))
        z = sp.Rational(x - mu, sg)
        need(z != 0 and (2 * z).q == 1 and abs(z) <= 3, f"z = {z}")
        if rep == "graph":
            g = q["graph"]
            k = max(2, math.ceil(abs(z)))
            want_marks = [{"at": float(mu + j * sg), "label": str(mu + j * sg)} for j in range(-k, k + 1)] + [{"at": float(x), "label": "x"}]
            need(g["kind"] == "normal" and g["mu"] == mu and g["sigma"] == sg, "the curve is another distribution")
            need([{"at": float(mk["at"]), "label": mk["label"]} for mk in g["marks"]] == want_marks, "the axis marks are not μ, the steps of σ and x")
        E14ZS_values(q, z, {E14ZS_ZS + "1": -z, E14ZS_ZS + "0": sp.Rational(x - mu, sg * sg)}, "z = ")
    elif u == "x-from-z":
        if rep == "words":
            m = re.fullmatch(rf"{re.escape(E14ZS_cap(c[1]))} has a z-value of (−?[\d.]+)\.", L[1])
            need(m is not None and len(L) == 2 and q["asked"] == f"Find this {c[3]}.", f"can't read {L}")
        else:
            m = re.fullmatch(r"z = (−?[\d.]+)", L[1])
            need(m is not None and len(L) == 2 and q["asked"] == "Find the value of x with this z-value.", f"can't read {L}")
        z = E14ZS_n(m.group(1))
        need(z != 0 and (2 * z).q == 1 and abs(z) <= 3, f"z = {z}")
        x = mu + z * sg
        need(x.q == 1, "x is not whole")
        E14ZS_values(q, x, {E14ZS_ZS + "1": mu - z * sg, E14ZS_T + "10": mu + z * sg * sg, E14ZS_T + "6": mu + z}, "x = ", c[0] if rep == "words" else "")
    else:
        m = re.fullmatch(rf"{re.escape(E14ZS_cap(c[1]))} has a z-value of (−?[\d.]+)\.", L[1])
        need(m is not None and len(L) == 2 and q["asked"] == "Which statement is true?", f"can't read {L}")
        z = E14ZS_n(m.group(1))
        need(z != 0 and (2 * z).q == 1 and abs(z) <= 2 and (mu + z * sg).q == 1, f"z = {z}")
        a = dec_text(abs(z))
        sds = "1 standard deviation" if abs(z) == 1 else f"{a} standard deviations"
        sd = "above" if z > 0 else "below"
        other = "below" if z > 0 else "above"
        right = f"{c[2]} is {sds} {sd} the mean"
        tagged = {E14ZS_ZS + "1": {f"{c[2]} is {sds} {other} the mean"}, E14ZS_T + "7": {f"{c[2]} is {a}{c[0]} {sd} the mean"}}
        if z < 0:
            tagged[E14ZS_ZS + "2"] = {"A z-value can't be negative, so there is an error"}
        gc_check_common(q, right, tagged)
        for o in q["choices"]:
            need(o["correct"] or o["ref"] or o["text"] == f"{c[2]} is {a} times the mean", f"the checker can't say why {o['text']!r} is wrong")
    return None, None


def E14ZS_spot(q, lines):
    L = q["lines"][:q["lines"].index("A student's working:")]
    q = dict(q, lines=L)
    mu, sg, c = E14ZS_model(q)
    u = q["view"]["unknown"]
    if u == "z-from-x":
        x = int(re.search(r"(\d+)", q["asked"].split("of")[-1]).group(1))
        z = sp.Rational(x - mu, sg)
        for i, t in enumerate(lines):
            if t == "z = (x − μ)/σ":
                ok = True
            elif (m := re.fullmatch(r"= \((\d+) − (\d+)\)/(\d+)²", t)):
                ok = (int(m.group(1)), int(m.group(2))) == (x, mu) and int(m.group(3)) ** 2 == sg
            elif (m := re.fullmatch(r"x − μ = (\d+) − (\d+) = (−?\d+)", t)):
                ok = (int(m.group(1)), int(m.group(2))) == (x, mu) and E14ZS_n(m.group(3)) == x - mu
            elif (m := re.fullmatch(r"σ² = (\d+)", t)):
                ok = int(m.group(1)) == sg * sg
            elif (m := re.fullmatch(r"(?:z = |= )(−?\d+)(?:/| ÷ )(\d+)", t)):
                ok = sp.Rational(E14ZS_n(m.group(1)), int(m.group(2))) == z
            elif (m := re.fullmatch(r"= (−?[\d.]+)", t)):
                ok = E14ZS_n(m.group(1)) == z
            else:
                need(False, f"can't read the line {t!r}")
            if not ok:
                return i
        return None
    zt = re.search(r"z(?: = |-value of )(−?\d+(?:\.\d+)?)", " ".join(L)).group(1)
    z = E14ZS_n(zt)
    x = mu + z * sg
    for i, t in enumerate(lines):
        if t == "x = μ + zσ":
            ok = True
        elif (m := re.fullmatch(r"zσ = (−?[\d.]+) × (\d+) = (−?[\d.]+)", t)):
            ok = E14ZS_n(m.group(1)) == z and int(m.group(2)) == sg and E14ZS_n(m.group(3)) == z * sg
        elif (m := re.fullmatch(r"= (\d+) \+ \(?(−?[\d.]+)\)? × (\d+)", t)):
            ok = int(m.group(1)) == mu and E14ZS_n(m.group(2)) == z and int(m.group(3)) == sg
        elif (m := re.fullmatch(r"= (\d+) ([+−]) ([\d.]+)", t)):
            ok = mu + (1 if m.group(2) == "+" else -1) * E14ZS_n(m.group(3)) == x
        elif (m := re.fullmatch(r"= (−?[\d.]+)", t)):
            ok = E14ZS_n(m.group(1)) == x
        else:
            need(False, f"can't read the line {t!r}")
        if not ok:
            return i
    return None


SITUATION_CHECKS["z-score"] = E14ZS_check
SPOT_CHECKS["z-score"] = E14ZS_spot

# ── end z-score ──


# ── sign-at-point (FAL-777) ──────────────────────────────────
# t5-ext-sign-at-point. f (or f′) is read back from the question, differentiated with SymPy and
# evaluated at the point; the direction is the sign of f′(a), and the slips are rebuilt from the
# same f. On Paper 2 f′(a) and f(a) come from mpmath, to 3 s.f.

E14SP_SK = "SL5.2.sign-at-point#"
E14SP_T = "t5-ext-sign-at-point#"
# The story -> (name, end, Up, Down, up, down, negative): a positive quantity falls, a negative one rises.
E14SP_CTX = {"The temperature of a cooling tank, in °C,": ("temperature", 6, "Rising", "Falling", "rising", "falling", False),
             "The depth of water in a reservoir, in metres,": ("depth of water", 8, "Rising", "Falling", "rising", "falling", False),
             "The number of rats in a bunker, in hundreds,": ("number of rats", 6, "Increasing", "Decreasing", "increasing", "decreasing", False),
             "The price of fuel, in caps per litre,": ("price of fuel", 8, "Rising", "Falling", "rising", "falling", False),
             "The temperature inside a freezer, in °C,": ("temperature", 6, "Rising", "Falling", "rising", "falling", True),
             "The height of a diver above the surface, in metres,": ("diver's height", 8, "Rising", "Falling", "rising", "falling", True),
             "The balance of a trader's account, in hundreds of caps,": ("balance", 8, "Rising", "Falling", "rising", "falling", True)}


def E14SP_poly(text, letter):
    e = E13PC_expr(text.replace(letter, "x")) if letter != "x" else E13PC_expr(text)
    return sp.Poly(e, CX)


def E14SP_cmp(v):
    return "> 0" if v > 0 else "< 0"


def E14SP_num(v):
    return frac_text(v) if isinstance(v, sp.Rational) or sp.Rational(v).q == 1 else dec_text(v)


def E14SP_check(q):
    u, L = q["view"]["unknown"], q["lines"]
    X = CX
    angle = q["view"]["angle"]
    plain = set()
    if u in ("from-formula", "in-context"):
        if u == "from-formula":
            m = re.fullmatch(r"f\(x\) = (.+)", L[0])
            need(m is not None and len(L) == 1, f"can't read {L}")
            g, letter, up, down = "f", "x", "Increasing", "Decreasing"
            f = E14SP_poly(m.group(1), "x")
            m2 = re.fullmatch(r"Is f increasing or decreasing at x = (−?\d+)\? Give a reason\.", q["asked"])
            need(m2 is not None, f"asked {q['asked']!r}")
            a = int(m2.group(1).replace("−", "-"))
            need(a in (-3, -2, -1, 2, 3), f"a = {a}")
        else:
            m = re.fullmatch(r"(.+,) is modelled by ([A-Z])\(t\) = (.+), where t is the time in hours, 0 ≤ t ≤ (\d+)\.", L[0])
            need(m is not None and len(L) == 1 and m.group(1) in E14SP_CTX, f"can't read {L}")
            name, end, up, down, up_w, down_w, neg = E14SP_CTX[m.group(1)]
            need(int(m.group(4)) == end, "the time the story runs for")
            g, letter = m.group(2), "t"
            f = E14SP_poly(m.group(3), "t")
            m2 = re.fullmatch(rf"Is the {re.escape(name)} {up_w} or {down_w} at t = (\d+)\? Give a reason\.", q["asked"])
            need(m2 is not None, f"asked {q['asked']!r}")
            a = int(m2.group(1))
            need(0 < a < end, f"t = {a}")
            if neg:
                need(all(-200 <= f.eval(t) < 0 for t in range(end + 1)), "the quantity leaves [−200, 0)")
            else:
                need(all(0 < f.eval(t) <= 200 for t in range(end + 1)), "the quantity leaves (0, 200]")
        need(f.degree() == 3, "f is not a cubic")
        d = f.diff(X)
        fa, fp = f.eval(a), d.eval(a)
        need(fa != 0 and fp != 0 and (fa > 0) != (fp > 0), "f(a) and f′(a) don't point opposite ways")
        word = up if fp > 0 else down
        lo, hi = sp.Rational(100 * a - 1, 100), sp.Rational(100 * a + 1, 100)
        flo, fhi = f.eval(lo), f.eval(hi)
        need((flo < fhi) == (fp > 0), "the neighbours disagree with f′(a)")
        if angle == "compare-neighbours":
            right = f"{word}, because {g}({dec_text(lo)}) {'<' if flo < fhi else '>'} {g}({dec_text(hi)})"
        else:
            right = f"{word}, because {g}′({frac_text(a)}) = {frac_text(fp)} {E14SP_cmp(fp)}"
        c3, c2, c1, _ = f.all_coeffs()
        # One term differentiated with its power left the same: x³ to 3x³, or x² to 2x².
        kept = {v for v in (3 * c3 * a**3 + 2 * c2 * a + c1, 3 * c3 * a**2 + 2 * c2 * a**2 + c1) if v not in (0, fp)}
        wd = lambda v: up if v > 0 else down
        tagged = {E14SP_SK + "0": {f"{wd(fa)}, because {g}({frac_text(a)}) = {frac_text(fa)} {E14SP_cmp(fa)}"},
                  E14SP_SK + "1": {f"{word}, because the graph {'goes up' if fp > 0 else 'goes down'}"}}
        if kept:
            tagged[E14SP_T + "2"] = {f"{wd(v)}, because {g}′({frac_text(a)}) = {frac_text(v)} {E14SP_cmp(v)}" for v in kept}
        plain = {f"Neither: {g} has a turning point at {letter} = {frac_text(a)}"}
        for sol in q["solutions"]:
            for st in sol["steps"]:
                if (mm := re.fullmatch(rf"{g}′\({letter}\) = (.+)\.", st)):
                    need(E14SP_poly(mm.group(1), letter).as_expr() == d.as_expr(), f"{sol['name']}: {st!r} is not {g}′")
                if (mm := re.fullmatch(rf"{g}\((−?[\d.]+)\) = (−?[\d.]+) and {g}\((−?[\d.]+)\) = (−?[\d.]+)\.", st)):
                    vals = [sp.Rational(x.replace("−", "-")) for x in mm.groups()]
                    need(vals == [lo, flo, hi, fhi], f"{sol['name']}: {st!r}")
    elif u == "from-derivative":
        m = re.fullmatch(r"f′\(x\) = (−?\d*)\(x ([+−]) (\d+)\)\(x ([+−]) (\d+)\)", L[0])
        need(m is not None and len(L) == 1, f"can't read {L}")
        k = {"": 1, "−": -1}.get(m.group(1), None) or int(m.group(1).replace("−", "-"))
        p = int(m.group(3)) * (1 if m.group(2) == "−" else -1)
        r = int(m.group(5)) * (1 if m.group(4) == "−" else -1)
        m2 = re.fullmatch(r"Is f increasing or decreasing at x = (−?\d+)\? Give a reason\.", q["asked"])
        need(m2 is not None, f"asked {q['asked']!r}")
        a = int(m2.group(1).replace("−", "-"))
        need(p < r and a not in (p, r) and 0 not in (p, r) and abs(k) <= 3, "the clean limits")
        fp = sp.expand(k * (X - p) * (X - r)).subs(X, a)
        word = "Increasing" if fp > 0 else "Decreasing"
        kt = "" if k == 1 else ("−" if k == -1 else frac_text(k))
        sgn = lambda v: f"+ {v}" if v >= 0 else f"− {-v}"
        right = f"{word}, because f′({frac_text(a)}) = {kt}({frac_text(a)} {sgn(-p)})({frac_text(a)} {sgn(-r)}) = {frac_text(fp)} {E14SP_cmp(fp)}"
        flips = set()
        for f0, f1 in ((-p, r), (p, -r)):
            v = k * (a - f0) * (a - f1)
            if v != 0 and v != fp:
                flips.add(f"{'Increasing' if v > 0 else 'Decreasing'}, because f′({frac_text(a)}) = {frac_text(v)} {E14SP_cmp(v)}")
        tagged = {E14SP_SK + "1": {f"{word}, because the graph {'goes up' if fp > 0 else 'goes down'}"}}
        if flips:
            tagged[E14SP_T + "3"] = flips
        plain = {f"Neither: f has a turning point at x = {frac_text(a)}"}
    else:
        need(q["paper"] == 2, "a GDC question is Paper 2")
        m = re.fullmatch(r"f\(x\) = (.+?)(, x > 0)?", L[0])
        need(m is not None and len(L) == 1, f"can't read {L}")
        f = E13_expr(m.group(1))
        m2 = re.fullmatch(r"Is f increasing or decreasing at x = (\d\.\d)\? Give a reason\.", q["asked"])
        need(m2 is not None, f"asked {q['asked']!r}")
        a = sp.Rational(m2.group(1))
        need(0 < a <= 3 and (10 * a).q == 1 and a.q != 1, f"x = {a}")
        fp = sp.N(sp.diff(f, X).subs(X, a), 40)
        fa = sp.N(f.subs(X, a), 40)
        need(abs(fp) > 0.1 and abs(fa) > 0.1 and (fp > 0) != (fa > 0) and not on_edge(abs(fp)) and not on_edge(abs(fa)), "the clean limits")
        at = m2.group(1)
        word = "Increasing" if fp > 0 else "Decreasing"
        right = f"{word}, because the GDC gives f′({at}) = {gc_s(fp)} {E14SP_cmp(fp)}"
        tagged = {E14SP_SK + "0": {f"{'Increasing' if fa > 0 else 'Decreasing'}, because f({at}) = {gc_s(fa)} {E14SP_cmp(fa)}"},
                  E14SP_SK + "1": {f"{word}, because the graph {'goes up' if fp > 0 else 'goes down'}"}}
        plain = {f"Neither: f has a turning point at x = {at}"}
        need(any(gc_s(fp) in st for st in q["solutions"][0]["steps"][:-1]), "the working doesn't show the GDC's gradient")
    if u != "gdc-check":
        need(q["paper"] == 1, f"Paper {q['paper']}")
    gc_check_common(q, right, tagged)
    for o in q["choices"]:
        need(o["correct"] or o["ref"] or o.get("trap") or o["text"] in plain, f"the checker can't say why {o['text']!r} is wrong")
    return None, None


SITUATION_CHECKS["sign-at-point"] = E14SP_check

# ── end sign-at-point ──


# ── gradient-from-graph (FAL-777) ────────────────────────────
# t5-ext-gradient-from-graph. The curve f(x) = c(x − a)^deg + m(x − a) + y₀ is rebuilt with SymPy
# from the question's data and held to its figure (every sampled point) and its table; the gradient
# is the tangent's rise over run between the grid points the question names, the chord's from the
# table, or SymPy's f′(a) to 3 s.f. on Paper 2. Each tagged option is rebuilt from the same numbers.

E14GG_SK = "SL5.1.gradient-from-graph#"
E14GG_T = "t5-ext-gradient-from-graph#"
E14GG_PT = r"\((−?\d+), (−?\d+)\)"


def E14GG_n(t):
    return sp.Rational(t.replace("−", "-"))


def E14GG_f(g):
    deg, c, a, m, y0 = int(g["deg"]), sp.Rational(str(g["c"])), int(g["a"]), int(g["m"]), int(g["y0"])
    # compare-two asks about A and B, not P, so its m may be 0.
    need(deg in (2, 3) and c != 0 and (m != 0 or g["ask"] == "compare-two"), "the curve's clean limits")
    return sp.expand(c * (CX - a) ** deg + m * (CX - a) + y0), a, y0


def E14GG_on(curve, e):
    """Every sampled point of a drawn curve lies on e."""
    fl = sp.lambdify(CX, e)
    need(len(curve) > 10, "a curve with too few points")
    for x, y in curve:
        need(abs(fl(x) - y) < 1e-6, f"the drawn curve leaves the curve at x = {x}")


def E14GG_line(curve):
    """The gradient and the line of a drawn straight line, from its ends."""
    (x0, y0), (x1, y1) = curve[0], curve[-1]
    g = sp.nsimplify((y1 - y0) / (x1 - x0), rational=True, tolerance=1e-9)
    for x, y in curve:
        need(abs(y0 + float(g) * (x - x0) - y) < 1e-6, "a drawn line is not straight")
    return g, sp.nsimplify(y0 - float(g) * x0, rational=True, tolerance=1e-9)


def E14GG_plain(q, plain):
    for o in q["choices"]:
        need(o["correct"] or o["ref"] or o.get("trap") or o["text"] in plain, f"the checker can't say why {o['text']!r} is wrong")


def E14GG_check(q):
    u, L, g = q["view"]["unknown"], q["lines"], q["given"]
    need(q["paper"] == (2 if u == "gdc-gradient" else 1), f"Paper {q['paper']}")
    if u == "gdc-gradient":
        m = re.fullmatch(r"f\(x\) = (.+?)(, x > 0)?", L[0])
        need(m is not None and len(L) == 1, f"can't read {L}")
        f = E13_expr(m.group(1))
        need(("log" in str(f)) == (m.group(2) is not None), "ln x without x > 0")
        m2 = re.fullmatch(r"Find the gradient of the curve y = f\(x\) at x = (\d\.\d)\.", q["asked"])
        need(m2 is not None, f"asked {q['asked']!r}")
        a = sp.Rational(m2.group(1))
        need(sp.Rational(1, 2) <= a <= 3 and a.q != 1, f"x = {a}")
        fp = sp.N(sp.diff(f, CX).subs(CX, a), 40)
        fa = sp.N(f.subs(CX, a), 40)
        need(abs(fp) > 0.1 and abs(fa) > 0.1 and not on_edge(abs(fp)) and not on_edge(abs(fa)) and not on_edge(abs(fa / a)), "the clean limits")
        h = sp.Rational(1, 1000)
        chord = sp.N((f.subs(CX, a + h) - f.subs(CX, a - h)) / (2 * h), 40)
        need(gc_s(chord) == gc_s(fp), "the short chord doesn't give f′(a) to 3 s.f.")
        gc_check_common(q, gc_s(fp), {E14GG_SK + "0": {gc_s(fa)}, E14GG_SK + "1": {gc_s(fa / a)}}, trap=gc_s2(fp))
        for sol in q["solutions"]:
            nums = [E14GG_n(x) for st in sol["steps"][:-1] for x in re.findall(r"−?\d+\.\d+", st)]
            if sol["angle"] == "gdc-dydx":
                need(any(abs(v - fp) < 1e-5 * max(1, abs(fp)) for v in nums), f"{sol['name']}: no GDC gradient")
            else:
                need(any(abs(v - chord) < 1e-5 * max(1, abs(chord)) for v in nums), f"{sol['name']}: no chord gradient")
        E14GG_plain(q, {gc_s(fp + 1), gc_s(fp - 1)})
        return None, None
    f, a, y0 = E14GG_f(g)
    d = sp.diff(f, CX)
    # A drawn tangent touches without cutting: no point of inflexion at P.
    need(u == "chord-table" or int(g["deg"]) == 2, "the drawn curve is not a parabola")
    if u == "tangent-drawn":
        m = re.fullmatch(rf"The graph shows the curve y = f\(x\) and its tangent at P{E14GG_PT}\. The tangent runs through the grid points {E14GG_PT} and {E14GG_PT}\.", L[0])
        need(m is not None and len(L) == 1 and q["asked"] == "Find the gradient of the curve at P.", f"can't read {L}")
        pa, py, x1, y1, x2, y2 = (int(v.replace("−", "-")) for v in m.groups())
        need((pa, py) == (a, y0) and f.subs(CX, a) == y0, "P is not on the curve")
        need(x1 == a - 2 and x2 == a + 2, "the grid points are not two units either side of P")
        grad = sp.Rational(y2 - y1, x2 - x1)
        need(sp.Rational(y0 - y1, a - x1) == grad, "P is not on the line through the grid points")
        need(d.subs(CX, a) == grad, "the line through the grid points is not the tangent")
        need(grad != y0 and grad != sp.Rational(y0, a), "a slip gives the answer")
        gr = q["graph"]
        need(len(gr["curves"]) == 2, "the figure needs the curve and the tangent")
        E14GG_on(gr["curves"][0], f)
        need(E14GG_line(gr["curves"][1]) == (grad, y0 - grad * a), "the drawn line is not the tangent")
        need({(p["x"], p["y"]) for p in gr["points"]} == {(a, y0), (x1, y1), (x2, y2)}, "the figure's points")
        tagged = {E14GG_SK + "0": {dec_text(y0)}, E14GG_SK + "1": {dec_text(sp.Rational(y0, a))}, E14GG_T + "3": {dec_text(1 / grad)}}
        if grad < 0:
            tagged[E14GG_T + "4"] = {dec_text(-grad)}
        gc_check_common(q, dec_text(grad), tagged)
        E14GG_plain(q, {dec_text(grad + 1), dec_text(grad - 1)})
    elif u == "chord-table":
        m = re.fullmatch(r"Estimate the gradient of the curve y = f\(x\) at x = (\d+), using the chord from x = (\d+\.\d) to x = (\d+\.\d)\.", q["asked"])
        need(m is not None and L == [f"The table gives values of f(x) near x = {m.group(1)}."], f"can't read {q['asked']!r}")
        xa, lo, hi = int(m.group(1)), sp.Rational(m.group(2)), sp.Rational(m.group(3))
        need(xa == a and lo == a - sp.Rational(1, 10) and hi == a + sp.Rational(1, 10), "the chord is not a ± 0.1")
        need(int(g["deg"]) == 3 and sp.Rational(str(g["c"])).q == 1, "the clean limits")
        rows = q["table"]["rows"]
        need(rows[0] == ["x", [dec_text(lo), dec_text(a), dec_text(hi)]], "the table's x row")
        need(rows[1][0] == "f(x)" and rows[1][1] == [dec_text(f.subs(CX, v)) for v in (lo, a, hi)], "the table's f(x) row is not f")
        flo, fa, fhi = (E14GG_n(v) for v in rows[1][1])
        est = (fhi - flo) / (hi - lo)
        need(abs(est - d.subs(CX, a)) < sp.Rational(1, 10), "the chord is far from the tangent")
        gc_check_common(q, dec_text(est), {E14GG_SK + "0": {dec_text(fa)}, E14GG_T + "5": {dec_text((fhi - flo) / sp.Rational(1, 10))}})
        E14GG_plain(q, {dec_text(est + 1), dec_text(est - 1)})
    elif u == "compare-two":
        need(L == ["The graph shows the curve y = f(x), with the points A and B on it."]
             and q["asked"] == "At which point, A or B, is the gradient of the curve greater? Give a reason.", f"can't read {L}")
        gr = q["graph"]
        E14GG_on(gr["curves"][0], f)
        pts = {p["label"]: (sp.nsimplify(p["x"]), sp.nsimplify(p["y"], rational=True)) for p in gr["points"]}
        need(set(pts) == {"A", "B"}, "the figure's points")
        (xa, ya), (xb, yb) = pts["A"], pts["B"]
        need(xa.q == 1 and xb.q == 1 and xa != 0 and xb != 0 and f.subs(CX, xa) == ya and f.subs(CX, xb) == yb, "A or B is not on the curve")
        ga, gb = d.subs(CX, xa), d.subs(CX, xb)
        need(abs(ga) >= 1 and abs(gb) >= 1 and abs(ga - gb) >= sp.Rational(3, 2), "the gradients are not clearly apart")
        need((ga < gb) != (ya < yb), "the heights are in the same order as the gradients")
        big, small = ("A", "B") if ga > gb else ("B", "A")
        high = "A" if ya > yb else "B"
        steep = "A" if ya / xa > yb / xb else "B"
        need(ya / xa != yb / xb, "the lines from the origin have one gradient")
        if (ga > 0) != (gb > 0):
            right = f"{big}, because the curve rises at {big} and falls at {small}"
        elif ga > 0:
            right = f"{big}, because the curve rises more steeply at {big} than at {small}"
        else:
            right = f"{big}, because the curve falls less steeply at {big} than at {small}"
        tagged = {E14GG_SK + "0": {f"{high}, because {high} is higher up the curve"},
                  E14GG_SK + "1": {f"{steep}, because the line from the origin to {steep} has the greater gradient"}}
        if ga < 0 and gb < 0:
            tagged[E14GG_SK + "2"] = {f"{small}, because the curve falls more steeply at {small}"}
        gc_check_common(q, right, tagged)
        E14GG_plain(q, {"Neither: the gradients at A and B are equal"})
    else:
        need(q["format"] == "pick-the-graph", f"format {q['format']}")
        m = re.fullmatch(rf"The graph shows the curve y = f\(x\) and the point P{E14GG_PT} on it\.", L[0])
        need(m is not None and len(L) == 1 and q["asked"] == "Which graph shows the tangent to the curve at P?", f"can't read {L}")
        need((int(m.group(1).replace("−", "-")), int(m.group(2).replace("−", "-"))) == (a, y0), "P is not the curve's point")
        want = {"": d.subs(CX, a), "origin": sp.Rational(y0, a), "height": sp.Integer(y0), "chord": (f.subs(CX, a + 2) - y0) / 2}
        refs = {"": "", "origin": E14GG_SK + "1", "height": E14GG_SK + "0", "chord": E14GG_T + "6"}
        need(len(set(want.values())) == 4, "two cards show the same line")
        ch, graphs = q["choices"], q["graphs"]
        need(len(ch) == 4 and len(graphs) == 4 and sum(o["correct"] for o in ch) == 1, "four cards, one right")
        seen = set()
        for o, card in zip(ch, graphs):
            need(o["text"] == "Graph " + "ABCD"[ch.index(o)], f"card {o['text']!r}")
            mk = "" if o["correct"] else o["mistake"]
            need(mk in want and mk not in seen and o["ref"] == refs[mk], f"{o['text']}: mistake {mk!r}, ref {o['ref']!r}")
            seen.add(mk)
            need(len(card["curves"]) == 2, f"{o['text']}: the curve and one line")
            E14GG_on(card["curves"][0], f)
            grad, icpt = E14GG_line(card["curves"][1])
            need(grad == want[mk] and icpt == y0 - want[mk] * a, f"{o['text']}: the line is not the {mk or 'tangent'} through P")
            if o["correct"]:
                need(q["answer_text"] == o["text"], "the answer is not the tangent's card")
        need(any(q["answer_text"] in st for st in q["solutions"][0]["steps"][-1:]), "the working doesn't end on the answer")
    return None, None


SITUATION_CHECKS["gradient-from-graph"] = E14GG_check

# ── end gradient-from-graph ──


# ── rate-of-rate (FAL-777) ───────────────────────────────────
# t5-ext-interpret-second-derivative. The signs of the first and second derivatives are read back
# from the question: from the signs it states, from its sentence, from the cubic model (SymPy
# differentiates it), or from the drawn curve (every sampled point is held to the cubic). The
# direction is the sign of f′ and the speed grows when f′ and f″ agree; each slip is rebuilt.

E14RR_SK = "SL5.7.interpret-second-derivative#"
E14RR_T = "t5-ext-interpret-second-derivative#"
# name -> (letter, up, down)
E14RR_STORIES = {"number of rats in a bunker": ("N", "increasing", "decreasing"),
                 "temperature of a reactor's coolant": ("T", "rising", "falling"),
                 "water level in a tank": ("L", "rising", "falling"),
                 "price of fuel": ("P", "rising", "falling"),
                 "volume of water in a reservoir": ("V", "increasing", "decreasing"),
                 "height of a weather balloon": ("H", "rising", "falling"),
                 "amount of dust in the air": ("A", "increasing", "decreasing"),
                 "radiation level in a crater": ("R", "rising", "falling")}


def E14RR_sentence(name, d, faster):
    _, up, down = E14RR_STORIES[name]
    w = up if d > 0 else down
    return f"The {name} is {w} more and more quickly." if faster else f"The {name} is {w}, but more and more slowly."


def E14RR_signs(q, s1, s2, at="t"):
    c = lambda v: "> 0" if v > 0 else "< 0"
    return f"{q}′({at}) {c(s1)} and {q}″({at}) {c(s2)}"


def E14RR_sentences(name, s1, s2):
    """The right sentence, the slips and the plain fillers."""
    _, up, down = E14RR_STORIES[name]
    right = E14RR_sentence(name, s1, s1 * s2 > 0)
    tagged = {}
    if s1 != s2:
        tagged[E14RR_SK + "0"] = {f"The {name} is {up if s2 > 0 else down}."}
        tagged[E14RR_T + "2"] = {E14RR_sentence(name, s2, s1 * s2 > 0)}
    if s1 < 0:
        tagged[E14RR_T + "3"] = {E14RR_sentence(name, s1, s2 > 0)}
    plain = {E14RR_sentence(name, d, f) for d in (1, -1) for f in (True, False)} | {f"The {name} is not changing."}
    return right, tagged, plain


def E14RR_cubic(text):
    return sp.Poly(E13_expr(text.replace("t", "x")), CX)


def E14RR_clear(f, t0):
    """The moment is clear of the turning points and the point of inflexion, and f stays in (0, 150]."""
    d1, d2 = f.diff(CX), f.diff(CX).diff(CX)
    need(abs(d1.eval(t0)) >= 2 and abs(d2.eval(t0)) >= 2, "the signs are too faint to read")
    for r in sp.real_roots(d1) + sp.real_roots(d2):
        need(abs(r - t0) >= 1, f"t = {t0} is within 1 of a turning point or the point of inflexion")
    need(all(0 < f.eval(t) <= 150 for t in range(7)), "the quantity leaves (0, 150]")
    return int(sp.sign(d1.eval(t0))), int(sp.sign(d2.eval(t0)))


def E14RR_plain(q, plain):
    for o in q["choices"]:
        need(o["correct"] or o["ref"] or o["text"] in plain, f"the checker can't say why {o['text']!r} is wrong")


def E14RR_check(q):
    u, L, asked = q["view"]["unknown"], q["lines"], q["asked"]
    need(q["paper"] == 1, f"Paper {q['paper']}")
    if u == "sentence-from-signs":
        m = re.fullmatch(r"([A-Z])\(t\) is the (.+), t hours after midnight\.", L[0])
        m2 = re.fullmatch(r"For (\d) < t < (\d+), ([A-Z])′\(t\) ([<>]) 0 and ([A-Z])″\(t\) ([<>]) 0\.", L[1])
        need(m and m2 and len(L) == 2 and m.group(2) in E14RR_STORIES, f"can't read {L}")
        name = m.group(2)
        need(m.group(1) == m2.group(3) == m2.group(5) == E14RR_STORIES[name][0], "the letter")
        need(asked == f"Which sentence describes the {name} for {m2.group(1)} < t < {m2.group(2)}?", f"asked {asked!r}")
        s1, s2 = (1 if m2.group(4) == ">" else -1), (1 if m2.group(6) == ">" else -1)
        right, tagged, plain = E14RR_sentences(name, s1, s2)
    elif u == "signs-from-sentence":
        m = re.fullmatch(r"([A-Z])\(t\) is the (.+), t hours after midnight\. For (\d) < t < (\d+):", L[0])
        need(m and len(L) == 2 and m.group(2) in E14RR_STORIES and asked == f"Which is true for {m.group(3)} < t < {m.group(4)}?", f"can't read {L}")
        name, letter = m.group(2), m.group(1)
        need(letter == E14RR_STORIES[name][0], "the letter")
        _, up, down = E14RR_STORIES[name]
        rate_words = L[1] == f"The {name} is {up} at a decreasing rate."
        if rate_words:
            s1, s2 = 1, -1
        else:
            pairs = [(d, sp_) for d in (1, -1) for sp_ in (1, -1) if E14RR_sentence(name, d, d * sp_ > 0) == L[1]]
            need(len(pairs) == 1, f"can't read the sentence {L[1]!r}")
            s1, s2 = pairs[0]
        right = E14RR_signs(letter, s1, s2)
        tagged = {}
        if rate_words:
            tagged[E14RR_SK + "1"] = {E14RR_signs(letter, -1, -1)}
        if s1 != s2:
            tagged[E14RR_T + "2"] = {E14RR_signs(letter, s2, s1)}
        if s1 < 0:
            tagged[E14RR_T + "3"] = {E14RR_signs(letter, -1, -s2)}
        plain = {E14RR_signs(letter, a, b) for a in (1, -1) for b in (1, -1)}
    elif u == "from-model":
        m = re.fullmatch(r"The (.+) t hours after midnight is modelled by ([A-Z])\(t\) = (.+), for 0 ≤ t ≤ 6\.", L[0])
        need(m and len(L) == 1 and m.group(1) in E14RR_STORIES and m.group(2) == E14RR_STORIES[m.group(1)][0], f"can't read {L}")
        name, letter = m.group(1), m.group(2)
        m2 = re.fullmatch(rf"Use {letter}′\((\d)\) and {letter}″\((\d)\) to describe the {re.escape(name)} at t = (\d)\.", asked)
        need(m2 and m2.group(1) == m2.group(2) == m2.group(3), f"asked {asked!r}")
        t0 = int(m2.group(1))
        f = E14RR_cubic(m.group(3))
        need(f.degree() == 3, "not a cubic")
        s1, s2 = E14RR_clear(f, t0)
        right, tagged, plain = E14RR_sentences(name, s1, s2)
        st = q["solutions"][0]["steps"]
        need(f"{letter}′({t0}) = {frac_text(f.diff(CX).eval(t0))} " in st[0] and f"{letter}″({t0}) = {frac_text(f.diff(CX).diff(CX).eval(t0))} " in st[1], "the working's h′(t₀) or h″(t₀)")
    else:
        m = re.fullmatch(r"The graph shows ([A-Z])\(t\), the (.+), t hours after midnight\. The point where t = (\d) is marked\.", L[0])
        need(m and len(L) == 1 and m.group(2) in E14RR_STORIES and m.group(1) == E14RR_STORIES[m.group(2)][0], f"can't read {L}")
        name, t0 = m.group(2), int(m.group(3))
        need(asked == f"Which sentence describes the {name} at t = {t0}?", f"asked {asked!r}")
        c = q["given"]["c"]
        f = sp.Poly([int(v) for v in c], CX)
        gr = q["graph"]
        fl = sp.lambdify(CX, f.as_expr())
        need(len(gr["curves"]) == 1 and len(gr["curves"][0]) > 10, "the figure's curve")
        for x, y in gr["curves"][0]:
            need(abs(fl(x) - y) < 1e-6, f"the drawn curve leaves the model at t = {x}")
        need(gr["curves"][0][0][0] == 0 and gr["curves"][0][-1][0] == 6, "the curve runs for 0 ≤ t ≤ 6")
        need(len(gr["points"]) == 1 and gr["points"][0]["x"] == t0 and abs(gr["points"][0]["y"] - fl(t0)) < 1e-9, "the marked point")
        s1, s2 = E14RR_clear(f, t0)
        right, tagged, plain = E14RR_sentences(name, s1, s2)
    gc_check_common(q, right, tagged)
    E14RR_plain(q, plain)
    for sol in q["solutions"]:
        need(sol["steps"][-1].rstrip(".") == right.rstrip("."), f"{sol['name']}: the last step is not the answer")
    return None, None


SITUATION_CHECKS["rate-of-rate"] = E14RR_check

# ── end rate-of-rate ──


# ── variable-kind (t4-ext-data-type, FAL-778) ────────────────
# Each variable is classified here from its own words: "the number of" is a count, a size, price,
# cost or score goes up in fixed steps, and a mass, time, length, volume, temperature, distance or
# height is measured, recorded "to the nearest" unit or not. Each claim offered is then judged true
# or false of that variable, so exactly one must be true, and it must be the one marked right.

E15DT_SK = "SL4.1.data-type#"
E15DT_T = "t4-ext-data-type#"
E15DT_CLAIMS = {
    "Discrete: it is counted, so it takes separate values with gaps between them.": lambda how: how == "counted",
    "Discrete: it goes up in fixed steps, with no values in between.": lambda how: how in ("counted", "stepped"),
    "Continuous: it is measured, so it can take any value in a range.": lambda how: how in ("measured", "rounded"),
    "Continuous: it is measured, so it can take any value in a range; rounding only changes how it is written.": lambda how: how in ("measured", "rounded"),
    "Continuous: its values have decimals.": lambda how: False,
    "Discrete: its values are whole numbers.": lambda how: False,
    "Continuous: an average of it can be a decimal.": lambda how: False,
    "Discrete: only a few separate values were recorded.": lambda how: False,
    "Discrete: it is measured, so it can only take whole values.": lambda how: False,
    "Continuous: it is counted, so it can take any value.": lambda how: False,
}
E15DT_ASKED = {"classify-variable": ("counted", "measured"), "decimal-but-discrete": ("stepped",), "rounded-but-continuous": ("rounded",)}


def E15DT_how(what):
    if what.startswith("the number of "):
        return "counted"
    if re.search(r"\b(shoe size|price|cost|score)\b", what):
        return "stepped"
    if re.search(r"\b(mass|time|length|volume|temperature|distance|height)\b", what):
        return "rounded" if "to the nearest" in what else "measured"
    raise Fail(f"can't tell how {what!r} is found")


def E15DT_table(q, what, how):
    rows = q["table"]["rows"]
    need(len(rows) == 1 and len(rows[0][1]) >= 5, "the table is not one row of values")
    vals = rows[0][1]
    need(len(set(vals)) == len(vals), "two values in the table are the same")
    for t in vals:
        x = sp.Rational(t)
        if how == "stepped":
            if "dollars and cents" in what:
                need(re.fullmatch(r"\d+\.\d\d", t) is not None, f"{t} is not dollars and cents")
            else:
                need((x * 2).q == 1 and re.fullmatch(r"\d+(\.5)?", t) is not None, f"{t} is not a whole or half step")
        elif how == "rounded":
            need(x.q == 1 and re.fullmatch(r"\d+", t), f"{t} is not a whole number")


def E15DT_check(q):
    u, L, ch = q["view"]["unknown"], q["lines"], q["choices"]
    if u in E15DT_ASKED:
        m = re.fullmatch(r"A study records (.+?)\.( Some of its values are in the table\.)?", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        what, how = m.group(1), E15DT_how(m.group(1))
        need(how in E15DT_ASKED[u], f"{u} asks about a variable that is {how}")
        need((q["table"] is not None) == (q["view"]["rep"] == "table") == bool(m.group(2)), "the table is not where the view puts it")
        if q["table"] is not None:
            E15DT_table(q, what, how)
        need(q["asked"] == "Is this variable discrete or continuous?", f"asked {q['asked']!r}")
        for o in ch:
            need(o["text"] in E15DT_CLAIMS, f"{o['text']!r} is not a known claim")
        true = [o["text"] for o in ch if E15DT_CLAIMS[o["text"]](how)]
        need(len(true) == 1, f"{len(true)} true claims for a variable that is {how}")
        want = true[0]
        wrongs = {E15DT_SK + "0": {"Continuous: its values have decimals."}, E15DT_SK + "1": {"Discrete: its values are whole numbers."},
                  E15DT_T + "2": {"Continuous: an average of it can be a decimal."} if how == "counted" else set(),
                  E15DT_T + "3": {"Discrete: only a few separate values were recorded."} if how == "measured" else set()}
        need(how != "stepped" or any(o["ref"] == E15DT_SK + "0" for o in ch), "a stepped variable without the decimals slip")
    else:
        kind = "continuous" if u == "which-continuous" else "discrete"
        need(q["asked"] == f"Which of these variables is {kind}?" and L[0] == "A study records four variables:", f"can't read {q['asked']!r}")
        listed = [re.fullmatch(r"(.+)\.", t).group(1) for t in L[1:5]]
        hows = {w: E15DT_how(w[0].lower() + w[1:]) for w in listed}
        of_kind = [w for w in listed if (hows[w] in ("measured", "rounded")) == (kind == "continuous")]
        need(len(of_kind) == 1, f"{len(of_kind)} {kind} variables among four")
        need(sorted(o["text"] for o in ch) == sorted(w + "." for w in listed), "the options are not the four variables")
        want = of_kind[0] + "."
        trap = "stepped" if kind == "continuous" else "rounded"
        wrongs = {E15DT_SK + ("0" if kind == "continuous" else "1"): {w + "." for w in listed if hows[w] == trap}}
    gc_check_common(q, want, wrongs)
    for sol in q["solutions"]:
        for st in sol["steps"]:
            if (m := re.search(r"between (.+?) and (.+?)(?:, however| can occur|: the|\.$)", st)):
                need(m.group(1) != m.group(2), f"{sol['name']}: {st!r}")
    return None, None


SITUATION_CHECKS["variable-kind"] = E15DT_check

# ── end variable-kind ──


# ── study (t4-ext-population-sample, FAL-778) ────────────────
# The population is read from the first line (everyone the study is about), the sample from the
# last (the people actually asked), and how they were chosen from the verbs of the last line, with
# the stories' own copy in SM_CTX. Random means a numbered draw from everyone; the right claim is
# written here from that, and each tagged option is rebuilt from its slip.

E15PS_SK = "SL4.1.population-sample#"
E15PS_T = "t4-ext-population-sample#"


def E15PS_read(q):
    L = q["lines"]
    c = next((c for c in SM_CTX if re.fullmatch(rf"The {c[1]} has \d+ {c[0]}\.", L[0])), None)
    need(c is not None, f"can't read {L[0]!r}")
    who, place, names, spot, lst, topic = c
    N = int(re.fullmatch(rf"The {place} has (\d+) {who}\.", L[0]).group(1))
    need(L[1] == f"A surveyor wants to learn {topic}.", f"can't read {L[1]!r}")
    if (m := re.fullmatch(rf"She numbers everyone on {lst}, draws (\d+) of the numbers at random and asks those (\d+) {who}\.", L[2])):
        need(m.group(1) == m.group(2), "she asks a different number from the draw")
        how, n, g = "draw", int(m.group(1)), None
    elif (m := re.fullmatch(rf"She stands {spot} and asks the first (\d+) {who} who come by\.", L[2])):
        how, n, g = "spot", int(m.group(1)), None
    elif (m := re.fullmatch(rf"She pins up a notice {spot} and asks the first (\d+) {who} who reply\.", L[2])):
        how, n, g = "volunteer", int(m.group(1)), None
    elif (m := re.fullmatch(rf"She draws (\d+) of the (.+) at random from {lst} and asks only them\.", L[2])):
        need(m.group(2) in names, f"{m.group(2)!r} is not a group of the {place}")
        how, n, g = "group", int(m.group(1)), m.group(2)
    else:
        raise Fail(f"can't read how the sample was chosen: {L[2]!r}")
    need(0 < 4 * n < N, f"a sample of {n} from {N}")
    return c, N, n, how, g


def E15PS_check(q):
    u, ch = q["view"]["unknown"], q["choices"]
    (who, place, names, spot, lst, topic), N, n, how, g = E15PS_read(q)
    everyone, asked = f"All {N} {who} in the {place}.", f"The {n} {who} she asked."
    for o in ch:
        need(not (o["text"].startswith("Only the ") and o["text"][9:].split(" in the ")[0] == g), f"{o['text']!r} is the sampled group")
    if u == "name-population":
        need(q["asked"] == "What is the population in this study?", f"asked {q['asked']!r}")
        want, wrongs = everyone, {E15PS_SK + "0": {asked}}
    elif u == "name-sample":
        need(q["asked"] == "What is the sample in this study?", f"asked {q['asked']!r}")
        want, wrongs = asked, {E15PS_T + "2": {everyone}}
    elif u == "is-random":
        need(q["asked"] == "Is the sample random? Give a reason.", f"asked {q['asked']!r}")
        want = {"draw": f"Yes: everyone on {lst} had the same chance of being chosen.",
                "spot": f"No: anyone who doesn't come by {spot} had no chance of being chosen.",
                "volunteer": "No: only people who choose to reply could be in the sample.",
                "group": f"No: only the {g} could be chosen, so the other {who} had no chance."}[how]
        for o in ch:
            need(o["correct"] or o["text"].startswith("Yes" if how != "draw" else "No"), f"{o['text']!r} gives the right verdict but is marked wrong")
        wrongs = {E15PS_SK + "1": {"Yes: whoever comes by is chosen by chance."} if how == "spot" else set(),
                  E15PS_T + "3": {f"Yes: {n} people is enough to make it random."} if how != "draw" else set()}
    else:
        need(how != "draw", "the sample is random already")
        need(q["asked"] == "Which change would make this a random sample?", f"asked {q['asked']!r}")
        want = f"Number everyone on {lst} and draw {n} of the numbers at random."
        wrongs = {E15PS_T + "3": {f"Keep the same method and ask {2 * n} {who} instead."},
                  E15PS_SK + "1": {f"Stand {spot} at a different time and ask the first {n} {who} who come by."}}
        for o in ch:
            need(o["correct"] or "at random" not in o["text"] or o["text"].startswith("Ask only the "), f"{o['text']!r} is a random draw from everyone")
    gc_check_common(q, want, wrongs)
    return None, None


SITUATION_CHECKS["study"] = E15PS_check

# ── end study ──


# ── stratified-sample (t4-ext-stratified-numbers, FAL-778) ────
# The groups are read from the sentence or the table, the sample size from the sentence or the
# table's total, and each answer is worked out again with exact fractions: G × n ÷ N, rounded to
# the nearest whole number where asked, n − r₁ − r₂ for the last group, q × N ÷ G backwards, and
# p% of n. Every tagged option is rebuilt from its slip, every sum in the working is redone, and an
# error-spot's lines are judged one by one.

E15SN_SK = "SL4.1.stratified-numbers#"
E15SN_T = "t4-ext-stratified-numbers#"


def E15SN_round(x):
    x = sp.Rational(x)
    return int(sp.floor(x + sp.Rational(1, 2)))


def E15SN_ctx(line):
    for c in SM_CTX:
        if re.match(rf"(A {c[1]} has \d+ {c[0]}:|The table shows the \d+ {c[0]} in a {c[1]}, by group\.|The {c[0]} of a {c[1]} are )", line):
            return c
    raise Fail(f"can't read {line!r}")


def E15SN_read(q):
    """{'c', 'G', 'N', 'n', 'col', 'g', 'p'}: the groups, the sample size and the sample column."""
    L, u = q["lines"], q["view"]["unknown"]
    c = E15SN_ctx(L[0])
    who, place, names = c[0], c[1], c[2]
    out = {"c": c, "G": None, "N": None, "n": None, "col": None, "g": None, "p": None}
    if u == "stratum-from-percent":
        m = re.fullmatch(rf"The {who} of a {place} are (\d+)% {names[0]}, (\d+)% {names[1]} and (\d+)% {names[2]}\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        out["p"] = [int(m.group(i)) for i in (1, 2, 3)]
        need(sum(out["p"]) == 100 and len(set(out["p"])) == 3, "the percentages don't add to 100")
    elif q["table"] is not None:
        rows = q["table"]["rows"]
        need(rows[0] == ["group", ["number", "in sample"]] and [r[0] for r in rows[1:4]] == list(names) and rows[4][0] == "Total", "table heads")
        out["G"] = [int(r[1][0]) for r in rows[1:4]]
        out["N"] = int(rows[4][1][0])
        need(sum(out["G"]) == out["N"], "the table's groups don't add to its total")
        out["col"] = [r[1][1] for r in rows[1:5]]
        need(L[0] == f"The table shows the {out['N']} {who} in a {place}, by group.", f"can't read {L[0]!r}")
        if out["col"][3] not in ("?", ""):
            out["n"] = int(out["col"][3])
    else:
        out["N"], out["G"] = sm_camp(L[0], c)
    need(out["G"] is None or len(set(out["G"])) == 3, "two groups are the same size")
    if u in ("stratum-count", "stratum-count-rounded", "stratum-from-percent") and q["table"] is None:
        m = re.fullmatch(rf"A stratified sample of (\d+) {who} is taken, by group\.", L[1])
        need(m is not None, f"can't read {L[1]!r}")
        out["n"] = int(m.group(1))
    m = re.search(r"Find how many (.+?) (?:go in the sample|she must take)", q["asked"])
    if m:
        out["g"] = names.index(m.group(1))
    return out


def E15SN_steps(q, d):
    """Every sum the working writes."""
    for sol in q["solutions"]:
        for st in sol["steps"]:
            for a, b, c, x, r in re.findall(r"(\d+)/(\d+) × (\d+) = ([\d.]+)(?: \(to 2 d\.p\.\))?(?:, which rounds to (\d+))?", st) + \
                    [(a, c, b, x, r) for a, b, c, x, r in re.findall(r"(\d+) × (\d+)/(\d+) = ([\d.]+)(?: \(to 2 d\.p\.\))?(?:, which rounds to (\d+))?", st)]:
                v = sp.Rational(int(a), int(b)) * int(c)
                need(abs(v - sp.Rational(x)) <= sp.Rational(1, 200), f"{sol['name']}: {st!r}")
                need(not r or E15SN_round(v) == int(r), f"{sol['name']}: {st!r} rounds wrong")
            for a, b, c, w in re.findall(r"(\d+) − (\d+) − (\d+) = (\d+)", st):
                need(int(a) - int(b) - int(c) == int(w), f"{sol['name']}: {st!r}")
            if (m := re.fullmatch(r"Check: the groups give (\d+), (\d+) and (\d+), which add to (\d+)\.", st)):
                got = [int(m.group(i)) for i in (1, 2, 3)]
                need(got == [E15SN_round(sp.Rational(G * d["n"], d["N"])) for G in d["G"]] and sum(got) == int(m.group(4)), f"{sol['name']}: {st!r}")


def E15SN_check(q):
    u = q["view"]["unknown"]
    d = E15SN_read(q)
    G, N, n, g, names = d["G"], d["N"], d["n"], d["g"], d["c"][2]
    third = E15SN_round(sp.Rational(n, 3)) if n else None
    if u == "stratum-count":
        need(n is not None and all((Gi * n) % N == 0 for Gi in G), "not every share is whole")
        v = G[g] * n // N
        need(10 <= n <= (40 if q["paper"] == 1 else 120) and max(G) <= (400 if q["paper"] == 1 else 3000), f"n = {n}, groups {G} outside the limits")
        wrongs = {E15SN_SK + "0": {f"number = {third}"} - {f"number = {v}"}}
    elif u == "stratum-count-rounded":
        x = sp.Rational(G[g] * n, N)
        need(abs(x - sp.floor(x) - sp.Rational(1, 2)) >= sp.Rational(1, 10), f"the share {float(x)} is within 0.1 of a half")
        v = E15SN_round(x)
        need(v != third, "the equal split is the answer")
        wrongs = {E15SN_SK + "0": {f"number = {third}"}, E15SN_T + "2": {f"number = {int(sp.floor(x))}"} - {f"number = {v}"}}
    elif u == "last-stratum":
        m = re.fullmatch(rf"A surveyor takes a stratified sample of (\d+)\. She has rounded the {names[0]} and the {names[1]} to the nearest whole number\.", q["lines"][1])
        need(m is not None and int(m.group(1)) == n, f"can't read {q['lines'][1]!r}")
        r = [E15SN_round(sp.Rational(Gi * n, N)) for Gi in G]
        need(d["col"][:3] == [str(r[0]), str(r[1]), "?"], "the table's rounded numbers are wrong")
        need(sum(r) != n, "the rounded shares already add to the sample")
        need(all(abs(sp.Rational(Gi * n, N) - sp.floor(sp.Rational(Gi * n, N)) - sp.Rational(1, 2)) >= sp.Rational(1, 10) for Gi in G), "a share is within 0.1 of a half")
        need(g == 2, "the asked group is not the third")
        v = n - r[0] - r[1]
        need(v > 0, "nothing left for the third group")
        wrongs = {E15SN_SK + "1": {f"number = {r[2]}"}}
    elif u == "sample-size-from-stratum":
        m = re.fullmatch(r"In a stratified sample, (\d+) (.+) are chosen\.", q["lines"][1])
        need(m is not None, f"can't read {q['lines'][1]!r}")
        qg, i = int(m.group(1)), names.index(m.group(2))
        need(d["col"] is None or (d["col"][i] == str(qg) and d["col"][3] == "?"), "the table's sample column is wrong")
        nn = sp.Rational(qg * N, G[i])
        need(nn.q == 1 and all(sp.Rational(Gi * nn, N).q == 1 for Gi in G), "the sample size isn't whole, or a share isn't")
        n = v = int(nn)
        wrongs = {E15SN_SK + "0": {f"sample size = {3 * qg}"} - {f"sample size = {v}"}}
    else:
        p = d["p"]
        need((p[g] * n) % 100 == 0 and n != 100, f"{p[g]}% of {n}")
        v = p[g] * n // 100
        need(v != third, "the equal split is the answer")
        wrongs = {E15SN_T + "3": {f"number = {p[g]}"}, E15SN_SK + "0": {f"number = {third}"}}
    label = "sample size = " if u == "sample-size-from-stratum" else "number = "
    gc_check_common(q, f"{label}{v}", wrongs)
    if G is not None:
        E15SN_steps(q, dict(d, n=n))
    return None, None


def E15SN_spot(q, lines):
    d = E15SN_read(q)
    G, N, n, g, names = d["G"], d["N"], d["n"], d["g"], d["c"][2]
    x = sp.Rational(G[g] * n, N)
    v = E15SN_round(x)
    name = names[g]
    for i, t in enumerate(lines):
        if (m := re.fullmatch(r"The groups add to (\d+): (\d+) \+ (\d+) \+ (\d+)\.", t)):
            ok = [int(m.group(k)) for k in (2, 3, 4)] == G and int(m.group(1)) == N
        elif t == "Each group's share is 1/3.":
            ok = False
        elif (m := re.fullmatch(r"The (.+?)'s? share is (\d+)/(\d+)\.", t)):
            ok = m.group(1) == name and sp.Rational(int(m.group(2)), int(m.group(3))) == sp.Rational(G[g], N)
        elif (m := re.fullmatch(r"(\d+)/(\d+) × (\d+) = ([\d.]+)(?: \(to 2 d\.p\.\))?(?:, which rounds to (\d+))?", t)):
            share = sp.Rational(int(m.group(1)), int(m.group(2)))
            got = share * int(m.group(3))
            ok = share == sp.Rational(G[g], N) and int(m.group(3)) == n and abs(got - sp.Rational(m.group(4))) <= sp.Rational(1, 200) \
                and (m.group(5) is None or E15SN_round(got) == int(m.group(5)))
        elif (m := re.fullmatch(rf"So (\d+) {re.escape(name)} go in the sample\.", t)):
            ok = int(m.group(1)) == v
        else:
            raise Fail(f"can't judge the line {t!r}")
        if not ok:
            return i
    return None


SITUATION_CHECKS["stratified-sample"] = E15SN_check
SPOT_CHECKS["stratified-sample"] = E15SN_spot

# ── end stratified-sample ──


# ── histogram (t4-ext-frequency-histogram, FAL-778) ──────────
# The data is read back from what the student sees: the table's rows, or the histogram's bars (each
# shaded strip's edges and height, which must touch, share one width and match their outlines).
# Every count is added up again from that, each class boundary goes in the class it starts, and
# each wrong histogram card is compared bar by bar with the data to find its one change.

E15FH_SK = "SL4.2.frequency-histogram#"
E15FH_T = "t4-ext-frequency-histogram#"
E15FH_STORIES = {"the time each driver takes to change a wheel": ("drivers", "t", "minutes", (5, 10)),
                 "the mass of each salvaged battery": ("batteries", "m", "kg", (5, 10)),
                 "the length of each salvaged pipe": ("pipes", "l", "cm", (10, 20)),
                 "the distance each courier rides in a day": ("couriers", "d", "km", (10, 20)),
                 "the time each runner takes to cross the dunes": ("runners", "t", "minutes", (10, 20))}


def E15FH_dec(r):
    r = sp.Rational(r)
    if r.q == 1:
        return str(r.p)
    s = f"{float(r):.6f}".rstrip("0")
    need(sp.Rational(s) == r, f"{r} doesn't end")
    return s


def E15FH_bars(g, card=False):
    """[(left, right, height)] from a histogram's shaded strips, checked against its outlines."""
    bars = []
    for reg, cur in zip(g["shade"], g["curves"]):
        need(len(reg) == 2 and reg[0][1] == 0 and reg[1][1] == 0 and reg[0][2] == reg[1][2], "a bar is not a rectangle from 0")
        l, r, h = sp.Rational(str(reg[0][0])), sp.Rational(str(reg[1][0])), sp.Rational(str(reg[0][2]))
        need([[float(l), 0.0], [float(l), float(h)], [float(r), float(h)], [float(r), 0.0]] == [[float(a), float(b)] for a, b in cur], "a bar's outline is not its shading")
        need(h.q == 1 and h > 0, f"a bar's height {h} is not a whole frequency")
        bars.append((l, r, int(h)))
    need(len(g["shade"]) == len(g["curves"]), "outlines and bars don't match")
    need(g.get("y_name") == "f" and g["y0"] == 0 and g["y1"] > max(b[2] for b in bars), "the frequency axis")
    return bars


def E15FH_read(q):
    """(story, w, freqs with None for a hidden class, T or None)."""
    L = q["lines"]
    m = re.match(r"The (?:table|histogram) shows (.+?)(?:, for (\d+) (\w+))?(?: \((\w) in (\w+)\))?\.$", L[0])
    need(m is not None and m.group(1) in E15FH_STORIES, f"can't read {L[0]!r}")
    who, x, unit, widths = E15FH_STORIES[m.group(1)]
    need(m.group(3) in (None, who) and m.group(4) in (None, x) and m.group(5) in (None, unit), f"can't read {L[0]!r}")
    T = int(m.group(2)) if m.group(2) else None
    if q["table"] is not None:
        rows = q["table"]["rows"]
        need(rows[0] == [f"{x} ({unit})", ["frequency"]], "the table's head")
        f, w = [], None
        body = rows[1:]
        if body[-1][0] == "Total":
            T2 = int(body[-1][1][0])
            need(T is None or T == T2, "two totals")
            T, body = T2, body[:-1]
        for c, (lab, val) in enumerate(body):
            mm = re.fullmatch(rf"(\d+) ≤ {x} < (\d+)", lab)
            need(mm is not None, f"can't read the class {lab!r}")
            a, b = int(mm.group(1)), int(mm.group(2))
            w = w or b - a
            need(a == c * w and b - a == w, f"the class {lab!r} doesn't follow on with width {w}")
            f.append(None if val[0] == "?" else int(val[0]))
    else:
        g = q["graph"]
        bars = E15FH_bars(g)
        w = bars[0][1] - bars[0][0]
        k = int(sp.Rational(g["x1"]) / w)
        need([t[0] for t in g["x_ticks"]] == [float(c * w) for c in range(k + 1)] and [t[1] for t in g["x_ticks"]] == [str(c * w) for c in range(k + 1)], "the boundaries marked")
        need(g.get("x_name") == x, "the across axis")
        f = [None] * k
        for l, r, h in bars:
            need(r - l == w and (l / w).q == 1, "the bars aren't equal-width classes with no gaps")
            f[int(l / w)] = h
        hidden = [c for c in range(k) if f[c] is None]
        need(len(hidden) <= 1, "more than one bar missing")
        if hidden:
            mm = re.fullmatch(rf"The bar for (\d+) ≤ {x} < (\d+) is missing, and (\d+) {who} are measured in all\.", L[1])
            need(mm is not None and int(mm.group(1)) == hidden[0] * w, f"can't read {L[1]!r}")
            T = int(mm.group(3))
            qm = [p for p in g["points"] if p["label"] == "?"]
            need(len(qm) == 1 and qm[0].get("name") and abs(qm[0]["x"] - float((hidden[0] + sp.Rational(1, 2)) * w)) < 1e-9, "the missing bar isn't marked ?")
    need(int(w) in widths and 4 <= len(f) <= 6, f"width {w}, {len(f)} classes")
    known = [v for v in f if v is not None]
    need(all(2 <= v <= 24 for v in known), "a frequency outside 2 to 24")
    need(all(f[c] is None or f[c + 1] is None or f[c] != f[c + 1] for c in range(len(f) - 1)), "two neighbouring frequencies are the same")
    if T is not None and None not in f:
        need(T == sum(f), "the total isn't the frequencies added")
    return (who, x, unit), int(w), f, T


def E15FH_cls(x, w, c):
    return f"{c * w} ≤ {x} < {(c + 1) * w}"


def E15FH_check(q):
    u, ch, asked = q["view"]["unknown"], q["choices"], q["asked"]
    (who, x, unit), w, f, T = E15FH_read(q)
    k = len(f)
    if u == "missing-frequency":
        need(f.count(None) == 1 and T is not None, "no one hidden frequency with a total")
        i = f.index(None)
        known = sum(v for v in f if v is not None)
        p = T - known
        need(p >= 2, f"the missing frequency is {p}")
        need(asked == ("Find the missing frequency." if q["table"] is not None else f"Find the frequency of the class {E15FH_cls(x, w, i)}."), f"asked {asked!r}")
        gc_check_common(q, f"frequency = {p}", {E15FH_T + "4": {f"frequency = {known}"}})
        return None, None
    need(None not in f, "a frequency is hidden")
    T = sum(f)
    if u == "bar-height":
        m = re.fullmatch(rf"A histogram is drawn from this table\. Find the height of the bar for (\d+) ≤ {x} < (\d+)\.", asked)
        need(m is not None, f"asked {asked!r}")
        i = int(m.group(1)) // w
        gc_check_common(q, f"height = {f[i]}", {E15FH_T + "2": {f"height = {E15FH_dec(sp.Rational(f[i], w))}"}, E15FH_T + "3": {f"height = {sum(f[:i + 1])}"}})
    elif u == "count-in-range":
        m = re.fullmatch(rf"Find how many {who} have (\d+) ≤ {x} < (\d+)\.", asked)
        need(m is not None, f"asked {asked!r}")
        a, b = int(m.group(1)) // w, int(m.group(2)) // w
        need(int(m.group(1)) % w == 0 and int(m.group(2)) % w == 0 and 1 <= a and b - a >= 2 and b <= k, "the range is not two or more whole classes")
        gc_check_common(q, f"number = {sum(f[a:b])}", {E15FH_SK + "0": {f"number = {sum(f[a - 1:b])}"}})
    elif u == "count-at-least":
        m = re.fullmatch(rf"Find how many {who} have {x} ≥ (\d+)\.", asked)
        need(m is not None and int(m.group(1)) % w == 0, f"asked {asked!r}")
        j = int(m.group(1)) // w
        need(1 <= j <= k - 2, "the boundary leaves fewer than two classes above it")
        gc_check_common(q, f"number = {sum(f[j:])}", {E15FH_SK + "0": {f"number = {sum(f[j - 1:])}"}})
    elif u == "class-of-value":
        m = re.fullmatch(rf"One more of the {who} is measured: its value is exactly (\d+) {unit}\.", q["lines"][1])
        need(m is not None and int(m.group(1)) % w == 0 and 0 < int(m.group(1)) < k * w, f"can't read {q['lines'][1]!r}")
        j = int(m.group(1)) // w
        gc_check_common(q, E15FH_cls(x, w, j), {E15FH_SK + "0": {E15FH_cls(x, w, j - 1)}})
    elif u == "total-frequency":
        need(asked == f"Find how many {who} the histogram shows.", f"asked {asked!r}")
        gc_check_common(q, f"number = {T}", {E15FH_T + "5": {f"number = {k}"}})
    else:
        need(asked == "Which histogram shows the data in the table?", f"asked {asked!r}")
        rights, wr = [], defaultdict(set)
        for o, gr in zip(ch, q["graphs"]):
            need(gr.get("card"), "a histogram card is not drawn as a card")
            bars = E15FH_bars(gr)
            touching = all(r - l == w for l, r, h in bars) and [l for l, r, h in bars] == [c * w for c in range(k)]
            gaps = all(abs((l - c * w) - sp.Rational(3, 20) * w) < sp.Rational(1, 1000) and abs((c + 1) * w - r - sp.Rational(3, 20) * w) < sp.Rational(1, 1000) for c, (l, r, h) in enumerate(bars))
            hs = [h for l, r, h in bars]
            need(len(bars) == k and (touching or gaps), "a card's bars are not the classes")
            diff = [c for c in range(k) if hs[c] != f[c]]
            if touching and not diff:
                rights.append(o["text"])
            mk = o.get("mistake", "")
            if o["correct"]:
                continue
            if mk == "gaps":
                need(gaps and not diff, "the gaps card changes more than the gaps")
                wr[E15FH_SK + "1"].add(o["text"])
            elif mk == "swap":
                need(touching and len(diff) == 2 and diff[1] == diff[0] + 1 and hs[diff[0]] == f[diff[1]] and hs[diff[1]] == f[diff[0]], "the swap card doesn't swap two neighbours")
            elif mk == "height":
                need(touching and len(diff) == 1 and hs[diff[0]] == f[diff[0]] + 2, "the height card doesn't raise one bar by 2")
            else:
                raise Fail(f"unknown mistake {mk!r}")
        need(len(rights) == 1, f"{len(rights)} cards show the data")
        gc_check_common(q, rights[0], wr)
    return None, None


SITUATION_CHECKS["histogram"] = E15FH_check

# ── end histogram ──


# ── correlation (t4-ext-describe-correlation, FAL-778) ───────
# r is worked out exactly from the points the scatter draws (SymPy), and it must be the r the
# question shows, to 2 d.p. The description follows from r's sign and size by the bands: strong
# 0.85 to 0.98, moderate 0.5 to 0.72, weak 0.2 to 0.4, none up to 0.12; a curve is r up to 0.12
# with a least-squares parabola through the points giving R² of at least 0.85. Each scatter card
# is judged the same way, and each tagged option is rebuilt from its slip.

E15DC_SK = "SL4.4.describe-correlation#"
E15DC_T = "t4-ext-describe-correlation#"
E15DC_STORIES = [("the number of fans sold in a day", "the number of heatstroke cases that day", "days", 1, "the heat of the day"),
                 ("the number of water barrels a camp has", "the number of goats it keeps", "camps", 1, "the size of the camp"),
                 ("the number of guards at a market", "the number of thefts reported there", "markets", 1, "how busy the market is"),
                 ("the number of dust masks sold in a week", "the number of people out walking that week", "weeks", -1, "how bad the dust storms are"),
                 ("the number of radio towers in a settlement", "the number of traders there", "settlements", 1, "the size of the settlement"),
                 ("the hours a scavenger trains each week", "her score in the trials", "scavengers", 1, ""),
                 ("the age of a water pump in years", "the litres it pumps an hour", "pumps", -1, ""),
                 ("the distance a convoy travels", "the fuel left in its tanks", "convoys", -1, "")]
E15DC_BANDS = [("strong", 0.85, 0.98), ("moderate", 0.5, 0.72), ("weak", 0.2, 0.4), ("none", 0.0, 0.12)]


def E15DC_pts(g):
    need(not g["curves"] and g["x0"] == 0 and g["y0"] == 0, "a scatter has no curves and starts at 0")
    xs = [sp.Rational(str(p["x"])) for p in g["points"]]
    ys = [sp.Rational(str(p["y"])) for p in g["points"]]
    need(all(v.q == 1 for v in xs + ys) and all(0 < x < g["x1"] for x in xs) and all(0 < y < g["y1"] for y in ys), "a point is not whole or is off the window")
    need(len(set(xs)) == len(xs) and 10 <= len(xs) <= 14, "the x-values")
    return xs, ys


def E15DC_r(xs, ys):
    n = len(xs)
    mx, my = sum(xs) / n, sum(ys) / n
    sxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    sxx = sum((x - mx) ** 2 for x in xs)
    syy = sum((y - my) ** 2 for y in ys)
    return float(sxy / sp.sqrt(sxx * syy))


def E15DC_band(r):
    """(band, sign), with r and its 2 d.p. text both inside the band."""
    shown = abs(round(r, 2))
    for name, lo, hi in E15DC_BANDS:
        if lo <= abs(r) <= hi and lo <= shown <= hi:
            return name, (0 if name == "none" else (1 if r > 0 else -1))
    raise Fail(f"r = {r:.4f} is in no band")


def E15DC_curve(xs, ys):
    """R² of the least-squares parabola, and the sign of its x² coefficient."""
    A = sp.Matrix([[1, x, x * x] for x in xs])
    Y = sp.Matrix(ys)
    c = (A.T * A).solve(A.T * Y)
    my = sum(ys) / len(ys)
    res = sum((y - (c[0] + c[1] * x + c[2] * x * x)) ** 2 for x, y in zip(xs, ys))
    tot = sum((y - my) ** 2 for y in ys)
    return float(1 - res / tot), sp.sign(c[2])


def E15DC_rtext(r):
    v = round(r, 2)
    return f"r = {'−' if v < 0 else ''}{abs(v):.2f}"


def E15DC_desc(band, sign):
    if band == "none":
        return "No linear correlation"
    return f"{band.capitalize()} {'positive' if sign > 0 else 'negative'} correlation"


def E15DC_read(q):
    """(story, n, r from the points or None, r shown or None)."""
    L = q["lines"]
    for st in E15DC_STORIES:
        x, y, who = st[0], st[1], st[2]
        m1 = re.fullmatch(rf"For (\d+) {who}, x is {re.escape(x)} and y is {re.escape(y)}\.", L[0])
        m2 = re.fullmatch(rf"The scatter diagram shows {re.escape(x)} \(x\) and {re.escape(y)} \(y\) for (\d+) {who}(?:, with r = (−?[\d.]+))?\.", L[0])
        if m1 or m2:
            break
    else:
        raise Fail(f"can't read {L[0]!r}")
    n = int((m1 or m2).group(1))
    shown = None
    if m1:
        mr = re.fullmatch(r"r = (−?\d\.\d\d)\.", L[1])
        need(mr is not None, f"can't read {L[1]!r}")
        shown = float(mr.group(1).replace("−", "-"))
    elif m2.group(2):
        shown = float(m2.group(2).replace("−", "-"))
    r = None
    if q["graph"] is not None:
        xs, ys = E15DC_pts(q["graph"])
        need(len(xs) == n, "the scatter has another number of points")
        r = E15DC_r(xs, ys)
        need(shown is None or E15DC_rtext(r) == f"r = {'−' if shown < 0 else ''}{abs(shown):.2f}", f"the r shown is not the points' r {r:.4f}")
    return st, n, r, (shown if shown is not None else r)


def E15DC_check(q):
    u, ch = q["view"]["unknown"], q["choices"]
    if u == "strongest-r":
        L = q["lines"]
        need(L[0] == "Four sets of data give these values of r:", f"can't read {L[0]!r}")
        rs = [float(re.fullmatch(r"r = (−?\d\.\d\d)\.", t).group(1).replace("−", "-")) for t in L[1:5]]
        top = max(rs, key=abs)
        need(sorted(abs(v) for v in rs)[-2] <= abs(top) - 0.08 + 1e-9, "the strongest r is not clear")
        tag = {E15DC_rtext(max(rs))} if top < 0 else set()
        gc_check_common(q, E15DC_rtext(top), {E15DC_SK + "0": tag})
        return None, None
    st, n, r, shown = E15DC_read(q)
    x, y, who, sign, third = st
    if u == "describe-scatter":
        need(r is not None and q["asked"] == "Describe the correlation.", "no scatter")
        band, sg = E15DC_band(r)
        need(sg == 0 or sg == sign, "the story's direction is not the data's")
        wr = {E15DC_SK + "0": {"Weak negative correlation"} if band == "strong" and sg < 0 else set()}
        gc_check_common(q, E15DC_desc(band, sg), wr)
    elif u == "describe-r":
        band, sg = E15DC_band(shown)
        need(sg == 0 or sg == sign, "the story's direction is not r's")
        wr = {E15DC_SK + "0": {"Weak negative correlation"} if band == "strong" and sg < 0 else set(),
              E15DC_T + "3": {"Strong positive correlation"} if sg > 0 and band != "strong" else set()}
        gc_check_common(q, E15DC_desc(band, sg), wr)
    elif u == "causation":
        band, sg = E15DC_band(shown)
        need(band == "strong" and sg == sign and third, "a cause question needs strong correlation and a third thing")
        near = "1" if sg > 0 else "−1"
        gc_check_common(q, f"No: correlation alone doesn't show cause; both could follow {third}.",
                        {E15DC_SK + "1": {f"Yes: r is close to {near}, so a change in x causes the change in y.", "Yes: the points lie close to a straight line, so x causes y."}})
    elif u == "no-linear":
        need(r is not None, "no scatter")
        xs, ys = E15DC_pts(q["graph"])
        r2, lead = E15DC_curve(xs, ys)
        need(abs(r) <= 0.12 and abs(round(r, 2)) >= 0.01 and r2 >= 0.85, f"r = {r:.3f}, R² = {r2:.3f}: not a curve with r near 0")
        gc_check_common(q, "There is no linear correlation, but the points follow a curve, so x and y are related.", {E15DC_SK + "2": {"x and y are not related at all."}})
        for sol in q["solutions"]:
            for t in sol["steps"]:
                if (m := re.match(r"The points (rise and then fall|fall and then rise)", t)):
                    need((m.group(1) == "rise and then fall") == (lead < 0), f"{sol['name']}: the curve is the other way up")
    else:
        need(q["asked"] == "Which scatter diagram shows these data?", f"asked {q['asked']!r}")
        band, sg = E15DC_band(shown)
        need(band in ("strong", "moderate") and sg == sign, "a match-r needs a strong or moderate r of the story's sign")
        rights, wr = [], defaultdict(set)
        for o, gr in zip(ch, q["graphs"]):
            need(gr.get("card"), "a scatter card is not drawn as a card")
            xs, ys = E15DC_pts(gr)
            rc = E15DC_r(xs, ys)
            b, s2 = E15DC_band(rc)
            if E15DC_rtext(rc) == E15DC_rtext(shown):
                rights.append(o["text"])
            if o["correct"]:
                continue
            mk = o.get("mistake")
            want = {"sign": (band, -sg), "weak": ("weak", sg), "none": ("none", 0)}.get(mk)
            need(want == (b, s2), f"the {mk} card has {b} {s2}")
            if mk == "weak" and band == "strong" and sg < 0:
                wr[E15DC_SK + "0"].add(o["text"])
        need(len(rights) == 1, f"{len(rights)} cards have r {E15DC_rtext(shown)}")
        gc_check_common(q, rights[0], wr)
    return None, None


SITUATION_CHECKS["correlation"] = E15DC_check

# ── end correlation ──


# ── exact-triangle (t3-ext-exact-triangle, FAL-778) ──────────
# The triangle is read from the words, or from the drawing (its side labels and angle, with the
# drawn corners checked to fit them), or for a height from the sketch (the foot H on AB, the right
# angle there). Every answer is worked out again exactly with SymPy's sin and cos of the angle,
# never a table of exact values, and so is every tagged slip. Each "= …" chain in the working is
# evaluated piece by piece, and an error-spot's lines are judged the same way.

E15ET_SK = "SL3.5.exact-triangle#"
E15ET_T = "t3-ext-exact-triangle#"


def E15ET_val(t):
    """An exact value as the game writes it ("9√3/2", "½ × 4 × 12 × √2/2", "6 sin 30°"), or None."""
    s = t.strip().rstrip(".").replace(" cm²", "").replace(" cm", "")
    if not s or re.search(r"[A-Za-z]", re.sub(r"\b(sin|cos) \d+°", "", s)):
        return None
    s = s.replace("−", "-").replace("×", "*").replace("÷", "/").replace("½", "(1/2)")
    s = re.sub(r"\b(sin|cos) (\d+)°", lambda m: f"{m.group(1)}({m.group(2)}*pi/180)", s)
    s = re.sub(r"√\(([^()]*)\)", r"sqrt(\1)", s)
    s = re.sub(r"√(\d+)", r"sqrt(\1)", s)
    s = re.sub(r"(\d+)²", r"(\1**2)", s)
    try:
        v = parse_expr(s, transformations=TRANSFORMS, local_dict={"sqrt": sp.sqrt, "sin": sp.sin, "cos": sp.cos, "pi": sp.pi})
    except Exception:
        return None
    return sp.nsimplify(sp.simplify(v)) if v.free_symbols == set() else None


def E15ET_text(v):
    """m√r as the game writes it: "18√2", "√103", "5/9", "−1/4"."""
    v = sp.nsimplify(v)
    if v.is_Rational:
        return frac_text(v)
    m, rest = v.as_coeff_Mul()
    need(rest.is_Pow and rest.exp == sp.Rational(1, 2) and rest.base.is_Integer, f"{v} is not m√r")
    m, r = sp.Rational(m), int(rest.base)
    top = ("" if abs(m.p) == 1 else str(abs(m.p))) + f"√{r}"
    return ("−" if m < 0 else "") + top + ("" if m.q == 1 else f"/{m.q}")


def E15ET_rad(d):
    return sp.Integer(d) * sp.pi / 180


def E15ET_chains(q):
    for sol in q["solutions"]:
        for st in sol["steps"]:
            parts = [E15ET_val(p) for p in st.split(" = ")]
            for x, y in zip(parts, parts[1:]):
                if x is not None and y is not None:
                    need(sp.simplify(x - y) == 0, f"{sol['name']}: {st!r}")


def E15ET_read(q):
    """{'a', 'b', 'c', 'C', 'A', 'area'} from the words, the drawing or the sketch."""
    u, L = q["view"]["unknown"], q["lines"]
    g = {"a": None, "b": None, "c": None, "C": None, "A": None, "area": None}
    if u == "exact-height":
        sk = q["graph"]
        need(sk is not None and sk["kind"] == "sketch" and sk["right"] == ["H"], "no sketch with a right angle at H")
        P = {k: sp.Matrix([sp.nsimplify(v[0]), sp.nsimplify(v[1])]) for k, v in sk["pts"].items()}
        A_, B_, C_, H_ = (sk["pts"][k] for k in "ABCH")
        need(abs(H_[1]) < 1e-9 and abs(H_[0] - C_[0]) < 1e-9 and 0 < H_[0] < B_[0] and A_ == [0.0, 0.0], "H is not the foot of the height on AB")
        lab = {(ln["a"], ln["b"]): ln for ln in sk["lines"]}
        need(lab[("C", "H")]["label"] == "?" and lab[("C", "H")]["dash"], "the height is not the dashed ? line")
        g["b"] = int(re.fullmatch(r"(\d+) cm", lab[("A", "C")]["label"]).group(1))
        arc = sk["arcs"][0]
        need(arc["at"] == "A", "the angle is not at A")
        g["A"] = int(re.fullmatch(r"(\d+)°", arc["label"]).group(1))
        need(abs(math.hypot(C_[0], C_[1]) - g["b"]) < 1e-9 and abs(math.degrees(math.atan2(C_[1], C_[0])) - g["A"]) < 1e-6, "the sketch is not drawn to its labels")
        return g
    if q["diagram"] is not None:
        d = q["diagram"]
        sides = {s["side"]: s["label"] for s in d["sides"]}
        for k in "abc":
            if (m := re.fullmatch(r"(\d+) cm", sides[k])):
                g[k] = int(m.group(1))
        ang = {a["at"]: a["label"] for a in d["angles"]}
        need(ang["A"] == "" and ang["B"] == "", "an angle at A or B is marked")
        if (m := re.fullmatch(r"(\d+)°", ang["C"])):
            g["C"] = int(m.group(1))
        V = d["vertices"]
        dist = lambda p, r: math.hypot(V[p][0] - V[r][0], V[p][1] - V[r][1])
        for k, (p, r) in {"a": ("B", "C"), "b": ("A", "C"), "c": ("A", "B")}.items():
            need(g[k] is None or abs(dist(p, r) - g[k]) < 1e-6, f"side {k} is not drawn to its label")
        if (m := re.fullmatch(r"The diagram shows triangle ABC\. Its area is (.+) cm²\.", L[0])):
            g["area"] = E15ET_val(m.group(1))
        else:
            need(L[0] == "The diagram shows triangle ABC.", f"can't read {L[0]!r}")
        return g
    if (m := re.fullmatch(r"In triangle ABC, BC = (\d+) cm, AC = (\d+) cm and angle ACB = (\d+)°\.", L[0])):
        g["a"], g["b"], g["C"] = int(m.group(1)), int(m.group(2)), int(m.group(3))
    elif (m := re.fullmatch(r"In triangle ABC, BC = (\d+) cm, AC = (\d+) cm and AB = (\d+) cm\.", L[0])):
        g["a"], g["b"], g["c"] = int(m.group(1)), int(m.group(2)), int(m.group(3))
    elif (m := re.fullmatch(r"In triangle ABC, BC = (\d+) cm and angle ACB = (\d+)°\. The area of the triangle is (.+) cm²\.", L[0])):
        g["a"], g["C"], g["area"] = int(m.group(1)), int(m.group(2)), E15ET_val(m.group(3))
    else:
        raise Fail(f"can't read {L[0]!r}")
    return g


def E15ET_check(q):
    u = q["view"]["unknown"]
    need(q["paper"] == 1, "an exact triangle is Paper 1")
    g = E15ET_read(q)
    a, b, c, C, A, area = g["a"], g["b"], g["c"], g["C"], g["A"], g["area"]
    sin, cos = sp.sin, sp.cos
    if u == "exact-area":
        need(a and b and C in (45, 60, 120, 135) and c is None, f"givens {g}")
        v = sp.Rational(1, 2) * a * b * sin(E15ET_rad(C))
        want = f"Area = {E15ET_text(v)} cm²"
        wr = {E15ET_T + "4": {f"Area = {E15ET_text(2 * v)} cm²"}}
        if C == 60:
            wr[E15ET_T + "3"] = {f"Area = {E15ET_text(sp.Rational(1, 2) * a * b * cos(E15ET_rad(C)))} cm²"}
    elif u == "exact-side":
        need(a and b and C in (60, 120), f"givens {g}")
        c2 = sp.nsimplify(a * a + b * b - 2 * a * b * cos(E15ET_rad(C)))
        need(c2.is_Integer and not sp.sqrt(c2).is_Integer, f"AB² = {c2}")
        want = f"AB = {E15ET_text(sp.sqrt(c2))} cm"
        wr = {E15ET_T + "5": {f"AB = {E15ET_text(sp.sqrt(a * a + b * b - a * b * cos(E15ET_rad(C))))} cm"}}
        if C == 120:
            wr[E15ET_SK + "0"] = {f"AB = {E15ET_text(sp.sqrt(a * a + b * b - 2 * a * b * sp.Rational(1, 2)))} cm"}
    elif u == "exact-cos":
        need(a and b and c and a + b > c and a + c > b and b + c > a, f"givens {g}")
        v = sp.Rational(a * a + b * b - c * c, 2 * a * b)
        need(v != 0, "cos C is 0")
        want = f"cos ACB = {E15ET_text(v)}"
        wr = {E15ET_T + "5": {f"cos ACB = {E15ET_text(2 * v)}"}, E15ET_T + "6": {f"cos ACB = {E15ET_text(sp.Rational(b * b + c * c - a * a, 2 * b * c))}"},
              E15ET_T + "8": {f"cos ACB = {E15ET_text(-v)}"}}
        need(q["diagram"] is None or {x["at"]: x["label"] for x in q["diagram"]["angles"]}["C"] == "?", "the asked angle is not marked ?")
    elif u == "side-from-exact-area":
        need(a and C and area is not None, f"givens {g}")
        v = sp.nsimplify(2 * area / (a * sin(E15ET_rad(C))))
        need(v.is_Integer and v > 0, f"AC = {v}")
        need(q["diagram"] is None or {s["side"]: s["label"] for s in q["diagram"]["sides"]}["b"] == "?", "AC is not marked ?")
        want = f"AC = {v} cm"
        wr = {E15ET_T + "4": {f"AC = {E15ET_text(v / 2)} cm"}}
    else:
        need(A in (30, 45, 60) and b, f"givens {g}")
        v = b * sin(E15ET_rad(A))
        want = f"CH = {E15ET_text(v)} cm"
        wr = {E15ET_T + "7": {f"CH = {E15ET_text(b * cos(E15ET_rad(A)))} cm"}}
    gc_check_common(q, want, wr)
    E15ET_chains(q)
    return None, None


def E15ET_spot(q, lines):
    g = E15ET_read(q)
    a, b, C = g["a"], g["b"], g["C"]
    area = sp.Rational(1, 2) * a * b * sp.sin(E15ET_rad(C))
    c2 = sp.nsimplify(a * a + b * b - 2 * a * b * sp.cos(E15ET_rad(C)))
    for i, t in enumerate(lines):
        if t in ("Area = ½ab sin C",):
            ok = True
        elif "≈" in t:
            ok = False
        elif (m := re.fullmatch(r"So the area is (.+) cm²", t)):
            v = E15ET_val(m.group(1))
            ok = v is not None and re.search(r"\.\d", m.group(1)) is None and sp.simplify(v - area) == 0
        else:
            parts = t.removeprefix("So ").removesuffix(" cm").split(" = ")
            head = parts[0]
            want = {"Area": area, "AB²": c2, "AB": sp.sqrt(c2)}.get(head)
            if want is None:
                want = E15ET_val(head)
                need(want is not None and re.fullmatch(r"(sin|cos) \d+°", head), f"can't judge the line {t!r}")
            vals = [E15ET_val(p) for p in parts[1:]]
            need(vals and all(v is not None for v in vals), f"can't judge the line {t!r}")
            ok = all(sp.simplify(v - want) == 0 for v in vals)
        if not ok:
            return i
    return None


SITUATION_CHECKS["exact-triangle"] = E15ET_check
SPOT_CHECKS["exact-triangle"] = E15ET_spot

# ── end exact-triangle ──


# ── Boss chains (FAL-415) ────────────────────────────────────

def check_chain(parts):
    """The parts of one mini-boss or boss: one situation, and each part carries the
    part before's right answer (IB follow-through). Each part is also checked on its
    own, so the carried value is the true value of the situation its givens describe."""
    parts = sorted(parts, key=lambda q: q["part"])
    need([q["part"] for q in parts] == list(range(len(parts))), "parts are not (a), (b), ... in order")
    need(len(parts) >= 2, "a chain of one part")
    for prev, q in zip(parts, parts[1:]):
        need(q["situation"] == parts[0]["situation"], f"part {q['part']} is on another situation")
        need(q["situation_id"] == parts[0]["situation_id"], f"part {q['part']} is on another kind of situation")
        c = q.get("carried")
        need(c is not None, f"part {q['part']} carries nothing on")
        need(c["values"] == prev["answer"]["values"], f"part {q['part']} carries {c['values']}, not the answer {prev['answer']['values']}")
        need(c["text"] == prev["answer_text"], f"part {q['part']} shows {c['text']!r}, not {prev['answer_text']!r}")
        need(c["part"] == "abcdefgh"[prev["part"]], f"part {q['part']} names the wrong part")



# ── E17 shared (FAL-780) ─────────────────────────────────────
# Tools the six E17 sections share: a number as the game writes it, and a check that every
# equation a line of working states holds at the solution, read with SymPy.

E17_X = sp.Symbol("x")
E17_LEAD = re.compile(r"^(?:So |Then |and |which gives |where |Check: )+")


def E17_n(v):
    """A rational as the game writes it: 3, −4, 8/5, −1/3."""
    v = sp.Rational(v)
    s = str(abs(v.p)) if v.q == 1 else f"{abs(v.p)}/{v.q}"
    return ("−" if v < 0 else "") + s


def E17_expr(text, letters=("x",)):
    """A side of an equation as SymPy, or None where it has words in it."""
    t = text.strip().rstrip(".").strip()
    t = E17_LEAD.sub("", t)
    if "a" in letters and "b" in letters:
        t = re.sub(r"(?<=[ab)])(?=[ab])", "*", t)
    if not t or re.search(r"[A-Za-wyz]{2,}", t.replace("ln", "")):
        return None
    t = re.sub(r"(?<=\d) (?=\d{3}(?!\d))", "", t)
    t = re.sub("[⁰¹²³⁴⁵⁶⁷⁸⁹⁻]+", lambda mt: "**(" + mt.group(0).translate(SF_SUP) + ")", t)
    t = t.replace("−", "-").replace("×", "*").replace("÷", "/").replace("^", "**")
    t = t.replace("√", "sqrt").replace("∛", "cbrt")
    t = re.sub(r"(sqrt|cbrt)([\d.]+)", r"\1(\2)", t)
    t = re.sub(r"(?<![\w)])ln (\d+)", r"ln(\1)", t)
    if not re.fullmatch(r"[0-9a-z+\-*/(). ]+", t):
        return None
    local = {"x": E17_X, "ln": sp.log, "sqrt": sp.sqrt, "cbrt": lambda v: sp.root(v, 3)}
    try:
        e = parse_expr(t, local_dict=local, transformations=TRANSFORMS + (rationalize,), evaluate=True)
    except Exception:
        return None
    if not all(str(s) in letters for s in e.free_symbols):
        return None
    return e


def E17_fragments(line):
    """The equations a line states, each as its list of sides."""
    out = []
    for part in re.split(r", as |, so |, and |; |: | and |, where |, ", line.rstrip(".")):
        if " = " not in part:
            continue
        out.append(part.split(" = "))
    return out


def E17_holds(line, subs, letters=("x",)):
    """False if an equation in the line is false at subs; True otherwise (unread ones pass)."""
    for sides in E17_fragments(line):
        es = [E17_expr(p, letters) for p in sides]
        if any(e is None for e in es):
            continue
        vals = [e.subs(subs) for e in es]
        # A side written as a bare decimal is that value to its last place.
        tol = sp.Float(10) ** -25
        for p in sides:
            mt = re.fullmatch(r"\s*−?\d+\.(\d+)\s*", E17_LEAD.sub("", p.strip().rstrip(".")))
            if mt:
                tol = max(tol, sp.Float(10) ** -len(mt.group(1)) / 2 + sp.Float(10) ** -12)
        for a, b in zip(vals, vals[1:]):
            d = sp.N(a - b, 40)
            if not d.is_real or abs(d) > tol * (1 + (0 if tol > 1e-20 else abs(sp.N(b, 40)))):
                return False
    return True


def E17_no_hyphen(q):
    """A minus is −, never a hyphen, in anything the student reads."""
    texts = [q["asked"], q.get("prompt", "")] + q["lines"] + [o["text"] for o in q["choices"]] + [st for sol in q["solutions"] for st in sol["steps"]]
    for t in texts:
        need(not re.search(r"(?<![A-Za-z])-\d", t), f"a hyphen for a minus in {t!r}")


def E17_steps(q, subs, letters=("x",)):
    for sol in q["solutions"]:
        for st in sol["steps"]:
            need(E17_holds(st, subs, letters), f"{sol['name']}: {st!r} is not true at the answer")


def E17_first_false(lines, subs, letters=("x",)):
    for i, t in enumerate(lines):
        if not E17_holds(t, subs, letters):
            return i
    return None


# ── solve-exponential, t1-ext-common-base (FAL-780) ─────────
# Each equation is read back from its line. Both bases must be powers of one prime, so the
# exponents are compared on that prime: i(x + c) = j(kx + e) is solved with exact fractions,
# and the answer is checked in the equation itself. Every tagged option is rebuilt from its
# slip, every equation in the working must hold at the answer, and an error-spot's first wrong
# line is the first whose equation fails there.

E17CB_MAP = "SL1.7.common-base#"
E17CB_OWN = "t1-ext-common-base#"
E17CB_UNKNOWNS = ("whole-power", "reciprocal-power", "fraction-power", "linear-exponents", "meet-on-graph")
E17CB_POW = re.compile(r"(\d+)\^(x|\(([^()]*)\))")


def E17CB_prime(n):
    f = sp.factorint(n)
    need(len(f) == 1, f"{n} is not a power of one prime")
    (t, p), = f.items()
    return t, p


def E17CB_side(text):
    """'8^(2x − 2)' -> (8, 2x − 2)."""
    m = E17CB_POW.fullmatch(text.strip())
    need(m is not None, f"can't read the power {text!r}")
    ex = E17_expr(m.group(3) if m.group(3) else "x")
    need(ex is not None and sp.Poly(ex, E17_X).degree() == 1, f"the exponent of {text!r} is not linear in x")
    return int(m.group(1)), ex


def E17CB_check(q):
    u, L, paper = q["view"]["unknown"], q["lines"], q["paper"]
    x = E17_X
    wr = {}
    if q["view"]["angle"] == "graph-intersect":
        need(paper == 2, "a graph-intersect question is not Paper 2")
    if u in ("whole-power", "reciprocal-power"):
        m = re.fullmatch(r"(\d+)\^x = (1/)?(\d+)", L[0])
        need(m is not None and bool(m.group(2)) == (u == "reciprocal-power"), f"can't read {L[0]!r}")
        b, N = int(m.group(1)), int(m.group(3))
        j = sp.Integer(sp.log(N, b)) if sp.log(N, b).is_Integer else None
        need(j is not None and b ** int(j) == N, f"{N} is not a whole power of {b}")
        need(2 <= j and N <= 1000 and (b, N) != (2, 32), f"{b}^x = {N} is outside the limits or the map's example")
        sol = j if u == "whole-power" else -j
        need(b ** sp.Integer(sol) == (N if u == "whole-power" else sp.Rational(1, N)), "the answer doesn't solve it")
        if u == "whole-power":
            wr[E17CB_MAP + "0"] = {f"x = {E17_n(sp.Rational(N, b))}"}
        else:
            wr[E17CB_MAP + "0"] = {f"x = {E17_n(sp.Rational(1, N * b))}"}
            wr[E17CB_OWN + "3"] = {f"x = {E17_n(j)}"}
    elif u == "fraction-power":
        m = re.fullmatch(r"(\d+)\^x = (\d+)", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        A, R = int(m.group(1)), int(m.group(2))
        t, i = E17CB_prime(A)
        t2, j = E17CB_prime(R)
        need(t == t2, "the two sides have no common base")
        need(A <= 27 and R <= 243 and i > 1 and j % i != 0, f"{A}^x = {R} is outside the limits")
        sol = sp.Rational(j, i)
        need(sp.Integer(A) ** sol == R, "the answer doesn't solve it")
        wr[E17CB_MAP + "0"] = {f"x = {E17_n(sp.Rational(R, A))}"}
        wr[E17CB_OWN + "2"] = {f"x = {E17_n(sp.Rational(i, j))}"}
    else:
        if u == "meet-on-graph":
            m = re.fullmatch(r"The graph shows y = (.+) and y = (.+), which cross at P\.", L[0])
        else:
            m = re.fullmatch(r"(.+) = (.+)", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        A, ex1 = E17CB_side(m.group(1))
        B, ex2 = E17CB_side(m.group(2))
        t, i = E17CB_prime(A)
        t2, j = E17CB_prime(B)
        need(t == t2 and i != j and sp.gcd(i, j) == 1 and max(A, B) <= 81, f"{A} and {B} break the limits")
        c, k, e = ex1.subs(x, 0), sp.Poly(ex2, x).LC(), ex2.subs(x, 0)
        need(sp.Poly(ex1, x).LC() == 1 and c != 0 and e != 0 and k in (1, 2, 3), "the exponents break the limits")
        roots = sp.solve(sp.Eq(i * ex1, j * ex2), x)
        need(len(roots) == 1, "not one solution")
        sol = sp.Rational(roots[0])
        D = i - j * k
        need(sol != 0 and abs(D) <= 7, f"x = {sol} or the coefficient {D} breaks the limits")
        need(sp.simplify(sp.Integer(A) ** ex1.subs(x, sol) - sp.Integer(B) ** ex2.subs(x, sol)) == 0, "the answer doesn't solve it")
        slip = sp.solve(sp.Eq(i * x + c, j * k * x + e), x)
        need(len(slip) == 1 and slip[0] != sol, "the x-only slip gives the answer")
        wr[E17CB_MAP + "1"] = {f"x = {E17_n(slip[0])}"}
        if k != 1:
            raw = sp.solve(sp.Eq(ex1, ex2), x)
            wr[E17CB_OWN + "4"] = {f"x = {E17_n(r)}" for r in raw}
        if u == "meet-on-graph":
            need(k == 1 and sol.q == 1 and -3 <= sol <= 4, f"P at x = {sol} is not whole, or outside −3 to 4")
            y = sp.Integer(A) ** ex1.subs(x, sol)
            need(2 <= y <= 600, f"P's height {y} is outside 2 to 600")
            wr[E17CB_OWN + "5"] = {f"x = {E17_n(y)}"}
            g = q["graph"]
            need(g is not None and any(p["label"] == "P" and abs(p["x"] - float(sol)) < 1e-9 and abs(p["y"] - float(y)) < 1e-6 for p in g["points"]), "P is not drawn at the crossing")
            for curve, (base, ex) in zip(g["curves"], ((A, ex1), (B, ex2))):
                for px, py in curve[::17]:
                    need(abs(py - float(sp.Integer(base) ** ex.subs(x, sp.nsimplify(px)))) <= 1e-6 * max(1, abs(py)), "a curve drawn is not its equation")
    want = f"x = {E17_n(sol)}"
    gc_check_common(q, want, wr)
    E17_steps(q, {x: sol})
    E17_no_hyphen(q)
    return None, None


def E17CB_spot(q, lines):
    u = q["view"]["unknown"]
    m = re.fullmatch(r"(.+) = (.+)", q["lines"][0])
    if u == "fraction-power":
        A, R = int(m.group(1).split("^")[0]), int(m.group(2))
        t, i = E17CB_prime(A)
        sol = sp.Rational(E17CB_prime(R)[1], i)
    else:
        A, ex1 = E17CB_side(m.group(1))
        B, ex2 = E17CB_side(m.group(2))
        t, i = E17CB_prime(A)
        j = E17CB_prime(B)[1]
        sol = sp.solve(sp.Eq(i * ex1, j * ex2), E17_X)[0]
    for t_ in lines:
        need(any(" = " in p for p in re.split(r", as |, so ", t_)), f"can't judge the line {t_!r}")
    return E17_first_false(lines, {E17_X: sol})


E17CB_PREV = SITUATION_CHECKS["solve-exponential"]
E17CB_PREV_SPOT = SPOT_CHECKS.get("solve-exponential")


def E17CB_entry(q):
    return E17CB_check(q) if q["view"]["unknown"] in E17CB_UNKNOWNS else E17CB_PREV(q)


def E17CB_spot_entry(q, lines):
    if q["view"]["unknown"] in E17CB_UNKNOWNS:
        return E17CB_spot(q, lines)
    return E17CB_PREV_SPOT(q, lines)


SITUATION_CHECKS["solve-exponential"] = E17CB_entry
SPOT_CHECKS["solve-exponential"] = E17CB_spot_entry



# ── integer-powers, t1-ext-exponent-laws (FAL-780) ──────────
# Each number or expression is read back from the question and worked out with SymPy: a value
# exactly, a term as its coefficient and exponent of x, a quotient as the exponents of a and b, and
# a product of powers of one prime as that prime's exponent. Every tagged option is rebuilt from its
# slip, every equation in the working must hold (at x = 2, or a = 2 and b = 3, where it has letters),
# and an error-spot's first wrong line is the first whose equation fails.

E17EL_IL = "SL1.5.integer-exponent-laws#"
E17EL_ZN = "SL1.5.zero-negative#"
E17EL_OWN = "t1-ext-exponent-laws#"
E17EL_A, E17EL_B = sp.Symbol("a"), sp.Symbol("b")


def E17EL_pw(base, e):
    """'2^3', '2^(−3)', '(2/3)^(−2)', 'x^4'."""
    b = base if isinstance(base, str) else (str(base) if sp.Rational(base).q == 1 and base > 0 else f"({E17_n(base)})")
    return f"{b}^{e}" if e >= 0 else f"{b}^(−{-e})"


def E17EL_mono(c, e, letter="x"):
    c = sp.Rational(c)
    if e == 0:
        return E17_n(c)
    if c == 1:
        head = ""
    elif c == -1:
        head = "−"
    elif c.q == 1:
        head = E17_n(c)
    else:
        head = ("−" if c < 0 else "") + f"({E17_n(abs(c))})"
    return head + (letter if e == 1 else E17EL_pw(letter, e))


def E17EL_ab(ea, eb):
    top, bottom = [], []
    for letter, e in (("a", ea), ("b", eb)):
        if e > 0:
            top.append(letter if e == 1 else E17EL_pw(letter, e))
        elif e < 0:
            bottom.append(letter if e == -1 else E17EL_pw(letter, -e))
    t = "".join(top) or "1"
    if not bottom:
        return t
    return f"{t}/{bottom[0]}" if len(bottom) == 1 else f"{t}/({''.join(bottom)})"


def E17EL_read(text, letters=("x",)):
    e = E17_expr(text, letters)
    need(e is not None, f"can't read {text!r}")
    return e


def E17EL_term(e):
    """c·x^k as (c, k)."""
    c, k = sp.expand(e).as_coeff_exponent(E17_X)
    need(c.free_symbols == set() and k.is_Integer, f"{e} is not a single term")
    return sp.Rational(c), int(k)


def E17EL_check(q):
    u, asked = q["view"]["unknown"], q["asked"]
    need(q["paper"] == 1, "an exponent-laws question is Paper 1")
    X = E17_X
    wr = {}
    subs = {X: 2}
    letters = ("x",)
    if u in ("negative-power", "zero-and-negative"):
        m = re.fullmatch(r"Find the exact value of (.+)\.", asked)
        need(m is not None, f"can't read {asked!r}")
        text = m.group(1)
        if u == "negative-power":
            mm = re.fullmatch(r"(\d+|\((\d+)/(\d+)\))\^\(−(\d)\)", text)
            need(mm is not None, f"can't read {text!r}")
            base = sp.Integer(mm.group(1)) if mm.group(2) is None else sp.Rational(int(mm.group(2)), int(mm.group(3)))
            n = int(mm.group(4))
            need(1 <= n <= 3 and (base.q == 1 and 2 <= base <= 6 and base ** n <= 216 or base.q != 1 and 2 <= n and max(base.p, base.q) <= 5), f"{text} breaks the limits")
            v = base ** -n
            wr[E17EL_ZN + "0"] = {f"value = {E17_n(-(base ** n))}"}
            wr[E17EL_OWN + "6"] = {f"value = {E17_n(base ** n)}"}
            if base.q == 1:
                wr[E17EL_OWN + "7"] = {f"value = {E17_n(-base * n)}"}
        else:
            mm = re.fullmatch(r"(\d)\^0 \+ (\d)\^\(−(\d)\)", text)
            need(mm is not None, f"can't read {text!r}")
            c, b, n = (int(mm.group(i)) for i in (1, 2, 3))
            need(c != b and 4 <= b ** n <= 216, f"{text} breaks the limits")
            v = 1 + sp.Rational(1, b ** n)
            wr[E17EL_ZN + "1"] = {f"value = {E17_n(sp.Rational(1, b ** n))}"}
            wr[E17EL_ZN + "0"] = {f"value = {E17_n(1 - b ** n)}"}
            wr[E17EL_OWN + "8"] = {f"value = {E17_n(c + sp.Rational(1, b ** n))}"}
            wr[E17EL_OWN + "6"] = {f"value = {E17_n(1 + b ** n)}"}
        need(E17_expr(text) is not None and sp.Rational(E17_expr(text)) == v, "the value read back is not the one worked out")
        want = f"value = {E17_n(v)}"
        subs = {}
    elif u == "to-index-form":
        m = re.fullmatch(r"Write (.+) in the form ax\^p, where a and p are constants\.", asked)
        need(m is not None, f"can't read {asked!r}")
        text = m.group(1)
        a, p = E17EL_term(E17EL_read(text))
        need(p < 0, "the power is not negative")
        top = re.fullmatch(r"(\d)/x(?:\^\d)?", text) is not None
        need(top or re.fullmatch(r"1/\((\d)x(?:\^\d)?\)", text), f"{text} is not c/xⁿ or 1/(cxⁿ)")
        want = E17EL_mono(a, p)
        wr[E17EL_OWN + "9"] = {E17EL_mono(a, -p)}
        wr[E17EL_ZN + "0"] = {E17EL_mono(-a, -p)}
        if not top:
            wr[E17EL_ZN + "2"] = {E17EL_mono(1 / a, p)}
    elif u == "power-of-product":
        m = re.fullmatch(r"Simplify (\((\d)x\^(\d)\)\^(\d) × (\d?)x(?:\^\(?(−?\d)\)?)?), giving your answer in the form cx\^e\.", asked)
        need(m is not None, f"can't read {asked!r}")
        a, mm, p = int(m.group(2)), int(m.group(3)), int(m.group(4))
        b = int(m.group(5) or 1)
        n = int((m.group(6) or "1").replace("−", "-"))
        C, e = E17EL_term(E17EL_read(m.group(1)))
        need(C == a ** p * b and e == mm * p + n, "the term read back is not (axᵐ)ᵖ × bxⁿ")
        need(e not in (0, 1) and mm * p <= 12 and e <= 10 and C <= 250, f"{m.group(1)} breaks the limits")
        want = E17EL_mono(C, e)
        wr[E17EL_IL + "0"] = {E17EL_mono(C, mm + p + n)}
        wr[E17EL_IL + "1"] = {E17EL_mono(a * b, e)}
        if a * p != a ** p:
            wr[E17EL_OWN + "10"] = {E17EL_mono(a * p * b, e)}
        if n < 0:
            wr[E17EL_OWN + "11"] = {E17EL_mono(C, mm * p - n)}
    elif u == "two-letter-quotient":
        m = re.fullmatch(r"Simplify \((.+)\)/\((.+)\), giving your answer with positive exponents only\.", asked)
        need(m is not None, f"can't read {asked!r}")
        letters = ("a", "b")
        top, bot = E17EL_read(m.group(1), letters), E17EL_read(m.group(2), letters)
        pt, pb = top.as_powers_dict(), bot.as_powers_dict()
        p, qq, r, s_ = (int(d.get(L_, 0)) for d, L_ in ((pt, E17EL_A), (pt, E17EL_B), (pb, E17EL_A), (pb, E17EL_B)))
        need(all(v != 0 and -4 <= v <= 5 for v in (p, qq, r, s_)), "an exponent breaks the limits")
        ea, eb = p - r, qq - s_
        need(ea * eb < 0, "the answer does not have one letter on each line")
        need(sp.simplify(top / bot - E17EL_A ** ea * E17EL_B ** eb) == 0, "the exponents worked out don't give the quotient")
        want = E17EL_ab(ea, eb)
        wr[E17EL_OWN + "12"] = {E17EL_ab(-ea, -eb)}
        wr[E17EL_OWN + "13"] = {E17EL_ab(p + r, qq + s_)}
        subs = {E17EL_A: 2, E17EL_B: 3}
    else:
        m = re.fullmatch(r"(\d+)\^\(?(−?\d)\)? ([×÷]) (\d+)\^\(?(−?\d)\)?", q["lines"][0])
        need(m is not None, f"can't read {q['lines'][0]!r}")
        A, mm, op, B, n = int(m.group(1)), int(m.group(2).replace("−", "-")), m.group(3), int(m.group(4)), int(m.group(5).replace("−", "-"))
        t, i = E17CB_prime(A)
        t2, j = E17CB_prime(B)
        need(t == t2 and i != j and min(i, j) >= 2 and max(A, B) <= 125, f"{A} and {B} break the limits")
        sgn = 1 if op == "×" else -1
        k = i * mm + sgn * j * n
        need(sp.Integer(A) ** mm * sp.Integer(B) ** (sgn * n) == sp.Integer(t) ** k, "the power worked out is not the number")
        need(k != 0 and abs(k) <= 20, f"k = {k} breaks the limits")
        need(re.search(rf"single power of {t}, in the form {t}\^k\.", asked), "the question asks for another base")
        want = E17EL_pw(t, k)
        wr[E17EL_OWN + "14"] = {E17EL_pw(t, mm + sgn * n)}
        if op == "×":
            need(sp.Integer(A * B) ** (mm + n) != sp.Integer(t) ** k, "combining the bases gives the answer's value")
            wr[E17EL_IL + "2"] = {E17EL_pw(A * B, mm + n)}
        subs = {}
    gc_check_common(q, want, wr)
    E17_steps(q, subs, letters)
    E17_no_hyphen(q)
    return None, None


def E17EL_spot(q, lines):
    for t in lines:
        need(" = " in t or t.startswith("Raise the bracket"), f"can't judge the line {t!r}")
    return E17_first_false(lines, {E17_X: 2})


SITUATION_CHECKS["integer-powers"] = E17EL_check
SPOT_CHECKS["integer-powers"] = E17EL_spot



# ── standard-form, t1-ext-standard-form-add and -powers (FAL-780) ──
# The numbers are read back from the lines (p and q, or a story) or from the question, and the sum,
# difference, power or root is worked out exactly with SymPy, then written in standard form. Every
# tagged option is rebuilt from its slip, every equation in the working must hold, and an
# error-spot's first wrong line is the first whose equation fails.

E17SF_SA = "SL1.1.add-subtract#"
E17SF_SP = "SL1.1.powers-roots#"
E17SF_OA = "t1-ext-standard-form-add#"
E17SF_OP = "t1-ext-standard-form-powers#"
E17SF_ADD = ("add-forms", "add-carry", "subtract-forms", "subtract-renormalise", "difference-context")
E17SF_POW = ("square-form", "cube-form", "root-even", "root-odd", "cube-root")
E17SF_GAPS = (
    "The salt road to the coast is (.+) metres long and the track to the mine is (.+) metres long.",
    "A dust storm carried (.+) kilograms of sand and a gale carried (.+) kilograms.",
    "The reservoir holds (.+) litres and the camp's cistern holds (.+) litres.",
    "A relay mast is (.+) metres from the base and a drone is (.+) metres from it.",
    "The old dam's turbines gave (.+) watts and a wind rig gives (.+) watts.",
    "A grain of dust is (.+) metres wide and a grain of pollen is (.+) metres wide.",
)


def E17SF_text(v, e=None):
    """v × 10^e, or v itself when e is None, normalised and written as the game writes it."""
    a, k = sf_norm(sp.Rational(v) * (sp.Rational(10) ** e if e is not None else 1))
    return sf_text(a, k, False), a, k


def E17SF_raw(a, e):
    """a × 10^e with a left as it is (a slip may leave it outside 1 to 10)."""
    return sf_text(sp.Rational(a), e, False)


def E17SF_one(text):
    got = sf_read(text)
    need(len(got) == 1, f"can't read one number in {text!r}")
    return got[0]


def E17SF_check(q):
    u, L, asked, paper = q["view"]["unknown"], q["lines"], q["asked"], q["paper"]
    if "A student's working:" in L:
        L = L[:L.index("A student's working:")]
    need(not q["view"]["angle"].startswith("gdc-") or paper == 2, "a GDC method is not Paper 2")
    wr = {}
    if u in E17SF_ADD:
        minus = u != "add-forms" and u != "add-carry"
        if q["view"]["rep"] == "words":
            m = next((re.fullmatch(g, L[0]) for g in E17SF_GAPS if re.fullmatch(g, L[0])), None)
            need(m is not None, f"can't read the story {L[0]!r}")
            (a, mm), (b, n) = E17SF_one(m.group(1)), E17SF_one(m.group(2))
            small = E17SF_GAPS.index(m.re.pattern) == len(E17SF_GAPS) - 1
            need((max(mm, n) < 0) == small, "a story's powers of ten have the wrong sign for what it measures")
        else:
            need(len(L) == 2 and L[0].startswith("p = ") and L[1].startswith("q = "), "p and q")
            (a, mm), (b, n) = E17SF_one(L[0]), E17SF_one(L[1])
            need(asked.startswith("Find p − q." if minus else "Find p + q."), f"the question asks {asked!r}")
        big = max(mm, n)
        need(mm != n and abs(mm - n) in (1, 2), "the powers are not 1 or 2 apart")
        need(all(1 <= v < 10 and (v * (10 if paper == 1 else 100)).q == 1 for v in (a, b)), f"{a} or {b} breaks the limits")
        if minus:
            need(mm > n, "the larger number comes second")
        P_, Q_ = a * sp.Rational(10) ** mm, b * sp.Rational(10) ** n
        v = P_ - Q_ if minus else P_ + Q_
        need(v > 0, "the difference is not positive")
        c = v / sp.Rational(10) ** big
        want, r, k = E17SF_text(v)
        need(abs(k) >= 2 and (r * 1000).q == 1, f"{want} breaks the limits")
        need((c >= 10) == (u == "add-carry") and (c < 1) == (u == "subtract-renormalise"), f"{u} with a coefficient of {c} at the larger power")
        raw = a - b if minus else a + b
        if minus and u != "subtract-renormalise":
            need(raw >= 1, "the coefficients are less than 1 apart")
        if raw > 0:
            wr[E17SF_SA + "0"] = {E17SF_raw(raw, mm + n)}
            wr[E17SF_SA + "1"] = {E17SF_raw(raw, big)}
            if minus:
                wr[E17SF_OA + "4"] = {E17SF_raw(raw, mm - n)}
        if u == "add-carry":
            wr[E17SF_OA + "2"] = {E17SF_raw(c, big)}
        if u == "subtract-renormalise":
            wr[E17SF_OA + "3"] = {E17SF_raw(c, big)}
    else:
        if u in ("square-form", "cube-form"):
            m = re.fullmatch(r"Find \((.+)\)([²³])\. Give your answer .*", asked)
            need(m is not None and (m.group(2) == "²") == (u == "square-form"), f"can't read {asked!r}")
            a, mm = E17SF_one(m.group(1))
            p = 2 if m.group(2) == "²" else 3
            need((a * 10).q == 1 and 1 <= a < (10 if p == 2 else sp.Rational(51, 10)) and 2 <= abs(mm) <= 6, f"{a} × 10^{mm} breaks the limits")
            v = (a * sp.Rational(10) ** mm) ** p
            want, r, k = E17SF_text(v)
            wr[E17SF_SP + "0"] = {E17SF_raw(a, p * mm)}
            wr[E17SF_SP + "1"] = {E17SF_text(a ** p, mm + p)[0]}
            wr[E17SF_OP + "3"] = {E17SF_text(a * p, p * mm)[0]}
        else:
            m = re.fullmatch(r"Find ([√∛])\((.+)\)\. Give your answer .*", asked)
            need(m is not None and (m.group(1) == "∛") == (u == "cube-root"), f"can't read {asked!r}")
            a, mm = E17SF_one(m.group(2))
            deg = 3 if m.group(1) == "∛" else 2
            need(1 <= a < 10, f"a = {a} is not in standard form")
            v = sp.root(a * sp.Rational(10) ** mm, deg)
            need(v.is_Rational, f"the root of {a} × 10^{mm} is not exact")
            want, r, k = E17SF_text(v)
            sh = mm - deg * k
            need(sh in range(deg) and (u != "root-even" or sh == 0) and (u != "root-odd" or sh == 1), f"{u} with the power adjusted by {sh}")
            need(abs(k) >= 2 and (r * 10).q == 1, f"{want} breaks the limits")
            big_a = a * 10 ** sh
            wr[E17SF_SP + "2"] = {E17SF_raw(r, mm - sh)}
            if deg == 2:
                wr[E17SF_OP + "4"] = {E17SF_text(big_a / 2, k)[0]}
            else:
                wr[E17SF_OP + "5"] = {E17SF_text(big_a / 3, k)[0]}
    gc_check_common(q, want, wr)
    E17_steps(q, {})
    E17_no_hyphen(q)
    return None, None


def E17SF_spot(q, lines):
    for t in lines:
        need(" = " in t or re.match(r"(Write [pq] with|Cube the number|Make the power|Check: \d|[\d.]+ is between)", t), f"can't judge the line {t!r}")
    return E17_first_false(lines, {})


E17SF_PREV = SITUATION_CHECKS["standard-form"]


def E17SF_entry(q):
    return E17SF_check(q) if q["view"]["unknown"] in E17SF_ADD + E17SF_POW else E17SF_PREV(q)


SITUATION_CHECKS["standard-form"] = E17SF_entry
SPOT_CHECKS["standard-form"] = E17SF_spot



# ── compound-interest, t1-ext-real-value (FAL-780) ──────────
# The amount, the interest and inflation rates and the years are read from the story, and each value
# is worked out with exact rationals: the real rate r − f, the value at that rate, the nominal value
# divided by (1 + f/100)^n, and whether r > f. Every tagged option is rebuilt from its slip, every
# offered value is clear of a rounding edge, the working's sums are redone, and an error-spot's lines
# are judged by what each one claims.

E17RV_MAP = "SL1.4.real-value#"
E17RV_OWN = "t1-ext-real-value#"
E17RV_UNKNOWNS = ("real-rate", "real-value-rate", "real-value-deflate", "keeps-pace")
E17RV_LINE = re.compile(r"(.+) puts (?:\$(\d+)|money) into an account that pays ([\d.]+)% interest per year(?:, compounded annually)?\. Prices rise by ([\d.]+)% per year\.")


def E17RV_read(q):
    m = E17RV_LINE.fullmatch(q["lines"][0])
    need(m is not None, f"can't read {q['lines'][0]!r}")
    need(m.group(1) in CI_WHO and CI_WHO.index(m.group(1)) == int(q["given"]["ctx"]), f"the story's name {m.group(1)!r}")
    pv = sp.Integer(m.group(2)) if m.group(2) else None
    r, f = R(m.group(3)), R(m.group(4))
    need(r in {sp.Rational(t, 10) for t in range(20, 81, 5)} and f in {sp.Rational(t, 10) for t in range(10, 61, 5)} and r != f, f"rates {r}% and {f}% break the limits")
    n = None
    mn = re.search(r"after (\d+) years", q["asked"])
    if mn:
        n = int(mn.group(1))
        need(3 <= n <= 12, f"n = {n}")
    if pv is not None:
        need(pv % 500 == 0 and 1000 <= pv <= 20000, f"PV {pv}")
    return pv, r, f, n


def E17RV_money(x):
    need(ci_clear(x), f"{float(x)} is too close to a rounding edge of a cent")
    return ci_money(ci_cents(x))


def E17RV_check(q):
    u = q["view"]["unknown"]
    need(q["paper"] == 2, "a real-value question is Paper 2")
    pv, r, f, n = E17RV_read(q)
    wr = {}
    if u == "real-rate":
        need(q["asked"] == "Write down the real interest rate.", f"asked {q['asked']!r}")
        want = f"real rate = {dec_text(r - f)}%"
        wr[E17RV_MAP + "0"] = {f"real rate = {dec_text(r + f)}%"}
        wr[E17RV_OWN + "3"] = {f"real rate = {dec_text(f - r)}%"}
    elif u == "keeps-pace":
        up = r > f
        want = ("Yes: the interest rate is more than the inflation rate, so its value in today's money rises." if up
                else "No: the interest rate is less than the inflation rate, so its value in today's money falls, though its balance rises.")
        wr[E17RV_MAP + "2"] = set() if up else {"Yes: its balance rises every year, so it keeps pace."}
        wr[E17RV_OWN + "6"] = {"No: prices rise every year, so its real value must fall."} if up else set()
        need(sp.Rational(1) + r / 100 > (1 + f / 100) if up else (1 + r / 100) < (1 + f / 100), "the factors disagree with the rates")
    else:
        need(pv is not None and n is not None and r > f, "a value needs an amount, the years and r > f")
        nominal = ci_value(pv, r, 1, n)
        real = ci_value(pv, r - f, 1, n)
        defl = nominal / (1 + f / 100) ** n
        need(abs(real - defl) >= 1, "the real-rate and deflated values are less than a dollar apart")
        if u == "real-value-rate":
            need(q["asked"] == f"Using the real interest rate, find the real value of the investment after {n} years, to the nearest cent.", f"asked {q['asked']!r}")
            want = f"real value = ${E17RV_money(real)}"
            wr[E17RV_MAP + "0"] = {f"real value = ${E17RV_money(ci_value(pv, r + f, 1, n))}"}
            wr[E17RV_OWN + "4"] = {f"real value = ${E17RV_money(nominal)}"}
        else:
            need(q["asked"] == f"By dividing by the rise in prices, find the value of the investment after {n} years in today's money, to the nearest cent.", f"asked {q['asked']!r}")
            want = f"real value = ${E17RV_money(defl)}"
            wr[E17RV_MAP + "1"] = {f"real value = ${E17RV_money(nominal / (1 + f / 100))}"}
            wr[E17RV_OWN + "4"] = {f"real value = ${E17RV_money(nominal)}"}
            wr[E17RV_OWN + "5"] = {f"real value = ${E17RV_money(nominal * (1 + f / 100) ** n)}"}
    gc_check_common(q, want, wr)
    E17RV_steps(q, pv, r, f, n)
    E17_no_hyphen(q)
    return None, None


def E17RV_close(a, b, places):
    return abs(sp.Rational(a) - sp.Rational(b)) <= sp.Rational(1, 2) * sp.Rational(1, 10) ** places + sp.Rational(1, 10 ** 9)


def E17RV_steps(q, pv, r, f, n):
    """Each figure the working writes, against the exact value it stands for."""
    for sol in q["solutions"]:
        for st in sol["steps"]:
            for a, b, c in re.findall(r"([\d.]+) − ([\d.]+) = (−?[\d.]+)", st):
                need(R(a) - R(b) == R(c.replace("−", "-")), f"{sol['name']}: {st!r}")
            for base, e, val in re.findall(r"(?<![\d.])(?<!× )([\d.]+)\^(\d+) = ([\d.]+)", st):
                places = len(val.split(".")[1]) if "." in val else 0
                need(E17RV_close(R(base) ** int(e), R(val), places), f"{sol['name']}: {st!r}")
            if (m := re.search(r"FV = (\d+) × ([\d.]+)\^(\d+) = ([\d.]+)", st)):
                need(E17RV_close(R(m.group(1)) * R(m.group(2)) ** int(m.group(3)), R(m.group(4)), 4), f"{sol['name']}: {st!r}")
            if (m := re.search(r"Solve for FV: FV = ([\d.]+)", st)):
                need(E17RV_close(ci_value(pv, r - f, 1, n), R(m.group(1)), 4), f"{sol['name']}: {st!r}")
            if (m := re.search(r"Real value = ([\d.]+) ÷ ([\d.]+) = ([\d.]+)", st)):
                need(E17RV_close(ci_value(pv, r, 1, n) / (1 + f / 100) ** n, R(m.group(3)), 4) and E17RV_close((1 + f / 100) ** n, R(m.group(2)), 6), f"{sol['name']}: {st!r}")
            if (m := re.search(r"After (\d+) years: (\d+) × ([\d.]+)\^(\d+) = ([\d.]+)", st)):
                g = (1 + (r - f) / 100) if q["view"]["unknown"] == "real-value-rate" else (1 + r / 100) / (1 + f / 100)
                need(int(m.group(1)) == n and E17RV_close(g, R(m.group(3)), 6) and E17RV_close(pv * g ** n, R(m.group(5)), 4), f"{sol['name']}: {st!r}")
            if (m := re.search(r"([\d.]+) ÷ ([\d.]+) = ([\d.]+), (more|less) than 1", st)):
                g = (1 + r / 100) / (1 + f / 100)
                need(E17RV_close(g, R(m.group(3)), 6) and (m.group(4) == "more") == (g > 1), f"{sol['name']}: {st!r}")


def E17RV_spot(q, lines):
    pv, r, f, n = E17RV_read(q)
    nominal = ci_value(pv, r, 1, n)
    for i, t in enumerate(lines):
        if t.startswith(("Use the real rate", "Divide the value after")):
            ok = True
        elif (m := re.fullmatch(r"Real rate = ([\d.]+) ([+−]) ([\d.]+) = ([\d.]+)%", t)):
            ok = m.group(2) == "−" and R(m.group(4)) == r - f
        elif (m := re.fullmatch(r"Value = (\d+) × \(1 \+ ([\d.]+)/100\)\^(\d+)(?: = ([\d.]+))?", t)):
            ok = R(m.group(2)) == r - f and (m.group(4) is None or E17RV_close(ci_value(pv, r - f, 1, n), R(m.group(4)), 4))
        elif (m := re.fullmatch(r"= ([\d.]+)", t)):
            ok = E17RV_close(ci_value(pv, r - f, 1, n), R(m.group(1)), 4)
        elif (m := re.fullmatch(r"FV = (\d+) × ([\d.]+)\^(\d+) = ([\d.]+)(?:, and prices rise by a factor of ([\d.]+))?", t)):
            ok = E17RV_close(nominal, R(m.group(4)), 4) and (m.group(5) is None or E17RV_close((1 + f / 100) ** n, R(m.group(5)), 4))
        elif (m := re.fullmatch(r"Prices rise by a factor of ([\d.]+)", t)):
            ok = E17RV_close((1 + f / 100) ** n, R(m.group(1)), 4)
        elif (m := re.fullmatch(r"Real value = ([\d.]+) ÷ ([\d.]+) = ([\d.]+)", t)):
            ok = E17RV_close(nominal / (1 + f / 100) ** n, R(m.group(3)), 4)
        elif (m := re.fullmatch(r"So the real value is \$([\d.]+)\.", t)):
            want = ci_value(pv, r - f, 1, n) if q["view"]["unknown"] == "real-value-rate" else nominal / (1 + f / 100) ** n
            ok = m.group(1) == ci_money(ci_cents(want))
        else:
            raise Fail(f"can't judge the line {t!r}")
        if not ok:
            return i
    return None


E17RV_PREV = SITUATION_CHECKS["compound-interest"]
E17RV_PREV_SPOT = SPOT_CHECKS.get("compound-interest")


def E17RV_entry(q):
    return E17RV_check(q) if q["view"]["unknown"] in E17RV_UNKNOWNS else E17RV_PREV(q)


def E17RV_spot_entry(q, lines):
    if q["view"]["unknown"] in E17RV_UNKNOWNS:
        return E17RV_spot(q, lines)
    return E17RV_PREV_SPOT(q, lines)


SITUATION_CHECKS["compound-interest"] = E17RV_entry
SPOT_CHECKS["compound-interest"] = E17RV_spot_entry



# ── show-that-value, t1-ext-numerical-show-that (FAL-780) ───
# The statement is read back from the question and checked true with SymPy (exactly, or to the
# nearest cent for an investment). The one valid working is written again here from the givens and
# its arithmetic redone; each tagged option is rebuilt from its slip and shown not to reach the
# result, or to reach it without a derivation. An error-spot's first wrong line is the first that
# starts from the value to be shown, or that rounds before the cents are known.

E17ST_SK = "SL1.6.numerical-show-that#"
E17ST_OWN = "t1-ext-numerical-show-that#"
E17ST_SUB = str.maketrans("0123456789", "₀₁₂₃₄₅₆₇₈₉")
E17ST_UNSUB = str.maketrans("₀₁₂₃₄₅₆₇₈₉", "0123456789")
E17ST_WHO = ("Kira", "Tomas", "Ines", "The caravan fund")


def E17ST_s(letter, n):
    return letter + str(n).translate(E17ST_SUB)


def E17ST_br(v):
    return str(v) if v >= 0 else f"(−{-v})"


def E17ST_check(q):
    u, L = q["view"]["unknown"], q["lines"]
    if "A student's working:" in L:
        L = L[:L.index("A student's working:")]
    need(q["asked"] == "Which working shows this?", f"asked {q['asked']!r}")
    need(q["paper"] == (2 if u == "interest-value" else 1), f"Paper {q['paper']} for {u}")
    wr = {}
    if u == "log-difference":
        m = re.fullmatch(r"Show that log([₀-₉]+) (\d+) − log\1 (\d+) = (\d+)\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        b, P, Q_, k = int(m.group(1).translate(E17ST_UNSUB)), int(m.group(2)), int(m.group(3)), int(m.group(4))
        need(b in (2, 3, 5) and 2 <= Q_ <= 12 and 4 <= b ** k <= 125 and 2 <= k, f"{L[0]} breaks the limits")
        need(sp.factorint(Q_).keys() != {b}, f"{Q_} is a power of {b}")
        need(sp.simplify(sp.log(P, b) - sp.log(Q_, b) - k) == 0, "the statement is false")
        lg = "log" + str(b).translate(E17ST_SUB)
        stmt = f"{lg} {P} − {lg} {Q_} = {k}"
        want = f"{lg} {P} − {lg} {Q_} = {lg}({P}/{Q_}) = {lg} {P // Q_} = {lg}({b}^{k}) = {k}"
        need(P % Q_ == 0 and P // Q_ == b ** k, "the working's quotient is not a power of the base")
        need(abs(math.log(P) / math.log(Q_) - k) > 1e-6, "dividing the logs gives the answer too")
        wr[E17ST_SK + "0"] = {f"If it is {k}, then {b}^{k} × {Q_} = {P}, which is true, so the statement holds"}
        wr[E17ST_SK + "1"] = {f"{stmt}, as required"}
        wr[E17ST_OWN + "3"] = {f"{lg} {P} − {lg} {Q_} = {lg} {P} ÷ {lg} {Q_} = {k}"}
    elif u == "series-sum":
        if q["view"]["rep"] == "words":
            m1 = re.fullmatch(r"A stack of crates has (\d+) in its top row, and each row below has (\d+) more than the row above\.", L[0])
            m2 = re.fullmatch(r"Show that (\d+) rows hold (\d+) crates in all\.", L[1])
            need(m1 is not None and m2 is not None, f"can't read {L!r}")
            u1, d, n, V = int(m1.group(1)), int(m1.group(2)), int(m2.group(1)), int(m2.group(2))
        else:
            m1 = re.fullmatch(r"The sequence (\d+), (\d+), (\d+), … is arithmetic\.", L[0])
            m2 = re.fullmatch(r"Show that the sum of its first (\d+) terms is (\d+)\.", L[1])
            need(m1 is not None and m2 is not None, f"can't read {L!r}")
            t = [int(m1.group(i)) for i in (1, 2, 3)]
            need(t[1] - t[0] == t[2] - t[1], "the sequence is not arithmetic")
            u1, d, n, V = t[0], t[1] - t[0], int(m2.group(1)), int(m2.group(2))
        need(1 <= u1 <= 12 and 2 <= d <= 9 and 8 <= n <= 20, "the sequence breaks the limits")
        need(sum(u1 + i * d for i in range(n)) == V, "the stated sum is false")
        inner = 2 * u1 + (n - 1) * d
        Sn = E17ST_s("S", n)
        want = f"{Sn} = {n}/2 × (2 × {u1} + {n - 1} × {d}) = {n}/2 × {inner} = {V}"
        un = u1 + (n - 1) * d
        need(n * un != V, "the last term times n gives the sum")
        wr[E17ST_SK + "0"] = {f"Put {Sn} = {V}: {V} = {n}/2 × {inner}, which is true"}
        wr[E17ST_SK + "1"] = {f"{Sn} = {V}, as required"}
        wr[E17ST_OWN + "4"] = {f"{Sn} = {n} × {E17ST_s('u', n)} = {n} × {un} = {n * un}"}
    elif u == "common-difference":
        m1 = re.fullmatch(r"In an arithmetic sequence, u([₀-₉]+) = (−?\d+) and u([₀-₉]+) = (−?\d+)\.", L[0])
        m2 = re.fullmatch(r"Show that the common difference is (\d+)\.", L[1])
        need(m1 is not None and m2 is not None, f"can't read {L!r}")
        p, A, qq, B = int(m1.group(1).translate(E17ST_UNSUB)), int(m1.group(2).replace("−", "-")), int(m1.group(3).translate(E17ST_UNSUB)), int(m1.group(4).replace("−", "-"))
        D = int(m2.group(1))
        need(qq - p >= 3 and sp.Rational(B - A, qq - p) == D, "the stated difference is false")
        gap, W = qq - p, B - A
        up, uq = E17ST_s("u", p), E17ST_s("u", qq)
        want = f"{uq} − {up} = {gap}d, so {gap}d = {E17_n(B)} − {E17ST_br(A)} = {W} and d = {W}/{gap} = {D}"
        need(sp.Rational(W, qq) != D, "the wrong divisor gives the answer")
        wr[E17ST_SK + "0"] = {f"With d = {D}, {uq} = {E17_n(A)} + {gap} × {D} = {E17_n(B)}, which is true"}
        wr[E17ST_SK + "1"] = {f"The terms go up evenly, so d = {D}"}
        wr[E17ST_OWN + "5"] = {f"d = ({E17_n(B)} − {E17ST_br(A)})/{qq} = {W}/{qq} = {E17_n(sp.Rational(W, qq))}"}
    elif u == "interest-value":
        m1 = re.fullmatch(r"(.+) invests \$(\d+) in an account that pays ([\d.]+)% per year, compounded annually\.", L[0])
        m2 = re.fullmatch(r"Show that the value after (\d+) years is \$([\d.]+), to the nearest cent\.", L[1])
        need(m1 is not None and m2 is not None, f"can't read {L!r}")
        need(m1.group(1) in E17ST_WHO, f"who {m1.group(1)!r}")
        pv, r, n, V = int(m1.group(2)), R(m1.group(3)), int(m2.group(1)), R(m2.group(2))
        need(pv % 100 == 0 and 500 <= pv <= 5000 and 2 <= r <= 9 and (2 * r).q == 1 and 3 <= n <= 8, "the investment breaks the limits")
        exact = pv * (1 + r / 100) ** n
        need(ci_clear(exact) and ci_cents(exact) == V and V.q != 1, f"${V} is not the value to the nearest cent, or is too close to an edge")
        factor = dec_text(1 + r / 100)
        mr = re.fullmatch(rf"{pv} × {re.escape(factor)}\^{n} = (\d+\.\d{{4}}), which is \${re.escape(ci_money(V))} to the nearest cent", q["answer_text"])
        need(mr is not None and abs(R(mr.group(1)) - exact) <= sp.Rational(1, 20000) + sp.Rational(1, 10 ** 9), f"the right working {q['answer_text']!r} is not the value to 4 decimal places")
        want = q["answer_text"]
        back = ci_cents(V / (1 + r / 100) ** n)
        need(back == pv, "working back from the given value doesn't land on the amount invested")
        dollars = int(sp.floor(exact + sp.Rational(1, 2)))
        wr[E17ST_SK + "0"] = {f"{ci_money(V)} ÷ {factor}^{n} = {pv}.00, the amount invested, so ${ci_money(V)} is right"}
        wr[E17ST_SK + "1"] = {f"After {n} years the value is ${ci_money(V)}"}
        wr[E17ST_SK + "2"] = {f"{pv} × {factor}^{n} = {dollars} to the nearest dollar, so the value is ${ci_money(V)}"}
    else:
        m = re.fullmatch(r"Verify that x = (−?\d+) is a solution of (.+) = 0\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        r = int(m.group(1).replace("−", "-"))
        f = E17_expr(m.group(2))
        need(f is not None and sp.Poly(f, E17_X).degree() == 2 and f.subs(E17_X, r) == 0, "x = r does not solve it")
        a, b, c = (int(v) for v in sp.Poly(f, E17_X).all_coeffs())
        need(1 <= a <= 3 and b != 0 and c != 0 and abs(r) <= 6, "the quadratic breaks the limits")
        sign = lambda v: "+" if v > 0 else "−"
        coef = lambda v: "" if abs(v) == 1 else str(abs(v))
        sub_text = f"{'' if a == 1 else a}({E17_n(r)})² {sign(b)} {coef(b)}({E17_n(r)}) {sign(c)} {abs(c)}"
        t1, t2 = a * r * r, b * r
        parts = f"{t1} {'+' if t2 >= 0 else '−'} {abs(t2)} {sign(c)} {abs(c)}"
        want = f"{sub_text} = {parts} = 0, so x = {E17_n(r)} is a solution"
        need(t1 + t2 != 0, "leaving out c gives 0")
        no_c = f"{'' if a == 1 else a}({E17_n(r)})² {sign(b)} {coef(b)}({E17_n(r)})"
        wr[E17ST_SK + "1"] = {f"x = {E17_n(r)} is a solution of the equation"}
        wr[E17ST_OWN + "6"] = {f"{sub_text}, so x = {E17_n(r)} is a solution"}
        wr[E17ST_OWN + "7"] = {f"{no_c} = {E17_n(t1 + t2)}, so x = {E17_n(r)} is a solution"}
    gc_check_common(q, want, wr)
    E17_steps(q, {})
    E17_no_hyphen(q)
    return None, None


def E17ST_spot(q, lines):
    u = q["view"]["unknown"]
    L = q["lines"][:q["lines"].index("A student's working:")]
    if u == "series-sum":
        V = int(re.search(r"(\d+)(?: crates in all|)\.$", L[1]).group(1))
        for i, t in enumerate(lines):
            if t.startswith("The first term is"):
                continue
            if re.fullmatch(rf"S[₀-₉]+ = {V}", t) or t.startswith(f"{V} = "):
                return i
            raise Fail(f"can't judge the line {t!r}")
        return None
    m1 = re.fullmatch(r"(.+) invests \$(\d+) in an account that pays ([\d.]+)% per year, compounded annually\.", L[0])
    n = int(re.search(r"after (\d+) years", L[1]).group(1))
    pv, r = int(m1.group(2)), R(m1.group(3))
    exact = pv * (1 + r / 100) ** n
    for i, t in enumerate(lines):
        if re.fullmatch(rf"(?:Value = |= ){pv} × (?:\(1 \+ [\d.]+/100\)|[\d.]+)\^{n}", t):
            ok = E17_holds("x = " + t.split("= ", 1)[1], {E17_X: exact})
        elif (m := re.fullmatch(r"= ([\d.]+)(?:, as required\.)?", t)):
            places = len(m.group(1).split(".")[1]) if "." in m.group(1) else 0
            ok = places >= 4 and abs(R(m.group(1)) - exact) <= sp.Rational(1, 20000)
        elif t.startswith("So the value is"):
            ok = True
        else:
            raise Fail(f"can't judge the line {t!r}")
        if not ok:
            return i
    return None


SITUATION_CHECKS["show-that-value"] = E17ST_check
SPOT_CHECKS["show-that-value"] = E17ST_spot


# ── binomial-expansion, t1-ext-binomial-constant-term and t1-ext-binomial-product (FAL-779) ──
# The checker's own copy of the clean limits: the engine's is in
# game/engine/situations/binomial_expansion.gd. Each bracket is read back from the question's
# words, expanded with SymPy, and the coefficient asked is read off the expansion, so nothing is
# taken from the engine. Every tagged option is rebuilt from its slip, every equation in the
# working must hold (at the r found, where there is one), and an error-spot's first wrong line is
# the first whose equation or claim fails. Every other unknown goes to the exam type's checks.

E16A_X, E16A_R, E16A_K = sp.symbols("x r k")
E16A_SUPS = str.maketrans("⁰¹²³⁴⁵⁶⁷⁸⁹⁻", "0123456789-")
E16A_SUP = "[⁰¹²³⁴⁵⁶⁷⁸⁹⁻]+"
E16A_HAND, E16A_MOST = 20000, 200000
E16A_SPLIT = re.compile(r", so |, and |, which gives |; |: | gives |, which is ")


def E16A_stop(t):
    """A full stop off the end, but not the dots of '+ ...'."""
    t = t.strip()
    return t if t.endswith("...") else t.rstrip(".").strip()


def E16A_sup(t):
    return int(t.translate(E16A_SUPS)) if t else 1


def E16A_n(v):
    """A rational as the game writes it: 3, −4, 8/5."""
    v = sp.Rational(v)
    s = str(abs(v.p)) if v.q == 1 else f"{abs(v.p)}/{v.q}"
    return ("−" if v < 0 else "") + s


def E16A_term(c, j):
    """c·x^j as the game writes it: 810x⁷, −80x, x⁻³, 45."""
    c = sp.Integer(c)
    if j == 0:
        return E16A_n(c)
    sup = "" if j == 1 else str(j).translate(str.maketrans("0123456789-", "⁰¹²³⁴⁵⁶⁷⁸⁹⁻"))
    head = "" if abs(c) == 1 else str(abs(c))
    return ("−" if c < 0 else "") + head + "x" + sup


def E16A_expr(text, letters=("x", "r", "k")):
    """A piece of working as SymPy, or None where it has words in it or a letter not allowed."""
    t = text.strip().rstrip(".").strip()
    if not t or re.search(r"[A-Z]", re.sub(r"(\d+)C(\d+|r)", "", t)):
        return None
    t = re.sub(E16A_SUP, lambda mt: "**(" + mt.group(0).translate(E16A_SUPS) + ")", t)
    t = re.sub(r"(\d+)C(\d+|r)", r"binomial(\1,\2)", t)
    t = t.replace("−", "-").replace("×", "*").replace("÷", "/").replace("^", "**")
    if not re.fullmatch(r"[0-9a-z+\-*/(), ]+", t.replace("binomial", "")):
        return None
    if any(ch not in letters for ch in set(re.findall(r"[a-z]", t.replace("binomial", "")))):
        return None
    local = {"x": E16A_X, "r": E16A_R, "k": E16A_K, "binomial": sp.binomial}
    try:
        e = parse_expr(t, local_dict=local, transformations=TRANSFORMS, evaluate=True)
    except Exception:
        return None
    if not all(str(s) in letters for s in e.free_symbols):
        return None
    return e


def E16A_series(text, letters):
    """A side that ends '+ ...': its terms, as {power: coefficient}, and that it is cut short."""
    t = E16A_stop(text)
    cut = t.endswith("+ ...")
    e = E16A_expr(t[:-5] if cut else t, letters)
    return e, cut


def E16A_powers(e):
    out = {}
    for t in sp.Add.make_args(sp.expand(e)):
        c, p = t.as_coeff_exponent(E16A_X)
        out[p] = out.get(p, 0) + c
    return {p: c for p, c in out.items() if c != 0}


def E16A_sides(frag, letters):
    """The sides of 'A = B = C' as SymPy: the first side its longest readable end, the last its
    longest readable start; None when a side can't be read."""
    parts = frag.split(" = ")
    out = []
    for i, p in enumerate(parts):
        words = E16A_stop(p).split(" ")
        got = None
        if i == 0:
            for s in range(len(words)):
                cand = " ".join(words[s:])
                got = E16A_series(cand, letters)
                if got[0] is not None:
                    break
        elif i == len(parts) - 1:
            for s in range(len(words), 0, -1):
                cand = " ".join(words[:s])
                got = E16A_series(cand, letters)
                if got[0] is not None:
                    break
        else:
            got = E16A_series(p, letters)
        if got is None or got[0] is None:
            return None
        out.append(got)
    return out


def E16A_judge(line, subs, letters=("x", "r", "k")):
    """(judged, true): every readable equation in the line, at each of subs."""
    judged = 0
    for frag in E16A_SPLIT.split(E16A_stop(line)):
        if " = " not in frag:
            continue
        sides = E16A_sides(frag, letters)
        if sides is None:
            continue
        judged += 1
        for (a, ca), (b, cb) in zip(sides, sides[1:]):
            if ca or cb:
                full, part = (b, a) if ca else (a, b)
                for sb in subs:
                    pf = E16A_powers(full.subs({k: v for k, v in sb.items() if k != E16A_X}))
                    pp = E16A_powers(part.subs({k: v for k, v in sb.items() if k != E16A_X}))
                    if not pp or any(pf.get(p) != c for p, c in pp.items()):
                        return judged, False
                    lo, hi = min(pp), max(pp)
                    if any(lo <= p <= hi and p not in pp for p in pf):
                        return judged, False
                continue
            for sb in subs:
                d = sp.simplify((a - b).subs(sb))
                if d != 0:
                    return judged, False
    return judged, True


def E16A_steps(q, subs, letters=("x", "r", "k")):
    for sol in q["solutions"]:
        for st in sol["steps"]:
            need(E16A_judge(st, subs, letters)[1], f"{sol['name']}: {st!r} is not true")


def E16A_no_hyphen(q):
    texts = [q["asked"], q.get("prompt", "")] + q["lines"] + [o["text"] for o in q["choices"]] + [st for sol in q["solutions"] for st in sol["steps"]]
    for t in texts:
        need(not re.search(r"(?<![A-Za-z])-\d", t), f"a hyphen for a minus in {t!r}")


def E16A_coef(e, j):
    return E16A_powers(e).get(j, sp.Integer(0))


# ── t1-ext-binomial-constant-term ──

E16BC_MAP = "SL1.9.constant-term#"
E16BC_OWN = "t1-ext-binomial-constant-term#"
E16BC_UNKNOWNS = ("ct-power-of-x", "ct-find-r", "ct-middle-constant", "ct-constant", "ct-constant-raised", "ct-given-power")
E16BC_BRACKET = re.compile(rf"\((\d*)x({E16A_SUP})? ([+−]) (\d+)/x({E16A_SUP})?\)({E16A_SUP})")
# The skill map's examples: (a, p, k, q, n, m).
E16BC_SKILL_MAP = {(1, 1, 2, 1, 6, 0), (1, 2, -1, 1, 9, 0), (2, 2, 1, 1, 6, 3)}


def E16BC_read(q):
    m = E16BC_BRACKET.search(q["asked"])
    need(m is not None, f"no bracket in {q['asked']!r}")
    a = int(m.group(1)) if m.group(1) else 1
    p, qq, n = E16A_sup(m.group(2)), E16A_sup(m.group(5)), E16A_sup(m.group(6))
    k = int(m.group(4)) * (1 if m.group(3) == "+" else -1)
    return a, p, k, qq, n


def E16BC_general(a, p, k, qq, n):
    return sp.binomial(n, E16A_R) * (a * E16A_X**p)**(n - E16A_R) * (k / E16A_X**qq)**E16A_R


def E16BC_check(q):
    u, paper = q["view"]["unknown"], q["paper"]
    a, p, k, qq, n = E16BC_read(q)
    x, r = E16A_X, E16A_R
    most = E16A_HAND if paper == 1 else E16A_MOST
    need(1 <= p <= 3 and qq in (1, 2) and 2 <= abs(k) <= 4 and 3 <= n <= 10 and 1 <= a <= 3, f"the bracket ({a}, {p}, {k}, {qq}, {n}) breaks the limits")
    need(not (a % 2 == 0 and k % 2 == 0) and not (a % 3 == 0 and k % 3 == 0), "the bracket has a common factor")
    expansion = sp.expand((a * x**p + k / x**qq)**n)
    power = p * (n - r) - qq * r
    wr = {}
    if u == "ct-power-of-x":
        mt = re.search(r" is (.+)\. Find the power of x", q["asked"])
        need(mt is not None, "no general term")
        g = E16A_expr(mt.group(1))
        need(g is not None and all(sp.simplify(g.subs(r, v) - E16BC_general(a, p, k, qq, n).subs(r, v)) == 0 for v in range(n + 1)), "the general term shown is not the bracket's")
        need(a == 1 and (a, p, k, qq, n, 0) not in E16BC_SKILL_MAP, "a number beside x, or the skill map's example")
        fmt = lambda top, c: f"{top} − {'' if c == 1 else c}r"
        want = fmt(p * n, p + qq)
        need(sp.expand(E16A_expr(want) - power) == 0, "the power of x is not the general term's")
        wr[E16BC_MAP + "0"] = {fmt(p * n, p)}
        if p > 1:
            wr[E16BC_OWN + "4"] = {fmt(n, 1 + qq)}
        gc_check_common(q, want, wr)
        E16A_steps(q, [{x: 2, r: 3}, {x: 3, r: 5}])
        E16A_no_hyphen(q)
        return None, None
    m = 0
    if u == "ct-given-power":
        mt = re.search(rf"coefficient of x({E16A_SUP})? in", q["asked"])
        need(mt is not None, "no power asked")
        m = E16A_sup(mt.group(1))
        need(m != 0 and abs(m) <= 9, f"x^{m} breaks the limits")
    roots = sp.solve(sp.Eq(power, m), r)
    need(len(roots) == 1 and roots[0].is_Integer and 1 <= roots[0] <= n - 1, f"no whole r from 1 to n − 1 gives x^{m}")
    r0 = int(roots[0])
    need((a, p, k, qq, n, m) not in E16BC_SKILL_MAP, "the skill map's example")
    need((p == qq) == (u == "ct-middle-constant"), "symmetric powers only for the middle term")
    if u == "ct-middle-constant":
        need(a == 1 and n % 2 == 0 and r0 == n // 2, "the middle term is not at r = n/2")
    if u in ("ct-find-r", "ct-constant", "ct-middle-constant"):
        need(a == 1, "a number beside x")
    if u == "ct-constant-raised":
        need(a >= 2 and n - r0 >= 2, "the number beside x is not raised to at least 2")
    if u == "ct-constant":
        need(r0 >= 2, "r is 1, so the top unraised is no slip")
    c = E16A_coef(expansion, m)
    need(c == sp.binomial(n, r0) * a**(n - r0) * k**r0, "the coefficient is not nCr a^(n − r) k^r")
    if u == "ct-find-r":
        want = f"r = {r0}"
        wr[E16BC_MAP + "0"] = {f"r = {n - sp.Rational(m, p)}"}
        wr[E16BC_OWN + "3"] = {f"r = {n - r0}"}
        if p > 1:
            wr[E16BC_OWN + "4"] = {f"r = {E16A_n(v)}" for v in sp.solve(sp.Eq(n - r - qq * r, 0), r)}
    else:
        need(abs(c) <= most, f"the coefficient {c} is too large for Paper {paper}")
        want = E16A_n(c)
        slip = n - sp.Rational(m, p)
        if slip.is_Integer and 0 <= slip <= n:
            # The fraction's x left out: p(n − r) = m.
            wr[E16BC_MAP + "0"] = {E16A_n(E16A_coef(sp.expand((a * x**p + k)**n), p * (n - slip)))}
        wr[E16BC_MAP + "1"] = {E16A_n(sp.binomial(n, r0) * a**(n - r0))}
        wr[E16BC_MAP + "2"] = {E16A_n(r0)}
        if c < 0:
            wr[E16BC_OWN + "5"] = {E16A_n(-c)}
        if a > 1:
            wr[E16BC_OWN + "6"] = {E16A_n(sp.binomial(n, r0) * a * k**r0)}
        if u == "ct-given-power":
            wr[E16BC_OWN + "7"] = {E16A_term(c, m)}
    gc_check_common(q, want, wr)
    E16A_steps(q, [{x: 2, r: r0}, {x: 3, r: r0}])
    E16A_no_hyphen(q)
    return None, None


def E16BC_spot(q, lines):
    a, p, k, qq, n = E16BC_read(q)
    x, r = E16A_X, E16A_R
    power = p * (n - r) - qq * r
    r0 = int(sp.solve(sp.Eq(power, 0), r)[0])
    const = sp.binomial(n, r0) * a**(n - r0) * k**r0
    gen = E16BC_general(a, p, k, qq, n)
    for i, t in enumerate(lines):
        ok = True
        judged, holds = E16A_judge(t, [{x: 2, r: r0}, {x: 3, r: r0}])
        ok = ok and holds
        if (mt := re.fullmatch(r"The general term is (.+)", t)):
            g = E16A_expr(mt.group(1))
            ok = ok and g is not None and all(sp.simplify(g.subs(r, v) - gen.subs(r, v)) == 0 for v in range(n + 1))
            judged += 1
        if (mt := re.fullmatch(r"(?:So the|The) power of x is (.+?)(?: = .*)?", t)):
            e = E16A_expr(mt.group(1))
            ok = ok and e is not None and sp.expand(e - power) == 0
            judged += 1
        if (mt := re.fullmatch(r"The constant term needs (.+) = 0", t)):
            e = E16A_expr(mt.group(1))
            ok = ok and e is not None and sp.expand(e - power) == 0
            judged += 1
        if (mt := re.fullmatch(r"The constant term is (?:.+ = )?(−?\d+)", t)):
            ok = ok and int(mt.group(1).replace("−", "-")) == const
            judged += 1
        need(judged > 0, f"can't judge the line {t!r}")
        if not ok:
            return i
    return None


# ── t1-ext-binomial-product ──

E16BP_MAP = "SL1.9.product-expansion#"
E16BP_OWN = "t1-ext-binomial-product#"
E16BP_UNKNOWNS = ("pr-linear", "pr-same-power", "pr-hence", "pr-reciprocal", "pr-find-k", "pr-small")
E16BP_PRODUCT = re.compile(rf"\(([^()]+)\)\(([^()]+)\)({E16A_SUP})")
# The skill map's examples: (first bracket, expansion's bracket, n, m).
E16BP_SKILL_MAP = {("1 + 2x", "3 − x", 5, 2), ("2 − x", "1 + x", 6, 3), ("x² + 1", "x − 2/x", 4, 0)}


def E16BP_read(q):
    m = E16BP_PRODUCT.search(q["asked"])
    need(m is not None, f"no product in {q['asked']!r}")
    first = E16A_expr(m.group(1), ("x", "k"))
    inner = E16A_expr(m.group(2), ("x",))
    need(first is not None and inner is not None, f"can't read {m.group(0)!r}")
    return m.group(1), m.group(2), first, inner, E16A_sup(m.group(3))


def E16BP_check(q):
    u, paper = q["view"]["unknown"], q["paper"]
    x, k = E16A_X, E16A_K
    ftext, itext, first, inner, n = E16BP_read(q)
    most = E16A_HAND if paper == 1 else E16A_MOST
    mt = re.search(rf"(?:coefficient of x({E16A_SUP})?|constant term) in", q["asked"])
    need(mt is not None, "no power asked")
    m = 0 if "constant term in" in mt.group(0) else E16A_sup(mt.group(1))
    need((ftext, itext, n, m) not in E16BP_SKILL_MAP, "the skill map's example")
    ex = sp.expand(inner**n)
    c = lambda j: E16A_coef(ex, j)
    wr = {}
    if u == "pr-reciprocal":
        need(n in (4, 6, 8), f"n = {n} is not even from 4 to 8")
        fp = E16A_powers(first)
        need(set(fp) == {2, 0} and fp[2] == 1, f"{ftext} is not x² + c")
        ip = E16A_powers(inner)
        need(set(ip) == {1, -1} and ip[1] == 1 and abs(ip[-1]) in (2, 3), f"{itext} is not x + k/x")
        cc = fp[0]
        pairs = [c(-2), cc * c(0)]
        v = E16A_coef(sp.expand(first * ex), 0)
        need(v == sum(pairs), "the two pairs don't add up to the constant term")
        wr[E16BP_MAP + "0"] = {E16A_n(cc * c(0))}
        wr[E16BP_OWN + "5"] = {E16A_n(c(2) + cc * c(0))}
        wr[E16BP_MAP + "2"] = {E16A_n(abs(pairs[0]) + abs(pairs[1]))}
        want = E16A_n(v)
        letters = ("x",)
    else:
        ip = E16A_powers(inner)
        need(set(ip) == {0, 1}, f"{itext} is not a + bx")
        ea, eb = ip[0], ip[1]
        need(1 <= ea <= 3 and 1 <= abs(eb) <= 3 and sp.gcd(ea, eb) == 1, f"{itext} breaks the limits")
        need(u == "pr-small" or not (ea == 1 and abs(eb) == 1), "(1 ± x) outside the small expansions")
        need((3 <= n <= 4) if u == "pr-small" else (5 <= n <= 8), f"n = {n} breaks the limits")
        if u == "pr-find-k":
            fp = E16A_powers(first.subs(k, 0))
            need(set(fp) == {0} and fp[0] == 1 and sp.expand(first - 1 - k * x) == 0, f"{ftext} is not 1 + kx")
            mv = re.search(r" is (−?\d+)\. Find the value of k\.", q["asked"])
            V = int(mv.group(1).replace("−", "-"))
            sol = sp.solve(sp.Eq(E16A_coef(sp.expand(first * ex), m), V), k)
            need(len(sol) == 1 and sol[0].is_Integer and 2 <= abs(sol[0]) <= 5, f"k = {sol} is not a whole number from 2 to 5 in size")
            K = sol[0]
            need(2 <= m <= n - 1 and c(m) != c(m - 1) and c(m) + K * c(m - 1) == V and K * c(m - 1) != 0, "the pairs break the limits")
            need(all(abs(t) <= most for t in (c(m), K * c(m - 1), V)), "a coefficient is too large")
            wr[E16BP_MAP + "0"] = {f"k = {E16A_n(sp.Rational(V, c(m - 1)))}"}
            if eb < 0:
                pos = sp.expand((ea - eb * x)**n)
                wr[E16BP_MAP + "2"] = {f"k = {E16A_n(sp.Rational(V - E16A_coef(pos, m), E16A_coef(pos, m - 1)))}"}
            wr[E16BP_OWN + "3"] = {f"k = {E16A_n(sp.Rational(V - c(m), c(m)))}"}
            want = f"k = {E16A_n(K)}"
            letters = ("x", "k")
            gc_check_common(q, want, wr)
            E16A_steps(q, [{x: 2, k: K}, {x: 3, k: K}], letters)
            E16A_no_hyphen(q)
            return None, None
        fp = E16A_powers(first)
        need(len(fp) == 2 and 0 in fp, f"{ftext} is not p + qx^d")
        d = max(fp)
        fa, fb = fp[0], fp[d]
        need(1 <= fa <= 4 and 1 <= abs(fb) <= 4 and sp.gcd(fa, fb) == 1 and fa + fb != 0, f"{ftext} breaks the limits")
        need(d == 1 or u == "pr-same-power", "x² in the first bracket")
        if u == "pr-same-power":
            need(m == d, "the power asked is not the first bracket's")
        else:
            need((1 <= m <= n) if u == "pr-small" else (2 <= m <= n - 1), f"x^{m} breaks the limits")
            need(c(m) != c(m - 1), "pairing x with the x^m term gives the answer")
        pairs = [fa * c(m), fb * c(m - d)]
        v = E16A_coef(sp.expand(first * ex), m)
        need(v == sum(pairs) and pairs[0] != 0 and pairs[1] != 0 and v != 0, "a pair or the answer is 0")
        need(all(abs(t) <= most for t in pairs + [v]), "a coefficient is too large")
        wr[E16BP_MAP + "0"] = {E16A_n(pairs[0])}
        wr[E16BP_MAP + "2"] = {E16A_n(abs(pairs[0]) + abs(pairs[1]))}
        if u == "pr-same-power":
            wr[E16BP_MAP + "1"] = {E16A_n(fb * c(m))}
        else:
            wr[E16BP_OWN + "3"] = {E16A_n((fa + fb) * c(m))}
        if u == "pr-hence":
            ml = re.fullmatch(rf"In the expansion of \({re.escape(itext)}\){E16A_SUP}, the coefficient of x({E16A_SUP})? is (−?\d+) and the coefficient of x({E16A_SUP})? is (−?\d+)\.", q["lines"][0])
            need(ml is not None, f"can't read {q['lines'][0]!r}")
            need(E16A_sup(ml.group(1)) == m and E16A_sup(ml.group(3)) == m - 1, "the coefficients given are not of x^m and x^(m − 1)")
            given = [int(ml.group(2).replace("−", "-")), int(ml.group(4).replace("−", "-"))]
            need(given == [c(m), c(m - 1)], f"the coefficients given {given} are not the expansion's")
            wr[E16BP_OWN + "4"] = {E16A_n(c(m) + c(m - 1))}
        want = E16A_n(v)
        letters = ("x",)
    gc_check_common(q, want, wr)
    E16A_steps(q, [{x: 2}, {x: 3}], letters)
    E16A_no_hyphen(q)
    return None, None


def E16BP_spot(q, lines):
    x = E16A_X
    ftext, itext, first, inner, n = E16BP_read(q)
    m = E16A_sup(re.search(rf"coefficient of x({E16A_SUP})? in", q["asked"]).group(1))
    ex = sp.expand(inner**n)
    v = E16A_coef(sp.expand(first * ex), m)
    for i, t in enumerate(lines):
        judged, ok = E16A_judge(t, [{x: 2}, {x: 3}], ("x",))
        if (mt := re.fullmatch(rf"The (x{E16A_SUP}?|constant) term of \((.+?)\)({E16A_SUP}) is (.+)", t)):
            j = 0 if mt.group(1) == "constant" else E16A_sup(mt.group(1)[1:])
            e = E16A_expr(mt.group(2), ("x",))
            last = E16A_expr(mt.group(4).split(" = ")[-1], ("x",))
            ok = ok and e is not None and last is not None and sp.expand(last - E16A_coef(sp.expand(e**E16A_sup(mt.group(3))), j) * x**j) == 0
            judged += 1
        if (mt := re.fullmatch(rf"The (x{E16A_SUP}?) terms add to (.+)", t)):
            last = E16A_expr(mt.group(2).split(" = ")[-1], ("x",))
            ok = ok and last is not None and sp.expand(last - v * x**m) == 0
            judged += 1
        if (mt := re.fullmatch(rf"So the coefficient of x({E16A_SUP})? is (−?\d+)", t)):
            ok = ok and E16A_sup(mt.group(1)) == m and int(mt.group(2).replace("−", "-")) == v
            judged += 1
        need(judged > 0, f"can't judge the line {t!r}")
        if not ok:
            return i
    return None


E16A_PREV = SITUATION_CHECKS["binomial-expansion"]
E16A_PREV_SPOT = SPOT_CHECKS.get("binomial-expansion")


def E16A_entry(q):
    u = q["view"]["unknown"]
    if u in E16BC_UNKNOWNS:
        return E16BC_check(q)
    if u in E16BP_UNKNOWNS:
        return E16BP_check(q)
    return E16A_PREV(q)


def E16A_spot_entry(q, lines):
    u = q["view"]["unknown"]
    if u in E16BC_UNKNOWNS:
        return E16BC_spot(q, lines)
    if u in E16BP_UNKNOWNS:
        return E16BP_spot(q, lines)
    need(E16A_PREV_SPOT is not None, "the checker has no error-spot checks for this unknown")
    return E16A_PREV_SPOT(q, lines)


SITUATION_CHECKS["binomial-expansion"] = E16A_entry
SPOT_CHECKS["binomial-expansion"] = E16A_spot_entry


# ── E16 shared (FAL-779) ─────────────────────────────────────
# Tools the E16 sections of this lane share: a side of a line of working read with SymPy (with
# the question's own letters put in, or left free where the line is an identity in them), and a
# check that every =, < and > a line states holds. A Σ with its limits, or a bare Σ on the
# question's limits, is summed first.

E16B_LEAD = re.compile(r"^(?:So |Need |Then |and |but |which gives |Check: )+")
E16B_SPLIT = re.compile(r", so |, but |, and |; |: | and | needs | means | gives |, as |, where |, ")
E16B_REL = re.compile(r" (=|<|>) ")
E16B_SUP = str.maketrans("⁰¹²³⁴⁵⁶⁷⁸⁹⁻", "0123456789-")
E16B_SUBS = str.maketrans("₀₁₂₃₄₅₆₇₈₉", "0123456789")
E16B_DEC = re.compile(r"\d+\.(\d+)")
E16B_SIGMA = re.compile(r"Σ \((\w) = (\S+) to (\S+)\) \(([^()]*)\)")
E16B_BARE_SIGMA = re.compile(r"Σ(\([^()]*\)|[0-9]+|[a-z])")


def E16B_q(text):
    """'−3/2' or '0.65' as an exact Rational."""
    return sp.Rational(text.strip().replace("−", "-"))


def E16B_expr(text, subs, free=()):
    """A side as SymPy with subs put in, or None where it has words or other letters in it."""
    t = E16B_LEAD.sub("", text.strip().rstrip(".").strip()).rstrip("%").strip()
    if not t:
        return None
    t = re.sub("[⁰¹²³⁴⁵⁶⁷⁸⁹⁻]+", lambda m: "**(" + m.group(0).translate(E16B_SUP) + ")", t)
    t = t.replace("−", "-").replace("×", "*").replace("÷", "/").replace("^", "**")
    t = re.sub(r"\bln ([\d.]+)", r"log(\1)", t).replace("ln(", "log(")
    if not re.fullmatch(r"[0-9a-z+\-*/(). ]+", t):
        return None
    bare = t.replace("log", "")
    if re.search(r"[a-z]{2,}", bare):
        return None
    letters = set(re.findall(r"[a-z]", bare))
    if not letters <= set(subs) | set(free):
        return None
    local = {k: sp.Symbol(k) for k in letters}
    local["log"] = sp.log
    try:
        e = parse_expr(t, local_dict=local, transformations=TRANSFORMS + (rationalize,), evaluate=True)
    except Exception:
        return None
    return e.subs({sp.Symbol(k): sp.nsimplify(v) for k, v in subs.items()})


def E16B_sums(line, var_limits):
    """Each Σ in the line replaced by its value. var_limits: (letter, lower, upper) for a bare Σ."""
    def full(m):
        v = sp.Symbol(m.group(1))
        lo, hi = (E16B_expr(x, {}, ("k", "n")) for x in (m.group(2), m.group(3)))
        body = E16B_expr(m.group(4), {}, (m.group(1),))
        if lo is None or hi is None or body is None:
            return m.group(0)
        return "(" + sp.sstr(sp.factor(sp.summation(body, (v, lo, hi)))) + ")"
    out = E16B_SIGMA.sub(full, line)
    if var_limits is not None:
        name, lo, hi = var_limits
        def bare(m):
            inner = m.group(1).strip("()")
            body = E16B_expr(inner, {}, (name,))
            if body is None:
                return m.group(0)
            return "(" + sp.sstr(sp.factor(sp.summation(body, (sp.Symbol(name), lo, hi)))) + ")"
        out = E16B_BARE_SIGMA.sub(bare, out)
    return out


def E16B_holds(line, subs, free=(), limits=None):
    """False if a relation the line states is false at subs; unread ones pass."""
    line = E16B_sums(line, limits)
    for frag in E16B_SPLIT.split(line.rstrip(".")):
        parts = E16B_REL.split(frag)
        sides, ops = parts[0::2], parts[1::2]
        if not ops:
            continue
        es = [E16B_expr(p, subs, free) for p in sides]
        tol = sp.Float(10) ** -25
        rel = sp.Float(0)
        for p in sides:
            p = E16B_LEAD.sub("", p.strip().rstrip(".").rstrip("%").strip())
            mt = re.fullmatch(r"−?\d+\.(\d+)", p)
            if mt:
                tol = max(tol, sp.Float(10) ** -len(mt.group(1)) / 2 + sp.Float(10) ** -12)
            for d in E16B_DEC.finditer(p):
                if len(d.group(0).replace(".", "").lstrip("0")) >= 6:
                    rel = sp.Float(10) ** -5
        for i, op in enumerate(ops):
            a, b = es[i], es[i + 1]
            if a is None or b is None or sides[i].strip() in free or sides[i + 1].strip() in free:
                continue
            if a.free_symbols or b.free_symbols:
                if op != "=":
                    continue
                if sp.simplify(a - b) != 0:
                    return False
                continue
            va, vb = sp.N(a, 40), sp.N(b, 40)
            if not (va.is_real and vb.is_real):
                return False
            if op == "=":
                if abs(va - vb) > tol + rel * abs(vb):
                    return False
            elif (op == "<") != (va < vb):
                return False
    return True


def E16B_first_false(lines, subs, free=(), limits=None):
    for i, t in enumerate(lines):
        if not E16B_holds(t, subs, free, limits):
            return i
    return None


def E16B_steps(q, subs, free=(), limits=None):
    for sol in q["solutions"]:
        for st in sol["steps"]:
            need(E16B_holds(st, subs, free, limits), f"{sol['name']}: {st!r} is not true at the answer")


def E16B_no_hyphen(q):
    texts = [q["asked"], q.get("prompt", "")] + q["lines"] + [o["text"] for o in q["choices"]] + [st for sol in q["solutions"] for st in sol["steps"]]
    for t in texts:
        need(not re.search(r"(?<![A-Za-z])-\d", t), f"a hyphen for a minus in {t!r}")


# ── geometric-sequence, t1-ext-partial-vs-infinite (FAL-779) ─
# u₁ and r are read back from the line (u₁ = 40,  r = 0.8, or four terms whose ratios must agree),
# and the gap, percentage or k from the question. The least n is found by stepping n up with exact
# fractions until S∞ − Sₙ is below the tolerance; the share and the gap after k terms are exact.
# Every tagged option is rebuilt from its slip, every relation in the working must hold at the
# answer, each Sₖ or S∞ − Sₖ written in a step is that value to its figures, and an error-spot's
# first wrong line is the first whose relation fails.

E16PI_MAP = "SL1.8.sn-vs-sinf#"
E16PI_OWN = "t1-ext-partial-vs-infinite#"
E16PI_UNKNOWNS = ("least-n-gap", "least-n-percent", "share-of-sinf", "gap-after-n")
E16PI_R = {sp.Rational(v, 100) for v in (20, 25, 30, 40, 50, 60, 65, 70, 75, 80, 85, 90)}
E16PI_EPS = {sp.Rational(1), sp.Rational(1, 2), sp.Rational(1, 10), sp.Rational(1, 20), sp.Rational(1, 100), sp.Rational(1, 200), sp.Rational(1, 1000)}
E16PI_PCT = {sp.Rational(v, 10) for v in (900, 950, 980, 990, 995, 999)}
E16PI_EDGE = sp.Rational(1, 10)
E16PI_NUM = r"−?\d+(?:\.\d+)?"


def E16PI_series(q):
    L = q["lines"]
    m = re.fullmatch(rf"u₁ = ({E16PI_NUM}),  r = ({E16PI_NUM})", L[0])
    if q["view"]["rep"] == "notation":
        need(m is not None, f"can't read u₁ and r from {L[0]!r}")
        return E16B_q(m.group(1)), E16B_q(m.group(2))
    m = re.fullmatch(rf"({E16PI_NUM}), ({E16PI_NUM}), ({E16PI_NUM}), ({E16PI_NUM}), …", L[0])
    need(m is not None, f"can't read four terms from {L[0]!r}")
    ts = [E16B_q(g) for g in m.groups()]
    r = ts[1] / ts[0]
    need(all(ts[i + 1] == ts[i] * r for i in range(3)), "the terms shown are not geometric")
    return ts[0], r


def E16PI_least(u1, r, tol, first=0):
    """The least n ≥ 1 with u₁ r^(n − first)/(1 − r) < tol."""
    n = 1
    while u1 * r ** (n - first) / (1 - r) >= tol:
        n += 1
        need(n < 500, "no n meets the condition")
    return n


def E16PI_clear(x):
    """x is at least 0.02 of a unit in its third figure from a rounding edge."""
    v = abs(sp.Rational(x))
    e = sp.floor(sp.log(v, 10))
    scaled = v / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= sp.Rational(2, 100)


def E16PI_shown(v, show):
    """A wrong value as the answer's style writes it."""
    if show == "sf":
        return ext_sf(v)
    t = dec_text(v)
    if "/" in t or len(t) > 8:
        t = dec_text(sp.Rational(sig3(v)))
    return t


def E16PI_named(q, u1, r):
    """Each Sₖ = v and S∞ − Sₖ = v a step writes is that value to its figures."""
    sinf = u1 / (1 - r)
    for sol in q["solutions"]:
        for st in sol["steps"]:
            for m in re.finditer(r"(S∞ − )?S([₀-₉]+) = (\d+(?:\.\d+)?)(?![\d.(/]| [×(/−+])", st):
                k = int(m.group(2).translate(E16B_SUBS))
                true = sinf * r ** k if m.group(1) else u1 * (1 - r ** k) / (1 - r)
                shown = sp.Rational(m.group(3))
                places = len(m.group(3).split(".")[1]) if "." in m.group(3) else 0
                close = abs(true - shown) <= sp.Rational(1, 2 * 10 ** places) + sp.Rational(1, 10 ** 12)
                need(close, f"{sol['name']}: {m.group(0)!r} is not S{'∞ − S' if m.group(1) else ''}{k} = {sp.N(true, 12)}")
            m = re.search(r"cross at x = (\d+(?:\.\d+)?)", st)
            if m:
                q_ = q["_e16pi_real"]
                places = len(m.group(1).split(".")[1]) if "." in m.group(1) else 0
                need(abs(q_ - sp.Rational(m.group(1))) <= sp.Rational(1, 2 * 10 ** places) + sp.Rational(1, 10 ** 9), f"the crossing {m.group(1)} is not at {sp.N(q_, 8)}")


def E16PI_check(q):
    u, asked = q["view"]["unknown"], q["asked"]
    need(q["paper"] == 2, "a partial-sum question is not Paper 2")
    u1, r = E16PI_series(q)
    need(r in E16PI_R and u1 > 0 and u1 % 20 == 0 and u1 <= 500, f"u₁ = {u1} and r = {r} are outside the limits")
    sinf = u1 / (1 - r)
    wr = {}
    trap = None
    if u in ("least-n-gap", "least-n-percent"):
        if u == "least-n-gap":
            m = re.search(r"Find the least n for which S∞ − Sₙ < (\d+(?:\.\d+)?)\.", asked)
            need(m is not None, f"can't read the gap from {asked!r}")
            tol = sp.Rational(m.group(1))
            need(tol in E16PI_EPS, f"the gap {tol} is not one of the limits")
        else:
            m = re.search(r"Find the least n for which Sₙ is more than (\d+(?:\.\d+)?)% of S∞\.", asked)
            need(m is not None, f"can't read the percentage from {asked!r}")
            pct = sp.Rational(m.group(1))
            need(pct in E16PI_PCT, f"{pct}% is not one of the limits")
            tol = (1 - pct / 100) * sinf
        n = E16PI_least(u1, r, tol)
        real = sp.log(tol / sinf) / sp.log(r)
        q["_e16pi_real"] = real
        need(4 <= n <= 40 and abs(sp.N(real - sp.floor(real + sp.Rational(1, 2)), 30)) >= E16PI_EDGE, f"n = {n}, crossing {sp.N(real, 8)}: outside the limits")
        need(sinf * r ** n < tol <= sinf * r ** (n - 1), "the least n doesn't meet the condition first")
        # One term below the tolerance: the least m with u₁r^(m − 1) < tol.
        m1 = 1
        while u1 * r ** (m1 - 1) >= tol:
            m1 += 1
        want = f"n = {n}"
        wr[E16PI_MAP + "1"] = {f"n = {n - 1}"}
        wr[E16PI_OWN + "3"] = {f"n = {n + 1}"}
        wr[E16PI_MAP + "2"] = {f"n = {m1}"}
        subs = {"n": n}
    else:
        if u == "share-of-sinf":
            m = re.search(r"Find the percentage of S∞ that the first (\d+) terms give\.", asked)
        else:
            m = re.search(r"Find S∞ − S([₀-₉]+), the part of S∞ still to come after the first (\d+) terms\.", asked)
            need(m is not None and int(m.group(1).translate(E16B_SUBS)) == int(m.group(2)), f"can't read k from {asked!r}")
            m = re.search(r"after the first (\d+) terms", asked)
        need(m is not None, f"can't read k from {asked!r}")
        k = int(m.group(1))
        need(3 <= k <= 8, f"k = {k} is outside 3 to 8")
        need(u != "share-of-sinf" or 100 * (1 - r ** k) <= 99, "the share is more than 99%")
        sk = u1 * (1 - r ** k) / (1 - r)
        if u == "share-of-sinf":
            v = 100 * sk / sinf
            slips = {E16PI_OWN + "3": 100 * (1 - r ** (k - 1)), E16PI_OWN + "4": 100 * r ** k, E16PI_OWN + "5": 100 * sinf / sk}
            head, tail = "", "%"
        else:
            v = sinf - sk
            slips = {E16PI_OWN + "6": u1 * r ** k, E16PI_OWN + "3": sinf * r ** (k - 1), E16PI_OWN + "7": sk}
            head, tail = f"S∞ − S{str(k).translate(str.maketrans('0123456789', '₀₁₂₃₄₅₆₇₈₉'))} = ", ""
        need(v == u1 * r ** k / (1 - r) if u == "gap-after-n" else v == 100 * (1 - r ** k), "the tail and the sum disagree")
        for x in [v] + list(slips.values()):
            need(not gc_rounds(x) or E16PI_clear(x), f"{sp.N(x, 10)} is on a rounding edge")
        show = "sf" if gc_rounds(v) else "dec"
        want = head + (ext_sf(v) if show == "sf" else dec_text(v)) + tail
        if show == "sf":
            trap = head + gc_s2(v) + tail
        for ref, x in slips.items():
            if x != v:
                wr[ref] = {head + E16PI_shown(x, show) + tail}
        subs = {}
    gc_check_common(q, want, wr, trap)
    E16B_steps(q, subs)
    E16PI_named(q, u1, r)
    E16B_no_hyphen(q)
    return None, None


def E16PI_spot(q, lines):
    u1, r = E16PI_series(q)
    sinf = u1 / (1 - r)
    m = re.search(r"S∞ − Sₙ < (\d+(?:\.\d+)?)\.", q["asked"])
    if m:
        tol = sp.Rational(m.group(1))
    else:
        pct = sp.Rational(re.search(r"more than (\d+(?:\.\d+)?)% of S∞", q["asked"]).group(1))
        tol = (1 - pct / 100) * sinf
    for t in lines:
        need(E16B_REL.search(t) is not None, f"can't judge the line {t!r}")
    return E16B_first_false(lines, {"n": E16PI_least(u1, r, tol)})


E16PI_PREV = SITUATION_CHECKS["geometric-sequence"]
E16PI_PREV_SPOT = SPOT_CHECKS.get("geometric-sequence")


def E16PI_entry(q):
    return E16PI_check(q) if q["view"]["unknown"] in E16PI_UNKNOWNS else E16PI_PREV(q)


def E16PI_spot_entry(q, lines):
    if q["view"]["unknown"] in E16PI_UNKNOWNS:
        return E16PI_spot(q, lines)
    need(E16PI_PREV_SPOT is not None, "the checker has no error-spot checks for geometric-sequence")
    return E16PI_PREV_SPOT(q, lines)


SITUATION_CHECKS["geometric-sequence"] = E16PI_entry
SPOT_CHECKS["geometric-sequence"] = E16PI_spot_entry


# ── arithmetic-sequence, t1-ext-sigma-arithmetic (FAL-779) ──
# The Σ is read back from its line, Σ (r = a to b) (pr + q), or the series from its first three
# terms and its last, and summed again with SymPy. An upper limit k is found by solving
# Σ (r = 1 to k) (pr + q) = T, which must have one positive whole root and one negative one.
# Every tagged option is rebuilt from its slip, every relation in the working must hold at the
# answer (a line in r must hold for every r), and an error-spot's first wrong line is the first
# whose relation fails.

E16SA_MAP = "SL1.2.sigma#"
E16SA_SUM = "SL1.2.sum#"
E16SA_OWN = "t1-ext-sigma-arithmetic#"
E16SA_UNKNOWNS = ("count-terms", "evaluate-sigma", "evaluate-shifted", "write-sigma", "upper-from-total")
E16SA_R = sp.Symbol("r")
E16SA_LINE = re.compile(r"Σ \(r = (\d+) to (\d+|k)\) \(([^()]*)\)(?: = (−?\d+))?")
E16SA_SERIES = re.compile(r"(−?\d+) ([+−]) (\d+) ([+−]) (\d+) \+ … ([+−]) (\d+)")
E16SA_UN_MAX = 400
E16SA_SN_MAX = 4000


def E16SA_n(v):
    """A rational as the game writes it: 3, −4, 8/5."""
    v = sp.Rational(v)
    s = str(abs(v.p)) if v.q == 1 else f"{abs(v.p)}/{v.q}"
    return ("−" if v < 0 else "") + s


def E16SA_term(text):
    """'3r + 2' -> (3, 2)."""
    e = E16B_expr(text, {}, ("r",))
    need(e is not None and sp.Poly(e, E16SA_R).degree() == 1, f"can't read the term {text!r}")
    P = sp.Poly(e, E16SA_R)
    return P.coeff_monomial(E16SA_R), P.coeff_monomial(1)


def E16SA_sum(p, c, a, b):
    return sp.summation(p * E16SA_R + c, (E16SA_R, a, b))


def E16SA_pair(n, first, last):
    return sp.Rational(n, 2) * (first + last)


def E16SA_check(q):
    u, L, angle = q["view"]["unknown"], q["lines"], q["view"]["angle"]
    need(q["paper"] == (2 if angle == "gdc-sigma" else 1), f"paper {q['paper']} for the method {angle}")
    wr = {}
    limits = None
    if u == "write-sigma":
        m = E16SA_SERIES.fullmatch(L[0])
        need(m is not None, f"can't read the series {L[0]!r}")
        sg = lambda s_, v: E16B_q(v) * (-1 if s_ == "−" else 1)
        t1, t2, t3, last = E16B_q(m.group(1)), sg(m.group(2), m.group(3)), sg(m.group(4), m.group(5)), sg(m.group(6), m.group(7))
        d = t2 - t1
        need(d != 0 and t3 - t2 == d, "the series shown is not arithmetic")
        n = (last - t1) / d + 1
        need(n.q == 1 and 8 <= n <= 40, f"{last} is not a term from the 8th to the 40th")
        p, c = d, t1 - d
        need(c != 0 and (p, c, n) != (3, 1, 20), f"p = {p}, q = {c} breaks the limits or is the map's example")
        need(abs(t1) <= E16SA_UN_MAX and abs(last) <= E16SA_UN_MAX and abs(E16SA_pair(n, t1, last)) <= E16SA_SN_MAX, "a value is past the limits")
        f = lambda p_, c_, n_: f"p = {E16SA_n(p_)}, q = {E16SA_n(c_)}, n = {E16SA_n(n_)}"
        want = f(p, c, n)
        wr[E16SA_OWN + "6"] = {f(p, t1, n)}
        wr[E16SA_SUM + "1"] = {f(p, c, n - 1)} | ({f(p, c, last)} if last > 0 else set())
        subs = {"p": p, "q": c, "n": n}
    else:
        m = E16SA_LINE.fullmatch(L[0])
        need(m is not None and bool(m.group(4)) == (u == "upper-from-total"), f"can't read the sum {L[0]!r}")
        a = int(m.group(1))
        p, c = E16SA_term(m.group(3))
        need(p != 0 and c != 0 and p.q == 1 and c.q == 1, f"the term {m.group(3)!r} breaks the limits")
        need(-5 <= p <= 9 and -9 <= c <= 12, f"p = {p} or q = {c} is outside the limits")
        if u == "upper-from-total":
            need(m.group(2) == "k" and a == 1, "the upper limit is not k from r = 1")
            T = E16B_q(m.group(4))
            k = sp.Symbol("k")
            roots = sp.solve(sp.Eq(E16SA_sum(p, c, 1, k), T), k)
            pos = [x for x in roots if x.is_integer and x > 0]
            neg = [x for x in roots if x < 0]
            need(len(roots) == 2 and len(pos) == 1 and len(neg) == 1 and neg[0].is_integer, f"the roots {roots} are not one positive and one negative whole number")
            K = int(pos[0])
            need(5 <= K <= 30 and p > 0 and (p, c, T) != (2, -1, 225), f"k = {K} or p = {p} breaks the limits")
            want = f"k = {K}"
            wr[E16SA_OWN + "7"] = {f"k = {E16SA_n(neg[0])}"}
            subs = {"k": K}
            limits = ("r", 1, K)
        else:
            b = int(m.group(2))
            n = b - a + 1
            first, last = p * a + c, p * b + c
            S = E16SA_sum(p, c, a, b)
            need(S == E16SA_pair(n, first, last), "the sum is not the arithmetic series it says")
            need(abs(first) <= E16SA_UN_MAX and abs(last) <= E16SA_UN_MAX and first != 0, "a term is past the limits")
            subs = {"n": n}
            if u == "count-terms":
                need(2 <= a <= 20 and 5 <= b - a <= 60 and (a, b) != (5, 30), f"r = {a} to {b} breaks the limits")
                want = f"{n} terms"
                wr[E16SA_MAP + "0"] = {f"{b - a} terms"}
            else:
                need(S != 0 and abs(S) <= E16SA_SN_MAX, f"the sum {S} is past the limits")
                want = E16SA_n(S)
                sr = E16SA_sum(1, 0, a, b)
                wr[E16SA_MAP + "1"] = {E16SA_n(p * sr + c)}
                if u == "evaluate-sigma":
                    need(a == 1 and 8 <= b <= 40 and (p, c, b) != (3, 2, 20), f"r = 1 to {b} breaks the limits, or is the map's example")
                    wr[E16SA_MAP + "2"] = {E16SA_n(p * sr)}
                    wr[E16SA_SUM + "0"] = {E16SA_n(sp.Rational(n, 2) * (2 * first + n * p))}
                else:
                    need(2 <= a <= 12 and 5 <= b - a <= 30, f"r = {a} to {b} breaks the limits")
                    wr[E16SA_MAP + "0"] = {E16SA_n(E16SA_pair(n - 1, first, last))}
                    wr[E16SA_OWN + "5"] = {E16SA_n(E16SA_sum(p, c, 1, b))}
                    wr[E16SA_MAP + "2"] = {E16SA_n(E16SA_pair(n, p, p * n))}
                limits = ("r", a, b)
    gc_check_common(q, want, wr)
    E16B_steps(q, subs, ("r",), limits)
    E16B_no_hyphen(q)
    return None, None


def E16SA_spot(q, lines):
    m = E16SA_LINE.fullmatch(q["lines"][0])
    need(m is not None, f"can't read the sum {q['lines'][0]!r}")
    a, b = int(m.group(1)), int(m.group(2))
    return E16B_first_false(lines, {"n": b - a + 1}, ("r",), ("r", a, b))


E16SA_PREV = SITUATION_CHECKS["arithmetic-sequence"]
E16SA_PREV_SPOT = SPOT_CHECKS.get("arithmetic-sequence")


def E16SA_entry(q):
    return E16SA_check(q) if q["view"]["unknown"] in E16SA_UNKNOWNS else E16SA_PREV(q)


def E16SA_spot_entry(q, lines):
    if q["view"]["unknown"] in E16SA_UNKNOWNS:
        return E16SA_spot(q, lines)
    need(E16SA_PREV_SPOT is not None, "the checker has no error-spot checks for arithmetic-sequence")
    return E16SA_PREV_SPOT(q, lines)


SITUATION_CHECKS["arithmetic-sequence"] = E16SA_entry
SPOT_CHECKS["arithmetic-sequence"] = E16SA_spot_entry


# ── solve-exponential, t1-ext-hidden-quadratic (FAL-779) ────
# The equation is read back from its line and turned into SymPy. Its base b is the one written
# with exponent x; the quadratic a u² + B u + C in u = b^x is found again by evaluating the
# equation at three values of u and checked at two more. Its roots come from SymPy, each
# positive one gives x = log_b u, and every answer, tagged option and claim in the working
# (u = N, b^x = N gives x = X, an identity, an equation = 0, x-intercepts) is worked out again.
# An error-spot's first wrong line is the first with a false claim.

E16HQ_MAP = "SL1.7.hidden-quadratic#"
E16HQ_OWN = "t1-ext-hidden-quadratic#"
E16HQ_UNKNOWNS = ("two-powers", "reject-negative", "zero-root", "exact-ln", "exact-log-base", "solution-count")
E16HQ_U = sp.Symbol("u")
E16HQ_MAPS = [(2, {2, 4}), (sp.E, {2, 3}), (3, {1, 3})]


def E16HQ_n(v):
    """A number as the game writes it: 3, −4, 8/5."""
    v = sp.Rational(v)
    s = str(abs(v.p)) if v.q == 1 else f"{abs(v.p)}/{v.q}"
    return ("−" if v < 0 else "") + s


def E16HQ_parse(text):
    """An expression in x and u, written as the game writes it, as SymPy (None if it can't be read)."""
    t = text.strip().rstrip(".").strip()
    t = t.replace("−", "-").replace("×", "*").replace("²", "**2").replace("^", "**")
    if not re.fullmatch(r"[0-9eux+\-*/(). ]+", t):
        return None
    try:
        return parse_expr(t, local_dict={"x": X, "u": E16HQ_U, "e": sp.E}, transformations=TRANSFORMS, evaluate=True)
    except Exception:
        return None


def E16HQ_base(eq):
    if re.search(r"e\^x", eq):
        return sp.E
    ms = re.findall(r"(?<![\d^(])(\d+)\^x", eq)
    need(len(ms) > 0, f"no b^x in {eq!r}")
    return sp.Integer(min(int(v) for v in ms))


def E16HQ_num(e, at):
    return sp.N(e.subs(at), 50)


def E16HQ_read(q):
    """(f, b, a, B, C): the equation as f(x) = 0 and its quadratic in u = b^x."""
    L, rep = q["lines"], q["view"]["rep"]
    if rep == "graph":
        m = re.fullmatch(r"The graph shows y = (.+), which meets the x-axis at P and Q\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        eq = m.group(1) + " = 0"
    else:
        eq = L[0]
    sides = eq.split(" = ")
    need(len(sides) == 2, f"can't read {eq!r}")
    lhs, rhs = E16HQ_parse(sides[0]), E16HQ_parse(sides[1])
    need(lhs is not None and rhs is not None, f"can't read {eq!r}")
    f = lhs - rhs
    b = E16HQ_base(eq)
    vals = []
    for uu in (1, 2, 3):
        v = E16HQ_num(f, {X: sp.log(uu) / sp.log(b)})
        vals.append(v)
    # f = a u² + B u + C at u = 1, 2, 3.
    a = (vals[2] - 2 * vals[1] + vals[0]) / 2
    B = vals[1] - vals[0] - 3 * a
    C = vals[0] - a - B
    a, B, C = (sp.Integer(round(v)) for v in (a, B, C))
    for uu in (5, sp.Rational(1, 7)):
        need(abs(E16HQ_num(f, {X: sp.log(uu) / sp.log(b)}) - (a * uu ** 2 + B * uu + C)) < 1e-30, "the equation is not a quadratic in b^x")
    need(a > 0, "the leading coefficient is not positive")
    return f, b, a, B, C


def E16HQ_log(u, b):
    """x with b^x = u, exact: a whole number where u is a power of b."""
    return sp.simplify(sp.log(u, b))


def E16HQ_ln(v):
    v = sp.Rational(v)
    return f"ln {E16HQ_n(v)}" if v.q == 1 and v > 0 else f"ln({E16HQ_n(v)})"


def E16HQ_xs(vals):
    vals = sorted(sp.Rational(v) for v in vals)
    names = [E16HQ_n(v) for v in vals]
    return "x = " + (", ".join(names[:-1]) + " or " + names[-1] if len(names) > 1 else names[0])


def E16HQ_claims_ok(t, f, b, quad, sols, strict_u=True):
    """Whether every claim in a line of working is true. quad: a u² + B u + C; sols: the x values."""
    u, roots = E16HQ_U, [r for r in sp.roots(sp.Poly(quad, E16HQ_U)).keys()]
    bt = "e" if b == sp.E else str(b)
    bx = re.escape(f"{bt}^x")
    xs_at = [sp.Rational(3, 10), sp.Rational(11, 10), sp.Rational(-7, 10)]

    def same(e1, e2):
        for xv in xs_at:
            at = {X: xv, u: b ** xv}
            if abs(E16HQ_num(e1, at) - E16HQ_num(e2, at)) > 1e-30:
                return False
        return True

    text = t.rstrip(".")
    # b^x = N gives x = X, or has no solution.
    for m in re.finditer(rf"(?:{bx}|u) = (−?[\d/]+) gives (?:x = ([^;,]+?)(?=$|;|,| and )|{bx} = (−?[\d/]+), so x = (−?[\d/]+))", text):
        N = sp.Rational(R(m.group(1).replace("−", "-")))
        if N not in roots or N <= 0:
            return False
        if m.group(2) is not None:
            xv = E16HQ_xv(m.group(2), b)
            if xv is None or abs(sp.N(b ** xv - N, 40)) > 1e-30:
                return False
    for m in re.finditer(rf"{bx} = (−?[\d/]+) has no solution, as {bx} (> 0 for every x|is never 0)", text):
        N = sp.Rational(R(m.group(1).replace("−", "-")))
        if N not in roots or (N < 0) != (m.group(2) == "> 0 for every x") or N > 0:
            return False
    text2 = re.sub(rf"(?:{bx}|u) = −?[\d/]+ (gives [^;]*|has no solution[^;]*)", "", text)
    # The x-values claimed: "So x = 1 or x = 3.", "x = 0 or 2".
    for m in re.finditer(r"(?:^|So |, so |: )x = ([^;:]+)$", text2):
        parts = re.split(r" or x = | or |, ", m.group(1))
        for p in parts:
            xv = E16HQ_xv(p, b)
            if xv is None or not any(abs(sp.N(xv - s_, 40)) < 1e-30 for s_ in sols):
                return False
        text2 = text2[:m.start()]
    # u = N and b^x = N, as roots: "so u = 1 or u = 25", "So 5^x = 1 or 5^x = 25".
    for m in re.finditer(rf"(?:(?<=so )|(?<=So )|(?<=^))((?:(?:u|{bx}) = −?[\d/]+(?: or )?)+)", text2):
        for v in re.findall(r"= (−?[\d/]+)", m.group(1)):
            if sp.Rational(R(v.replace("−", "-"))) not in roots:
                return False
    # Equations and identities with x or u on both sides, or ending in = 0.
    for frag in re.split(r", so | the equation is |: |; |, the roots? of |, a root of |, as |, and | and |, the left side factorises in |^So |^Then |^As ", text2):
        frag = frag.strip()
        if " = " not in frag or "gives" in frag:
            continue
        sides = frag.split(" = ")
        es = [E16HQ_parse(p) for p in sides]
        if any(e is None for e in es):
            continue
        if not any(e.free_symbols for e in es):
            # A numerical fact: "3^2 = 9".
            if any(abs(sp.N(es[i] - es[i + 1], 40)) > 1e-30 for i in range(len(es) - 1)):
                return False
            continue
        if len(es) == 2 and es[1] == 0:
            if not (same(es[0], f) or same(es[0], quad.subs(u, b ** X))):
                return False
            continue
        if len(es) == 2 and es[0] == u and not es[1].free_symbols:
            if es[1] not in roots:
                return False
            continue
        if es[0] == u and len(es) == 2 and es[1].free_symbols == {X}:
            continue  # "u = 2^x" names u
        if len(es) == 2 and es[0] == b ** X and not es[1].free_symbols:
            if es[1] not in roots:
                return False
            continue
        if len(es) == 2 and es[0] == X and not es[1].free_symbols:
            if not any(abs(sp.N(es[1] - s_, 40)) < 1e-30 for s_ in sols):
                return False
            continue
        for i in range(len(es) - 1):
            if not same(es[i], es[i + 1]):
                return False
    return True


def E16HQ_xv(text, b):
    """An x-value as written: "3", "−1", "ln 4", "ln 12/ln 5"."""
    t = text.strip().rstrip(".")
    m = re.fullmatch(r"(−?)ln (\d+)/ln (\d+)", t)
    if m:
        return (-1 if m.group(1) else 1) * sp.log(int(m.group(2))) / sp.log(int(m.group(3)))
    m = re.fullmatch(r"(−?)ln ?\(?(\d+(?:/\d+)?)\)?", t)
    if m:
        return (-1 if m.group(1) else 1) * sp.log(sp.Rational(m.group(2)))
    if re.fullmatch(r"−?\d+(?:/\d+)?", t):
        return sp.Rational(t.replace("−", "-"))
    return None


def E16HQ_check(q):
    u_id, paper = q["view"]["unknown"], q["paper"]
    U = E16HQ_U
    f, b, a, B, C = E16HQ_read(q)
    quad = a * U ** 2 + B * U + C
    rts = sp.roots(sp.Poly(quad, U))
    need(all(r.is_Rational for r in rts), "a root in u is not rational")
    roots = sorted(rts.keys())
    pos = [r for r in roots if r > 0]
    sols = [E16HQ_log(r, b) for r in pos]
    if q["view"]["angle"] == "graph-zeros":
        need(paper == 2, "a graph-zeros question is not Paper 2")
    for bb, us in E16HQ_MAPS:
        need(not (b == bb and a == 1 and {abs(r) for r in roots} == us), "the skill map's example, or it with a sign flipped")
    need(b in (2, 3, 4, 5, 7, sp.E), f"the base {b} is outside the limits")
    wr = {}
    bt = "e" if b == sp.E else str(b)
    if u_id in ("two-powers", "reject-negative", "zero-root"):
        need(all(s_.is_Integer and -2 <= s_ <= 4 for s_ in sols), f"x = {sols} is not whole from −2 to 4")
        want = E16HQ_xs(sols)
        if u_id == "two-powers":
            need(len(sols) == 2 and len(roots) == 2, "not two solutions")
            wr[E16HQ_MAP + "2"] = {E16HQ_xs(roots)}
            small = [r for r in pos if r < 1]
            if small:
                wr[E16HQ_OWN + "4"] = {E16HQ_xs([s_ for r, s_ in zip(pos, sols) if r >= 1])}
        elif u_id == "reject-negative":
            neg = [r for r in roots if r < 0]
            need(len(sols) == 1 and len(neg) == 1, "not one positive and one negative root")
            k = E16HQ_log(-neg[0], b)
            need(k.is_Integer, "the negative root is not minus a power of b")
            wr[E16HQ_MAP + "1"] = {E16HQ_xs(sols + [k])}
            wr[E16HQ_MAP + "2"] = {E16HQ_xs(roots)}
        else:
            need(C == 0 and len(sols) == 1 and 0 in roots, "not a zero root and one positive root")
            wr[E16HQ_OWN + "3"] = {E16HQ_xs(sols + [0])}
            wr[E16HQ_MAP + "2"] = {E16HQ_xs(pos)}
    elif u_id == "exact-ln":
        need(b == sp.E and a == 1 and len(pos) == 2 and all(r.q == 1 and 3 <= r <= 9 for r in pos), f"roots {roots} break the limits")
        want = f"x = ln {E16HQ_n(pos[0])} or x = ln {E16HQ_n(pos[1])}"
        wr[E16HQ_MAP + "2"] = {f"x = {E16HQ_n(pos[0])} or x = {E16HQ_n(pos[1])}"}
        lin = sp.solve(sp.Eq(2 * a * U + B * U + C, 0), U)
        wr[E16HQ_MAP + "0"] = {f"x = {E16HQ_ln(r)}" for r in lin if r > 0}
        if q["view"]["rep"] == "graph":
            g = q["graph"]
            need(g is not None, "no graph")
            P = {p["label"]: p for p in g["points"]}
            need(set(P) == {"P", "Q"}, "the graph doesn't mark P and Q")
            for lab, s_ in zip("PQ", sols):
                need(abs(P[lab]["x"] - float(s_)) < 1e-9 and P[lab]["y"] == 0, f"{lab} is not at the zero x = {s_}")
            for px, py in g["curves"][0][::13]:
                need(abs(py - float(E16HQ_num(f, {X: sp.nsimplify(px)}))) <= 1e-6 * max(1, abs(py)), "the curve drawn is not its equation")
    elif u_id == "exact-log-base":
        neg = [r for r in roots if r < 0]
        need(b != sp.E and len(pos) == 1 and len(neg) == 1 and pos[0].q == 1, "not one whole positive root and one negative")
        r, s_ = pos[0], -neg[0]
        need(not E16HQ_log(r, b).is_Rational and 3 <= r <= 20 and 2 <= s_ <= 9, f"u = {r} breaks the limits")
        want = f"x = ln {r}/ln {bt}"
        wr[E16HQ_OWN + "6"] = {f"x = ln {bt}/ln {r}"}
        wr[E16HQ_MAP + "1"] = {f"x = ln {r}/ln {bt} or x = ln {s_}/ln {bt}"}
        wr[E16HQ_MAP + "2"] = {f"x = {r}"}
    else:
        n = len(pos)
        want = f"number of solutions = {n}"
        if len(rts) == 1:
            need(n == 1, "a repeated root that is not positive")
            wr[E16HQ_OWN + "5"] = {"number of solutions = 2"}
        if any(r < 0 for r in roots):
            wr[E16HQ_MAP + "1"] = {f"number of solutions = {len(roots)}"}
        if any(0 < r < 1 for r in roots):
            wr[E16HQ_OWN + "4"] = {f"number of solutions = {sum(1 for r in roots if r >= 1)}"}
    gc_check_common(q, want, wr)
    for sol in q["solutions"]:
        for st in sol["steps"]:
            need(E16HQ_claims_ok(st, f, b, quad, sols), f"{sol['name']}: {st!r} is not true")
        if sol["angle"] == "graph-zeros" and u_id != "solution-count":
            need(any(st == "It crosses the x-axis " + ("once, at " if len(sols) == 1 else "at ") + " and ".join(f"x = {E16HQ_n(s_)}" for s_ in sols) + "." for st in sol["steps"]), "the GDC's zeros are not the solutions")
        if sol["angle"] == "graph-zeros" and u_id == "solution-count":
            said = {2: "It crosses the x-axis twice.", 0: "It doesn't meet the x-axis."}.get(len(sols), "It touches the x-axis once, without crossing it." if len(rts) == 1 else "It crosses the x-axis once.")
            need(said in sol["steps"], "the GDC's graph doesn't show the count")
    E17_no_hyphen(q)
    return None, None


def E16HQ_spot(q, lines):
    f, b, a, B, C = E16HQ_read(dict(q, lines=q["lines"][:q["lines"].index("A student's working:")]))
    U = E16HQ_U
    quad = a * U ** 2 + B * U + C
    sols = [E16HQ_log(r, b) for r in sp.roots(sp.Poly(quad, U)) if r > 0]
    for i, t in enumerate(lines):
        if not E16HQ_claims_ok(t, f, b, quad, sols):
            return i
    return None


E16HQ_PREV = SITUATION_CHECKS["solve-exponential"]
E16HQ_PREV_SPOT = SPOT_CHECKS.get("solve-exponential")


def E16HQ_entry(q):
    return E16HQ_check(q) if q["view"]["unknown"] in E16HQ_UNKNOWNS else E16HQ_PREV(q)


def E16HQ_spot_entry(q, lines):
    if q["view"]["unknown"] in E16HQ_UNKNOWNS:
        return E16HQ_spot(q, lines)
    return E16HQ_PREV_SPOT(q, lines)


SITUATION_CHECKS["solve-exponential"] = E16HQ_entry
SPOT_CHECKS["solve-exponential"] = E16HQ_spot_entry


# ── bearings-elevation, t3-ext-two-observations (FAL-779) ───
# The distance AB and the two angles of elevation are read back from the lines. The top T is
# found again from coordinates (A at 0, B at d, T where the two lines of sight meet), not from the
# sine rule the engine uses, at 40 digits. Every tagged option is rebuilt from its slip, the side
# view is held to the story, and every numerical equation in the working is worked out again from
# the figures it shows, with each length it gives (BT, TF, BF, x, y) held to the true one.

E16TO_MAP = "SL3.3.two-observations#"
E16TO_OWN = "t3-ext-two-observations#"
E16TO_UNKNOWNS = ("angle-at-top", "slant-distance", "height-two-angles", "ground-distance", "height-exact", "height-either-side")


def E16TO_read(q):
    L, u = q["lines"], q["view"]["unknown"]
    if u == "height-either-side":
        m = re.fullmatch(r"A and B are points on level ground, (\d+) m apart, and the foot F of a vertical (.+) is on the line between them\.", L[0])
        m2 = re.fullmatch(r"The angle of elevation of the top T is (\d+)° from A and (\d+)° from B\.", L[1])
        need(m and m2, f"can't read {L[:2]!r}")
        return int(m.group(1)), int(m2.group(1)), int(m2.group(2)), m.group(2), True
    m = re.fullmatch(r"A and B are points on level ground, in a straight line with the foot F of a vertical (.+), and B is between A and F\.", L[0])
    m2 = re.fullmatch(r"AB = (\d+) m\. The angle of elevation of the top T is (\d+)° from A and (\d+)° from B\.", L[1])
    need(m and m2, f"can't read {L[:2]!r}")
    return int(m2.group(1)), int(m2.group(2)), int(m2.group(3)), m.group(1), False


def E16TO_eval(text):
    """A numerical expression as the working writes it, at 40 digits; None where it has words."""
    t = text.strip().rstrip(".").strip()
    t = re.sub(r"(sin|cos|tan) (\d+)°", r"\1(radians(\2))", t)
    t = t.replace("°", "").replace("−", "-").replace("×", "*").replace("÷", "/")
    t = re.sub(r"√(\d+)", r"sqrt(\1)", t)
    t = re.sub(r"(\d)(sqrt)", r"\1*\2", t)
    if not re.fullmatch(r"[0-9.+\-*/() ]*(?:(?:sin|cos|tan|radians|sqrt)[0-9.+\-*/() ]*)*", t) or not re.search(r"\d", t):
        return None
    try:
        return mpmath.mpf(eval(t, {"__builtins__": {}}, {"sin": mpmath.sin, "cos": mpmath.cos, "tan": mpmath.tan, "radians": mpmath.radians, "sqrt": mpmath.sqrt}))
    except Exception:
        return None


def E16TO_steps(q, truth):
    """Every numerical equation holds to the figures shown, and each named length is the true one."""
    for sol in q["solutions"]:
        for st in sol["steps"]:
            for frag in re.split(r", so |: |; |, and |, | and |\. ", st.rstrip(".")):
                sides = frag.split(" = ")
                if len(sides) < 2:
                    continue
                vals = [E16TO_eval(p) for p in sides]
                for a, b in zip(vals, vals[1:]):
                    if a is None or b is None:
                        continue
                    # A figure shown to 5 s.f. (102 for 102.0003) is that value to its last place.
                    tol = abs(b) * mpmath.mpf("1.2e-4") + mpmath.mpf("1e-25")
                    need(abs(a - b) <= tol, f"{sol['name']}: {frag!r} doesn't hold ({a} against {b})")
                name = re.sub(r"^(?:So |They meet at |Triangle BFT has a right angle at F: |Let )", "", sides[0]).strip()
                last = next((v for v in reversed(vals) if v is not None), None)
                for key in ("BT", "TF", "BF", "x", "y"):
                    if name == key and last is not None and key in truth:
                        need(abs(last - truth[key]) <= abs(truth[key]) * mpmath.mpf("1.2e-4"), f"{sol['name']}: {name} = {last}, not {truth[key]}")
            # "They meet at x = 32.474, y = 22.739": both read.
            for key, v in re.findall(r"\b(x|y) = ([\d.]+)(?=[,:])", st):
                need(abs(mpmath.mpf(v) - truth[key]) <= truth[key] * mpmath.mpf("1.2e-4"), f"{sol['name']}: {key} = {v} is not the crossing")


def E16TO_check(q):
    with mpmath.workdps(40):
        return E16TO_work(q)


def E16TO_work(q):
    u, asked, paper = q["view"]["unknown"], q["asked"], q["paper"]
    d, al, be, thing, either = E16TO_read(q)
    tan, sin, cos = be_t, be_s, be_c
    dm = mpmath.mpf(d)
    # T from the two lines of sight: y = x tan α from A at 0, and y = ±(x − d) tan β from B at d.
    if either:
        need(40 <= d <= 200 and 20 <= al <= 70 and 20 <= be <= 70 and abs(al - be) >= 8 and al + be <= 140, f"{d}, {al}°, {be}° break the limits")
        xf = dm * tan(be) / (tan(al) + tan(be))
        bf = dm - xf
    else:
        exact = u == "height-exact"
        if exact:
            need(paper == 1 and (al, be) == (30, 60) and d % 2 == 0 and 4 <= d <= 60, f"{d}, {al}°, {be}° break the exact limits, or not Paper 1")
        else:
            need(15 <= al <= 45 and al + 10 <= be <= min(al + 30, 75) and 20 <= d <= 120, f"{d}, {al}°, {be}° break the limits")
        xf = dm * tan(be) / (tan(be) - tan(al))
        bf = xf - dm
    if u != "height-exact":
        need(paper == 2, "not Paper 2")
    h = xf * tan(al)
    bt = mpmath.hypot(bf, h)
    truth = {"BT": bt, "TF": h, "BF": bf, "x": bf, "y": h}
    wr = {}
    label, tail, x = None, " m", None

    def W(ref, val):
        if val > 0:
            wr.setdefault(ref, set()).add(be_text(label, val, tail))

    if u == "angle-at-top":
        top = be_angle((xf, h), (0, 0), (dm, 0))
        need(abs(top - mpmath.nint(top)) < mpmath.mpf("1e-20"), "angle ATB is not whole")
        want = f"angle ATB = {int(mpmath.nint(top))}°"
        wr[E16TO_MAP + "1"] = {f"angle ATB = {al + be}°"}
        wr[E16TO_OWN + "3"] = {f"angle ATB = {180 - al - be}°"}
        need(asked == "Find angle ATB.", f"asked {asked!r}")
    elif u == "height-exact":
        he = sp.Integer(d) * sp.tan(sp.pi / 6) * sp.tan(sp.pi / 3) / (sp.tan(sp.pi / 3) - sp.tan(sp.pi / 6))
        need(abs(sp.N(he, 40) - sp.Float(str(h), 40)) < 1e-25, "the exact height is not the height")
        want = f"height = {rt_exact(he)} m"
        wr[E16TO_MAP + "0"] = {f"height = {rt_exact(d * sp.tan(sp.pi / 3))} m"}
        wr[E16TO_OWN + "5"] = {f"height = {rt_exact(sp.Integer(d) * sp.cos(sp.pi / 3))} m"}
        wr[E16TO_OWN + "4"] = {f"height = {d} m"}  # BT = AB in the isosceles triangle
        need(asked == f"Find the exact height of the {thing}.", f"asked {asked!r}")
    else:
        if u == "slant-distance":
            label, x = "BT = ", bt
            W(E16TO_MAP + "1", dm * sin(al) / sin(al + be))
            W(E16TO_MAP + "2", dm * tan(al))
            need(asked.startswith("Find the distance BT."), f"asked {asked!r}")
        elif u == "ground-distance":
            label, x = "BF = ", bf
            W(E16TO_MAP + "0", dm)
            W(E16TO_OWN + "6", dm + bf)
            need(asked.startswith("Find the distance BF."), f"asked {asked!r}")
        else:
            label, x = "height = ", h
            need(asked.startswith(f"Find the height of the {thing}."), f"asked {asked!r}")
            W(E16TO_MAP + "0", dm * tan(be))
            if u == "height-two-angles":
                W(E16TO_MAP + "1", dm * sin(al) * sin(be) / sin(al + be))
                W(E16TO_OWN + "4", bt)
                W(E16TO_OWN + "5", bt * cos(be))
            else:
                lo, hi = min(al, be), max(al, be)
                W(E16TO_OWN + "7", dm * sin(lo) * sin(hi) / sin(hi - lo))
        need(x > 0 and be_clear(x), f"{x} is on a rounding edge")
        need(asked.endswith(" Give your answer to 3 significant figures."), f"asked {asked!r}")
        for o in q["choices"]:
            v = re.search(r"= (−?[\d.]+)", o["text"])
            need(v is not None and be_clear(R(v.group(1).replace("−", "-"))), f"option {o['text']!r} is on a rounding edge or unread")
    trap = None
    if x is not None:
        want = be_text(label, x, tail)
        t2 = bn_trap(label, nu_f(x))
        trap = t2 + tail if t2 else None
    gc_check_common(q, want, wr, trap)
    # The side view, to scale, with T above F and the asked part marked ?.
    pts = be_figure(q, True)
    for n, p in (("A", (0, 0)), ("B", (dm, 0)), ("F", (xf, 0)), ("T", (xf, h))):
        need(n in pts, f"no {n} in the sketch")
    s = pts["B"][0] / dm
    for n, p in (("A", (0, 0)), ("F", (xf, 0)), ("T", (xf, h))):
        need(abs(pts[n][0] - p[0] * s) + abs(pts[n][1] - p[1] * s) < mpmath.mpf("1e-6") * dm * s, f"{n} is not where the story puts it")
    need("F" in q["graph"].get("right", []), "no right angle at F")
    ask = {"angle-at-top": "ATB", "slant-distance": "BT", "ground-distance": "BF"}.get(u, "TF")
    marks = [ln["a"] + ln["b"] for ln in q["graph"]["lines"] if ln["label"] == "?"] + [a["from"] + a["at"] + a["to"] for a in q["graph"]["arcs"] if a["label"] == "?"]
    need(marks in ([ask], [ask[::-1]]), f"the sketch marks {marks}, not {ask}")
    E16TO_steps(q, truth)
    E17_no_hyphen(q)
    return None, None


E16TO_PREV = SITUATION_CHECKS["bearings-elevation"]


def E16TO_entry(q):
    return E16TO_check(q) if q["view"]["unknown"] in E16TO_UNKNOWNS else E16TO_PREV(q)


SITUATION_CHECKS["bearings-elevation"] = E16TO_entry





# ── approximation (t1-ai-percentage-error, t1-ai-approx-bounds, FAL-999) ──────
# The `approximation` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/approximation.gd. Every value is read back from the sentences (never the
# question's `given`) and worked out again with exact rationals; a rounding is done with Decimal,
# half up, and the slips are built from their descriptions in the catalogue.

R1AP_WHO = ["Kira", "Tomas", "Ines", "Ravi", "Lena", "Odo"]
R1AP_RA = "AI-SL1.6.round-accuracy#"
R1AP_PE = "AI-SL1.6.percentage-error#"
R1AP_ER = "AI-SL1.6.estimate-reasonableness#"
R1AP_BO = "AI-SL1.6.bounds#"
R1AP_MP = "AI-SL1.6.max-percentage-error#"
R1AP_TP = "t1-ai-percentage-error#"
R1AP_TB = "t1-ai-approx-bounds#"
R1AP_EDGE = sp.Rational(39, 1000)       # the engine's is 0.04
R1AP_CENT_EDGE = sp.Rational(149, 1000)  # the engine's is 0.15
R1AP_N = r"(\d+(?:\.\d+)?)"


def r1ap_q(t):
    return sp.Rational(t.replace("−", "-"))


def r1ap_round(v, places, mode=ROUND_HALF_UP):
    """v rounded to `places` decimal places (negative: to tens and up), as an exact Rational and its text."""
    d = Decimal(v.p) / Decimal(v.q) if isinstance(v, sp.Rational) else Decimal(str(v))
    q = Decimal(1).scaleb(-places)
    r = d.quantize(q, rounding=mode)
    text = f"{r:.{max(places, 0)}f}"
    return sp.Rational(text), text


def r1ap_places(v):
    """The decimal places a decimal is written with."""
    t = str(Decimal(v.p) / Decimal(v.q)).rstrip("0") if v.q != 1 else ""
    return len(t.split(".")[1]) if "." in t else 0


def r1ap_lead(v):
    return int(sp.floor(sp.log(abs(v), 10) + sp.Rational(1, 10**12)))


def r1ap_clear3(x):
    """x is at least R1AP_EDGE of its 3rd figure from a rounding edge."""
    v = abs(num(x))
    if v == 0:
        return False
    e = sp.floor(sp.log(v, 10))
    scaled = v / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= R1AP_EDGE


def r1ap_sf(label, x, unit=""):
    return f"{label}{gc_s(x)}{unit}", f"{label}{gc_s2(r9ac_f(x))}{unit}"


def r1ap_who(w):
    need(w in R1AP_WHO, f"the story's name {w!r}")


def r1ap_read(pattern, text, what):
    m = re.fullmatch(pattern, text)
    need(m is not None, f"can't read {what}: {text!r}")
    return m


def r1ap_money(x):
    return ci_money(ci_cents(x))


def r1ap_cents_clear(x):
    f = x * 100 - sp.floor(x * 100)
    return abs(f - sp.Rational(1, 2)) >= R1AP_CENT_EDGE


def r1ap_check(q):
    u, L, asked = q["view"]["unknown"], q["lines"], q["asked"]
    need(q["paper"] == 2, "every AI question is Paper 2")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs, want, trap = {}, None, None
    if u == "round-figures":
        v = r1ap_q(r1ap_read(r"A GDC gives the value " + R1AP_N + r"\.", L[0], "the value").group(1))
        m = r1ap_read(r"Write this value correct to (\d) (decimal places?|significant figures?)\.", asked, "the accuracy")
        n = int(m.group(1))
        dp = m.group(2).startswith("decimal")
        need(m.group(2) in (("decimal place" if n == 1 else "decimal places"), ("significant figure" if n == 1 else "significant figures")), "a plural")
        places = n if dp else n - 1 - r1ap_lead(v)
        need(places >= 0 and r1ap_places(v) > places + 1, f"{v} has too few digits for {places} places")
        need(len(L[0].split("value ")[1].rstrip(".").replace(".", "").lstrip("0")) <= 7, "the GDC value has more than 7 figures")
        r, want = r1ap_round(v, places)
        need(r != 0 and r1ap_lead(r) == r1ap_lead(v), "rounding changes the place of the first figure")
        if not dp and v < sp.Rational(1, 100):
            need(n == 3, "a small value is rounded to 3 s.f.")
            wrongs[R1AP_RA + "0"] = {r1ap_round(v, n)[1]}
        st = v
        for p in range(r1ap_places(v) - 1, places - 1, -1):
            st = r1ap_round(st, p)[0]
        if st != r:
            wrongs[R1AP_RA + "1"] = {r1ap_round(st, places)[1]}
        cut, cut_t = r1ap_round(v, places, "ROUND_DOWN")
        if cut != r:
            wrongs[R1AP_TP + "9"] = {cut_t}
        for o in q["choices"]:
            if not o["correct"]:
                need(r1ap_q(o["text"]) != r, f"wrong option {o['text']!r} has the answer's value")
    elif u == "round-context":
        m = r1ap_read(r"(\w+) orders " + R1AP_N + r" (m³|litres|metres|tonnes) of (concrete|paint|fencing|cable|fuel|gravel) at \$" + R1AP_N
                      + r" per (m³|litre|metre|tonne), and pays for (\d+)% extra to allow for waste\.", L[0], "the order")
        r1ap_who(m.group(1))
        V, p, w = r1ap_q(m.group(2)), r1ap_q(m.group(5)), int(m.group(7))
        need(asked == "Find the total cost, correct to the nearest cent.", f"asked {asked!r}")
        need(w in (5, 8, 10, 12, 15, 20) and r1ap_places(V) <= 2 and r1ap_places(p) <= 2, "the order is outside the limits")
        cost = V * p * (1 + sp.Rational(w, 100))
        bare = V * p
        need(100 <= cost <= 99999 and r1ap_cents_clear(cost) and r1ap_cents_clear(bare), "the cost is on a cent edge or outside the limits")
        f = cost * 100 - sp.floor(cost * 100)
        need(f > sp.Rational(1, 2) + R1AP_CENT_EDGE, "cutting off and rounding give the same cents")
        want = "cost = $" + r1ap_money(cost)
        wrongs[R1AP_RA + "3"] = {"cost = $" + ci_money(sp.Rational(sig3(cost)))}
        wrongs[R1AP_TP + "10"] = {"cost = $" + r1ap_money(bare)}
        wrongs[R1AP_TP + "9"] = {"cost = $" + ci_money(sp.floor(cost * 100) / 100)}
    elif u == "whole-items":
        mb = re.fullmatch(r"Each (tin of paint|bag of plaster|roll of turf|box of tiles) covers (\d+) m²\. (\w+) needs to cover (\d+) m², and buys (\d+)% extra to allow for waste\.", L[0])
        if mb:
            r1ap_who(mb.group(3))
            plural = {"tin of paint": "tins", "bag of plaster": "bags", "roll of turf": "rolls", "box of tiles": "boxes"}[mb.group(1)]
            need(asked == f"Find the number of {plural} that must be bought.", f"asked {asked!r}")
            c, A, w = int(mb.group(2)), int(mb.group(4)), int(mb.group(5))
            x = sp.Rational(A) * (100 + w) / 100 / c
            n = int(sp.ceiling(x))
            f = x - sp.floor(x)
            need(sp.Rational(1, 10) < f < sp.Rational(4, 10), f"the count's fraction {float(f):.3f} is not clear of rounding")
            want = f"number = {n}"
            wrongs[R1AP_TP + "11"] = {f"number = {int(sp.floor(x + sp.Rational(1, 2)))}"}
            wrongs[R1AP_TP + "10"] = {f"number = {int(sp.ceiling(sp.Rational(A, c)))}"}
        else:
            m = r1ap_read(r"Each (tile|plank|panel|brick) is (\d+) cm long\. (\w+) lays them end to end along a wall " + R1AP_N + r" m long, using whole (tiles|planks|panels|bricks) only\.", L[0], "the wall")
            r1ap_who(m.group(3))
            need(m.group(5) == m.group(1) + "s" and asked == f"Find the largest number of whole {m.group(5)} that fit along the wall.", f"asked {asked!r}")
            a, Lm = int(m.group(2)), r1ap_q(m.group(4))
            y = Lm * 100 / a
            f = y - sp.floor(y)
            need(sp.Rational(6, 10) < f < sp.Rational(9, 10), "the count's fraction is not clear of rounding")
            want = f"number = {int(sp.floor(y))}"
            wrongs[R1AP_TP + "11"] = {f"number = {int(sp.floor(y + sp.Rational(1, 2)))}"}
    elif u in ("percentage-error", "error-of-rounding", "exact-from-error"):
        if u == "percentage-error":
            m = r1ap_read(r"(\w+) estimates (the [a-z ]+) as " + R1AP_N + r" (\S+)\. The exact value is " + R1AP_N + r" (\S+)\.", L[0], "the estimate")
            r1ap_who(m.group(1))
            need(m.group(4) == m.group(6), "two units")
            need(asked == "Find the percentage error in the estimate.", f"asked {asked!r}")
            va, ve = r1ap_q(m.group(3)), r1ap_q(m.group(5))
            need(va != ve and abs(va / ve - 1) <= sp.Rational(27, 100), "the estimate is not off by 2% to 25%")
        elif u == "error-of-rounding":
            m = r1ap_read(r"A GDC gives (the [a-z ]+) as " + R1AP_N + r" (\S+)\. (\w+) rounds this value to (the nearest whole number|the nearest ten|1 decimal place)\.", L[0], "the rounding")
            r1ap_who(m.group(4))
            need(asked == "Find the percentage error caused by this rounding.", f"asked {asked!r}")
            ve = r1ap_q(m.group(2))
            places = {"the nearest whole number": 0, "the nearest ten": -1, "1 decimal place": 1}[m.group(5)]
            va = r1ap_round(ve, places)[0]
            need(va != ve, "the rounding changes nothing")
            for sol in q["solutions"]:
                need(sol["steps"][0] == f"Rounded to {m.group(5)}, {dec_text(ve)} is {dec_text(va)}.", f"{sol['name']}: the rounding step {sol['steps'][0]!r}")
        else:
            m = r1ap_read(r"(\w+) measures (the [a-z ]+) as " + R1AP_N + r" (\S+)\. The percentage error in this measurement is at most (\d+)%\.", L[0], "the measurement")
            r1ap_who(m.group(1))
            ma = r1ap_read(r"Find the (largest|smallest) possible exact value\.", asked, "the side")
            va, p, unit = r1ap_q(m.group(3)), sp.Rational(int(m.group(5)), 100), m.group(4)
            need(int(m.group(5)) in (2, 3, 4, 5, 6, 8, 10, 12, 15), "p is outside the limits")
            big = ma.group(1) == "largest"
            x, apply_, other = (va / (1 - p), va * (1 + p), va / (1 + p)) if big else (va / (1 + p), va * (1 - p), va / (1 - p))
            for y in (x, apply_, other):
                need(r1ap_clear3(y), f"{float(y):.5f} is on a 3 s.f. edge")
            # The answer is right: its percentage error is p at the most.
            need(abs(va - x) / x == p, "the exact value's error is not the largest allowed")
            want, trap = r1ap_sf("v_E = ", x, " " + unit)
            wrongs[R1AP_TP + "12"] = {r1ap_sf("v_E = ", apply_, " " + unit)[0]}
            wrongs[R1AP_TP + "13"] = {r1ap_sf("v_E = ", other, " " + unit)[0]}
        if u != "exact-from-error":
            e = abs(va - ve) / abs(ve) * 100
            over_a = abs(va - ve) / abs(va) * 100
            need(r1ap_clear3(e) and r1ap_clear3(over_a), "the error is on a 3 s.f. edge")
            want, trap = r1ap_sf("percentage error = ", e, "%")
            wrongs[R1AP_PE + "0"] = {r1ap_sf("percentage error = ", over_a, "%")[0]}
            if u == "percentage-error":
                wrongs[R1AP_PE + "1"] = {r1ap_sf("percentage error = ", e / 100, "%")[0]}
                if va < ve:
                    wrongs[R1AP_PE + "2"] = {r1ap_sf("percentage error = ", -e, "%")[0]}
            else:
                ve3 = sp.Rational(sig3(ve))
                wrongs[R1AP_PE + "3"] = {r1ap_sf("percentage error = ", abs(va - ve3) / ve3 * 100, "%")[0]}
    elif u == "estimate-1sf":
        m = r1ap_read(r"(\w+) needs a quick estimate of " + R1AP_N + " × " + R1AP_N + " ÷ " + R1AP_N + r"\.", L[0], "the calculation")
        r1ap_who(m.group(1))
        need(asked == "Estimate the value by rounding each number to 1 significant figure.", f"asked {asked!r}")
        a, b, c = (r1ap_q(m.group(i)) for i in (2, 3, 4))
        A, B, C = (sp.Rational(sig3(x, 1)) for x in (a, b, c))
        need(all(r1ap_lead(X1) == r1ap_lead(x) for X1, x in ((A, a), (B, b), (C, c))), "rounding to 1 s.f. moves a first figure")
        est = A * B / C
        need(est.q == 1, "the estimate is not a whole number")
        want = "estimate = " + dec_text(est)
        if C < 1:
            wrongs[R1AP_ER + "0"] = {"estimate = " + dec_text(A * B * C)}
    elif u == "reasonable-answer":
        m = r1ap_read(r"A rectangular pen is x m wide and \(x \+ (\d+)\) m long\. Its area is (\d+) m², so x\(x \+ (\d+)\) = (\d+)\.", L[0], "the pen")
        need(m.group(1) == m.group(3) and m.group(2) == m.group(4), "the equation is not the pen's")
        d, A = int(m.group(1)), int(m.group(2))
        roots = sorted(sp.solve(sp.Symbol("w") ** 2 + d * sp.Symbol("w") - A, sp.Symbol("w")), key=lambda z: -num(z))
        r1, r2 = roots
        need(float(r1) > 0 > float(r2) and not r1.is_rational, "the roots are not one positive and one negative, both irrational")
        r1, r2 = sp.N(r1, 30), sp.N(r2, 30)
        need(r1ap_clear3(r1) and r1ap_clear3(r2), "a root is on a 3 s.f. edge")
        need(L[1] == f"A GDC solves this equation and gives x = {gc_s(r1)} or x = {gc_s(r2)}.", f"the GDC's solutions {L[1]!r}")
        need(asked == "Which value of x is the width of the pen? Give a reason.", f"asked {asked!r}")
        want = f"x = {gc_s(r1)}: a width must be positive."
        wrongs[R1AP_ER + "1"] = {f"x = {gc_s(r2)}: it is the other solution of the equation."}
    elif u == "measurement-bound":
        side = r1ap_read(r"Write down the (lower|upper) bound\.", asked, "the bound").group(1)
        unit_text = ""
        mdp = re.fullmatch(r"(The [a-z ]+) is " + R1AP_N + r" (\S+), correct to (\d) decimal places?\.", L[0])
        mn = re.fullmatch(r"There are (\d+) ([a-z ]+), correct to the nearest (ten|hundred|thousand)\.", L[0])
        msf = re.fullmatch(r"There are (\d+) ([a-z ]+), correct to (\d) significant figures\.", L[0])
        if mdp:
            v, unit_text, dp = r1ap_q(mdp.group(2)), " " + mdp.group(3), int(mdp.group(4))
            unit = sp.Rational(1, 10**dp)
            need(r1ap_places(v) == dp, f"{v} is not written to {dp} places")
        elif mn:
            v, unit = sp.Integer(mn.group(1)), {"ten": 10, "hundred": 100, "thousand": 1000}[mn.group(3)]
            need(v % unit == 0 and (v // unit) % 10 != 0, f"{v} is not to the nearest {unit} alone")
        else:
            m = msf
            need(m is not None, f"can't read the value {L[0]!r}")
            v, n = sp.Integer(m.group(1)), int(m.group(3))
            unit = sp.Integer(10) ** (r1ap_lead(v) - n + 1)
            need(v % unit == 0 and (v // unit) % 10 != 0 and unit >= 10, f"{v} is not to {n} s.f. with zeros after")
        lo = side == "lower"
        b = v - unit / 2 if lo else v + unit / 2
        want = f"{side} bound = {dec_text(b)}{unit_text}"
        wrongs[R1AP_BO + "0"] = {f"{side} bound = {dec_text(v - unit if lo else v + unit)}{unit_text}"}
        if mdp and not lo:
            wrongs[R1AP_BO + "1"] = {f"{side} bound = {dec_text(b - unit / 10)}{unit_text}"}
        if msf:
            wrongs[R1AP_BO + "2"] = {f"{side} bound = {dec_text(v - sp.Rational(1, 2) if lo else v + sp.Rational(1, 2))}{unit_text}"}
    elif u == "calc-bound":
        ma = r1ap_read(r"Find the (least|greatest) possible (area of the field|area of the pond|volume of the ball|volume of the tank|total length of the route)\.", asked, "the question")
        lo = ma.group(1) == "least"
        side = "lower" if lo else "upper"
        acc = {"1 decimal place": sp.Rational(1, 10), "the nearest metre": sp.Integer(1)}
        PI = sp.pi
        if ma.group(2) == "area of the field":
            m = r1ap_read(r"A rectangular field is " + R1AP_N + r" m long and " + R1AP_N + r" m wide, each correct to (1 decimal place|the nearest metre)\.", L[0], "the field")
            xs, u0, f, unit = [r1ap_q(m.group(1)), r1ap_q(m.group(2))], acc[m.group(3)], lambda a, b: a * b, " m²"
        elif ma.group(2) == "area of the pond":
            m = r1ap_read(r"The radius of a circular pond is " + R1AP_N + r" m, correct to 1 decimal place\.", L[0], "the pond")
            xs, u0, f, unit = [r1ap_q(m.group(1))], sp.Rational(1, 10), lambda r: PI * r**2, " m²"
        elif ma.group(2) == "volume of the ball":
            m = r1ap_read(r"The diameter of a ball is " + R1AP_N + r" cm, correct to 1 decimal place\. The volume of a sphere of diameter d is πd³ ÷ 6\.", L[0], "the ball")
            xs, u0, f, unit = [r1ap_q(m.group(1))], sp.Rational(1, 10), lambda d: PI * d**3 / 6, " cm³"
        elif ma.group(2) == "volume of the tank":
            m = r1ap_read(r"A cylindrical tank has radius " + R1AP_N + r" m and height " + R1AP_N + r" m, each correct to (1 decimal place|the nearest metre)\.", L[0], "the tank")
            xs, u0, f, unit = [r1ap_q(m.group(1)), r1ap_q(m.group(2))], acc[m.group(3)], lambda r, h: PI * r**2 * h, " m³"
        else:
            m = r1ap_read(r"A route has (\d+) stages of (.+) km, each correct to the nearest km\.", L[0], "the route")
            parts = m.group(2).replace(" and ", ", ").split(", ")
            xs, u0, f, unit = [sp.Integer(t) for t in parts], sp.Integer(1), lambda *a: sum(a), " km"
            need(len(xs) == int(m.group(1)) and 4 <= len(xs) <= 6, "the stages")
        half = [x - u0 / 2 if lo else x + u0 / 2 for x in xs]
        whole = [x - u0 if lo else x + u0 for x in xs]
        val, wv, mv = (sp.N(f(*a), 40) if unit != " km" else f(*a) for a in (half, whole, xs))
        label = "length = " if unit == " km" else ("area = " if unit == " m²" else "volume = ")
        if unit == " km":
            want = label + dec_text(val) + unit
            wrongs[R1AP_BO + "0"] = {label + dec_text(wv) + unit}
            wrongs[R1AP_TB + "6"] = {label + dec_text(mv) + unit}
        else:
            vals = [val, wv, mv]
            if len(xs) == 2:
                vals.append(sp.N(f(half[0], xs[1] + u0 / 2 if lo else xs[1] - u0 / 2), 40))
            need(all(r1ap_clear3(y) for y in vals) and len({gc_s(y) for y in vals}) == len(vals), "a value is on a 3 s.f. edge, or two read the same")
            want, trap = r1ap_sf(label, val, unit)
            wrongs[R1AP_BO + "0"] = {r1ap_sf(label, wv, unit)[0]}
            wrongs[R1AP_TB + "6"] = {r1ap_sf(label, mv, unit)[0]}
            if len(xs) == 2:
                wrongs[R1AP_TB + "7"] = {r1ap_sf(label, vals[3], unit)[0]}
    elif u == "quotient-bound":
        ma = r1ap_read(r"Find the (greatest|least) possible (average speed|density)\.", asked, "the question")
        up = ma.group(1) == "greatest"
        if ma.group(2) == "average speed":
            m = r1ap_read(r"(\w+) runs (\d+) m in " + R1AP_N + r" s\. The distance is correct to the nearest (metre|10 m) and the time to 1 decimal place\.", L[0], "the run")
            r1ap_who(m.group(1))
            top, bottom, ut, ub = sp.Integer(m.group(2)), r1ap_q(m.group(3)), sp.Integer(1 if m.group(4) == "metre" else 10), sp.Rational(1, 10)
            need(top % ut == 0, "the distance is not a multiple of its unit")
            label, unit = "speed = ", " m/s"
        else:
            m = r1ap_read(r"A block of metal has mass (\d+) g and volume (\d+) cm³, the mass correct to the nearest gram and the volume to the nearest cm³\.", L[0], "the block")
            top, bottom, ut, ub = sp.Integer(m.group(1)), sp.Integer(m.group(2)), sp.Integer(1), sp.Integer(1)
            label, unit = "density = ", " g/cm³"
        t_up, t_lo, b_up, b_lo = top + ut / 2, top - ut / 2, bottom + ub / 2, bottom - ub / 2
        corners = [t_up / b_lo, t_up / b_up, t_lo / b_lo, t_lo / b_up]
        val = max(corners) if up else min(corners)
        need(val == (t_up / b_lo if up else t_lo / b_up), "the extreme is not upper over lower")
        same = t_up / b_up if up else t_lo / b_lo
        vals = [val, same, top / bottom, min(corners) if up else max(corners)]
        need(all(r1ap_clear3(y) for y in vals) and len({gc_s(y) for y in vals}) == 4, "a value is on a 3 s.f. edge, or two read the same")
        want, trap = r1ap_sf(label, val, unit)
        wrongs[R1AP_MP + "2"] = {r1ap_sf(label, same, unit)[0]}
        wrongs[R1AP_TB + "6"] = {r1ap_sf(label, top / bottom, unit)[0]}
    elif u == "max-percentage-error":
        m = r1ap_read(r"The (side of a square tile|edge of a cube|radius of a circular mat|radius of a ball) is measured as " + R1AP_N + r" cm, correct to (1 decimal place|the nearest centimetre)\.", L[0], "the length")
        k = {"side of a square tile": 2, "edge of a cube": 3, "radius of a circular mat": 2, "radius of a ball": 3}[m.group(1)]
        what = "area" if k == 2 else "volume"
        need(L[1] == f"Its {what} is worked out from this measurement.", f"{L[1]!r}")
        need(asked == f"Find the maximum percentage error in the {what}.", f"asked {asked!r}")
        x, u0 = r1ap_q(m.group(2)), sp.Rational(1, 10) if m.group(3) == "1 decimal place" else sp.Integer(1)
        lo, hi = x - u0 / 2, x + u0 / 2
        # Each bound's area or volume taken as the exact value; the constant (π, 4π/3) cancels.
        e_lo, e_hi = abs(x**k - lo**k) / lo**k * 100, abs(x**k - hi**k) / hi**k * 100
        need(e_lo > e_hi, "the lower bound does not give the larger error")
        vals = [e_lo, (x / lo - 1) * 100, e_hi]
        need(all(r1ap_clear3(y) for y in vals) and len({gc_s(y) for y in vals}) == 3, "a value is on a 3 s.f. edge, or two read the same")
        want, trap = r1ap_sf("maximum error = ", e_lo, "%")
        wrongs[R1AP_MP + "0"] = {r1ap_sf("maximum error = ", vals[1], "%")[0]}
        wrongs[R1AP_MP + "1"] = {r1ap_sf("maximum error = ", e_hi, "%")[0]}
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, trap)
    return None, None


SITUATION_CHECKS["approximation"] = r1ap_check


# ── tvm (t1-ai-amortization, t1-ai-annuity, FAL-999) ─────────────────
# The `tvm` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/tvm.gd. The loan, the deposits or the fund are read back from the
# sentences, and every value is worked out again from the annuity sums at 50 digits (mpmath),
# a number of payments by counting rows of the balance with exact rationals where the rate is,
# and a rate by solving for it. A payment shown in the question is held to the solver's payment.

R1TV_LR = "AI-SL1.7.loan-repayment#"
R1TV_LT = "AI-SL1.7.loan-term-or-rate#"
R1TV_OB = "AI-SL1.7.outstanding-balance#"
R1TV_TI = "AI-SL1.7.total-interest-compare#"
R1TV_SA = "AI-SL1.7.savings-annuity#"
R1TV_PA = "AI-SL1.7.payout-annuity#"
R1TV_TA = "t1-ai-amortization#"
R1TV_TN = "t1-ai-annuity#"
R1TV_FREQ = {"monthly": 12, "quarterly": 4, "half-yearly": 2}
R1TV_CENT_EDGE = mpmath.mpf("0.149")
R1TV_N_GAP = mpmath.mpf("0.099")
R1TV_M = r"\$(\d+(?:\.\d\d)?)"
R1TV_R = r"(\d+(?:\.\d)?)"


def r1tv_i(r, c):
    with mpmath.workdps(50):
        return (1 + mpmath.mpf(r.p) / r.q / (100 * c)) ** (mpmath.mpf(c) / 12) - 1


def r1tv_mp(x):
    return mpmath.mpf(x.p) / x.q if isinstance(x, sp.Rational) else mpmath.mpf(x)


def r1tv_pmt(pv, i, n):
    return r1tv_mp(pv) * i / (1 - (1 + i) ** (-n))


def r1tv_bal(pv, i, p, k):
    g = (1 + i) ** k
    return r1tv_mp(pv) * g - r1tv_mp(p) * (g - 1) / i


def r1tv_saved(p0, i, d, k):
    g = (1 + i) ** k
    return r1tv_mp(p0) * g + r1tv_mp(d) * (g - 1) / i


def r1tv_cents(x):
    """x to the nearest cent, half up, as a Rational, and held clear of the half-cent edge."""
    c = x * 100
    f = c - mpmath.floor(c)
    need(abs(f - mpmath.mpf("0.5")) >= R1TV_CENT_EDGE, f"{float(x):.5f} is on the edge between two cents")
    return sp.Rational(int(mpmath.floor(c + mpmath.mpf("0.5"))), 100)


def r1tv_money(x):
    return ci_money(r1tv_cents(x) if not isinstance(x, sp.Rational) else x)


def r1tv_who(w):
    need(w in R1AP_WHO, f"the story's name {w!r}")


def r1tv_whole_n(x, up):
    f = x - mpmath.floor(x)
    need(R1TV_N_GAP <= f <= 1 - R1TV_N_GAP, f"N = {float(x):.4f} is not clear of a whole number")
    return int(mpmath.floor(x)) + (1 if up else 0)


def r1tv_says(q, x, angles=None):
    """Some figure in each worked solution (of these methods) is x to the 4 places the working shows."""
    for sol in q["solutions"]:
        if angles and sol["angle"] not in angles:
            continue
        figs = [mpmath.mpf(t) for st in sol["steps"] for t in re.findall(r"\d+\.\d{4}\b", st)]
        need(any(abs(f - x) < mpmath.mpf("0.00006") for f in figs), f"{sol['name']}: the working doesn't show {float(x):.4f}")


def r1tv_check(q):
    with mpmath.workdps(50):
        return r1tv_check_at(q)


def r1tv_check_at(q):
    from fractions import Fraction
    u, L, asked, rep = q["view"]["unknown"], q["lines"], q["asked"], q["view"]["rep"]
    need(q["paper"] == 2, "every AI question is Paper 2")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs, want, trap = {}, None, None
    freqs = "|".join(R1TV_FREQ)
    if u == "loan-payment":
        md = re.fullmatch(r"(\w+) buys (a house|a cargo truck) for " + R1TV_M + r", pays a deposit of (\d+)% and borrows the rest\.", L[0])
        if md:
            r1tv_who(md.group(1))
            price, dep = sp.Integer(md.group(3)), int(md.group(4))
            need(dep in (10, 15, 20, 25) and (md.group(2) == "a house") == (price >= 80000), "the deposit or the item")
            Lo = price * (100 - dep) / 100
            need(Lo.q == 1, "the loan is not whole dollars")
        else:
            m = r1ap_read(r"(\w+) takes out a loan of " + R1TV_M + r"\.", L[0], "the loan")
            r1tv_who(m.group(1))
            Lo = sp.Integer(m.group(2))
        m = r1ap_read(r"The loan is repaid with equal monthly payments over (\d+) years, at " + R1TV_R + r"% per year, compounded (" + freqs + r")\.", L[1], "the terms")
        n, r, c = int(m.group(1)), R(m.group(2)), R1TV_FREQ[m.group(3)]
        need(2 <= n <= 30 and 2 <= r <= sp.Rational(95, 10), "the term or rate is outside the limits")
        need(asked == "Find the monthly payment, to the nearest cent.", f"asked {asked!r}")
        i, N = r1tv_i(r, c), 12 * n
        p = r1tv_pmt(Lo, i, N)
        want = "payment = $" + r1tv_money(p)
        wrongs[R1TV_LR + "0"] = {"payment = $" + r1tv_money(r1tv_pmt(Lo, i, n))}
        wrongs[R1TV_LR + "1"] = {"payment = $" + r1tv_money(r1tv_pmt(Lo, r1tv_i(r / 12, c), N))}
        wrongs[R1TV_LR + "2"] = {"payment = $" + r1tv_money(r1tv_mp(Lo * (1 + r * n / 100) / N))}
        wrongs[R1TV_LR + "3"] = {"payment = $" + r1tv_money(r1tv_mp(Lo / N))}
        r1tv_says(q, p)
    elif u in ("loan-term", "final-payment"):
        m = r1ap_read(r"(\w+) borrows " + R1TV_M + r" at " + R1TV_R + r"% per year, compounded monthly, and repays \$(\d+) at the end of each month\.", L[0], "the loan")
        r1tv_who(m.group(1))
        Lo, r, p = sp.Integer(m.group(2)), R(m.group(3)), sp.Integer(m.group(4))
        i = r / 1200
        need(p > Lo * i, "the payment doesn't cover a month's interest")
        # Count the rows: the balance after each payment, exactly.
        fi, fp = Fraction(int(r.p), int(r.q) * 1200), Fraction(int(p))
        fb, k = Fraction(int(Lo)), 0
        while fb * (1 + fi) > fp:
            fb = fb * (1 + fi) - fp
            k += 1
            need(k <= 400, "more than 400 payments")
        bal = sp.Rational(fb.numerator, fb.denominator)
        x = -mpmath.log(1 - r1tv_mp(Lo * i / p)) / mpmath.log(1 + r1tv_mp(i))
        need(int(mpmath.floor(x)) == k, "the count of rows and the solver's N disagree")
        if u == "loan-term":
            need(asked == "Find the number of monthly payments needed to repay the loan.", f"asked {asked!r}")
            want = f"payments = {r1tv_whole_n(x, True)}"
            wrongs[R1TV_LT + "0"] = {f"payments = {k}"}
            r1tv_says(q, x, ("tvm-n-or-i",))
        else:
            need(L[1] == "The last payment is smaller than the others and clears the loan." and asked == "Find the amount of the last payment, to the nearest cent.", f"asked {asked!r}")
            r1tv_whole_n(x, False)
            last = r1tv_mp(bal * (1 + i))
            want = "last payment = $" + r1tv_money(last)
            wrongs[R1TV_TA + "13"] = {"last payment = $" + r1tv_money(r1tv_mp(bal))}
            wrongs[R1TV_TA + "14"] = {"last payment = $" + r1tv_money((x - k) * r1tv_mp(p))}
            r1tv_says(q, last)
    elif u == "loan-rate":
        m = r1ap_read(r"(\w+) borrows " + R1TV_M + r" and repays it with (\d+) monthly payments of " + R1TV_M + r"\. Interest is compounded monthly\.", L[0], "the loan")
        r1tv_who(m.group(1))
        Lo, N, p = sp.Integer(m.group(2)), int(m.group(3)), R(m.group(4))
        need(N % 12 == 0 and asked == "Find the annual interest rate, as a percentage to 3 s.f.", f"asked {asked!r}")
        rate = mpmath.findroot(lambda y: r1tv_pmt(Lo, y / 1200, N) - r1tv_mp(p), 5)
        simple = (N * p - Lo) / Lo / (N // 12) * 100
        for y in (rate, 12 * rate, simple):
            need(r1ap_clear3(sp.Float(y, 30)), f"{float(y):.5f} is on a 3 s.f. edge")
        want, trap = r1ap_sf("rate = ", sp.Float(rate, 30), "%")
        wrongs[R1TV_LT + "2"] = {r1ap_sf("rate = ", sp.Float(12 * rate, 30), "%")[0]}
        wrongs[R1TV_TA + "11"] = {r1ap_sf("rate = ", simple, "%")[0]}
    elif u in ("balance-after", "first-interest", "total-interest"):
        m = r1ap_read(r"(\w+) borrows " + R1TV_M + r" over (\d+) years at " + R1TV_R + r"% per year, compounded (" + freqs + r")\. The monthly payment is " + R1TV_M + r"\.", L[0], "the loan")
        r1tv_who(m.group(1))
        Lo, n, r, c, p = sp.Integer(m.group(2)), int(m.group(3)), R(m.group(4)), R1TV_FREQ[m.group(5)], R(m.group(6))
        i, N = r1tv_i(r, c), 12 * n
        need(r1tv_cents(r1tv_pmt(Lo, i, N)) == p, "the payment shown is not the solver's payment to the cent")
        if u == "balance-after":
            k = int(r1ap_read(r"Find the amount still owed after (\d+) payments, to the nearest cent\.", asked, "the question").group(1))
            need(1 <= k < N, "k is outside the term")
            b = r1tv_bal(Lo, i, p, k)
            want = "balance = $" + r1tv_money(b)
            wrongs[R1TV_OB + "0"] = {"balance = $" + r1tv_money(r1tv_mp(Lo - k * p))}
            r1tv_says(q, b)
        elif u == "first-interest":
            need(c == 12 and Lo % 1200 == 0, "a month's interest is not whole cents")
            i1 = Lo * r / 1200
            year = Lo * r / 100
            if asked == "Find how much of the first payment is interest.":
                want = "interest = $" + ci_money(i1)
                wrongs[R1TV_OB + "1"] = {"interest = $" + ci_money(year)}
                wrongs[R1TV_OB + "2"] = {"interest = $" + r1tv_money(r1tv_mp((N * p - Lo) / N))}
            else:
                need(asked == "Find how much the first payment reduces the amount owed.", f"asked {asked!r}")
                want = "reduction = $" + ci_money(p - i1)
                wrongs[R1TV_OB + "1"] = {"reduction = $" + ci_money(p - year)}
                wrongs[R1TV_OB + "2"] = {"reduction = $" + r1tv_money(r1tv_mp(Lo / N))}
        else:
            need(asked == f"Find the total interest paid over the {n} years.", f"asked {asked!r}")
            want = "interest = $" + ci_money(N * p - Lo)
            wrongs[R1TV_TI + "0"] = {"interest = $" + ci_money(N * p)}
            wrongs[R1TV_TA + "12"] = {"interest = $" + ci_money(Lo * r * n / 100)}
    elif u == "compare-loans":
        m = r1ap_read(r"(\w+) needs to borrow " + R1TV_M + r" and is offered two loans, each repaid monthly with interest compounded monthly\.", L[0], "the loans")
        r1tv_who(m.group(1))
        Lo = sp.Integer(m.group(2))
        if rep == "table":
            rows = q["table"]["rows"]
            need(rows[0] == ["Loan", ["A", "B"]] and rows[1][0] == "Rate (% per year)" and rows[2][0] == "Term (years)", "the table's heads")
            ra, rb, na, nb = R(rows[1][1][0]), R(rows[1][1][1]), int(rows[2][1][0]), int(rows[2][1][1])
        else:
            mm = r1ap_read(r"Loan A: " + R1TV_R + r"% per year over (\d+) years\. Loan B: " + R1TV_R + r"% per year over (\d+) years\.", L[1], "the two loans")
            ra, na, rb, nb = R(mm.group(1)), int(mm.group(2)), R(mm.group(3)), int(mm.group(4))
        need(asked == "Which loan costs less in total interest, and by how much? Give the amount to the nearest dollar.", f"asked {asked!r}")
        pa, pb = r1tv_pmt(Lo, r1tv_mp(ra / 1200), 12 * na), r1tv_pmt(Lo, r1tv_mp(rb / 1200), 12 * nb)
        ia, ib = 12 * na * pa - r1tv_mp(Lo), 12 * nb * pb - r1tv_mp(Lo)
        cheap, dear = ("A", "B") if ia < ib else ("B", "A")
        need((pa > pb) == (cheap == "A"), "the cheaper loan does not have the higher payment")
        d = abs(ia - ib)
        need(d >= 50 and abs(d - mpmath.floor(d) - mpmath.mpf("0.5")) >= mpmath.mpf("0.149"), "the difference is under 50 or on a half-dollar edge")
        dr = abs(12 * na * r1tv_mp(r1tv_cents(pa)) - 12 * nb * r1tv_mp(r1tv_cents(pb)))
        D = int(mpmath.floor(d + mpmath.mpf("0.5")))
        need(int(mpmath.floor(dr + mpmath.mpf("0.5"))) == D, "the payments to the cent give another dollar")
        want = f"Loan {cheap}, by ${D}."
        wrongs[R1TV_TI + "1"] = {f"Loan {dear}, by ${D}."}
        wrongs[R1TV_TA + "15"] = {f"Loan {cheap}, by ${int(mpmath.floor(abs(pa - pb) + mpmath.mpf('0.5')))}."}
    elif u in ("savings-fv", "savings-interest", "savings-time"):
        m0 = re.fullmatch(r"(\w+) deposits " + R1TV_M + r" at the end of every month into a savings account that pays " + R1TV_R + r"% per year, compounded (monthly|quarterly)\.", L[0])
        if m0:
            r1tv_who(m0.group(1))
            p0, d, r, c = sp.Integer(0), sp.Integer(m0.group(2)), R(m0.group(3)), R1TV_FREQ[m0.group(4)]
        else:
            m = r1ap_read(r"(\w+) opens a savings account with " + R1TV_M + r" and deposits " + R1TV_M + r" at the end of every month\. The account pays " + R1TV_R + r"% per year, compounded (monthly|quarterly)\.", L[0], "the account")
            r1tv_who(m.group(1))
            p0, d, r, c = sp.Integer(m.group(2)), sp.Integer(m.group(3)), R(m.group(4)), R1TV_FREQ[m.group(5)]
        i = r1tv_i(r, c)
        if u == "savings-time":
            T = sp.Integer(r1ap_read(r"Find the number of months until the account first holds more than " + R1TV_M + r"\.", asked, "the target").group(1))
            need(c == 12, "a time is compounded monthly")
            x = mpmath.log((r1tv_mp(T) + r1tv_mp(d) / i) / (r1tv_mp(p0) + r1tv_mp(d) / i)) / mpmath.log(1 + i)
            k = r1tv_whole_n(x, True)
            need(r1tv_saved(p0, i, d, k) > r1tv_mp(T) > r1tv_saved(p0, i, d, k - 1), "the month is not the first past the target")
            want = f"months = {k}"
            wrongs[R1TV_TN + "6"] = {f"months = {k - 1}"}
            r1tv_says(q, x)
        else:
            n = int(r1ap_read(r"Find the (?:value of the account after|interest earned over the) (\d+) years, to the nearest cent\.", asked, "the question").group(1))
            N = 12 * n
            fv = r1tv_saved(p0, i, d, N)
            paid = r1tv_mp(p0 + N * d)
            if u == "savings-fv":
                need(asked == f"Find the value of the account after {n} years, to the nearest cent.", f"asked {asked!r}")
                want = "value = $" + r1tv_money(fv)
                wrongs[R1TV_SA + "0"] = {"value = $" + r1tv_money(paid)}
                if p0 == 0:
                    wrongs[R1TV_SA + "1"] = {"value = $" + r1tv_money(N * r1tv_mp(d) * (1 + r1tv_mp(r) / (100 * c)) ** (c * n))}
                r1tv_says(q, fv)
            else:
                want = "interest = $" + r1tv_money(fv - paid)
                wrongs[R1TV_TN + "7"] = {"interest = $" + r1tv_money(fv)}
                if p0 > 0:
                    wrongs[R1TV_TN + "8"] = {"interest = $" + r1tv_money(fv - r1tv_mp(p0))}
                r1tv_says(q, fv - paid)
    elif u == "savings-deposit":
        m = r1ap_read(r"(\w+) wants " + R1TV_M + r" in a savings account after (\d+) years, and will deposit the same amount at the end of every month\. The account pays " + R1TV_R + r"% per year, compounded (monthly|quarterly)\.", L[0], "the plan")
        r1tv_who(m.group(1))
        T, n, r, c = sp.Integer(m.group(2)), int(m.group(3)), R(m.group(4)), R1TV_FREQ[m.group(5)]
        p0 = sp.Integer(0)
        if len(L) > 1:
            p0 = sp.Integer(r1ap_read(r"The account already holds " + R1TV_M + r"\.", L[1], "the opening sum").group(1))
        need(asked == "Find the monthly deposit needed, to the nearest cent.", f"asked {asked!r}")
        i, N = r1tv_i(r, c), 12 * n

        def dep(k):
            g = (1 + i) ** k
            return (r1tv_mp(T) - r1tv_mp(p0) * g) * i / (g - 1)
        dv = dep(N)
        need(abs(r1tv_saved(p0, i, dv, N) - r1tv_mp(T)) < mpmath.mpf("1e-20"), "the deposit doesn't reach the target")
        want = "deposit = $" + r1tv_money(dv)
        wrongs[R1TV_SA + "0"] = {"deposit = $" + r1tv_money(r1tv_mp((T - p0) / N))}
        wrongs[R1TV_TN + "5"] = {"deposit = $" + r1tv_money(dep(n))}
        r1tv_says(q, dv)
    elif u == "payout-pv":
        m = r1ap_read(r"(\w+) wants to withdraw " + R1TV_M + r" at the end of every month for (\d+) years from a fund that pays " + R1TV_R + r"% per year, compounded (monthly|quarterly)\. The fund is then empty\.", L[0], "the fund")
        r1tv_who(m.group(1))
        W, n, r, c = sp.Integer(m.group(2)), int(m.group(3)), R(m.group(4)), R1TV_FREQ[m.group(5)]
        need(asked == "Find the amount the fund must hold at the start, to the nearest cent.", f"asked {asked!r}")
        i, N = r1tv_i(r, c), 12 * n
        pv = r1tv_mp(W) * (1 - (1 + i) ** (-N)) / i
        need(abs(r1tv_bal(pv, i, W, N)) < mpmath.mpf("1e-20"), "the fund is not empty at the end")
        want = "fund = $" + r1tv_money(pv)
        wrongs[R1TV_PA + "0"] = {"fund = $" + r1tv_money(r1tv_mp(N * W))}
        wrongs[R1TV_PA + "1"] = {"fund = $" + r1tv_money(r1tv_saved(0, i, W, N))}
        r1tv_says(q, pv)
    elif u in ("payout-months", "payout-balance"):
        m = r1ap_read(r"A fund of " + R1TV_M + r" pays " + R1TV_R + r"% per year, compounded monthly\. (\w+) withdraws " + R1TV_M + r" from it at the end of every month\.", L[0], "the fund")
        r1tv_who(m.group(3))
        Lo, r, W = sp.Integer(m.group(1)), R(m.group(2)), sp.Integer(m.group(4))
        i = r / 1200
        if u == "payout-months":
            need(W > Lo * i, "the withdrawal doesn't exceed a month's interest")
            need(asked == "Find the number of full withdrawals the fund can pay.", f"asked {asked!r}")
            fi, fw = Fraction(int(r.p), int(r.q) * 1200), Fraction(int(W))
            fb, k = Fraction(int(Lo)), 0
            while fb * (1 + fi) >= fw:
                fb = fb * (1 + fi) - fw
                k += 1
                need(k <= 700, "more than 700 withdrawals")
            x = -mpmath.log(1 - r1tv_mp(Lo * i / W)) / mpmath.log(1 + r1tv_mp(i))
            need(r1tv_whole_n(x, False) == k, "the count of rows and the solver's N disagree")
            want = f"withdrawals = {k}"
            wrongs[R1TV_PA + "2"] = {f"withdrawals = {k + 1}"}
            wrongs[R1TV_TN + "9"] = {f"withdrawals = {int(sp.floor(Lo / W))}"}
            r1tv_says(q, x)
        else:
            n = int(r1ap_read(r"Find the amount left in the fund after (\d+) years, to the nearest cent\.", asked, "the question").group(1))
            N = 12 * n
            b = Lo * (1 + i) ** N - W * ((1 + i) ** N - 1) / i
            need(b > 0 and Lo - N * W > 0, "the fund runs out")
            want = "balance = $" + ci_money(ci_cents(b))
            need(r1tv_cents(r1tv_mp(b)) == ci_cents(b), "rounding")
            wrongs[R1TV_TN + "9"] = {"balance = $" + r1tv_money(r1tv_mp(Lo - N * W))}
            r1tv_says(q, r1tv_mp(b))
    elif u == "payout-withdrawal":
        m = r1ap_read(r"A fund of " + R1TV_M + r" pays " + R1TV_R + r"% per year, compounded (monthly|quarterly)\. (\w+) wants to withdraw the same amount at the end of every month for (\d+) years, leaving the fund empty\.", L[0], "the fund")
        r1tv_who(m.group(4))
        Lo, r, c, n = sp.Integer(m.group(1)), R(m.group(2)), R1TV_FREQ[m.group(3)], int(m.group(5))
        need(asked == "Find the largest monthly withdrawal, to the nearest cent.", f"asked {asked!r}")
        i, N = r1tv_i(r, c), 12 * n
        w = r1tv_pmt(Lo, i, N)
        want = "withdrawal = $" + r1tv_money(w)
        wrongs[R1TV_TN + "9"] = {"withdrawal = $" + r1tv_money(r1tv_mp(Lo / N))}
        wrongs[R1TV_TN + "5"] = {"withdrawal = $" + r1tv_money(r1tv_pmt(Lo, i, n))}
        r1tv_says(q, w)
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, trap)
    return None, None


SITUATION_CHECKS["tvm"] = r1tv_check


# ── log-technology (t1-ext-logs-with-technology, FAL-999) ──────────────
# The log or the equation is read back from the line shown, and every value is worked out
# again with SymPy at 30 digits. The error-spot working is read line by line: a line that names
# x is held to the equation's solution, and a line that evaluates a log to the value of that log.

R1LT_ET = "SL1.5.evaluate-tech#"
R1LT_TL = "t1-ext-logs-with-technology#"


def r1lt_log(key, v):
    return sp.log(v, 10) if key == "log" else sp.log(v)


def r1lt_other(key):
    return "ln" if key == "log" else "log"


def r1lt_x(line):
    """The solution of the equation shown, and its parts."""
    m = re.fullmatch(r"(10|e)\^x = (\d+(?:\.\d)?)", line)
    if m:
        key = "log" if m.group(1) == "10" else "ln"
        b = R(m.group(2))
        return r1lt_log(key, b), ("one", key, b)
    m = re.fullmatch(r"(\d+(?:\.\d+)?)\^x = (\d+)", line)
    need(m is not None, f"can't read the equation {line!r}")
    a, b = R(m.group(1)), R(m.group(2))
    return sp.log(b) / sp.log(a), ("base", a, b)


def r1lt_close(shown, true):
    return abs(R(shown.replace("−", "-")) - sp.N(true, 30)) < sp.Rational(6, 10**7)


def r1lt_spot(q, lines):
    x, _ = r1lt_x(q["lines"][0])
    for idx, line in enumerate(lines):
        ok = None
        m = re.fullmatch(r"x = (log|ln) (\d+(?:\.\d)?)", line)
        if m:
            ok = abs(sp.N(r1lt_log(m.group(1), R(m.group(2))) - x, 30)) < sp.Rational(1, 10**12)
        if ok is None and (mm := re.fullmatch(r"x = log\((\d+) ÷ (\d+(?:\.\d+)?)\)", line)):
            ok = abs(sp.N(sp.log(R(mm.group(1)) / R(mm.group(2)), 10) - x, 30)) < sp.Rational(1, 10**12)
        if ok is None and (mm := re.fullmatch(r"x = log (\d+) ÷ log (\d+(?:\.\d+)?)", line)):
            ok = abs(sp.N(sp.log(R(mm.group(1))) / sp.log(R(mm.group(2))) - x, 30)) < sp.Rational(1, 10**12)
        if ok is None and (mm := re.fullmatch(r"(log|ln) (\d+(?:\.\d)?) = (−?\d+\.\d{6})", line)):
            ok = r1lt_close(mm.group(3), r1lt_log(mm.group(1), R(mm.group(2))))
        if ok is None and (mm := re.fullmatch(r"log\((\d+) ÷ (\d+(?:\.\d+)?)\) = (−?\d+\.\d{6})", line)):
            ok = r1lt_close(mm.group(3), sp.log(R(mm.group(1)) / R(mm.group(2)), 10))
        if ok is None and (mm := re.fullmatch(r"log (\d+) ÷ log (\d+(?:\.\d+)?) = (−?\d+\.\d{6})", line)):
            ok = r1lt_close(mm.group(3), sp.log(R(mm.group(1))) / sp.log(R(mm.group(2))))
        if ok is None and (mm := re.fullmatch(r"x = (−?\d+\.\d{6})", line)):
            ok = r1lt_close(mm.group(1), x)
        if ok is None and (mm := re.fullmatch(r"x = (\S+) to 3 s\.f\.", line)):
            ok = mm.group(1) == gc_s(sp.N(x, 30))
        need(ok is not None, f"can't read the working line {line!r}")
        if not ok:
            return idx
    return None


def r1lt_check(q):
    u, L, asked = q["view"]["unknown"], q["lines"], q["asked"]
    need(q["paper"] == 2, "the GDC's log keys are Paper 2")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs = {}
    if u == "evaluate-log":
        m = r1ap_read(r"(log|ln) (\d+(?:\.\d)?)", L[0], "the log")
        need(asked == f"Use your GDC to find the value of {L[0]}, correct to 3 significant figures.", f"asked {asked!r}")
        key, b = m.group(1), R(m.group(2))
        v = sp.N(r1lt_log(key, b), 30)
        o = sp.N(r1lt_log(r1lt_other(key), b), 30)
        need(r1ap_clear3(v) and r1ap_clear3(o) and gc_s(v) != gc_s(o), "a value is on a 3 s.f. edge, or the two keys read the same")
        want, trap = r1ap_sf(f"{L[0]} = ", v)
        wrongs[R1LT_ET + "0"] = {r1ap_sf(f"{L[0]} = ", o)[0]}
    elif u in ("solve-ten-or-e", "solve-base"):
        need(asked == "Solve the equation, giving x correct to 3 significant figures.", f"asked {asked!r}")
        x, (kind, p1, p2) = r1lt_x(L[0])
        x = sp.N(x, 30)
        need(r1ap_clear3(x), "x is on a 3 s.f. edge")
        want, trap = r1ap_sf("x = ", x)
        if u == "solve-ten-or-e":
            need(kind == "one", "not 10^x or e^x")
            wrongs[R1LT_ET + "0"] = {r1ap_sf("x = ", sp.N(r1lt_log(r1lt_other(p1), p2), 30))[0]}
        else:
            need(kind == "base" and p1 in {sp.Rational(3, 2), 2, sp.Rational(5, 2), 3, 4, 5, 6, 7, sp.Rational(108, 100), sp.Rational(112, 100), sp.Rational(125, 100)}, "the base is outside the limits")
            wrongs[R1LT_ET + "1"] = {r1ap_sf("x = ", sp.N(sp.log(p2 / p1, 10), 30))[0]}
            wrongs[R1LT_TL + "3"] = {r1ap_sf("x = ", sp.N(sp.log(p1) / sp.log(p2), 30))[0]}
    elif u == "evaluate-expression":
        m1 = re.fullmatch(r"(\d) ln (\d+) − log (\d+)", L[0])
        m2 = re.fullmatch(r"(\d) log (\d+) \+ ln (\d+)", L[0])
        need(m1 or m2, f"can't read {L[0]!r}")
        need(asked == f"Use your GDC to find the value of {L[0]}, correct to 3 significant figures.", f"asked {asked!r}")
        p, a, b = (int((m1 or m2).group(i)) for i in (1, 2, 3))
        k1 = "ln" if m1 else "log"
        sign = -1 if m1 else 1

        def val(ka, kb, early):
            la, lb = sp.N(r1lt_log(ka, a), 30), sp.N(r1lt_log(kb, b), 30)
            if early:
                la, lb = sp.Rational(sig3(la)), sp.Rational(sig3(lb))
            return p * la + sign * lb
        v = val(k1, r1lt_other(k1), False)
        sw = val(r1lt_other(k1), k1, False)
        ea = val(k1, r1lt_other(k1), True)
        need(all(r1ap_clear3(y) for y in (v, sw, ea)) and len({gc_s(y) for y in (v, sw, ea)}) == 3, "a value is on a 3 s.f. edge, or two read the same")
        want, trap = r1ap_sf("value = ", v)
        wrongs[R1LT_ET + "0"] = {r1ap_sf("value = ", sw)[0]}
        wrongs[R1LT_ET + "2"] = {r1ap_sf("value = ", ea)[0]}
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, trap)
    return None, None


SITUATION_CHECKS["log-technology"] = r1lt_check
SPOT_CHECKS["log-technology"] = r1lt_spot


# ── R2 (FAL-1000): the AI SL 5.6 to 5.8 types. Each type's section goes after its own marker. ──

# R2-STATIONARY: t5-ai-stationary-points (ai-stationary), prefix R2SP_ / r2sp_

# ── ai-stationary (t5-ai-stationary-points, FAL-1000) ─────────────────────────
# The checker's own copy of the situation's limits and stories; the engine's is in
# game/engine/situations/ai_stationary.gd and ai_stationary_views.gd. Every function is read back
# from the question's sentences (never its `given`), differentiated and solved again with SymPy,
# exactly where the zeros are rational and as exact roots otherwise; every slip is built again from
# its description in the catalogue. The three f′-graph unknowns are DerivativeGraphViews' questions
# re-tagged, so they go to E12DG_check with this type's refs mapped back to SL5.7's.

R2SP_SZ = "AI-SL5.6.solve-gradient-zero#"
R2SP_LE = "AI-SL5.6.locate-local-extrema#"
R2SP_CS = "AI-SL5.6.classify-by-gradient-sign#"
R2SP_GD = "AI-SL5.6.greatest-least-on-domain#"
R2SP_RG = "AI-SL5.6.read-from-gradient-graph#"
R2SP_TT = "t5-ai-stationary-points#"
R2SP_EDGE = sp.Rational(39, 1000)       # the engine's is 0.04
# A story: its function's letter, input letter, output unit, the sentence before the formula, what
# the output is.
R2SP_STORY = {
    "still": ("T", "t", "°C", "A still in the camp is lit at dawn. Its temperature, T °C, t hours after it is lit, is modelled by", "temperature"),
    "track": ("h", "x", "m", "A track leaves the camp and crosses a dry valley. Its height above the valley floor, h metres, x km from the camp, is modelled by", "height"),
    "turbine": ("P", "v", "kW", "A salvaged wind turbine gives P kW of power in a wind of v m/s, where", "power"),
    "reservoir": ("D", "t", "m", "The depth of water in a reservoir, D metres, t weeks after the rains begin, is modelled by", "depth"),
    "flare": ("h", "t", "m", "A flare is fired upwards from a watchtower. Its height above the ground, h metres, t seconds after it is fired, is modelled by", "height"),
    "drone": ("F", "v", "ml", "A scout drone flying at v km/h uses F millilitres of fuel per km, where", "fuel used per km"),
}
R2SP_RATE = {
    "still": "A still in the camp is lit at dawn. Its temperature is T °C, t hours after it is lit, for {lo} ≤ t ≤ {hi}. The rate of change of T is",
    "track": "A track leaves the camp and crosses a dry valley. Its height above the valley floor is h metres, x km from the camp, for {lo} ≤ x ≤ {hi}. The rate of change of h is",
    "turbine": "A salvaged wind turbine gives P kW of power in a wind of v m/s, for {lo} ≤ v ≤ {hi}. The rate of change of P is",
    "reservoir": "The depth of water in a reservoir is D metres, t weeks after the rains begin, for {lo} ≤ t ≤ {hi}. The rate of change of D is",
}
R2SP_SUP = {"": 1, "²": 2, "³": 3}
R2SP_NUM = r"−?\d+(?:\.\d+)?"


def r2sp_n(x):
    """An exact value as itself when rational, else to 40 digits (gc_s takes no surds)."""
    x = sp.sympify(x)
    return x if x.is_Rational else sp.N(x, 40)


def r2sp_gs(x):
    return gc_s(r2sp_n(x))


def r2sp_gs2(x):
    return gc_s2(r2sp_n(x))


def r2sp_fair(x):
    return gc_fair(r2sp_n(x))


def r2sp_q(t):
    return sp.Rational(t.replace("−", "-"))


def r2sp_terms(text, var="x", k=False):
    """A sum of terms the way the game writes them ('0.21t³ − 2.99t² + 12.5t + 30', '2x + 18/x − 5',
    'x³ + kx² − 9x + 4') as SymPy in x (and k), read term by term."""
    s = text.strip()
    need(not re.search(r"(?<![A-Za-z])-\d", s), f"a hyphen for a minus in {text!r}")
    s = s.replace(" − ", " + −").replace(" + ", "\t")
    out = sp.Integer(0)
    K = sp.Symbol("k")
    for i, term in enumerate(s.split("\t")):
        sign = 1
        if term.startswith("−"):
            sign, term = -1, term[1:]
        m = re.fullmatch(r"(\d+)/" + var + "(²?)", term)
        if m:
            out += sign * sp.Integer(m.group(1)) / CX ** (2 if m.group(2) else 1)
            continue
        m = re.fullmatch(r"(\d+(?:\.\d+)?)?(k)?(" + var + r")?([²³]?)", term)
        need(m is not None and term != "", f"can't read the term {term!r} in {text!r}")
        need(not m.group(4) or m.group(3), f"a power with no {var} in {term!r}")
        need(k or not m.group(2), f"a letter k in {text!r}")
        c = sp.Rational(m.group(1)) if m.group(1) else sp.Integer(1)
        if m.group(1) and m.group(1) == "1" and (m.group(2) or m.group(3)):
            need(False, f"a coefficient of 1 is written in {text!r}")
        p = R2SP_SUP[m.group(4)] if m.group(3) else 0
        out += sign * c * (K if m.group(2) else 1) * CX ** p
    return sp.expand(out)


def r2sp_dom(lo, hi):
    return r2sp_q(lo), r2sp_q(hi)


def r2sp_read(q):
    """The function in the first line: (f, var, letter, lo, hi, story, recip)."""
    L = q["lines"]
    m = re.fullmatch(r"(f)\((x)\) = (.+?)(?:, for (−?\d+) ≤ x ≤ (−?\d+)\.|(, for x > 0\.))?", L[0])
    if m:
        f = r2sp_terms(m.group(3))
        lo, hi = (r2sp_q(m.group(4)), r2sp_q(m.group(5))) if m.group(4) else (None, None)
        return f, "x", "f", lo, hi, None, m.group(6) is not None
    for story, (fs, v, unit, head, what) in R2SP_STORY.items():
        if L[0].startswith(head + " "):
            rest = L[0][len(head) + 1:]
            m = re.fullmatch(rf"{fs}\({v}\) = (.+), for (\d+) ≤ {v} ≤ (\d+)\.", rest)
            need(m is not None, f"can't read the model in {L[0]!r}")
            return r2sp_terms(m.group(1), v), v, fs, R(m.group(2)), R(m.group(3)), story, False
    raise Fail(f"can't read the function in {L[0]!r}")


def r2sp_num(x):
    return sp.N(x, 40)


def r2sp_whole(x):
    return x.is_Rational and x.q == 1


def r2sp_sf(x):
    return r2sp_gs(x)


def r2sp_clear(x):
    """x is at least R2SP_EDGE of its 3rd figure from a rounding edge."""
    v = abs(r2sp_num(x))
    if v == 0:
        return True
    e = sp.floor(sp.log(v, 10))
    scaled = v / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= R2SP_EDGE


def r2sp_opt(x, exact):
    """A value as a wrong option shows it: in an exact question its 3 s.f. as a decimal, else 3 s.f."""
    if exact:
        return dec_text(x) if r2sp_whole(sp.nsimplify(x) if x.is_Rational else x) else dec_text(sp.Rational(sig3(x)))
    return r2sp_gs(x)


def r2sp_ans(x, exact):
    return dec_text(x) if exact else r2sp_gs(x)


def r2sp_xs(v, xs, show):
    names = [show(x) for x in sorted(xs, key=lambda t: float(r2sp_num(t)))]
    return f"{v} = " + (names[0] if len(names) == 1 else ", ".join(names[:-1]) + " or " + names[-1])


def r2sp_zeros(e):
    """The real zeros of a polynomial (or of a rational function's top), exact, in order."""
    top = sp.numer(sp.together(e))
    return sorted(sp.Poly(top, CX).real_roots(), key=lambda t: float(r2sp_num(t)))


def r2sp_kind(d, x):
    """'maximum' or 'minimum' at a zero x of d, from its sign either side."""
    eps = sp.Rational(1, 10**6)
    l, r = r2sp_num(d.subs(CX, x - eps)), r2sp_num(d.subs(CX, x + eps))
    need(l * r < 0, "f′ does not change sign at its zero")
    return "maximum" if l > 0 else "minimum"


def r2sp_w(text, x):
    """A working value (6 s.f.) agrees with x to its last figure."""
    v = r2sp_num(x)
    if v == 0:
        return r2sp_q(text) == 0
    e = sp.floor(sp.log(abs(v), 10))
    return abs(r2sp_q(text) - v) <= sp.Integer(10) ** (e - 5) * sp.Rational(6, 10)


def r2sp_steps_have(q, method, pattern, values):
    """In the worked solution by `method`, a step matches pattern and its numbers are the values."""
    for sol in q["solutions"]:
        if sol["angle"] != method:
            continue
        for st in sol["steps"]:
            m = re.search(pattern, st)
            if m:
                for g, x in zip(m.groups(), values):
                    need(r2sp_w(g, x), f"{method}: {g} in {st!r} is not {float(r2sp_num(x)):.7g}")
                return
        need(False, f"{method}: no step like {pattern!r}")


def r2sp_deriv_step(q, d, name, v):
    """Every step that writes the derivative out writes it right."""
    for sol in q["solutions"]:
        for st in sol["steps"]:
            m = re.search(re.escape(name) + r" = ([^=,.]+(?:\.\d[^=,.]*)*)(?:\.$| = |, |\.\s)", st)
            if m and "k" not in m.group(1) and "(" not in m.group(1):
                need(sp.expand(r2sp_terms(m.group(1).strip(), v) - d) == 0, f"{sol['angle']}: {name} = {m.group(1)!r} is not {d}")


def r2sp_check(q):
    u, L, asked, rep = q["view"]["unknown"], q["lines"], q["asked"], q["view"]["rep"]
    need(q["paper"] == 2, "every AI question is Paper 2")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    if u in R2SP_DG:
        return r2sp_dg(q)
    wrongs, want, trap = {}, None, None
    if u == "gradient-zero-x":
        f, v, fs, lo, hi, story, recip = r2sp_read(q)
        d = sp.diff(f, CX)
        xs = r2sp_zeros(d)
        if recip:
            xs = [x for x in xs if x > 0]
        if story:
            need(all(lo < x < hi for x in xs), "a zero of the rate is outside the domain")
            need(asked == f"Find the {'values' if len(xs) > 1 else 'value'} of {v} at which the rate of change of {fs} is zero.", f"asked {asked!r}")
        else:
            need(asked == f"Find the {'values' if len(xs) > 1 else 'value'} of x where the gradient of the graph of f is zero.", f"asked {asked!r}")
        need(xs and len(xs) <= 2, "f′ should have one or two zeros")
        exact = all(r2sp_whole(x) for x in xs)
        if not exact:
            need(all(r2sp_fair(x) for x in xs), "a zero is on a 3 s.f. edge or nearly whole")
        want = r2sp_xs(v, xs, lambda x: r2sp_ans(x, exact))
        show = lambda x: r2sp_opt(x, exact)
        if recip:
            c0 = f.as_coefficients_dict().get(sp.Integer(1), 0)
            rs = [x for x in r2sp_zeros(f) if x > 0]
            kept = [x for x in r2sp_zeros(d + c0) if x > 0] if c0 != 0 else []
        else:
            c0 = f.subs(CX, 0)
            rs = r2sp_zeros(f)
            if story:
                rs = [x for x in rs if x >= lo]
            kept = r2sp_zeros(d + c0) if c0 != 0 else []
        if rs:
            wrongs[R2SP_SZ + "0"] = {r2sp_xs(v, rs, show)}
        if kept:
            wrongs[R2SP_SZ + "1"] = {r2sp_xs(v, kept, show)}
        if not recip and not story and sp.expand(d.subs(CX, -CX) - d) == 0:
            wrongs[R2SP_SZ + "2"] = {r2sp_xs(v, [max(xs, key=lambda t: float(r2sp_num(t)))], show)}
        dn = f"d{fs}/d{v}" if story else "f′(x)"
        r2sp_deriv_step(q, d, dn, v)
        if len(xs) == 2 and not exact:
            r2sp_steps_have(q, "gdc-equation-solver", rf"shows {v} = ({R2SP_NUM}) and ({R2SP_NUM})", xs)
    elif u == "gradient-zero-given-derivative":
        if rep == "equation":
            m = re.fullmatch(r"f′\(x\) = (.+)", L[0])
            need(m is not None, f"can't read {L[0]!r}")
            d, v, fs, lo, hi = r2sp_terms(m.group(1)), "x", "f", None, None
            ma = re.fullmatch(r"Find the x-coordinate of the local (maximum|minimum) of f\.", asked)
        else:
            d = None
            for story, head in R2SP_RATE.items():
                fs, v = R2SP_STORY[story][0], R2SP_STORY[story][1]
                m = re.fullmatch(re.escape(head).replace(r"\{lo\}", r"(\d+)").replace(r"\{hi\}", r"(\d+)") + rf" d{fs}/d{v} = (.+)\.", L[0])
                if m:
                    lo, hi, d = R(m.group(1)), R(m.group(2)), r2sp_terms(m.group(3), v)
                    break
            need(d is not None, f"can't read the rate in {L[0]!r}")
            ma = re.fullmatch(rf"Find the value of {v} at which {fs} has a local (maximum|minimum)\.", asked)
        need(ma is not None, f"asked {asked!r}")
        kind = ma.group(1)
        xs = r2sp_zeros(d)
        need(len(xs) == 2, "f′ should have two zeros")
        if lo is not None:
            need(all(lo < x < hi for x in xs), "a zero is outside the domain")
        hits = [x for x in xs if r2sp_kind(d, x) == kind]
        need(len(hits) == 1, f"no single local {kind}")
        x = hits[0]
        o = [t for t in xs if t != x][0]
        exact = all(r2sp_whole(t) for t in xs)
        if not exact:
            need(r2sp_fair(x) and r2sp_fair(o), "a zero is on a 3 s.f. edge")
        want = f"{v} = " + r2sp_ans(x, exact)
        trap = None if exact else gc_trap([r2sp_n(x)], f"{v} = " + r2sp_gs2(x))
        if sp.expand(d.subs(CX, -CX) - d) == 0:
            need(x < 0, "the extremum asked is not at the negative zero, so the positive one is no slip")
            wrongs[R2SP_SZ + "2"] = {f"{v} = " + r2sp_opt(o, exact)}
        else:
            wrongs[R2SP_CS + "0"] = {f"{v} = " + r2sp_opt(o, exact)}
        if not exact:
            r2sp_steps_have(q, "gdc-equation-solver", rf"It shows {v} = ({R2SP_NUM}) and ({R2SP_NUM})", xs)
    elif u == "coefficient-from-stationary":
        m = re.fullmatch(r"f\(x\) = (.+), where k is a constant\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        f = r2sp_terms(m.group(1), "x", k=True)
        K = sp.Symbol("k")
        need(sp.degree(f, K) == 1, "k is not one coefficient")
        mx = re.fullmatch(r"The graph of f has a stationary point where x = (−?\d+)\.", L[1])
        need(mx is not None, f"can't read {L[1]!r}")
        X = r2sp_q(mx.group(1))
        need(asked == "Find the value of k.", f"asked {asked!r}")
        k = sp.solve(sp.diff(f, CX).subs(CX, X), K)
        need(len(k) == 1, "no single k")
        k = k[0]
        need((k * 10).is_integer and k != 0, f"k = {k} is not a one-decimal value")
        want = "k = " + dec_text(k)
        ks = sp.solve(f.subs(CX, X), K)
        need(len(ks) == 1, "f(x) = 0 gives no single k")
        need(r2sp_clear(ks[0]), "the f(x) = 0 slip is on a 3 s.f. edge")
        wrongs[R2SP_SZ + "0"] = {"k = " + r2sp_opt(ks[0], True)}
        for sol in q["solutions"]:
            gives = [re.search(r"which gives (.+) = 0\.$", st) for st in sol["steps"]]
            for g in gives:
                if g:
                    need(sp.expand(r2sp_terms(g.group(1), "x", k=True) - sp.diff(f, CX).subs(CX, X)) == 0,
                         f"{sol['angle']}: {g.group(1)} = 0 is not f′({X}) = 0")
        need(len(r2sp_zeros(sp.diff(f.subs(K, k), CX))) == 2, "f has no two stationary points")
    elif u == "local-extremum-point":
        f, v, fs, lo, hi, story, recip = r2sp_read(q)
        ma = re.fullmatch(r"Find the coordinates of the local (maximum|minimum) point of the graph of f\.", asked)
        need(ma is not None, f"asked {asked!r}")
        kind = ma.group(1)
        d = sp.diff(f, CX)
        xs = [x for x in r2sp_zeros(d) if not recip or x > 0]
        hits = [x for x in xs if r2sp_kind(d, x) == kind]
        need(len(hits) == 1, f"no single local {kind}")
        x = hits[0]
        y = sp.nsimplify(sp.simplify(f.subs(CX, x))) if x.is_Rational else f.subs(CX, x)
        exact = r2sp_whole(x) and r2sp_whole(sp.nsimplify(y)) if x.is_Rational else False
        if exact:
            y = sp.nsimplify(y)
        else:
            need(r2sp_clear(x) and r2sp_clear(y), "a coordinate is on a 3 s.f. edge")
        sh = lambda t: r2sp_ans(t, exact)
        want = f"({sh(x)}, {sh(y)})"
        op = lambda t: r2sp_opt(t, exact)
        wrongs[R2SP_LE + "0"] = {f"({op(x)}, 0)"}
        wrongs[R2SP_LE + "1"] = {f"x = {op(x)}"}
        if rep == "graph":
            mw = re.fullmatch(r"The GDC shows the graph of y = f\(x\) in the window (−?\d+) ≤ x ≤ (−?\d+), (−?\d+) ≤ y ≤ (−?\d+)\.", L[1])
            need(mw is not None, f"can't read the window {L[1]!r}")
            x0, x1, y0, y1 = (r2sp_q(mw.group(i)) for i in range(1, 5))
            g = q["graph"]
            need(g is not None and (g["x0"], g["x1"], g["y0"], g["y1"]) == (int(x0), int(x1), int(y0), int(y1)), "the window drawn is not the one given")
            c = g["curves"][0]
            need(co_curve_is(c, f), "the curve drawn is not f")
            need(abs(c[0][0] - float(x0)) < 1e-9 and abs(c[-1][0] - float(x1)) < 1e-9, "the curve does not reach both sides of the window")
            need(all(float(y0) <= p[1] <= float(y1) for p in c), "the curve leaves the window through the top or bottom")
            need(all(x0 < t < x1 for t in xs), "a turning point is off the screen")
            edges = [e for e in (x0, x1) if (f.subs(CX, e) > y) == (kind == "maximum")]
            need(edges, "no end of the screen is beyond the extremum")
            wrongs[R2SP_LE + "2"] = {f"({op(e)}, {op(f.subs(CX, e))})" for e in edges}
        elif not recip:
            need(q["graph"] is None, "an equation question draws a graph")
    elif u == "extremum-value-in-context":
        f, v, fs, lo, hi, story, recip = r2sp_read(q)
        need(story is not None, "not a story")
        what = R2SP_STORY[story][4]
        ma = re.fullmatch(r"Find the (greatest|least) (.+)\.", asked)
        need(ma is not None and ma.group(2) == what, f"asked {asked!r}")
        big = ma.group(1) == "greatest"
        kind = "maximum" if big else "minimum"
        d = sp.diff(f, CX)
        xs = [x for x in r2sp_zeros(d) if lo < x < hi]
        hits = [x for x in xs if r2sp_kind(d, x) == kind]
        need(len(hits) == 1, f"no single local {kind} on the domain")
        x = hits[0]
        y = f.subs(CX, x)
        for e in (lo, hi):
            ye = f.subs(CX, e)
            need((ye < y) if big else (ye > y), "an end beats the stationary value")
        need(r2sp_fair(y) and r2sp_fair(x) and r2sp_clear(f.subs(CX, hi)), "a value is on a 3 s.f. edge")
        lab, unit = f"{fs} = ", " " + R2SP_STORY[story][2]
        want = lab + r2sp_gs(y) + unit
        trap = gc_trap([r2sp_n(y)], lab + r2sp_gs2(y) + unit)
        inp = {lab + r2sp_gs(x) + unit}
        wrongs[R2SP_LE + "1"] = inp
        wrongs[R2SP_TT + "16"] = inp
        wrongs[R2SP_TT + "17"] = {lab + r2sp_gs(f.subs(CX, hi)) + unit}
        if sp.degree(f, CX) == 2:
            a2 = sp.Poly(f, CX).LC()
            need((a2 < 0) == big, "the quadratic's vertex is the other kind")
        else:
            need(not any(sol["angle"] == "vertex-of-quadratic" for sol in q["solutions"]), "a cubic model has a vertex working")
        r2sp_steps_have(q, "gdc-max-min", rf"at {v} = ({R2SP_NUM}), {fs} = ({R2SP_NUM})", [x, y])
    elif u == "classify-stationary":
        f, v, fs, lo, hi, story, recip = r2sp_read(q)
        d = sp.diff(f, CX)
        ms = re.fullmatch(r"The graph of f has stationary points at x = (−?\d+) and x = (−?\d+)\.", L[1])
        need(ms is not None, f"can't read {L[1]!r}")
        sts = [r2sp_q(ms.group(1)), r2sp_q(ms.group(2))]
        need(sorted(r2sp_zeros(d)) == sorted(sts), "those are not the stationary points")
        ma = re.fullmatch(r"Determine the nature of the stationary point at x = (−?\d+)\. Which answer is fully justified\?", asked)
        need(ma is not None, f"asked {asked!r}")
        p = r2sp_q(ma.group(1))
        need(p in sts, "the point asked is not stationary")
        other = [t for t in sts if t != p][0]
        h = sp.Rational(1, 10) if rep == "table" else sp.Integer(1)
        need(abs(other - p) >= 2, "the stationary points are too close for the test points")
        tl, tr = p - h, p + h
        P0, TL, TR = dec_text(p), dec_text(tl), dec_text(tr)
        sw = lambda z: "positive" if z > 0 else "negative"
        rl = lambda z: ">" if z > 0 else "<"
        dl, dr = d.subs(CX, tl), d.subs(CX, tr)
        kind = r2sp_kind(d, p)
        okind = "minimum" if kind == "maximum" else "maximum"
        ev = f"f′({TL}) {rl(dl)} 0 and f′({TR}) {rl(dr)} 0"
        ch = f"so f′ changes from {sw(dl)} to {sw(dr)} at x = {P0}"
        want = f"Local {kind}: {ev}, {ch}"
        fl, fr = f.subs(CX, tl), f.subs(CX, tr)
        need(fl != 0 and fr != 0, "f is zero at a test point")
        if (fl > 0) == (fr > 0):
            fc = f"Neither: f({TL}) {rl(fl)} 0 and f({TR}) {rl(fr)} 0, so f does not change sign at x = {P0}"
        else:
            fc = f"Local {'maximum' if fl > 0 else 'minimum'}: f({TL}) {rl(fl)} 0 and f({TR}) {rl(fr)} 0, so f changes from {sw(fl)} to {sw(fr)} at x = {P0}"
        uu, ww = min(sts) - 1, max(sts) + 1
        du, dw = d.subs(CX, uu), d.subs(CX, ww)
        need((du > 0) == (dw > 0), "the far test points have different signs")
        wrongs = {R2SP_CS + "0": {f"Local {okind}: {ev}, {ch}"}, R2SP_CS + "1": {fc},
                  R2SP_CS + "2": {f"Neither: f′({dec_text(uu)}) {rl(du)} 0 and f′({dec_text(ww)}) {rl(dw)} 0, so f′ does not change sign at x = {P0}"}}
        if rep == "table":
            t = q["table"]
            need(t is not None and L[2] == f"The table gives f(x) and f′(x) near x = {P0}.", "no table, or it isn't named")
            xs3 = [tl, p, tr]
            need(t["rows"] == [["x", [dec_text(z) for z in xs3]], ["f(x)", [dec_text(f.subs(CX, z)) for z in xs3]],
                               ["f′(x)", [dec_text(d.subs(CX, z)) for z in xs3]]], f"the table is wrong: {t['rows']}")
        a3 = sp.Poly(f, CX).LC()
        need((kind == "maximum") == ((p < other) == (a3 > 0)), "the cubic-shape rule disagrees")
    elif u == "greatest-on-domain":
        f, v, fs, lo, hi, story, recip = r2sp_read(q)
        need(lo is not None, "no domain")
        ma = re.fullmatch(rf"Find the (greatest|least) value of {re.escape('f(x)') if not story else fs} for (−?\d+) ≤ {v} ≤ (−?\d+)\.", asked)
        need(ma is not None and (r2sp_q(ma.group(2)), r2sp_q(ma.group(3))) == (lo, hi), f"asked {asked!r}")
        big = ma.group(1) == "greatest"
        kind = "maximum" if big else "minimum"
        d = sp.diff(f, CX)
        sts = r2sp_zeros(d)
        need(len(sts) == 2, "f should have two stationary points")
        inside = [x for x in sts if lo < x < hi]
        cands = [(lo, f.subs(CX, lo), "end"), (hi, f.subs(CX, hi), "end")] + [(x, f.subs(CX, x), "st") for x in inside]
        key = lambda c: r2sp_num(c[1])
        b = max(cands, key=key) if big else min(cands, key=key)
        need(sum(1 for c in cands if abs(r2sp_num(c[1] - b[1])) < sp.Rational(1, 100)) == 1, "two candidates tie")
        exact = story is None
        if exact:
            need(all(r2sp_whole(c[1]) for c in cands), "a value on the domain is not whole")
        lab, unit = (f"{ma.group(1)} value = ", "") if exact else (f"{fs} = ", " " + R2SP_STORY[story][2])
        want = lab + r2sp_ans(b[1], exact) + unit
        trap = None if exact else gc_trap([r2sp_n(b[1])], lab + r2sp_gs2(b[1]) + unit)
        op = lambda t: lab + r2sp_opt(t, exact) + unit
        asked_in = [x for x in inside if r2sp_kind(d, x) == kind]
        no_ends = set()
        if b[2] == "end" and asked_in:
            if big:
                wrongs[R2SP_GD + "0"] = {op(f.subs(CX, asked_in[0]))}
            no_ends.add(op(f.subs(CX, asked_in[0])))
        outs = [x for x in sts if not lo < x < hi]
        beat = [x for x in outs if ((f.subs(CX, x) > b[1]) if big else (f.subs(CX, x) < b[1]))]
        if beat:
            wrongs[R2SP_GD + "1"] = {op(f.subs(CX, x)) for x in beat}
        if not asked_in and inside:
            no_ends |= {op(f.subs(CX, x)) for x in inside}
        if no_ends:
            wrongs[R2SP_GD + "2"] = no_ends
    elif u == "local-not-greatest":
        f, v, fs, lo, hi, story, recip = r2sp_read(q)
        need(lo is not None, "no domain")
        exact = story is None
        d = sp.diff(f, CX)
        sts = r2sp_zeros(d)
        need(len(sts) == 2 and all(lo < x < hi for x in sts), "both stationary points should be inside the domain")
        ma = re.fullmatch(rf"Is the local (maximum|minimum) value the (greatest|least) value of {fs} for (−?\d+) ≤ {v} ≤ (−?\d+)\? Which answer is fully justified\?", asked)
        need(ma is not None and (r2sp_q(ma.group(3)), r2sp_q(ma.group(4))) == (lo, hi), f"asked {asked!r}")
        kind = ma.group(1)
        big = kind == "maximum"
        need(ma.group(2) == ("greatest" if big else "least"), "the question pairs the wrong words")
        x = [t for t in sts if r2sp_kind(d, t) == kind][0]
        y = f.subs(CX, x)
        Vf = lambda t: dec_text(t) if (exact or r2sp_whole(t)) else r2sp_gs(t)
        fx = lambda t: f"{fs}({Vf(t)})"
        if story:
            need(L[1] == f"{fs} has a local {kind} at {v} = {Vf(x)}.", f"{L[1]!r}")
        else:
            need(L[1] == f"The graph of y = f(x) is shown. f has a local {kind} at x = {Vf(x)}.", f"{L[1]!r}")
            g = q["graph"]
            need(g is not None and co_curve_is(g["curves"][0], f), "the curve drawn is not f")
            need(abs(g["curves"][0][0][0] - float(lo)) < 1e-9 and abs(g["curves"][0][-1][0] - float(hi)) < 1e-9, "the curve is not drawn on the domain")
        ends = [e for e in (lo, hi) if ((f.subs(CX, e) > y) if big else (f.subs(CX, e) < y))]
        need(len(ends) == 1, "not exactly one end beyond the local extremum")
        e = ends[0]
        more = "greater" if big else "less"
        want = f"No: {fx(e)} = {Vf(f.subs(CX, e))} is {more} than the local {kind}, {fx(x)} = {Vf(y)}"
        zero_at = f"d{fs}/d{v} = 0 at {v} = {Vf(x)}" if story else f"f′({Vf(x)}) = 0"
        wrongs[R2SP_GD + ("0" if big else "2")] = {f"Yes: the local {kind}, {fx(x)} = {Vf(y)}, is the {'greatest' if big else 'least'} value, because {zero_at}"}
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, trap)
    return None, None


R2SP_DG = {"extremum-from-gradient-graph": "extremum-from-derivative", "increasing-from-gradient-graph": "increasing-past-touch",
           "pick-f-from-gradient-graph": "pick-f-from-derivative"}


def r2sp_dg(q):
    """The derivative-graph question, its refs mapped back to SL5.7's and checked there."""
    u = q["view"]["unknown"]
    c = json.loads(json.dumps(q))
    c["paper"] = 1
    c["view"]["unknown"] = R2SP_DG[u]
    F = E12DG_F
    if u == "pick-f-from-gradient-graph":
        mine = {"copy": "", "flipped": R2SP_RG + "1", "touch-turn": R2SP_RG + "2", "peak": R2SP_RG + "0"}
        theirs = {"copy": F + "10", "flipped": F + "11", "touch-turn": F + "1", "peak": F + "0"}
        for o in c["choices"]:
            if o["correct"]:
                continue
            need(o["mistake"] in mine and o["ref"] == mine[o["mistake"]], f"{o['text']}: {o['mistake']} tagged {o['ref']!r}")
            o["ref"] = theirs[o["mistake"]]
        return E12DG_check(c)
    back = {R2SP_RG + "0": F + "0", R2SP_RG + "2": F + "1" if u == "extremum-from-gradient-graph" else F + "5"}
    if u == "extremum-from-gradient-graph":
        back[R2SP_RG + "1"] = F + "11"
        if any(o["ref"] == R2SP_RG + "1" for o in q["choices"]):
            need("local maximum" in q["asked"], "a maximum read at the other crossing is the slip only when a maximum is asked")
    for o in c["choices"]:
        if o["ref"] == R2SP_TT + "15":
            # Where the graph of f′ rises: f″ > 0, between or outside its turning points.
            need(q["asked"] == "Find the values of x for which f is increasing.", "the f′-rises slip on a decreasing question")
            e = E12DG_curve(c)
            dd = sp.diff(e, CX)
            ts = sorted(E12DG_changes(dd))
            need(len(ts) == 2, "f′ should have two turning points")
            need(o["text"] == mo_iv(E12DG_shape(dd, ts[0], ts[1], True), ts[0], ts[1]), f"{o['text']!r} is not where f′ rises")
            o["ref"] = ""
        elif o["ref"]:
            need(o["ref"] in back, f"{o['ref']} is no slip of {u}")
            o["ref"] = back[o["ref"]]
    return E12DG_check(c)


SITUATION_CHECKS["ai-stationary"] = r2sp_check


# (between the R2 markers)

# R2-OPTIMISATION: t5-ai-optimisation (ai-optimisation), prefix R2OP_ / r2op_

# ── ai-optimisation (t5-ai-optimisation, FAL-1000) ───────────────────
# The `ai-optimisation` situation's clean limits, the checker's own copy: the engine's is in
# game/engine/situations/ai_optimisation.gd. A given model is read back from its line and
# optimised again with SymPy (exactly where it is a polynomial or has a 1/x term, at 40 digits
# where it is an angle model); a price and its demand are read from the sentences; a shape is
# read by om_read (the optimisation-model checker's reader), as the AA type's stories are
# reused. Every answer and every tagged slip is worked out again from what the slip says, and
# the GDC readings and sign tests in the working are checked against the numbers.

R2OP_G = "AI-SL5.7.optimise-given-model#"
R2OP_B = "AI-SL5.7.build-model-from-constraint#"
R2OP_C = "AI-SL5.7.optimise-container#"
R2OP_I = "AI-SL5.7.interpret-optimum-in-context#"
R2OP_OWN = "t5-ai-optimisation#"
R2OP_EDGE = sp.Rational(39, 1000)      # the engine's is 0.04
R2OP_X = sp.Symbol("x", positive=True)
R2OP_SHAPES = ("constraint-second-length", "objective-one-variable", "container-optimal-dimension",
               "container-optimum-value", "container-other-dimension", "route-least-time", "context-domain")
R2OP_UNITS = [(r"at x scrap a jug|x scrap to sharpen|at x scrap a metre|x scrap a blade", " scrap"), (r"x km/h", " km/h"),
              (r"x litres a minute", " litres a minute"), (r"x kg of charcoal an hour", " kg an hour"),
              (r"x tonnes of scrap steel", " tonnes"), (r"x hundred litres", " hundred litres"), (r"x kg of wild seed", " kg")]


def r2op_clear(v, edge=R2OP_EDGE):
    """v reads clearly at 3 s.f.: at least `edge` of a unit of its 3rd figure from a rounding edge."""
    w = abs(sp.N(v, 40))
    if w == 0:
        return False
    e = sp.floor(sp.log(w, 10))
    scaled = w / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= edge


def r2op_w(v):
    """A GDC reading as the working writes it: 6 s.f., no trailing zeros."""
    t = sig3(sp.N(v, 40), 6)
    if "." in t:
        t = t.rstrip("0").rstrip(".")
    return t.replace("-", "−")


def r2op_sf(label, v, unit=""):
    """The answer's text and its rounding trap (None where it needs no rounding)."""
    return f"{label}{gc_s(sp.N(v, 40))}{unit}", (f"{label}{gc_s2(sp.N(v, 40))}{unit}" if gc_rounds(sp.N(v, 40)) else None)


def r2op_expr(text):
    """A model as the game writes it, as SymPy: decimals exact, θ in degrees."""
    t = text.strip().replace("−", "-").replace("×", "*")
    t = re.sub(r"[⁰¹²³⁴⁵⁶⁷⁸⁹]+", lambda m: "**" + m.group(0).translate(SUP_DIGITS), t)
    t = re.sub(r"sin θ \(", "sin(pi*x/180)*(", t)
    t = re.sub(r"(sin|cos) θ", r"\1(pi*x/180)", t)
    t = re.sub(r"\d+\.\d+", lambda m: f"({sp.Rational(m.group(0))})", t)
    need(re.fullmatch(r"[0-9x+\-*/(). a-z]+", t) is not None, f"can't read the model {text!r}")
    return parse_expr(t, transformations=TRANSFORMS, local_dict={"x": R2OP_X, "pi": sp.pi, "sin": sp.sin, "cos": sp.cos})


def r2op_model(q):
    """The given model's line: (letter, F, domain, kind)."""
    L = q["lines"]
    line = next((l for l in L if re.match(r"[PCA]\((x|θ)\) = ", l)), None)
    need(line is not None, "no model line")
    m = re.fullmatch(r"([PCA])\((x|θ)\) = (.+), (for .+)\.", line)
    need(m is not None, f"can't read the model line {line!r}")
    name, var, body, dom = m.groups()
    F = r2op_expr(body)
    text = " ".join(L)
    if var == "θ":
        need(name == "A" and dom == "for 0° < θ < 90°" and "A m²" in text, "an angle model is an area for 0° < θ < 90°")
        kind, lo, hi = "angle", 0, 90
    else:
        need(f"{name} scrap" in text, f"the story doesn't say what {name} is")
        poly = sp.Poly(F, R2OP_X) if F.is_polynomial(R2OP_X) else None
        md = re.fullmatch(r"for 0 ≤ x ≤ (\d+)", dom)
        mw = re.fullmatch(r"for whole numbers x from 1 to (\d+)", dom)
        if poly is not None:
            need(md is not None, f"a polynomial model's domain {dom!r}")
            kind, lo, hi = {2: "quad", 3: "cubic"}.get(poly.degree(), "?"), 0, int(md.group(1))
            need(kind != "?", "the model is not a quadratic or a cubic")
        else:
            need(sp.simplify(sp.diff(F * R2OP_X, R2OP_X, 3)) == 0, "the model is not a x + b/x + c")
            need(dom == "for x > 0" or mw is not None, f"a reciprocal model's domain {dom!r}")
            kind, lo, hi = "recip", 0, (int(mw.group(1)) if mw else sp.oo)
    need(name != "A" or kind == "angle", "A is the angle model's letter")
    return name, F, (lo, hi), kind


def r2op_unit(q):
    text = " ".join(q["lines"])
    if "θ" in text:
        return "°"
    hits = [u for pat, u in R2OP_UNITS if re.search(pat, text)]
    need(len(hits) == 1, "the story's unit of x")
    return hits[0]


def r2op_stationary(F, lo, hi, kind):
    """The stationary points inside the domain, as (x, kind) with kind max or min."""
    x = R2OP_X
    d = sp.diff(F, x)
    if kind == "angle":
        f = sp.lambdify(x, d, "mpmath")
        pts = []
        with mpmath.workdps(40):
            grid = [mpmath.mpf(k) / 4 for k in range(1, 360)]
            for a, b in zip(grid, grid[1:]):
                if f(a) * f(b) < 0:
                    pts.append(sp.Float(str(mpmath.findroot(f, (a, b), solver="anderson", tol=mpmath.mpf(10) ** -32)), 40))
    else:
        pts = [s for s in sp.solve(sp.numer(sp.together(d)), x) if s.is_real and s > lo and (hi == sp.oo or s < hi)]
    out = []
    for p0 in pts:
        d2 = sp.N(sp.diff(F, x, 2).subs(x, p0), 30)
        need(d2 != 0, "a stationary point that is neither")
        out.append((p0, "max" if d2 < 0 else "min"))
    return out


def r2op_steps_have(q, text, what):
    need(any(text in st for sol in q["solutions"] for st in sol["steps"]), f"no working step shows {what} ({text!r})")


def r2op_given(q, u):
    """optimal-input, optimum-value, suggested-not-optimal and whole-number-optimum."""
    name, F, (lo, hi), kind = r2op_model(q)
    x = R2OP_X
    big = name in ("P", "A")
    ang = q["view"]["angle"]
    methods = {s["angle"] for s in q["solutions"]}
    need(kind != "angle" or not methods & {"derivative-zero", "vertex-of-quadratic-model"}, "an angle model has a working that needs calculus or a vertex")
    need(("vertex-of-quadratic-model" in methods) == (kind == "quad" and u in ("optimal-input-given-model", "optimum-value-given-model")), "the vertex working is not on exactly the quadratic models")
    sts = r2op_stationary(F, lo, hi, kind)
    want_kind = "max" if big else "min"
    best = [p0 for p0, k in sts if k == want_kind]
    need(len(best) == 1, f"{len(best)} stationary points of the right kind inside the domain")
    x0 = best[0]
    others = [p0 for p0, k in sts if k != want_kind]
    need((kind == "cubic") == (len(others) == 1) and len(others) <= 1, "only a cubic has the other stationary point")
    v0 = F.subs(x, x0)
    if hi != sp.oo:
        for end in (lo, hi):
            if kind != "angle" and u != "whole-number-optimum":
                need((sp.N(F.subs(x, end) - v0, 30) < 0) == big, "an end of the domain beats the optimum")
    tail = " m²" if name == "A" else " scrap"
    w = {}
    want, trap = None, None
    if u in ("optimal-input-given-model", "optimum-value-given-model"):
        need(r2op_clear(x0) and r2op_clear(v0) and gc_rounds(sp.N(x0, 40)) and gc_rounds(sp.N(v0, 40)), "the optimum or its value is on a rounding edge, or needs no rounding")
        if kind == "cubic":
            m0 = others[0]
            need(r2op_clear(m0) and r2op_clear(F.subs(x, m0)) and gc_s(sp.N(F.subs(x, m0), 40)) != gc_s(sp.N(v0, 40)), "the other stationary point reads badly")
        thing = {"P": "the greatest profit", "C": "the least cost", "A": "the greatest cross-section area"}[name]
        letter = "θ" if kind == "angle" else "x"
        unit = r2op_unit(q)
        if u == "optimal-input-given-model":
            need(q["asked"] == f"Find the value of {letter} that gives {thing}.", f"asked {q['asked']!r}")
            want, trap = r2op_sf(f"{letter} = ", x0, unit)
            if kind == "cubic":
                w[R2OP_G + "2"] = {r2op_sf(f"{letter} = ", others[0], unit)[0]}
        else:
            need(q["asked"] == f"Find {thing}.", f"asked {q['asked']!r}")
            want, trap = r2op_sf(f"{name} = ", v0, tail)
            w[R2OP_G + "0"] = {r2op_sf(f"{name} = ", x0, tail)[0]}
            if kind == "cubic":
                w[R2OP_G + "2"] = {r2op_sf(f"{name} = ", F.subs(x, others[0]), tail)[0]}
        r2op_steps_have(q, f"x = {r2op_w(x0)}", "the optimum to 6 s.f.")
        if u == "optimum-value-given-model":
            r2op_steps_have(q, r2op_w(v0), "the value to 6 s.f.")
        if kind != "angle":
            dtext = next(st for sol in q["solutions"] if sol["angle"] == "derivative-zero" for st in sol["steps"][:1]) if "derivative-zero" in methods else None
            if dtext:
                mt = re.fullmatch(rf"{name}′\(x\) = (.+)\.", dtext)
                need(mt is not None and sp.simplify(r2op_expr(mt.group(1)) - sp.diff(F, x)) == 0, f"the derivative {dtext!r}")
            r2op_sign_tests(q, F, name)
        gc_check_common(q, want, w, trap)
        return
    if u == "suggested-not-optimal":
        need(name == "P" and kind in ("quad", "cubic"), "a suggested value is on a profit polynomial")
        mt = re.fullmatch(r"It is suggested that x = (\d+) gives the greatest profit\.", q["lines"][-1])
        need(mt is not None, f"can't read the suggestion {q['lines'][-1]!r}")
        p0 = int(mt.group(1))
        need(q["asked"] == f"Which statement explains why x = {p0} does not give the greatest profit?", f"asked {q['asked']!r}")
        d0, f0 = sp.diff(F, x).subs(x, p0), F.subs(x, p0)
        need(lo < p0 < hi and d0 != 0 and f0 > 0 and abs(d0) != f0, "the suggestion is outside the limits")
        need(r2op_clear(x0), "the maximum is on a rounding edge")
        d = f"P′({p0}) = {dec_text(d0)}"
        want = f"{d} ≠ 0, so P is not at its maximum at x = {p0}; the maximum is at x = {gc_s(sp.N(x0, 40))}"
        w[R2OP_OWN + "12"] = {f"The profit at x = {p0} is {d} scrap, so it is not the greatest profit"}
        w[R2OP_OWN + "13"] = {f"P({p0}) = {dec_text(f0)} > 0, so x = {p0} gives the greatest profit"}
        for o in q["choices"]:
            if not o["correct"] and not o["ref"]:
                need(o["text"] != want and "≠ 0, so P is not at its maximum" not in o["text"], f"a filler {o['text']!r} is the right claim")
        r2op_steps_have(q, f"x = {r2op_w(x0)}", "the maximum to 6 s.f.")
        r2op_steps_have(q, f"{dec_text(d0)}", "P′ at the suggested value")
        gc_check_common(q, want, w, None)
        return
    # whole-number-optimum
    need(kind == "recip" and hi != sp.oo, "a whole-number model is a x + b/x + c on whole numbers")
    vals = {n: F.subs(x, n) for n in range(1, int(hi) + 1)}
    pick = (max if big else min)(vals, key=lambda n: vals[n])
    need(list(vals.values()).count(vals[pick]) == 1, "two whole numbers tie")
    frac = x0 - sp.floor(x0)
    need(sp.Rational(1, 5) < frac < sp.Rational(4, 5) and r2op_clear(x0), "x is too near a whole number, or on a rounding edge")
    near = int(sp.floor(x0 + sp.Rational(1, 2)))
    need(near != pick and abs(near - pick) == 1, "the nearest whole number is the best one, so the slip is the answer")
    need(q["asked"] == f"Find {'the greatest profit' if big else 'the least cost'}.", f"asked {q['asked']!r}")
    want = f"{name} = {dec_text(vals[pick])} scrap"
    w[R2OP_I + "0"] = {f"{name} = {dec_text(vals[near])} scrap"}
    w[R2OP_G + "0"] = {f"{name} = {pick} scrap"}
    if q["view"]["rep"] == "table":
        rows = q["table"]["rows"]
        need(len(rows) == 2 and all(len(r) == 2 and isinstance(r[1], list) for r in rows), "a table row is not [head, [cells]]")
        need(rows[0][0] == "x" and rows[1][0] == f"{name}(x)", "the table's heads")
        xs = [int(t) for t in rows[0][1]]
        need(len(rows[1][1]) == len(xs), "the table's rows differ in length")
        need(pick in xs and near in xs, "the table leaves out a neighbour of the optimum")
        for n, t in zip(xs, rows[1][1]):
            ex = dec_text(vals[n])
            need(t == ex if "/" not in ex else t == r2op_w(vals[n]), f"the table's {name}({n}) = {t}")
    r2op_steps_have(q, f"x = {r2op_w(x0)}", "the optimum to 6 s.f.")
    r2op_steps_have(q, f"{name}({pick}) = {dec_text(vals[pick])}", "the best whole number's value")
    r2op_steps_have(q, f"{name}({near}) = {dec_text(vals[near])}", "the nearest whole number's value")
    gc_check_common(q, want, w, None)


def r2op_sign_tests(q, F, name):
    """Every 'P′(a) = u and P′(b) = v' in the working is the derivative there, to 3 s.f."""
    d = sp.diff(F, R2OP_X)
    for sol in q["solutions"]:
        for st in sol["steps"]:
            for a, va in re.findall(rf"{name}′\((\d+)\) = (−?[\d.]+)", st):
                need(va == gc_s(sp.N(d.subs(R2OP_X, int(a)), 40)), f"{name}′({a}) is not {va}")


def r2op_demand(q):
    L = q["lines"]
    m1 = re.fullmatch(r"(A trader|A cobbler|A tinker) sells (water filters|pairs of boots|lamps) at p scrap each\. At that price, (\d+) − (\d+)p \2 are sold (a week|a month)\.", L[0])
    m2 = re.fullmatch(r"Each (filter|pair|lamp) costs (\d+) scrap to make, and (her stall|his workshop|her cart) costs (\d+) scrap (a week|a month)\.", L[1])
    need(m1 is not None and m2 is not None and m1.group(5) == m2.group(5), f"can't read the price and demand {L!r}")
    A, Bc, c, F0 = int(m1.group(3)), int(m1.group(4)), int(m2.group(2)), int(m2.group(4))
    p = sp.Symbol("p")
    P = (p - c) * (A - Bc * p) - F0
    ps = sp.solve(sp.diff(P, p), p)
    need(len(ps) == 1 and sp.diff(P, p, 2) < 0, "the profit has no maximum")
    p0 = ps[0]
    best = P.subs(p, p0)
    need(c < p0 < sp.Rational(A, Bc) and best > 0, "the best price is outside the limits")
    rev = p * (A - Bc * p)
    r0 = sp.solve(sp.diff(rev, p), p)[0]
    w = {}
    if q["asked"] == "Find the price that gives the greatest profit.":
        want = f"p = {dec_text(p0)} scrap"
        w[R2OP_G + "1"] = {f"p = {dec_text(r0)} scrap"}
        # Leaving out the cost per item gives the revenue's price too, so it has no option of its own.
        need(not any(o["ref"] == R2OP_OWN + "11" for o in q["choices"]), "the cost-left-out slip on the price")
    else:
        need(q["asked"] == f"Find the greatest possible profit {m1.group(5)}.", f"asked {q['asked']!r}")
        want = f"P = {dec_text(best)} scrap"
        w[R2OP_G + "1"] = {f"P = {dec_text(rev.subs(p, r0))} scrap"}
        w[R2OP_OWN + "11"] = {f"P = {dec_text(rev.subs(p, r0) - F0)} scrap"}
    poly = sp.Poly(sp.expand(P), p).all_coeffs()
    r2op_steps_have(q, f"(p − {c})({A} − {Bc}p) − {F0} = " + r2op_terms_p(poly), "the profit expanded")
    r2op_steps_have(q, f"p = {dec_text(p0)}", "the best price")
    gc_check_common(q, want, w, None)


def r2op_terms_p(cs):
    """−4p² + 792p − 32030, as the game writes a quadratic in p."""
    out = ""
    for c, body in zip(cs, ("p²", "p", "")):
        c = sp.Rational(c)
        if c == 0:
            continue
        mag = abs(c)
        t = (dec_text(mag) if body == "" or mag != 1 else "") + body
        out += (("−" if c < 0 else "") if out == "" else (" − " if c < 0 else " + ")) + t
    return out


def r2op_forms(q, want, tagged):
    """Each option's expression is the one asked, or for a tag, what its slip gives."""
    for o in q["choices"]:
        e = om_expr(o["text"].split(" = ", 1)[1])
        need(om_same(e, want) == o["correct"], f"option {o['text']!r} against {want}")
        if o["ref"]:
            need(o["ref"] in tagged, f"the checker can't confirm {o['ref']} on {q['view']['unknown']}")
            need(any(om_same(e, t) for t in tagged[o["ref"]]), f"option {o['text']!r} is not what {o['ref']} gives")
        if o["correct"]:
            body = ""
            for item in q["answer"]["template"]:
                body += item if isinstance(item, str) else "(" + str(q["answer"]["values"][item["slot"]]) + ")"
            need(om_same(om_expr(body.split(" = ", 1)[1]), want), f"the answer's slots make {body!r}, not {want}")


def r2op_slip_x(F, dom):
    """The smallest stationary point of a slip's function inside its domain."""
    inside, _ = om_stationary(F, dom)
    need(len(inside) >= 1, "a slip's function has no stationary point")
    return min(inside, key=lambda v: sp.N(v, 30))


def r2op_shape(q, u):
    p = om_read(q)
    fam, F, dom, Y = p["fam"], p["F"], p["dom"], p["Y"]
    x = OM_X
    w = {}
    vals = {}
    allowed = {"constraint-second-length": ("pen", "paddock", "can", "bin"), "objective-one-variable": ("pen", "paddock", "can", "bin", "box"),
               "container-optimal-dimension": ("paddock", "can", "bin", "box"), "container-optimum-value": ("paddock", "can", "bin", "box"),
               "container-other-dimension": ("paddock", "can", "bin"), "route-least-time": ("route",), "context-domain": ("box", "pen")}[u]
    need(fam in allowed, f"{fam} is not a shape for {u}")
    letter = "r" if fam == "can" else "x"
    O = {"pen": "A", "paddock": "L", "bin": "V", "box": "V"}.get(fam, "")
    if fam == "can":
        O = "C" if p["cost"] else "S"
    if fam == "route":
        O = "C" if p["cost"] else "T"
    unit = {"pen": "m", "paddock": "m", "bin": "cm", "box": "cm", "route": "km"}.get(fam, p.get("unit", ""))
    tail = {"pen": " m²", "paddock": " m", "bin": " cm³", "box": " cm³"}.get(fam, "")
    if fam == "can":
        tail = " scrap" if p["cost"] else " cm²"
    if fam == "route":
        tail = " scrap" if p["cost"] else " hours"
    if u == "constraint-second-length":
        # A lid counted on the box, the circumference for the base's area, a fence along the
        # wall, the area as a sum: each worked out from the shape's own numbers.
        if fam == "bin":
            tagged = {R2OP_OWN + "16": [(p["T"] - 2 * x**2) / (4 * x)]}
        elif fam == "can":
            tagged = {R2OP_OWN + "17": [p["V"] / (2 * sp.pi * x)]}
        elif fam == "pen":
            tagged = {R2OP_OWN + "18": [(p["T"] - p["n"] * x) / 2]}
        else:
            tagged = {R2OP_OWN + "19": [p["T"] - p["n"] * x]}
        r2op_forms(q, Y, tagged)
        calc_options(q)
        return
    if u == "objective-one-variable":
        if fam == "box":
            r2op_forms(q, F, {R2OP_B + "0": [x * (p["w"] - x) * (p["h"] - x)]})
            calc_options(q)
            return
        line = next(l for l in q["lines"] if l.startswith("Show that "))
        tgt = re.match(r"Show that . = (.+), where p and q are whole numbers\.", line).group(1)
        P_, Q_ = sp.symbols("P_ Q_")
        tt = tgt.replace("p", " P_ ").replace("q", " Q_ ")
        tt = re.sub(r"[⁰¹²³⁴⁵⁶⁷⁸⁹]+", lambda m: "**" + m.group(0).translate(SUP_DIGITS), tt.replace("−", "-").replace("π", " pi ").replace("r", "x"))
        te = parse_expr(tt, transformations=TRANSFORMS, local_dict={"x": OM_X, "P_": P_, "Q_": Q_, "pi": sp.pi})
        got = sp.solve([te.subs(x, 1) - F.subs(x, 1), te.subs(x, 2) - F.subs(x, 2)], [P_, Q_], dict=True)
        need(len(got) == 1, f"p and q are not fixed by {line!r}")
        pv, qv = got[0][P_], got[0][Q_]
        need(om_same(te.subs({P_: pv, Q_: qv}), F) and pv.is_integer and qv.is_integer and pv > 0 and qv > 0, f"no whole p and q make {line!r} this function")
        nm = lambda a, b: f"p = {om_num(a)}, q = {om_num(b)}"
        if fam == "can":
            w[R2OP_B + "1"] = {nm(pv, qv / 2)}            # πrh for the curved side
            if p["ends"] == 1:
                w[R2OP_B + "2"] = {nm(2 * p["re"], qv)}   # a lid on the open can
        gc_check_common(q, nm(pv, qv), w, None)
        return
    if u == "context-domain":
        roots = sorted(r for r in sp.solve(F, x) if r.is_real and r > 0)
        need(len(roots) >= 1, "the function has no positive zero")
        top = roots[0]
        need(all(F.subs(x, top * k / 10) > 0 for k in range(1, 10)), "the function is not positive inside the domain")
        line = q["lines"][-1]
        mt = re.fullmatch(r"(V|A) = (.+), where \1 (cm³|m²) is the (volume of the tray|area of the [a-z ]+)\.", line)
        need(mt is not None and om_same(om_expr(mt.group(2)), F), f"the function shown, {line!r}, is not this shape's")
        need(top.is_rational and (top.q == 1), "the domain's end is not a whole number")
        need(q["asked"] == f"Find the domain of {mt.group(1)} in this context.", f"asked {q['asked']!r}")
        big = p["w"] if fam == "box" else p["T"]
        want = f"0 < x < {om_num(top)}"
        w[R2OP_I + "1"] = {f"0 < x < {om_num(big)}", "x > 0"}
        w[R2OP_OWN + "14"] = {f"0 ≤ x ≤ {om_num(top)}"}
        if fam == "box":
            need(top == sp.Rational(p["w"], 2), "a tray's domain ends at half its shorter side")
        else:
            need(top == sp.Rational(p["T"], p["n"]), "a yard's domain ends where y is 0")
        gc_check_common(q, want, w, None)
        return
    if u == "route-least-time":
        x0 = om_route_best(F, dom)
        need(OM_FIT[0] * p["b"] <= x0 <= OM_FIT[1] * p["b"], f"x = {x0} is too near an end of the road")
        best = F.subs(x, x0)
        line = sp.sqrt(p["a"] ** 2 + p["b"] ** 2)
        one = p["v"] * line if p["cost"] else line / p["v"]
        need(om_clear(x0) and om_clear(best) and r2op_clear(one), "a value is on a rounding edge")
        what = "total cost" if p["cost"] else "total time"
        if q["asked"] == f"Find the value of x that makes the {what} as small as possible.":
            want, trap = r2op_sf("x = ", x0, " km")
            if not p["cost"]:
                w[R2OP_OWN + "15"] = {f"x = {gc_s(sp.Integer(p['b']))} km"}
        else:
            need(q["asked"] == f"Find the least possible {what}.", f"asked {q['asked']!r}")
            want, trap = r2op_sf(f"{O} = ", best, tail)
            w[R2OP_G + "0"] = {r2op_sf(f"{O} = ", x0, tail)[0]}
            if not p["cost"]:
                w[R2OP_OWN + "15"] = {r2op_sf(f"{O} = ", one, tail)[0]}
            need(gc_s(sp.N(one, 40)) != gc_s(sp.N(best, 40)), "the one-speed slip reads as the answer")
        r2op_steps_have(q, f"x = {r2op_w(x0)}", "the best point to 6 s.f.")
        r2op_steps_have(q, f"{O} = {r2op_w(best)}", "the least value to 6 s.f.")
        gc_check_common(q, want, w, trap)
        return
    # The best length, the optimum and the other length.
    inside, others = om_stationary(F, dom)
    need(len(inside) == 1, f"{len(inside)} stationary points in the domain")
    x0 = inside[0]
    least = OM_MIN[fam]
    need((sp.N(sp.diff(F, x, 2).subs(x, x0), 30) > 0) == least, "the stationary point is the wrong kind")
    best = sp.simplify(F.subs(x, x0))
    need(om_clear(x0) and om_clear(best), "the optimum is on a rounding edge")
    sign_ok = r2op_shape_sign(q, F, x0, letter, O)
    need(sign_ok, "no sign test in the calculus working")
    r2op_steps_have(q, f"{letter} = {r2op_w(x0)}", "the optimum to 6 s.f.")
    goal = {"paddock": "the least length of fence", "can": "the least cost" if p.get("cost") else "the least surface area"}.get(fam, "the greatest volume")
    if u == "container-optimal-dimension":
        need(q["asked"] == f"Find the value of {letter} that gives {goal}.", f"asked {q['asked']!r}")
        want, trap = r2op_sf(f"{letter} = ", x0, f" {unit}")
        if fam == "box":
            one = r2op_slip_x(x * (p["w"] - x) * (p["h"] - x), (0, p["w"]))     # a cut at one end only
            vals[R2OP_B + "0"] = one
            vals[R2OP_C + "0"] = sp.Rational(p["w"], 2)                            # the root where V = 0
            need(len(others) == 1, "the tray's other root")
            vals[R2OP_I + "1"] = others[0]                                         # the cut too big for the sheet
        elif fam == "bin":
            vals[R2OP_OWN + "16"] = r2op_slip_x(x * (p["T"] - 2 * x**2) / 4, (0, sp.sqrt(p["T"])))   # a lid counted
        elif fam == "can":
            e = p["re"] * p["ends"]
            # πrh; a lid on an open can gives the same r, so the engine offers only this slip
            vals[R2OP_B + "1"] = r2op_slip_x(e * sp.pi * x**2 + p["V"] / x, (0, sp.oo))
        for ref, v in vals.items():
            w[ref] = {r2op_sf(f"{letter} = ", v, f" {unit}")[0]}
    elif u == "container-optimum-value":
        need(q["asked"] == f"Find the {'minimum' if least else 'maximum'} value of {O}.", f"asked {q['asked']!r}")
        want, trap = r2op_sf(f"{O} = ", best, tail)
        ref = R2OP_C + "2" if fam == "can" else R2OP_G + "0"
        w[ref] = {r2op_sf(f"{O} = ", x0, tail)[0]}
        r2op_steps_have(q, r2op_w(best), "the optimum's value to 6 s.f.")
    else:
        letter2 = "y" if fam == "paddock" else "h"
        need(q["asked"] == f"Find the value of {letter2} that gives {goal}.", f"asked {q['asked']!r}")
        y0 = sp.simplify(Y.subs(x, x0))
        need(om_clear(y0), "the second length is on a rounding edge")
        want, trap = r2op_sf(f"{letter2} = ", y0, f" {unit}")
        if fam == "can":
            yr = Y.subs(x, sp.Rational(sig3(sp.N(x0, 40))))                     # r rounded before h
            vals[R2OP_C + "1"] = yr
            w[R2OP_C + "1"] = {r2op_sf(f"{letter2} = ", yr, f" {unit}")[0]}
        r2op_steps_have(q, f"= {r2op_w(y0)}", "the second length to 6 s.f.")
    for o in q["choices"]:
        if o["ref"] in vals:
            need(r2op_clear(vals[o["ref"]]), f"the slip {o['text']!r} is on a rounding edge")
    gc_check_common(q, want, w, trap)


def r2op_shape_sign(q, F, x0, letter, O):
    """The calculus working's sign test: the derivative's values either side, to 3 s.f."""
    d = sp.diff(F, OM_X)
    found = False
    for sol in q["solutions"]:
        for st in sol["steps"]:
            mt = re.search(rf"d{O}/d{letter} = (−?[\d.]+) at {letter} = (\d+) and (−?[\d.]+) at {letter} = (\d+)", st)
            if mt:
                lo, hi = int(mt.group(2)), int(mt.group(4))
                need(lo < x0 < hi and hi == lo + 1, "the sign test is not either side of the optimum")
                for v, at in ((mt.group(1), lo), (mt.group(3), hi)):
                    need(v == gc_s(sp.N(d.subs(OM_X, at), 40)), f"d{O}/d{letter} at {at} is not {v}")
                found = True
    return found or q["view"]["angle"] == "gdc-graph-route"


def r2op_check(q):
    u = q["view"]["unknown"]
    need(q["paper"] == 2, "every AI question is Paper 2")
    calc_steps(q, (2, 5))
    calc_options(q)
    if u in R2OP_SHAPES:
        r2op_shape(q, u)
    elif u == "profit-from-revenue-cost":
        r2op_demand(q)
    elif u in ("optimal-input-given-model", "optimum-value-given-model", "suggested-not-optimal", "whole-number-optimum"):
        r2op_given(q, u)
    else:
        raise Fail(f"no check for {u}")
    return None, None


SITUATION_CHECKS["ai-optimisation"] = r2op_check

# (between the R2 markers)

# R2-TRAPEZOIDAL: t5-ai-trapezoidal (trapezoidal), prefix R2TR_ / r2tr_

R2TR_TF = "AI-SL5.8.trapezoid-from-function#"
R2TR_TD = "AI-SL5.8.trapezoid-from-data#"
R2TR_CE = "AI-SL5.8.compare-with-exact#"
R2TR_OU = "AI-SL5.8.over-or-under-estimate#"
R2TR_MV = "AI-SL5.8.find-missing-value#"
R2TR_EDGE = sp.Rational(39, 1000)  # the engine's is 0.04
R2TR_N = r"(−?\d+(?:\.\d+)?)"
R2TR_WHO = ["Juno", "Ash", "Vex", "Mara", "Rook", "Tess"]
R2TR_IMPROVE = "Use more strips of smaller width: the chords then follow the curve more closely."
R2TR_FEWER = "Use fewer, wider strips: each strip adds an error of its own, so fewer strips give a better estimate."
R2TR_SAME = "Nothing: the strip width makes no difference, since the formula is the same."
R2TR_ROUND = "Round each height to 1 decimal place first: the bracket is then exact."


def r2tr_q(t):
    return sp.Rational(t.replace("−", "-"))


def r2tr_fn(text):
    """f(x) as the game writes it: '0.5x² − 2x + 3', '2√(x + 3)', '3e^(−0.4x)', '12/(x + 2)'."""
    t = text.replace("−", "-").replace("√(", "sqrt(").replace("√x", "sqrt(x)").replace("e^(", "exp(")
    t = t.replace("x³", "x**3").replace("x²", "x**2")
    need(re.fullmatch(r"[0-9x+\-*/(). sqrtexp]+", t) is not None, f"can't read the function {text!r}")
    return sp.nsimplify(parse_expr(t, transformations=TRANSFORMS, local_dict={"x": X, "sqrt": sp.sqrt, "exp": sp.exp}), rational=True)


def r2tr_w(x, n=6):
    """x to n significant figures without the zeros a GDC doesn't show (the engine's Fmt.work)."""
    t = sig3(x, n)
    if "." in t:
        t = t.rstrip("0").rstrip(".")
    return t.replace("-", "−")


def r2tr_clear(x):
    v = abs(num(x))
    if v == 0:
        return False
    e = sp.floor(sp.log(v, 10))
    scaled = v / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= R2TR_EDGE


def r2tr_distinct(xs):
    need(all(r2tr_clear(x) for x in xs), "a value or slip is on a 3 s.f. edge")
    need(len({gc_s(x) for x in xs}) == len(xs), "two of the values or slips read the same to 3 s.f.")


def r2tr_ends(v):
    """An exact value's option: as it is when it ends, else to 3 s.f."""
    return sig3(v) if "/" in dec_text(v) else dec_text(v)


def r2tr_rule(ys, h, inner=2, ends=1, half=sp.Rational(1, 2)):
    return half * h * sum(y * (ends if i in (0, len(ys) - 1) else inner) for i, y in enumerate(ys))


def r2tr_find(pattern, texts, what):
    for t in texts:
        m = re.search(pattern, t)
        if m:
            return m
    raise Fail(f"can't find {what}")


def r2tr_bend(fn, a, b):
    """'up', 'down' or 'line' for f on [a, b]; a bend that changes sign fails."""
    d2 = sp.simplify(sp.diff(fn, X, 2))
    if d2 == 0:
        return "line"
    f2 = sp.lambdify(X, d2, "mpmath")
    vals = [f2(mpmath.mpf(a + (b - a) * sp.Rational(i, 60))) for i in range(61)]
    need(all(v > 0 for v in vals) or all(v < 0 for v in vals), "f″ changes sign on the interval: the estimate is not clearly over or under")
    return "up" if vals[0] > 0 else "down"


def r2tr_slope(fn, a, b):
    f1 = sp.lambdify(X, sp.diff(fn, X), "mpmath")
    vals = [f1(mpmath.mpf(a + (b - a) * sp.Rational(i, 60))) for i in range(61)]
    need(all(v > 0 for v in vals) or all(v < 0 for v in vals), "f turns on the interval")
    return "rises" if vals[0] > 0 else "falls"


def r2tr_function(q):
    """(f, a, b, n, h, xs, ys, T, I) from what a function question shows."""
    texts = q["lines"] + [q["asked"]]
    m = r2tr_find(r"(?:^f\(x\) = |^The graph of y = )(.+?)(?:, for | is shown|$)", texts, "f(x)")
    fn = r2tr_fn(m.group(1))
    m = r2tr_find(r"from x = " + R2TR_N + r" to x = " + R2TR_N + r"|for " + R2TR_N + r" ≤ x ≤ " + R2TR_N, texts, "the limits")
    lims = [g for g in m.groups() if g is not None]
    m = re.match(r"(.*) (.*)", " ".join(lims))
    a, b = r2tr_q(m.group(1)), r2tr_q(m.group(2))
    mn = None
    for t in texts:
        mn = re.search(r"using (\d+) strips|the (\d+) trapezia|cut into (\d+) strips", t)
        if mn:
            break
    if mn:
        n = int(next(g for g in mn.groups() if g))
    else:
        need(q["table"] is not None, "no number of strips")
        n = len(q["table"]["rows"][0][1]) - 1
    need(3 <= n <= 6 and b > a, "n is not 3 to 6")
    h = (b - a) / n
    need(h in (sp.Rational(1, 2), 1, 2, sp.Rational(1, 4), sp.Rational(1, 5), sp.Rational(2, 5), sp.Rational(3, 2)), f"h = {h} is not a tidy decimal")
    xs = [a + i * h for i in range(n + 1)]
    ys = [fn.subs(X, x) for x in xs]
    need(all(sp.N(y) > sp.Rational(49, 100) for y in ys), "a height is not positive")
    T = r2tr_rule(ys, h)
    I = sp.integrate(fn, (X, a, b))
    # Exact where the values are rational (a polynomial), else to 40 digits.
    T, I = (v if v.is_Rational else sp.N(v, 40) for v in (T, I))
    ys = [y if y.is_Rational else sp.N(y, 40) for y in ys]
    return fn, a, b, n, h, xs, ys, T, I


def r2tr_curve(curve, fn):
    f = gc_f(fn)
    return gc_curve_is(curve, f, 1e-5)


def r2tr_steps(q):
    return [st for sol in q["solutions"] for st in sol["steps"]]


def r2tr_in_every(q, text, what):
    for sol in q["solutions"]:
        need(any(text in st for st in sol["steps"]), f"{sol['name']}: the working doesn't show {what} {text!r}")


def r2tr_shape(q, rows=True):
    """(kind, h, ys, j) from a measurement question: the story line, then the table, the words
    or the figure. j is the index of k, or None."""
    L = q["lines"]
    m = re.search(r"every " + R2TR_N + r" (m|seconds|minutes)", L[0])
    need(m is not None, f"can't read the spacing in {L[0]!r}")
    h = r2tr_q(m.group(1))
    j, ys, xs = None, None, None
    if q["table"] is not None:
        r = q["table"]["rows"]
        need(len(r) == 2, "the table has two rows")
        xs = [r2tr_q(t) for t in r[0][1]]
        ys = []
        for i, t in enumerate(r[1][1]):
            if t == "k":
                j = i
                ys.append(None)
            else:
                ys.append(r2tr_q(t))
    elif q["graph"] is not None:
        g = q["graph"]
        pts = sorted(g["points"], key=lambda p: p["x"])
        xs = [sp.nsimplify(p["x"]) for p in pts]
        if all(p["label"] == "" for p in pts):
            ys = [sp.nsimplify(p["y"]) for p in pts]
            need(all(y == int(y) and abs(p["y"] - float(y)) < 1e-9 for y, p in zip(ys, pts)), "a plotted speed is not on a whole grid line")
        else:
            ys = []
            for p in pts:
                mm = re.fullmatch(R2TR_N + r" m", p["label"])
                need(mm is not None and p.get("name"), f"can't read the label {p['label']!r}")
                ys.append(r2tr_q(mm.group(1)))
            # Each labelled width is drawn to its length, at its distance.
            segs = [c for c in g["curves"] if len(c) == 2 and abs(c[0][0] - c[1][0]) < 1e-9]
            need(len(segs) == len(ys), "the figure doesn't draw every width")
            for x, y, sg in zip(xs, ys, sorted(segs, key=lambda c: c[0][0])):
                need(abs(sg[0][0] - float(x)) < 1e-6 and abs(abs(sg[1][1] - sg[0][1]) - float(y)) < 1e-4, f"the width at {x} is not drawn {y} long")
            ticks = [(sp.nsimplify(t[0]), t[1]) for t in g.get("x_ticks", [])]
            need([t[1] for t in ticks] == [dec_text(x) for x in xs], "the distances under the figure are not the widths' distances")
    else:
        m2 = re.search(r"are (.+) and " + R2TR_N + r", in ", L[1])
        need(m2 is not None, f"can't read the values in {L[1]!r}")
        ys = [r2tr_q(t) for t in m2.group(1).split(", ")] + [r2tr_q(m2.group(2))]
        m3 = re.search(r"at (?:t = |distances )(.+?) (?:minutes|seconds|m from)", L[1])
        need(m3 is not None, "can't read the times")
        xs = [r2tr_q(t) for t in m3.group(1).split(", ")]
    need(len(xs) == len(ys) and 5 <= len(ys) <= 7, "4 to 6 strips")
    need(xs == [i * h for i in range(len(xs))], "the measurements are not every h from 0")
    return h, ys, j


def r2tr_check(q):
    u, rep, L, asked = q["view"]["unknown"], q["view"]["rep"], q["lines"], q["asked"]
    need(q["paper"] == 2, "every AI question is Paper 2")
    for tx in [asked] + L + r2tr_steps(q) + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs, want, trap = {}, None, None
    if u == "strip-width":
        fn, a, b, n, h, xs, ys, T, I = r2tr_function(q)
        want = "h = " + dec_text(h)
        wrongs[R2TR_TF + "0"] = {"h = " + r2tr_ends((b - a) / (n + 1))}
        if rep == "table":
            rows = q["table"]["rows"]
            need(rows[0][1] == [dec_text(x) for x in xs] and rows[1][1] == [dec_text(y) for y in ys], "the table is not x against f(x)")
            need(asked == "Write down the strip width h.", f"asked {asked!r}")
        else:
            need(asked == "Find the strip width h.", f"asked {asked!r}")
        r2tr_in_every(q, f"h = (b − a)/n = {dec_text(b - a)}/{n} = {dec_text(h)}", "h")
    elif u == "function-estimate":
        fn, a, b, n, h, xs, ys, T, I = r2tr_function(q)
        vals = [T, T * n / (n + 1), r2tr_rule(ys, h, 1), r2tr_rule(ys, h, half=1)]
        r2tr_distinct(vals)
        want, trap = r1ap_sf("estimate = ", vals[0])
        need(gc_rounds(T), "the estimate needs no rounding")
        wrongs[R2TR_TF + "0"] = {r1ap_sf("estimate = ", vals[1])[0]}
        wrongs[R2TR_TF + "1"] = {r1ap_sf("estimate = ", vals[2])[0]}
        wrongs[R2TR_TF + "2"] = {r1ap_sf("estimate = ", vals[3])[0]}
        if rep == "graph":
            g = q["graph"]
            need(r2tr_curve(g["curves"][0], fn), "the graph's curve is not f")
            tops = g["curves"][1]
            need(len(tops) == n + 1 and all(abs(p[0] - float(x)) < 1e-6 and abs(p[1] - float(y)) < 1e-6 for p, x, y in zip(tops, xs, ys)), "the trapezia's tops are not the chords")
            sides = g["curves"][2:]
            need(len(sides) == n + 1 and all(abs(s[0][0] - float(x)) < 1e-6 and abs(s[0][1]) < 1e-9 and abs(s[1][1] - float(y)) < 1e-6 for s, x, y in zip(sides, xs, ys)), "the trapezia's sides are wrong")
            need([[round(p[0], 6), round(p[2], 6)] for p in g["shade"][0]] == [[round(float(x), 6), round(float(y), 6)] for x, y in zip(xs, ys)], "the shaded trapezia are wrong")
        if rep == "table":
            rows = q["table"]["rows"]
            need(rows[0][1] == [dec_text(x) for x in xs], "the table's x-values")
            blanks = [i for i, t in enumerate(rows[1][1]) if t in ("p", "q")]
            need(1 <= len(blanks) <= 2 and [rows[1][1][i] for i in blanks] == ["p", "q"][:len(blanks)], "the missing heights are not p (and q)")
            need(all(rows[1][1][i] == dec_text(ys[i]) for i in range(n + 1) if i not in blanks), "the table's heights are not f(x)")
            for i, nm in zip(blanks, ["p", "q"]):
                r2tr_in_every(q, f"{nm} = f({dec_text(xs[i])}) = {dec_text(ys[i])}", "the missing height")
        for y in ys:
            r2tr_in_every(q, r2tr_w(y), "the height")
        r2tr_in_every(q, "= " + r2tr_w(T), "the estimate")
    elif u == "percentage-error-of-estimate":
        fn, a, b, n, h, xs, ys, T, I = r2tr_function(q)
        need(asked == "Find the percentage error in this estimate, against the exact area the GDC's integral gives.", f"asked {asked!r}")
        e = abs(T - I) / I * 100
        need(sp.Rational(1, 10) <= e <= 25, "the error is not 0.1% to 25%")
        T0 = T * n / (n + 1)
        vals = [e, abs(T - I) / T * 100, abs(T0 - I) / I * 100] + ([(T - I) / I * 100] if T < I else [])
        r2tr_distinct(vals)
        want, trap = r1ap_sf("percentage error = ", e, "%")
        wrongs[R2TR_CE + "0"] = {r1ap_sf("percentage error = ", vals[1], "%")[0]}
        wrongs[R2TR_TF + "0"] = {r1ap_sf("percentage error = ", vals[2], "%")[0]}
        if T < I:
            wrongs[R2TR_CE + "2"] = {r1ap_sf("percentage error = ", vals[3], "%")[0]}
        t7, i7 = r2tr_w(T, 7), r2tr_w(I, 7)
        r2tr_in_every(q, f"ε = |{t7} − {i7}| ÷ {i7} × 100% = {r2tr_w(e)}%", "the error")
        # The error from the figures shown is the answer too.
        e7 = abs(r2tr_q(t7) - r2tr_q(i7)) / r2tr_q(i7) * 100
        need(gc_s(e7) == gc_s(e), "the working's figures give another error")
    elif u == "improve-estimate":
        fn, a, b, n, h, xs, ys, T, I = r2tr_function(q)
        need(any(f"using {n} strips, and gets {r2tr_w(T)}. The GDC's integral gives {r2tr_w(I)}." in t for t in L), "the estimate or the integral the question gives")
        ys2 = [fn.subs(X, a + i * h / 2) for i in range(2 * n + 1)]
        T2 = sp.N(r2tr_rule(ys2, h / 2), 40)
        need(abs(T2 - I) < abs(T - I), "more strips are not closer")
        r2tr_in_every(q, f"it gives {r2tr_w(T2)}: an error of {r2tr_w(abs(T2 - I))}", "the estimate with twice the strips")
        need(asked == "How could the estimate be made more accurate, and why?", f"asked {asked!r}")
        want = R2TR_IMPROVE
        wrongs[R2TR_CE + "1"] = {R2TR_FEWER}
        wrongs["t5-ai-trapezoidal#14"] = {R2TR_SAME}
        need(all(o["correct"] or o["text"] in (R2TR_FEWER, R2TR_SAME, R2TR_ROUND) for o in q["choices"]), "an option that isn't one of the claims")
        if rep == "graph":
            need(r2tr_curve(q["graph"]["curves"][0], fn), "the graph's curve is not f")
    elif u == "over-or-under":
        fn, a, b, n, h, xs, ys, T, I = r2tr_function(q)
        bd, sl = r2tr_bend(fn, a, b), r2tr_slope(fn, a, b)
        line = bd == "line"
        thing = "line" if line else "curve"
        if bd == "up":
            need(T > I, "the rule doesn't overestimate a concave-up curve")
            want = "Overestimate: the curve bends upwards (concave up), so the tops of the trapezia lie above it."
        elif bd == "down":
            need(T < I, "the rule doesn't underestimate a concave-down curve")
            want = "Underestimate: the curve bends downwards (concave down), so the tops of the trapezia lie below it."
        else:
            need(T == I, "the rule isn't exact for a line")
            want = "Neither: the graph is a straight line, so the tops of the trapezia lie along it and the estimate is exact."
        if not line:
            need(abs(T - I) / I >= sp.Rational(2, 1000), "the estimate is too close to tell")
        under_from_rise = bd == "up" or (line and sl == "falls")
        wrongs[R2TR_OU + "0"] = {(f"Underestimate: the {thing} {sl}, so the tops of the trapezia lie below it." if under_from_rise
                                  else f"Overestimate: the {thing} {sl}, so the tops of the trapezia lie above it.")}
        wrongs[R2TR_OU + "1"] = {"Overestimate: the trapezoidal rule always gives an overestimate of an area."}
        if line:
            wrongs[R2TR_OU + "2"] = {"Underestimate: the rule is only an approximation, so even under a line it leaves gaps."}
        r2tr_in_every(q, "So: " + want, "the claim")
        cmp = "The two are equal" if line else (f"{r2tr_w(T, 7)} {'>' if T > I else '<'} {r2tr_w(I, 7)}")
        need(any(cmp in st for st in r2tr_steps(q)), "the comparison with the GDC")
        if rep == "graph":
            g = q["graph"]
            need(r2tr_curve(g["curves"][0], fn), "the graph's curve is not f")
            need([round(v["at"], 6) for v in g["vlines"]] == [round(float(x), 6) for x in xs], "the strip edges are not drawn at the x-values")
    elif u == "pick-underestimate-graph":
        m = re.fullmatch(r"The area under each curve from x = " + R2TR_N + r" to x = " + R2TR_N + r" is estimated with the trapezoidal rule\. For which curve is the estimate (an underestimate|an overestimate)\?", asked)
        need(m is not None, f"asked {asked!r}")
        a, b, under = float(r2tr_q(m.group(1))), float(r2tr_q(m.group(2))), m.group(3) == "an underestimate"
        graphs, ch = q["graphs"], q["choices"]
        need(len(graphs) == 4 and [o["text"] for o in ch] == ["Graph A", "Graph B", "Graph C", "Graph D"], "four cards, A to D")
        need(len({(g["x0"], g["x1"], g["y0"], g["y1"]) for g in graphs}) == 1, "the cards don't share one window")

        def kind(curve):
            need(abs(curve[0][0] - a) < 1e-6 and abs(curve[-1][0] - b) < 1e-6, "a card's curve is not on the interval")
            ys_ = [p[1] for p in curve]
            d2 = [ys_[i - 1] - 2 * ys_[i] + ys_[i + 1] for i in range(1, len(ys_) - 1)]
            d1 = [ys_[i + 1] - ys_[i] for i in range(len(ys_) - 1)]
            sl_ = "rises" if all(d > 0 for d in d1) else ("falls" if all(d < 0 for d in d1) else "")
            if all(abs(d) < 1e-7 for d in d2):
                return "line", sl_
            need(all(d > 0 for d in d2) or all(d < 0 for d in d2), "a card's curve bends both ways")
            mid = ys_[len(ys_) // 2]
            need(abs(mid - (ys_[0] + ys_[-1]) / 2) >= 0.39, "a card's bend is too slight to see")
            return ("up" if d2[0] > 0 else "down"), sl_

        right_bend = "down" if under else "up"
        other = "up" if under else "down"
        letter = None
        for o, g in zip(ch, graphs):
            need(len(g["curves"]) == 1 and g.get("card"), "a card has one curve")
            bd, sl = kind(g["curves"][0])
            if o["correct"]:
                need(bd == right_bend and sl == ("rises" if under else "falls"), "the right card doesn't bend the right way, or has the slope the slope slip reads as the target")
                letter = o["text"]
                continue
            mk = o.get("mistake", "")
            need(o.get("why", "") != "", "a wrong card doesn't say why")
            if mk == "rises":
                need(o["ref"] == R2TR_OU + "0" and bd == other and sl == ("falls" if under else "rises"), "the slope slip's card does not have the slope it reads as the target, bending the other way")
                wrongs.setdefault(R2TR_OU + "0", set()).add(o["text"])
            elif mk == "line":
                need(o["ref"] == R2TR_OU + "2" and bd == "line", "the line card is not a line")
                wrongs.setdefault(R2TR_OU + "2", set()).add(o["text"])
            elif mk == "same-way":
                need(o["ref"] == "" and bd == other, "the same-way card doesn't bend the other way")
            else:
                raise Fail(f"a card names no mistake ({mk!r})")
        need(letter is not None, "no right card")
        want = letter
    elif u == "data-estimate":
        h, ys, _ = r2tr_shape(q)
        m = re.search(r"(salvage field|toxic lake|flooded canal)", L[0])
        need(m is not None and any(w in L[0] for w in R2TR_WHO), "the story")
        kind = {"salvage field": "field", "toxic lake": "lake", "flooded canal": "canal"}[m.group(1)]
        region = {"field": "the field", "lake": "the lake", "canal": "the canal's cross-section"}[kind]
        need(asked == f"Use the trapezoidal rule to estimate the area of {region}.", f"asked {asked!r}")
        n = len(ys) - 1
        xs = [i * h for i in range(n + 1)]
        T = r2tr_rule(ys, h)
        vals = [T, r2tr_rule(xs, h), r2tr_rule(ys, h, 2, 2), r2tr_rule(ys, h, 1, 1), 2 * T]
        r2tr_distinct(vals)
        want, trap = r1ap_sf("area = ", T, " m²")
        for ref, v in zip([R2TR_TD + "0", R2TR_TD + "2", R2TR_TF + "1", R2TR_TF + "2"], vals[1:]):
            wrongs[ref] = {r1ap_sf("area = ", v, " m²")[0]}
        r2tr_in_every(q, "= " + dec_text(T), "the area")
    elif u == "accumulated-total":
        h, ys, _ = r2tr_shape(q)
        n = len(ys) - 1
        T = r2tr_rule(ys, h)
        if L[0].startswith("A scout rover"):
            mix = "every " + dec_text(h) + " minutes" in L[0]
            label, unit = "distance = ", " m"
            need(asked == f"Use the trapezoidal rule to estimate the distance the rover travels in these {dec_text(n * h)} {'minutes' if mix else 'seconds'}, in metres.", f"asked {asked!r}")
            factor = 60 if mix else 1
        elif L[0].startswith("Water is pumped"):
            mix = "litres per second" in L[0]
            label, unit = "volume = ", " litres"
            need(asked == f"Use the trapezoidal rule to estimate the volume of water pumped in these {dec_text(n * h)} minutes, in litres.", f"asked {asked!r}")
            factor = 60 if mix else 1
        else:
            m = re.fullmatch(r"A drainage channel is " + R2TR_N + r" m wide\. Its depth is measured every " + R2TR_N + r" m across it, and the water flows through it at " + R2TR_N + r" m/s\.", L[0])
            need(m is not None and r2tr_q(m.group(1)) == n * h, f"the channel {L[0]!r}")
            mix, label, unit, factor = False, "flow = ", " m³/s", r2tr_q(m.group(3))
        if rep == "graph":
            need(q["graph"]["x_name"] == "t" and q["graph"]["y_name"] == "v", "the graph's axes")
        total = T * factor
        vals = [total, 2 * total, r2tr_rule(ys, h, 2, 2) * factor, r2tr_rule(ys, h, 1, 1) * factor] + ([T] if mix else [])
        r2tr_distinct(vals)
        exact = not gc_rounds(total)
        need(not exact or rep == "graph", "a total from a table or words needs rounding")
        show = (lambda v: label + dec_text(v) + unit) if exact else (lambda v: r1ap_sf(label, v, unit)[0])
        want = show(total)
        trap = None if exact else r1ap_sf(label, total, unit)[1]
        for ref, v in zip([R2TR_TF + "2", R2TR_TD + "2", R2TR_TF + "1"], vals[1:4]):
            wrongs[ref] = {show(v)}
        if mix:
            wrongs[R2TR_TD + "1"] = {show(T)}
            r2tr_in_every(q, f"h = {dec_text(h)} min = {dec_text(60 * h)} s", "the spacing in seconds")
        if unit == " m³/s":
            r2tr_in_every(q, f"= {dec_text(T)} m²", "the cross-section's area")
            r2tr_in_every(q, f"= {dec_text(T)} × {dec_text(factor)} = {dec_text(total)} m³/s", "the flow")
        else:
            r2tr_in_every(q, f"= {dec_text(total)}{unit}", "the total")
    elif u == "missing-height":
        h, ys, j = r2tr_shape(q)
        need(j is not None, "no k in the table")
        m = re.fullmatch(r"The table gives the (widths|depths), with one of them k\. The trapezoidal rule with these (widths|depths) gives " + R2TR_N + r" m² for the area\.", L[1])
        need(m is not None, f"can't read the estimate {L[1]!r}")
        A = r2tr_q(m.group(3))
        n = len(ys) - 1
        inner = 0 < j < n
        w = 2 if inner else 1
        rest = sum(y * (1 if i in (0, n) else 2) for i, y in enumerate(ys) if i != j)
        k = (2 * A / h - rest) / w
        need(k > 0 and (k * 10).q == 1, "k is not a height to 1 d.p.")
        need(asked == "Find the value of k.", f"asked {asked!r}")
        want = "k = " + dec_text(k)
        if inner:
            wrongs[R2TR_MV + "0"] = {"k = " + r2tr_ends(2 * A / h - rest)}
        else:
            # Both end heights doubled: 2A/h = 2(other end) + 2k + 2(inner sum).
            E = ys[n - j]
            I = sum(y for i, y in enumerate(ys) if 0 < i < n)
            wrongs[R2TR_TD + "2"] = {"k = " + r2tr_ends(A / h - E - I)}
        wrongs[R2TR_MV + "1"] = {"k = " + r2tr_ends((A - rest) / w)}
        r2tr_in_every(q, "k = " + dec_text(k), "k")
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, trap)
    return None, None


SITUATION_CHECKS["trapezoidal"] = r2tr_check

# (end of the R2 markers)


# ── complex-number (t1-ahl-complex-cartesian, t1-ai-complex-cartesian, FAL-1004) ──────────
# Every number is read back from the lines, the question or the Argand diagram's points, and the
# answer and each slip are worked out again with SymPy, exactly: products, quotients and powers
# with I, an argument with sp.arg (exact on Paper 1) or atan2 to 30 digits. A slip's option is
# held to what that slip gives. Every name here starts CX_ or cx_, so it can't overwrite another
# type's.

CX_AA = "AHL1.12."
CX_AI = "AI-AHL1.12."
CX_TA = "t1-ahl-complex-cartesian#"
CX_TI = "t1-ai-complex-cartesian#"
# slip -> ref, for each type: the catalogue's misconceptions, in their order.
CX_REFS = {
    "t1-ahl-complex-cartesian": {
        "i3": CX_AA + "powers-of-i#0", "coef": CX_AA + "powers-of-i#1", "i2plus": CX_AA + "cartesian-arithmetic#0",
        "i2plus-div": CX_AA + "cartesian-arithmetic#0", "i2plus-pow": CX_AA + "cartesian-arithmetic#0",
        "denom-only": CX_AA + "cartesian-arithmetic#1", "pairwise": CX_AA + "cartesian-arithmetic#2",
        "power-parts": CX_AA + "cartesian-arithmetic#2", "quadrant": CX_AA + "parts-modulus-argument#1",
        "mod-add": CX_AA + "parts-modulus-argument#2", "mod-diff": CX_AA + "parts-modulus-argument#2",
        "one-root": CX_AA + "equate-parts#1", "conj-as-z": CX_AA + "equate-parts#2", "swap-axes": CX_AA + "argand-diagram#0",
        "conj-imag-axis": CX_AA + "argand-diagram#1", "part-by-part": CX_TA + "11", "times": CX_TA + "12",
        "wrong-part": CX_TA + "13", "k-sign": CX_TA + "14", "conj-real-sign": CX_TA + "15", "sqrt-swap": CX_TA + "16",
        "sqrt-sign": CX_TA + "17", "p-sign": CX_TA + "18", "arctan-swap": CX_TA + "19", "clockwise": CX_TA + "20",
        "conj-neg": CX_TA + "21", "add-not-sub": CX_TA + "22", "dist-no-root": CX_TA + "23", "sub-wrong-way": CX_TA + "24",
        "sub-not-add": CX_TA + "25", "no-brackets": CX_TA + "26",
    },
    "t1-ai-complex-cartesian": {
        "i2plus": CX_AI + "add-multiply#0", "pairwise": CX_AI + "add-multiply#1", "part-by-part": CX_AI + "divide-conjugate#0",
        "diff-squares": CX_AI + "divide-conjugate#1", "denom-only": CX_AI + "divide-conjugate#2",
        "quadrant": CX_AI + "modulus-argument#0", "no-root": CX_AI + "modulus-argument#1", "mod-diff": CX_AI + "modulus-argument#2",
        "power-parts": CX_AI + "powers-technology#0", "no-brackets": CX_AI + "powers-technology#1",
        "swap-axes": CX_AI + "argand-diagram#0", "conj-imag-axis": CX_AI + "argand-diagram#1", "conj-neg": CX_AI + "argand-diagram#2",
        "not-halved": CX_AI + "complex-quadratic-roots#0", "no-solution": CX_AI + "complex-quadratic-roots#1",
        "real-roots": CX_AI + "complex-quadratic-roots#2", "i3": CX_TI + "16", "times": CX_TI + "17", "arctan-swap": CX_TI + "18",
        "clockwise": CX_TI + "19", "add-not-sub": CX_TI + "20", "h-sign": CX_TI + "21", "coef": CX_TI + "22",
    },
}
CX_SUP = {c: str(i) for i, c in enumerate("⁰¹²³⁴⁵⁶⁷⁸⁹")}
CX_READ_A = "The point A on the Argand diagram represents the complex number z."
CX_READ_AB = "The points A and B on the Argand diagram represent the complex numbers z₁ and z₂."


def cx_q(x):
    """A rational as the game writes it: "3", "−3/2"."""
    x = sp.Rational(x)
    s = str(abs(x.p)) if x.q == 1 else f"{abs(x.p)}/{x.q}"
    return ("−" if x < 0 else "") + s


def cx_iterm(b):
    m = abs(sp.Rational(b))
    if m == 1:
        return "i"
    return f"{m.p}i" if m.q == 1 else f"({m.p}/{m.q})i"


def cx_parts(z):
    z = sp.expand(z)
    a, b = sp.re(z), sp.im(z)
    need(a.is_rational and b.is_rational, f"{z} doesn't have rational parts")
    return sp.Rational(a), sp.Rational(b)


def cx_fmt(z):
    """a + bi as the IB writes it: "3 − 2i", "−i", "4", "1/2 + (3/2)i"."""
    a, b = cx_parts(z)
    if b == 0:
        return cx_q(a)
    if a == 0:
        return ("−" if b < 0 else "") + cx_iterm(b)
    return cx_q(a) + (" − " if b < 0 else " + ") + cx_iterm(b)


def cx_parse(t):
    """A complex number from its text: "−5 − 2i", "(3/5)i", "−2 + 2√3 i"."""
    s = t.replace("−", "-")
    s = re.sub(r"(\d)√", r"\1*√", s)
    s = re.sub(r"√(\d+)", r"sqrt(\1)", s)
    s = re.sub(r"(\d|\))\s*i", r"\1*I", s)
    s = re.sub(r"(?<![A-Za-z*])i", "I", s)
    need(re.fullmatch(r"[-+*/() 0-9I]*(sqrt\(\d+\)[-+*/() 0-9I]*)*", s) is not None, f"can't read the number {t!r}")
    return sp.expand(sp.sympify(s, locals={"I": sp.I, "sqrt": sp.sqrt}))


def cx_read(line, name):
    need(line.startswith(name + " = "), f"expected {name} = …, got {line!r}")
    return cx_parse(line[len(name) + 3:])


def cx_sup(s):
    need(s != "" and all(ch in CX_SUP for ch in s), f"can't read the power {s!r}")
    return int("".join(CX_SUP[ch] for ch in s))


def cx_mulplus(z, w):
    """z × w worked with i² = +1."""
    a, b = cx_parts(z)
    c, d = cx_parts(w)
    return (a * c + b * d) + (a * d + b * c) * sp.I


def cx_root(n):
    """√n in simplest surd form: "13", "√61", "6√2"."""
    n = int(n)
    m, r = 1, n
    f = 2
    while f * f <= r:
        while r % (f * f) == 0:
            r //= f * f
            m *= f
        f += 1
    if r == 1:
        return str(m)
    return ("" if m == 1 else str(m)) + f"√{r}"


def cx_pi(c):
    """A multiple of π: "π", "5π/6", "−π/2"."""
    c = sp.Rational(c)
    top = "π" if abs(c.p) == 1 else f"{abs(c.p)}π"
    return ("−" if c < 0 else "") + top + ("" if c.q == 1 else f"/{c.q}")


def cx_point(q, label):
    g = q["graph"]
    need(g is not None and g.get("x_name") == "Re" and g.get("y_name") == "Im", "no Argand diagram")
    pts = [p for p in g["points"] if p["label"] == label or p["label"].startswith(label + "(")]
    need(len(pts) == 1, f"no point {label} on the diagram")
    p = pts[0]
    need(g["x0"] <= p["x"] <= g["x1"] and g["y0"] <= p["y"] <= g["y1"], f"{label} is off the diagram")
    return p


def cx_grid_point(q, label):
    """A point drawn on a grid line: its whole-number coordinates."""
    p = cx_point(q, label)
    x, y = sp.Rational(p["x"]), sp.Rational(p["y"])
    need(x.q == 1 and y.q == 1 and x != 0 and y != 0, f"{label} is not on a grid point off the axes")
    return x + y * sp.I


def cx_conj_text(z):
    return cx_fmt(sp.conjugate(z))


def cx_pm(z):
    """±(a + bi) with a > 0."""
    a, b = cx_parts(z)
    if a < 0 or (a == 0 and b < 0):
        z = -z
    return f"±({cx_fmt(z)})"


def cx_check(q):
    t, u, rep, L, asked = q["view"]["type"], q["view"]["unknown"], q["view"]["rep"], q["lines"], q["asked"]
    refs = CX_REFS[t]
    ai = t == "t1-ai-complex-cartesian"
    need(q["paper"] == 2 if ai else q["paper"] in (1, 2), f"Paper {q['paper']}")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs = {}

    def slip(key, text):
        if key in refs:
            wrongs.setdefault(refs[key], set()).add(text)

    trap = None
    I = sp.I
    if u == "power-of-i":
        need(t == "t1-ai-complex-cartesian" or q["paper"] == 1, "powers of i are Paper 1")
        m = re.fullmatch(r"(?:i|\((\d)i\))([⁰¹²³⁴⁵⁶⁷⁸⁹]+)", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        k, n = int(m.group(1) or 1), cx_sup(m.group(2))
        need(asked == f"Simplify {L[0]}, giving your answer in the form a + bi.", f"asked {asked!r}")
        v = sp.expand((k * I) ** n)
        want = cx_fmt(v)
        if n % 4 == 3:
            slip("i3", cx_fmt(k ** n * I))
        if k > 1:
            slip("coef", cx_fmt(sp.expand(k * I ** n)))
    elif u == "product":
        z = cx_read(L[0], "z")
        if asked == "Find the value of zz*.":
            name, w = "zz*", sp.conjugate(z)
            need(len(L) == 1, "zz* has one number")
        else:
            m = re.fullmatch(r"Find (zw|z²|zw\*) in the form a \+ bi\.", asked)
            need(m is not None, f"asked {asked!r}")
            name = m.group(1)
            if name == "z²":
                need(len(L) == 1, "z² has one number")
                w = z
            else:
                need(len(L) == 2, "zw has two numbers")
                w = cx_read(L[1], "w")
                if name == "zw*":
                    w = sp.conjugate(w)
        p = sp.expand(z * w)
        want = f"{name} = {cx_fmt(p)}"
        a, b = cx_parts(z)
        c, d = cx_parts(w)
        slip("i2plus", f"{name} = {cx_fmt(cx_mulplus(z, w))}")
        slip("pairwise", f"{name} = {cx_fmt(a * c + b * d * I)}")
    elif u == "quotient":
        need(asked == "Express z/w in the form a + bi.", f"asked {asked!r}")
        z, w = cx_read(L[0], "z"), cx_read(L[1], "w")
        r = sp.expand(sp.simplify(z / w))
        ra, rb = cx_parts(r)
        need(ra.q == 1 and rb.q == 1, "the quotient isn't whole")
        want = f"z/w = {cx_fmt(r)}"
        a, b = cx_parts(z)
        c, d = cx_parts(w)
        nw = c ** 2 + d ** 2
        slip("denom-only", f"z/w = {cx_fmt(z / nw)}")
        slip("part-by-part", f"z/w = {cx_fmt(a / c + b / d * I)}")
        if c ** 2 != d ** 2:
            slip("diff-squares", f"z/w = {cx_fmt(sp.expand(z * sp.conjugate(w)) / (c ** 2 - d ** 2))}")
            slip("i2plus-div", f"z/w = {cx_fmt(cx_mulplus(z, sp.conjugate(w)) / (c ** 2 - d ** 2))}")
    elif u == "solve-linear":
        need(asked == "Find z in the form a + bi.", f"asked {asked!r}")
        m = re.fullmatch(r"\((.+)\)z = (.+)", L[0]) or re.fullmatch(r"(−?\d*i)z = (.+)", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        w, rhs = cx_parse(m.group(1)), cx_parse(m.group(2))
        r = sp.expand(sp.simplify(rhs / w))
        ra, rb = cx_parts(r)
        need(ra.q == 1 and rb.q == 1, "z isn't whole")
        want = f"z = {cx_fmt(r)}"
        c, d = cx_parts(w)
        e, f = cx_parts(rhs)
        slip("denom-only", f"z = {cx_fmt(rhs / (c ** 2 + d ** 2))}")
        slip("times", f"z = {cx_fmt(sp.expand(rhs * w))}")
        if c ** 2 != d ** 2:
            slip("diff-squares", f"z = {cx_fmt(sp.expand(rhs * sp.conjugate(w)) / (c ** 2 - d ** 2))}")
        if c != 0 and d != 0:
            slip("part-by-part", f"z = {cx_fmt(e / c + f / d * I)}")
    elif u == "power":
        m = re.fullmatch(r"Find z([⁰¹²³⁴⁵⁶⁷⁸⁹]+) in the form a \+ bi\.", asked)
        need(m is not None, f"asked {asked!r}")
        n = cx_sup(m.group(1))
        need(2 <= n <= (6 if ai else 4), f"power {n}")
        z = cx_read(L[0], "z")
        a, b = cx_parts(z)
        name = "z" + m.group(1)
        want = f"{name} = {cx_fmt(sp.expand(z ** n))}"
        slip("power-parts", f"{name} = {cx_fmt(sp.expand(a ** n + (b * I) ** n))}")
        slip("no-brackets", f"{name} = {cx_fmt(sp.expand(a + b * I ** n))}")
        pw = sp.Integer(1)
        for _ in range(n):
            pw = cx_mulplus(pw, z)
        slip("i2plus-pow", f"{name} = {cx_fmt(pw)}")
    elif u == "real-parameter":
        m = re.fullmatch(r"z = \(k ([+−]) (\d*)i\)\((.+)\), where k is real\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        mm = int(m.group(2) or 1) * (-1 if m.group(1) == "−" else 1)
        w = cx_parse(m.group(3))
        k = sp.Symbol("k", real=True)
        c, d = cx_parts(w)
        re_, im_ = k * c - mm * d, k * d + mm * c
        re_plus = k * c + mm * d
        mode = {"Find the value of k for which z is real.": "real", "Find the value of k for which z is purely imaginary.": "imaginary",
                "Find the value of k for which arg z = π/4.": "quarter"}.get(asked)
        need(mode is not None, f"asked {asked!r}")
        solve1 = lambda e: sp.solve(e, k)[0]
        if mode == "real":
            kv = solve1(im_)
            slip("wrong-part", f"k = {cx_q(solve1(re_))}")
        elif mode == "imaginary":
            kv = solve1(re_)
            slip("wrong-part", f"k = {cx_q(solve1(im_))}")
            slip("i2plus", f"k = {cx_q(solve1(re_plus))}")
        else:
            kv = solve1(re_ - im_)
            need(re_.subs(k, kv) > 0, "arg z is not π/4: the parts are not positive")
            slip("i2plus", f"k = {cx_q(solve1(re_plus - im_))}")
        need(kv != 0, "k is 0")
        want = f"k = {cx_q(kv)}"
        slip("k-sign", f"k = {cx_q(-kv)}")
    elif u == "equate-conjugate":
        need(asked == "Find z, giving your answer in the form a + bi.", f"asked {asked!r}")
        m = re.fullmatch(r"(−?\d*)z ([+−]) (\d*)(i?)z\* = (.+)", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        al = {"": 1, "−": -1}.get(m.group(1)) or int(m.group(1).replace("−", "-"))
        be = int(m.group(3) or 1) * (-1 if m.group(2) == "−" else 1)
        rot = I if m.group(4) else 1
        rhs = cx_parse(m.group(5))
        x, y = sp.symbols("x y", real=True)

        def solve_for(zs):
            lhs = sp.expand(al * (x + y * I) + be * rot * zs)
            sol = sp.solve([sp.re(lhs) - sp.re(rhs), sp.im(lhs) - sp.im(rhs)], [x, y], dict=True)
            need(len(sol) == 1, "the equation doesn't have one solution")
            return sol[0][x] + sol[0][y] * I

        zv = solve_for(x - y * I)
        want = f"z = {cx_fmt(zv)}"
        slip("conj-as-z", f"z = {cx_fmt(sp.expand(sp.simplify(rhs / (al + be * rot))))}")
        slip("conj-real-sign", f"z = {cx_fmt(solve_for(-x + y * I))}")
    elif u == "square-root":
        need(asked == "Find the two square roots of z, in the form ±(a + bi) with a > 0.", f"asked {asked!r}")
        z = cx_read(L[0], "z")
        a, b = sp.symbols("a b", real=True)
        A, Bv = cx_parts(z)
        sols = [s for s in sp.solve([a ** 2 - b ** 2 - A, 2 * a * b - Bv], [a, b], dict=True) if s[a].is_real and s[a] > 0]
        need(len(sols) == 1 and sols[0][a].is_integer and sols[0][b].is_integer, "the roots aren't whole")
        r = sols[0][a] + sols[0][b] * I
        need(sp.expand(r ** 2 - z) == 0, "the root doesn't square back")
        want = cx_pm(r)
        ra, rb = cx_parts(r)
        slip("one-root", cx_fmt(r))
        slip("sqrt-swap", cx_pm(rb + ra * I))
        slip("sqrt-sign", cx_pm(ra - rb * I))
    elif u == "root-substitute":
        m = re.fullmatch(r"The equation z² \+ pz \+ q = 0, where p and q are real, has a root z = (.+)\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        need(asked == "Find the value of p and the value of q.", f"asked {asked!r}")
        r = cx_parse(m.group(1))
        p, qq = sp.symbols("p q", real=True)
        e = sp.expand(r ** 2 + p * r + qq)
        sol = sp.solve([sp.re(e), sp.im(e)], [p, qq], dict=True)
        need(len(sol) == 1, "p and q aren't fixed")
        pv, qv = sol[0][p], sol[0][qq]
        want = f"p = {cx_q(pv)}, q = {cx_q(qv)}"
        mr, nr = cx_parts(r)
        slip("i2plus", f"p = {cx_q(-2 * mr)}, q = {cx_q(mr ** 2 - nr ** 2)}")
        slip("p-sign", f"p = {cx_q(2 * mr)}, q = {cx_q(nr ** 2 - 3 * mr ** 2)}")
    elif u in ("modulus", "argument", "argand-read"):
        if rep == "equation":
            need(u != "argand-read", "argand-read is on a diagram")
            z = cx_read(L[0], "z")
        else:
            special = u == "argument" and L[0] != CX_READ_A
            if special:
                m = re.fullmatch(r"The point A\((.+), (.+)\) on the Argand diagram represents the complex number z\.", L[0])
                need(m is not None, f"can't read {L[0]!r}")
                z = cx_parse(m.group(1)) + cx_parse(m.group(2)) * I
                p = cx_point(q, "A")
                need(abs(sp.N(sp.re(z)) - p["x"]) < 1e-9 and abs(sp.N(sp.im(z)) - p["y"]) < 1e-9, "the point isn't where its label says")
            else:
                need(L[0] == CX_READ_A, f"lines {L!r}")
                z = cx_grid_point(q, "A")
        a, b = sp.re(z), sp.im(z)
        if u == "modulus":
            a, b = cx_parts(z)
            n = a ** 2 + b ** 2
            by_gdc = q["view"]["angle"] == "gdc-abs-angle"
            sf = by_gdc and sp.sqrt(n).is_rational is False
            need(asked == ("Find |z|." if by_gdc else "Find the exact value of |z|."), f"asked {asked!r}")
            show = (lambda v: gc_s(sp.N(sp.sqrt(v), 30))) if sf else (lambda v: cx_root(v))
            if sf:
                want, trap = r1ap_sf("|z| = ", sp.N(sp.sqrt(n), 30))
            else:
                want = "|z| = " + cx_root(n)
            slip("mod-add", "|z| = " + (gc_s(abs(a) + abs(b)) if sf else str(abs(a) + abs(b))))
            slip("no-root", "|z| = " + (gc_s(n) if sf else str(n)))
            if a ** 2 != b ** 2:
                slip("mod-diff", "|z| = " + show(abs(a ** 2 - b ** 2)))
        elif u == "argument":
            th = sp.arg(z)
            if q["paper"] == 1:
                need(asked == "Find arg z, where −π < arg z ≤ π.", f"asked {asked!r}")
                c = sp.nsimplify(th / sp.pi)
                need(c.is_rational and c.q in (2, 3, 4, 6), f"arg z = {th} is not a standard angle")
                want = "arg z = " + cx_pi(c)
                if a < 0:
                    slip("quadrant", "arg z = " + cx_pi(sp.nsimplify(sp.atan(b / a) / sp.pi)))
                slip("arctan-swap", "arg z = " + cx_pi(sp.nsimplify(sp.atan(a / b) / sp.pi)))
            else:
                need(asked == "Find arg z, giving your answer in radians, correct to 3 significant figures.", f"asked {asked!r}")
                need(sp.re(z).is_integer and sp.im(z).is_integer and abs(a) != abs(b), "Paper 2 numbers")
                thf = sp.N(sp.atan2(b, a), 30)
                need(r1ap_clear3(thf), "arg z is on a 3 s.f. edge")
                want, trap = r1ap_sf("arg z = ", thf)
                if a < 0:
                    slip("quadrant", "arg z = " + gc_s(sp.N(sp.atan(b / a), 30)))
                slip("arctan-swap", "arg z = " + gc_s(sp.N(sp.atan(a / b), 30)))
        else:
            a, b = cx_parts(z)
            mode = {"Write down z in the form a + bi.": "z", "Write down z* in the form a + bi.": "z*",
                    "Write down −z in the form a + bi.": "−z", "Find iz in the form a + bi.": "iz"}.get(asked)
            need(mode is not None, f"asked {asked!r}")
            op = {"z": lambda v: v, "z*": sp.conjugate, "−z": lambda v: -v, "iz": lambda v: sp.expand(I * v)}[mode]
            want = f"{mode} = {cx_fmt(op(z))}"
            slip("swap-axes", f"{mode} = {cx_fmt(op(b + a * I))}")
            if mode == "z*":
                slip("conj-imag-axis", f"{mode} = {cx_fmt(-a + b * I)}")
                slip("conj-neg", f"{mode} = {cx_fmt(-z)}")
            elif mode == "−z":
                slip("conj-neg", f"{mode} = {cx_fmt(sp.conjugate(z))}")
            elif mode == "iz":
                slip("clockwise", f"{mode} = {cx_fmt(sp.expand(-I * z))}")
    elif u == "argand-sum":
        need(L == [CX_READ_AB], f"lines {L!r}")
        z1, z2 = cx_grid_point(q, "A"), cx_grid_point(q, "B")
        sw = lambda v: sp.im(v) + sp.re(v) * I
        if asked == "Find z₁ + z₂ in the form a + bi.":
            name, v, vs = "z₁ + z₂", z1 + z2, sw(z1) + sw(z2)
            slip("sub-not-add", f"{name} = {cx_fmt(z1 - z2)}")
        else:
            need(asked == "The vector from A to B represents z₂ − z₁. Find z₂ − z₁ in the form a + bi.", f"asked {asked!r}")
            name, v, vs = "z₂ − z₁", z2 - z1, sw(z2) - sw(z1)
            slip("sub-wrong-way", f"{name} = {cx_fmt(z1 - z2)}")
        want = f"{name} = {cx_fmt(v)}"
        slip("swap-axes", f"{name} = {cx_fmt(vs)}")
    elif u == "distance":
        if rep == "equation":
            need(asked == "Find the exact distance between the points that represent z₁ and z₂ on an Argand diagram.", f"asked {asked!r}")
            z1, z2 = cx_read(L[0], "z₁"), cx_read(L[1], "z₂")
        else:
            need(L == [CX_READ_AB] and asked == "Find the exact distance AB.", f"lines {L!r}, asked {asked!r}")
            z1, z2 = cx_grid_point(q, "A"), cx_grid_point(q, "B")
        d = z2 - z1
        n = sp.re(d) ** 2 + sp.im(d) ** 2
        want = "|z₂ − z₁| = " + cx_root(n)
        s = z1 + z2
        slip("add-not-sub", "|z₂ − z₁| = " + cx_root(sp.re(s) ** 2 + sp.im(s) ** 2))
        slip("dist-no-root", f"|z₂ − z₁| = {n}")
        slip("no-root", f"|z₂ − z₁| = {n}")
    elif u == "quadratic-roots":
        need(ai, "quadratic-roots is AI's")
        zx = sp.Symbol("z")
        if rep == "equation":
            need(asked == "Solve the equation, giving the roots in the form h ± ki.", f"asked {asked!r}")
            m = re.fullmatch(r"(z² .+) = 0", L[0])
            need(m is not None, f"can't read {L[0]!r}")
            poly = m.group(1)
        else:
            m = re.fullmatch(r"The diagram shows the graph of y = (x² .+), with its vertex marked\.", L[0])
            need(m is not None, f"can't read {L[0]!r}")
            poly = m.group(1).replace("x", "z")
            need(asked == f"Hence solve {poly} = 0, giving the roots in the form h ± ki.", f"asked {asked!r}")
        mm = re.fullmatch(r"z² ([+−]) (\d*)z ([+−]) (\d+)", poly)
        need(mm is not None, f"can't read the quadratic {poly!r}")
        pv = int(mm.group(2) or 1) * (-1 if mm.group(1) == "−" else 1)
        qv = int(mm.group(4)) * (-1 if mm.group(3) == "−" else 1)
        roots = sp.solve(zx ** 2 + pv * zx + qv, zx)
        need(len(roots) == 2 and all(sp.im(r) != 0 for r in roots), "the roots aren't a complex pair")
        h, k = sp.re(roots[0]), abs(sp.im(roots[0]))
        need(h.is_integer and k.is_integer and h != 0, "the roots aren't whole")
        if rep == "graph":
            g = q["graph"]
            need(g and float(g["a"]) == 1.0 and float(g["h"]) == float(h) and float(g["k"]) == float(k ** 2), "the parabola drawn isn't this quadratic")
            need([(p["x"], p["y"]) for p in g["points"]] == [(float(h), float(k ** 2))] and g["points"][0]["label"] == f"({cx_q(h)}, {cx_q(k ** 2)})", "the vertex marked")
            need(g["y0"] < 0 < k ** 2 < g["y1"] and g["x0"] < h < g["x1"], "the vertex is off the graph")
        roots_text = lambda hh, kk: f"z = {cx_q(hh)} ± {cx_iterm(kk)}"
        want = roots_text(h, k)
        slip("not-halved", roots_text(h, 2 * k))
        slip("real-roots", f"z = {cx_q(h - k)} or z = {cx_q(h + k)}")
        slip("no-solution", "There are no solutions.")
        slip("h-sign", roots_text(-h, k))
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, trap)
    return None, None


SITUATION_CHECKS["complex-number"] = cx_check
SITUATION_CHECKS["complex-number-ai"] = cx_check


# ── complex-polar (t1-ahl-complex-polar, t1-ahl-de-moivre, t1-ahl-conjugate-roots, t1-ai-complex-polar, FAL-1005) ──
# Every number is read back from the lines, the question or the Argand diagram, and the answer
# and each slip are worked out again with SymPy: a modulus with sp.Abs, an argument with sp.arg,
# exact cosines and sines, products and powers with I. A slip's option is held to what that slip
# gives. Every name here starts CPL_ or cpl_, so it can't overwrite another type's.

CPL_AA = "AHL1.13."
CPL_TA = "t1-ahl-complex-polar#"
CPL_REFS = {
    "t1-ahl-complex-polar": {
        "quadrant": CPL_AA + "convert-forms#0", "mod-add": CPL_AA + "convert-forms#1", "neg-mod": CPL_AA + "convert-forms#2",
        "arg-mul": CPL_AA + "polar-products-quotients#0", "mod-sum": CPL_AA + "polar-products-quotients#1",
        "arg-div": CPL_AA + "polar-products-quotients#2", "clockwise": CPL_AA + "geometric-interpretation#0",
        "rotation-only": CPL_AA + "geometric-interpretation#1", "add-rotates": CPL_AA + "geometric-interpretation#2",
        "two-mod": CPL_AA + "sums-in-euler-form#0", "add-exp": CPL_AA + "sums-in-euler-form#1", "no-i": CPL_AA + "sums-in-euler-form#2",
        "part-mod": CPL_AA + "exact-trig-from-forms#0", "sub-args": CPL_AA + "exact-trig-from-forms#1",
        "arctan-swap": CPL_TA + "14", "arg-sign": CPL_TA + "15", "trig-swap": CPL_TA + "16", "ref-signs": CPL_TA + "17",
        "unreduced": CPL_TA + "18", "quot-order": CPL_TA + "19", "square-mod": CPL_TA + "20", "mean-diff": CPL_TA + "21",
        "lost-two": CPL_TA + "22", "rev-sign": CPL_TA + "23", "re-for-im": CPL_TA + "24", "neg-vector": CPL_TA + "25",
    },
}
CPL_AI = "AI-AHL1.13."
CPL_TI = "t1-ai-complex-polar#"
CPL_REFS["t1-ai-complex-polar"] = {
    "arg-sign": CPL_AI + "convert-forms#0", "trig-swap": CPL_AI + "convert-forms#1", "degree-mode": CPL_AI + "convert-forms#2",
    "no-root": CPL_AI + "convert-forms#3", "mod-sum": CPL_AI + "multiply-divide-polar#0", "arg-mul": CPL_AI + "multiply-divide-polar#1",
    "quot-order": CPL_AI + "multiply-divide-polar#2", "parts-power": CPL_AI + "integer-powers#0", "mod-unraised": CPL_AI + "integer-powers#1",
    "arg-raised": CPL_AI + "integer-powers#2", "amp-sum": CPL_AI + "add-sinusoids#0", "phase-avg": CPL_AI + "add-sinusoids#1",
    "phase-degrees": CPL_AI + "add-sinusoids#2", "rotation-only": CPL_AI + "geometric-interpretation#0",
    "i-reflect": CPL_AI + "geometric-interpretation#1", "quadrant": CPL_TI + "15", "mod-add": CPL_TI + "16", "ref-signs": CPL_TI + "17",
    "unreduced": CPL_TI + "18", "clockwise": CPL_TI + "19", "add-rotates": CPL_TI + "20", "pos-only": CPL_TI + "21", "kind-swap": CPL_TI + "22",
}
CPL_FORM = {"re^(iθ)": "euler", "r cis θ": "cis"}


def cpl_root_of(n):
    """√n for a whole n as (m, r), r square-free."""
    n = int(n)
    m, r, f = 1, n, 2
    while f * f <= r:
        while r % (f * f) == 0:
            r //= f * f
            m *= f
        f += 1
    return m, r


def cpl_split(x):
    """A real m√r as (m, r): m rational, r square-free."""
    x = sp.nsimplify(sp.simplify(x))
    if x == 0:
        return sp.Integer(0), 1
    n = sp.Rational(sp.simplify(x ** 2))
    k, r = cpl_root_of(n.p * n.q)
    m = sp.Rational(k, n.q) * (1 if x > 0 else -1)
    need(sp.simplify(m * sp.sqrt(r) - x) == 0, f"{x} is not one surd")
    return m, r


def cpl_s(x):
    """m√r as the game writes it: "2√3", "−√2", "3/2", "3√2/2"."""
    m, r = cpl_split(x)
    if r == 1:
        return cx_q(m)
    am = abs(m)
    return ("−" if m < 0 else "") + ("" if am.p == 1 else str(am.p)) + f"√{r}" + ("" if am.q == 1 else f"/{am.q}")


def cpl_iterm(b):
    m, r = cpl_split(abs(b))
    if r == 1:
        if m == 1:
            return "i"
        return f"{m.p}i" if m.q == 1 else f"({m.p}/{m.q})i"
    return cpl_s(abs(b)) + " i"


def cpl_c(z):
    """a + bi with surd parts: "−2√3 + 2i", "3√2 − 3√2 i", "−4i"."""
    z = sp.expand(z)
    a, b = sp.re(z), sp.im(z)
    if b == 0:
        return cpl_s(a)
    if a == 0:
        return ("−" if b < 0 else "") + cpl_iterm(b)
    return cpl_s(a) + (" − " if b < 0 else " + ") + cpl_iterm(b)


def cpl_pi(c):
    c = sp.Rational(c)
    return "0" if c == 0 else cx_pi(c)


def cpl_pi_i(c):
    c = sp.Rational(c)
    if c == 0:
        return "0"
    top = "πi" if abs(c.p) == 1 else f"{abs(c.p)}πi"
    return ("−" if c < 0 else "") + top + ("" if c.q == 1 else f"/{c.q}")


def cpl_p(r, c, style):
    """r e^(cπi) or r cis(cπ) as the game writes it."""
    rt = "" if cpl_split(r) == (1, 1) else cpl_s(r)
    if style == "euler":
        return rt + (" " if "√" in rt else "") + f"e^({cpl_pi_i(c)})"
    return (rt + " " if rt else "") + f"cis({cpl_pi(c)})"


def cpl_principal(c):
    c = sp.Rational(c)
    while c > 1:
        c -= 2
    while c <= -1:
        c += 2
    return c


def cpl_arg(z):
    """arg z as a multiple of π, exactly."""
    a = sp.simplify(sp.arg(sp.expand(z)) / sp.pi)
    need(a.is_rational, f"arg {z} is not a rational multiple of π")
    return sp.Rational(a)


def cpl_cis(r, c):
    return sp.expand(r * (sp.cos(sp.Rational(c) * sp.pi) + sp.I * sp.sin(sp.Rational(c) * sp.pi)))


def cpl_angle(t):
    """A multiple of π from "5π/6", "−πi/4", "π", "0"."""
    t = t.replace("i", "")
    if t == "0":
        return sp.Integer(0)
    m = re.fullmatch(r"(−?)(\d*)π(?:/(\d+))?", t)
    need(m is not None, f"can't read the angle {t!r}")
    return sp.Rational(int(m.group(2) or 1) * (-1 if m.group(1) else 1), int(m.group(3) or 1))


def cpl_polar(t):
    """(r, c, style) from "4e^(5πi/6)", "√2 e^(−πi/4)", "4 cis(π/6)", "cis(π/3)"."""
    m = re.fullmatch(r"(?:(.+?) ?)?e\^\((.+)\)", t)
    if m:
        r = cx_parse(m.group(1)) if m.group(1) else sp.Integer(1)
        return r, cpl_angle(m.group(2)), "euler"
    m = re.fullmatch(r"(?:(.+?) )?cis\((.+)\)", t)
    need(m is not None, f"can't read the polar number {t!r}")
    r = cx_parse(m.group(1)) if m.group(1) else sp.Integer(1)
    return r, cpl_angle(m.group(2)), "cis"


def cpl_read_polar(line, name):
    need(line.startswith(name + " = "), f"expected {name} = …, got {line!r}")
    return cpl_polar(line[len(name) + 3:])


def cpl_quadrant(c):
    c = sp.Rational(c)
    if (2 * c).q == 1:
        return 0
    if c > 0:
        return 1 if c < sp.Rational(1, 2) else 2
    return 4 if c > -sp.Rational(1, 2) else 3


def cpl_turn(c):
    c = sp.Rational(c)
    if c == 1:
        return "π"
    return f"{cpl_pi(abs(c))} {'anticlockwise' if c > 0 else 'clockwise'}"


def cpl_describe(r, c):
    rot = f"a rotation of {cpl_turn(c)} about 0"
    if cpl_split(r) == (1, 1):
        return "A" + rot[1:] + "."
    return f"An enlargement with scale factor {cpl_s(r)} and centre 0, and {rot}."


def cpl_trig_term(k, fn, n, letter, with_i):
    sign = "−" if k < 0 else ""
    m = abs(k)
    lead = ("" if m == 1 else str(m)) + ("i" if with_i else "")
    nl = ("" if n == 1 else str(n)) + letter
    if lead == "":
        return f"{sign}{fn} {nl}"
    return f"{sign}{lead} {fn} {nl}"


def cpl_pair(v, ra, rb, den):
    """v = (x√a + y√b)/den with x, y = ±1, written as the game writes it."""
    for x, y in product([1, -1], [1, -1]):
        if sp.simplify(v - (x * sp.sqrt(int(ra.lstrip("√") or 1)) + y * sp.sqrt(int(rb.lstrip("√") or 1))) / den) == 0:
            tail = "" if den == 1 else f"/{den}"
            if x > 0 and y > 0:
                return f"({ra} + {rb}){tail}"
            if x < 0 and y < 0:
                return f"−({ra} + {rb}){tail}"
            if x > 0:
                return f"({ra} − {rb}){tail}"
            return f"({rb} − {ra}){tail}"
    raise Fail(f"{v} is not (±{ra} ± {rb})/{den}")


def cpl_check(q):
    t, u, rep, L, asked = q["view"]["type"], q["view"]["unknown"], q["view"]["rep"], q["lines"], q["asked"]
    refs = CPL_REFS[t]
    # Every AI paper allows a GDC; AA HL asks these exactly on every paper.
    need(q["paper"] == 2 if t == "t1-ai-complex-polar" else q["paper"] in (1, 2), f"Paper {q['paper']}")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs = {}

    def slip(key, text):
        if key in refs:
            wrongs.setdefault(refs[key], set()).add(text)

    I = sp.I
    pi = sp.pi
    if u == "to-polar":
        m = re.fullmatch(r"Write z in the form (re\^\(iθ\)|r cis θ), where r > 0 and −π < θ ≤ π\.", asked)
        need(m is not None, f"asked {asked!r}")
        style = CPL_FORM[m.group(1)]
        if rep == "graph":
            m2 = re.fullmatch(r"The point A\((.+), (.+)\) on the Argand diagram represents the complex number z\.", L[0])
            need(m2 is not None, f"can't read {L[0]!r}")
            z = cx_parse(m2.group(1)) + I * cx_parse(m2.group(2))
            p = cx_point(q, "A")
            need(abs(p["x"] - float(sp.re(z))) < 1e-9 and abs(p["y"] - float(sp.im(z))) < 1e-9, "A is drawn in the wrong place")
        else:
            z = cx_read(L[0], "z")
        r, c = sp.simplify(sp.Abs(z)), cpl_arg(z)
        want = "z = " + cpl_p(r, c, style)
        a, b = sp.re(z), sp.im(z)
        qd = cpl_quadrant(c)
        if qd in (2, 3):
            slip("quadrant", "z = " + cpl_p(r, sp.Rational(sp.atan(b / a) / pi), style))
        elif c == 1:
            slip("quadrant", "z = " + cpl_p(r, 0, style))
        if qd > 0 and abs(a) == abs(b):
            slip("mod-add", "z = " + cpl_p(abs(a) + abs(b), c, style))
        if c == 1:
            slip("neg-mod", "z = −" + cpl_s(r) + ("e^(0)" if style == "euler" else " cis 0"))
        if qd > 0:
            slip("arctan-swap", "z = " + cpl_p(r, sp.Rational(sp.atan(a / b) / pi), style))
        if c != 1:
            slip("arg-sign", "z = " + cpl_p(r, -c, style))
        slip("no-root", "z = " + cpl_p(a ** 2 + b ** 2, c, style))
    elif u == "to-cartesian":
        need(asked == "Write z in the form a + bi.", f"asked {asked!r}")
        r, c, _ = cpl_read_polar(L[0], "z")
        z = cpl_cis(r, c)
        want = "z = " + cpl_c(z)
        a, b = sp.re(z), sp.im(z)
        slip("trig-swap", "z = " + cpl_c(b + a * I))
        if cpl_quadrant(c) != 1:
            slip("ref-signs", "z = " + cpl_c(abs(a) + abs(b) * I))
    elif u in ("polar-product", "product-cartesian"):
        if u == "polar-product":
            m = re.fullmatch(r"Write (z₁z₂|z₁/z₂|z²) in the form (re\^\(iθ\)|r cis θ), where r > 0 and −π < θ ≤ π\.", asked)
        else:
            m = re.fullmatch(r"Express (z₁z₂|z₁/z₂) in the form a \+ bi\.", asked)
        need(m is not None, f"asked {asked!r}")
        name = m.group(1)
        if name == "z²":
            need(len(L) == 1, "z² has one number")
            r1, c1, style = cpl_read_polar(L[0], "z")
            R, raw = r1 ** 2, 2 * c1
        else:
            need(len(L) == 2, f"{name} has two numbers")
            r1, c1, style = cpl_read_polar(L[0], "z₁")
            r2, c2, style2 = cpl_read_polar(L[1], "z₂")
            need(style == style2, "the two numbers are in different forms")
            R, raw = (r1 * r2, c1 + c2) if name == "z₁z₂" else (r1 / r2, c1 - c2)
        z = sp.expand(sp.simplify(cpl_cis(r1, c1) * (cpl_cis(r1, c1) if name == "z²" else cpl_cis(r2, c2) if name == "z₁z₂" else 1 / cpl_cis(r2, c2))))
        need(sp.simplify(sp.Abs(z) - R) == 0, "the modulus rule is off")
        C = cpl_principal(raw)
        need(C == cpl_arg(z), "the argument rule is off")
        head = name + " = "
        if u == "polar-product":
            want = head + cpl_p(R, C, style)
            if name == "z₁z₂":
                pr = c1 * c2
                top = "π²" if abs(pr.p) == 1 else f"{abs(pr.p)}π²"
                pt = ("−" if pr < 0 else "") + top + ("" if pr.q == 1 else f"/{pr.q}")
                slip("arg-mul", head + cpl_s(R) + ((" " if "√" in cpl_s(R) else "") + f"e^({pt.replace('π²', 'π²i')})" if style == "euler" else f" cis({pt})"))
                slip("mod-sum", head + cpl_p(r1 + r2, C, style))
            elif name == "z₁/z₂":
                x = sp.Rational(c1 / c2)
                if style == "euler":
                    tx = ("−" if x < 0 else "") + ("" if abs(x.p) == 1 else str(abs(x.p))) + "i" + ("" if x.q == 1 else f"/{x.q}")
                    slip("arg-div", head + cpl_s(R) + f"e^({tx})")
                else:
                    slip("arg-div", head + cpl_s(R) + f" cis({cx_q(x)})")
                slip("quot-order", head + cpl_p(R, cpl_principal(c2 - c1), style))
            else:
                slip("square-mod", head + cpl_p(2 * r1, C, style))
            if raw != C:
                slip("unreduced", head + cpl_p(R, raw, style))
        else:
            want = head + cpl_c(z)
            a, b = sp.re(z), sp.im(z)
            slip("trig-swap", head + cpl_c(b + a * I))
            if name == "z₁z₂":
                slip("mod-sum", head + cpl_c(cpl_cis(r1 + r2, C)))
            else:
                slip("quot-order", head + cpl_c(cpl_cis(R, cpl_principal(c2 - c1))))
    elif u == "rotate-point":
        need(rep == "graph" and L == [CX_READ_A], f"lines {L!r}")
        z = cx_grid_point(q, "A")
        m = re.fullmatch(r"A is rotated through (π|π/2 anticlockwise|π/2 clockwise) about the origin(?:, then enlarged with scale factor (\d) and centre the origin,)? to give the point B\. Find the complex number that B represents, in the form a \+ bi\.", asked)
        need(m is not None, f"asked {asked!r}")
        c = {"π": sp.Integer(1), "π/2 anticlockwise": sp.Rational(1, 2), "π/2 clockwise": sp.Rational(-1, 2)}[m.group(1)]
        k = int(m.group(2) or 1)
        need(k > 1 or m.group(2) is None, "an enlargement by 1")
        want = "B = " + cpl_c(cpl_cis(k, c) * z)
        if c != 1:
            slip("clockwise", "B = " + cpl_c(cpl_cis(k, -c) * z))
        if k > 1:
            slip("rotation-only", "B = " + cpl_c(cpl_cis(1, c) * z))
    elif u == "describe-map":
        w = cx_read(L[0], "w")
        a, b = sp.re(w), sp.im(w)
        if asked == "Describe geometrically the transformation of the Argand diagram that maps z to z + w.":
            want = f"A translation by the vector ({cx_q(a)}, {cx_q(b)})."
            slip("add-rotates", "A rotation about 0 through the angle arg w.")
            slip("neg-vector", f"A translation by the vector ({cx_q(-a)}, {cx_q(-b)}).")
        else:
            need(asked == "Describe geometrically the transformation of the Argand diagram that maps z to wz.", f"asked {asked!r}")
            r, c = sp.simplify(sp.Abs(w)), cpl_arg(w)
            want = cpl_describe(r, c)
            if c != 1:
                slip("clockwise", cpl_describe(r, -c))
            if cpl_split(r) != (1, 1):
                slip("rotation-only", cpl_describe(1, c))
            if w == I:
                slip("i-reflect", "A reflection in the line y = x.")
    elif u == "euler-sum":
        m = re.fullmatch(r"Write z in the form (re\^\(iθ\)|r cis θ), where r > 0 and −π < θ ≤ π\.", asked)
        need(m is not None, f"asked {asked!r}")
        style = CPL_FORM[m.group(1)]
        m = re.fullmatch(r"z = (.+) \+ (.+)", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        cs = []
        for term in (m.group(1), m.group(2)):
            if term == "1":
                cs.append(sp.Integer(0))
            else:
                r1, c1, st = cpl_polar(term)
                need(r1 == 1 and st == style, f"the term {term!r}")
                cs.append(c1)
        al, be = (cs[1], cs[0]) if m.group(1) == "1" else (cs[0], cs[1])
        z = sp.expand(sp.exp(I * pi * al) + sp.exp(I * pi * be))
        r, c = sp.simplify(sp.Abs(z)), cpl_arg(z)
        need(r != 0, "the sum is 0")
        want = "z = " + cpl_p(r, c, style)
        slip("two-mod", "z = " + cpl_p(2, c, style))
        slip("add-exp", "z = " + cpl_p(1, cpl_principal(al + be), style))
        half = (al - be) / 2
        if abs(half) != abs(c):
            slip("mean-diff", "z = " + cpl_p(r, half, style))
    elif u == "euler-trig":
        m = re.fullmatch(r"(\d?)e\^\((−?)(\d?)i(θ|x)\) − (\d?)e\^\((−?)(\d?)i(θ|x)\)|(\d?)e\^\((\d?)i(θ|x)\) \+ (\d?)e\^\(−(\d?)i(θ|x)\)", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        if m.group(9) is not None:
            k, n, letter = int(m.group(9) or 1), int(m.group(10) or 1), m.group(11)
            need((int(m.group(12) or 1), int(m.group(13) or 1), m.group(14)) == (k, n, letter), "the two terms differ")
            mode = "plus"
        else:
            k, n, letter = int(m.group(1) or 1), int(m.group(3) or 1), m.group(4)
            need((int(m.group(5) or 1), int(m.group(7) or 1), m.group(8)) == (k, n, letter), "the two terms differ")
            need((m.group(2), m.group(6)) in (("", "−"), ("−", "")), "the signs of the powers")
            mode = "minus" if m.group(2) == "" else "reverse"
        nl = ("" if n == 1 else str(n)) + letter
        need(asked == f"Write this expression as a single term in sin {nl} or cos {nl}.", f"asked {asked!r}")
        th = sp.Symbol("t", real=True)
        e1, e2 = k * sp.exp(I * n * th), k * sp.exp(-I * n * th)
        val = sp.simplify(sp.expand_complex(e1 + e2 if mode == "plus" else e1 - e2 if mode == "minus" else e2 - e1))
        if mode == "plus":
            need(sp.simplify(val - 2 * k * sp.cos(n * th)) == 0, "the sum is not 2k cos nθ")
            want = cpl_trig_term(2 * k, "cos", n, letter, False)
            slip("lost-two", cpl_trig_term(k, "cos", n, letter, False))
        else:
            sgn = 1 if mode == "minus" else -1
            need(sp.simplify(val - sgn * 2 * k * I * sp.sin(n * th)) == 0, "the difference is not ±2ki sin nθ")
            want = cpl_trig_term(sgn * 2 * k, "sin", n, letter, True)
            slip("no-i", cpl_trig_term(sgn * 2 * k, "sin", n, letter, False))
            if mode == "minus":
                slip("lost-two", cpl_trig_term(k, "sin", n, letter, True))
            else:
                slip("rev-sign", cpl_trig_term(2 * k, "sin", n, letter, True))
    elif u == "exact-trig":
        m = re.fullmatch(r"By writing (z₁z₂|z₁/z₂) in the form a \+ bi and in modulus-argument form, find the exact value of (cos|sin)\((.+)\)\.", asked)
        need(m is not None, f"asked {asked!r}")
        name, fn, phi = m.group(1), m.group(2), cpl_angle(m.group(3))
        z1, z2 = cx_read(L[0], "z₁"), cx_read(L[1], "z₂")
        w = sp.expand(sp.simplify(z1 * z2 if name == "z₁z₂" else z1 / z2))
        need(cpl_arg(w) == phi, "the angle asked is not the argument")
        need(phi.q == 12, "the angle is not an odd multiple of π/12")
        val = sp.cos(phi * pi) if fn == "cos" else sp.sin(phi * pi)
        oth = sp.sin(phi * pi) if fn == "cos" else sp.cos(phi * pi)
        head = f"{fn}({cpl_pi(phi)}) = "
        want = head + cpl_pair(val, "√6", "√2", 4)
        slip("re-for-im", head + cpl_pair(oth, "√6", "√2", 4))
        part = sp.re(w) if fn == "cos" else sp.im(w)
        den = 2 if name == "z₁z₂" else 4
        slip("part-mod", head + cpl_pair(part / 2, "1", "√3", den))
        if name == "z₁z₂":
            phi2 = cpl_arg(sp.expand(sp.simplify(z1 / z2)))
            slip("sub-args", head + cpl_pair(sp.cos(phi2 * pi) if fn == "cos" else sp.sin(phi2 * pi), "√6", "√2", 4))
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, None)
    return None, None


SITUATION_CHECKS["complex-polar"] = cpl_check


# t1-ahl-de-moivre (FAL-1005): every number is read back from the lines and the question, and
# the answer and each slip are worked out again with SymPy: a power by z**n, the least power by
# trying n = 1, 2, … on z**n itself, the roots by solving zⁿ = w, the polygon from its vertices,
# the identities by expanding (cos θ + i sin θ)ⁿ and (z ± 1/z)ⁿ symbolically, and the proof
# from its own six lines. Every name here starts DMV_ or dmv_.

DMV_P = "AHL1.14.de-moivre-powers#"
DMV_R = "AHL1.14.nth-roots#"
DMV_M = "AHL1.14.multiple-angle-identities#"
DMV_I = "AHL1.14.de-moivre-induction#"
DMV_T = "t1-ahl-de-moivre#"
DMV_SUPS = "⁰¹²³⁴⁵⁶⁷⁸⁹"
DMV_KINDS = {"real": "real", "purely imaginary": "imaginary", "a positive real number": "positive", "a negative real number": "negative"}
DMV_OTHER = {"real": "imaginary", "imaginary": "real", "positive": "negative", "negative": "positive"}
DMV_QUAD = {"first": 1, "second": 2, "third": 3, "fourth": 4}
DMV_TH = sp.Symbol("t", real=True)
DMV_BOTH = ("power-polar", "power-cartesian", "least-power", "nth-root", "all-roots", "roots-polygon")


def dmv_sup(n):
    return "" if n == 1 else "".join(DMV_SUPS[int(ch)] for ch in str(n))


def dmv_number(t):
    """A number written either way: polar (r, c, style) or Cartesian (z, None, None)."""
    if "cis(" in t or "e^(" in t:
        r, c, style = cpl_polar(t)
        return cpl_cis(r, c), c, style
    return cx_parse(t), None, None


def dmv_is(z, kind):
    z = sp.expand(z)
    a, b = sp.simplify(sp.re(z)), sp.simplify(sp.im(z))
    return {"real": b == 0, "imaginary": a == 0 and b != 0, "positive": b == 0 and a > 0, "negative": b == 0 and a < 0}[kind]


def dmv_least(z, kind, top=48):
    """The least n ≥ 1 with zⁿ of the kind, tried power by power, or 0."""
    w = sp.Integer(1)
    for n in range(1, top + 1):
        w = sp.expand(w * z)
        if dmv_is(w, kind):
            return n
    return 0


def dmv_style_of(asked):
    if "re^(iθ)" in asked:
        return "euler"
    if "r cis θ" in asked:
        return "cis"
    return None


def dmv_roots(w, n):
    """The n roots of zⁿ = w: their modulus and their principal arguments, least first."""
    rho = sp.simplify(sp.Abs(w) ** sp.Rational(1, n))
    phi = cpl_arg(w)
    args = sorted(cpl_principal((phi + 2 * k) / n) for k in range(n))
    for c in args:
        need(abs(complex(sp.N(cpl_cis(rho, c) ** n - w, 30))) < 1e-20, "a root doesn't solve the equation")
    return rho, phi, args


def dmv_list(items):
    return items[0] if len(items) == 1 else ", ".join(items[:-1]) + " or " + items[-1]


def dmv_try(f):
    """A slip's text, or None where its value isn't one surd per part (the game can't offer it)."""
    try:
        return f()
    except (Fail, TypeError):
        return None


def dmv_lead(cf, body):
    a = abs(cf)
    if body == "":
        return str(a)
    return ("" if a == 1 else str(a)) + body


def dmv_join(terms):
    """[(coefficient, unsigned text)] joined with signs, highest first unless it is negative."""
    terms = [t for t in terms if t[0] != 0]
    if terms[0][0] < 0:
        terms = terms[::-1]
    out = ""
    for i, (cf, body) in enumerate(terms):
        out += ("−" if cf < 0 else "") if i == 0 else (" − " if cf < 0 else " + ")
        out += body
    return out


def dmv_pow_text(fn, e, L):
    return "" if e == 0 else (f"{fn} {L}" if e == 1 else f"{fn}{dmv_sup(e)}{L}")


def dmv_poly(fn, n, L, coef=True, sign=True):
    """cos nθ or sin nθ as a polynomial in cos θ or sin θ, from (cos θ + i sin θ)ⁿ expanded
    with sp.binomial, the slip versions leaving out the binomial coefficients or i²'s sign."""
    C, S = sp.symbols("C S", real=True)
    tot = sp.expand(sum((sp.binomial(n, k) if coef else 1) * C ** (n - k) * S ** k * (sp.I ** k if sign else (sp.I if k % 2 else 1))
                        for k in range(n + 1)))
    part = sp.re(tot) if fn == "cos" else sp.im(tot)
    # Only even powers of the other function are left: replace them by Pythagoras.
    p = sp.expand(part.subs(S, sp.sqrt(1 - C ** 2))) if fn == "cos" else sp.expand(part.subs(C, sp.sqrt(1 - S ** 2)))
    x = C if fn == "cos" else S
    p = sp.Poly(p, x)
    terms = [(int(p.coeff_monomial(x ** e)), dmv_lead(int(p.coeff_monomial(x ** e)), dmv_pow_text(fn, e, L))) for e in range(n, -1, -1)]
    return dmv_join(terms), p.as_expr().subs(x, sp.cos(DMV_TH) if fn == "cos" else sp.sin(DMV_TH))


def dmv_reduce(fn, n, L, coef=True, divide=True, with_i=True):
    """cosⁿθ or sinⁿθ in multiple angles: (z ± 1/z)ⁿ expanded, each z^m paired with z^(−m)."""
    z = sp.Symbol("z")
    s, d = (1, 2) if fn == "cos" else (-1, 2 * sp.I if with_i else 2)
    tot = sum((sp.binomial(n, k) if coef else 1) * s ** k * z ** (n - 2 * k) for k in range(n + 1))
    tot = sp.expand(tot / (d ** n if divide else (d / 2) ** n))
    P = sp.Poly(sp.expand(tot * z ** n), z)
    a = {m: sp.expand(P.coeff_monomial(z ** (m + n))) for m in range(-n, n + 1)}
    kind = "sin" if fn == "sin" and n % 2 == 1 else "cos"
    co = {0: sp.nsimplify(a[0])}
    for m in range(1, n + 1):
        # a z^m + b z^(−m) = (a + b) cos mθ + i(a − b) sin mθ.
        co[m] = sp.nsimplify(a[m] + a[-m] if kind == "cos" else (sp.I * (a[m] - a[-m]) if with_i else a[m] - a[-m]))
    for v in co.values():
        need(v.is_rational, f"{fn}{n}: a coefficient {v} is not rational")
    den = sp.ilcm(*[sp.Rational(v).q for v in co.values()])
    terms = []
    for m in range(n, -1, -1):
        v = int(co[m] * den)
        if v:
            terms.append((v, dmv_lead(v, "" if m == 0 else f"{kind} {'' if m == 1 else m}{L}")))
    body = dmv_join(terms)
    return (body if den == 1 else f"({body})/{den}"), kind, co


def dmv_proof(L, kind):
    c = f"cos {L} + i sin {L}"
    step = f"= cos(k + 1){L} + i sin(k + 1){L}, {'by the compound-angle formulae, ' if kind == 'compound' else ''}so the statement is true for n = k + 1."
    four = (f"= (cos k{L} cos {L} − sin k{L} sin {L}) + i(sin k{L} cos {L} + cos k{L} sin {L})" if kind == "compound"
            else f"= cos(k{L} + {L}) + i sin(k{L} + {L}), multiplying the moduli and adding the arguments")
    return [f"When n = 1, both sides are {c}, so the statement is true for n = 1.",
            f"Assume ({c})^k = cos k{L} + i sin k{L} for some positive integer k.",
            f"Then ({c})^(k + 1) = (cos k{L} + i sin k{L})({c})", four, step,
            "It is true for n = 1, and if it is true for n = k it is true for n = k + 1, so by induction it is true for every positive integer n."]


def dmv_check(q):
    u, L, asked, angle = q["view"]["unknown"], q["lines"], q["asked"], q["view"]["angle"]
    # A GDC method is Paper 2; powers and roots are on both papers; identities and the proof Paper 1.
    need(q["paper"] == 2 if angle.startswith("gdc-") else q["paper"] in ((1, 2) if u in DMV_BOTH else (1,)), f"Paper {q['paper']}")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs = {}

    def slip(ref, text):
        if text is not None:
            wrongs.setdefault(ref, set()).add(text)

    if u in ("power-polar", "power-cartesian", "least-power"):
        need(len(L) == 1 and L[0].startswith("z = "), f"lines {L!r}")
        z, c0, style = dmv_number(L[0][4:])
        r, c = sp.simplify(sp.Abs(z)), cpl_arg(z)
        need(c0 is None or cpl_principal(c0) == c, "z's argument is not principal")
    if u == "power-polar":
        m = re.fullmatch(r"Write z([⁰¹²³⁴⁵⁶⁷⁸⁹]+) in the form (re\^\(iθ\)|r cis θ), where r > 0 and −π < θ ≤ π\.", asked)
        need(m is not None, f"asked {asked!r}")
        n, st = cx_sup(m.group(1)), CPL_FORM[m.group(2)]
        need(n >= 2, "a power below 2")
        P = sp.expand(z ** n)
        R, C = sp.simplify(sp.Abs(P)), cpl_arg(P)
        head = f"z{dmv_sup(n)} = "
        want = head + cpl_p(R, C, st)
        slip(DMV_P + "0", head + cpl_p(R, c, st))
        slip(DMV_P + "1", head + cpl_p(n * r, C, st))
        if n * c != C:
            slip(DMV_T + "12", head + cpl_p(R, n * c, st))
        if r != 1:
            slip(DMV_T + "13", head + cpl_p(r, C, st))
    elif u == "power-cartesian":
        m = re.fullmatch(r"Find z([⁰¹²³⁴⁵⁶⁷⁸⁹]+) in the form a \+ bi\.", asked)
        need(m is not None, f"asked {asked!r}")
        n = cx_sup(m.group(1))
        need(c0 is None, "z is not in Cartesian form")
        P = sp.expand(z ** n)
        R, C = sp.simplify(sp.Abs(P)), cpl_arg(P)
        head = f"z{dmv_sup(n)} = "
        want = head + cpl_c(P)
        slip(DMV_P + "0", dmv_try(lambda: head + cpl_c(cpl_cis(R, c))))
        slip(DMV_P + "1", dmv_try(lambda: head + cpl_c(cpl_cis(n * r, C))))
        slip(DMV_P + "2", dmv_try(lambda: head + cpl_c(sp.re(z) ** n + (sp.I * sp.im(z)) ** n)))
        if angle == "gdc-power":
            need(sp.re(P).is_integer and sp.im(P).is_integer, "a GDC power without whole parts")
    elif u == "least-power":
        m = re.fullmatch(r"Find the least positive integer n for which z\^n is (.+)\.", asked)
        need(m is not None and m.group(1) in DMV_KINDS, f"asked {asked!r}")
        kind = DMV_KINDS[m.group(1)]
        n = dmv_least(z, kind)
        need(n >= 2, f"the least n is {n}")
        want = f"n = {n}"
        if kind == "real":
            k = dmv_least(z, "positive")
            if k and k != n:
                slip(DMV_T + "14", f"n = {k}")
        k = dmv_least(z, DMV_OTHER[kind])
        if k and k != n:
            slip(DMV_T + "15", f"n = {k}")
        if c0 is None and cpl_quadrant(c) in (2, 3):
            w = sp.Abs(z) * sp.exp(sp.I * sp.atan(sp.im(z) / sp.re(z)))
            k = dmv_least(sp.expand(sp.expand_complex(w)), kind)
            if k and k != n:
                slip(DMV_T + "16", f"n = {k}")
        for o in q["choices"]:
            need(int(o["text"][4:]) >= 1, f"option {o['text']!r} is not a positive integer")
    elif u in ("nth-root", "all-roots", "roots-polygon"):
        m = re.fullmatch(r"z([⁰¹²³⁴⁵⁶⁷⁸⁹]+) = (.+)", L[0]) if len(L) == 1 else None
        need(m is not None, f"lines {L!r}")
        n = cx_sup(m.group(1))
        w, _, _ = dmv_number(m.group(2))
        rho, phi, args = dmv_roots(w, n)
        need(rho.is_integer, f"the roots' modulus {rho} is not whole")
        big = sp.Abs(w)
        mdiv = big / n if (big / n).is_integer and big / n != rho else None
        half = sorted((phi + k) / n for k in range(n))
        if u == "nth-root":
            m = re.fullmatch(r"(Find the root of this equation with the least positive argument\.|Find the root of this equation with the greatest argument\.|"
                             r"One root of this equation lies in the (first|second|third|fourth) quadrant\. Find this root\.) "
                             r"Give it in the form (re\^\(iθ\)|r cis θ), where r > 0 and −π < θ ≤ π\.", asked)
            need(m is not None, f"asked {asked!r}")
            st = CPL_FORM[m.group(3)]

            def pick(cs):
                if "least positive" in asked:
                    pos = [x for x in cs if x > 0]
                    return pos[0] if pos else None
                if "greatest" in asked:
                    return cs[-1]
                inq = [x for x in cs if cpl_quadrant(x) == DMV_QUAD[m.group(2)]]
                return inq[0] if len(inq) == 1 else None
            C = pick(args)
            need(C is not None, "no root fits the question, or two do")
            want = "z = " + cpl_p(rho, C, st)
            if phi / n != C:
                slip(DMV_R + "0", "z = " + cpl_p(rho, phi / n, st))
            if mdiv is not None:
                slip(DMV_R + "1", "z = " + cpl_p(mdiv, C, st))
            h = pick(half)
            if h is not None and h != C:
                slip(DMV_T + "17", "z = " + cpl_p(rho, h, st))
        elif u == "all-roots":
            m = re.fullmatch(r"Find all the roots of this equation, giving them in the form (re\^\(iθ\), where r > 0 and −π < θ ≤ π|r cis θ, where r > 0 and −π < θ ≤ π|a \+ bi)\.", asked)
            need(m is not None, f"asked {asked!r}")
            st = dmv_style_of(m.group(1))

            def text(R, cs):
                return "z = " + dmv_list([cpl_p(R, x, st) if st else cpl_c(cpl_cis(R, x)) for x in cs])
            want = text(rho, args)
            slip(DMV_R + "0", "z = " + (cpl_p(rho, phi / n, st) if st else cpl_c(cpl_cis(rho, phi / n))) + " only")
            if mdiv is not None:
                slip(DMV_R + "1", dmv_try(lambda: text(mdiv, args)))
            if st:
                slip(DMV_R + "2", "z = " + dmv_list([cpl_p(rho, phi / n + 2 * k, st) for k in range(n)]))
            slip(DMV_T + "17", dmv_try(lambda: text(rho, half)))
        else:
            need(n in (3, 4, 6), f"a polygon with {n} sides")
            m = re.fullmatch(r"The roots of this equation are the vertices of a regular polygon on the Argand diagram\. Find the exact (length of each side|area|perimeter) of the polygon\.", asked)
            need(m is not None, f"asked {asked!r}")
            what = {"length of each side": "side", "area": "area", "perimeter": "perimeter"}[m.group(1)]
            head = {"side": "Side = ", "area": "Area = ", "perimeter": "Perimeter = "}[what]
            pts = [cpl_cis(rho, x) for x in args]

            def measure(ps):
                side = sp.sqrt(sp.simplify(sp.expand(sp.Abs(ps[1] - ps[0]) ** 2)))
                if what == "side":
                    return side
                if what == "perimeter":
                    return n * side
                # The shoelace formula over the vertices in order of argument.
                return sp.Abs(sp.nsimplify(sp.simplify(sum(sp.re(ps[i]) * sp.im(ps[(i + 1) % n]) - sp.re(ps[(i + 1) % n]) * sp.im(ps[i]) for i in range(n)) / 2)))
            v = sp.nsimplify(sp.simplify(measure(pts)))
            want = head + cpl_s(v)
            if mdiv is not None:
                slip(DMV_R + "1", head + cpl_s(sp.nsimplify(sp.simplify(measure([cpl_cis(mdiv, x) for x in args])))))
            if n != 6:
                # The radius taken as the side: the polygon with side ρ.
                rad_side = {"side": rho, "perimeter": n * rho, "area": (sp.sqrt(3) / 4 if n == 3 else 1) * rho ** 2}[what]
                slip(DMV_T + "18", head + cpl_s(rad_side))
            if what == "area":
                slip(DMV_T + "19", head + cpl_s(2 * v))
    elif u == "multiple-angle":
        m = re.fullmatch(r"Express (cos|sin) (\d)(θ|α|x) as a polynomial in (cos|sin) (θ|α|x)\.", asked)
        need(m is not None and m.group(1) == m.group(4) and m.group(3) == m.group(5), f"asked {asked!r}")
        fn, n, Lt = m.group(1), int(m.group(2)), m.group(3)
        lhs = f"{fn} {n}{Lt} = "
        txt, p = dmv_poly(fn, n, Lt)
        th = DMV_TH
        val = (sp.cos(n * th) if fn == "cos" else sp.sin(n * th)) - p
        need(all(abs(float(val.subs(th, t0))) < 1e-9 for t0 in (0.3, 1.1, 2.7)), "the identity is false")
        want = lhs + txt
        slip(DMV_M + "0", lhs + dmv_poly(fn, n, Lt, coef=False)[0])
        slip(DMV_M + "2", lhs + dmv_poly(fn, n, Lt, sign=False)[0])
    elif u == "power-reduction":
        m = re.fullmatch(r"Use z = cos (θ|α|x) \+ i sin \1 to express (cos|sin)([⁰¹²³⁴⁵⁶⁷⁸⁹]+)\1 in terms of (.+)\.", asked)
        need(m is not None, f"asked {asked!r}")
        Lt, fn, n = m.group(1), m.group(2), cx_sup(m.group(3))
        lhs = f"{fn}{dmv_sup(n)}{Lt} = "
        txt, kind, co = dmv_reduce(fn, n, Lt)
        th = DMV_TH
        f = sp.cos if kind == "cos" else sp.sin
        val = (sp.cos(th) if fn == "cos" else sp.sin(th)) ** n - sum(co[k] * (f(k * th) if k else 1) for k in co)
        need(all(abs(float(val.subs(th, t0))) < 1e-9 for t0 in (0.3, 1.1, 2.7)), "the identity is false")
        names = [("a constant" if k == 0 else f"{kind} {'' if k == 1 else k}{Lt}") for k in sorted(co, reverse=True) if co[k] != 0]
        need(m.group(4) == (names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]), f"the terms asked for: {m.group(4)!r}")
        want = lhs + txt
        slip(DMV_M + "0", lhs + dmv_reduce(fn, n, Lt, coef=False)[0])
        slip(DMV_T + "20", lhs + dmv_reduce(fn, n, Lt, divide=False)[0])
        if fn == "sin" and n % 2 == 1:
            slip(DMV_M + "1", lhs + dmv_reduce(fn, n, Lt, with_i=False)[0])
    elif u in ("induction-gap", "induction-flaw"):
        need(len(L) == 7, f"{len(L)} lines")
        m = re.fullmatch(r"Prove by induction that \(cos (θ|α|x) \+ i sin \1\)\^n = cos n\1 \+ i sin n\1 for every positive integer n\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        Lt = m.group(1)
        kind = {"induction-compound-angle": "compound", "induction-polar-product": "polar"}[angle]
        right = dmv_proof(Lt, kind)
        shown = []
        for i, line in enumerate(L[1:]):
            need(line.startswith(f"Line {i + 1}: "), f"can't read {line!r}")
            shown.append(line[len(f"Line {i + 1}: "):])
        c = f"cos {Lt} + i sin {Lt}"
        if u == "induction-gap":
            need(asked == "One line of this proof is missing. Which line completes the proof?", f"asked {asked!r}")
            gaps = [i for i, x in enumerate(shown) if x == "(missing)"]
            need(len(gaps) == 1, "not exactly one line missing")
            g = gaps[0]
            need(all(shown[i] == right[i] for i in range(6) if i != g), "a shown line is not the proof's")
            want = right[g]
            if g == 1:
                slip(DMV_I + "0", f"Assume ({c})^(k + 1) = cos(k + 1){Lt} + i sin(k + 1){Lt} for some positive integer k.")
            if g == 3 and kind == "compound":
                slip(DMV_I + "1", f"= (cos k{Lt} cos {Lt} + sin k{Lt} sin {Lt}) + i(sin k{Lt} cos {Lt} + cos k{Lt} sin {Lt})")
            if g == 5:
                slip(DMV_I + "2", "If it is true for n = k it is true for n = k + 1, so by induction it is true for every positive integer n.")
        else:
            need(asked == "One line of this proof is wrong. Which is the first incorrect line?", f"asked {asked!r}")
            bad = [i for i in range(6) if shown[i] != right[i]]
            need(len(bad) == 1, f"{len(bad)} lines differ from the proof")
            need(bad[0] != 0, "the base case is spoiled")
            want = f"Line {bad[0] + 1}"
            for o in q["choices"]:
                need(re.fullmatch(r"Line [1-6]", o["text"]) is not None, f"option {o['text']!r}")
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, None)
    return None, None


SITUATION_CHECKS["de-moivre"] = dmv_check


# t1-ahl-conjugate-roots (FAL-1005): the polynomial and its root are read from the lines, the
# roots and coefficients are worked out again with SymPy (sp.solve, sp.Poly), and each slip from
# its own rule. Names start CJR_ or cjr_.

CJR_AQ = "AHL1.14.complex-quadratic#"
CJR_AC = "AHL1.14.conjugate-root-polynomial#"
CJR_TC = "t1-ahl-conjugate-roots#"
CJR_REFS = {
    "sqrt-neg": CJR_AQ + "0", "half-only": CJR_AQ + "1", "sum-sign": CJR_AQ + "2", "real-sign": CJR_AC + "0", "factor-sign": CJR_AC + "1",
    "h-sign": CJR_TC + "5", "not-halved": CJR_TC + "6", "i2-product": CJR_TC + "7", "half-sum": CJR_TC + "8", "negate": CJR_TC + "9",
    "cubic-sum-sign": CJR_TC + "10", "product-sign": CJR_TC + "11", "vieta-signs": CJR_TC + "12",
}
CJR_Z = sp.Symbol("z")


def cjr_poly(t):
    """The coefficients of a polynomial in z from its text, highest power first: "z³ − 5z² + 9z − 5"."""
    s = t.replace("−", "-").replace("³", "**3").replace("²", "**2")
    s = re.sub(r"(\d)z", r"\1*z", s)
    need(re.fullmatch(r"[-+*/ 0-9z]+", s) is not None, f"can't read the polynomial {t!r}")
    return [sp.Integer(c) for c in sp.Poly(sp.sympify(s, locals={"z": CJR_Z}), CJR_Z).all_coeffs()]


def cjr_text(coeffs):
    """A polynomial in z as the game writes it, from its coefficients."""
    n = len(coeffs) - 1
    out = ""
    for i, c in enumerate(coeffs):
        c = sp.Integer(c)
        p = n - i
        if c == 0:
            continue
        mag = abs(c)
        body = ("" if (mag == 1 and p > 0) else str(mag)) + ("" if p == 0 else "z" + {1: "", 2: "²", 3: "³"}[p])
        out += ("−" if c < 0 else "") + body if out == "" else (" − " if c < 0 else " + ") + body
    return out


def cjr_pm(h, k):
    return f"{cx_q(h)} ± {cx_iterm(k)}"


def cjr_check(q):
    t, u, L, asked = q["view"]["type"], q["view"]["unknown"], q["lines"], q["asked"]
    gdc = q["view"]["angle"] == "gdc-solver"
    need(q["paper"] == 2 if gdc else q["paper"] in (1, 2), f"Paper {q['paper']}")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs = {}

    def slip(key, text):
        wrongs.setdefault(CJR_REFS[key], set()).add(text)

    I = sp.I
    if u == "solve-quadratic":
        need(asked == "Solve the equation, giving the roots in the form h ± ki." and len(L) == 1 and L[0].endswith(" = 0"), f"lines {L!r}")
        c = cjr_poly(L[0][:-4])
        need(len(c) == 3 and c[0] == 1, "not a monic quadratic")
        roots = sp.solve(sp.Poly(c, CJR_Z).as_expr(), CJR_Z)
        need(len(roots) == 2 and all(sp.im(r) != 0 for r in roots), "the roots aren't a complex pair")
        h, k = sp.re(roots[0]), abs(sp.im(roots[0]))
        need(h.is_integer and k.is_integer and h != 0, "the roots aren't whole")
        want = "z = " + cjr_pm(h, k)
        slip("sqrt-neg", f"z = {cx_q(h - k)} or z = {cx_q(h + k)}")
        slip("half-only", "z = " + cjr_pm(-c[1], k))
        slip("h-sign", "z = " + cjr_pm(-h, k))
        slip("not-halved", "z = " + cjr_pm(h, 2 * k))
    elif u == "quadratic-from-root":
        m = re.fullmatch(r"z = (.+) is a root of z² \+ pz \+ q = 0, where p and q are real\.", L[0])
        need(m is not None and asked == "Find the values of p and q, and write down the equation.", f"lines {L!r}")
        z0 = cx_parse(m.group(1))
        h, k = sp.re(z0), abs(sp.im(z0))
        need(k != 0, "the root is real")
        P = sp.Poly(sp.expand((CJR_Z - z0) * (CJR_Z - sp.conjugate(z0))), CJR_Z).all_coeffs()
        want = cjr_text(P) + " = 0"
        slip("sum-sign", cjr_text([1, -P[1], P[2]]) + " = 0")
        slip("i2-product", cjr_text([1, P[1], h ** 2 - k ** 2]) + " = 0")
        slip("half-sum", cjr_text([1, -h, P[2]]) + " = 0")
    elif u == "other-root":
        need(asked == "Write down another root of the equation.", f"asked {asked!r}")
        m = re.fullmatch(r"One root of (.+) = 0 is (.+)\.", L[0])
        if m:
            c = cjr_poly(m.group(1))
            z0 = cx_parse(m.group(2))
            need(sp.expand(sp.Poly(c, CJR_Z).as_expr().subs(CJR_Z, z0)) == 0, "the root given is not a root")
        else:
            m = re.fullmatch(r"A cubic equation with real coefficients has a root (.+)\.", L[0])
            need(m is not None, f"can't read {L[0]!r}")
            z0 = cx_parse(m.group(1))
        want = "z = " + cx_fmt(sp.conjugate(z0))
        h, b = sp.re(z0), sp.im(z0)
        slip("real-sign", "z = " + cx_fmt(-h + b * I))
        slip("negate", "z = " + cx_fmt(-z0))
    elif u in ("real-root", "cubic-coefficients"):
        if u == "real-root":
            need(asked == "Find the real root of the equation." and len(L) == 2 and L[0].endswith(" = 0"), f"lines {L!r}")
            c = cjr_poly(L[0][:-4])
            m = re.fullmatch(r"One root of this equation is (.+)\.", L[1])
            need(m is not None and len(c) == 4 and c[0] == 1, f"can't read {L!r}")
            z0 = cx_parse(m.group(1))
            Pz = sp.Poly(c, CJR_Z).as_expr()
            need(sp.expand(Pz.subs(CJR_Z, z0)) == 0, "the root given is not a root")
            real = [r for r in sp.solve(Pz, CJR_Z) if sp.im(r) == 0]
            need(len(real) == 1 and real[0].is_integer, "the cubic has no single whole real root")
            tv = real[0]
            a, d = c[1], c[3]
            h, k = sp.re(z0), abs(sp.im(z0))
            mm = h ** 2 + k ** 2
            want = "z = " + cx_q(tv)
            slip("factor-sign", "z = " + cx_q(2 * h - a))
            slip("cubic-sum-sign", "z = " + cx_q(a - 2 * h))
            slip("product-sign", "z = " + cx_q(sp.Rational(d, mm)))
        else:
            m = re.fullmatch(r"z³ \+ az² \+ bz \+ d = 0, where a, b and d are real, has roots (.+) and (−?\d+)\.", L[0])
            need(m is not None and asked == "Find the values of a, b and d.", f"lines {L!r}")
            z0, tv = cx_parse(m.group(1)), sp.Integer(m.group(2).replace("−", "-"))
            c = sp.Poly(sp.expand((CJR_Z - z0) * (CJR_Z - sp.conjugate(z0)) * (CJR_Z - tv)), CJR_Z).all_coeffs()
            txt = lambda a, b, d: f"a = {cx_q(a)}, b = {cx_q(b)}, d = {cx_q(d)}"
            want = txt(c[1], c[2], c[3])
            h, k = sp.re(z0), abs(sp.im(z0))
            fs = sp.Poly(sp.expand((CJR_Z ** 2 + 2 * h * CJR_Z + h ** 2 + k ** 2) * (CJR_Z - tv)), CJR_Z).all_coeffs()
            slip("factor-sign", txt(fs[1], fs[2], fs[3]))
            slip("vieta-signs", txt(-c[1], c[2], -c[3]))
            i2 = sp.Poly(sp.expand((CJR_Z ** 2 - 2 * h * CJR_Z + h ** 2 - k ** 2) * (CJR_Z - tv)), CJR_Z).all_coeffs()
            slip("i2-product", txt(i2[1], i2[2], i2[3]))
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, None)
    return None, None


SITUATION_CHECKS["conjugate-roots"] = cjr_check


# t1-ai-complex-polar (FAL-1005): the exact unknowns go through cpl_check with the AI refs; the GDC
# conversions, powers, the least power, the image of a point and the sum of two sinusoids are
# worked out here, the decimals with mpmath to 30 digits. Names start AIP_ or aip_.

AIP_SUP = {c: str(i) for i, c in enumerate("⁰¹²³⁴⁵⁶⁷⁸⁹")}


def aip_s(x):
    """3 s.f., as the game writes it, for a SymPy or an mpmath number."""
    return gc_s(sp.Float(mpmath.nstr(x, 25), 30) if isinstance(x, mpmath.mpf) else x)


def aip_dec(t):
    return sp.Rational(t.replace("−", "-"))


def aip_dpolar(r, t, style):
    return f"{aip_s(r)}e^({aip_s(t)}i)" if style == "euler" else f"{aip_s(r)} cis({aip_s(t)})"


def aip_dcart(x, y):
    return aip_s(x) + (" − " if y < 0 else " + ") + aip_s(abs(y)) + "i"


def aip_wave(A, fn, w, B):
    tail = "" if B == 0 else (" − " if B < 0 else " + ") + aip_s(abs(B))
    return f"{aip_s(A)} {fn}({w}t{tail})"


def aip_least(c, mode):
    for n in range(1, 25):
        v = sp.Rational(c) * n
        if mode == "real" and v.q == 1:
            return n
        if mode == "imaginary" and (v + sp.Rational(1, 2)).q == 1:
            return n
        if mode == "positive" and v.q == 1 and v.p % 2 == 0:
            return n
        if mode == "negative" and v.q == 1 and v.p % 2 == 1:
            return n
    return 0


def aip_check(q):
    t, u, rep, L, asked = q["view"]["type"], q["view"]["unknown"], q["view"]["rep"], q["lines"], q["asked"]
    # A conversion asked to 3 s.f. has whole parts or a phase in radians for the GDC; any other
    # is exact, as on AA HL, whatever method the view shows first.
    gdc = "to 3 significant figures" in asked
    if u in ("to-polar", "to-cartesian") and not gdc or u in ("polar-product", "product-cartesian", "describe-map"):
        return cpl_check(q)
    refs = CPL_REFS[t]
    need(q["paper"] == 2, f"Paper {q['paper']}")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs = {}

    def slip(key, text):
        if key in refs:
            wrongs.setdefault(refs[key], set()).add(text)

    I = sp.I
    if u == "to-polar":
        m = re.fullmatch(r"Write z in the form (re\^\(iθ\)|r cis θ), where r > 0 and −π < θ ≤ π, giving r and θ to 3 significant figures\.", asked)
        need(m is not None, f"asked {asked!r}")
        style = CPL_FORM[m.group(1)]
        if rep == "graph":
            m2 = re.fullmatch(r"The point A\((−?\d+), (−?\d+)\) on the Argand diagram represents the complex number z\.", L[0])
            need(m2 is not None, f"can't read {L[0]!r}")
            z = cx_parse(m2.group(1)) + I * cx_parse(m2.group(2))
            p = cx_point(q, "A")
            need(abs(p["x"] - float(sp.re(z))) < 1e-9 and abs(p["y"] - float(sp.im(z))) < 1e-9, "A is drawn in the wrong place")
        else:
            z = cx_read(L[0], "z")
        a, b = (sp.Integer(v) for v in cx_parts(z))
        need(a != 0 and b != 0 and abs(a) != abs(b), "the point is on an axis or a 45° line")
        r, th = mpmath.sqrt(a ** 2 + b ** 2), mpmath.atan2(b, a)
        want = "z = " + aip_dpolar(r, th, style)
        slip("arg-sign", "z = " + aip_dpolar(r, -th, style))
        slip("no-root", "z = " + aip_dpolar(a ** 2 + b ** 2, th, style))
        if a < 0:
            slip("quadrant", "z = " + aip_dpolar(r, mpmath.atan(mpmath.mpf(b) / a), style))
        slip("mod-add", "z = " + aip_dpolar(abs(a) + abs(b), th, style))
    elif u == "to-cartesian":
        need(asked == "Write z in the form a + bi, giving a and b to 3 significant figures.", f"asked {asked!r}")
        m = re.fullmatch(r"z = (\d+)(?:e\^\((−?[\d.]+)i\)| cis\((−?[\d.]+)\))", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        r, th = sp.Integer(m.group(1)), aip_dec(m.group(2) or m.group(3))
        x, y = r * mpmath.cos(th), r * mpmath.sin(th)
        want = "z = " + aip_dcart(x, y)
        slip("degree-mode", "z = " + aip_dcart(r * mpmath.cos(mpmath.radians(th)), r * mpmath.sin(mpmath.radians(th))))
        slip("trig-swap", "z = " + aip_dcart(y, x))
    elif u in ("power-polar", "power-cartesian"):
        m = re.fullmatch(r"Find z([⁰¹²³⁴⁵⁶⁷⁸⁹]+) in the form (re\^\(iθ\)|r cis θ|a \+ bi)(, where r > 0 and −π < θ ≤ π)?\.", asked)
        need(m is not None, f"asked {asked!r}")
        n = int("".join(AIP_SUP[ch] for ch in m.group(1)))
        name = "z" + m.group(1)
        head = name + " = "
        if u == "power-polar":
            need(m.group(2) != "a + bi", "power-polar asks for a polar form")
            r, c, style = cpl_read_polar(L[0], "z")
            need(CPL_FORM[m.group(2)] == style, "the form asked is not the form given")
            need(3 <= n <= 6, f"power {n}")
            R, raw = r ** n, c * n
            C = cpl_principal(raw)
            need(C == cpl_arg(sp.expand(cpl_cis(r, c) ** n)), "De Moivre's argument is off")
            want = head + cpl_p(R, C, style)
            slip("mod-unraised", head + cpl_p(r, C, style))
            pw = f"({cpl_pi(c)}){m.group(1)}"
            slip("arg-raised", head + cpl_s(R) + (f"e^({pw} i)" if style == "euler" else f" cis({pw})"))
            if raw != C:
                slip("unreduced", head + cpl_p(R, raw, style))
        else:
            need(m.group(2) == "a + bi", "power-cartesian asks for a + bi")
            z = cx_read(L[0], "z")
            p = sp.expand(z ** n)
            want = head + cpl_c(p)
            r, c = sp.simplify(sp.Abs(z)), cpl_arg(z)
            slip("mod-unraised", head + cpl_c(cpl_cis(r, cpl_principal(c * n))))
            a, b = sp.re(z), sp.im(z)
            pp = sp.expand(a ** n + (b * I) ** n)
            try:
                slip("parts-power", head + cpl_c(pp))
            except Fail:
                pass
    elif u == "least-power":
        r, c, style = cpl_read_polar(L[0], "z")
        mode = {"real": "real", "purely imaginary": "imaginary", "a positive real number": "positive", "a negative real number": "negative"}
        m = re.fullmatch(r"Find the least positive integer n for which z\^n is (.+)\.", asked)
        need(m is not None and m.group(1) in mode, f"asked {asked!r}")
        md = mode[m.group(1)]
        n = aip_least(c, md)
        need(n > 1, "n is 1")
        zn = sp.expand(cpl_cis(r, c) ** n)
        need({"real": sp.im(zn) == 0, "imaginary": sp.re(zn) == 0, "positive": sp.im(zn) == 0 and zn > 0,
              "negative": sp.im(zn) == 0 and zn < 0}[md], "z^n is not what was asked")
        want = f"n = {n}"
        if md == "real":
            slip("pos-only", f"n = {aip_least(c, 'positive')}")
        other = {"real": "imaginary", "imaginary": "real", "positive": "negative", "negative": "positive"}[md]
        if aip_least(c, other) > 0:
            slip("kind-swap", f"n = {aip_least(c, other)}")
    elif u == "multiply-point":
        need(rep == "graph" and L == [CX_READ_A], f"lines {L!r}")
        z = cx_grid_point(q, "A")
        m = re.fullmatch(r"The point A on the Argand diagram represents the complex number z, and w = (.+)\. Find the complex number that represents the image of A under the map z ↦ wz, in the form a \+ bi\.", asked)
        need(m is not None, f"asked {asked!r}")
        w = cx_parse(m.group(1))
        head = "w × z = "
        want = head + cpl_c(w * z)
        if w == I:
            slip("i-reflect", head + cpl_c(sp.im(z) + sp.re(z) * I))
        if sp.im(w) != 0:
            slip("clockwise", head + cpl_c(sp.conjugate(w) * z))
            if sp.simplify(sp.Abs(w) - 1) != 0:
                slip("rotation-only", head + cpl_c(sp.expand(w / sp.Abs(w) * z)))
    elif u == "add-sinusoids":
        m = re.fullmatch(r"(V|y|I)₁ = (\d) (cos|sin)\((\d)t(?: ([+−]) ([\d.]+))?\) and (V|y|I)₂ = (\d) (cos|sin)\((\d)t(?: ([+−]) ([\d.]+))?\), where t is the time in seconds\.", L[0])
        need(m is not None, f"can't read {L[0]!r}")
        Lt, fn, w = m.group(1), m.group(3), int(m.group(4))
        need((m.group(7), m.group(9), int(m.group(10))) == (Lt, fn, w), "the two waves differ in letter, function or frequency")
        a1, a2 = int(m.group(2)), int(m.group(8))
        p1 = aip_dec(m.group(6)) * (-1 if m.group(5) == "−" else 1) if m.group(6) else sp.Integer(0)
        p2 = aip_dec(m.group(12)) * (-1 if m.group(11) == "−" else 1) if m.group(12) else sp.Integer(0)
        need(asked == f"Use complex numbers to write {Lt}₁ + {Lt}₂ in the form A {fn}({w}t + B), where A > 0 and −π < B ≤ π, giving A and B to 3 significant figures.", f"asked {asked!r}")
        zs = a1 * mpmath.expj(p1) + a2 * mpmath.expj(p2)
        A, B = abs(zs), mpmath.arg(zs)
        # The sum really is A fn(wt + B): checked at a few times.
        f = mpmath.cos if fn == "cos" else mpmath.sin
        for tt in (0, 0.3, 1.1):
            need(abs(a1 * f(w * tt + p1) + a2 * f(w * tt + p2) - A * f(w * tt + B)) < 1e-9, "the sum is not one sinusoid")
        head = f"{Lt}₁ + {Lt}₂ = "
        want = head + aip_wave(A, fn, w, B)
        slip("amp-sum", head + aip_wave(a1 + a2, fn, w, B))
        slip("phase-avg", head + aip_wave(A, fn, w, (p1 + p2) / 2))
        zd = a1 * mpmath.expj(mpmath.radians(p1)) + a2 * mpmath.expj(mpmath.radians(p2))
        slip("phase-degrees", head + aip_wave(abs(zd), fn, w, mpmath.degrees(mpmath.arg(zd))))
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, None)
    return None, None


SITUATION_CHECKS["complex-polar-ai"] = aip_check
# ── end complex-polar ──


# ── R9 (FAL-1007): AA HL rational, odd/even and inverse functions, AI HL composites. Each type's section goes after its own marker. ──

# R9-RATIONAL: fn-ahl-rational-quadratic (rational-quadratic), prefix R9RQ_ / r9rq_

# ── rational-quadratic (fn-ahl-rational-quadratic, FAL-1007) ─────────────────
# The checker's own copy of the situation's clean limits; the engine's is in
# game/engine/situations/rational_quadratic.gd and rational_quadratic_views.gd. Every function is
# read back from the question's first line (never its `given`), and every asymptote, intercept,
# constant and range is worked out again with SymPy: zeros by exact roots, the oblique asymptote by
# polynomial division, a range from the turning points, f′(x) = 0. Each slip is rebuilt from its
# description in the catalogue. A pick-the-graph card is drawn again from the one mistake it names.

R9RQ_VA = "AHL2.13.vertical-asymptotes#"
R9RQ_HA = "AHL2.13.horizontal-asymptote#"
R9RQ_OA = "AHL2.13.oblique-asymptote#"
R9RQ_RT = "AHL2.13.range-turning-points#"
R9RQ_SK = "AHL2.13.sketch#"
R9RQ_T = "fn-ahl-rational-quadratic#"
R9RQ_FRAC_MAX = 12          # a simple fraction's denominator, at most
R9RQ_PLOT = 6               # features stay this far inside the window
R9RQ_WIN = (-8, 8, -8, 8)
R9RQ_K = sp.Symbol("k")
R9RQ_NUM = r"−?\d+(?:\.\d+)?(?:/\d+)?"


def r9rq_poly(text, k=False):
    """A polynomial the way the game writes it ('2x² − x + 5', 'x² + kx − 6') as SymPy in x (and k)."""
    need(not re.search(r"(?<![A-Za-z])-", text), f"a hyphen for a minus in {text!r}")
    need(re.fullmatch(r"[0-9xk²/ +−]+", text) is not None, f"can't read the polynomial {text!r}")
    need(k or "k" not in text, f"a letter k in {text!r}")
    s = text.replace("−", "-").replace("²", "**2")
    s = re.sub(r"(\d)([xk])", r"\1*\2", s).replace("kx", "k*x")
    return sp.expand(sp.sympify(s, locals={"x": X, "k": R9RQ_K}))


def r9rq_t(v):
    """An exact number as the game writes it: 3, −2, −7/2."""
    v = sp.Rational(v)
    body = str(abs(v.p)) if v.q == 1 else f"{abs(v.p)}/{v.q}"
    return ("−" if v < 0 else "") + body


def r9rq_v(v):
    """A value as an answer writes it: exact when rational, else to 3 s.f."""
    v = sp.nsimplify(v) if isinstance(v, sp.Rational) else v
    return r9rq_t(v) if v.is_Rational else gc_s(sp.N(v, 40))


def r9rq_w(text, x):
    """A working value: exact, or to 6 s.f. as a GDC shows it, agrees with x."""
    t = sp.Rational(text.replace("−", "-"))
    v = sp.N(x, 40)
    if v == 0:
        return t == 0
    e = sp.floor(sp.log(abs(v), 10))
    return abs(t - v) <= sp.Integer(10) ** (e - 5) * sp.Rational(6, 10)


def r9rq_lin(m, c):
    """mx + c as the game writes it: '2x + 1', '−x', 'x − 3'."""
    m, c = sp.Rational(m), sp.Rational(c)
    head = "x" if m == 1 else ("−x" if m == -1 else r9rq_t(m) + "x")
    if c == 0:
        return head
    return head + (" − " if c < 0 else " + ") + r9rq_t(abs(c))


def r9rq_xs(xs):
    return " and ".join("x = " + r9rq_t(x) for x in sorted(xs))


def r9rq_pt(x, y):
    return f"({r9rq_t(x)}, {r9rq_t(y)})"


def r9rq_between(lo, hi, strict=False):
    r = "<" if strict else "≤"
    return f"{r9rq_v(lo)} {r} f(x) {r} {r9rq_v(hi)}"


def r9rq_outside(lo, hi, strict=False):
    return f"f(x) {'<' if strict else '≤'} {r9rq_v(lo)} or f(x) {'>' if strict else '≥'} {r9rq_v(hi)}"


def r9rq_read(q):
    """f from the first line: (N, D, form, has_k)."""
    m = re.fullmatch(r"f\(x\) = \((.+?)\)/\((.+?)\)(, where k is a constant\.)?", q["lines"][0])
    need(m is not None, f"can't read f in {q['lines'][0]!r}")
    has_k = m.group(3) is not None
    N, D = r9rq_poly(m.group(1), has_k), r9rq_poly(m.group(2), has_k)
    dn, dd = sp.degree(N, X), sp.degree(D, X)
    need((dn, dd) in ((1, 2), (2, 1)), f"f is not a linear over a quadratic or a quadratic over a linear: {q['lines'][0]!r}")
    need(sp.Poly(D, X).LC() == 1, "the denominator is not monic")
    return N, D, "lq" if dn == 1 else "ql", has_k


def r9rq_clean(q, N, D, form):
    """The situation's clean limits, the checker's own copy."""
    need(sp.gcd(N, D).is_number, f"the numerator and denominator share a factor: {N}, {D}")
    if form == "lq":
        a, b = sp.Poly(N, X).all_coeffs()
        _, p, qq = sp.Poly(D, X).all_coeffs()
        need(a != 0 and b != 0 and abs(a) <= 3 and abs(b) <= 8 and sp.igcd(a, b) == 1, f"the numerator {N} is out of range")
        need(qq != 0 and (b / qq).q <= R9RQ_FRAC_MAX, "the y-intercept is not a simple fraction")
        zs = sorted(sp.Poly(D, X).real_roots())
        need(all(z.is_integer and z != 0 and abs(z) <= 5 for z in zs), f"the denominator's zeros {zs} are not whole numbers from −5 to 5")
        if len(zs) == 2:
            need(zs[0] != -zs[1], "the denominator's zeros are opposite numbers")
        if not zs:
            h = p / 2
            s2 = qq - h**2
            need(h.is_integer and abs(h) <= 3 and sp.sqrt(s2).is_integer and 1 <= sp.sqrt(s2) <= 4, f"{D} is not (x + h)² + s² for whole h and s")
    else:
        m, b, c = sp.Poly(N, X).all_coeffs()
        e = D.subs(X, 0)
        need(m in (1, 2, 3, -1, -2) and e != 0 and abs(e) <= 5, f"m or e out of range in {N}, {D}")
        k, R = r9rq_div(N, D)
        need(k != 0 and b != 0 and b + m * e != 0 and c != 0 and R != 0, "k, b, b + me, c and the remainder must all be nonzero")
        need(c / e != m, "the y-intercept is the leading coefficient")
        need(abs(b) <= 20 and abs(c) <= 40, "the coefficients are too large")


def r9rq_div(N, D):
    """A quadratic over x + e divided: (the quotient's constant k, the remainder R)."""
    quo, rem = sp.div(N, D, X)
    return sp.Poly(quo, X).all_coeffs()[-1], rem


def r9rq_steps(q, method, pattern, values):
    """In the worked solution by `method`, a step matches pattern and its numbers are the values."""
    for sol in q["solutions"]:
        if sol["angle"] != method:
            continue
        for st in sol["steps"]:
            mt = re.search(pattern, st)
            if mt:
                for g, x in zip(mt.groups(), values):
                    need(r9rq_w(g, x), f"{method}: {g} in {st!r} is not {sp.N(x, 7)}")
                return
        need(False, f"{method}: no step like {pattern!r}")


def r9rq_step_has(q, method, text):
    for sol in q["solutions"]:
        if sol["angle"] == method:
            need(any(text in st for st in sol["steps"]), f"{method}: no step says {text!r}")


def r9rq_check(q):
    u, L, asked, rep = q["view"]["unknown"], q["lines"], q["asked"], q["view"]["rep"]
    texts = [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]
    for tx in texts:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    if q["paper"] == 1:
        need(not any(sol["angle"].startswith("gdc-") for sol in q["solutions"]), "a GDC method on Paper 1")
    N, D, form, has_k = r9rq_read(q)
    if u == "denominator-from-asymptote":
        return r9rq_constant(q, N, D, form)
    if u == "coefficient-from-oblique":
        return r9rq_coefficient(q, N, D)
    need(not has_k, "a constant k where none is asked for")
    r9rq_clean(q, N, D, form)
    f = N / D
    wrongs = {}
    want = None
    if form == "lq":
        a, b = sp.Poly(N, X).all_coeffs()
        _, p, qq = sp.Poly(D, X).all_coeffs()
        zs = sorted(sp.Poly(D, X).real_roots())
        z = -b / a
    else:
        m, b, c = sp.Poly(N, X).all_coeffs()
        e = D.subs(X, 0)
        k, Rm = r9rq_div(N, D)
    if u == "vertical-asymptotes-lq":
        need(form == "lq", "not a linear over a quadratic")
        zs = list(dict.fromkeys(sp.roots(D, X, filter="R").keys()))
        zs = sorted(zs)
        need(asked == "Find the equations of any vertical asymptotes of the graph of y = f(x).", f"asked {asked!r}")
        wrongs[R9RQ_VA + "0"] = {"x = " + r9rq_t(z)}
        if len(zs) == 2:
            want = r9rq_xs(zs)
            wrongs[R9RQ_VA + "1"] = {r9rq_xs([-zs[0], -zs[1]])}
        elif len(zs) == 1:
            want = "x = " + r9rq_t(zs[0])
            wrongs[R9RQ_VA + "1"] = {"x = " + r9rq_t(-zs[0])}
        else:
            want = "no vertical asymptotes"
            # The discriminant's sign dropped: x = (−p ± √(4q − p²))/2.
            w = sp.sqrt(4 * qq - p**2)
            wrongs[R9RQ_VA + "2"] = {r9rq_xs([(-p - w) / 2, (-p + w) / 2])}
            need(q["view"]["angle"] in ("discriminant-count",) or q["view"].get("shared"), "a denominator with no zeros on a method that factorises it")
        dd = p**2 - 4 * qq
        if any(s["angle"] == "discriminant-count" for s in q["solutions"]):
            r9rq_steps(q, "discriminant-count", r"discriminant is \(?(−?\d+)\)?² − 4 × 1 × \(?(−?\d+)\)? = (−?\d+)\.", [p, qq, dd])
        if len(zs) == 2 and any(s["angle"] == "factorise-denominator" for s in q["solutions"]):
            r9rq_step_has(q, "factorise-denominator", f"= {r9rq_fac(zs)}.")
        if len(zs) == 2 and any(s["angle"] == "gdc-table-near" for s in q["solutions"]):
            r9rq_near(q, f, zs)
    elif u == "vertical-asymptote-ql":
        need(form == "ql", "not a quadratic over a linear")
        want = "x = " + r9rq_t(-e)
        rs = sp.roots(N, X, filter="R")
        need(len(rs) == 2 and all(r.is_integer for r in rs), "the numerator's zeros are not two whole numbers")
        wrongs[R9RQ_VA + "0"] = {"x = " + r9rq_t(r) for r in rs}
        wrongs[R9RQ_T + "12"] = {"x = " + r9rq_t(e)}
        r9rq_steps(q, "factorise-denominator", r"numerator .* is (−?\d+), not 0", [N.subs(X, -e)])
        if any(s["angle"] == "gdc-table-near" for s in q["solutions"]):
            r9rq_near(q, f, [-e])
    elif u == "horizontal-asymptote":
        need(form == "lq" and len(zs) == 2, "not a linear over a quadratic with two vertical asymptotes")
        want = "y = 0"
        wrongs[R9RQ_HA + "0"] = {"y = " + r9rq_t(a)}
        wrongs[R9RQ_HA + "2"] = {"y = " + r9rq_t(b / qq)}
        wrongs[R9RQ_T + "15"] = {"y = " + r9rq_t(r) for r in zs}
        if any(s["angle"] == "gdc-large-x" for s in q["solutions"]):
            r9rq_step_has(q, "gdc-large-x", f"f(1000) = {gc_s(f.subs(X, 1000))} and f(−1000) = {gc_s(f.subs(X, -1000))}")
    elif u == "crosses-horizontal":
        need(form == "lq", "not a linear over a quadratic")
        want = r9rq_pt(z, 0)
        need(sp.limit(f, X, sp.oo) == 0 and f.subs(X, z) == 0, "the graph doesn't cross y = 0 at the numerator's zero")
        wrongs[R9RQ_HA + "1"] = {"it never crosses its horizontal asymptote"}
    elif u == "x-intercepts-ql":
        need(form == "ql", "not a quadratic over a linear")
        if "x-axis" in asked:
            need(asked == "Find the coordinates of the points where the graph of y = f(x) meets the x-axis.", f"asked {asked!r}")
            rs = sorted(sp.roots(N, X, filter="R").keys())
            need(len(rs) == 2 and all(r.is_integer for r in rs) and -e not in rs, "the numerator's zeros are not two whole numbers")
            want = " and ".join(r9rq_pt(r, 0) for r in rs)
            wrongs[R9RQ_T + "14"] = {" and ".join(r9rq_pt(r, 0) for r in sorted([-rs[0], -rs[1]]))}
        else:
            need(asked == "Find the coordinates of the point where the graph of y = f(x) meets the y-axis.", f"asked {asked!r}")
            want = r9rq_pt(0, f.subs(X, 0))
            # The leading coefficients' ratio, m/1.
            wrongs[R9RQ_SK + "1"] = {r9rq_pt(0, m)}
    elif u == "oblique-asymptote":
        need(form == "ql", "not a quadratic over a linear")
        need(asked == "Find the equation of the oblique asymptote of the graph of y = f(x).", f"asked {asked!r}")
        want = "y = " + r9rq_lin(m, k)
        need(sp.limit(f - (m * X + k), X, sp.oo) == 0, "f − (mx + k) does not tend to 0")
        wrongs[R9RQ_OA + "0"] = {"y = " + r9rq_lin(m, 0)}
        wrongs[R9RQ_OA + "1"] = {"y = " + r9rq_lin(m, b)}
        # The first subtraction's sign slipped: (b + me) for (b − me).
        wrongs[R9RQ_T + "13"] = {"y = " + r9rq_lin(m, b + m * e)}
        split = f"f(x) = {r9rq_lin(m, k)} {'+' if Rm > 0 else '−'} {r9rq_t(abs(Rm))}/({r9rq_lin(1, e)})"
        for meth in ("polynomial-division", "compare-coefficients"):
            if any(s["angle"] == meth for s in q["solutions"]):
                r9rq_step_has(q, meth, split)
    elif u == "range-lq":
        need(form == "lq" and not zs, "not a linear over a quadratic with no vertical asymptote")
        need(asked == "Find the range of f.", f"asked {asked!r}")
        lo, hi, xlo, xhi = r9rq_lq_range(N, D)
        exact = lo.is_Rational
        need(exact == (q["paper"] == 1), "Paper 1's range is exact and Paper 2's needs the GDC")
        if exact:
            need(lo.q <= R9RQ_FRAC_MAX and hi.q <= R9RQ_FRAC_MAX and xlo.is_Rational and xhi.is_Rational, "the turning values are not simple fractions")
        else:
            need(all(gc_fair(v) for v in (lo, hi, xlo, xhi)), "a turning value is on a 3 s.f. edge or nearly whole")
        want = r9rq_between(lo, hi)
        wrongs[R9RQ_RT + "0"] = {"f(x) ≠ 0"}
        dd = p**2 - 4 * qq
        if any(s["angle"] == "discriminant-in-x" for s in q["solutions"]):
            yq = sp.expand(dd * X**2 + (4 * b - 2 * a * p) * X + a**2)
            r9rq_step_has(q, "discriminant-in-x", ": " + r9rq_polytext(yq, "y") + " ≥ 0.")
            r9rq_steps(q, "discriminant-in-x", rf"Its zeros are y = ({R9RQ_NUM}) and y = ({R9RQ_NUM})", [lo, hi])
        for meth in ("degree-comparison", "stationary-points"):
            if any(s["angle"] == meth for s in q["solutions"]):
                r9rq_steps(q, meth, rf"f\(({R9RQ_NUM})\) = ({R9RQ_NUM}) is the least value and f\(({R9RQ_NUM})\) = ({R9RQ_NUM}) the greatest", [xlo, lo, xhi, hi])
        if any(s["angle"] == "stationary-points" for s in q["solutions"]):
            top = sp.expand(sp.diff(N, X) * D - N * sp.diff(D, X))
            r9rq_step_has(q, "stationary-points", f" = ({r9rq_polytext(top)})/(")
        if any(s["angle"] == "gdc-max-min" for s in q["solutions"]):
            r9rq_steps(q, "gdc-max-min", rf"minimum is \(({R9RQ_NUM}), ({R9RQ_NUM})\) and its maximum is \(({R9RQ_NUM}), ({R9RQ_NUM})\)", [xlo, lo, xhi, hi])
    elif u == "range-ql":
        need(form == "ql", "not a quadratic over a linear")
        need(m * Rm > 0, "f has no turning points")
        root = sp.sqrt(m * Rm)
        Lv, Uv = k - m * e - 2 * root, k - m * e + 2 * root
        t = sp.sqrt(Rm / m)
        xs = [-e - t, -e + t]
        # Check the turning values against f itself.
        vals = sorted([sp.radsimp(sp.simplify(f.subs(X, x))) for x in xs], key=lambda v: float(v))
        need(sp.simplify(vals[0] - Lv) == 0 and sp.simplify(vals[1] - Uv) == 0, "the turning values are not k − me ± 2√(mR)")
        exact = root.is_Rational
        need(exact == (q["paper"] == 1), "Paper 1's range is exact and Paper 2's needs the GDC")
        if exact:
            need(Lv.is_integer and Uv.is_integer and all(x.is_Rational and x.q <= R9RQ_FRAC_MAX for x in xs), "the turning points are not clean")
        else:
            need(all(gc_fair(v) for v in [Lv, Uv] + xs), "a turning value is on a 3 s.f. edge or nearly whole")
        if asked == "Find the range of f.":
            want = r9rq_outside(Lv, Uv)
            wrongs[R9RQ_RT + "1"] = {r9rq_between(Lv, Uv, True)}
        else:
            need(asked == "Find the set of values that f(x) never takes.", f"asked {asked!r}")
            want = r9rq_between(Lv, Uv, True)
        xL = [x for x in xs if sp.simplify(f.subs(X, x) - Lv) == 0][0]
        xU = [x for x in xs if x != xL][0]
        need(sp.N(sp.diff(f, X, 2).subs(X, xL)) < 0 and sp.N(sp.diff(f, X, 2).subs(X, xU)) > 0, "the lower turning value is not the local maximum")
        if any(s["angle"] == "discriminant-in-x" for s in q["solutions"]):
            yq = sp.expand(X**2 + (4 * m * e - 2 * b) * X + b**2 - 4 * m * c)
            r9rq_step_has(q, "discriminant-in-x", "that is " + r9rq_polytext(yq, "y") + " ≥ 0.")
            r9rq_steps(q, "discriminant-in-x", rf"Its zeros are y = ({R9RQ_NUM}) and y = ({R9RQ_NUM})", [Lv, Uv])
        if any(s["angle"] == "stationary-points" for s in q["solutions"]):
            r9rq_steps(q, "stationary-points", rf"local maximum \(({R9RQ_NUM}), ({R9RQ_NUM})\) and a local minimum \(({R9RQ_NUM}), ({R9RQ_NUM})\)", [xL, Lv, xU, Uv])
        if any(s["angle"] == "gdc-max-min" for s in q["solutions"]):
            r9rq_steps(q, "gdc-max-min", rf"local maximum of ({R9RQ_NUM}) at x = ({R9RQ_NUM}) and a local minimum of ({R9RQ_NUM}) at x = ({R9RQ_NUM})", [Lv, xL, Uv, xU])
    elif u in ("sketch-lq", "sketch-ql"):
        need(form == ("lq" if u == "sketch-lq" else "ql"), f"the wrong form for {u}")
        need(asked == f"Which graph is y = {L[0][len('f(x) = '):]}?", f"asked {asked!r}")
        right = r9rq_cards(q, N, D, form)
        gc_check_common(q, right, {o["ref"]: {o["text"]} for o in q["choices"] if o["ref"]})
        return None, None
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs)
    return None, None


def r9rq_fac(zs):
    """(x − r₁)(x − r₂) as the game writes it."""
    return "".join(f"(x {'−' if r > 0 else '+'} {r9rq_t(abs(r))})" for r in zs)


def r9rq_polytext(e, var="x"):
    """A polynomial in X written the game's way, highest power first, in `var`."""
    cs = sp.Poly(e, X).all_coeffs()
    n = len(cs) - 1
    out = ""
    for i, c in enumerate(cs):
        pw = n - i
        if c == 0:
            continue
        mag = abs(c)
        v = "" if pw == 0 else var + ("²" if pw == 2 else "")
        body = r9rq_t(mag) if pw == 0 else (("" if mag == 1 else r9rq_t(mag)) + v)
        out += (("−" if c < 0 else "") + body) if out == "" else ((" − " if c < 0 else " + ") + body)
    return out or "0"


def r9rq_near(q, f, rs):
    """The GDC table near each vertical asymptote: f(r ± 0.001) to 3 s.f."""
    for r in rs:
        lo, hi = r - sp.Rational(1, 1000), r + sp.Rational(1, 1000)
        r9rq_step_has(q, "gdc-table-near", f"f({dec_text(lo)}) = {gc_s(f.subs(X, lo))} and f({dec_text(hi)}) = {gc_s(f.subs(X, hi))}")


def r9rq_lq_range(N, D):
    """The least and greatest values of an lq with no vertical asymptote, and where they are."""
    f = N / D
    xs = sp.solve(sp.numer(sp.together(sp.diff(f, X))), X)
    need(len(xs) == 2, "f′ should have two zeros")
    ys = [sp.radsimp(sp.simplify(f.subs(X, x))) for x in xs]
    pairs = sorted(zip(ys, xs), key=lambda t: float(t[0]))
    (lo, xlo), (hi, xhi) = pairs
    need(lo < 0 < hi, "the range does not hold 0 inside it")
    return sp.simplify(lo), sp.simplify(hi), sp.simplify(xlo), sp.simplify(xhi)


def r9rq_constant(q, N, D, form):
    """denominator-from-asymptote: k in the denominator, from a vertical asymptote."""
    L, rep = q["lines"], q["view"]["rep"]
    need(q["asked"] == "Find the value of k.", f"asked {q['asked']!r}")
    need(not N.has(R9RQ_K) and D.has(R9RQ_K) and sp.degree(D, R9RQ_K) == 1, "k is not one coefficient of the denominator")
    if rep == "graph":
        need(L[1] == "The graph of y = f(x) is shown, with its asymptotes dashed.", f"{L[1]!r}")
        g = q["graph"]
        need(g is not None and not g.get("card"), "no graph shown")
        ats = sorted(sp.Rational(v["at"]).limit_denominator(1000) for v in g["vlines"])
        need(ats, "the graph shows no vertical asymptote")
    else:
        mv = re.fullmatch(r"The graph of y = f\(x\) has a vertical asymptote x = (−?\d+)\.", L[1])
        need(mv is not None, f"can't read {L[1]!r}")
        ats = [sp.Rational(mv.group(1).replace("−", "-"))]
    ks = {sp.solve(D.subs(X, r), R9RQ_K)[0] for r in ats}
    need(len(ks) == 1, "the asymptotes shown give different values of k")
    kv = ks.pop()
    Dk = D.subs(R9RQ_K, kv)
    r9rq_clean(q, N, Dk, form)
    zs = sorted(sp.roots(Dk, X, filter="R").keys())
    need(sorted(ats) == zs if rep == "graph" else ats[0] in zs, "the asymptotes given are not the zeros of the denominator")
    if form == "lq":
        need(len(zs) == 2, "the denominator has no two whole zeros")
    if rep == "graph":
        r9rq_graph_is(q["graph"], N / Dk, form, dash=None if form == "lq" else sp.div(N, Dk, X)[0])
    want = "k = " + r9rq_t(kv)
    # The asymptote's sign changed: k from x = −r.
    slips = {"k = " + r9rq_t(sp.solve(D.subs(X, -r), R9RQ_K)[0]) for r in ats if r != 0}
    if form == "lq":
        r = ats[0] if rep != "graph" else None
        for sol in q["solutions"]:
            for st in sol["steps"]:
                mt = re.search(r"Put x = (−?\d+): (\d+) ([+−]) (\d*)k ([+−]) (\d+) = 0", st)
                if mt:
                    x0 = sp.Rational(mt.group(1).replace("−", "-"))
                    need(x0 in zs, f"{st!r} puts in an x that is no asymptote")
                    co = int(mt.group(4) or 1) * (1 if mt.group(3) == "+" else -1)
                    c0 = int(mt.group(6)) * (1 if mt.group(5) == "+" else -1)
                    need(sp.expand(sp.Integer(int(mt.group(2))) + co * R9RQ_K + c0 - D.subs(X, x0)) == 0, f"{st!r} is not the denominator at x = {x0}")
    gc_check_common(q, want, {R9RQ_T + "12": slips})
    return None, None


def r9rq_coefficient(q, N, D):
    """coefficient-from-oblique: k in the numerator, from the oblique asymptote."""
    L = q["lines"]
    need(q["asked"] == "Find the value of k.", f"asked {q['asked']!r}")
    need(N.has(R9RQ_K) and not D.has(R9RQ_K) and sp.expand(N - N.subs(R9RQ_K, 0)) == R9RQ_K * X, "k is not the x coefficient of the numerator")
    mo = re.fullmatch(r"The graph of y = f\(x\) has the oblique asymptote y = (.+)\.", L[1])
    need(mo is not None, f"can't read {L[1]!r}")
    line = r9rq_poly(mo.group(1))
    need(sp.degree(line, X) == 1, "the asymptote is not a slanted line")
    quo, _ = sp.div(N, D, X)
    sol = sp.solve(sp.Poly(sp.expand(quo - line), X).all_coeffs(), R9RQ_K, dict=True)
    need(len(sol) == 1, "no single k makes that the oblique asymptote")
    kv = sol[0][R9RQ_K]
    r9rq_clean(q, N.subs(R9RQ_K, kv), D, "ql")
    m = sp.Poly(N, X).LC()
    e = D.subs(X, 0)
    q0 = line.subs(X, 0)
    want = "k = " + r9rq_t(kv)
    # The subtraction's sign slipped: the quotient's constant taken as k + me, so k = q0 − me.
    gc_check_common(q, want, {R9RQ_T + "13": {"k = " + r9rq_t(q0 - m * e)}})
    for st in [s for sol in q["solutions"] for s in sol["steps"]]:
        mt = re.search(r"So the quotient is .*x \+ \(k ([+−]) (\d+)\)", st)
        if mt:
            need((1 if mt.group(1) == "+" else -1) * int(mt.group(2)) == -m * e, f"{st!r}: the quotient's constant is k − me")
    return None, None


def r9rq_fn(kind, P):
    """A card's function: lq (n1, n0, v0, v1) is (n1·x + n0)/((x − v0)(x − v1)); ql (M, K, R, v) is Mx + K + R/(x − v)."""
    if kind == "lq":
        n1, n0, v0, v1 = P
        return (n1 * X + n0) / ((X - v0) * (X - v1)), [v0, v1]
    M, K, Rr, v = P
    return M * X + K + Rr / (X - v), [v]


def r9rq_curve_on(curve, fn, tol=1e-6):
    fl = sp.lambdify(X, fn, "mpmath")
    for x, y in curve:
        need(R9RQ_WIN[2] - 1e-6 <= y <= R9RQ_WIN[3] + 1e-6 and R9RQ_WIN[0] - 1e-9 <= x <= R9RQ_WIN[1] + 1e-9, f"a point ({x}, {y}) is outside the plot")
        need(abs(float(fl(mpmath.mpf(x))) - y) <= tol * max(1, abs(y)), f"a point ({x}, {y}) is not on {fn}")


def r9rq_dots(fn, vas):
    """The intercepts a card marks: the zeros and f(0), each at least half a unit inside the plot."""
    out = []
    for r in sp.Poly(sp.numer(sp.together(fn)), X).real_roots():
        if abs(r) <= R9RQ_WIN[1] - sp.Rational(1, 2) and r not in vas:
            out.append((float(r), 0.0))
    if 0 not in vas:
        y0 = fn.subs(X, 0)
        if abs(y0) <= R9RQ_WIN[3] - sp.Rational(1, 2):
            out.append((0.0, float(y0)))
    return sorted(out)


def r9rq_graph_is(g, fn, kind, across=False, dash=None):
    """A drawn graph is fn: its pieces lie on it and stop at each vertical asymptote (or, across,
    one piece runs over it), the dashed lines are its asymptotes, and an oblique one's dashes lie
    on y = dash(x)."""
    vas = sorted(sp.roots(sp.denom(sp.together(fn)), X, filter="R").keys())
    need(sorted(round(v["at"], 9) for v in g["vlines"]) == [float(v) for v in vas], "the dashed vertical lines are not the vertical asymptotes")
    need([h["at"] for h in g["hlines"]] == ([0.0] if kind == "lq" else []), "the dashed horizontal line is not y = 0")
    need((g["x0"], g["x1"], g["y0"], g["y1"]) == R9RQ_WIN, "the plot is not −8 to 8 both ways")
    sand = g.get("sand_from", len(g["curves"]))
    curves, dashes = g["curves"][:sand], g["curves"][sand:]
    need(len(curves) >= 1, "no curve is drawn")
    for c in curves:
        r9rq_curve_on(c, fn)
        crosses = [v for v in vas if c[0][0] < v < c[-1][0]]
        need(bool(crosses) == across, "a piece is drawn across a vertical asymptote" if not across else "the joined graph doesn't cross its asymptote")
    need(sum(len(c) for c in curves) > 150, "too little of the curve is drawn")
    if kind == "ql":
        need(len(dashes) > 10, "the oblique asymptote is not drawn")
        for dsh in dashes:
            need(len(dsh) == 2, "a dash is not a short segment")
            for x, y in dsh:
                need(abs(float(dash.subs(X, x)) - y) < 1e-9, "a dash is off the oblique asymptote")
    else:
        need(not dashes, "an lq graph has no oblique asymptote")


def r9rq_cards(q, N, D, form):
    """Pick the graph: the right card is f, and each wrong card is f with the one mistake it names."""
    graphs, ch = q["graphs"], q["choices"]
    need(len(graphs) == 4 and len(ch) == 4, "pick the graph needs four graphs")
    need([o["text"] for o in ch] == ["Graph A", "Graph B", "Graph C", "Graph D"], "the graphs are not lettered A to D")
    need(sum(1 for o in ch if o["correct"]) == 1, "not exactly one right graph")
    need(all(g.get("card") for g in graphs), "a graph is not drawn as a card")
    need(len({json.dumps(g["curves"]) for g in graphs}) == 4, "two graphs are the same")
    if form == "lq":
        a, b = sp.Poly(N, X).all_coeffs()
        zs = sorted(sp.roots(D, X, filter="R").keys())
        need(len(zs) == 2, "an lq card needs two vertical asymptotes")
        z = -b / a
        yi = N.subs(X, 0) / D.subs(X, 0)
        need(zs[1] - zs[0] >= 2 and abs(z) <= R9RQ_PLOT and abs(yi) <= R9RQ_PLOT and all(abs(z - r) >= 1 and z != -r for r in zs), "the features are not inside the plot")
        base = (a, b, zs[0], zs[1])
        made = {"": base, "no-zero": (0, b, zs[0], zs[1]), "flipped": (-a, -b, zs[0], zs[1]),
                "va-sign": (a, b, -zs[1], -zs[0]), "zero-sign": (a, -b, zs[0], zs[1])}
        refs = {"no-zero": R9RQ_SK + "0", "flipped": "", "va-sign": "", "zero-sign": ""}
        need(any(o["mistake"] == "no-zero" for o in ch), "no card misses the zero")
    else:
        m = sp.Poly(N, X).LC()
        e = D.subs(X, 0)
        k, Rm = r9rq_div(N, D)
        rs = sp.roots(N, X, filter="R")
        need(len(rs) == 2 and all(r.is_integer and abs(r) <= R9RQ_PLOT and abs(r + e) >= 1 for r in rs), "the numerator's zeros are not whole and inside the plot")
        need(abs(m) <= 2 and abs(k) <= 4 and abs(Rm) <= 5 and abs(e) <= 4 and abs(N.subs(X, 0) / e) <= R9RQ_PLOT, "the features are not inside the plot")
        base = (m, k, Rm, -e)
        made = {"": base, "no-constant": (m, 0, Rm, -e), "remainder-flipped": (m, k, -Rm, -e), "va-mirrored": (m, k, Rm, e), "through": base}
        refs = {"no-constant": R9RQ_OA + "0", "remainder-flipped": "", "va-mirrored": "", "through": ""}
        need(any(o["mistake"] == "no-constant" for o in ch), "no card loses the oblique asymptote's constant")
    for o, g in zip(ch, graphs):
        mk = "" if o["correct"] else o.get("mistake", "")
        need(mk in made, f"a wrong graph names no mistake this check knows ({mk!r})")
        if not o["correct"]:
            need(o["ref"] == refs[mk], f"the {mk} graph is tagged {o['ref']!r}, not {refs[mk]!r}")
            need(o.get("why", "") != "", f"the {mk} graph doesn't say what is wrong")
        fn, vas = r9rq_fn(form, made[mk])
        if mk == "":
            need(sp.simplify(fn - N / D) == 0, "the right graph is not f")
            # Every branch shows: one piece more than there are vertical asymptotes.
            need(len(g["curves"][:g.get("sand_from", len(g["curves"]))]) == len(vas) + 1, "the right graph doesn't show every branch")
        dash = None if form == "lq" else made[mk][0] * X + made[mk][1]
        r9rq_graph_is(g, fn, form, mk == "through", dash)
        dots = sorted((round(p["x"], 6), round(p["y"], 6)) for p in g["points"])
        want = [(round(x, 6), round(y, 6)) for x, y in r9rq_dots(fn, vas)]
        need(dots == want, f"the {mk or 'right'} graph doesn't mark its intercepts: {dots} vs {want}")
    return next(o["text"] for o in ch if o["correct"])


SITUATION_CHECKS["rational-quadratic"] = r9rq_check

# (between the R9 markers)

# R9-ODD-EVEN: fn-ahl-odd-even (odd-even), prefix R9OE_ / r9oe_

R9OE_T = "AHL2.14.odd-even-test#"
R9OE_G = "AHL2.14.odd-even-graph#"
R9OE_C = "AHL2.14.odd-even-combine#"
R9OE_OWN = "fn-ahl-odd-even#"
R9OE_SUP = {"⁰": "0", "¹": "1", "²": "2", "³": "3", "⁴": "4", "⁵": "5", "⁶": "6", "⁷": "7", "⁸": "8", "⁹": "9"}
R9OE_VERDICT = {"odd": "Odd: f(−x) = −f(x)", "even": "Even: f(−x) = f(x)", "neither": "Neither: f(−x) is not f(x) or −f(x)"}
R9OE_H = {"odd": "Odd: h(−x) = −h(x)", "even": "Even: h(−x) = h(x)", "neither": "Neither: h(−x) is not h(x) or −h(x)"}
# Every option a classify question may offer, and the verdict each one gives.
R9OE_CLAIMS = {R9OE_VERDICT["odd"]: "odd", R9OE_VERDICT["even"]: "even", R9OE_VERDICT["neither"]: "neither",
               "Even: f(−x) = −f(x)": "even", "Odd: f(−x) = f(x)": "odd", "Odd: f(−x) is not f(x)": "odd",
               "Odd: every power of x in it is odd": "odd", "Even: f(−π) = f(π)": "even",
               "Even: an odd part plus an even part is even": "even", "Odd: an odd part plus an even part is odd": "odd"}
R9OE_HCLAIMS = {R9OE_H["odd"]: "odd", R9OE_H["even"]: "even", R9OE_H["neither"]: "neither", "Even: h(−x) = −h(x)": "even",
                "Odd: h(−x) = h(x)": "odd", "Odd: odd × odd is odd": "odd", "Odd: odd + even is odd": "odd", "Even: odd + even is even": "even"}


def r9oe_fn(text, letters=""):
    """A function as the game writes it: '3x² sin x − 2x', '4e^(−x)', '(−x)³ cos(−x)', '2 + 3 sin 1 − e'."""
    t = text.replace("−", "-")
    need(re.fullmatch(r"[0-9a-z^()+\-*/ ⁰¹²³⁴⁵⁶⁷⁸⁹π]+", t) is not None, f"can't read {text!r}")
    t = re.sub("([⁰¹²³⁴⁵⁶⁷⁸⁹]+)", lambda m: "**" + "".join(R9OE_SUP[c] for c in m.group(1)), t)
    t = t.replace("e^(", "exp(").replace("e^x", "exp(x)").replace("π", "pi")
    t = re.sub(r"\b(sin|cos) (x|\d+)\b", r"\1(\2)", t)
    for L in letters:
        t = re.sub(r"(?<![a-z])" + L + r"(?=x)", L + "*", t)
    loc = {"x": X, "e": sp.E, "exp": sp.exp, "sin": sp.sin, "cos": sp.cos, "pi": sp.pi}
    for L in letters:
        loc[L] = sp.Symbol(L)
    return parse_expr(t, transformations=TRANSFORMS, local_dict=loc)


def r9oe_zero(e):
    """Whether e is 0 for every x: exactly, and at rational points to 30 digits."""
    if sp.simplify(sp.expand(e)) == 0:
        return True
    pts = [sp.Rational(3, 7), sp.Rational(-5, 4), sp.Rational(11, 5)]
    others = sorted(e.free_symbols - {X}, key=str)
    for i, p in enumerate(pts):
        sub = {X: p}
        sub.update({c: sp.Rational(2 * j + i + 3, 5 + j) for j, c in enumerate(others)})
        if abs(sp.N(e.subs(sub), 30)) >= sp.Float("1e-25"):
            return False
    return True


def r9oe_parity(f):
    fm = f.subs(X, -X)
    ev, od = r9oe_zero(fm - f), r9oe_zero(fm + f)
    need(not (ev and od), "f is 0")
    return "even" if ev else ("odd" if od else "neither")


def r9oe_t(v):
    """A rational as the game writes it: −7, 29/2."""
    v = sp.Rational(v)
    return (str(v.p) if v.q == 1 else f"{v.p}/{v.q}").replace("-", "−")


def r9oe_steps(q):
    return [st for sol in q["solutions"] for st in sol["steps"]]


def r9oe_sol(q, angle):
    for sol in q["solutions"]:
        if sol["angle"] == angle:
            return sol["steps"]
    return None


def r9oe_after(steps, prefix):
    for st in steps:
        if st.startswith(prefix):
            return st[len(prefix):]
    raise Fail(f"no step starting {prefix!r}")


def r9oe_options(q, known):
    for o in q["choices"]:
        need(o["text"] in known, f"option {o['text']!r} is not one of the claims")


def r9oe_classify(q, mixed):
    L = q["lines"]
    need(len(L) == 1 and L[0].startswith("f(x) = "), f"lines {L!r}")
    need(q["asked"] == "Is f odd, even or neither, and why?", f"asked {q['asked']!r}")
    ftxt = L[0][7:]
    f = r9oe_fn(ftxt)
    trig = f.has(sp.sin) or f.has(sp.cos) or f.has(sp.exp)
    need(trig == mixed, "a polynomial type with sin, cos or e^x, or a mixed one without")
    if not mixed:
        need(sp.Poly(f, X) is not None and f.is_polynomial(X), "not a polynomial")
    par = r9oe_parity(f)
    want = R9OE_VERDICT[par]
    r9oe_options(q, R9OE_CLAIMS)
    for o in q["choices"]:
        need(o["correct"] or R9OE_CLAIMS[o["text"]] != par, f"option {o['text']!r} gives the right verdict but is marked wrong")
    wrongs = {}
    if par == "odd":
        wrongs[R9OE_OWN + "10"] = {"Even: f(−x) = −f(x)"}
    if par == "neither":
        wrongs[R9OE_T + "0"] = {"Odd: f(−x) is not f(x)"}
        if not mixed:
            P = sp.Poly(f, X)
            if P.coeff_monomial(1) != 0 and all(m[0] % 2 == 1 for m in P.monoms() if m[0] > 0):
                wrongs[R9OE_T + "1"] = {"Odd: every power of x in it is odd"}
            wrongs[R9OE_C + "1"] = {"Even: an odd part plus an even part is even", "Odd: an odd part plus an even part is odd"}
    if mixed and par != "even" and sp.simplify(f.subs(X, sp.pi) - f.subs(X, -sp.pi)) == 0:
        wrongs[R9OE_T + "2"] = {"Even: f(−π) = f(π)"}
    fm = sp.expand(f.subs(X, -X))
    st = r9oe_sol(q, "substitute-minus-x")
    need(st is not None, "no substitution working")
    raw = r9oe_after(st, "Put −x in: f(−x) = ")
    need("(−x)" in raw or "e^" in raw or re.search(r"\d", raw), "the substitution is not shown")
    need(r9oe_zero(r9oe_fn(raw) - fm), f"f(−x) = {raw!r} is wrong")
    for sol in q["solutions"]:
        for s_ in sol["steps"]:
            m = re.match(r"(?:Simplify: |So )f\(−x\) = (.+)$", s_)
            if m:
                need(r9oe_zero(r9oe_fn(m.group(1)) - fm), f"f(−x) = {m.group(1)!r} is wrong")
                need(re.search(r"(?<!\^)\(−x\)", m.group(1)) is None, "f(−x) is not simplified")
            m = re.match(r"That is −\((.+)\) = −f\(x\)$", s_)
            if m:
                need(par == "odd" and r9oe_fn(m.group(1)) == f, f"{s_!r}")
            if s_ == "That is f(x)":
                need(par == "even", s_)
            m = re.match(r"That is not f\(x\), and not −f\(x\) = (.+)$", s_)
            if m:
                need(par == "neither" and r9oe_zero(r9oe_fn(m.group(1)) + f), s_)
    # Each piece's parity in the building-blocks line.
    st = r9oe_sol(q, "known-building-blocks")
    need(st is not None, "no building-blocks working")
    for piece in st[0].split("; "):
        m = re.fullmatch(r"(.+?) is (?:(odd|even) × (odd|even) = )?(odd|even|neither)(?: \(an? (?:odd power|even power|constant)\)|: x → −x swaps .*)?", piece)
        need(m is not None, f"can't read {piece!r}")
        T_ = r9oe_fn(m.group(1))
        need(r9oe_parity(T_) == m.group(4), f"{piece!r}: wrong parity")
        if m.group(2):
            need((m.group(2) == m.group(3)) == (m.group(4) == "even"), f"{piece!r}: wrong product rule")
            xp = sp.Poly(T_.as_independent(sp.sin, sp.cos)[0], X).degree()
            need((xp % 2 == 0) == (m.group(2) == "even") and (m.group(3) == "odd") == T_.has(sp.sin), f"{piece!r}: the factors' parities")
    st = r9oe_sol(q, "counterexample")
    if q["view"]["angle"] == "counterexample":
        need(par == "neither", "a counterexample for a function that is odd or even")
    if st is not None:
        need(par == "neither", "a counterexample working for a function that is odd or even")
        m = re.fullmatch(r"Try x = (\d): f\(\1\) = (.+) and f\(−\1\) = (.+)", st[0])
        need(m is not None, f"can't read {st[0]!r}")
        a = int(m.group(1))
        up, down = r9oe_fn(m.group(2)), r9oe_fn(m.group(3))
        need(sp.simplify(up - f.subs(X, a)) == 0 and sp.simplify(down - f.subs(X, -a)) == 0, "the counterexample's values are wrong")
        need(abs(sp.N(up - down, 30)) > 1e-6 and abs(sp.N(up + down, 30)) > 1e-6, "the counterexample doesn't show neither")
        m = re.search(r"≠ −f\(\d\) = (.+), so f is not odd$", st[2])
        need(m is not None and sp.simplify(r9oe_fn(m.group(1)) + up) == 0, f"{st[2]!r}")
    if q["view"]["angle"] == "unit-circle":
        need(f.has(sp.sin) or f.has(sp.cos), "the unit circle with no sin or cos")
    return want, wrongs


def r9oe_coefficient(q):
    L = q["lines"]
    need(len(L) == 2 and L[0].startswith("f(x) = "), f"lines {L!r}")
    m = re.fullmatch(r"f is an (odd|even) function\.", L[1])
    need(m is not None, L[1])
    kind = m.group(1)
    K = sp.Symbol("k")
    f = sp.expand(r9oe_fn(L[0][7:], "k"))
    P = sp.Poly(f, X)
    bad = [P.coeff_monomial(X**d) for d in range(P.degree() + 1) if (d % 2 == 0) == (kind == "odd")]
    good = [P.coeff_monomial(X**d) for d in range(P.degree() + 1) if (d % 2 == 0) != (kind == "odd")]
    sols = sp.solve([c for c in bad if c != 0], K, dict=True)
    need(len(sols) == 1, f"k is not unique: {sols}")
    k = sols[0][K]
    need(k.is_integer, "k is not whole")
    g = f.subs(K, k)
    need(r9oe_parity(g) == kind, "f with that k is not the asked kind")
    need(all(c.subs(K, k) != 0 for c in good if c.has(K)), "k kills a term of the right kind")
    slips = set()
    for c in good:
        if c.has(K):
            for v in sp.solve(c, K):
                slips.add("k = " + r9oe_t(v))
    want = "k = " + r9oe_t(k)
    for st in r9oe_steps(q):
        if st.startswith("Put −x in: f(−x) = "):
            need(sp.expand(r9oe_fn(st[19:], "k") - f.subs(X, -X)) == 0, f"{st!r}")
        mm = re.match(r"Then f\(x\) = (.+), with only (odd|even) powers$", st)
        if mm:
            need(sp.expand(r9oe_fn(mm.group(1)) - g) == 0 and mm.group(2) == kind, f"{st!r}")
        mm = re.search(r"must be 0: (.+) = 0$", st)
        if mm:
            need(sp.solve(r9oe_fn(mm.group(1), "k"), K) == [k], f"{st!r}")
    return want, {R9OE_OWN + "12": slips}


def r9oe_eval(expr, a, fa, fma):
    t = expr.replace(f"f(−{a})", f"({fma})").replace(f"f({a})", f"({fa})").replace("−", "-")
    t = re.sub(r"(\d)\(", r"\1*(", t)
    need(re.fullmatch(r"[0-9()+\-* ]+", t) is not None, f"can't read {expr!r}")
    return sp.sympify(t)


def r9oe_value(q):
    rep, L = q["view"]["rep"], q["lines"]
    m = re.fullmatch(r"Find (f\(−(\d)\)|f\((\d)\) \+ f\(−\3\)|f\(−(\d)\) − f\(\4\)|f\(−(\d)\) \+ 2f\(\5\))\.", q["asked"])
    need(m is not None, f"asked {q['asked']!r}")
    expr = m.group(1)
    a = int(next(g for g in m.groups()[1:] if g))
    if rep == "graph":
        mm = re.fullmatch(r"The graph of y = f\(x\) for x ≥ 0 is shown\. f is (odd|even)\.", L[0])
        need(mm is not None, L[0])
        par = mm.group(1)
        g = q["graph"]
        cv = g["curves"][0]
        need(len(g["curves"]) == 1 and all(p[0] >= 0 for p in cv), "the graph is not one half for x ≥ 0")
        need(par != "odd" or (cv[0][0] == 0 and cv[0][1] == 0), "an odd half not through the origin")
        pts = g["points"]
        need(len(pts) == 1 and pts[0]["x"] == a, "the marked point is not at x = a")
        b = sp.Integer(round(pts[0]["y"]))
        need(pts[0]["label"] == f"({a}, {r9oe_t(b)})" and any(p[0] == a and p[1] == pts[0]["y"] for p in cv), "the point is not a key point of the curve")
    else:
        mm = re.fullmatch(r"f\(x\) = (.+), where (p and q|p, q and r) are constants, and f\((\d)\) = (−?\d+)\.", L[0])
        need(mm is not None and int(mm.group(3)) == a, L[0])
        letters = "pqr" if "r" in mm.group(2) else "pq"
        f = r9oe_fn(mm.group(1), letters)
        need(f.free_symbols == {X} | {sp.Symbol(c) for c in letters}, "the constants named are not the rule's")
        par = r9oe_parity(f)
        need(par != "neither", "the rule is neither odd nor even")
        b = sp.Integer(int(mm.group(4).replace("−", "-")))
    need(b != 0, "f(a) = 0")
    fma = -b if par == "odd" else b
    v = r9oe_eval(expr, a, b, fma)
    want = expr + " = " + r9oe_t(v)
    slip = r9oe_eval(expr, a, b, -fma)
    wrongs = {(R9OE_G + "0") if par == "odd" else (R9OE_OWN + "11"): {expr + " = " + r9oe_t(slip)}}
    for st in r9oe_steps(q):
        mm = re.fullmatch(r"f\(−\d\) = (−?\d+)", st)
        if mm:
            need(R(mm.group(1).replace("−", "-")) == fma, st)
        mm = re.fullmatch(r"(.+) = (.+) = (−?\d+)", st)
        if mm and mm.group(1) == expr:
            need(sp.sympify(mm.group(2).replace("−", "-").replace("×", "*")) == v and R(mm.group(3).replace("−", "-")) == v, st)
    return want, wrongs


def r9oe_segs(curves):
    out = set()
    for c in curves:
        for p, r in zip(c, c[1:]):
            out.add(frozenset({(round(p[0], 6), round(p[1], 6)), (round(r[0], 6), round(r[1], 6))}))
    return out


def r9oe_map(segs, fx):
    return {frozenset(fx(p) for p in s) for s in segs}


def r9oe_sym(segs, kind):
    if kind == "odd":
        return r9oe_map(segs, lambda p: (-p[0], -p[1])) == segs
    return r9oe_map(segs, lambda p: (-p[0], p[1])) == segs


def r9oe_complete(q):
    L = q["lines"]
    m = re.fullmatch(r"The graph of y = f\(x\) for x ≥ 0 is shown\. f is (odd|even) and defined for every x\.", L[0])
    need(m is not None, L[0])
    par = m.group(1)
    need(q["asked"] == "Which graph shows y = f(x) for every x?", q["asked"])
    g = q["graph"]
    half = [(round(p[0], 6), round(p[1], 6)) for p in g["curves"][0]]
    need(len(g["curves"]) == 1 and half[0][0] == 0 and all(p[0] >= 0 for p in half), "the graph is not one half for x ≥ 0")
    need(par != "odd" or half[0][1] == 0, "an odd function defined at 0 not through the origin")
    need([(p["x"], p["y"]) for p in g["points"]] == half and all(p["label"] == f"({r9oe_t(int(p['x']))}, {r9oe_t(int(p['y']))})" for p in g["points"]), "the key points")
    hs = r9oe_segs([half])
    rot = r9oe_map(hs, lambda p: (-p[0], -p[1]))
    mir = r9oe_map(hs, lambda p: (-p[0], p[1]))
    xax = r9oe_map(hs, lambda p: (p[0], -p[1]))
    w = half[-1][0]
    slide = r9oe_map(hs, lambda p: (p[0] - w, p[1]))
    right = hs | (rot if par == "odd" else mir)
    want, wrongs = None, {}
    for o, card in zip(q["choices"], q["graphs"]):
        cs = r9oe_segs(card["curves"])
        need(card.get("card"), "not a card")
        if o["correct"]:
            need(cs == right, "the right card is not the half and its image")
            need(r9oe_sym(cs, par), "the right card is not " + par)
            want = o["text"]
            continue
        mk, ref = o.get("mistake", ""), o.get("ref", "")
        need(o.get("why"), "a wrong card says no why")
        if mk == "y-axis":
            need(par == "odd" and cs == hs | mir and ref == R9OE_G + "0", "the y-axis card")
        elif mk == "x-axis":
            need(cs == hs | xax and ref == (R9OE_G + "1" if par == "odd" else ""), "the x-axis card")
        elif mk == "off-origin":
            need(par == "odd" and ref == R9OE_G + "2", "the off-origin card")
            left = cs - hs
            at0 = [p for s in left for p in s if p[0] == 0]
            need(len(at0) >= 1, "the off-origin card has no point on the y-axis")
            k = sp.Rational(at0[0][1]) / 2
            need(k != 0 and k.q == 1, "the off-origin card's centre")
            need(cs == hs | r9oe_map(hs, lambda p: (-p[0], round(float(2 * k) - p[1], 6))), "the off-origin card is not a half-turn about (0, k)")
        elif mk == "half-turn":
            need(par == "even" and cs == hs | rot and ref == "", "the half-turn card")
        elif mk == "slide":
            need(par == "even" and cs == hs | slide and ref == "", "the slide card")
        else:
            raise Fail(f"a card names no mistake ({mk!r})")
        if ref:
            wrongs.setdefault(ref, set()).add(o["text"])
        need(cs != right, "a wrong card is the right graph")
    need(want is not None, "no right card")
    return want, wrongs


def r9oe_which(q):
    m = re.fullmatch(r"Which graph shows an (odd|even) function\?", q["asked"])
    need(m is not None, q["asked"])
    par = m.group(1)
    other = "even" if par == "odd" else "odd"
    want, wrongs = None, {}
    for o, card in zip(q["choices"], q["graphs"]):
        cs = r9oe_segs(card["curves"])
        xs = [p[0] for s in cs for p in s]
        # A graph of a function: each card is one polyline rising in x.
        need(len(card["curves"]) == 1 and all(a[0] < b[0] for a, b in zip(card["curves"][0], card["curves"][0][1:])), "a card is not one function")
        if o["correct"]:
            need(r9oe_sym(cs, par), "the right card is not " + par)
            want = o["text"]
            continue
        need(not r9oe_sym(cs, par), f"wrong card {o['text']} is {par} too")
        mk, ref = o.get("mistake", ""), o.get("ref", "")
        if mk == other:
            need(r9oe_sym(cs, other) and ref == (R9OE_G + "0" if par == "odd" else ""), f"the {other} card")
        elif mk == "shifted":
            need(ref == "", "the shifted card")
            if par == "odd":
                y0 = [p[1] for s in cs for p in s if p[0] == 0][0]
                need(y0 != 0 and r9oe_sym(r9oe_map(cs, lambda p: (p[0], round(p[1] - y0, 6))), "odd"), "the shifted card is not an odd graph moved up or down")
            else:
                h = (min(xs) + max(xs)) / 2
                need(h != 0 and r9oe_sym(r9oe_map(cs, lambda p: (round(p[0] - h, 6), p[1])), "even"), "the shifted card is not an even graph moved sideways")
        elif mk == "neither":
            need(ref == "" and not r9oe_sym(cs, "odd") and not r9oe_sym(cs, "even"), "the neither card")
        else:
            raise Fail(f"a card names no mistake ({mk!r})")
        if ref:
            wrongs.setdefault(ref, set()).add(o["text"])
    need(want is not None, "no right card")
    return want, wrongs


def r9oe_combine(q):
    L = q["lines"]
    need(len(L) == 2, f"lines {L!r}")
    m = re.fullmatch(r"(?:f and g are both (odd|even) functions|f is an (odd|even) function and g is an (odd|even) function), and neither is 0 for every x\.", L[0])
    need(m is not None, L[0])
    pf, pg = (m.group(1), m.group(1)) if m.group(1) else (m.group(2), m.group(3))
    ops = {"h(x) = f(x)g(x)": lambda F, G: F * G, "h(x) = f(x) + g(x)": lambda F, G: F + G,
           "h(x) = f(g(x))": lambda F, G: F.subs(X, G), "h(x) = g(f(x))": lambda F, G: G.subs(X, F)}
    need(L[1] in ops, L[1])
    need(q["asked"] == "Is h odd, even or neither?", q["asked"])
    # Concrete functions of each kind: h's parity must be the same for every choice.
    egs = {"odd": [X**3 + X, sp.sin(X), X**5 - 2 * X], "even": [X**2 + 1, sp.cos(X) + 2, X**4 - 3 * X**2]}
    pars = {r9oe_parity(sp.expand(ops[L[1]](F, G))) for F in egs[pf] for G in egs[pg]}
    need(len(pars) == 1, f"h's parity depends on f and g: {pars}")
    par = pars.pop()
    r9oe_options(q, R9OE_HCLAIMS)
    for o in q["choices"]:
        need(o["correct"] or R9OE_HCLAIMS[o["text"]] != par, f"option {o['text']!r} gives the right verdict but is marked wrong")
    wrongs = {}
    if L[1] == "h(x) = f(x)g(x)" and pf == pg == "odd":
        wrongs[R9OE_C + "0"] = {"Odd: odd × odd is odd"}
    if L[1] == "h(x) = f(x) + g(x)" and pf != pg:
        wrongs[R9OE_C + "1"] = {"Odd: odd + even is odd", "Even: odd + even is even"}
    st = r9oe_sol(q, "sign-rule")
    if st is not None:
        need(L[1] == "h(x) = f(x)g(x)", "the sign rule on something other than a product")
        sg = {"odd": "(−1)", "even": "(+1)"}
        need(f"h = f × g: {sg[pf]} × {sg[pg]} = {'+1' if par == 'even' else '−1'}, which is {par}" in st, "the sign rule's line")
    return R9OE_H[par], wrongs


def r9oe_poly_integral(pts, lo, hi):
    """∫ of a polyline from lo to hi, exactly, as trapezia."""
    tot = sp.Integer(0)
    for p, r in zip(pts, pts[1:]):
        x0, x1 = max(p[0], lo), min(r[0], hi)
        if x1 <= x0:
            continue
        y = lambda x: p[1] + (r[1] - p[1]) * (x - p[0]) / (r[0] - p[0])
        tot += (x1 - x0) * (y(x0) + y(x1)) / 2
    return tot


def r9oe_integral(q):
    rep, L, paper = q["view"]["rep"], q["lines"], q["paper"]
    m = re.fullmatch(r"Find ∫ from −(\d) to \1 of f\(x\) dx\.", q["asked"])
    need(m is not None, q["asked"])
    a = int(m.group(1))
    label = f"∫ from −{a} to {a} of f(x) dx = "
    wrongs = {}
    show = r9oe_t
    if rep == "graph":
        mm = re.fullmatch(r"The graph of y = f\(x\) is shown for −(\d) ≤ x ≤ \1\. The shaded region, between the curve and the x-axis from x = 0 to x = \1, has area (\d+(?:/\d+)?)\.", L[0])
        need(mm is not None and int(mm.group(1)) == a, L[0])
        area = R(mm.group(2))
        g = q["graph"]
        pts = [(sp.nsimplify(p[0]), sp.nsimplify(p[1])) for c in g["curves"] for p in c]
        pts = sorted(set(pts))
        need(pts[0][0] == -a and pts[-1][0] == a, "the curve is not drawn from −a to a")
        need(all(y >= 0 for x, y in pts if x >= 0), "the curve dips below the x-axis from 0 to a")
        need(r9oe_poly_integral(pts, 0, a) == area, "the shaded area is not the area under the curve")
        sh = g["shade"]
        need(len(sh) == 1 and abs(sh[0][0][0]) < 1e-9 and abs(sh[0][-1][0] - a) < 1e-9, "the shading is not from 0 to a")
        whole = r9oe_poly_integral(pts, -a, a)
        segs = r9oe_segs(g["curves"])
        par = "odd" if r9oe_sym(segs, "odd") else ("even" if r9oe_sym(segs, "even") else "neither")
        need(par != "neither", "the graph is neither odd nor even")
        I, v = area, whole
        wrongs = {R9OE_OWN + "9": {label + show(2 * I)}} if par == "odd" else {R9OE_C + "2": {label + "0"}}
    else:
        mm = re.fullmatch(r"f is an (odd|even) function, and ∫ from 0 to (\d) of f\(x\) dx = (−?\d+(?:\.\d+)?)\.", L[0])
        if mm:
            need(int(mm.group(2)) == a, "the limits")
            par, I = mm.group(1), R(mm.group(3).replace("−", "-"))
            need(I != 0, "I = 0")
            if "." in mm.group(3):
                need(paper == 2, "a decimal integral on Paper 1")
                show = dec_text
            # ∫ from −a to 0 of f(x) dx = ∫ from 0 to a of f(−u) du: −I for odd f, I for even f.
            v = I + (-I if par == "odd" else I)
            wrongs = {R9OE_OWN + "9": {label + show(2 * I)}} if par == "odd" else {R9OE_C + "2": {label + "0"}}
        else:
            need(L[0].startswith("f(x) = "), L[0])
            f = r9oe_fn(L[0][7:])
            v = sp.nsimplify(sp.simplify(sp.integrate(f, (X, -a, a))))
            need(v.is_Rational, f"the integral {v} is not exact")
            need(abs(mpmath.quad(sp.lambdify(X, f, "mpmath"), [-a, a]) - mpmath.mpf(sp.N(v, 30))) < 1e-20, "the exact integral disagrees with quadrature")
            fm = f.subs(X, -X)
            ev_part = sp.expand((f + fm) / 2)
            if not r9oe_zero(ev_part):
                wrongs[R9OE_C + "2"] = {label + "0"}
            od_part = sp.expand((f - fm) / 2)
            if not r9oe_zero(od_part) and f.is_polynomial(X):
                wrongs[R9OE_OWN + "9"] = {label + r9oe_t(2 * sp.integrate(f, (X, 0, a)))}
            I = sp.integrate(ev_part, (X, 0, a))
            for st in r9oe_steps(q):
                mt = re.fullmatch(r"2 × \[(.+)\] from 0 to (\d) = 2 × \(?(−?\d+(?:/\d+)?)\)? = (−?\d+(?:/\d+)?)", st)
                if mt:
                    Fx = r9oe_fn(mt.group(1))
                    need(sp.expand(sp.diff(Fx, X) - ev_part) == 0 and Fx.subs(X, 0) == 0, f"{st!r}: not an antiderivative of the even part")
                    need(Fx.subs(X, a) == R(mt.group(3).replace("−", "-")) and 2 * Fx.subs(X, a) == R(mt.group(4).replace("−", "-")), f"{st!r}")
    if paper == 1:
        need(sp.Rational(v) == v, "a Paper 1 integral that is not exact")
    want = label + show(v)
    for st in r9oe_steps(q):
        mt = re.fullmatch(r"∫ from −\d to \d of f\(x\) dx = (.+) = (.+)", st)
        if mt:
            e = mt.group(1).replace("−", "-").replace("×", "*")
            need(sp.nsimplify(sp.sympify(e)) == sp.nsimplify(v), f"{st!r}")
    return want, wrongs


def r9oe_check(q):
    u = q["view"]["unknown"]
    need(q["paper"] in (1, 2), "paper")
    for tx in [q["asked"]] + q["lines"] + r9oe_steps(q) + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
        if q["paper"] == 1:
            need(not re.search(r"(?i)\b(gdc|calculator)\b", tx), f"a calculator on Paper 1: {tx!r}")
    if u in ("classify-polynomial", "classify-mixed"):
        want, wrongs = r9oe_classify(q, u == "classify-mixed")
    elif u == "symmetry-coefficient":
        want, wrongs = r9oe_coefficient(q)
    elif u == "value-from-symmetry":
        want, wrongs = r9oe_value(q)
    elif u == "complete-graph":
        want, wrongs = r9oe_complete(q)
    elif u == "which-graph":
        want, wrongs = r9oe_which(q)
    elif u == "combine-parity":
        want, wrongs = r9oe_combine(q)
    elif u == "symmetric-integral":
        want, wrongs = r9oe_integral(q)
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs)
    return None, None


SITUATION_CHECKS["odd-even"] = r9oe_check

# (between the R9 markers)

# R9-INVERSE: fn-ahl-inverse-restricted (inverse-restricted), prefix R9IR_ / r9ir_

# ── inverse-restricted (fn-ahl-inverse-restricted, FAL-1007) ─────────
# The checker's own reading of the `inverse-restricted` situation: the engine's is in
# game/engine/situations/inverse_restricted.gd. Each rule is read back from the question's
# lines with SymPy, and every answer is worked out again from it: the turning point and the
# side for the largest domain, the next turning point of the wave, the branch of x = f(y)
# that gives back the domain, the range of f, the k that makes f(f(x)) = x, f(f(x)) itself,
# and the real roots of f(x) = x or f(f(x)) = x. Every tagged option is rebuilt from what its
# slip does, and the working's completed squares, derivatives and checks are checked as maths.

R9IR_RD = "AHL2.14.restrict-domain-inverse#"
R9IR_SI = "AHL2.14.self-inverse#"
R9IR_II = "AHL2.14.inverse-intersection#"
R9IR_OWN = "fn-ahl-inverse-restricted#"
R9IR_K = sp.Symbol("k")
R9IR_Y = sp.Symbol("y")
R9IR_SUP = {"⁰": "0", "¹": "1", "²": "2", "³": "3", "⁴": "4", "⁵": "5", "⁶": "6", "⁷": "7", "⁸": "8", "⁹": "9"}
R9IR_YES_ALL = "Yes: f(f(x)) = x for every x in its domain."
R9IR_NO_TIMES = "No: f(x) × f(x) is not 1, so f is not its own inverse."
R9IR_NO_ONE = "No: f is not one-to-one, so it has no inverse."
R9IR_NO_NEVER = "No: a function is never its own inverse."
R9IR_YES_ONE = "Yes: f is one-to-one, so it is its own inverse."
R9IR_YES_ODD = "Yes: f is odd, f(−x) = −f(x), so f is its own inverse."


def r9ir_expr(text, var="x"):
    """An expression as the game writes it: '2(x − 3)² − 4', '√((x + 2)/2)', '−(1/4)x³',
    '2cos(x − π/4) + 1', '(kx + 2)/(x − 4)', '−(x/3)^(1/3)'."""
    t = text.strip().replace("−", "-").replace("½", "(1/2)").replace("π", "pi").replace("^", "**")
    t = re.sub("[⁰¹²³⁴⁵⁶⁷⁸⁹]+([a-z(√])?", lambda m: "**" + "".join(R9IR_SUP[c] for c in m.group().rstrip("abcdefghijklmnopqrstuvwxyz(√"))
               + ("*" + m.group(1) if m.group(1) else ""), t)
    t = t.replace("√(", "sqrt(")
    t = re.sub(r"√([a-z0-9])", r"sqrt(\1)", t)
    need(re.fullmatch(r"[0-9a-z+\-*/(). ]+", t) is not None, f"can't read {text!r}")
    loc = {"x": X, "y": R9IR_Y, "k": R9IR_K, "sqrt": sp.sqrt, "pi": sp.pi, "cos": sp.cos, "sin": sp.sin}
    return parse_expr(t, local_dict=loc, transformations=TRANSFORMS)


def r9ir_n(v):
    """An exact number as the game writes it: '3', '−1/2'."""
    return frac_text(sp.Rational(v))


def r9ir_sf(v):
    v = sp.N(v, 40)
    return "0" if abs(v) < sp.Float("1e-12") else sig3(v).replace("-", "−")


def r9ir_pi(q):
    """A multiple of π as the game writes it: 'π', '5π/6', '−π/2', '2π', '0'."""
    q = sp.Rational(q)
    if q == 0:
        return "0"
    top = "π" if abs(q.p) == 1 else f"{abs(q.p)}π"
    return ("−" if q < 0 else "") + top + ("" if q.q == 1 else f"/{q.q}")


def r9ir_pt(x, y, exact):
    s = r9ir_n if exact else r9ir_sf
    return f"({s(x)}, {s(y)})"


def r9ir_list(ps):
    return ps[0] if len(ps) == 1 else ", ".join(ps[:-1]) + " and " + ps[-1]


def r9ir_same(f, g, xs):
    """f and g agree at every x in xs (both real there)."""
    for x0 in xs:
        a, b = sp.N(f.subs(X, x0), 30), sp.N(g.subs(X, x0), 30)
        if not (a.is_real and b.is_real) or abs(a - b) > sp.Float("1e-20"):
            return False
    return True


def r9ir_steps(q):
    return [st for sol in q["solutions"] for st in sol["steps"]]


def r9ir_in_every(q, text, what):
    for sol in q["solutions"]:
        need(any(text in st for st in sol["steps"]), f"{sol['name']}: the working doesn't show {what} {text!r}")


def r9ir_rule(line):
    """'f(x) = RULE, DOMAIN' -> (RULE text, DOMAIN text or '')."""
    m = re.fullmatch(r"f\(x\) = (.+?)(?:, (.+))?", line)
    need(m is not None, f"can't read the rule {line!r}")
    return m.group(1), m.group(2) or ""


def r9ir_square_steps(q):
    """Each 'Complete the square: A = B' in the working is an identity."""
    for st in r9ir_steps(q):
        m = re.search(r"Complete the square: (.+) = (.+)$", st)
        if m:
            need(sp.expand(r9ir_expr(m.group(1)) - r9ir_expr(m.group(2))) == 0, f"the completed square {st!r} is wrong")


def r9ir_curve(c, fn, tol=1e-6):
    """A sampled curve lies on y = fn(x)."""
    need(len(c) >= 5, "a curve with too few points")
    for x0, y0 in c[:: max(1, len(c) // 12)]:
        v = complex(sp.N(fn.subs(X, sp.Float(x0, 30)), 30))
        need(abs(v.imag) < tol and abs(v.real - y0) < tol * max(1.0, abs(y0)), f"the curve is not the rule at x = {x0}")


def r9ir_choice_texts(q):
    return [o["text"] for o in q["choices"]]


# ── each unknown ─────────────────────────────────────────────

def r9ir_largest(q, wrongs):
    L, asked = q["lines"], q["asked"]
    rule, dom = r9ir_rule(L[0])
    m = re.fullmatch(r"x (≤|≥) a", dom)
    need(m is not None, f"the domain {dom!r}")
    side = m.group(1)
    need(asked == f"Find the {'largest' if side == '≤' else 'smallest'} value of a for which f has an inverse.", f"asked {asked!r}")
    f = r9ir_expr(rule)
    root = rule.startswith("√(")
    inside = r9ir_expr(rule[2:-1]) if root else f
    need(sp.Poly(inside, X).degree() == 2, "the rule is not a quadratic or its root")
    if root:
        need(sp.discriminant(inside, X) < 0 and sp.LC(sp.Poly(inside, X)) > 0, "the root's quadratic is not positive everywhere")
    crit = [c for c in sp.solve(sp.diff(f, X), X) if c.is_real]
    need(len(crit) == 1 and crit[0].is_integer, "f has no single whole turning point")
    h = crit[0]
    # f is one-to-one up to h (or from h): f′ keeps its sign there, and changes it at h.
    d = sp.diff(f, X)
    need(sp.sign(d.subs(X, h - 1)) == -sp.sign(d.subs(X, h + 1)) != 0, "f′ doesn't change sign at the turning point")
    want = "a = " + r9ir_n(h)
    wrongs[R9IR_OWN + "8"] = {"a = 0"}
    wrongs[R9IR_OWN + "10"] = {"a = " + r9ir_n(f.subs(X, h))}
    if not root:
        rs = sorted(r for r in sp.solve(f, X) if r.is_rational)
        if len(rs) == 2:
            wrongs[R9IR_OWN + "9"] = {"a = " + r9ir_n(rs[0] if side == "≤" else rs[1])}
    if q["view"]["rep"] == "graph":
        need(q["graph"] is not None and len(q["graph"]["curves"]) == 1, "no graph of f")
        r9ir_curve(q["graph"]["curves"][0], f)
        need(abs(q["graph"]["curves"][0][0][0] - float(h - 4)) < 1e-9 and abs(q["graph"]["curves"][0][-1][0] - float(h + 4)) < 1e-9, "the graph doesn't show both sides of the turn")
    r9ir_square_steps(q)
    for st in r9ir_steps(q):
        mm = re.match(r"f′\(x\) = (.+), which is 0 where (.+) = 0$", st)
        if mm:
            need(sp.simplify(r9ir_expr(mm.group(1)) - d) == 0, f"the derivative {st!r} is wrong")
            need(sp.solve(r9ir_expr(mm.group(2)), X) == [h], f"{st!r} is not 0 at the turning point")
    r9ir_in_every(q, f"x = {r9ir_n(h)}", "the turning point")
    return want


def r9ir_trig(q, wrongs):
    L, asked = q["lines"], q["asked"]
    need(asked == "Find the largest value of a for which f has an inverse.", f"asked {asked!r}")
    rule, dom = r9ir_rule(L[0])
    m = re.fullmatch(r"(.+) ≤ x ≤ a", dom)
    need(m is not None, f"the domain {dom!r}")
    s = r9ir_expr(m.group(1)) / sp.pi
    need(s.is_rational and s.q in (1, 2, 3, 4, 6, 12) and -1 < s <= sp.Rational(3, 2), f"the start {m.group(1)!r} is not a tidy multiple of π")
    f = r9ir_expr(rule)
    d = sp.diff(f, X)
    need(sp.simplify(d.subs(X, s * sp.pi)) == 0, "the domain doesn't start at a turning point")
    end = s + 1
    need(sp.simplify(d.subs(X, end * sp.pi)) == 0, "no turning point half a period on")
    # No turning point in between: f′ keeps one sign inside.
    signs = {sp.sign(sp.N(d.subs(X, (s + sp.Rational(i, 20)) * sp.pi), 30)) for i in range(1, 20)}
    need(len(signs) == 1 and 0 not in signs, "f turns inside the domain")
    want = "a = " + r9ir_pi(end)
    wrongs[R9IR_OWN + "11"] = {"a = " + r9ir_pi(s + sp.Rational(1, 2)), "a = " + r9ir_pi(s + 2)}
    for st in r9ir_steps(q):
        mm = re.match(r"At x = (.+), f is at its (maximum|minimum), f\((.+)\) = (.+)$", st)
        if mm:
            v = f.subs(X, s * sp.pi)
            need(sp.simplify(v - r9ir_expr(mm.group(4))) == 0, f"{st!r}: the height is wrong")
            need((mm.group(2) == "maximum") == (sp.N(f.subs(X, (s + sp.Rational(1, 2)) * sp.pi)) < v), f"{st!r}: not a {mm.group(2)}")
        mm = re.match(r"f′\(x\) = (.+)$", st)
        if mm and not mm.group(1).startswith("0 "):
            need(sp.simplify(r9ir_expr(mm.group(1)) - d) == 0, f"the derivative {st!r} is wrong")
    r9ir_in_every(q, f"x = {r9ir_pi(end)}", "the next turning point")
    return want


def r9ir_half(q):
    """(f, side, h) from 'f(x) = RULE, x ≥ h': a quadratic whose vertex is at h."""
    rule, dom = r9ir_rule(q["lines"][0])
    m = re.fullmatch(r"x (≤|≥) (−?\d+)", dom)
    need(m is not None, f"the domain {dom!r}")
    f = r9ir_expr(rule)
    h = sp.Integer(m.group(2).replace("−", "-"))
    need(sp.Poly(f, X).degree() == 2, "f is not a quadratic")
    need(sp.diff(f, X).subs(X, h) == 0, "the domain is not cut at the vertex")
    need(f.subs(X, h).is_integer, "the vertex is not whole")
    return f, m.group(1), h


def r9ir_inverse(q, wrongs):
    need(q["asked"] == "Find f⁻¹(x).", f"asked {q['asked']!r}")
    f, side, h = r9ir_half(q)
    k = f.subs(X, h)
    up = sp.LC(sp.Poly(f, X)) > 0
    # Points in the range of f, and the inputs that give them.
    ts = [h + i if side == "≥" else h - i for i in (sp.Rational(1, 2), 1, 2, 3)]
    xs = [f.subs(X, t) for t in ts]
    branches = sp.solve(f.subs(X, R9IR_Y) - X, R9IR_Y)
    need(len(branches) == 2, "x = f(y) has not two branches")
    good = [b for b in branches if all(abs(sp.N(b.subs(X, x0) - t0, 30)) < 1e-20 for x0, t0 in zip(xs, ts))]
    need(len(good) == 1, "no single branch gives back the domain")
    g = good[0]
    bad = [b for b in branches if b is not g][0]
    right = None
    for o in q["choices"]:
        m = re.fullmatch(r"f⁻¹\(x\) = (.+)", o["text"])
        need(m is not None, f"option {o['text']!r}")
        body = m.group(1)
        if "±" in body:
            p_, n_ = r9ir_expr(body.replace("±", "+", 1)), r9ir_expr(body.replace("±", "−", 1))
            if (r9ir_same(p_, g, xs) and r9ir_same(n_, bad, xs)) or (r9ir_same(n_, g, xs) and r9ir_same(p_, bad, xs)):
                wrongs.setdefault(R9IR_RD + "0", set()).add(o["text"])
            continue
        e = r9ir_expr(body)
        if r9ir_same(e, g, xs):
            need(right is None, "two options are f⁻¹")
            right = o["text"]
        elif r9ir_same(e, bad, xs):
            wrongs.setdefault(R9IR_RD + "1", set()).add(o["text"])
    need(right is not None, "no option is f⁻¹")
    r9ir_square_steps(q)
    for st in r9ir_steps(q):
        mm = re.match(r"Swap x and y: x = (.+)$", st)
        if mm:
            need(sp.expand(r9ir_expr(mm.group(1)) - f.subs(X, R9IR_Y)) == 0, f"{st!r} is not x = f(y)")
        mm = re.match(r"Swap x and y and write it as a quadratic in y: (.+) = 0$", st)
        if mm:
            need(sp.expand(r9ir_expr(mm.group(1)) - (f.subs(X, R9IR_Y) - X)) == 0, f"{st!r} is not f(y) − x")
        mm = re.match(r"y = \((.+)\)/(.+), which simplifies to y = (.+)$", st)
        if mm:
            top, den = mm.group(1), r9ir_expr(mm.group(2))
            got = [r9ir_expr(top.replace("±", s_, 1)) / den for s_ in ("+", "−")]
            need(any(r9ir_same(a, g, xs) for a in got) and any(r9ir_same(a, bad, xs) for a in got), f"{st!r}: the formula's two roots are not the branches")
    r9ir_in_every(q, f"y {side} {r9ir_n(h)}", "the domain of f as the inverse's values")
    return right


def r9ir_inverse_domain(q, wrongs):
    need(q["asked"] == "State the domain of f⁻¹.", f"asked {q['asked']!r}")
    f, side, h = r9ir_half(q)
    k = f.subs(X, h)
    up = sp.LC(sp.Poly(f, X)) > 0
    need(k != h, "the vertex's coordinates are the same")
    dir_ = "≥" if up else "≤"
    want = f"x {dir_} {r9ir_n(k)}"
    wrongs[R9IR_RD + "2"] = {f"x {side} {r9ir_n(h)}"}
    wrongs[R9IR_OWN + "10"] = {f"x {dir_} {r9ir_n(h)}"}
    if q["view"]["rep"] == "graph":
        g = q["graph"]
        need(g is not None and len(g["curves"]) == 1, "no graph of f")
        c = g["curves"][0]
        r9ir_curve(c, f)
        need(all((p[0] >= float(h) - 1e-9) if side == "≥" else (p[0] <= float(h) + 1e-9) for p in c), "the graph runs past the domain")
        need(len(g["points"]) == 1 and abs(g["points"][0]["x"] - float(h)) < 1e-9 and abs(g["points"][0]["y"] - float(k)) < 1e-9, "the vertex is not marked")
    r9ir_square_steps(q)
    for sol in q["solutions"]:
        need(any(f"y {dir_} {r9ir_n(k)}" in st or f"c {dir_} {r9ir_n(k)}" in st for st in sol["steps"]), f"{sol['name']}: the working doesn't give the range of f")
    return want


def r9ir_constant(q, wrongs):
    need(q["asked"] == "Find the value of k for which f is its own inverse.", f"asked {q['asked']!r}")
    rule, dom = r9ir_rule(q["lines"][0])
    f = r9ir_expr(rule)
    need(R9IR_K in f.free_symbols, "f has no k")
    ff = sp.together(f.subs(X, f) - X)
    num_ = sp.Poly(sp.numer(ff), X)
    sols = sp.solve(num_.coeffs(), R9IR_K, dict=True)
    # Leave out a k that makes f a constant.
    ks = [s_[R9IR_K] for s_ in sols if sp.diff(f.subs(R9IR_K, s_[R9IR_K]), X) != 0]
    need(len(ks) == 1 and ks[0].is_integer and ks[0] != 0, f"no single whole k makes f its own inverse ({ks})")
    kv = ks[0]
    pole = sp.solve(sp.denom(sp.together(f)), X)
    need(len(pole) == 1, "f has not one excluded value")
    pm = re.fullmatch(r"x ≠ (.+)", dom)
    need(pm is not None and sp.simplify(r9ir_expr(pm.group(1)) - pole[0]) == 0, f"the excluded value {dom!r} is wrong")
    wrongs[R9IR_OWN + "12"] = {"k = " + r9ir_n(-kv)}
    for st in r9ir_steps(q):
        mm = re.match(r"Here a = (.+) and d = (.+), so (.+) = 0$", st)
        if mm:
            a_, d_ = r9ir_expr(mm.group(1)), r9ir_expr(mm.group(2))
            need(sp.simplify(f - (a_ * X + f.subs(X, 0) * d_) / (X + d_)) == 0, f"{st!r}: those are not this f's a and d")
            need(sp.expand(r9ir_expr(mm.group(3)) - (a_ + d_)) == 0 and sp.solve(a_ + d_, R9IR_K) == [kv], f"{st!r} is wrong")
    return "k = " + r9ir_n(kv)


def r9ir_selfq(q, wrongs):
    need(q["asked"] == "Is f its own inverse? Give a reason.", f"asked {q['asked']!r}")
    rule, dom = r9ir_rule(q["lines"][0])
    f = r9ir_expr(rule)
    if dom.startswith("0 ≤ x ≤ "):
        r = r9ir_expr(dom[8:])
        need(sp.simplify(f.subs(X, 0) - r) == 0 and f.subs(X, r) == 0, "the root's domain is not 0 to r")
        xp = sp.Symbol("xp", positive=True)
        ffx = sp.simplify(f.subs(X, f).subs(X, xp)) - xp
        self_inv = sp.simplify(ffx) == 0
        need(self_inv, "a quarter circle that is not its own inverse")
    else:
        if dom:
            pm = re.fullmatch(r"x ≠ (.+)", dom)
            need(pm is not None and sp.solve(sp.denom(sp.together(f)), X) == [r9ir_expr(pm.group(1))], f"the excluded value {dom!r}")
        need(sp.diff(f, X) != 0, "f is a constant")
        self_inv = sp.simplify(f.subs(X, f) - X) == 0
    if self_inv:
        want = R9IR_YES_ALL
    else:
        m = re.fullmatch(r"No: f\(f\((−?[\d/]+)\)\) = (−?[\d/]+), not (−?[\d/]+)\.", q["answer_text"])
        need(m is not None, f"the answer {q['answer_text']!r}")
        v = sp.Rational(m.group(1).replace("−", "-"))
        need(m.group(3) == m.group(1), "the answer's value and its 'not' differ")
        ffv = f.subs(X, f.subs(X, v))
        need(ffv != v, "f(f(v)) is v")
        want = f"No: f(f({r9ir_n(v)})) = {r9ir_n(ffv)}, not {r9ir_n(v)}."
        r9ir_in_every(q, f"f({r9ir_n(v)}) = {r9ir_n(f.subs(X, v))} and f({r9ir_n(f.subs(X, v))}) = {r9ir_n(ffv)}", "the check")
        fixed = [p for p in sp.solve(f - X, X) if p.is_rational]
        wrongs[R9IR_SI + "1"] = {f"Yes: f(f({r9ir_n(p)})) = {r9ir_n(p)}, so f is its own inverse." for p in fixed}
        if sp.simplify(f.subs(X, -X) + f) == 0:
            wrongs[R9IR_SI + "2"] = {R9IR_YES_ODD}
    # Whatever f is, f(x) × f(x) is not 1 for every x here.
    need(sp.simplify(f * f - 1) != 0, "f × f is 1")
    wrongs[R9IR_SI + "0"] = {R9IR_NO_TIMES}
    for o in q["choices"]:
        need(o["correct"] or o["ref"] or o["text"] in (R9IR_NO_ONE, R9IR_NO_NEVER, R9IR_YES_ONE), f"an option that isn't one of the claims: {o['text']!r}")
        if o["text"] in (R9IR_NO_ONE, R9IR_NO_NEVER):
            need(self_inv, f"{o['text']!r} on a function that is not its own inverse")
        if o["text"] == R9IR_YES_ONE:
            need(not self_inv, "'one-to-one, so yes' on a function that is its own inverse")
    # The compose working's top and bottom, where it shows them.
    for st in r9ir_steps(q):
        mm = re.match(r"Multiply the top and the bottom of f\(f\(x\)\) by (.+): the top is (.+) = (.+)$", st)
        if mm:
            mult = r9ir_expr(mm.group(1))
            top = sp.expand(sp.cancel(sp.numer(sp.together(f)).subs(X, f) * mult))
            need(sp.expand(r9ir_expr(mm.group(2))) == sp.expand(r9ir_expr(mm.group(3))) == top, f"{st!r} is wrong")
        mm = re.match(r"The bottom is (.+) = (.+)$", st)
        if mm:
            need(sp.expand(r9ir_expr(mm.group(1))) == r9ir_expr(mm.group(2)), f"{st!r} is wrong")
        mm = re.search(r"[Ss]o f⁻¹\(x\) = (.+?)(?:, |$)", st)
        if mm:
            need(sp.simplify(f.subs(X, r9ir_expr(mm.group(1))) - X) == 0, f"{st!r}: that is not f⁻¹")
    return want


def r9ir_meet_inc(q, wrongs):
    need(q["asked"] == "Find the coordinates of the points where the graphs of y = f(x) and y = f⁻¹(x) meet.", f"asked {q['asked']!r}")
    rule, dom = r9ir_rule(q["lines"][0])
    f = r9ir_expr(rule)
    m = re.fullmatch(r"x ≥ (.+)", dom)
    need(m is not None, f"the domain {dom!r}")
    lo = r9ir_expr(m.group(1))
    root = rule.startswith("√")
    if root:
        need(f.subs(X, lo) == 0, "the root's domain doesn't start where it is 0")
    else:
        need(lo == 0, "the quadratic's domain is not x ≥ 0")
    need(all(sp.N(sp.diff(f, X).subs(X, lo + sp.Rational(i, 4))) > 0 for i in range(1, 40)), "f is not increasing on its domain")
    xs = sorted(r for r in sp.solve(f - X, X) if r.is_real and r >= lo)
    need(len(xs) == 2, "f(x) = x has not two roots in the domain")
    exact = all(r.is_rational for r in xs)
    gdc = q["view"]["angle"] == "gdc-intersect"
    if not exact:
        need(gdc and q["paper"] == 2, "meeting points that need a GDC on a question without one")
    else:
        need(all(r.q in (1, 2) for r in xs), "meeting points that are not whole or halves")
    want = r9ir_list([r9ir_pt(r, r, exact) for r in xs])
    # The 1/f slip: f(x)² = 1, and f(x) ≥ 0 on the domain.
    ones = sorted(r for r in sp.solve(f**2 - 1, X) if r.is_real and r >= lo)
    if not ones:
        wrongs[R9IR_II + "2"] = {"The graphs do not meet: f(x) = ±1 has no solution."}
    elif all(r.is_rational for r in ones) or not exact:
        def show(v):
            if exact:
                return r9ir_n(v)
            return dec_text(v) if v.is_rational and "/" not in dec_text(v) else r9ir_sf(v)
        wrongs[R9IR_II + "2"] = {r9ir_list([f"({show(r)}, 1)" for r in ones])}
    if q["view"]["rep"] == "graph":
        g = q["graph"]
        need(g is not None and len(g["curves"]) == 3, "the graph is not f, f⁻¹ and y = x")
        r9ir_curve(g["curves"][0], f)
        need(all(abs(sp.N(f.subs(X, sp.Float(p[1], 30)) - p[0])) < 1e-6 for p in g["curves"][1][::10]), "the second curve is not f⁻¹")
        need(all(abs(p[0] - p[1]) < 1e-9 for p in g["curves"][2]), "the third line is not y = x")
    for st in r9ir_steps(q):
        mm = re.search(r"gives (.+) = 0$", st)
        if mm:
            need(set(sp.solve(r9ir_expr(mm.group(1)), X)) == set(xs), f"{st!r}: its roots are not the meeting points")
        mm = re.match(r"x = \((\d+) ± √(\d+)\)/2", st)
        if mm:
            need({(int(mm.group(1)) + s_ * sp.sqrt(int(mm.group(2)))) / 2 for s_ in (1, -1)} == set(xs), f"{st!r} is wrong")
    for r in xs:
        r9ir_in_every(q, f"x = {r9ir_n(r) if exact else r9ir_sf(r)}", "the root")
    return want


def r9ir_meet_dec(q, wrongs):
    need(q["asked"] == "Find the coordinates of every point where the graphs of y = f(x) and y = f⁻¹(x) meet.", f"asked {q['asked']!r}")
    rule, dom = r9ir_rule(q["lines"][0])
    need(dom == "", "a decreasing f with a domain")
    f = r9ir_expr(rule)
    need(sp.simplify(f.subs(X, -X) + f) == 0, "f is not odd")
    need(all(sp.diff(f, X).subs(X, v) <= 0 for v in (-2, -1, 0, 1, 2)) and sp.diff(f, X).subs(X, 1) < 0, "f is not decreasing")
    xs = sorted(r for r in sp.solve(sp.expand(f.subs(X, f) - X), X) if r.is_real)
    need(len(xs) == 3, "f(f(x)) = x has not three real roots")
    exact = all(r.is_rational for r in xs)
    if not exact:
        need(q["view"]["angle"] == "gdc-intersect" and q["paper"] == 2, "meeting points that need a GDC on a question without one")
    want = r9ir_list([r9ir_pt(r, f.subs(X, r), exact) for r in xs])
    on = sorted(r for r in sp.solve(f - X, X) if r.is_real)
    wrongs[R9IR_II + "0"] = {r9ir_list([r9ir_pt(r, r, exact) for r in on]) + (" only" if len(on) == 1 else "")}
    if q["view"]["rep"] == "graph":
        g = q["graph"]
        need(g is not None and len(g["curves"]) == 3, "the graph is not f, f⁻¹ and y = x")
        r9ir_curve(g["curves"][0], f)
        need(all(abs(float(sp.N(f.subs(X, sp.Float(p[1], 30)))) - p[0]) < 1e-6 for p in g["curves"][1][::10]), "the second curve is not f⁻¹")
        need(all(abs(p[0] - p[1]) < 1e-9 for p in g["curves"][2]), "the third line is not y = x")
        e = max(abs(float(r)) for r in xs)
        need(g["x1"] >= e + 0.5 and g["y1"] >= e + 0.5, "the meeting points are off the grid")
    for st in r9ir_steps(q):
        mm = re.match(r"Swap x and y: x = .+, so f⁻¹\(x\) = (.+)$", st)
        if mm:
            gi = r9ir_expr(mm.group(1))
            for v in (sp.Rational(1, 3), 2, 5):
                need(abs(sp.N(f.subs(X, gi.subs(X, v)) - v, 30)) < 1e-20, f"{st!r}: that is not f⁻¹")
        mm = re.search(r"and f\(f\(x\)\) = (.+) = (.+)$", st)
        if mm:
            need(sp.expand(r9ir_expr(mm.group(1)) - f.subs(X, f)) == 0 and sp.expand(r9ir_expr(mm.group(2)) - f.subs(X, f)) == 0, f"{st!r}: that is not f(f(x))")
    return want


def r9ir_check(q):
    u, rep = q["view"]["unknown"], q["view"]["rep"]
    texts = [q["asked"]] + q["lines"] + r9ir_steps(q) + r9ir_choice_texts(q)
    for tx in texts:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    if q["paper"] == 1:
        need(not any("GDC" in s["name"] or s["angle"].startswith("gdc-") for s in q["solutions"]), "a calculator working on Paper 1")
    wrongs = {}
    if u == "largest-domain":
        want = r9ir_largest(q, wrongs)
    elif u == "largest-domain-trig":
        want = r9ir_trig(q, wrongs)
    elif u == "inverse-restricted":
        want = r9ir_inverse(q, wrongs)
    elif u == "inverse-domain":
        want = r9ir_inverse_domain(q, wrongs)
    elif u == "self-inverse-constant":
        want = r9ir_constant(q, wrongs)
    elif u == "is-self-inverse":
        want = r9ir_selfq(q, wrongs)
    elif u == "meet-increasing":
        want = r9ir_meet_inc(q, wrongs)
    elif u == "meet-decreasing":
        want = r9ir_meet_dec(q, wrongs)
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs)
    return None, None


SITUATION_CHECKS["inverse-restricted"] = r9ir_check

