def r9ac_pat(template):
    return re.escape(template).replace("%s", "(.+?)")


def r9ac_match(template, text):
    m = re.fullmatch(r9ac_pat(template), text)
    return m.groups() if m else None


def r9ac_n(text):
    t = text.strip()
    need(re.fullmatch(r"−?\d+(\.\d+)?", t) is not None, f"{t!r} is not a number as the game writes one")
    return R(t.replace("−", "-"))


def r9ac_expr(text, var):
    """A rule as the game writes it, read with SymPy: "0.02n² + 3n + 150", "2.5 + 600/n",
    "4 + 2.5 ln p", "e^((x − 4)/2.5)", "(e^x − 4)/2.5", "1/(2.2x + 4)"."""
    s = text.replace("−", "-").replace("²", "**2").replace("³", "**3").replace("^", "**")
    s = re.sub(r"√([a-z])", r"sqrt(\1)", s).replace("√(", "sqrt(")
    # Only the rule's own letter may be a capital (T, C), so no other name slips through.
    need(re.fullmatch(r"[0-9a-zA-Z.+\-*/() ]+", s) is not None
         and not re.search(r"[A-Z]", re.sub(rf"(?<![A-Za-z]){var}(?![A-Za-z])", "", s)), f"can't read the rule {text!r}")
    s = re.sub(r"ln ([a-zA-Z])", r"ln(\1)", s)
    s = re.sub(r"(\d)\s*([a-zA-Z(])", r"\1*\2", s)
    s = re.sub(r"\)\s*([a-zA-Z0-9(])", r")*\1", s)
    s = s.replace("ln(", "log(")
    s = re.sub(r"(?<![a-z_])e\*\*", "E**", s)
    s = re.sub(r"(\d+(?:\.\d+)?)", r"Rational('\1')", s)
    loc = {"Rational": sp.Rational, "log": sp.log, "sqrt": sp.sqrt, "E": sp.E, var: sp.Symbol(var)}
    e = sp.sympify(s, locals=loc)
    need(e.free_symbols <= {sp.Symbol(var)}, f"the rule {text!r} is not in {var}")
    return e


def r9ac_same(a, b):
    return sp.simplify(a - b) == 0


def r9ac_exact(v):
    """Whether the game writes v exactly: a rational with two decimal places at most."""
    return isinstance(v, sp.Rational) and (v * 100).is_integer and abs(v) < 10**6


def r9ac_f(v):
    """v as gc_s takes it: a rational as it is, anything else as a 30-digit float."""
    return v if isinstance(v, sp.Rational) else sp.Float(sp.N(v, 30), 30)


def r9ac_show(v):
    return dec_text(v) if r9ac_exact(v) else gc_s(r9ac_f(v))


def r9ac_opt(v, exact):
    """A wrong value as an option shows it: as the answer is shown (exact, or 3 s.f.)."""
    if not exact:
        return gc_s(r9ac_f(v))
    return dec_text(v) if r9ac_exact(v) else dec_text(sp.Rational(sig3(v)))


def r9ac_fair(v):
    """The value is shown exactly, or clear of a 3 s.f. rounding edge."""
    if r9ac_exact(v):
        return True
    x = num(v)
    e = sp.floor(sp.log(abs(x), 10))
    scaled = abs(x) / sp.Integer(10) ** (e - 2)
    return abs(scaled - sp.floor(scaled) - sp.Rational(1, 2)) >= sp.Rational(39, 1000)


def r9ac_line(points):
    """The line through the graph's first two marked points, checked against the others."""
    (x0, y0), (x1, y1) = [(R(p["x"]), R(p["y"])) for p in points[:2]]
    m = (y1 - y0) / (x1 - x0)
    T = sp.Symbol("T")
    g = y0 + m * (T - x0)
    for p in points:
        need(abs(float(g.subs(T, R(p["x"]))) - p["y"]) < 1e-9, f"the point {p['label']} is not on the line")
        need(p["label"] == f"({dec_text(sp.nsimplify(p['x']))}, {dec_text(sp.nsimplify(p['y']))})", f"the label {p['label']!r} is not its point")
    return g, T


def r9ac_graph_g(q, var):
    """The inner model read off its graph: the line through its marked points, drawn as a curve."""
    gr = q["graph"]
    need(gr is not None and gr["points"], "no graph")
    gT, T = r9ac_line(gr["points"])
    need(gc_curve_is(gr["curves"][0], lambda x: float(gT.subs(T, sp.Float(x, 20)))), "the curve is not the line through its points")
    need(gr["x0"] == 0 and abs(gr["curves"][0][-1][0] - gr["x1"]) < 1e-9, "the line is not drawn from 0 across the window")
    return sp.expand(gT.subs(T, sp.Symbol(var))), {R(p["x"]): R(p["y"]) for p in gr["points"]}


def r9ac_story(q, with_g=True):
    """The story, g (in its input letter) and f (in g's letter), read from the lines."""
    L, rep = q["lines"], q["view"]["rep"]
    for key, row in R9AC_STORY.items():
        gl, v = row[0], row[1]
        mf = r9ac_match(row[6], L[1]) if len(L) > 1 else None
        if mf is None:
            continue
        f = r9ac_expr(mf[0], gl)
        if rep == "table":
            need(L[0] == f"The table gives {row[7]}.", f"{L[0]!r}")
            return key, row, None, f
        if rep == "graph":
            need(L[0] == f"The graph shows {row[7]}.", f"{L[0]!r}")
            return key, row, None, f
        mg = r9ac_match(row[5], L[0])
        need(mg is not None, f"can't read {L[0]!r}")
        return key, row, r9ac_expr(mg[0], v), f
    raise Fail(f"no story reads {L!r}")


def r9ac_steps_have(q, angle, pattern):
    for sol in q["solutions"]:
        if sol["angle"] == angle:
            need(any(re.search(pattern, st) for st in sol["steps"]), f"{angle}: no step matches {pattern!r}")


def r9ac_pick(q, exprs, var, prefix="", suffix=""):
    """For rule options: the option texts whose rule is each expression. exprs: name -> expr."""
    out = {k: set() for k in exprs}
    for o in q["choices"]:
        t = o["text"]
        need(t.startswith(prefix) and t.endswith(suffix), f"option {t!r} is not {prefix}…{suffix}")
        body = t[len(prefix):len(t) - len(suffix)] if suffix else t[len(prefix):]
        e = r9ac_expr(body, var)
        for k, want in exprs.items():
            if want is not None and r9ac_same(e, want):
                out[k].add(t)
    return out


def r9ac_check(q):
    u, L, asked, rep = q["view"]["unknown"], q["lines"], q["asked"], q["view"]["rep"]
    need(q["paper"] == 2, "every AI question is Paper 2")
    for tx in [asked] + L + [st for sol in q["solutions"] for st in sol["steps"]] + [o["text"] for o in q["choices"]]:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    wrongs, want, trap = {}, None, None
    X_ = sp.Symbol("x")
    if u in ("composite-value", "composite-equation", "composite-rule") and not (u == "composite-rule" and rep == "equation"):
        key, row, g, f = r9ac_story(q)
        gl, v, unit_in, fl, unit_out = row[:5]
        V, G = sp.Symbol(v), sp.Symbol(gl)
    if u == "composite-value":
        x0 = r9ac_n(r9ac_match(row[10], asked)[0])
        if rep == "words":
            gx = g.subs(V, x0)
        elif rep == "table":
            t = q["table"]["rows"]
            need(t[0][0] == v and t[1][0] == f"{gl}({v})", "the table's heads")
            col = dict(zip([r9ac_n(c) for c in t[0][1]], [r9ac_n(c) for c in t[1][1]]))
            need(x0 in col, "the input is not in the table")
            gx = col[x0]
        else:
            g, pts = r9ac_graph_g(q, v)
            need(x0 in pts, "the input's point is not marked on the graph")
            gx = pts[x0]
        val = f.subs(G, gx)
        need(val > 0, "the story's value is not positive")
        need(r9ac_exact(val), "the value does not end")
        want = f"{dec_text(val)} {unit_out}"
        wrongs[R9AC_CC + "1"] = {f"{r9ac_opt(f.subs(G, x0) * gx, True)} {unit_out}"}
        if rep == "words":
            wrongs[R9AC_CC + "0"] = {f"{r9ac_opt(g.subs(V, f.subs(G, x0)), True)} {unit_out}"}
        r9ac_steps_have(q, "inside-out", re.escape(f"{fl}({dec_text(gx)}) = ") + r".* = " + re.escape(dec_text(val)) + r"\.$")
    elif u == "composite-equation":
        target = r9ac_n(r9ac_match(row[11], asked)[0])
        if rep == "graph":
            g, pts = r9ac_graph_g(q, v)
        h = sp.expand(f.subs(G, g))
        ts = sp.solve(sp.Eq(h, target), V)
        need(len(ts) == 1 and ts[0] > 0, "no single positive input")
        t = ts[0]
        mid = sp.solve(sp.Eq(f, target), G)[0]
        if rep == "graph":
            need(t in pts and pts[t] == mid, "the graph does not mark the point the working reads")
        need(r9ac_fair(t), "the answer is on a 3 s.f. edge")
        exact = r9ac_exact(t)
        want = f"{v} = {r9ac_show(t)} {unit_in}"
        trap = None if exact else f"{v} = {gc_s2(r9ac_f(t))} {unit_in}"
        slip = sp.solve(sp.Eq(sp.expand(g.subs(V, f.subs(G, V))), target), V)[0]
        if slip > 0:
            wrongs[R9AC_CC + "0"] = {f"{v} = {r9ac_opt(slip, exact)} {unit_in}"}
        else:
            need(not any(o["ref"] == R9AC_CC + "0" for o in q["choices"]), "a negative time is offered as the order slip")
        r9ac_steps_have(q, "substitute-expression", re.escape(f"{fl}({gl}({v})) = ") + r".* = (.+)\.$")
        for sol in q["solutions"]:
            if sol["angle"] == "substitute-expression":
                m = [re.search(re.escape(f"{fl}({gl}({v})) = ") + r".* = ([^=]+)\.$", st) for st in sol["steps"]]
                m = [x for x in m if x]
                need(m and r9ac_same(r9ac_expr(m[0].group(1), v), h), f"the composite in the working is not {h}")
    elif u == "composite-rule":
        if rep == "equation":
            for key, row in R9AC_STORY.items():
                mg = r9ac_match(row[8], L[0])
                mf = r9ac_match(row[9], L[1]) if mg else None
                if mf:
                    break
            need(mg and mf, f"can't read {L!r}")
            v = row[1]
            V = sp.Symbol(v)
            g, f, G = r9ac_expr(mg[0], v), r9ac_expr(mf[0], "x"), X_
            need(asked == f"Find (f∘g)({v}) as a rule in {v}.", f"asked {asked!r}")
        else:
            need(asked == row[12], f"asked {asked!r}")
        h = sp.expand(f.subs(G, g))
        swapped = sp.expand(g.subs(V, f.subs(G, V)))
        exprs = {"right": h, R9AC_CC + "0": swapped}
        p = sp.Poly(f, G)
        if p.degree() == 2:
            a2, b2, c2 = p.all_coeffs()
            exprs[R9AC_CC + "2"] = sp.expand(a2 * g**2 + b2 * V + c2)
        else:
            need(not any(o["ref"] == R9AC_CC + "2" for o in q["choices"]), "the one-x slip on a line, which has one x")
        got = r9ac_pick(q, exprs, v)
        need(len(got["right"]) == 1, "not exactly one option is the composite")
        want = next(iter(got["right"]))
        wrongs = {k: got[k] for k in exprs if k != "right"}
    elif u == "composite-order":
        m1 = re.fullmatch(r"A trader takes (\d+)% off a price of x caps: D\(x\) = (.+)x\.", L[0])
        need(m1 is not None, f"{L[0]!r}")
        pct, m = int(m1.group(1)), r9ac_n(m1.group(2))
        need(m == 1 - sp.Rational(pct, 100), "D's multiplier is not the percentage")
        mv = re.fullmatch(r"A voucher takes (\d+) caps off a price of x caps: V\(x\) = x − (\d+)\.", L[1])
        mfe = re.fullmatch(r"A trading fee adds (\d+) caps to a price of x caps: F\(x\) = x \+ (\d+)\.", L[1])
        need((mv or mfe) is not None, f"{L[1]!r}")
        mm = mv or mfe
        need(mm.group(1) == mm.group(2), "the rule's amount is not the story's")
        Lt, c = ("V", -R(mm.group(1))) if mv else ("F", R(mm.group(1)))
        mp = re.fullmatch(r"An item is priced at (\d+) caps\.", L[2])
        need(mp is not None, f"{L[2]!r}")
        P = R(mp.group(1))
        ma = re.fullmatch(rf"Which order of D and {Lt} gives the (lower|higher) final price for the item, and what is it\?", asked)
        need(ma is not None, f"asked {asked!r}")
        word = ma.group(1)
        ld, dl = m * P + c, m * (P + c)
        need(ld != dl, "the orders agree")
        n_ld, n_dl = f"({Lt}∘D)({P})", f"(D∘{Lt})({P})"
        first = (ld < dl) == (word == "lower")
        than = "lower than" if word == "lower" else "higher than"
        claim = lambda n1, v1, n2, v2: f"{n1} = {dec_text(v1)} caps, {than} {n2} = {dec_text(v2)} caps"
        want = claim(n_ld, ld, n_dl, dl) if first else claim(n_dl, dl, n_ld, ld)
        wrongs[R9AC_CC + "3"] = {f"Either order: both give {dec_text(ld if first else dl)} caps"}
    elif u in ("inverse-rule", "inverse-value", "inverse-identity"):
        words = rep == "words" and u == "inverse-rule"
        for key, row in R9AC_MODEL.items():
            if words and row[4]:
                mw = r9ac_match(row[4][0], L[0])
                if mw:
                    vals = dict(zip(row[4][1], [r9ac_n(t) for t in mw]))
                    break
            else:
                mw = r9ac_match(row[3], L[0])
                if mw:
                    break
        need(mw is not None, f"can't read {L[0]!r}")
        F, v, fam = row[0], row[1], row[2]
        Vs = sp.Symbol(v)
        if words:
            f = {"lin": lambda: vals["m"] * X_ + vals["b"], "rat": lambda: vals["c"] + vals["k"] / X_,
                 "log": lambda: vals["a"] + vals["b"] * sp.log(X_)}[fam]()
        else:
            f = r9ac_expr(mw[0], v).subs(Vs, X_)
        Y = sp.Symbol("y", positive=True)
        if fam != "cubic":
            sols = sp.solve(sp.Eq(f.subs(X_, Y), X_), Y)
            need(len(sols) == 1, f"no single inverse of {f}")
            finv = sols[0]
            consts = sp.Poly(f, X_).all_coeffs() if fam == "lin" else None
        if u == "inverse-rule":
            if fam == "lin":
                mm_, bb = consts
                order = X_ / mm_ - bb
            elif fam == "rat":
                cc = f.subs(X_, sp.oo)
                kk = sp.simplify((f - cc) * X_)
                order = kk / X_ - cc
            else:
                aa = f.subs(X_, 1)
                bb = sp.simplify((f - aa) / sp.log(X_))
                order = (sp.exp(X_) - aa) / bb
            suffix = f", {row[5]}" if words else ""
            need(asked == (f"Find {F}⁻¹(x) and state what it calculates." if words else f"Find {F}⁻¹(x)."), f"asked {asked!r}")
            if words:
                for o in q["choices"]:
                    need(o["text"].endswith(", " + row[5]) or o["text"].endswith(", " + row[6]), f"{o['text']!r} says nothing it calculates")
                plain = [o for o in q["choices"] if o["text"].endswith(", " + row[6])]
                need(all(not o["ref"] for o in plain), "a wrong meaning is tagged with a rule's slip")
            mine = [o for o in q["choices"] if o["text"].endswith(suffix)]
            got = r9ac_pick(dict(q, choices=mine), {"right": finv, R9AC_FI + "0": 1 / f, R9AC_FI + "1": order}, "x", f"{F}⁻¹(x) = ", suffix)
            need(len(got["right"]) == 1, "not exactly one option is the inverse with what it calculates")
            want = next(iter(got["right"]))
            wrongs = {k: got[k] for k in got if k != "right"}
            for o in q["choices"]:
                if o["text"] != want and o["text"].endswith(suffix) and not words:
                    need(not r9ac_same(r9ac_expr(o["text"][len(f"{F}⁻¹(x) = "):], "x"), finv), f"{o['text']!r} is the inverse too")
        elif u == "inverse-value":
            if rep == "words":
                vv = r9ac_n(r9ac_match(row[7], asked)[0])
                label, unit = "", row[8]
            else:
                ma = re.fullmatch(rf"Find {F}⁻¹\((.+)\)\.", asked)
                need(ma is not None, f"asked {asked!r}")
                vv = r9ac_n(ma.group(1))
                label, unit = f"{F}⁻¹({dec_text(vv)}) = ", ""
            if fam == "cubic":
                need(sp.diff(f, X_).subs(X_, 0) > 0 and all(c >= 0 for c in sp.Poly(f, X_).all_coeffs()), "the tank's model is not increasing")
                rs = [r for r in sp.Poly(f - vv, X_).nroots(n=30) if r.is_real and r > 0]
                need(len(rs) == 1, "no single depth")
                x = sp.Float(rs[0], 30)
                r = sp.nsimplify(x, tolerance=1e-20, rational=True)
                if f.subs(X_, r) == vv:
                    x = r
            else:
                x = sp.nsimplify(finv.subs(X_, vv)) if fam != "log" else finv.subs(X_, vv)
                need(x.is_positive, "the inverse's value is not positive")
            need(r9ac_fair(x), "the answer is on a 3 s.f. edge")
            exact = r9ac_exact(x)
            want = f"{label}{r9ac_show(x)}{unit}"
            trap = None if exact else f"{label}{gc_s2(r9ac_f(x))}{unit}"
            fv = f.subs(X_, vv)
            wrongs[R9AC_FI + "2"] = {f"{label}{r9ac_opt(fv, exact)}{unit}"}
            if abs(num(1 / fv)) >= sp.Rational(1, 1000):
                wrongs[R9AC_FI + "0"] = {f"{label}{r9ac_opt(1 / fv, exact)}{unit}"}
            if fam == "lin":
                mm_, bb = consts
                wrongs[R9AC_FI + "1"] = {f"{label}{r9ac_opt(vv / mm_ - bb, exact)}{unit}"}
            elif fam == "rat":
                cc = f.subs(X_, sp.oo)
                kk = sp.simplify((f - cc) * X_)
                wrongs[R9AC_FI + "1"] = {f"{label}{r9ac_opt(kk / vv - cc, exact)}{unit}"}
            elif fam == "log":
                aa = f.subs(X_, 1)
                bb = sp.simplify((f - aa) / sp.log(X_))
                wrongs[R9AC_FI + "1"] = {f"{label}{r9ac_opt(sp.N((sp.exp(vv) - aa) / bb, 30), exact)}{unit}"}
            if not exact:
                r9ac_steps_have(q, "solve-for-value", re.escape(f"gives {v} = {r9ac_work(x)}."))
        else:
            if len(L) == 1:
                ma = re.fullmatch(rf"Write down \({F}∘{F}⁻¹\)\((.+)\)\.", asked)
                need(ma is not None, f"asked {asked!r}")
                vv = r9ac_n(ma.group(1))
                need(finv.subs(X_, vv).is_positive, "the value is not in the range of the model")
                label = f"({F}∘{F}⁻¹)({dec_text(vv)}) = "
                need(sp.simplify(f.subs(X_, finv) - X_) == 0, "f∘f⁻¹ is not the identity")
                want = label + dec_text(vv)
                wrongs[R9AC_II + "0"] = {label + "1"}
            else:
                mb = re.fullmatch(rf"{F}⁻¹\(a\) = (.+), where a is a constant\.", L[1])
                need(mb is not None and asked == "Find a.", f"{L[1]!r} / {asked!r}")
                b = r9ac_n(mb.group(1))
                a = sp.nsimplify(f.subs(X_, b))
                need(finv.subs(X_, a) == b, "f⁻¹(a) is not b")
                need(r9ac_fair(a), "a is on a 3 s.f. edge")
                exact = r9ac_exact(a)
                want = f"a = {r9ac_show(a)}"
                trap = None if exact else f"a = {gc_s2(r9ac_f(a))}"
                wrongs[R9AC_II + "1"] = {f"a = {r9ac_opt(sp.nsimplify(finv.subs(X_, b)), exact)}"}
    elif u == "restrict-domain":
        for key, (F, tmpl) in R9AC_QUAD.items():
            mq = r9ac_match(tmpl + ".", L[0])
            if mq:
                break
        need(mq is not None, f"can't read {L[0]!r}")
        f = r9ac_expr(mq[0], "x")
        p = sp.Poly(f, X_)
        need(p.degree() == 2, "not a quadratic")
        a2, b2, c2 = p.all_coeffs()
        h = -b2 / (2 * a2)
        k = f.subs(X_, h)
        need(h > 0, "the vertex is not inside the story's domain")
        need(asked == f"Find the least value of k for which {F} has an inverse on the domain x ≥ k.", f"asked {asked!r}")
        want = f"k = {dec_text(h)}"
        wrongs = {R9AC_RD + "2": {"k = 0"}, R9AC_VERTEX_Y: {f"k = {dec_text(k)}"}}
        if rep == "graph":
            need(L[1] == f"The graph of y = {F}(x) is shown.", f"{L[1]!r}")
            gr = q["graph"]
            need(gc_curve_is(gr["curves"][0], lambda x: float(f.subs(X_, sp.Float(x, 20)))), "the curve is not the model")
            marks = {(R(p_["x"]), R(p_["y"])): p_["label"] for p_ in gr["points"]}
            need(marks.get((h, k)) == f"({dec_text(h)}, {dec_text(k)})", "the vertex is not marked")
            need(marks.get((0, c2)) == f"(0, {dec_text(c2)})", "the y-intercept is not marked")
            need(gr["curves"][0][0][0] == 0 and gr["curves"][0][-1][0] > float(h), "the curve does not run past the vertex")
            r9ac_steps_have(q, q["view"]["angle"], re.escape(f"the vertex is at ({dec_text(h)}, {dec_text(k)})."))
        else:
            r9ac_steps_have(q, q["view"]["angle"], re.escape(f"= {dec_text(h)}."))
    elif u == "inverse-domain-range":
        mw = re.fullmatch(r"Write down the (domain|range) of ([A-Za-z])⁻¹\.", asked)
        need(mw is not None, f"asked {asked!r}")
        what, F = mw.groups()
        inv = F + "⁻¹"
        got = None
        for key, (Fq, tmpl) in R9AC_QUAD.items():
            mq = r9ac_match(tmpl + ", for x ≥ %s.", L[0])
            if mq:
                f = r9ac_expr(mq[0], "x")
                h = r9ac_n(mq[1])
                p = sp.Poly(f, X_)
                a2, b2, _ = p.all_coeffs()
                need(-b2 / (2 * a2) == h and Fq == F, "the domain does not start at the vertex")
                k = f.subs(X_, h)
                rel = "≥" if a2 > 0 else "≤"
                dom_f, ran_f = f"x ≥ {dec_text(h)}", f"x {rel} {dec_text(k)}"
                got = (ran_f, f"{inv}(x) ≥ {dec_text(h)}", dom_f)
                break
        if got is None:
            for key, (Fl, vl, tmpl) in R9AC_LINE.items():
                ml = r9ac_match(tmpl, L[0])
                if ml:
                    f = r9ac_expr(ml[0], vl).subs(sp.Symbol(vl), X_)
                    lo, hi = r9ac_n(ml[1]), r9ac_n(ml[2])
                    y0, y1 = sorted([f.subs(X_, lo), f.subs(X_, hi)])
                    need(Fl == F, "the letter is not the model's")
                    got = (f"{dec_text(y0)} ≤ x ≤ {dec_text(y1)}", f"{dec_text(lo)} ≤ {inv}(x) ≤ {dec_text(hi)}", f"{dec_text(lo)} ≤ x ≤ {dec_text(hi)}")
                    break
        need(got is not None, f"can't read {L[0]!r}")
        want = got[0] if what == "domain" else got[1]
        if what == "domain":
            wrongs[R9AC_RD + "0"] = {got[2]}
    elif u == "inverse-graph":
        m = re.fullmatch(r"f\(x\) = (.+?)(?:, for x ≥ (−?\d+))?", L[0])
        need(m is not None and L[1] == "The graph of y = f(x) is shown, with its key points marked.", f"{L!r}")
        f = r9ac_expr(m.group(1), "x")
        base = q["graph"]["curves"][0]
        need(gc_curve_is(base, lambda x: float(f.subs(X_, sp.Float(x, 20)))), "the graph drawn is not f")
        if m.group(2):
            need(abs(base[0][0] - float(r9ac_n(m.group(2)))) < 1e-9, "half the parabola does not start at its vertex")
        xs, ys = [p_[0] for p_ in base], [p_[1] for p_ in base]
        need(all(b_ > a_ for a_, b_ in zip(xs, xs[1:])) and (all(b_ > a_ for a_, b_ in zip(ys, ys[1:])) or all(b_ < a_ for a_, b_ in zip(ys, ys[1:]))),
             "f is not one-to-one on the graph")
        graphs, ch = q["graphs"], q["choices"]
        need(len(graphs) == 4 and len(ch) == 4, "pick the graph needs four graphs")
        need(len({json.dumps(gr["curves"]) for gr in graphs}) == 4, "two graphs are the same")
        moves = {"x-axis": lambda c: (c[0], -c[1]), "y-axis": lambda c: (-c[0], c[1]), "y=-x": lambda c: (-c[1], -c[0])}
        for o, gr in zip(ch, graphs):
            if o["correct"]:
                need(bo_card_is(gr, base, lambda c: (c[1], c[0])), "the right graph is not f reflected in y = x")
            else:
                mk = o["mistake"]
                need(mk in moves and bo_card_is(gr, base, moves[mk]), f"the {mk} graph is not that reflection")
                need(o["why"] != "", "a wrong graph doesn't say what is wrong")
                need(o["ref"] == ("" if mk == "y=-x" else R9AC_II + "2"), f"the {mk} graph is tagged {o['ref']!r}")
        want = next(o["text"] for o in ch if o["correct"])
        wrongs = {R9AC_II + "2": {o["text"] for o in ch if o["ref"]}}
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs, trap)
    return None, None


def r9ac_work(x):
    """A GDC value as the working writes it: 6 s.f. with no trailing zeros."""
    t = sig3(x, 6)
    if "." in t:
        t = t.rstrip("0").rstrip(".")
    return t.replace("-", "−")


SITUATION_CHECKS["ai-composite-inverse"] = r9ac_check


# (end of the R9 markers)


# R10-MODULUS-EQUATION: fn-ahl-modulus-equations, prefix MODEQ_ / modeq_

# ── modulus-equation (fn-ahl-modulus-equations, FAL-1008) ─────────
# The checker's own reading of the `modulus-equation` situation: the engine's is in
# game/engine/situations/modulus_equation.gd. Each equation or inequality is read back from
# the question's lines with SymPy and solved again: the roots of a modulus against a constant,
# a modulus or a line (solveset over the reals, so a false root never gets in), the number of
# solutions of |f(x)| = k and the k for three or four, the solution set of an inequality, and
# for |f(x)| against a line on a domain the crossings (exact for a quadratic, found by sign
# changes and mpmath for a trig f) and the set they cut out. Every tagged option is rebuilt
# from what its slip does, and the working's cases, squares, factors, checks and GDC readings
# are checked as maths.

MODEQ_EQ = "AHL2.16.modulus-equation#"
MODEQ_IN = "AHL2.16.modulus-inequality#"
MODEQ_OWN = "fn-ahl-modulus-equations#"
MODEQ_X = sp.Symbol("x", real=True)
MODEQ_RELS = ("≤", "≥", "<", ">")
MODEQ_FLIP = {"<": ">", "≤": "≥", ">": "<", "≥": "≤"}
MODEQ_TOL = 1e-6


def modeq_expr(text):
    """An expression as the game writes it: '|3x − 2|', '−3x + 5', '2|x + 3|', '−½x + 4',
    'x² − 11x + 22', '2sin x − 1', '−(x − 2)(x − 6)'."""
    t = text.strip().replace("−", "-").replace("½", "(1/2)").replace("²", "**2").replace("π", "pi")
    t = re.sub(r"(sin|cos) x", r"\1(x)", t)
    t = re.sub(r"\|([^|]+)\|", r"Abs(\1)", t)
    need("|" not in t, f"can't read the moduli in {text!r}")
    need(re.fullmatch(r"[0-9xAbsincopi+\-*/(). ]+", t) is not None, f"can't read {text!r}")
    loc = {"x": MODEQ_X, "Abs": sp.Abs, "sin": sp.sin, "cos": sp.cos, "pi": sp.pi}
    return parse_expr(t, local_dict=loc, transformations=TRANSFORMS)


def modeq_n(v):
    """An exact number as the game writes it: '3', '−13/4'."""
    return frac_text(sp.Rational(v))


def modeq_sf(v):
    return sig3(sp.N(v, 40)).replace("-", "−")


def modeq_xs(vals):
    """An xs answer: 'x = −1 or 15', 'x = 3'."""
    return "x = " + " or ".join(modeq_n(v) for v in sorted(set(vals)))


def modeq_steps(q):
    return [st for sol in q["solutions"] for st in sol["steps"]]


def modeq_in_every(q, text, what):
    for sol in q["solutions"]:
        need(any(text in st for st in sol["steps"]), f"{sol['name']}: the working doesn't show {what} {text!r}")


def modeq_roots(eq):
    """The real solutions of an equation, which must be finitely many."""
    s = sp.solveset(eq, MODEQ_X, sp.S.Reals)
    need(isinstance(s, sp.FiniteSet), f"{eq} has not finitely many solutions ({s})")
    return sorted(s)


def modeq_inside(e):
    """The inside of a modulus, |u| or m|u|."""
    ab = list(e.atoms(sp.Abs))
    need(len(ab) == 1, f"{e} has not one modulus")
    return ab[0].args[0]


def modeq_curve_on(c, fn, what):
    """A sampled curve lies on y = fn(x)."""
    need(len(c) >= 20, f"{what}: too few points")
    for x0, y0 in c[:: max(1, len(c) // 25)]:
        v = float(sp.N(fn.subs(MODEQ_X, sp.Float(x0, 30)), 30))
        need(abs(v - y0) < MODEQ_TOL * max(1.0, abs(v)), f"{what} is not y = {fn} at x = {x0}")


def modeq_graph(q, fns, xs):
    """The graph shows y = fn for each fn, over a window that holds every x in xs."""
    g = q["graph"]
    need(g is not None, "the graph rep shows no graph")
    need(len(g["curves"]) == len(fns), f"{len(g['curves'])} curves, not {len(fns)}")
    for c, fn in zip(g["curves"], fns):
        modeq_curve_on(c, fn, "a curve")
    for x0 in xs:
        need(g["x0"] < float(x0) < g["x1"], f"x = {x0} is off the graph")


# ── sets ─────────────────────────────────────────────────────

def modeq_piece(p, v="x"):
    """(lo, hi, lo_in, hi_in), each end None or its text."""
    lo, hi, li, hi_in = p
    if lo is None:
        return f"{v} {'≤' if hi_in else '<'} {hi}"
    if hi is None:
        return f"{v} {'≥' if li else '>'} {lo}"
    return f"{lo} {'≤' if li else '<'} {v} {'≤' if hi_in else '<'} {hi}"


def modeq_set_text(pieces):
    return " or ".join(modeq_piece(p) for p in pieces)


def modeq_pieces(s):
    """A SymPy set of reals (intervals, exact ends) as the game's pieces."""
    if isinstance(s, sp.Interval):
        parts = [s]
    elif isinstance(s, sp.Union):
        parts = sorted(s.args, key=lambda i: i.inf)
    else:
        raise Fail(f"a solution set that is not intervals: {s}")
    out = []
    for i in parts:
        need(isinstance(i, sp.Interval) and i.inf != i.sup, f"a piece that is not an interval: {i}")
        lo = None if i.inf == -sp.oo else modeq_n(i.inf)
        hi = None if i.sup == sp.oo else modeq_n(i.sup)
        out.append((lo, hi, not i.left_open, not i.right_open))
    return out


def modeq_rel(lhs, rel, rhs_):
    return {"<": sp.StrictLessThan, "≤": sp.LessThan, ">": sp.StrictGreaterThan, "≥": sp.GreaterThan}[rel](lhs, rhs_)


def modeq_split_rel(line):
    for r in MODEQ_RELS:
        if f" {r} " in line:
            a, b = line.split(f" {r} ", 1)
            return a, r, b
    raise Fail(f"no inequality in {line!r}")


# ── equations ────────────────────────────────────────────────

def modeq_gives(q):
    """Every 'A = B gives [cx = d, so ]x = v' in the working solves A = B."""
    for st in modeq_steps(q):
        for part in st.split(", and "):
            m = re.search(r"([^:]+?) = (.+?) gives (?:(.+?) = (.+?), so )?x = ([−\d/]+)", part)
            if not m:
                continue
            a, b = modeq_expr(m.group(1)), modeq_expr(m.group(2))
            v = sp.Rational(m.group(5).replace("−", "-"))
            need(sp.solve(sp.Eq(a, b), MODEQ_X) == [v], f"{st!r}: x = {modeq_n(v)} doesn't solve it")
            if m.group(3):
                need(sp.solve(sp.Eq(modeq_expr(m.group(3)), modeq_expr(m.group(4))), MODEQ_X) == [v], f"{st!r}: the middle step is wrong")


def modeq_squares(q, L, R2):
    """The squared equation and its factors in the working are (L)² − (R)² up to a factor."""
    want = sp.expand(L**2 - R2**2)
    for st in modeq_steps(q):
        m = re.search(r"(?:Expand and collect:|, so) ([^,:]+?) = 0(?:, that is (.+?) = 0)?\.$", st)
        if m and "²" in m.group(1):
            for g in (m.group(1), m.group(2)):
                if g:
                    r_ = sp.cancel(modeq_expr(g) / want)
                    need(r_.is_number and r_ != 0, f"{st!r}: {g} is not the squared equation")
        m = re.search(r"Square both sides: \((.+)\)² = \((.+)\)²", st) or re.search(r"square them: \((.+)\)² = \((.+)\)²", st)
        if m:
            need(sp.expand(modeq_expr(m.group(1)) - L) == 0 and sp.expand(modeq_expr(m.group(2)) - R2) == 0, f"{st!r} squares the wrong sides")
        m = re.search(r"Factorise: \((.+)\)\((.+)\) = 0, so x = ([−\d/]+) or x = ([−\d/]+)\.", st)
        if m:
            f1, f2 = modeq_expr(m.group(1)), modeq_expr(m.group(2))
            r_ = sp.cancel(sp.expand(f1 * f2) / want)
            need(r_.is_number and r_ != 0, f"{st!r}: the factors are not the squared equation's")
            got = [sp.Rational(m.group(i).replace("−", "-")) for i in (3, 4)]
            need(sp.solve(f1, MODEQ_X) == [got[0]] and sp.solve(f2, MODEQ_X) == [got[1]], f"{st!r}: the roots are not the factors'")


def modeq_equation(q, wrongs):
    u = q["view"]["unknown"]
    need(q["asked"] == "Solve the equation.", f"asked {q['asked']!r}")
    a, b = q["lines"][0].split(" = ")
    L, Rt = modeq_expr(a), modeq_expr(b)
    need(isinstance(L, sp.Abs), f"the left side {a!r} is not a modulus")
    inside = L.args[0]
    need(sp.Poly(inside, MODEQ_X).degree() == 1, "the inside is not linear")
    roots = modeq_roots(sp.Eq(L, Rt))
    want = modeq_xs(roots)
    if u in ("shifted-modulus", "linear-equals-constant"):
        need(Rt.is_Integer and Rt > 0, f"the right side {b!r} is not a positive whole number")
        if u == "shifted-modulus":
            need(sp.Poly(inside, MODEQ_X).LC() == 1, "a shifted modulus with an x term that is not x")
        need(len(roots) == 2, "not two roots")
        wrongs[MODEQ_EQ + "1"] = {modeq_xs(sp.solve(inside - Rt, MODEQ_X))}
        for st in modeq_steps(q):
            mm = re.search(r"Split into the two cases: (.+) = (\d+) or (.+) = −(\d+)\.", st)
            if mm:
                need(sp.expand(modeq_expr(mm.group(1)) - inside) == 0 and int(mm.group(2)) == Rt == int(mm.group(4)), f"{st!r}: not the two cases")
    elif u == "modulus-equals-modulus":
        need(isinstance(Rt, sp.Abs), f"the right side {b!r} is not a modulus")
        other = Rt.args[0]
        need(len(roots) == 2, "not two roots")
        wrongs[MODEQ_EQ + "1"] = {modeq_xs(sp.solve(inside - other, MODEQ_X))}
        modeq_squares(q, inside, other)
        if q["view"]["rep"] == "graph":
            corners = sp.solve(inside, MODEQ_X) + sp.solve(other, MODEQ_X)
            modeq_graph(q, [L, Rt], roots + corners)
    else:  # modulus-equals-line
        need(sp.Poly(Rt, MODEQ_X).degree() == 1, f"the right side {b!r} is not a line")
        need(len(roots) == 1, f"not one root ({roots})")
        both = sorted(set(sp.solve(sp.expand(inside**2 - Rt**2), MODEQ_X)))
        need(len(both) == 2 and roots[0] in both, "squaring doesn't give the root and one false root")
        bad = [r for r in both if r != roots[0]][0]
        good = roots[0]
        need(Rt.subs(MODEQ_X, bad) < 0, "the false root doesn't make the line negative")
        # Squaring and keeping both is #2 on the squaring method, and keeping a root that
        # makes the line negative is #0 on the others: the same two values.
        ref = MODEQ_EQ + ("2" if q["view"]["angle"] == "square-both-sides" else "0")
        wrongs[ref] = {modeq_xs(both)}
        modeq_squares(q, inside, Rt)
        line_t = b
        for st in modeq_steps(q):
            mm = re.search(r"At x = ([−\d/]+) the right-hand side (.+) is ([−\d/]+), below 0, .* At x = ([−\d/]+) both sides are ([−\d/]+)\.", st)
            if mm:
                vb, vg = sp.Rational(mm.group(1).replace("−", "-")), sp.Rational(mm.group(4).replace("−", "-"))
                need(vb == bad and vg == good and mm.group(2) == line_t, f"{st!r}: not the false and the true root")
                need(sp.Rational(mm.group(3).replace("−", "-")) == Rt.subs(MODEQ_X, bad), f"{st!r}: the line's value is wrong")
                need(sp.Rational(mm.group(5).replace("−", "-")) == Rt.subs(MODEQ_X, good) == L.subs(MODEQ_X, good), f"{st!r}: the sides are not equal there")
            mm = re.search(r"a V with its vertex at \(([−\d/]+), 0\)", st)
            if mm:
                need(sp.solve(inside, MODEQ_X) == [sp.Rational(mm.group(1).replace("−", "-"))], f"{st!r}: the vertex is wrong")
            mm = re.search(r"They meet once, at x = ([−\d/]+), where both are ([−\d/]+)\.", st)
            if mm:
                need(sp.Rational(mm.group(1).replace("−", "-")) == good and sp.Rational(mm.group(2).replace("−", "-")) == Rt.subs(MODEQ_X, good), f"{st!r} is wrong")
            mm = re.search(r"The other case gives x = ([−\d/]+), but there the line is at y = ([−\d/]+),", st)
            if mm:
                need(sp.Rational(mm.group(1).replace("−", "-")) == bad and sp.Rational(mm.group(2).replace("−", "-")) == Rt.subs(MODEQ_X, bad), f"{st!r} is wrong")
        modeq_in_every(q, modeq_n(bad), "the false root")
        if q["view"]["rep"] == "graph":
            modeq_graph(q, [L, Rt], roots + sp.solve(inside, MODEQ_X))
    need(all(r.q <= 6 for r in roots), "a root that is not a simple fraction")
    modeq_gives(q)
    return want


# ── counting the solutions of |f(x)| = k ─────────────────────

def modeq_count(f, k):
    return len(modeq_roots(sp.Eq(sp.Abs(f), k)))


def modeq_count_q(q, wrongs):
    m = re.fullmatch(r"f\(x\) = (.+)", q["lines"][0])
    need(m is not None, f"can't read {q['lines'][0]!r}")
    f = sp.expand(modeq_expr(m.group(1)))
    P = sp.Poly(f, MODEQ_X)
    need(P.degree() == 2, "f is not a quadratic")
    rs = sorted(sp.solve(f, MODEQ_X))
    need(len(rs) == 2 and all(r.is_integer for r in rs), "f has not two whole zeros")
    h = sp.solve(sp.diff(f, MODEQ_X), MODEQ_X)[0]
    d = abs(f.subs(MODEQ_X, h))
    need(h.is_integer and d.is_integer and d > 0, "the hump's top is not whole")
    asked = q["asked"]
    mk = re.fullmatch(r"Find the number of solutions of \|f\(x\)\| = (\d+)\.", asked)
    if mk:
        k = sp.Integer(mk.group(1))
        need(0 < k <= d, "k is not up to the hump's top")
        n = modeq_count(f, k)
        want = str(n)
        nf = len(modeq_roots(sp.Eq(f, k)))
        if nf != n:
            wrongs[MODEQ_OWN + "6"] = {str(nf)}
        modeq_in_every(q, f"So |f(x)| = {k} has {n} solutions.", "the count")
    elif asked == "Find the set of values of k for which |f(x)| = k has exactly four solutions.":
        # Four from just above 0 to just below the top, and not at either end or past them.
        for k in (d / 7, d / 2, d * 6 / 7, d - sp.Rational(1, 100), sp.Rational(1, 100)):
            need(modeq_count(f, k) == 4, f"|f(x)| = {k} has not four solutions")
        for k in (0, d, d + sp.Rational(1, 100), d + 5):
            need(modeq_count(f, k) != 4, f"|f(x)| = {k} has four solutions")
        want = f"0 < k < {modeq_n(d)}"
    else:
        need(asked == "Find the value of k for which |f(x)| = k has exactly three solutions.", f"asked {asked!r}")
        threes = [k for k in range(0, int(d) + 3) if modeq_count(f, k) == 3]
        need(threes == [d], f"three solutions at k = {threes}")
        need(modeq_count(f, d - sp.Rational(1, 100)) == 4 and modeq_count(f, d + sp.Rational(1, 100)) == 2, "three solutions not only at the top")
        want = "k = " + modeq_n(d)
    for st in modeq_steps(q):
        mm = re.search(r"is 0 at x = ([−\d]+) and x = ([−\d]+), and f\(([−\d]+)\) = ([−\d]+)\.", st)
        if mm:
            got = [sp.Integer(mm.group(i).replace("−", "-")) for i in range(1, 5)]
            need(got[:2] == rs and got[2] == h and got[3] == f.subs(MODEQ_X, h), f"{st!r} is wrong")
            fac = st.split(" is 0 at")[0][len("f(x) = "):]
            need(sp.expand(modeq_expr(fac) - f) == 0, f"{st!r}: the factorised f is not f")
    modeq_in_every(q, f"top is ({modeq_n(h)}, {modeq_n(d)})", "the hump's top")
    if q["view"]["rep"] == "graph":
        g = q["graph"]
        need(g is not None, "the graph rep shows no graph")
        modeq_curve_on(g["curves"][0], sp.Abs(f), "the graph of |f(x)|")
        if mk:
            need(len(g["curves"]) == 2, "no line y = k")
            modeq_curve_on(g["curves"][1], sp.Integer(mk.group(1)) + 0 * MODEQ_X, "the line y = k")
        else:
            need(len(g["curves"]) == 1, "a line drawn for an unknown k")
        need(g["x0"] < float(rs[0]) and float(rs[1]) < g["x1"] and g["y1"] > float(d), "the hump is off the graph")
        need(any(abs(p["x"] - float(h)) < 1e-9 and abs(p["y"] - float(d)) < 1e-9 for p in g["points"]), "the hump's top is not marked")
    return want


# ── inequalities with exact ends ─────────────────────────────

def modeq_ineq(q, wrongs):
    u = q["view"]["unknown"]
    need(q["asked"] == "Solve the inequality.", f"asked {q['asked']!r}")
    a, rel, b = modeq_split_rel(q["lines"][0])
    L, Rt = modeq_expr(a), modeq_expr(b)
    inc = rel in ("≤", "≥")
    S = sp.solveset(modeq_rel(L, rel, Rt), MODEQ_X, sp.S.Reals)
    want = modeq_set_text(modeq_pieces(S))
    ends = modeq_roots(sp.Eq(L, Rt))
    need(len(ends) == 2, f"not two critical values ({ends})")
    lo, hi = ends
    wrongs[MODEQ_OWN + "7"] = {f"x = {modeq_n(lo)} or x = {modeq_n(hi)}"}
    wrongs[MODEQ_OWN + "8"] = {modeq_set_text(modeq_pieces(sp.Complement(sp.S.Reals, S)))}
    r = "≤" if inc else "<"
    inside = modeq_inside(L)
    if u in ("modulus-less-than", "modulus-greater-than"):
        need(isinstance(L, sp.Abs) and Rt.is_Integer and Rt > 0, "not a modulus against a positive whole number")
        need((rel in ("<", "≤")) == (u == "modulus-less-than"), f"{rel} on {u}")
        if u == "modulus-less-than":
            wrongs[MODEQ_IN + "0"] = {f"x {r} {modeq_n(hi)}"}
        else:
            wrongs[MODEQ_IN + "1"] = {f"{modeq_n(hi)} {r} x {r} {modeq_n(lo)}"}
        for st in modeq_steps(q):
            mm = re.search(r"squaring keeps the inequality: \((.+)\)² (.) (\d+)\.", st)
            if mm:
                need(sp.expand(modeq_expr(mm.group(1)) - inside) == 0 and mm.group(2) == rel and int(mm.group(3)) == Rt**2, f"{st!r} is wrong")
            mm = re.search(r"Collect: (.+) (.) 0, and (.+) = 0 at x = ([−\d/]+) and x = ([−\d/]+)\.", st)
            if mm:
                P = modeq_expr(mm.group(1))
                need(sp.expand(P - (inside**2 - Rt**2)) == 0 and mm.group(1) == mm.group(3) and mm.group(2) == rel, f"{st!r}: not the squared inequality")
                need([sp.Rational(mm.group(i).replace("−", "-")) for i in (4, 5)] == sorted(sp.solve(P, MODEQ_X)) == [lo, hi], f"{st!r}: the roots are wrong")
            mm = re.search(r"Take out (\d+): (.+) = (\d+)\|x ([−+]) (.+?)\|, so .* is \|x ([−+]) (.+?)\| (.) (.+)\.$", st)
            if mm:
                c_ = int(mm.group(1))
                need(int(mm.group(3)) == c_ and sp.expand(c_ * modeq_expr("x " + mm.group(4) + " " + mm.group(5)) - inside) == 0, f"{st!r}: not taken out right")
                need(mm.group(4) == mm.group(6) and mm.group(5) == mm.group(7) and mm.group(8) == rel and sp.Rational(mm.group(9)) == Rt / c_, f"{st!r}: the new bound is wrong")
            mm = re.search(r"distance from x to ([−\d/]+) is .*?([\d/]+), so x is \w+ ([−\d/]+) − ([\d/]+) = ([−\d/]+) (?:and|or above) ([−\d/]+) \+ ([\d/]+) = ([−\d/]+)\.", st)
            if mm:
                c0, rr = sp.Rational(mm.group(1).replace("−", "-")), sp.Rational(mm.group(2))
                need(sp.solve(inside, MODEQ_X) == [c0], f"{st!r}: the centre is wrong")
                need(c0 - rr == lo and c0 + rr == hi, f"{st!r}: the ends are wrong")
                need(all(sp.Rational(mm.group(i).replace("−", "-")) == v for i, v in ((3, c0), (4, rr), (5, lo), (6, c0), (7, rr), (8, hi))), f"{st!r}: the sums are wrong")
            mm = re.search(r"^(.+) is the distance from x to ([−\d/]+) on the number line\.", st)
            if mm:
                need(sp.solve(inside, MODEQ_X) == [sp.Rational(mm.group(2).replace("−", "-"))], f"{st!r}: the centre is wrong")
            mm = re.search(r"x is (less than|at most|more than|at least) (\d+) from ([−\d]+), so (?:between ([−\d]+) and ([−\d]+)|below ([−\d]+) or above ([−\d]+))\.$", st)
            if mm:
                need(int(mm.group(2)) == Rt and sp.solve(inside, MODEQ_X) == [sp.Integer(mm.group(3).replace("−", "-"))], f"{st!r}: the distance is wrong")
                need((mm.group(1) in ("at most", "at least")) == inc and (mm.group(1) in ("less than", "at most")) == (u == "modulus-less-than"), f"{st!r}: the wrong words")
                got = [sp.Integer(t.replace("−", "-")) for t in mm.groups()[3:] if t]
                need(got == [lo, hi] and (mm.group(4) is not None) == (u == "modulus-less-than"), f"{st!r}: the ends are wrong")
    else:  # modulus-against-modulus
        need(isinstance(L, sp.Abs) and sp.Poly(inside, MODEQ_X).LC() == 1, "the left side is not |x + a|")
        mm_ = re.fullmatch(r"(\d)\|(.+)\|", b)
        need(mm_ is not None and int(mm_.group(1)) in (2, 3), f"the right side {b!r} is not m|x − b|")
        m = int(mm_.group(1))
        other = modeq_expr(mm_.group(2))
        flip = MODEQ_FLIP[rel]
        for st in modeq_steps(q):
            mm = re.search(r"squaring keeps the inequality: \((.+)\)² (.) (\d+)\((.+)\)²\.", st)
            if mm:
                need(sp.expand(modeq_expr(mm.group(1)) - inside) == 0 and mm.group(2) == rel and int(mm.group(3)) == m * m
                     and sp.expand(modeq_expr(mm.group(4)) - other) == 0, f"{st!r} is wrong")
            mm = re.search(r"turns the sign round: (.+) (.) 0, that is \((.+)\)\((.+)\) (.) 0\.", st)
            if mm:
                P = sp.expand(m * m * other**2 - inside**2)
                need(sp.expand(modeq_expr(mm.group(1)) - P) == 0 and sp.expand(modeq_expr(mm.group(3)) * modeq_expr(mm.group(4)) - P) == 0, f"{st!r}: not m²(x − b)² − (x + a)²")
                need(mm.group(2) == flip == mm.group(5), f"{st!r}: the sign didn't turn round")
            mm = re.search(r"Its roots are x = ([−\d/]+) and x = ([−\d/]+), and with a positive x² term it is (below|above) 0 (between|outside) them\.", st)
            if mm:
                need([sp.Rational(mm.group(i).replace("−", "-")) for i in (1, 2)] == [lo, hi], f"{st!r}: the roots are wrong")
                need((mm.group(3) == "below") == (flip in ("<", "≤")) and (mm.group(4) == "between") == (mm.group(3) == "below"), f"{st!r}: the wrong side")
            mm = re.search(r"They meet at x = (\S+) and x = (\S+), which are ([−\d/]+) and ([−\d/]+)\.", st)
            if mm:
                for i, v in ((1, lo), (2, hi)):
                    need(abs(float(mm.group(i).replace("−", "-")) - float(v)) <= 1e-5 * max(1, abs(float(v))), f"{st!r}: the GDC reading is wrong")
                need([sp.Rational(mm.group(i).replace("−", "-")) for i in (3, 4)] == [lo, hi], f"{st!r}: the exact values are wrong")
            mm = re.search(r"The steeper V, y = (.+), is below y = (.+) between them \(it is 0 at x = ([−\d/]+)\)", st)
            if mm:
                need(mm.group(1) == b and mm.group(2) == a and sp.solve(other, MODEQ_X) == [sp.Rational(mm.group(3).replace("−", "-"))], f"{st!r} is wrong")
                need(Rt.subs(MODEQ_X, (lo + hi) / 2) < L.subs(MODEQ_X, (lo + hi) / 2), f"{st!r}: the steeper V is not below between them")
        if q["view"]["rep"] == "graph":
            modeq_graph(q, [L, Rt], [lo, hi] + sp.solve(inside, MODEQ_X) + sp.solve(other, MODEQ_X))
    for v in (lo, hi):
        modeq_in_every(q, modeq_n(v), "the critical value")
    return want


# ── |f(x)| against a line on a domain ────────────────────────

def modeq_crossings(f, g, lo, hi, trig):
    """Where |f(x)| = g(x) for lo ≤ x ≤ hi (floats or None for no end): the roots of
    f = g and f = −g where g ≥ 0, exact for a quadratic and to 30 digits for a trig f."""
    out = []
    for h in (f - g, f + g):
        if not trig:
            rs = [r for r in sp.Poly(sp.expand(h), MODEQ_X).real_roots()]
            vals = [mpmath.mpf(sp.N(r, 40)) for r in rs]
        else:
            hf = sp.lambdify(MODEQ_X, h, "mpmath")
            vals, n = [], 6000
            a0, b0 = mpmath.mpf(lo), mpmath.mpf(hi)
            prev_x, prev = a0, hf(a0)
            for i in range(1, n + 1):
                x1 = a0 + (b0 - a0) * i / n
                y1 = hf(x1)
                if prev == 0:
                    vals.append(prev_x)
                elif y1 * prev < 0:
                    vals.append(mpmath.findroot(hf, (prev_x, x1), solver="anderson"))
                prev_x, prev = x1, y1
        for r in vals:
            if lo is not None and (r < lo - 1e-12 or r > hi + 1e-12):
                continue
            gv = sp.N(g.subs(MODEQ_X, sp.Float(r, 40)), 40)
            if gv < 0:
                continue
            if not any(abs(r - o) < 1e-12 for o in out):
                out.append(r)
    return sorted(out)


def modeq_cut(f, g, rel, cuts, ends_text, unbounded):
    """The pieces where |f| rel g between the cuts, and the pieces where it fails. A domain
    end (or None) is in both; a crossing is in the set for ≤ and ≥ and in its
    complement for < and >."""
    inc = rel in ("≤", "≥")
    hf = sp.lambdify(MODEQ_X, sp.Abs(f) - g, "mpmath")
    sol, comp, last = [], [], None
    for i in range(len(cuts) - 1):
        a_, b_ = cuts[i], cuts[i + 1]
        if a_ is None:
            mid = b_ - 1
        elif b_ is None:
            mid = a_ + 1
        else:
            mid = (a_ + b_) / 2
        v = hf(mpmath.mpf(mid))
        need(abs(v) > 1e-9, "|f| − g is 0 between two crossings")
        holds = (v < 0) if rel in ("<", "≤") else (v > 0)
        need(holds != last, "|f| − g keeps its sign through a crossing (a touch)")
        last = holds
        first, end = i == 0, i == len(cuts) - 2
        lo_t, hi_t = ends_text[i], ends_text[i + 1]
        if holds:
            sol.append((lo_t, hi_t, (first and not unbounded) or inc, (end and not unbounded) or inc))
        else:
            comp.append((lo_t, hi_t, (first and not unbounded) or not inc, (end and not unbounded) or not inc))
    return sol, comp


def modeq_curve(q, wrongs):
    need(q["paper"] == 2, "|f(x)| against a line is Paper 2")
    m = re.fullmatch(r"f\(x\) = (.+), (.+) ≤ x ≤ (.+)", q["lines"][0])
    need(m is not None, f"can't read {q['lines'][0]!r}")
    f = modeq_expr(m.group(1))
    trig = f.has(sp.sin) or f.has(sp.cos)
    d0, d1 = modeq_expr(m.group(2)), modeq_expr(m.group(3))
    if trig:
        need(d0 == 0 and d1 in (sp.pi, 2 * sp.pi), "a trig domain that is not 0 to π or 2π")
    else:
        need(sp.Poly(f, MODEQ_X).degree() == 2 and sp.Poly(f, MODEQ_X).LC() == 1, "f is not x² + Bx + C")
        need(d0.is_integer and d1.is_integer and d0 < d1, "a quadratic's domain that is not two whole numbers")
        disc = sp.discriminant(f, MODEQ_X)
        need(disc > 0, "f has no part below the axis to reflect")
    ma = re.fullmatch(r"Solve \|f\(x\)\| (.) (.+)\. Give any end that is not exact to 3 s\.f\.", q["asked"])
    need(ma is not None and ma.group(1) in MODEQ_RELS, f"asked {q['asked']!r}")
    rel, g = ma.group(1), modeq_expr(ma.group(2))
    need(sp.Poly(g, MODEQ_X).degree() <= 1, "the other side is not a line")
    lo, hi = float(d0), float(d1)
    xs = modeq_crossings(f, g, lo, hi, trig)
    need(1 <= len(xs) <= 3, f"{len(xs)} crossings")
    for x0 in xs:
        need(x0 - lo >= 0.1 and hi - x0 >= 0.1, "a crossing at a domain end")
        s_ = modeq_sf(x0)
        # Not at a 3 s.f. rounding edge, so a GDC's reading rounds the same way.
        need(modeq_sf(x0 - 1e-7) == s_ == modeq_sf(x0 + 1e-7), f"the crossing {float(x0)} is at a rounding edge")
    # No near-touch away from the crossings: the sign of |f| − g is clear everywhere else.
    hf = sp.lambdify(MODEQ_X, sp.Abs(f) - g, "mpmath")
    for i in range(801):
        x0 = mpmath.mpf(lo + (hi - lo) * i / 800)
        if all(abs(x0 - c) > 0.03 for c in xs):
            need(abs(hf(x0)) > 1e-3, f"|f| and the line nearly touch at x = {float(x0)}")
    texts = [m.group(2)] + [modeq_sf(c) for c in xs] + [m.group(3)]
    sol, comp = modeq_cut(f, g, rel, [lo] + xs + [hi], texts, False)
    need(sol, "the inequality holds nowhere on the domain")
    want = modeq_set_text(sol)
    wrongs[MODEQ_OWN + "8"] = {modeq_set_text(comp)}
    if not trig:
        every = modeq_crossings(f, g, None, None, False)
        wide, _ = modeq_cut(f, g, rel, [None] + every + [None], [None] + [modeq_sf(c) for c in every] + [None], True)
        wt = modeq_set_text(wide)
        if wt != want:
            wrongs[MODEQ_IN + "2"] = {wt}
    for st in modeq_steps(q):
        mm = re.search(r"The GDC gives the crossings? (.+)\.$", st)
        if mm:
            got = [float(t.replace("−", "-")) for t in re.findall(r"x = (\S+?)(?= and|$)", mm.group(1))]
            need(len(got) == len(xs) and all(abs(a_ - float(b_)) <= 1e-5 * max(1, abs(float(b_))) for a_, b_ in zip(got, xs)), f"{st!r}: not the crossings {[float(c) for c in xs]}")
        mm = re.search(r"The graph of y = \|f\(x\)\| is (above|below) the line on (.+), and the domain", st)
        if mm:
            need((mm.group(1) == "above") == (rel in (">", "≥")) and mm.group(2) == want, f"{st!r} is wrong")
        mm = re.search(r"Graph y = \|(.+)\| and y = (.+) on the GDC for (.+)\.$", st)
        if mm:
            need(sp.simplify(modeq_expr(mm.group(1)) - f) == 0 and sp.simplify(modeq_expr(mm.group(2)) - g) == 0 and mm.group(3) == f"{m.group(2)} ≤ x ≤ {m.group(3)}", f"{st!r}: not this question's graphs")
    if q["view"]["rep"] == "graph":
        gr = q["graph"]
        need(gr is not None and len(gr["curves"]) == 2, "the graph is not |f(x)| and the line")
        modeq_curve_on(gr["curves"][0], sp.Abs(f), "the graph of |f(x)|")
        modeq_curve_on(gr["curves"][1], g, "the line")
        need(gr["x0"] <= lo and hi <= gr["x1"], "the domain is off the graph")
        for c in gr["curves"]:
            need(abs(c[0][0] - lo) < 1e-9 and abs(c[-1][0] - hi) < 1e-9, "a curve doesn't run over the domain")
        for c0 in xs:
            need(gr["y0"] < float(sp.N(g.subs(MODEQ_X, sp.Float(c0, 30)))) < gr["y1"], "a crossing is off the graph")
    return want


def modeq_check(q):
    u = q["view"]["unknown"]
    texts = [q["asked"]] + q["lines"] + modeq_steps(q) + [o["text"] for o in q["choices"]]
    for tx in texts:
        need(not re.search(r"(?<![A-Za-z_])-\d", tx), f"a hyphen for a minus in {tx!r}")
    if q["paper"] == 1:
        need(not any(s["angle"].startswith("gdc-") for s in q["solutions"]), "a calculator working on Paper 1")
    if q["view"]["rep"] != "graph":
        need(q["graph"] is None, "a graph on the equation rep")
    wrongs = {}
    if u in ("shifted-modulus", "linear-equals-constant", "modulus-equals-modulus", "modulus-equals-line"):
        want = modeq_equation(q, wrongs)
    elif u == "count-solutions":
        want = modeq_count_q(q, wrongs)
    elif u in ("modulus-less-than", "modulus-greater-than", "modulus-against-modulus"):
        want = modeq_ineq(q, wrongs)
    elif u == "modulus-vs-curve":
        with mpmath.workdps(40):
            want = modeq_curve(q, wrongs)
    else:
        raise Fail(f"no check for {u}")
    gc_check_common(q, want, wrongs)
    return None, None


SITUATION_CHECKS["modulus-equation"] = modeq_check

# (end of R10-MODULUS-EQUATION)


def check_questions(data):
    """Checks every question in an export. The summary is all the report needs."""
    qs = data["questions"]
    by_cell = defaultdict(lambda: [0, 0])
    by_type = defaultdict(lambda: [0, 0])
    failures = []
    for q in qs:
        cell = q["cell"]
        t = q["view"]["type"]
        ok = True
        try:
            check(q)
        except Fail as e:
            ok = False
            failures.append(f"{cell} seed {q['view']['seed']} ({q['format']}): {e}")
        except Exception as e:  # a checker crash on a question counts as a failure
            ok = False
            failures.append(f"{cell} seed {q['view']['seed']} ({q['format']}): checker error {type(e).__name__}: {e}")
        by_cell[cell][0] += 1
        by_type[t][0] += 1
        if not ok:
            by_cell[cell][1] += 1
            by_type[t][1] += 1

    chains = defaultdict(list)
    for q in qs:
        if "chain" in q:
            chains[q["chain"]].append(q)
    chain_failures = []
    for name, parts in chains.items():
        try:
            check_chain(parts)
        except Fail as e:
            chain_failures.append(f"{name}: {e}")
    failures += [f"chain {m}" for m in chain_failures]

    return {
        "shard": data.get("shard", [1, 1]),
        "by_cell": by_cell,
        "by_type": by_type,
        "failures": failures,
        "chains": len(chains),
        "chain_parts": sum(len(v) for v in chains.values()),
        "chain_failures": len(chain_failures),
        "problems": [f"export error: {e['view']}: {e['error']}" for e in data.get("errors", [])],
        "error_types": [e["view"]["type"] for e in data.get("errors", [])],
    }


def merged_summaries(root):
    """All the shards' summaries as one, with a problem for any shard not there once."""
    parts = [json.loads(p.read_text()) for p in sorted(Path(root).rglob("summary.json"))]
    if not parts:
        sys.exit(f"FAIL no summary.json under {root}")
    n = parts[0]["shard"][1]
    seen = sorted(p["shard"][0] for p in parts)
    out = {
        "shard": [1, 1],
        "by_cell": defaultdict(lambda: [0, 0]),
        "by_type": defaultdict(lambda: [0, 0]),
        "failures": [],
        "chains": 0,
        "chain_parts": 0,
        "chain_failures": 0,
        "problems": [],
        "error_types": [],
    }
    if seen != list(range(1, n + 1)) or any(p["shard"][1] != n for p in parts):
        out["problems"].append(f"shards: have {[p['shard'] for p in parts]}, want each of 1 to {n} once")
    for p in parts:
        for key in ("by_cell", "by_type"):
            for k, (made, bad) in p[key].items():
                out[key][k][0] += made
                out[key][k][1] += bad
        for key in ("failures", "problems", "error_types"):
            out[key] += p[key]
        for key in ("chains", "chain_parts", "chain_failures"):
            out[key] += p[key]
    return out


def report(s):
    """Prints the tables. Coverage only counts when the summary is the whole catalogue."""
    by_cell, by_type = s["by_cell"], s["by_type"]
    failures, problems = s["failures"], s["problems"]
    whole = s["shard"][1] == 1
    if not whole:
        print(f"Shard {s['shard'][0]} of {s['shard'][1]}: coverage is checked when the shards are merged")
        print()
    types = sorted(by_type)
    cat = catalogue_cells(set(types) | set(s["error_types"]))

    print("Per type")
    print(f"  {'type':34} {'questions':>9} {'failed':>7} {'cells':>13}")
    for t in sorted(cat):
        made = sum(1 for c in cat[t] if by_cell[c][0] > 0)
        print(f"  {t:34} {by_type[t][0]:>9} {by_type[t][1]:>7} {made:>6} of {len(cat[t]):<4}")
        if whole and by_type[t][0] < MIN_PER_TYPE:
            problems.append(f"{t}: {by_type[t][0]} questions, fewer than {MIN_PER_TYPE}")
    print()
    print("Per cell (type | unknown | representation | angle)")
    print(f"  {'cell':100} {'questions':>9} {'failed':>7}")
    for t in sorted(cat):
        for c in cat[t]:
            n, bad = by_cell[c]
            if whole or n:
                print(f"  {c:100} {n:>9} {bad:>7}")
            if whole and n < MIN_PER_CELL:
                problems.append(f"{c}: {n} questions, fewer than {MIN_PER_CELL}")
    extra = sorted(set(by_cell) - {c for cs in cat.values() for c in cs})
    for c in extra:
        problems.append(f"{c}: not a catalogue cell")
    print()
    total = sum(v[0] for v in by_type.values())
    print(f"Boss chains: {s['chains']}, {s['chain_parts']} parts, {s['chain_failures']} failed")
    print(f"{total} questions, {len(failures)} failed, {sum(len(v) for v in cat.values())} catalogue cells")
    for msg in failures[:40]:
        print("FAIL " + msg)
    if len(failures) > 40:
        print(f"... and {len(failures) - 40} more")
    for msg in problems:
        print("FAIL " + msg)
    return 1 if failures or problems else 0


def main():
    if sys.argv[1:2] == ["--merge"]:
        sys.exit(report(merged_summaries(sys.argv[2])))
    path = Path(sys.argv[1] if len(sys.argv) > 1 else ROOT / "_scratch/check-answers/questions.json")
    summary = check_questions(json.loads(path.read_text()))
    path.with_name("summary.json").write_text(json.dumps(summary))
    sys.exit(report(summary))


if __name__ == "__main__":
    main()
